FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// ---------------------------------------------------------------------------
// FOIL DESIGN TOOL
// Version: build 245 (2026-10-14)
//   wing 1.070 | stab 4.036 | performance 1.030 | mast 2.011 | fuselage 5.008 | mold 2.148
//
// Features: Foil wing, Foil stabiliser, Foil performance, Foil mast, Foil fuselage, Foil mold.
// Shared geometry core used by the wing and stabiliser: area-first planform solver,
// superellipse / linear chord, alignment line, power-law sweep, anhedral + gull,
// washout, thickness distribution, tip cap, tabulated profiles, section polars.
//
// Frame: X = downstream (LE -> TE), Y = span, Z = up.
// Wing root pivot (default quarter chord) sits at the world origin.
// Sections are streamwise (planes normal to Y). Span is the projected,
// tip-to-tip distance seen from above.
//
// The build number goes up on every delivery, the per-feature versions when that
// feature changes; both must match FOIL_FILE_BUILD and the FOIL_*_VERSION constants.
// Full change history: see the changelog above those constants.
// ---------------------------------------------------------------------------

export enum BoltSize
{
    annotation { "Name" : "M4" }
    M4,
    annotation { "Name" : "M5" }
    M5,
    annotation { "Name" : "M6" }
    M6,
    annotation { "Name" : "M8" }
    M8,
    annotation { "Name" : "M10" }
    M10,
    annotation { "Name" : "Custom hole sizes" }
    CUSTOM
}

/**
 * Metric bolt dimensions, mm: nominal diameter, close-fit clearance hole, tapping drill, and the 90 deg
 * countersunk head (ISO 10642 / DIN 7991 theoretical head diameter dk and head height k). CUSTOM returns zeros;
 * callers then take the typed hole and a head of twice the hole.
 */
function boltDims(size is BoltSize) returns map
{
    if (size == BoltSize.M4) return { "name" : "M4", "dia" : 4, "clear" : 4.4, "tap" : 3.3, "head" : 8.96, "k" : 2.48 };
    if (size == BoltSize.M5) return { "name" : "M5", "dia" : 5, "clear" : 5.4, "tap" : 4.2, "head" : 11.2, "k" : 3.1 };
    if (size == BoltSize.M6) return { "name" : "M6", "dia" : 6, "clear" : 6.4, "tap" : 5.0, "head" : 13.44, "k" : 3.72 };
    if (size == BoltSize.M8) return { "name" : "M8", "dia" : 8, "clear" : 8.4, "tap" : 6.8, "head" : 17.92, "k" : 4.96 };
    if (size == BoltSize.M10) return { "name" : "M10", "dia" : 10, "clear" : 10.5, "tap" : 8.5, "head" : 22.4, "k" : 6.2 };
    return { "name" : "custom", "dia" : 0, "clear" : 0, "tap" : 0, "head" : 0, "k" : 0 };
}

/** Countersunk head diameter for a bolt choice, given the hole it goes through (Custom: twice the hole). */
function boltHead(size is BoltSize, hole is ValueWithUnits) returns ValueWithUnits
{
    return size == BoltSize.CUSTOM ? 2 * hole : boltDims(size).head * millimeter;
}

/**
 * Console line that is also kept in a variable (build 202): printed as before, and appended to the
 * string variable key, so an API client (the Onshape MCP server) reads every feature's log with one
 * FeatureScript evaluation. Each feature clears its key when it starts.
 */
function foilPrint(context is Context, key is string, line is string)
{
    println(line);
    var s = "";
    try silent
    {
        const prev = getVariable(context, key);
        if (prev is string)
            s = prev;
    }
    setVariable(context, key, s == "" ? line : s ~ "\n" ~ line);
}

/** The feature's notice, kept in the variable key as well as shown on the feature (build 202). */
function foilNotice(context is Context, id is Id, key is string, msg is string, warn is boolean)
{
    setVariable(context, key, msg);
    if (warn)
        reportFeatureWarning(context, id, msg);
    else
        reportFeatureInfo(context, id, msg);
}

