                annotation { "Name" : "Bolt 1 from",
                             "Description" : "The first bolt's centre behind the root leading edge. Limits 5-300 mm. Typical 25-40 % of the root chord, so the row straddles the section's thickest part where there is most laminate under the heads; the last bolt must stay inside the chord." }
                isLength(definition.flatBolt1From, { (millimeter) : [5, 35, 300] } as LengthBoundSpec);

                annotation { "Name" : "Bolt pitch",
                             "Description" : "Spacing of the bolts along the chord. Limits 10-150 mm. Typical 20-30 mm (a flat-bar plan: 25, with the bar tapped at 25 mm so the wing can shift a hole). Ignored with one bolt." }
                isLength(definition.flatPitch, { (millimeter) : [10, 25, 150] } as LengthBoundSpec);

                annotation { "Name" : "Countersink", "Default" : true,
                             "Description" : "Sinks each head into the top skin with a 90 deg countersink to the head diameter, so the heads sit flush (the mold forms the countersinks from the upper half). Off: plain through holes for button heads or washers on top. Typical on." }
                definition.flatCsk is boolean;

                annotation { "Name" : "Mount pad", "Default" : true,
                             "Description" : "Adds a pad under the root that seats the wing on the flat bar at the modelled Incidence: a flat horizontal face, Pad width wide and Pad height below the underside's lowest point, its top following the root's own lower surface, from Flat start to the trailing edge (build 227, user: a wing bolted straight onto a bar takes the angle of its underside, not the angle it was drawn at - a Clark Y's flat lies 2.1 deg from its chord, a cambered NACA underside rocks on its curve; the pad is the shim that sets it). The bolts pass through it and the laminate under each head counts it. Off: bare underside, and the notice reports the angle the wing would seat at instead." }
                definition.flatPadOn is boolean;

                if (definition.flatPadOn)
                {
                    annotation { "Name" : "Pad width",
                                 "Description" : "Width of the pad face across the span, centred on the root. Limits 5-80 mm. Typical the bar's width: 19 for a 19 x 25 mm flat bar on edge, 25 for one laid flat. Wider than the bar only adds wetted area; narrower leaves the bar's edges unseated." }
                    isLength(definition.flatPadWidth, { (millimeter) : [5, 20, 80] } as LengthBoundSpec);

                    annotation { "Name" : "Pad height",
                                 "Description" : "How far the flat face sits below the underside's lowest point at the root. Limits 0-20 mm. Typical 1-3 mm: enough that the face is a full flat rather than a line touching the skin. 0 puts the face exactly on the lowest point, so a section whose underside already lies flat at the modelled Incidence (a Clark Y drawn at 2.1 deg) gets no pad body at all: its own flat is the seat. Any other section gets a face at least 0.3 mm below its lowest point (build 238): on the point itself the face would touch the skin along a line, which the mold cannot cut." }
                    isLength(definition.flatPadHeight, { (millimeter) : [0, 2, 20] } as LengthBoundSpec);

                    annotation { "Name" : "Flat start",
                                 "Description" : "Where the flat face begins, in mm behind the root leading edge; it runs from here to the trailing edge. Limits 2-300 mm. Typical 15-25 % of the root chord: at or just ahead of the underside's lowest point, so the face begins where the section already reaches the pad plane, and ahead of the first bolt. Held at least 5 mm inside the chord at both ends, with a warning." }
                    isLength(definition.flatPadStart, { (millimeter) : [2, 20, 300] } as LengthBoundSpec);

                    annotation { "Name" : "Front ramp", "Default" : true,
                                 "Description" : "Fairs the pad's front from just behind the leading edge down to the flat face at Flat start with a smooth ramp, closing the gap between the bar and the wing's nose. Off: the pad begins at Flat start with a square front face, for a bar that starts there. Typical on." }
                    definition.flatPadRamp is boolean;
                }
            }

            if (definition.socketOn && definition.wingJoint == WingJoint.ROUND)
            {
                annotation { "Name" : "Tube dia",
                             "Description" : "Round tube socket: outside diameter of the round fuselage tube. Limits 10-60 mm. Typical 20-30 mm for carbon or aluminium tube. The Square socket is sized by Bore width and Bore height instead (build 233: hidden there)." }
                isLength(definition.tubeDia, { (millimeter) : [10, 24, 60] } as LengthBoundSpec);
            }

            if (definition.socketOn && definition.wingJoint != WingJoint.HUB && definition.wingJoint != WingJoint.FLAT)
            {
                annotation { "Name" : "Clearance",
                             "Description" : "Clearance between the bore and what goes in it, across the bore: Round, added to Tube dia; Square, added to Bore width and to Bore height (half each side), and half of it to Bore corner. Limits 0-2 mm. Typical 0.1-0.3 mm for a firm slip fit that is then bolted or bonded." }
                isLength(definition.tubeClearance, { (millimeter) : [0, 0.2, 2] } as LengthBoundSpec);

                annotation { "Name" : "Wall",
                             "Description" : "Nacelle wall thickness round the bore, which sets the nacelle's size: Round, Tube dia + 2 x Wall across (the Clearance comes out of the wall); Square, the bore (Bore width or Bore height + Clearance) + 2 x Wall each way. Limits 2-15 mm. Typical 4-6 mm for carbon. Thicker is stronger but adds frontal area and drag. Mouth wall % sets how much of it the rear face keeps." }
                isLength(definition.socketWall, { (millimeter) : [2, 5, 15] } as LengthBoundSpec);

                annotation { "Name" : "Blend length",
                             "Description" : "Length over which the socket grows out of the wing, from the root's thickest point (where it starts hidden inside the wing) to the full nacelle diameter. Limits 10-300 mm. Typical 50-90 mm - longer is a gentler, lower-drag blend. Should reach full diameter before or just after the trailing edge." }
                isLength(definition.socketBlend, { (millimeter) : [10, 70, 300] } as LengthBoundSpec);

                annotation { "Name" : "Rear extension",
                             "Description" : "How far the socket extends behind the root trailing edge to its rear face, where the tube enters. Limits 0-400 mm. Typical 60-120 mm; with Socket depth this sets how much tube is held and how far the joint sits behind the wing." }
                isLength(definition.socketRearExt, { (millimeter) : [0, 90, 400] } as LengthBoundSpec);

                annotation { "Name" : "Rear fairing",
                             "Description" : "Taper at the back of the socket, from the full nacelle down to the rear face, where the wall is thinned to Mouth wall % of Wall - this is what keeps the fuselage slender: Foil fuselage matches the diameter this taper actually produces, not the nacelle's peak diameter. Limits 5-150 mm. Typical 20-40 mm; longer is gentler and lower drag. 0 is refused, since it would force the whole fuselage to the wide nacelle diameter. No taper with Mouth wall % at 100." }
                isLength(definition.nacelleRearFair, { (millimeter) : [5, 25, 150] } as LengthBoundSpec);

                annotation { "Name" : "Mouth wall %",
                             "Description" : "Wall left round the bore at the socket's rear face, its mouth, as % of Wall; Rear fairing tapers the nacelle down to it (build 233, user). Round socket: that wall, less half the Clearance at 100. Square socket: its section shrinks in proportion to the larger side, so the walls come out near it, the narrower side's a little thicker. Limits 25-100 %. Typical 50 (the taper every earlier build made) for a round carbon tube in a slim fuselage; 75-100 for a metal bar in the Square socket, whose bending moment is largest at the mouth, where a thin lip splits first. 100 = no taper: the full nacelle ends square at the rear face, and a Foil fuselage on a Round socket is as wide as the nacelle." }
                isReal(definition.mouthWallPct, { (unitless) : [25, 50, 100] } as RealBoundSpec);

                annotation { "Name" : "Socket depth",
                             "Description" : "How far the bore runs forward from the rear face - the length of tube or bar inside the socket. Limits 20-300 mm. Typical 3-4 x Tube dia (Square: x Bore height); longer carries bending better. It may not reach forward into the blend. Shorter than Rear extension (the defaults) leaves the whole bore behind the root trailing edge, a pod behind the wing; the notice says so and gives the depth that brings 10 mm of it under the wing." }
                isLength(definition.socketDepth, { (millimeter) : [20, 80, 300] } as LengthBoundSpec);

                annotation { "Name" : "Socket height",
                             "Description" : "Moves the bore's axis up (+) or down (-) from the root section's mid-thickness at its thickest point. Limits -15 to 15 mm. Typical 0; a few mm up puts the fuselage higher on the wing. The nacelle still starts hidden inside the wing, so a large offset makes it stand out of one skin more than the other." }
                isLength(definition.socketHeight, { (millimeter) : [-15, 0, 15] } as LengthBoundSpec);

                annotation { "Name" : "Bolts",
                             "Description" : "Vertical countersunk bolts through the nacelle and the tube or bar, spread along the socket, heads sunk into the nacelle's top. Limits 0-3. Typical 2. 0 = no holes (bonded joint)." }
                isInteger(definition.socketPins, { (unitless) : [0, 2, 3] } as IntegerBoundSpec);

                annotation { "Name" : "Bolt", "Default" : "M6",
                             "Description" : "The cross bolt (or pin) through the nacelle and the tube or bar: sets the clearance hole here and in the Foil fuselage's matching holes (M5 5.5, M6 6.5, M8 8.5 mm, 0.1 mm looser than a close fit so the two parts line up). Typical M6 for a 24 mm tube or a 19-25 mm bar; the hole must be under half the tube diameter, or under half the Bore width on the Square socket (the bar's side it passes through). Custom hole sizes: type the hole below (a plain dowel, for instance)." }
                definition.socketPinBolt is BoltSize;

                if (definition.socketPinBolt == BoltSize.CUSTOM)
                {
                    annotation { "Name" : "Bolt dia",
                                 "Description" : "Pin or bolt clearance hole diameter (Custom only). Limits 3-12 mm. Typical 6.5 mm (M6) for a 24 mm tube; under half the tube diameter, or half the Bore width on the Square socket." }
                    isLength(definition.socketPinDia, { (millimeter) : [3, 6.5, 12] } as LengthBoundSpec);
                }

                annotation { "Name" : "Bolt pitch",
                             "Description" : "Spacing of the socket bolts along the tube, centred on the socket. Limits 10-150 mm. Typical 30-40; all must fit within Socket depth. Ignored with one bolt." }
                isLength(definition.socketPinPitch, { (millimeter) : [10, 35, 150] } as LengthBoundSpec);
            }

            if (definition.socketOn && (definition.wingJoint == WingJoint.ROUND || definition.wingJoint == WingJoint.SQUARE || definition.wingJoint == WingJoint.HUB))
            {
                annotation { "Name" : "Root fairing", "Default" : false,
                             "Description" : "Lofts the corner where the wing root meets the joint, instead of leaving a hard corner or a small fillet (build 241, user: lofted transitions, not fillets on hard faces). Sockets: the nacelle's own sections gain a concave flare each side, tangent to the nacelle and running into the skin, above and below. Flat hub: a flare round the hub's sides and front, tangent to its walls and running into the skin, in place of Hub fillet. Its radius is Fairing radius, held so it never climbs over the nacelle or the hub's top; behind the trailing edge it carries on for Fairing tail, else it eases to nothing just ahead of the trailing edge. Foil performance then counts the wing's two root junctions as lofted. Typical on for a low-drag joint; off keeps the joint as before build 241." }
                definition.rootFairing is boolean;

                if (definition.rootFairing)
                {
                    annotation { "Name" : "Fairing radius",
                                 "Description" : "The root fairing's largest radius. Held under 90 % of how far the nacelle (or the hub's wall) stands above or below the skin at each station, so it never climbs over the nacelle's top or reaches the hub's flat top, and its foot 3 mm behind the leading edge; with a tail it is also the radius, seen from above, where the tail leaves the trailing edge. Limits 2-100 mm (wide open while it is tested). Typical 8-15 mm on a 30-40 mm nacelle, up to the wall's height on a flat hub; larger is a gentler corner and a wider foot on the skin." }
                    isLength(definition.fairingRadius, { (millimeter) : [2, 10, 100] } as LengthBoundSpec);

                    annotation { "Name" : "Fairing spread",
                                 "Description" : "How flat and wide the root fairing is: how far it reaches out along the skin for each mm it climbs the nacelle or the hub's wall. 1 is a quarter circle (Fairing radius both ways, every build before this field); 2 runs twice as far out as it climbs, flatter and wider, a gentler blend into the skin with a wider foot; under 1 is steeper and narrower. Fairing radius stays the height it climbs, and the caps on it are unchanged. Limits 0.5-4. Typical 1-2.5; the wider the foot, the more of the skin near the root it reshapes." }
                    isReal(definition.fairingSpread, { (unitless) : [0.5, 1, 4] } as RealBoundSpec);

                    annotation { "Name" : "Fairing tail",
                                 "Description" : "Where the socket or the hub runs on behind the trailing edge, the fairing keeps its full radius to the trailing edge and carries on behind it for this length: the root's trailing edge continues as a thin web on the trailing edge's own height (its bottom on the mold's parting), leaving the trailing edge on a radius seen from above, its fillets shrinking to nothing, as wind-tunnel fillets that grow aft and run past the trailing edge onto the body do. Held to the socket's Rear extension less 3 mm, or to the hub's back. Limits 0-100 mm (capped while it is tested). Typical 40-80 mm, longer is gentler. 0, or a joint that ends at the trailing edge, eases the fairing to nothing just ahead of the trailing edge instead." }
                    isLength(definition.fairingTail, { (millimeter) : [0, 50, 100] } as LengthBoundSpec);
                }
            }
        }

        annotation { "Name" : "Log inputs", "Default" : true,
                     "Description" : "Prints every parameter on this feature to the FeatureScript console as one line, so the whole set can be pasted elsewhere (e.g. back to an AI assistant) along with the notice or CSV." }
        definition.logInputs is boolean;
    }
    {
        setVariable(context, "foilWingLog", "");
        setVariable(context, "foilWingNotice", "");
        const m = buildFoil(context, id, definition, vector(0, 0, 0) * meter);
        if (definition.logInputs)
            foilPrint(context, "foilWingLog", wingInputLog(definition));
        const socketInfo = buildWingSocket(context, id, definition, m);
        setVariable(context, "foilWingSocket", socketInfo.model);
        setVariable(context, "foilWingHub", socketInfo.hub == undefined ? { "on" : 0 } : socketInfo.hub);
        setVariable(context, "foilWingFlat", socketInfo.flat == undefined ? { "on" : 0 } : socketInfo.flat);
        nameSolids(context, id, definition.mirror ? "Wing" : "Wing (half)");

        setVariable(context, "foilWingArea", m.areaProj);
        setVariable(context, "foilWingAreaDeveloped", m.areaDev);
        setVariable(context, "foilWingSpan", m.span);
        setVariable(context, "foilWingRootChord", m.rootChord);
        setVariable(context, "foilWingTipChord", m.tipChord);
        setVariable(context, "foilWingMAC", m.mac);
        setVariable(context, "foilWingAR", m.aspect);
        setVariable(context, "foilWingIncidence", definition.incidence);
        setVariable(context, "foilWingRootThickness", definition.rootThickness);
        setVariable(context, "foilWingTipThickness", definition.tipThickness);
        setVariable(context, "foilWingZeroLift", m.alpha0);
        setVariable(context, "foilWingModel", m.model);
        const roll = rollResponse(m.model);
        setVariable(context, "foilWingRoll", roll);
        foilPrint(context, "foilWingLog", "WING_ROLL: toolVersion=" ~ FOIL_WING_VERSION ~ "; clBeta_per_rad=" ~ fmt(roll.clb, 4) ~ "; equivAnhedral_deg=" ~ fmt(roll.deg, 2));

        foilNotice(context, id, "foilWingNotice", planformSummary(definition, m) ~ rollNote(roll) ~ socketInfo.note, false);
    });

annotation { "Feature Type Name" : "Foil stabiliser",
             "Feature Type Description" : "Parametric hydrofoil stabiliser with the wing's geometry, placed by arm behind the wing and optionally linked to it as a fraction of its area. Carries a mount pad, tail fairing and bolt pattern pinned to its pivot, seated on the fuselage by Height; reports tail volume and decalage." }
export const foilStabiliser = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Group Name" : "Section", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Profile",
                         "Description" : "Section family. NACA 4-digit is fully parametric (camber, camber position, thickness) - use it for anything except matching a known published section. Named sections are digitised tables, thickness-scaled to Root/Tip thick % (Camber % fixed, hidden). Where each fits, from builders' results and the polars: MRC-16 (Drela, 13.9 %, Decavitator hydrofoil): anything pumped, carved or taken off slowly; the all-rounder, gentle stall, most cavitation margin in a hard turn. MH 18 (Hepperle, 11.2 %, pylon racing): fast flat-water wings at low lift; cheapest at cruise, tops out near CL 1.1, cavitates first in a turn. H105 (Speer, 12.6 %, sailing foils): slow high-lift take-off, a bigger stab for its nose-down moment (NeuralFoil polar). Clark Y: flat-bottomed home builds; most lift, biggest moment. E817/E818: widest cavitation-free band at speed. NACA 63-412: laminar bucket on a clean surface." }
            definition.profile is FoilProfile;

            if (definition.profile == FoilProfile.NACA4)
            {
                annotation { "Name" : "Camber %",
                             "Description" : "Maximum camber as % of chord. Limits -6 to +6 %. Typical 0 for stabs. 0 = symmetric (most common stab section). Negative = inverted camber that lifts downward, trimming with less negative incidence; typical -1 to -2 % if used. Positive only for lifting stabs (rare). Only shown for NACA 4-digit - the tabulated profiles carry their own fixed camber." }
                isReal(definition.camber, { (unitless) : [-6, 0, 6] } as RealBoundSpec);

                annotation { "Name" : "Camber pos %",
                             "Description" : "Position of maximum camber as % of chord from the leading edge. Limits 10-90 %. Typical 30-50 %. Ignored when camber is 0. Only shown for NACA 4-digit." }
                isReal(definition.camberPos, { (unitless) : [10, 40, 90] } as RealBoundSpec);
            }

            annotation { "Name" : "Root thick %",
                         "Description" : "Root section thickness as % of chord. Limits 4-20 %. Typical 8-11 %. Thinner = less drag; below about 8 % stabs get flexible and stall abruptly." }
            isReal(definition.rootThickness, { (unitless) : [4, 10, 20] } as RealBoundSpec);

            annotation { "Name" : "Tip thick %",
                         "Description" : "Tip section thickness as % of chord. Limits 4-20 %. Typical 7-10 %. Blend between root and tip is set by the thickness exponent." }
            isReal(definition.tipThickness, { (unitless) : [4, 8, 20] } as RealBoundSpec);

            annotation { "Name" : "Tip profile",
                         "Description" : "Section at the tip. Same as root: one section along the whole span, as before. Any other: the root section changes into this one from Blend from % outward, point by point along the section, so a cambered root can run out to a flatter, thinner-nosed tip the way production wings do. Foil performance uses it: the zero-lift angle varies along the span (aerodynamic twist, so the lift distribution and trim move), the stall check compares each station against ITS section's CL max, and the drag bucket is blended by area. Foil mold follows the blend. With Section data = Built-in the tip gets its own fitted polar; with Polar summary the root's numbers are used for both (one set of 13)." }
            definition.tipProfile is TipProfile;

            if (definition.tipProfile != TipProfile.SAME)
            {
                if (definition.tipProfile == TipProfile.NACA4)
                {
                    annotation { "Name" : "Tip camber %",
                                 "Description" : "Maximum camber of the tip section as % of chord. Limits -6 to 8. Negative = inverted. Typical 0 on a stab, or the root's own value with a flatter shape." }
                    isReal(definition.tipCamber, { (unitless) : [-6, 2, 8] } as RealBoundSpec);

                    annotation { "Name" : "Tip camb pos %",
                                 "Description" : "Position of the tip section's maximum camber, % of chord from the leading edge. Limits 10-90. Typical 35-45." }
                    isReal(definition.tipCamberPos, { (unitless) : [10, 40, 90] } as RealBoundSpec);
                }

                annotation { "Name" : "Blend from %",
                             "Description" : "Limits 0-95, per half span. Out to here the section is the root's; from here it blends smoothly into the tip section, reaching it at the tip. 0 = a straight blend across the whole span. Typical 30-60: keep the root section where the chord and the bending are, change it over the outer half." }
                isReal(definition.blendFrom, { (unitless) : [0, 40, 95] } as RealBoundSpec);
            }

            annotation { "Name" : "TE thickness",
                         "Description" : "Limits 0.1-3 mm, and at most 3 % of the root chord. Thinned automatically near the tip. Typical 0.5-0.8 mm for wet-laid carbon in printed molds, 0.3-0.5 mm for prepreg. Thicker = tougher edge but more base drag and a risk of humming." }
            isLength(definition.teThickness, { (millimeter) : [0.1, 0.6, 3] } as LengthBoundSpec);

            annotation { "Name" : "Points/surface",
                         "Description" : "Limits 10-120. Typical 30-40. Cosine-spaced towards the leading edge. Above about 60 slows regeneration for no visible gain." }
            isInteger(definition.pointsPerSurface, { (unitless) : [10, 36, 120] } as IntegerBoundSpec);
        }

        annotation { "Group Name" : "Planform", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Planform input",
                         "Description" : "Area + aspect ratio (recommended): enter the area everyone quotes and the shape; span and root chord are solved. Span + root chord: enter the geometry directly (e.g. to copy an existing foil); area becomes an output." }
            definition.planformMode is PlanformMode;

            if (definition.planformMode == PlanformMode.AREA_AR)
            {
                annotation { "Name" : "Area cm^2",
                             "Description" : "Target stab area in cm^2. Limits 30-1000 cm^2. Typical 15-22 % of the front wing: 150-350 cm^2 for surf/eFoil/pump, 80-150 for kite race. Larger = more pitch stability and damping, more drag. The notice reports the ratio to the wing." }
                isReal(definition.targetArea, { (unitless) : [30, 165, 1000] } as RealBoundSpec);

                annotation { "Name" : "Aspect ratio",
                             "Description" : "Limits 2-14, projected span^2 / projected area. Typical 4-6 surf/eFoil, 6-9 pump/downwind/race. Higher = more efficient stab and more pitch damping per area, but more tip-breach risk and flex." }
                isReal(definition.aspectRatio, { (unitless) : [2, 7.5, 14] } as RealBoundSpec);

                annotation { "Name" : "Area definition",
                             "Description" : "Which area the target refers to. Projected (top view) is what sets lift and what most brands quote. Developed is measured along the curved span line and is larger with anhedral or gull. Both are reported." }
                definition.areaDefinition is AreaDefinition;
            }
            else
            {
                annotation { "Name" : "Span",
                             "Description" : "Limits 80-1200 mm, projected tip to tip (top view). Typical 250-450 mm." }
                isLength(definition.span, { (millimeter) : [80, 330, 1200] } as LengthBoundSpec);

                annotation { "Name" : "Root chord",
                             "Description" : "Limits 20-300 mm. Typical 60-110 mm." }
                isLength(definition.rootChord, { (millimeter) : [20, 75, 300] } as LengthBoundSpec);
            }

            annotation { "Name" : "Chord distribution",
                         "Description" : "Superellipse: c = c0 (1 - (s 2y/b)^n)^(1/n), cut off at the end chord ratio, giving a rounded tip. Linear: straight taper to a square tip. Double taper: a steep taper from the root to Break %, then a gentler one to the tip - a wide root flaring into a slim outer wing (the full-base stab, or a high-aspect wing with a broad centre); Blend % rounds the corner between the two. Linear and double taper end in a square tip: Tip cap = Rounded + plan rounds it in plan view too." }
            definition.chordShape is ChordShape;

            if (definition.chordShape == ChordShape.SUPERELLIPSE)
            {
                annotation { "Name" : "Exponent n",
                             "Description" : "Limits 1.2-8. 2 = elliptic. 2.5-4 = fuller tips (common on stabs, keeps area outboard for damping). Above 5 approaches a rectangle with rounded corners. Typical 2.5-4." }
                isReal(definition.superN, { (unitless) : [1.2, 2.5, 8] } as RealBoundSpec);

                annotation { "Name" : "End ratio",
                             "Description" : "Limits 0.02-0.6. Chord of the small end face as a fraction of root chord. Typical 0.06-0.12 for a rounded tip (stab chords are small, so keep the end face above about 5 mm); 0.15-0.3 for a blunt tip." }
                isReal(definition.endRatio, { (unitless) : [0.02, 0.08, 0.6] } as RealBoundSpec);
            }
            else
            {
                if (definition.chordShape == ChordShape.DOUBLE)
                {
                    annotation { "Name" : "Break %",
                                 "Description" : "Limits 5-60, per half span. Where the steep root taper ends and the gentle outer taper begins, as a percentage of the half span. Typical 20-30 for a full-base stab: the wide root carries the mount and the bolts, so the mount pad can be shorter and the root thinner in percent without a tubercle." }
                    isReal(definition.breakPct, { (unitless) : [5, 28, 60] } as RealBoundSpec);

                    annotation { "Name" : "Mid ratio",
                                 "Description" : "Limits 0.2-1.0. Chord at the break as a fraction of root chord. Must be at least Tip ratio. Typical 0.55-0.7 for a full-base stab." }
                    isReal(definition.midRatio, { (unitless) : [0.2, 0.62, 1] } as RealBoundSpec);

                    annotation { "Name" : "Blend %",
                                 "Description" : "Limits 0-30, per half span. Rounds the corner where the two tapers meet: the outline follows a smooth curve from Blend % before the break to Blend % after it, tangent to both tapers, instead of a sharp kink. 0 = sharp. Typical 8-15. Clamped so the blend never reaches the root or the tip." }
                    isReal(definition.blendPct, { (unitless) : [0, 10, 30] } as RealBoundSpec);
                }

                annotation { "Name" : "Tip ratio",
                             "Description" : "Limits 0.1-1.0. Tip chord as a fraction of root chord; the tip is square in plan view. Typical 0.4-0.7 for linear taper, 0.15-0.3 for double taper, where it is the chord at the end of the outer taper and must not exceed Mid ratio." }
                isReal(definition.tipRatio, { (unitless) : [0.1, 0.5, 1] } as RealBoundSpec);
            }

            annotation { "Name" : "Min tip", "Default" : false,
                         "Description" : "On = the tip chord is widened automatically until the section at the tip cap start is at least Min tip mm thick, by raising End ratio (or Tip ratio) above the value entered. The notice reports the ratio used. Guards a thin, small-chord tip that cannot be laid up; especially useful on a stab linked to a wing, where the link sets area, aspect ratio and thickness but the tip chord is still this feature's own." }
            definition.minTipOn is boolean;

            if (definition.minTipOn)
            {
                annotation { "Name" : "Min tip mm",
                             "Description" : "Minimum section thickness at the tip cap start (the last full section before the cap tapers out). Limits 0.2-5 mm. Typical 1-1.5 mm for a carbon layup: two skin plies plus a little UD; the cap beyond it is tow and resin. Only the tip chord is changed, never the thickness %. From build 239 the cap's end is also held at 0.5 mm or more (Cap end % raised for the thickness only, said in the notice): thinner, the mold's cavity cut can fail on some sections." }
                isLength(definition.minTip, { (millimeter) : [0.2, 1, 5] } as LengthBoundSpec);
            }

            annotation { "Name" : "Stations",
                         "Description" : "Limits 3-30, per half span. Typical 9-13 for a rounded superellipse tip, 5-7 for linear taper. Tip-cap stations are added on top, and with Tip drop or Gull dihedral about 17 through the drop (build 235), so the stab follows its drop law and the mold's parting stays inside the trailing edge." }
            isInteger(definition.stations, { (unitless) : [3, 11, 30] } as IntegerBoundSpec);

            annotation { "Name" : "Root tail", "Default" : false,
                         "Description" : "On = the stab's own outline carries a tail: the trailing edge is extended aft at the centreline by Tail length, fading to nothing over Tail span %, so the root ends in a rounded point behind the trailing edge like a production stab's, and the fuselage tip can be the stab itself. The extension is all behind the trailing edge whatever Align is; the section keeps its thickness in mm and is stretched aft, so the tail is thin. The area solver includes it. With it on you can turn the mount pad's Tail off; the fuselage then ends at the stab's trailing edge." }
            definition.rootTailOn is boolean;

            if (definition.rootTailOn)
            {
                annotation { "Name" : "Tail length",
                             "Description" : "How far the trailing edge extends behind the root trailing edge at the centreline. Limits 5-200 mm. Typical 30-60 mm for a stab; about half the root chord gives the V of a full-base stab." }
                isLength(definition.rootTailLen, { (millimeter) : [5, 40, 200] } as LengthBoundSpec);

                annotation { "Name" : "Tail span %",
                             "Description" : "Over what part of the half span the tail fades to nothing, from the centreline. Limits 5-60 %. The fade is smooth at both ends: flat across the centreline (a rounded tail nose) and tangent to the outline where it ends. Typical 20-35." }
                isReal(definition.rootTailSpan, { (unitless) : [5, 25, 60] } as RealBoundSpec);
            }

            annotation { "Name" : "Mirror to full span", "Default" : true,
                         "Description" : "On = complete foil. Off = right half only, for faster edits and section inspection. Reported metrics are always full-span values." }
            definition.mirror is boolean;
        }

        annotation { "Group Name" : "Sweep, alignment and anhedral", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Align line %",
                         "Description" : "Limits 0-100 %. The chord line that stays straight (apart from Sweep aft). Typical 100 for a superellipse stab with a straight trailing edge, 25-50 for both edges curving, 0 for a double-taper full-base stab: straight leading edge, the flare and the root tail all on the trailing edge. Independent of the incidence pivot. Plan-view tip rounding is centred on the mid-chord regardless, so both tip corners round." }
            isReal(definition.planformAlign, { (unitless) : [0, 50, 100] } as RealBoundSpec);

            annotation { "Name" : "Sweep aft",
                         "Description" : "Limits -50 to +200 mm, positive = aft. How far the alignment line sits aft at the tip. Typical 10-50 mm. More sweep = more yaw stability and a longer effective tail arm." }
            isLength(definition.sweepTip, { (millimeter) : [-50, 30, 200] } as LengthBoundSpec);

            annotation { "Name" : "Sweep exp",
                         "Description" : "Limits 0.5-4. Shape of the sweep line x = offset (2y/b)^m. 1 = straight (kinked at the root), 2-3 = curved and tangent at the root, 3-4 = raked tips. Typical 2." }
            isReal(definition.sweepExp, { (unitless) : [0.5, 2, 4] } as RealBoundSpec);

            annotation { "Name" : "Tip drop",
                         "Description" : "Limits -50 to +100 mm, positive = down (anhedral). Typical 0-15 mm; negative (tips up) is used on some stabs for yaw stability. Large values can create mold undercuts." }
            isLength(definition.tipDrop, { (millimeter) : [-50, 20, 100] } as LengthBoundSpec);

            annotation { "Name" : "Drop shape",
                         "Description" : "How the drop is spread between Drop from % and Drop to %. Power law: z = -drop u^e with Drop exp, steepening all the way to the tip (2-3 = flat centre, tips dropping late). S-curve: a smoothstep, flat at both ends and steepest in the middle, so the wing levels off again before the tip - the gull front view of many surf wings." }
            definition.dropLaw is DropLaw;

            if (definition.dropLaw == DropLaw.POWER)
            {
            annotation { "Name" : "Drop exp",
                         "Description" : "Limits 1-6. Typical 2-3. Shape of the drop z = -drop (2y/b)^e. 1 = straight from the root, 2-3 = flat centre with tips falling away." }
            isReal(definition.dropExp, { (unitless) : [1, 2, 6] } as RealBoundSpec);
            }

            annotation { "Name" : "Drop from %",
                         "Description" : "Limits 0-70, per half span. Where the drop begins: the span line is flat (or on the gull dihedral line) out to here, then drops by Tip drop over the rest with the Drop exp shape. 0 = the drop starts at the root, the plain law. Typical 0, or 15-30 for a flat centre with a break. A flat centre with a distinct break and a near-straight drop, as on some surf wings (about 20 with Drop exp 1.3), needs this; the winglet gives the tip rise on top of it." }
            isReal(definition.dropFrom, { (unitless) : [0, 0, 70] } as RealBoundSpec);

            annotation { "Name" : "Drop to %",
                         "Description" : "Limits 30-100, per half span. Where the drop is complete: beyond it the span line runs level at the full Tip drop (until a winglet bends it). Typical 100, or 85-95 for a wing that levels off before its tips." }
            isReal(definition.dropTo, { (unitless) : [30, 100, 100] } as RealBoundSpec);

            annotation { "Name" : "Gull dihedral",
                         "Description" : "Limits -10 to +20 deg, positive = up. Gull term as on the wing; rarely used on stabs. Typical 0. Needs a drop exponent above 1." }
            isAngle(definition.rootDihedral, { (degree) : [-10, 0, 20] } as AngleBoundSpec);

            annotation { "Name" : "Winglet",
                         "Description" : "Off: the tip follows Tip drop and Gull dihedral only. Up / Down: the outer part of each half span bends through Winglet angle on an arc of Bend radius and then runs straight, with every section drawn square to the bent path, so the winglet keeps its true section at any angle up to 90 deg. Its size is Winglet area: the chord distribution continues along the bend, and the tool solves how much of the half span to bend so that area comes out. Area and aspect ratio stay the developed values of the whole half span, winglet included; the notice adds the winglet height and the projected span. Foil performance credits a winglet as extra effective span for induced drag (0.9 x its height across the pair). Foil mold molds it up to 75 deg; steeper cannot release from a vertical pull." }
            definition.winglet is Winglet;

            if (definition.winglet != Winglet.OFF)
            {
                annotation { "Name" : "Winglet area",
                             "Description" : "Area of each winglet, cm^2, measured along the bend. Limits 0.5-200. Typical 4-15 for a stab. The bend starts where the outer chord distribution has this much area left to the tip, so it must fit: the winglet cannot start inside 30 % of the half span." }
                isReal(definition.wingletArea, { (unitless) : [0.5, 8, 200] } as RealBoundSpec);

                annotation { "Name" : "Winglet angle",
                             "Description" : "Limits 10-90 deg from the span plane. 90 = vertical. Typical 45-70 for a foil winglet; small angles are just a stronger tip drop and Tip drop does that with a smooth curve." }
                isAngle(definition.wingletAngle, { (degree) : [10, 60, 90] } as AngleBoundSpec);

                annotation { "Name" : "Bend radius",
                             "Description" : "Limits 5-300 mm, on the span line. The bend is an arc of this radius through Winglet angle, then straight to the tip. Typical 20-40 mm. If the arc would be longer than the winglet, the radius is reduced so the whole winglet is the bend, and the notice says so." }
                isLength(definition.wingletRadius, { (millimeter) : [5, 30, 300] } as LengthBoundSpec);
            }

            annotation { "Name" : "LE tubercles", "Default" : false,
                         "Description" : "Leading-edge tubercles (as on humpback flippers and on some production wings): the leading edge moves forward and back sinusoidally along the span while the trailing edge stays put, so the chord swells at each peak. Published tests (Miklosovic 2004, Johari 2007) show a softer stall and lift kept beyond it, for a little drag and sometimes a little maximum lift before stall; for a foil that is take-off, pumping and hard turns. GEOMETRY ONLY in the sweep: Foil performance uses the smooth chord distribution and never credits or charges them in its figures; from build 232 it reports what they would do on a separate line (its Tubercles switch). Foil mold follows them exactly. Adds six stations per tubercle pitch, so regeneration slows." }
            definition.bumpOn is boolean;

            if (definition.bumpOn)
            {
                annotation { "Name" : "Tubercle amp",
                             "Description" : "Limits 0.3-8 mm. Peak-to-trough travel of the leading edge. Typical 1.5-3 on a stab. The section is stretched at a peak and compressed at a trough with its thickness in mm unchanged." }
                isLength(definition.bumpAmp, { (millimeter) : [0.3, 2, 8] } as LengthBoundSpec);

                annotation { "Name" : "Tubercle pitch",
                             "Description" : "Limits 10-150 mm. Spanwise distance from one peak to the next. Typical 25-50 on a stab. The tubercles fade in and out over half a pitch at each end of their range." }
                isLength(definition.bumpPitch, { (millimeter) : [10, 35, 150] } as LengthBoundSpec);

                annotation { "Name" : "Tubercles from",
                             "Description" : "Limits 3-90, % of the half span. Where the tubercles start, from the centreline. Some production wings start them near the centre (from about 5), others outboard (from 12-20). Typical 10-20. Not 0: a tubercle starting on the centreline broke the mold's cavity cut (build 164), and a real wing has its mount there anyway." }
                isReal(definition.bumpFrom, { (unitless) : [3, 15, 90] } as RealBoundSpec);

                annotation { "Name" : "Tubercles to",
                             "Description" : "Limits 10-100, % of the half span. Where the tubercles end; must be beyond Tubercles from by at least one pitch. Typical 90-95, leaving the tip cap clean." }
                isReal(definition.bumpTo, { (unitless) : [10, 92, 100] } as RealBoundSpec);
            }
        }

        annotation { "Group Name" : "Twist and thickness distribution", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Washout",
                         "Description" : "Limits -5 to +8 deg, relative to the root incidence; positive = tip leading edge down. Typical 0 deg; stabs are normally untwisted." }
            isAngle(definition.washout, { (degree) : [-5, 0, 8] } as AngleBoundSpec);

            annotation { "Name" : "Washout exp",
                         "Description" : "Limits 0.5-4. Twist follows washout (2y/b)^w. 1 = linear, 2-3 = twist concentrated towards the tips. Typical 1." }
            isReal(definition.washoutExp, { (unitless) : [0.5, 1, 4] } as RealBoundSpec);

            annotation { "Name" : "Thickness exp",
                         "Description" : "Limits 0.5-4. Thickness % follows root + (tip - root)(2y/b)^p. 1 = linear, 2-3 = keeps root thickness further out. Typical 1-2." }
            isReal(definition.thicknessExp, { (unitless) : [0.5, 1.5, 4] } as RealBoundSpec);
        }

        annotation { "Group Name" : "Incidence", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Incidence",
                         "Description" : "Limits -10 to +5 deg, measured from the fuselage axis (X), positive = leading edge up. Typical -1 to -3 deg. Aim for a wing-minus-stab difference (decalage) of 1.5-3 deg; the notice reports geometric and aerodynamic decalage." }
            isAngle(definition.incidence, { (degree) : [-10, -1.5, 5] } as AngleBoundSpec);

            annotation { "Name" : "Pivot",
                         "Description" : "Point each section rotates about for incidence and washout, and the line that follows the drop curve. The root pivot sits at the stab position. Quarter chord (recommended) keeps the lift centre fixed as angles change. Plan-view shape is set by the alignment line, not the pivot." }
            definition.pivot is FoilPivot;
        }

        annotation { "Group Name" : "Position and link to wing", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Arm",
                         "Description" : "Limits 200-1500 mm, positive = aft. Distance along the fuselage axis from the wing root pivot (world origin) to the stab root pivot. This sets the pitching moment arm and, with stab area, the tail volume - it is a design decision, not a fuselage detail. Typical 550-800 mm; short (450-550) for surf/carving, long (700-900+) for pump/downwind. Longer = more pitch stability and damping, slower pitch response. A fuselage, if you add one later, is built to match this arm rather than the other way round." }
            isLength(definition.arm, { (millimeter) : [200, 650, 1500] } as LengthBoundSpec);

            annotation { "Name" : "Height",
                         "Description" : "Where the stab's seat plane sits relative to the fuselage centreline (the axis of the wing's socket, Round tube or Square), positive = up; 0 = on the centreline. The seat plane is the pad face, or the bare root surface without a pad. Pad on top (fuselage over the stab): 0 cuts the fuselage flat to half the tube under the seat, -4 leaves a flat 2 x sqrt(R^2 - 16) wide and more tube (typical -3 to -5); below the axis only. Pad underneath (stab on top): +4 does the same the other way; above the axis only. The stab is placed to this after it is built, so resizing or relinking it never moves the seat. With no socket on the wing (none, Flat hub or Flat mount) it is the stab pivot's offset from the wing pivot instead, so turning a socket on or off moves the stab; the notice says which applies. Limits -100 to +100 mm. Typical -4 (pad on top), +4 (pad underneath), 0 to +20 with no socket." }
            isLength(definition.height, { (millimeter) : [-100, 0, 100] } as LengthBoundSpec);

            annotation { "Name" : "Link to wing",
                         "Description" : "Independent: every stab parameter below is typed in directly. Linked to wing: area, aspect ratio, thickness and incidence are derived from the wing's reported values instead, using the ratios and offsets below. Camber, planform shape, sweep, anhedral, twist and tip stay independent either way." }
            definition.stabLink is StabLink;

            if (definition.stabLink == StabLink.LINKED)
            {
                annotation { "Name" : "Area ratio",
                             "Description" : "Limits 0.05-0.4. Stab projected area as a fraction of the wing's projected area. Typical 0.15-0.22. Replaces the direct area input; aspect ratio still sets the span/chord split." }
                isReal(definition.linkAreaRatio, { (unitless) : [0.05, 0.15, 0.4] } as RealBoundSpec);

                annotation { "Name" : "AR offset",
                             "Description" : "Limits -8 to +4. Added to the wing's aspect ratio to get the stab's. Typical -2 to 0: a lower-AR stab is common for extra pitch damping and robustness." }
                isReal(definition.linkAROffset, { (unitless) : [-8, -1.5, 4] } as RealBoundSpec);

                annotation { "Name" : "Thick offset",
                             "Description" : "Limits -6 to +2 %. Added to the wing's root and tip thickness % to get the stab's, so the stab reliably stays thinner (or thicker) than the wing. Typical -3 to -1." }
                isReal(definition.linkThicknessOffset, { (unitless) : [-6, -2, 2] } as RealBoundSpec);

                annotation { "Name" : "Decalage",
                             "Description" : "Limits 0-6 deg. Stab incidence is set to the wing's incidence minus this value, so you tune the one number that actually sets trim instead of two absolute angles. Typical 1.5-3 deg geometric. The notice still reports the resulting geometric and aerodynamic decalage." }
                isAngle(definition.linkDecalage, { (degree) : [0, 1.5, 6] } as AngleBoundSpec);
            }
        }

        annotation { "Group Name" : "Tip", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Tip cap",
                         "Description" : "Rounded tip: section thickness falls along a quarter-ellipse over the cap length, rounding the tip in front view; plan-view rounding then comes only from the superellipse end ratio. Rounded + plan: the chord also shrinks along the same quarter-ellipse over the cap length, to Cap end % of the chord at the cap start, so a linear or double taper gets a rounded tip in plan view as well (the area solver allows for it). Flat tip: thickness is unchanged to the end face." }
            definition.tipCap is TipCap;

            if (definition.tipCap != TipCap.FLAT)
            {
                annotation { "Name" : "Cap length",
                             "Description" : "Limits 2-40 mm, and at most 30 % of the half span. Typical 5-12 mm." }
                isLength(definition.capLength, { (millimeter) : [2, 8, 40] } as LengthBoundSpec);

                annotation { "Name" : "Cap end %",
                             "Description" : "End-face thickness as % of the tip section thickness. Limits 5-80 %. Typical 20-35 % (stab tips are small; keep the end face layable)." }
                isReal(definition.capEnd, { (unitless) : [5, 30, 80] } as RealBoundSpec);
            }
        }


        annotation { "Group Name" : "Section polar", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Section data",
                         "Description" : "Built-in: fitted XFoil data, nothing to type in. E817/E818/NACA 63-412/Clark Y/MRC-16/MH 18 use one real XFoil polar each (H105 a NeuralFoil one, no XFoil polar being published), moved to your Root/Tip thick % by a NeuralFoil fit. NACA 4-digit uses the exact zero-lift angle/moment for your Camber %/Camber pos %, plus lift slope, CLmax and drag bucket fitted from real NACA polars at your thickness/camber - coarser than the fixed profiles (a fit across a family, not one measured shape); use Polar summary for higher accuracy at your exact section. Analytic (default): thin-aerofoil model - camber-line angle/moment, fixed lift slope, skin-friction drag, Section CL max from Foil performance. Polar summary: your own XFoil/XFLR5 numbers at your own Reynolds numbers, via the fields below. Run scripts/polar_summary.py (developer skill) on your polar - the tool never invents section data." }
            definition.polarSource is PolarSource;

            if (definition.polarSource == PolarSource.POLAR)
            {
                annotation { "Name" : "Zero-lift",
                             "Description" : "Zero-lift angle of attack from the polar, deg (usually negative for a cambered section). Limits -8 to 4 deg. Replaces the thin-aerofoil estimate. Typical -1 to -3 deg for a few % camber. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isAngle(definition.polarAlpha0, { (degree) : [-8, -2, 4] } as AngleBoundSpec);

                annotation { "Name" : "Lift slope",
                             "Description" : "Section lift-curve slope from the polar, per radian. Limits 4-7.5. Thin-aerofoil theory gives 2*pi = 6.28. Replaces the fixed analytic value. Typical 5.5-6.5 depending on thickness and Reynolds number. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarCla, { (unitless) : [4, 6, 7.5] } as RealBoundSpec);

                annotation { "Name" : "Cm c/4",
                             "Description" : "Section pitching moment about the quarter chord from the polar (usually fairly constant with CL below stall). Limits -0.15 to 0.05. Replaces the thin-aerofoil Cm0. Typical -0.03 to -0.11 for a cambered section, near 0 for symmetric. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarCm0, { (unitless) : [-0.15, -0.05, 0.05] } as RealBoundSpec);

                annotation { "Name" : "Re 1 (M)",
                             "Description" : "First Reynolds number the polar data below is from, in millions. Limits 0.1-5. Values are interpolated (log Re) between Re 1 and Re 2, and held flat outside that range. Typical: near your take-off Reynolds number (about 0.2-0.5 M for a wing, lower for a stab). For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarRe1, { (unitless) : [0.1, 0.2, 5] } as RealBoundSpec);

                annotation { "Name" : "CLmax @Re1",
                             "Description" : "Maximum section lift coefficient at Re 1. Limits 0.6-1.8. Real CLmax usually drops noticeably below the higher-Re value, which is why a single fixed CL max (the analytic fallback) can be optimistic at take-off. Typical 0.85-1.1 at low Re. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarClmax1, { (unitless) : [0.6, 0.85, 1.8] } as RealBoundSpec);

                annotation { "Name" : "Cdmin @Re1",
                             "Description" : "Minimum section drag coefficient at Re 1 (the bottom of the drag bucket). Limits 0.004-0.03. Friction drag rises as Re falls. Typical 0.008-0.018 at low Re. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarCdmin1, { (unitless) : [0.004, 0.01, 0.03] } as RealBoundSpec);

                annotation { "Name" : "CL@Cdmin 1",
                             "Description" : "The lift coefficient at which Cdmin occurs at Re 1 - the centre of the drag bucket. Limits -0.3 to 1.0. Typical 0.3-0.7. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarClcd1, { (unitless) : [-0.3, 0.3, 1] } as RealBoundSpec);

                annotation { "Name" : "k @Re1",
                             "Description" : "Drag-rise rate at Re 1: Cd = Cdmin + k (CL - CL@Cdmin)^2. Limits 0.005-0.05. For your own polar, read it off two points on the drag bucket away from Cdmin and solve for k, or use polar_summary.py to fit it automatically. Typical 0.005-0.04. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarK1, { (unitless) : [0.005, 0.013, 0.05] } as RealBoundSpec);

                annotation { "Name" : "Re 2 (M)",
                             "Description" : "Second Reynolds number, in millions. Limits 0.1-5. Must differ from Re 1 for interpolation to do anything. Typical: near your cruise or max-speed Reynolds number. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarRe2, { (unitless) : [0.1, 0.5, 5] } as RealBoundSpec);

                annotation { "Name" : "CLmax @Re2",
                             "Description" : "Maximum section lift coefficient at Re 2. Limits 0.6-1.8. Typical 1.0-1.3 at higher Re. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarClmax2, { (unitless) : [0.6, 1, 1.8] } as RealBoundSpec);

                annotation { "Name" : "Cdmin @Re2",
                             "Description" : "Minimum section drag coefficient at Re 2. Limits 0.004-0.03. Typical 0.004-0.008 at higher Re. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarCdmin2, { (unitless) : [0.004, 0.007, 0.03] } as RealBoundSpec);

                annotation { "Name" : "CL@Cdmin 2",
                             "Description" : "The lift coefficient at which Cdmin occurs at Re 2. Limits -0.3 to 1.0. Typically close to CL@Cdmin 1, since the drag bucket centre moves less with Re than CLmax does. Typical 0.3-0.4. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarClcd2, { (unitless) : [-0.3, 0.3, 1] } as RealBoundSpec);

                annotation { "Name" : "k @Re2",
                             "Description" : "Drag-rise rate at Re 2. Limits 0.005-0.05. Typical 0.01-0.035. For the built-in profiles (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) use Section data = Built-in instead of typing these in." }
                isReal(definition.polarK2, { (unitless) : [0.005, 0.01, 0.05] } as RealBoundSpec);
            }
        }

        if (definition.profile != FoilProfile.NACA4)
        {
            annotation { "Name" : "Invert section", "Default" : true,
                         "Description" : "Mount the stab's tabulated profile (E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18, H105) upside down, camber down, so it makes the downforce a stab is there for - the convention for a cambered stab section. The right way up it LIFTS at cruise and throws the trim CG far aft. No effect on NACA 4-digit, where the sign of Camber % does this (negative = inverted)." }
            definition.invertSection is boolean;
        }

        annotation { "Group Name" : "Mount pad", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Mount side", "Default" : "TOP",
                         "Description" : "Which side of the stab the fuselage is on, pad or no pad (build 199: separate from the pad, as some stabs are designed without one). Top: the fuselage passes over the stab and the bolts go up through it into the fuselage (the common production layout); the bolt heads countersink into the stab's underside and Height sets the seat at or below the centreline. Bottom: the stab sits on top of the fuselage tail and bolts down into it; heads on top, Height at or above the centreline. Without a pad the seat is the bare root skin on that side, and the Foil fuselage cuts its flat to it." }
            definition.mountSide is PadSide;

            annotation { "Name" : "Mount pad", "Default" : true,
                         "Description" : "Adds the production-style mount to the stab root, modelled on a common production rear wing: a flat pad face on the fuselage side, faired in from the leading edge, the full root chord long, with an optional tail fairing running aft of the trailing edge to close the fuselage's end. The Foil fuselage seats on this face and the Foil mold puts bolt cones in it. Off = bare root, the fuselage seats on the curved skin." }
            definition.padOn is boolean;

            if (definition.padOn)
            {
                annotation { "Name" : "Pad width",
                             "Description" : "Width of the pad face across the span, centred on the root. Limits 5-80 mm. Typical 20-24 mm; match or slightly under the fuselage Tail dia so the seat is full width. Also the width of the tail fairing where it leaves the trailing edge." }
                isLength(definition.padWidth, { (millimeter) : [5, 22, 80] } as LengthBoundSpec);

                annotation { "Name" : "Pad height",
                             "Description" : "How far the flat pad face stands above the section's highest point at the root (on the pad side). Limits 0-20 mm. Typical 5-8 mm: room for the fuselage seat to be full width and the bolt heads or threads to bite. 0 puts the flat exactly on the section's highest point, so the pad is only the flat face and its ramp, no raised block (build 201, user). Sets the pad plane the fuselage seats on." }
                isLength(definition.padHeight, { (millimeter) : [0, 6, 20] } as LengthBoundSpec);

                annotation { "Name" : "Flat start",
                             "Description" : "Where the flat pad face begins, in mm from the stab pivot along X (negative = ahead of it). Limits -100 to 100 mm. Typical -10 to 0 (just ahead of the quarter-chord pivot). The ramp fairs up from the leading edge to here, so it adapts to the stab; everything aft of here is the fixed interface the fuselage seats on. Must be at least 6 mm behind the leading edge with Front ramp on (room for the ramp), 2 mm with it off (a square front) - the notice warns and holds it there if not. The notice gives the leading edge's X; with a Root tail it stays where the base chord puts it, the tail being all aft." }
                isLength(definition.flatStart, { (millimeter) : [-100, -5, 100] } as LengthBoundSpec);

                annotation { "Name" : "Front ramp", "Default" : true,
                             "Description" : "Fairs the pad's front from just behind the leading edge up to Flat start with a smooth ramp. Off: the pad begins at Flat start with a square front face (build 202, user). Either way, where the pad-side skin is already flat at the pad plane over the pad's length - a Clark Y's flat side with Pad height 0 - no pad body is built at all: the skin itself is the seat and there is nothing to ramp or step." }
                definition.padRamp is boolean;

                annotation { "Name" : "Block to body", "Default" : false,
                             "Description" : "For a round tube fuselage: continues the pad as a block of Pad width from the pad face out to the fuselage's centreline, less the tube's round (Fuselage dia), so the stab carries its own mount as a molded rear wing does and the Foil fuselage only cuts its flat seat and taps the holes (build 198). Its height is minus Height by definition, so it grows and shrinks as Height moves: nothing where the tube's flat at the pad face is as wide as the pad, cheeks beside a narrower tube, a fill under the tube when the pad face is beyond its radius. Off (the default from build 228): the pad stays exactly Pad height whatever Height is - right for a flat bar, or a fuselage that brings its own seat. Typical off; on for a round tube set below the pad face." }
                definition.stabBlock is boolean;

                if (definition.stabBlock)
                {
                    annotation { "Name" : "Fuselage dia",
                                 "Description" : "The Foil fuselage's diameter where the stab seats (its Tail dia), for the block's saddle. Limits 8-60 mm. Typical 20-30 (the fuselage's default 24). Type the fuselage's own value: the stab is built before the fuselage and cannot read it." }
                    isLength(definition.fusDia, { (millimeter) : [8, 24, 60] } as LengthBoundSpec);
                }

                annotation { "Name" : "Tail fairing", "Default" : true,
                             "Description" : "Continues the pad aft of the trailing edge as a tail: full Pad width from the trailing edge to Tail start, then tapering to End width x End thick at Tail end, flat on the pad side. Its top is the same seat plane, so the fuselage's flat runs from Flat start to Tail end and its tip tapers from Tail start, whatever the stab's chord. Off = the pad ends at the trailing edge and the interface is no longer fixed." }
                definition.tailOn is boolean;

                if (definition.tailOn)
                {
                    annotation { "Name" : "Tail start",
                                 "Description" : "Where the tail fairing and the fuselage tip begin to taper, in mm aft of the stab pivot. Limits 0-300 mm. Typical 80-100: at or a little behind the trailing edge of your biggest stab (root chord x 0.75 from a quarter-chord pivot). A stab whose trailing edge is behind this is warned and the taper starts at its trailing edge instead." }
                    isLength(definition.tailStart, { (millimeter) : [0, 85, 300] } as LengthBoundSpec);

                    annotation { "Name" : "Tail end",
                                 "Description" : "Where the tail fairing and the fuselage end, in mm aft of the stab pivot. Limits 10-400 mm. Typical Tail start + 35-50. Must be at least 5 mm behind Tail start and the trailing edge." }
                    isLength(definition.tailEnd, { (millimeter) : [10, 125, 400] } as LengthBoundSpec);

                    annotation { "Name" : "End width",
                                 "Description" : "Plan width of the tail at its end. Limits 1-30 mm. Typical 3-6 mm. The taper from Pad width is concave - fast at first, then easing - like a fuselage tail." }
                    isLength(definition.tailEndWidth, { (millimeter) : [1, 4, 30] } as LengthBoundSpec);

                    annotation { "Name" : "End thick",
                                 "Description" : "Thickness of the tail at its end, from the pad plane to the far surface. Limits 1-20 mm. Typical 5-7 mm: the far surface slopes from the trailing edge up to here." }
                    isLength(definition.tailEndThick, { (millimeter) : [1, 6, 20] } as LengthBoundSpec);
                }
            }
        }

        annotation { "Group Name" : "Mount bolts", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Stab bolts",
                         "Description" : "Through holes on the centreline for the bolts that hold the stab to the fuselage. Limits 0-6. Typical 2. The stab owns this pattern: the Foil fuselage taps its blind holes to match and the Foil mold puts undersized cones at the same positions. 0 = no holes." }
            isInteger(definition.stabBolts, { (unitless) : [0, 2, 6] } as IntegerBoundSpec);

            {
                annotation { "Name" : "Bolt 1 at",
                             "Description" : "First bolt's position in mm from the stab pivot along X (negative = ahead). Limits -100 to 200 mm. Typical 0 (the quarter chord, where the section is thickest). Fixed to the pivot, so the fuselage's tapped holes are the same for every stab. Keep it on the flat (at or behind Flat start) for a seat of constant depth." }
                isLength(definition.bolt1At, { (millimeter) : [-100, 0, 200] } as LengthBoundSpec);

                annotation { "Name" : "Bolt pitch",
                             "Description" : "Spacing between bolts along X. Limits 5-200 mm. Typical 30-40 mm. Every bolt must sit inside the root or the tail; the notice warns if one does not." }
                isLength(definition.boltPitch, { (millimeter) : [5, 35, 200] } as LengthBoundSpec);

                annotation { "Name" : "Bolt", "Default" : "M5",
                             "Description" : "The bolt that holds the stab to the fuselage (standard: two M5, build 208). Sets the stab's clearance hole (close fit: M4 4.4, M5 5.4, M6 6.4, M8 8.4, M10 10.5 mm) and, through the published pattern, the Foil fuselage's tapping drill (3.3 / 4.2 / 5.0 / 6.8 / 8.5 mm), so the two can never disagree. Typical M6, M8 for a big stab. Custom hole sizes: type the clearance hole here and the tapping drill in the fuselage yourself." }
                definition.boltSize is BoltSize;

                if (definition.boltSize == BoltSize.CUSTOM)
                {
                    annotation { "Name" : "Bolt dia",
                                 "Description" : "Clearance hole diameter in the stab (Custom only). Limits 2-14 mm. Typical 8.4 (M8) or 6.4 (M6). This is the finished hole: the mold makes an undersized cone and it is drilled to this after cure. Set the matching tapping drill in Foil fuselage's Stab bolt dia." }
                    isLength(definition.boltDia, { (millimeter) : [2, 8.4, 14] } as LengthBoundSpec);
                }

                annotation { "Name" : "Countersink", "Default" : true,
                             "Description" : "90 deg countersink on the face away from the pad, where the bolt heads sit (the underside with the pad on top), to the ISO 10642 head diameter of the chosen Bolt (M6 13.4, M8 17.9 mm; Custom: twice the hole). Cut in the model for fit; on the molded part it is drilled and countersunk after cure like the hole itself. Skipped for a bolt behind the trailing edge." }
                definition.boltCsk is boolean;
            }
        }

        annotation { "Name" : "Log inputs", "Default" : true,
                     "Description" : "Prints every parameter on this feature to the FeatureScript console as one line, so the whole set can be pasted elsewhere (e.g. back to an AI assistant) along with the notice or CSV." }
        definition.logInputs is boolean;
    }
    {
        setVariable(context, "foilStabLog", "");
        setVariable(context, "foilStabNotice", "");
        const m = buildFoil(context, id, definition, vector(definition.arm, 0 * meter, definition.height));
        var height = definition.height;            // effective pivot height: set by the seat shift below
        var seatNote = "";

        setVariable(context, "foilStabArea", m.areaProj);
        setVariable(context, "foilStabAreaDeveloped", m.areaDev);
        setVariable(context, "foilStabSpan", m.span);
        setVariable(context, "foilStabRootChord", m.rootChord);
        setVariable(context, "foilStabMAC", m.mac);
        setVariable(context, "foilStabAR", m.aspect);
        setVariable(context, "foilStabIncidence", m.incidence);
        setVariable(context, "foilStabZeroLift", m.alpha0);
        setVariable(context, "foilStabArm", definition.arm);
        var sxMin = 1 * meter;
        var sxMax = -1 * meter;
        var szMin = 1 * meter;
        for (var p in m.rootPts)
        {
            sxMin = min(sxMin, p[0]);
            sxMax = max(sxMax, p[0]);
            szMin = min(szMin, p[1]);
        }
        var szMax = -1 * meter;
        for (var p in m.rootPts)
            szMax = max(szMax, p[1]);
        const pad = buildStabMount(context, id, definition, m);
        if (pad.on && pad.side == -1)
            szMin = pad.padRel;             // pad underneath: its face is the lowest point of the root
        if (pad.on && pad.side == 1)
            szMax = pad.padRel;             // pad on top: its face is the highest point
        // Height is where the seat plane sits relative to the fuselage centreline (build 134, user:
        // "0 mm offset always has the mount interface on the centreline"). The stab is built at a
        // provisional height and then shifted so its seat plane - the pad face, or the bare root
        // surface - lands at axis + Height. Everything published below uses the shifted height
        // (build 124: relinking the stab lifted the pad into the fuselage and the seat vanished)
        var contour = pad.contour;
        {
            var sockS;
            try silent { sockS = getVariable(context, "foilWingSocket"); }
            if (sockS == undefined || sockS.on != 1)
                seatNote = " | Height is the stab pivot's offset from the wing pivot (no socket on the wing; with a round or square socket it would be the seat plane's offset from the socket axis)";
            else
            {
                const over = pad.side != -1;                          // fuselage over the stab (Mount side Top)
                const seatRel = over ? szMax : szMin;                 // seat plane relative to the root pivot
                const target = sockS.axisZ * meter + definition.height;
                const dz = target - (definition.height + seatRel);
                if (abs(dz) > 0.005 * millimeter)
                {
                    opTransform(context, id + "seatShift", {
                                "bodies" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                                "transform" : transform(vector(0 * meter, 0 * meter, dz))
                            });
                    height = definition.height + dz;
                    contour = [];
                    for (var cp in pad.contour)
                        contour = append(contour, [cp[0], cp[1] + dz / meter]);
                }
                seatNote = " | Height is measured from the " ~ (sockS.joint != undefined && sockS.joint == "SQUARE" ? "square" : "round") ~ " socket's axis, the fuselage centreline (Z " ~ fmt(sockS.axisZ * 1000, 1) ~ "): seat plane " ~
                    (definition.height == 0 * meter ? "on it" : fmt(abs(definition.height) / millimeter, 1) ~ " mm " ~ (definition.height > 0 * meter ? "above" : "below") ~ " it") ~
                    ", pivot at Z " ~ fmt(height / millimeter, 1) ~ " mm (the Height that keeps the stab here with no socket on the wing)" ~
                    (over && definition.height > 0 * meter ? " - WARNING: with Mount side Top the seat must be at or below the centreline; set Height to 0 or negative" : "") ~
                    (!over && definition.height < 0 * meter ? " - WARNING: with Mount side Bottom the seat must be at or above the centreline; set Height to 0 or positive" : "");
            }
        }
        if (definition.logInputs)
            foilPrint(context, "foilStabLog", stabInputLog(definition, height));
        setVariable(context, "foilStabHeight", height);
        nameSolids(context, id, definition.mirror ? "Stabiliser" : "Stabiliser (half)");
        var boltWorld = [];
        for (var bx in pad.boltX)
            boltWorld = append(boltWorld, (definition.arm + bx) / meter);
        setVariable(context, "foilStabRoot", {
                    "leX" : (definition.arm + sxMin) / meter, "teX" : (definition.arm + sxMax) / meter,
                    "bottomZ" : (height + szMin) / meter, "topZ" : (height + szMax) / meter,
                    "pivotX" : definition.arm / meter,
                    "padOn" : pad.on ? 1 : 0, "padSide" : pad.side,
                    "padZ" : (height + pad.padRel) / meter,
                    "mountFarZ" : (height + (pad.farRel == undefined ? pad.padRel : pad.farRel)) / meter, "blockOn" : pad.blockOn == true ? 1 : 0,
                    "fusDia" : (definition.stabBlock == true ? definition.fusDia : 0 * meter) / meter,
                    "padWidth" : (pad.on ? definition.padWidth : 0 * meter) / meter,
                    "tailOn" : pad.tailOn ? 1 : 0, "tailEndX" : (definition.arm + pad.endRel) / meter,
                    "padRampPct" : pad.on ? pad.rampPct : 0, "padX0" : (definition.arm + sxMin + 1 * millimeter) / meter,
                    "tailStartX" : (definition.arm + pad.tailStartRel) / meter,
                    "contour" : contour,
                    "tailLength" : (pad.tailOn ? pad.tailLen : 0 * meter) / meter,
                    "tailEndWidth" : (pad.tailOn ? definition.tailEndWidth : 0 * meter) / meter, "tailExp" : 1.6,
                    "boltX" : boltWorld, "boltDia" : (definition.stabBolts > 0 ? stabBoltClear(definition) : 0 * meter) / meter,
                    "tapDia" : definition.stabBolts > 0 && definition.boltSize != BoltSize.CUSTOM ? boltDims(definition.boltSize).tap / 1000 : 0,
                    "boltName" : boltDims(definition.boltSize).name, "headDia" : (definition.boltCsk ? boltHead(definition.boltSize, stabBoltClear(definition)) : 0 * meter) / meter,
                    "cskSide" : pad.cskSide == undefined ? 0 : pad.cskSide
                });
        // the model at the height the stab actually ended up at (Seat on tube shifts it after
        // buildFoil; build 124-132 published the typed Height, so every mold of a seated stab
        // parted at the wrong height)
        var stabModel = m.model;
        stabModel.baseZ = height / meter;
        setVariable(context, "foilStabModel", stabModel);
        const roll = rollResponse(m.model);
        setVariable(context, "foilStabRoll", roll);
        foilPrint(context, "foilStabLog", "STAB_ROLL: toolVersion=" ~ FOIL_STAB_VERSION ~ "; clBeta_per_rad=" ~ fmt(roll.clb, 4) ~ "; equivAnhedral_deg=" ~ fmt(roll.deg, 2));

        var msg = planformSummary(definition, m) ~ rollNote(roll) ~ pad.note ~ seatNote;
        if (definition.stabLink == StabLink.LINKED)
            msg = msg ~ " (linked)";
        if (m.model.inverted == 1)
            msg = msg ~ " (" ~ m.model.profileName ~ " inverted)";

        // wing reference, if a Foil wing feature precedes this one
        var wingArea;
        var wingMac;
        var wingInc;
        var wingA0;
        try silent
        {
            wingArea = getVariable(context, "foilWingArea");
            wingMac = getVariable(context, "foilWingMAC");
            wingInc = getVariable(context, "foilWingIncidence");
            wingA0 = getVariable(context, "foilWingZeroLift");
        }
        if (wingArea == undefined || wingMac == undefined || wingInc == undefined || wingA0 == undefined)
        {
            msg = msg ~ " | add a Foil wing feature above this one for tail volume and decalage";
        }
        else
        {
            const areaPct = m.areaProj / wingArea * 100;
            const tailVolume = m.areaProj * definition.arm / (wingArea * wingMac);
            const decGeo = wingInc - m.incidence;
            const decAero = (wingInc - wingA0) - (m.incidence - m.alpha0);
            setVariable(context, "foilTailVolume", tailVolume);
            msg = msg ~ " | " ~ toString(round(areaPct)) ~ "% of wing" ~
                " · tail volume " ~ toString(round(tailVolume * 100) / 100) ~
                " · decalage " ~ toString(round(decGeo / degree * 10) / 10) ~ " deg geometric, " ~
                toString(round(decAero / degree * 10) / 10) ~ " deg aerodynamic";
        }
        if (pad.cskWarn != undefined && pad.cskWarn != "")
            foilNotice(context, id, "foilStabNotice", msg ~ " | WARNING: " ~ pad.cskWarn, true);
        else
            foilNotice(context, id, "foilStabNotice", msg, false);
    });

annotation { "Feature Type Name" : "Foil performance",
             "Feature Type Description" : "No geometry: a speed sweep of the Foil wing, stabiliser, mast and fuselage above it. Lifting-line lift and induced drag, profile, mast, pod and fuselage drag, trim, static margin, stall, cavitation and root bending, with optional propulsion for eFoil and foil assist: prop rpm, battery power, Wh/km, range, top speed and powered trim. Results in the notice and as a CSV in the console." }
export const foilPerformance = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Group Name" : "Load and water", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Total mass kg",
                         "Description" : "Rider + board + foil (+ battery for eFoil), in kg. Limits 20-250. Typical 75-110 kg for an adult rider with board and foil; add 10-20 kg of battery for eFoil. The weight the foil must lift at every speed." }
            isReal(definition.mass, { (unitless) : [20, 75, 250] } as RealBoundSpec);

            annotation { "Name" : "Pitch Nm",
                         "Description" : "External pitching moment about the centre of mass, N m, positive = nose up. Limits -500 to +500. Typical 0 unless modelling propulsion or sail forces. 0 for pump/SUP/surf (rider weight only). eFoil: with Propulsion on and a motor pod, the thrust/drag couple is added automatically, so leave this 0 unless something else acts. Wind/kite: sail or harness force times its height above the CG. Shifts the trim CG position; does not change drag." }
            isReal(definition.extMoment, { (unitless) : [-500, 0, 500] } as RealBoundSpec);

            annotation { "Name" : "Density kg/m^3",
                         "Description" : "Water density. Limits 990-1040. Typical 1025 (sea) or 998 (fresh). 1025 seawater, 998 fresh water. Fresh water needs about 1.3 % more speed for the same lift." }
            isReal(definition.density, { (unitless) : [990, 1025, 1040] } as RealBoundSpec);

            annotation { "Name" : "Water temp C",
                         "Description" : "Water temperature in deg C. Limits 0-35. Typical 15-25 C. Sets viscosity (Reynolds number, skin friction) and vapour pressure (cavitation). Cold water raises friction drag slightly." }
            isReal(definition.waterTemp, { (unitless) : [0, 20, 35] } as RealBoundSpec);

            annotation { "Name" : "Wing depth",
                         "Description" : "Depth of the front wing below the surface. Limits 100-3000 mm. Typical 400-800 mm when riding. Used for the cavitation number and a free-surface warning: below about 2 MAC the surface causes lift loss and wave drag that are not modelled." }
            isLength(definition.depth, { (millimeter) : [100, 600, 3000] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Speeds", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Take-off km/h",
                         "Description" : "Speed at which you want to be foiling. Limits 3-60 km/h. Typical 8-12 pump/SUP, 12-16 eFoil/surf, 12-18 wind, 15-25 kite race. The notice shows how close to stall the wing is here." }
            isReal(definition.vTakeoff, { (unitless) : [3, 15, 60] } as RealBoundSpec);

            annotation { "Name" : "Cruise km/h",
                         "Description" : "Main operating speed; headline L/D, drag, power, trim and structure are reported here. Limits 4-80 km/h. Typical 12-18 pump/downwind, 18-25 eFoil/wind, 30-45 kite race." }
            isReal(definition.vCruise, { (unitless) : [4, 20, 80] } as RealBoundSpec);

            annotation { "Name" : "Max km/h",
                         "Description" : "Top of the analysed range, used for the cavitation check. Limits 5-100 km/h. Typical 25-35 eFoil/wind, 45-70 kite race." }
            isReal(definition.vMax, { (unitless) : [5, 30, 100] } as RealBoundSpec);

            annotation { "Name" : "Step km/h",
                         "Description" : "Speed step for the CSV sweep printed to the FeatureScript console, from take-off to max speed. Limits 0.5-5 km/h. Typical 1 km/h." }
            isReal(definition.vStep, { (unitless) : [0.5, 1, 5] } as RealBoundSpec);
        }

        annotation { "Group Name" : "Section and drag model", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Section CL max",
                         "Description" : "Maximum lift coefficient of the section. Used only when the wing's Section polar (in Foil wing) is set to Analytic - if it is set to Polar summary, the polar's own CLmax (interpolated at the take-off Reynolds number) is used instead and this field is ignored. Limits 0.6-1.8. Typical 1.0-1.2 for 8-10 % thick low-camber sections, 1.2-1.4 for 12 % with 2-3 % camber, 1.4-1.6 for 14 % with 4 % camber. Real values drop at low Reynolds number. Local lift in the outer 5 % of span is ignored." }
            isReal(definition.clMax, { (unitless) : [0.6, 1, 1.8] } as RealBoundSpec);

            annotation { "Name" : "Laminar run %",
                         "Description" : "Portion of the chord in laminar flow before transition. Limits 0-60 %. Typical 0-20 % for molded carbon parts. 0 = fully turbulent (conservative; realistic for a hand-finished or scratched surface). 20-40 % for a smooth, fair finish on a NACA 4-digit; 50-60 % only for laminar sections with a polished finish." }
            isReal(definition.laminar, { (unitless) : [0, 0, 60] } as RealBoundSpec);

            annotation { "Name" : "Joint finish", "Default" : JointFinish.FILLET,
                         "Description" : "How the joints are finished, for their drag, counted from the parts' own geometry: the corners where the wing roots, stab roots and the mast's foot meet the fuselage, nacelle or pod (Hoerner: dCD on t^2 = 0.75 t/c - 0.0003/(t/c)^2), and faces square to the flow (the socket's mouth where the tube enters, the flat hub's front and back; the socket's nose grows out of the wing over Blend length and counts as lofted). Filleted (default, the tool's joints): corners halved, faces Cd 0.15. Lofted, one section carried into the other: corners a tenth, faces 0.04 front, 0.02 back. Bare, hard corners and square edges: faces 0.8 front, 0.2 back. Not counted: as before build 240. Handbook estimates, not measurements; Lofted shows what a blended joint would buy (about 5 % of cruise drag on a socket eFoil)." }
            definition.jointFinish is JointFinish;

            annotation { "Name" : "Other cm^2",
                         "Description" : "Extra drag area (Cd x area) in cm^2 for anything NOT modelled. Limits 0-200. Typical 1-3 cm^2. The mast (submerged part + spray), motor pod and fuselage come from the Foil mast and Foil fuselage features, and the joints (wing, stab and mast junctions, the nacelle's and hub's faces) from Joint finish, so do not include them here; use this for bolt heads, fittings, cables and anything else." }
            isReal(definition.otherDrag, { (unitless) : [0, 0, 200] } as RealBoundSpec);

            annotation { "Name" : "Tubercles", "Default" : true,
                         "Description" : "With leading-edge tubercles on the Foil wing, reports what they would do as a separate line of the notice and a block of the report, never folded into the sweep's figures (build 232, user: call them out apart, not as a hidden overall impact). The charge the lifting line can compute: a trough-first stall, the local lift rising in the troughs by the chord's share of half the tubercle height. Then the published credits on the same take-off loading and stall speed: section CL max -5 % (two-dimensional tests at low Re) to +6 % (the humpback flipper at Re 0.5 million), the flipper's +4 deg stall angle as a bound, lift held past stall; and drag before stall of unknown sign within 8 % of the wing's profile drag, as a glide range. Typical on. Nothing happens without tubercles on the wing; off hides the line." }
            definition.tubercleCredits is boolean;
        }

        annotation { "Group Name" : "Structure", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Load factor g",
                         "Description" : "Multiple of the cruise wing lift used for the root bending check. Limits 1-8. Typical 3 for general riding, 4-5 for pumping, jumps and hard landings, 6+ for kite freestyle." }
            isReal(definition.loadFactor, { (unitless) : [1, 3, 8] } as RealBoundSpec);

            annotation { "Name" : "Cap stress MPa",
                         "Description" : "Allowable stress in the unidirectional carbon spar caps, MPa. Limits 100-1500. Typical 300-500 for wet-laid UD carbon with a safety factor (compression governs, roughly half the tensile strength), 600-900 for prepreg. Lower = more conservative." }
            isReal(definition.capStress, { (unitless) : [100, 450, 1500] } as RealBoundSpec);

            annotation { "Name" : "Cap width %",
                         "Description" : "Width of each spar cap as % of root chord. Limits 10-70 %. Typical 25-40 %. Wider caps can be thinner for the same strength." }
            isReal(definition.capWidth, { (unitless) : [10, 35, 70] } as RealBoundSpec);
        }

        annotation { "Group Name" : "Propulsion", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Propulsion", "Default" : false,
                         "Description" : "eFoil / foil-assist drivetrain. At steady speed prop thrust equals foil drag, so from the drag at each speed this finds the prop rpm (Wageningen B-series open-water KT/KQ, the same polynomials as the B-series blade feature), then motor current, throttle, battery power, Wh/km, range, top speed, and the thrust/drag couple in trim (thrust on the pod axis). Off for pump, SUP, surf, wing, wind and kite. Open-water estimate, about +/- 20 %: no pod or mast wake, no free surface, no cavitation or ventilation." }
            definition.propOn is boolean;

            if (definition.propOn)
            {
                annotation { "Name" : "Prop dia",
                             "Description" : "Propeller diameter. Limits 60-400 mm. Typical 120-160 mm for eFoil, 100-140 mm for foil assist. The prop axis is taken as the motor pod axis for the immersion check. Bigger turns slower and more efficiently but needs more depth to stay submerged." }
                isLength(definition.propDia, { (millimeter) : [60, 140, 400] } as LengthBoundSpec);

                annotation { "Name" : "Prop P/D",
                             "Description" : "Pitch / diameter at 0.7R. Limits 0.5-1.4 (the B-series fitted range). Typical 0.8-1.0 for eFoil. Higher pitch raises top speed and cruise efficiency, lower pitch gives more static thrust. Top speed is roughly pitch x no-load rpm less slip." }
                isReal(definition.propPD, { (unitless) : [0.5, 0.8, 1.4] } as RealBoundSpec);

                annotation { "Name" : "Prop EAR",
                             "Description" : "Expanded blade area ratio. Limits 0.3-1.05 (the B-series fitted range). Typical 0.3-0.55 for eFoil. More area spreads the load (less cavitation) but adds blade friction." }
                isReal(definition.propEAR, { (unitless) : [0.3, 0.3, 1.05] } as RealBoundSpec);

                annotation { "Name" : "Blades",
                             "Description" : "Number of blades. Limits 2-7 (the B-series fitted range). Typical 2-3 for eFoil." }
                isInteger(definition.propBlades, { (unitless) : [2, 3, 7] } as IntegerBoundSpec);

                annotation { "Name" : "Prop hub",
                             "Description" : "Hub diameter at the blade roots, mm. Limits 0-300. Typical 52-63 for a direct-drive outrunner (the motor's own diameter), 30-40 on a geared inrunner drive; 0 uses the polynomials' own 0.167 x D hub. The B-series polynomials were fitted on a 0.167 D hub, so a bigger hub blanks the inner blade: thrust is scaled by 1 - (h^3 - 0.167^3) and torque by 1 - (h^4 - 0.167^4), h = hub / D (a 63 mm hub on a 140 mm prop: thrust x 0.91, torque x 0.96). With Torque const 9.55 this brings static thrust within 7 % of the e-Foil Holland measurements." }
                isLength(definition.propHub, { (millimeter) : [0, 0, 300] } as LengthBoundSpec);

                annotation { "Name" : "Motor kV",
                             "Description" : "Motor speed constant, rpm per volt at no load. Limits 50-1000. Typical 100-160 for a direct-drive 63-series outrunner, 300-500 geared. No-load prop speed = kV x cells x Cell V / gear ratio; torque per amp = Torque const / kV." }
                isReal(definition.motorKv, { (unitless) : [50, 450, 1000] } as RealBoundSpec);

                annotation { "Name" : "Cells (S)",
                             "Description" : "Lithium cells in series; pack voltage = cells x Cell V. Limits 1-30. Typical 10-14 S for eFoil (12 S at 3.7 V = 44.4 V)." }
                isInteger(definition.cells, { (unitless) : [1, 12, 30] } as IntegerBoundSpec);

                annotation { "Name" : "Cell V",
                             "Description" : "Volts per cell under load. Limits 3.0-4.2. Typical 3.7 (nominal, mid-discharge); 4.0-4.1 for a fresh pack under load, which is what a VESC log shows on the first run; 3.4 near empty. Sets the no-load speed and the back-EMF headroom, so it moves the top speed and the cruise throttle; the pack Wh for range also scale with it." }
                isReal(definition.cellVolts, { (unitless) : [3.0, 3.7, 4.2] } as RealBoundSpec);

                annotation { "Name" : "Torque const",
                             "Description" : "Motor torque constant x kV, Nm per amp times rpm per volt; torque per amp = this / kV. Limits 5-12. Typical 9.55, the ideal 60 / (2 pi) that a datasheet's mNm/A x kV comes to (Flipsky 6384: 67.4 mNm/A x 140 kV = 9.44); enter the datasheet product when you have it. 8.27 was the figure builds before 229 used, which read about 13 % low on static thrust." }
                isReal(definition.torqueConst, { (unitless) : [5, 9.55, 12] } as RealBoundSpec);

                annotation { "Name" : "Gear ratio",
                             "Description" : "Motor turns per prop turn. Limits 1-10. Typical 1 (direct drive) or 3-5 for a geared outrunner. Higher gives more prop torque, less prop rpm." }
                isReal(definition.gearRatio, { (unitless) : [1, 4, 10] } as RealBoundSpec);

                annotation { "Name" : "Current lim A",
                             "Description" : "Motor current limit set in the ESC, A. Limits 1-600. Typical 80-150 A for eFoil. Sets the full-power torque, so the static thrust and the top speed." }
                isReal(definition.currentLimit, { (unitless) : [1, 120, 600] } as RealBoundSpec);

                annotation { "Name" : "Winding mOhm",
                             "Description" : "Motor winding (phase) resistance, milliohm. Limits 0-500. Typical 5-40 for eFoil motors; 12 matches the B-series blade feature's check of a 450 kV 12 S drive. Near no-load rpm it caps the current the pack voltage can push. 0 = ignore (optimistic top speed)." }
                isReal(definition.windingR, { (unitless) : [0, 12, 500] } as RealBoundSpec);

                annotation { "Name" : "Gearbox eff %",
                             "Description" : "Gearbox efficiency, %. Limits 80-100. Typical 95 for one planetary stage, 100 for direct drive. The blade feature ignores gear loss, so set 100 to compare with its numbers." }
                isReal(definition.gearEff, { (unitless) : [80, 95, 100] } as RealBoundSpec);

                annotation { "Name" : "ESC eff %",
                             "Description" : "ESC efficiency, %. Limits 80-100. Typical 95-98. Motor copper loss is in the winding resistance; iron and no-load losses (550-900 W on a 63-series outrunner at speed, from a production eFoil's logs) are not modelled, so Wh/km reads low." }
                isReal(definition.escEff, { (unitless) : [80, 97, 100] } as RealBoundSpec);

                annotation { "Name" : "Pack Ah",
                             "Description" : "Battery pack capacity, amp hours. Limits 1-100. Typical 12-30 Ah for eFoil. With Cells (S) x Cell V and Usable % this sets the range." }
                isReal(definition.packAh, { (unitless) : [1, 20, 100] } as RealBoundSpec);

                annotation { "Name" : "Usable %",
                             "Description" : "Share of the nameplate pack energy you actually use before cut-off or voltage sag ends the ride, %. Limits 50-100. Typical 80-90." }
                isReal(definition.usable, { (unitless) : [50, 90, 100] } as RealBoundSpec);
            }
        }

        annotation { "Name" : "Print report", "Default" : true,
                     "Description" : "Prints the full report and a CSV speed sweep to the FeatureScript console, ready to paste into a spreadsheet." }
        definition.printReport is boolean;
    }
    {
        setVariable(context, "foilPerfLog", "");
        setVariable(context, "foilPerfNotice", "");
        // ---------------- inputs ----------------
        var wing;
        var stab;
        try silent { wing = getVariable(context, "foilWingModel"); }
        try silent { stab = getVariable(context, "foilStabModel"); }
        var mastM;
        var fusM;
        try silent { mastM = getVariable(context, "foilMastModel"); }
        try silent { fusM = getVariable(context, "foilFuselageModel"); }
        if (wing == undefined)
            throw regenError("Add a Foil wing feature above this one");
        if (!(definition.vTakeoff < definition.vCruise && definition.vCruise < definition.vMax))
            throw regenError("Speeds must increase: take-off < cruise < max", ["vTakeoff", "vCruise", "vMax"]);

        const g = 9.80665;
        const rho = definition.density;
        const T = definition.waterTemp;
        const nu = waterViscosity(T, rho);
        const W = definition.mass * g;

        // ---------------- aerodynamic model ----------------
        // each surface's own lift-curve slope: the polar value if it has one, else the shared
        // thin-aerofoil default (2 pi with a viscous allowance) - previously both surfaces were
        // forced to share one fixed slope regardless of section
        const Lw = liftingLine(wing, wing.claSection, 20);
        var ctx = {
                "rho" : rho, "nu" : nu, "W" : W, "lam" : definition.laminar / 100,
                "cdA" : definition.otherDrag / 10000, "Mext" : definition.extMoment,
                "wing" : wing, "Lw" : Lw, "xw" : acX(wing), "cd0Shape_w" : formFactor(meanThickness(wing)) * wing.wetted / wing.area,
                "ke" : 2 / (PI * Lw.AR), "hasStab" : stab != undefined,
                "powered" : false, "thrustZ" : 0, "stabZ" : stab != undefined ? stab.baseZ : 0, "fusZ" : 0,
                "podX" : 0, "podTilt" : 0
            };
        if (ctx.hasStab)
        {
            const Ls = liftingLine(stab, stab.claSection, 20);
            ctx.stab = stab;
            ctx.Ls = Ls;
            ctx.xs = acX(stab);
            ctx.cd0Shape_s = formFactor(meanThickness(stab)) * stab.wetted / stab.area;
            ctx.C1 = Ls.CL0 - Ls.CLa * ctx.ke * Lw.CL0;
            ctx.C2 = Ls.CLa * (1 - ctx.ke * Lw.CLa);
        }
        else
        {
            ctx.C1 = 0;
            ctx.C2 = 0;
            ctx.xs = 0;
        }
        // mast, motor pod and fuselage drag. The wing is Wing depth below the surface (surface at
        // Z = +depth in the wing-pivot frame), so only the mast between its base and the surface is
        // wetted; spray drag where it pierces the surface. Drag only - their pitching moments are
        // not added to trim (the balancing thrust/pull line depends on the discipline).
        const depthM = definition.depth / meter;
        ctx.mastOn = mastM != undefined;
        if (ctx.mastOn)
        {
            // the section where the mast is wetted: at half the submerged height (taper / thickening)
            const sMid = mastM.chordTop != undefined ? min(max((depthM / 2) / mastM.height, 0), 1) : 0;
            ctx.mastC = mastM.chordTop != undefined ? mastM.chord + (mastM.chordTop - mastM.chord) * sMid : mastM.chord;
            const uT = mastM.chordTop != undefined && mastM.thickenFrom < 1 ? min(max((sMid - mastM.thickenFrom) / (1 - mastM.thickenFrom), 0), 1) : 0;
            ctx.mastT = mastM.chordTop != undefined ? mastM.thick + (mastM.thickTop - mastM.thick) * uT * uT * (3 - 2 * uT) : mastM.thick;
            ctx.mastFF = formFactor(ctx.mastT / ctx.mastC);
            // the mast's own law for the strip sum in partsDrag (build 241): chord base to top, thickness to the top
            // by a smoothstep from Thicken from
            const lawOn = mastM.chordTop != undefined;
            ctx.mastC0 = mastM.chord;
            ctx.mastC1 = lawOn ? mastM.chordTop : mastM.chord;
            ctx.mastT0 = mastM.thick;
            ctx.mastT1 = lawOn && mastM.thickTop != undefined ? mastM.thickTop : mastM.thick;
            ctx.mastS0 = lawOn && mastM.thickenFrom != undefined ? mastM.thickenFrom : 1;
            ctx.mastBase = mastM.baseZ;
            ctx.mastH = mastM.height;
            ctx.podOn = mastM.podOn == 1;
            if (ctx.podOn)
            {
                ctx.podL = mastM.podLength;
                ctx.podD = mastM.podDia;
                ctx.podZ = mastM.podZ;
                ctx.podX = mastM.podX;
                ctx.podTilt = mastM.podTilt != undefined ? mastM.podTilt : 0;      // rad, nose-down positive
                ctx.podSwet = PI * mastM.podDia * (mastM.podLength - 0.5 * mastM.podFairLength);
            }
        }
        else
            ctx.podOn = false;
        ctx = rideDepth(ctx, depthM);
        ctx.fusOn = fusM != undefined && fusM.len != undefined;
        if (ctx.fusOn)
        {
            ctx.fusL = fusM.len;
            ctx.fusD = fusM.dia;
            ctx.fusSwet = fusM.wettedExt;
            ctx.fusZ = fusM.axisZ != undefined ? fusM.axisZ : 0;
        }
        var socketJ;
        var hubJ;
        var flatJ;
        try silent { socketJ = getVariable(context, "foilWingSocket"); }
        try silent { hubJ = getVariable(context, "foilWingHub"); }
        try silent { flatJ = getVariable(context, "foilWingFlat"); }
        ctx.joints = jointsOf(definition.jointFinish, wing, stab, mastM, ctx.fusOn, socketJ, hubJ, flatJ);

        const Sw = wing.area;
        const Ss = ctx.hasStab ? stab.area : 0;
        const xnp = (Sw * Lw.CLa * ctx.xw + Ss * ctx.C2 * ctx.xs) / (Sw * Lw.CLa + Ss * ctx.C2);

        // ---------------- operating points ----------------
        const pTo = trimPoint(ctx, definition.vTakeoff / 3.6);
        const pCr = trimPoint(ctx, definition.vCruise / 3.6);
        const pMx = trimPoint(ctx, definition.vMax / 3.6);

        // motor pod layout, set by Pod height. Low pod = eFoil: the motor is in the water at every depth
        // the wing can ride. High pod = foil assist: the rider picks the mode by ride depth - deep, the
        // motor is in the water and drives; shallow, the pod is out and the foil is ridden on pumping
        // or wave energy. Pod out = surface 10 mm below the pod's bottom; pod in = 10 mm above its top.
        // Pod out only counts as a real mode if the wing can still ride there: at least 2 MAC deep,
        // the same free-surface limit as the Wing depth check. Each mode is solved at its own depth.
        // with Propulsion on, "in" and "out" also cover the prop disc (its axis on the pod axis)
        const propOn = definition.propOn;
        const pr = propOn ? propModel(definition, rho) : undefined;
        var assist = undefined;
        if (ctx.podOn)
        {
            const rP = propOn ? max(ctx.podD, pr.D) / 2 : ctx.podD / 2;
            const dOut = ctx.podZ - rP - 0.01;
            const dIn = ctx.podZ + rP + 0.01;
            const minOut = 2 * wing.mac;
            assist = { "dOut" : dOut, "dIn" : dIn, "minOut" : minOut,
                       "outOk" : dOut >= minOut, "inOk" : dIn - ctx.mastBase < ctx.mastH };
            if (assist.outOk)
                assist.pOut = trimPoint(rideDepth(ctx, dOut), definition.vCruise / 3.6);
            if (assist.inOk)
                assist.pIn = trimPoint(rideDepth(ctx, dIn), definition.vCruise / 3.6);
        }

        // propulsion: solved at the powered ride depth - Wing depth if the prop is fully under
        // water there, else the pod-in depth (foil assist), else not at all
        var pctx = undefined;
        var pDepth = depthM;
        var propCr = undefined;
        var vTop = -1;
        var fullStatic = undefined;
        var pPw = undefined;            // powered cruise point (thrust couple in trim)
        var smPwMin = 1e9;              // lowest powered static margin over take-off..max, % MAC
        var smPwMinV = 0;
        if (propOn)
        {
            if (!ctx.podOn)
                pctx = ctx;
            else if (depthM >= ctx.podZ + max(ctx.podD, pr.D) / 2)
                pctx = ctx;
            else if (assist.inOk)
            {
                pDepth = assist.dIn;
                pctx = rideDepth(ctx, pDepth);
            }
            if (pctx != undefined)
            {
                // the thrust line is the pod axis; with no pod its height is unknown, so no couple
                if (ctx.podOn)
                {
                    pctx.powered = true;
                    pctx.thrustZ = ctx.podZ;
                }
                const Vc = definition.vCruise / 3.6;
                pPw = trimPoint(pctx, Vc);
                const Tc = pPw.T;
                propCr = propOperate(pr, Vc, Tc);
                propCr.T = Tc;
                vTop = propTopSpeed(pr, pctx, definition.vTakeoff);
                fullStatic = propFullPower(pr, 0);
                if (ctx.hasStab && pctx.powered)
                {
                    var vs = definition.vTakeoff;
                    while (vs <= definition.vMax + 1e-9)
                    {
                        const sm = (xnp - trimPoint(pctx, vs / 3.6).xcg) / wing.mac * 100;
                        if (sm < smPwMin)
                        {
                            smPwMin = sm;
                            smPwMinV = vs;
                        }
                        vs += definition.vStep;
                    }
                }
            }
        }

        // wing section CL max: the polar value interpolated at the take-off Reynolds number if
        // the wing has a polar (stall genuinely happens near take-off, so that Re is the one
        // that matters most), else the flat analytic input
        const clMaxWing = wing.polarOn == 1
            ? polarInterp(wing.polarRe1, wing.polarClmax1, wing.polarRe2, wing.polarClmax2, pTo.Re)
            : definition.clMax;
        // the tip section's own CL max at the same Re (build 166); the root's when there is no tip section
        const clMaxTip = wing.polarOn == 1 && wing.tipOn == 1
            ? polarInterp(wing.polarRe1, wing.polarClmax1Tip, wing.polarRe2, wing.polarClmax2Tip, pTo.Re)
            : clMaxWing;

        // stall: first section to reach ITS CL max, then the speed that needs that alpha
        const aStall = stallAlpha(wing, Lw, clMaxWing, clMaxTip);
        const liftCoefAtStall = Sw * (Lw.CL0 + Lw.CLa * aStall) + Ss * (ctx.C1 + ctx.C2 * aStall);
        const vStall = (aStall < 1e8 && liftCoefAtStall > 0) ? sqrt(2 * W / (rho * liftCoefAtStall)) : -1;
        const toMargin = maxLocalClRatio(wing, Lw, pTo.alpha, clMaxWing, clMaxTip);

        // ---------------- leading-edge tubercles: reported apart, never folded into the figures (build 232, user) ----------------
        var tub = { "on" : false, "note" : "" };
        if (definition.tubercleCredits != false && wing.bumpOn == 1 && wing.bumpAmp != undefined && wing.bumpAmp > 0)
        {
            var worst = 0;
            var ripple = 0;
            var cSum = 0;
            var nIn = 0;
            for (var th in Lw.thetas)
            {
                const eta = cos(th * radian);
                if (eta > 0.95 || eta < wing.bumpFrom || eta > wing.bumpTo)
                    continue;
                const c = chordAt(wing, eta);
                const rp = 0.5 * wing.bumpAmp / c;
                const r = lltLocalCl(wing, Lw, pTo.alpha, th) * (1 + rp) / clMaxAt(wing, eta, clMaxWing, clMaxTip);
                if (r > worst)
                {
                    worst = r;
                    ripple = rp;
                }
                cSum += c;
                nIn += 1;
            }
            if (nIn > 0)
            {
                const cMean = cSum / nIn;
                const hc = wing.bumpAmp / cMean;                               // height over the chord there
                const lc = wing.bumpPitch / cMean;                             // pitch over the chord
                const flank = atan(PI * wing.bumpAmp / wing.bumpPitch) / degree;
                const tested = hc >= 0.025 && hc <= 0.12 && lc >= 0.11 && lc <= 0.5;
                const toT = max(toMargin, worst);
                const vT = speedAtAlpha(ctx, tubercleStallAlpha(wing, Lw, clMaxWing, clMaxTip, 1, true));
                const vLo = speedAtAlpha(ctx, tubercleStallAlpha(wing, Lw, clMaxWing, clMaxTip, 0.95, true));
                const vHi = speedAtAlpha(ctx, tubercleStallAlpha(wing, Lw, clMaxWing, clMaxTip, 1.06, true));
                const v4 = speedAtAlpha(ctx, tubercleStallAlpha(wing, Lw, clMaxWing, clMaxTip, 1, true) + 4 * PI / 180);
                // the wing's profile drag at cruise, as trimPass has it, for the drag range
                const qCr = 0.5 * rho * (definition.vCruise / 3.6) ^ 2;
                const cdProfW = wing.polarOn == 1
                    ? polarInterp(wing.polarRe1, wing.polarCdmin1 + wing.polarK1 * (pCr.CLw - wing.polarClcd1) ^ 2,
                                  wing.polarRe2, wing.polarCdmin2 + wing.polarK2 * (pCr.CLw - wing.polarClcd2) ^ 2, pCr.Re)
                    : skinFriction(pCr.Re, ctx.lam) * ctx.cd0Shape_w * (1 + 0.38 * pCr.CLw * pCr.CLw);
                const DpW = qCr * Sw * cdProfW;
                const ldLo = W / (pCr.D + 0.08 * DpW);
                const ldHi = W / (pCr.D - 0.08 * DpW);
                tub = { "on" : true, "hc" : hc, "lc" : lc, "ripple" : ripple, "flankDeg" : flank, "tested" : tested,
                        "toSmooth" : toMargin, "toTrough" : toT, "toClmaxLo" : toT / 0.95, "toClmaxHi" : toT / 1.06,
                        "vSmooth" : vStall, "vTrough" : vT, "vClmaxLo" : vLo, "vClmaxHi" : vHi, "vDelay4" : v4,
                        "DpW" : DpW, "ldLo" : ldLo, "ldHi" : ldHi, "ldSmooth" : pCr.LD };
                tub.note = " | LE tubercles, reported apart (not in the figures above): height " ~ fmt(hc * 100, 1) ~ " % of chord, pitch " ~ fmt(lc, 2) ~ " c, flank sweep " ~ fmt(flank, 0) ~ " deg" ~
                    (tested ? "" : " (outside the tested range, 2.5-12 % and 0.11-0.5 c)") ~
                    "; trough-first stall, local cl +" ~ fmt(ripple * 100, 1) ~ " %: take-off " ~ fmt(toT * 100, 0) ~ " % of CL max (smooth " ~ fmt(toMargin * 100, 0) ~ "), stall " ~ kmh(vT) ~ " km/h (" ~ kmh(vStall) ~ ")" ~
                    "; published CL max -5 to +6 %: take-off " ~ fmt(toT / 0.95 * 100, 0) ~ " to " ~ fmt(toT / 1.06 * 100, 0) ~ " %, stall " ~ kmh(vLo) ~ " to " ~ kmh(vHi) ~ " km/h" ~
                    "; the flipper's +4 deg stall angle: " ~ kmh(v4) ~ " km/h if the lift curve held, which it does not - read it as lift kept past stall" ~
                    "; drag before stall of unknown sign within 8 % of the wing's profile drag: glide " ~ fmt(ldLo, 1) ~ " to " ~ fmt(ldHi, 1) ~ " at cruise (" ~ fmt(pCr.LD, 1) ~ ")";
            }
        }
        setVariable(context, "foilTubercleCredits", tub);

        // cavitation number at max speed
        const pv = 610.94 * exp(17.625 * T / (T + 243.04));
        const depth = definition.depth / meter;
        const sigma = (101325 + rho * g * depth - pv) / (0.5 * rho * (definition.vMax / 3.6) ^ 2);

        // root bending at cruise lift x load factor
        const halfLift = 0.5 * rho * (definition.vCruise / 3.6) ^ 2 * Sw * pCr.CLw / 2;
        const yBar = lltCentroid(Lw, pCr.alpha) * wing.span / 2;
        const Mroot = definition.loadFactor * halfLift * yBar;
        const hRoot = wing.rootT * wing.c0;
        const capW = definition.capWidth / 100 * wing.c0;
        const disc = hRoot ^ 2 - 4 * Mroot / (definition.capStress * 1e6 * capW);
        const tCap = disc > 0 ? (hRoot - sqrt(disc)) / 2 : -1;
        // bending moment along the half span at the load factor, for the Foil mold's stiffness check
        // (it has the layup; this has the loads). Stab: its cruise lift, or 15 % of the weight if
        // that is larger (a pump or a gust loads it far beyond level trim), same load factor
        setVariable(context, "foilWingLoads", { "n" : definition.loadFactor, "W" : W, "span" : wing.span, "halfLift" : definition.loadFactor * halfLift, "yBar" : yBar,
                    "M" : lltMoments(Lw, pCr.alpha, wing.span, definition.loadFactor * halfLift) });
        if (ctx.hasStab)
        {
            const halfLiftS = max(abs(0.5 * rho * (definition.vCruise / 3.6) ^ 2 * Ss * pCr.CLs), 0.15 * W) / 2;
            setVariable(context, "foilStabLoads", { "n" : definition.loadFactor, "W" : W, "span" : stab.span, "halfLift" : definition.loadFactor * halfLiftS,
                        "M" : lltMoments(ctx.Ls, pCr.alpha, stab.span, definition.loadFactor * halfLiftS) });
        }

        // ---------------- notice ----------------
        const macW = wing.mac;
        var msg = "Cruise " ~ fmt(definition.vCruise, 0) ~ " km/h: L/D " ~ fmt(pCr.LD, 1) ~
            " · drag " ~ fmt(pCr.D, 0) ~ " N (mast " ~ fmt(pCr.Dmast, 1) ~ ", fuselage/pod " ~ fmt(pCr.Dbody, 1) ~
            (ctx.joints.on ? ", joints " ~ fmt(pCr.Djoints, 1) ~ " " ~ finishWord(ctx.joints.finish) : "") ~ ") · " ~ fmt(pCr.P, 0) ~ " W" ~
            " | stall " ~ (vStall > 0 ? fmt(vStall * 3.6, 1) ~ " km/h" : "n/a") ~ (wing.polarOn == 1 ? " (polar)" : "") ~
            " | take-off at " ~ fmt(toMargin * 100, 0) ~ "% of CL max" ~
            (ctx.hasStab ? " | trim CG " ~ fmt(pCr.xcg * 1000, 0) ~ " mm · static margin " ~ fmt((xnp - pCr.xcg) / macW * 100, 0) ~ "% MAC" : " | no stabiliser: trim not solved") ~
            " | root " ~ fmt(Mroot, 0) ~ " Nm at " ~ fmt(definition.loadFactor, 1) ~ "g, caps " ~ (tCap > 0 ? fmt(tCap * 1000, 1) ~ " mm" : "impossible (section too thin)");
        var warnings = [];
        if (toMargin >= 1)
            warnings = append(warnings, "wing stalls at take-off speed");
        else if (toMargin > 0.85)
            warnings = append(warnings, "take-off within 15% of stall");
        if (ctx.hasStab && (abs(pTo.CLs) > 0.8 || abs(pMx.CLs) > 0.8))
            warnings = append(warnings, "stab CL above 0.8 in range");
        if (sigma < 1.5)
            warnings = append(warnings, "cavitation number " ~ fmt(sigma, 2) ~ " at max speed - check section Cp min");
        if (depth / macW < 2)
            warnings = append(warnings, "depth under 2 MAC - free-surface effects not modelled");
        if (!ctx.mastOn)
            warnings = append(warnings, "no Foil mast above this feature - mast drag not included (move Foil performance below the mast, or use Other cm^2)");
        else if (!ctx.mastPierces)
            warnings = append(warnings, "the whole mast is under water at this Wing depth - the board would be submerged; check Wing depth");
        if (assist != undefined && !assist.inOk)
            warnings = append(warnings, "the motor pod cannot be fully submerged without the board going under, so the motor can never drive - lower Pod height (Foil mast)");
        if (assist != undefined)
        {
            const podState = ctx.podFrac >= 1 ? "in the water" : (ctx.podFrac <= 0 ? "out of the water" : fmt(ctx.podFrac * 100, 0) ~ "% in the water (transition)");
            if (assist.outOk)
            {
                msg = msg ~ " | foil assist: pod " ~ podState ~ " at this depth";
                if (assist.inOk)
                    msg = msg ~ "; motor mode at >= " ~ fmt(assist.dIn * 1000, 0) ~ " mm: L/D " ~ fmt(assist.pIn.LD, 1) ~ ", drag (= thrust) " ~ fmt(assist.pIn.D, 0) ~ " N";
                msg = msg ~ "; pump/wave mode at <= " ~ fmt(assist.dOut * 1000, 0) ~ " mm: L/D " ~ fmt(assist.pOut.LD, 1) ~ ", drag " ~ fmt(assist.pOut.D, 0) ~ " N, " ~
                    fmt(assist.pOut.P, 0) ~ " W to sustain";
            }
            else
                msg = msg ~ " | eFoil layout: pod " ~ podState ~ " at this depth" ~ (assist.inOk ? ", fully in at >= " ~ fmt(assist.dIn * 1000, 0) ~ " mm" : "");
        }
        if (propOn)
        {
            if (pctx == undefined)
                warnings = append(warnings, "Propulsion: the prop cannot be fully submerged without the board going under - lower Pod height (Foil mast) or use a smaller Prop dia");
            else
            {
                msg = msg ~ " | prop at " ~ fmt(definition.vCruise, 0) ~ " km/h" ~ (pDepth != depthM ? " (pod in, " ~ fmt(pDepth * 1000, 0) ~ " mm)" : "") ~ ": " ~
                    fmt(propCr.rpm, 0) ~ " rpm, " ~ fmt(propCr.throttle * 100, 0) ~ "% throttle, " ~ fmt(propCr.pBatt, 0) ~ " W battery, " ~
                    fmt(propCr.whKm, 1) ~ " Wh/km, range " ~ fmt(propCr.range, 0) ~ " km · top speed " ~
                    (vTop < 0 ? "over 100 km/h" : (vTop == 0 ? "below take-off" : fmt(vTop, 1) ~ " km/h"));
                if (pctx.powered && ctx.hasStab)
                    msg = msg ~ " · under power: thrust couple " ~ fmt(pPw.Mthrust, 1) ~ " Nm, trim CG " ~ fmt(pPw.xcg * 1000, 0) ~ " mm (" ~
                        (pPw.xcg >= pCr.xcg ? "+" : "") ~ fmt((pPw.xcg - pCr.xcg) * 1000, 0) ~ "), static margin " ~ fmt((xnp - pPw.xcg) / macW * 100, 0) ~ "% MAC";
                if (smPwMin < 0)
                    warnings = append(warnings, "Propulsion: pitch-unstable under power at " ~ fmt(smPwMinV, 1) ~ " km/h (static margin " ~ fmt(smPwMin, 0) ~
                        "% MAC - the thrust couple puts the trim CG behind the neutral point). Lower Pod height (Foil mast) to bring the thrust line down, or add stab area / Arm");
                else if (smPwMin < 5)
                    warnings = append(warnings, "Propulsion: static margin under power only " ~ fmt(smPwMin, 0) ~ "% MAC at " ~ fmt(smPwMinV, 1) ~ " km/h - lower Pod height or add stab area / Arm");
                if (vTop == 0)
                    warnings = append(warnings, "Propulsion: full power cannot hold take-off speed - raise Current lim A, Gear ratio or Prop dia");
                if (propCr.iMotor > pr.iLim)
                    warnings = append(warnings, "Propulsion: cruise needs " ~ fmt(propCr.iMotor, 0) ~ " A, over the " ~ fmt(pr.iLim, 0) ~ " A limit - raise Current lim A or Gear ratio, or lower Prop P/D");
                if (propCr.throttle > 1)
                    warnings = append(warnings, "Propulsion: cruise needs " ~ fmt(propCr.throttle * 100, 0) ~ "% throttle (the motor cannot spin the prop fast enough) - raise Prop P/D or Cells (S), or lower Gear ratio");
            }
        }
        if (!ctx.fusOn)
            warnings = append(warnings, "no Foil fuselage above this feature - fuselage drag not included (move Foil performance below the fuselage, or use Other cm^2)");
        if (wing.polarOn == 1 && polarOutOfRange(wing, [pTo.Re, pCr.Re, pMx.Re]))
            warnings = append(warnings, "wing polar used outside its own Re 1-Re 2 range at some speed - CLmax/Cd there are extrapolated flat, not interpolated");
        if (ctx.hasStab && stab.polarOn == 1 && polarOutOfRange(stab, [pTo.Re * stab.mac / wing.mac, pCr.Re * stab.mac / wing.mac, pMx.Re * stab.mac / wing.mac]))
            warnings = append(warnings, "stab polar used outside its own Re 1-Re 2 range at some speed - CLmax/Cd there are extrapolated flat, not interpolated");
        msg = msg ~ tub.note;
        if (size(warnings) > 0)
        {
            var w = "";
            for (var s in warnings)
                w = w ~ (w == "" ? "" : "; ") ~ s;
            foilNotice(context, id, "foilPerfNotice", msg ~ " | WARNING: " ~ w, true);
        }
        else
            foilNotice(context, id, "foilPerfNotice", msg, false);

        setVariable(context, "foilCruiseLD", pCr.LD);
        setVariable(context, "foilCruiseDrag", pCr.D);
        setVariable(context, "foilCruisePower", pCr.P);
        setVariable(context, "foilStallSpeed", vStall * 3.6);
        setVariable(context, "foilRootMoment", Mroot);
        if (propCr != undefined)
        {
            setVariable(context, "foilCruiseBatteryPower", propCr.pBatt);
            setVariable(context, "foilCruiseWhPerKm", propCr.whKm);
            setVariable(context, "foilRangeKm", propCr.range);
            setVariable(context, "foilTopSpeed", vTop);
            if (pctx.powered)
                setVariable(context, "foilPoweredTrimCG", pPw.xcg * 1000);   // mm aft of the wing root pivot
        }

        // ---------------- console report ----------------
        if (definition.printReport)
        {
            foilPrint(context, "foilPerfLog", "===== FOIL PERFORMANCE =====");
            foilPrint(context, "foilPerfLog", perfInputLog(definition));
            foilPrint(context, "foilPerfLog", "Water: rho " ~ fmt(rho, 0) ~ " kg/m3, nu " ~ fmt(nu * 1e6, 3) ~ "e-6 m2/s, mass " ~ fmt(definition.mass, 0) ~ " kg");
            foilPrint(context, "foilPerfLog", "Wing: S " ~ fmt(Sw * 1e4, 0) ~ " cm2, AR " ~ fmt(Lw.AR, 2) ~ ", CLa " ~ fmt(Lw.CLa, 3) ~ "/rad, CL0 " ~ fmt(Lw.CL0, 3) ~
                ", span efficiency e " ~ fmt(spanEfficiency(Lw), 3) ~ ", Cm0 " ~ fmt(wing.cm0, 4) ~ ", ac " ~ fmt(ctx.xw * 1000, 1) ~ " mm");
            if (ctx.hasStab)
            {
                foilPrint(context, "foilPerfLog", "Stab: S " ~ fmt(Ss * 1e4, 0) ~ " cm2, AR " ~ fmt(ctx.Ls.AR, 2) ~ ", CLa " ~ fmt(ctx.Ls.CLa, 3) ~ "/rad, CL0 " ~ fmt(ctx.Ls.CL0, 3) ~
                    ", ac " ~ fmt(ctx.xs * 1000, 1) ~ " mm, downwash de/da " ~ fmt(ctx.ke * Lw.CLa, 3));
                foilPrint(context, "foilPerfLog", "Neutral point " ~ fmt(xnp * 1000, 1) ~ " mm aft of wing root pivot");
            }
            foilPrint(context, "foilPerfLog", "Stall " ~ (vStall > 0 ? fmt(vStall * 3.6, 1) ~ " km/h" : "n/a") ~ " (section CL max " ~ fmt(clMaxWing, 2) ~ (wing.tipOn == 1 ? " root, " ~ fmt(clMaxTip, 2) ~ " tip" : "") ~
                (wing.polarOn == 1 ? " from polar at Re " ~ fmt(pTo.Re / 1e6, 2) ~ "M" : " analytic") ~ ")");
            if (tub.on)
            {
                foilPrint(context, "foilPerfLog", "Tubercles - reported apart: nothing above, below or in the CSV includes them (build 232)");
                foilPrint(context, "foilPerfLog", "  geometry: height " ~ fmt(tub.hc * 100, 1) ~ " % of the local chord, pitch " ~ fmt(tub.lc, 2) ~ " c, flank sweep up to " ~ fmt(tub.flankDeg, 1) ~ " deg" ~
                    (tub.tested ? " - inside the tested range (height 2.5-12 % c, pitch 0.11-0.5 c)" : " - OUTSIDE the tested range (height 2.5-12 % c, pitch 0.11-0.5 c): the credits below are extrapolated"));
                foilPrint(context, "foilPerfLog", "  what the lifting line can compute: the local cl in the troughs is " ~ fmt(tub.ripple * 100, 1) ~ " % above the smooth wing's (the chord's share of half the height; the loading cannot follow a ripple shorter than a chord), so the first stall begins there: take-off " ~
                    fmt(tub.toTrough * 100, 0) ~ " % of CL max against " ~ fmt(tub.toSmooth * 100, 0) ~ " smooth, stall " ~ kmh(tub.vTrough) ~ " km/h against " ~ kmh(tub.vSmooth));
                foilPrint(context, "foilPerfLog", "  published credits on the same two numbers: section CL max -5 % (two-dimensional sections at Re 0.1-0.2M, Johari 2007, Hansen 2011) to +6 % (humpback flipper, finite wing at Re 0.5M, Miklosovic 2004): take-off " ~
                    fmt(tub.toClmaxLo * 100, 0) ~ " to " ~ fmt(tub.toClmaxHi * 100, 0) ~ " %, stall " ~ kmh(tub.vClmaxLo) ~ " to " ~ kmh(tub.vClmaxHi) ~ " km/h");
                foilPrint(context, "foilPerfLog", "  stall angle +4 deg on the flipper: stall " ~ kmh(tub.vDelay4) ~ " km/h if the lift curve held its slope; it flattens, so read it as lift kept past stall (about 0.8 CL max at a 12 % height in the 2D tests, less at a small height): a pump stroke or a carve that has stalled the most loaded station degrades instead of failing. This model has no post-stall branch and cannot show it");
                foilPrint(context, "foilPerfLog", "  drag before stall: unknown sign, within 8 % of the wing's profile drag (" ~ fmt(tub.DpW, 1) ~ " N at cruise; finite and swept wings measured less drag, two-dimensional sections more): glide " ~ fmt(tub.ldLo, 1) ~ " to " ~ fmt(tub.ldHi, 1) ~ " against " ~ fmt(tub.ldSmooth, 1));
            }
            foilPrint(context, "foilPerfLog", "Cavitation number at " ~ fmt(definition.vMax, 0) ~ " km/h, depth " ~ fmt(depth * 1000, 0) ~ " mm: " ~ fmt(sigma, 2) ~ " (cavitation starts where -Cp min exceeds this)");
            if (ctx.joints.on)
            {
                const qCr = 0.5 * ctx.rho * (definition.vCruise / 3.6) ^ 2;
                var jt = "";
                for (var j in ctx.joints.junctions)
                    jt = jt ~ (jt == "" ? "" : "; ") ~ j[3] ~ " " ~ fmt(j[0], 0) ~ " x " ~ fmt(j[1] * 1000, 1) ~ " on " ~ fmt(j[2] * 1000, 0) ~ " mm (t/c " ~ fmt(100 * j[1] / j[2], 1) ~ " %) " ~
                        fmt(j[0] * junctionDrag(qCr, j[1], j[2], j[4]), 2) ~ " N";
                for (var f in ctx.joints.faces)
                    jt = jt ~ (jt == "" ? "" : "; ") ~ f[3] ~ " " ~ fmt(f[0] * 10000, 1) ~ " cm^2 " ~ finishWord(f[2]) ~ " " ~ fmt(faceDrag(qCr, f[0], f[1], f[2]), 2) ~ " N";
                foilPrint(context, "foilPerfLog", "JOINTS " ~ finishWord(ctx.joints.finish) ~ " at " ~ fmt(definition.vCruise, 0) ~ " km/h: " ~ fmt(pCr.Djoints, 2) ~ " N of " ~ fmt(pCr.D, 1) ~ " (" ~
                    fmt(100 * pCr.Djoints / pCr.D, 1) ~ " %): " ~ (jt == "" ? "none found (no joint, fuselage or pod above this feature)" : jt) ~
                    ". Lofted, bare and filleted bracket it; the factors are handbook estimates (Hoerner), not measurements");
            }
            if (ctx.mastOn)
                foilPrint(context, "foilPerfLog", "Mast: " ~ fmt(ctx.mastSub * 1000, 0) ~ " mm of " ~ fmt(mastM.height * 1000, 0) ~ " mm submerged at this depth, chord " ~ fmt(ctx.mastC * 1000, 0) ~
                    " mm, t/c " ~ fmt(mastM.tc * 100, 1) ~ "%, at cruise " ~ fmt(pCr.Dmast, 1) ~ " N incl. spray " ~ fmt(pCr.Dspray, 2) ~ " N" ~
                    (ctx.podOn ? "; motor pod " ~ fmt(ctx.podD * 1000, 0) ~ " x " ~ fmt(ctx.podL * 1000, 0) ~ " mm, " ~ fmt(ctx.podFrac * 100, 0) ~ "% under water" ~
                        (pCr.DpodSpray > 0 ? ", pod spray " ~ fmt(pCr.DpodSpray, 2) ~ " N (in fuselage/pod drag)" : "") : ""));
            if (assist != undefined)
            {
                if (assist.outOk)
                {
                    foilPrint(context, "foilPerfLog", "Layout: foil assist - motor mode when ridden deep, pump/wave mode when ridden shallow with the pod out");
                    foilPrint(context, "foilPerfLog", "  pump/wave mode (pod OUT, wing depth <= " ~ fmt(assist.dOut * 1000, 0) ~ " mm): cruise drag " ~ fmt(assist.pOut.D, 1) ~ " N, L/D " ~ fmt(assist.pOut.LD, 2) ~
                        ", " ~ fmt(assist.pOut.P, 0) ~ " W to sustain from pumping or the wave, mast " ~ fmt(assist.pOut.Dmast, 1) ~ " N");
                }
                else
                    foilPrint(context, "foilPerfLog", "Layout: eFoil - the pod would only clear the water with the wing at " ~ fmt(assist.dOut * 1000, 0) ~ " mm, under the " ~ fmt(assist.minOut * 1000, 0) ~
                        " mm (2 MAC) it needs to ride; raise Pod height by at least " ~ fmt((assist.minOut - assist.dOut) * 1000, 0) ~ " mm for a foil-assist layout");
                if (assist.inOk)
                    foilPrint(context, "foilPerfLog", "  " ~ (assist.outOk ? "motor mode" : "motor") ~ " (pod IN, wing depth >= " ~ fmt(assist.dIn * 1000, 0) ~ " mm): cruise drag = thrust needed " ~ fmt(assist.pIn.D, 1) ~ " N, L/D " ~ fmt(assist.pIn.LD, 2) ~
                        ", power at the prop " ~ fmt(assist.pIn.P, 0) ~ " W, mast " ~ fmt(assist.pIn.Dmast, 1) ~ " N, fuselage/pod " ~ fmt(assist.pIn.Dbody, 1) ~ " N");
            }
            if (ctx.fusOn)
                foilPrint(context, "foilPerfLog", "Fuselage: " ~ fmt(ctx.fusL * 1000, 0) ~ " mm long, " ~ fmt(ctx.fusD * 1000, 1) ~ " mm dia, wetted " ~ fmt(ctx.fusSwet * 1e4, 0) ~
                    " cm2, fuselage + pod at cruise " ~ fmt(pCr.Dbody, 1) ~ " N");
            foilPrint(context, "foilPerfLog", "Root bending at " ~ fmt(definition.loadFactor, 1) ~ "g: " ~ fmt(Mroot, 0) ~ " Nm, lift centroid " ~ fmt(yBar * 1000, 0) ~ " mm from centreline, section depth " ~
                fmt(hRoot * 1000, 1) ~ " mm, cap width " ~ fmt(capW * 1000, 0) ~ " mm -> cap thickness " ~ (tCap > 0 ? fmt(tCap * 1000, 2) ~ " mm each" : "not achievable"));
            if (propCr != undefined)
            {
                foilPrint(context, "foilPerfLog", "Propulsion (B-series open water, +/- 20 %): prop " ~ fmt(pr.D * 1000, 0) ~ " mm, P/D " ~ fmt(pr.pd, 2) ~ ", EAR " ~ fmt(pr.ear, 2) ~ ", " ~ pr.z ~
                    " blades; " ~ fmt(pr.kv, 0) ~ " kV, " ~ definition.cells ~ "S (" ~ fmt(pr.vPack, 1) ~ " V), gear " ~ fmt(pr.gear, 2) ~ ":1, limit " ~ fmt(pr.iLim, 0) ~
                    " A, winding " ~ fmt(pr.R * 1000, 1) ~ " mOhm; pack " ~ fmt(pr.packWh, 0) ~ " Wh usable");
                foilPrint(context, "foilPerfLog", "  solved at ride depth " ~ fmt(pDepth * 1000, 0) ~ " mm" ~ (pDepth != depthM ? " (pod-in depth: the prop is not fully under water at Wing depth)" : "") ~
                    (ctx.podOn ? "" : " - no motor pod on Foil mast, so prop immersion is not checked"));
                foilPrint(context, "foilPerfLog", "  static, full power: " ~ fmt(fullStatic.n * 60, 0) ~ " prop rpm, " ~ fmt(fullStatic.T, 0) ~ " N (" ~ fmt(fullStatic.T / g, 1) ~ " kgf) thrust; no-load prop speed " ~
                    fmt(pr.nNoLoad * 60, 0) ~ " rpm, pitch speed " ~ fmt(pr.pd * pr.D * pr.nNoLoad * 3.6, 1) ~ " km/h");
                foilPrint(context, "foilPerfLog", "  cruise " ~ fmt(definition.vCruise, 1) ~ " km/h: thrust = drag " ~ fmt(propCr.T, 1) ~ " N (" ~ fmt(propCr.T / g, 2) ~ " kgf), " ~ fmt(propCr.rpm, 0) ~
                    " prop rpm, J " ~ fmt(propCr.J, 2) ~ ", prop efficiency " ~ fmt(propCr.eta0 * 100, 0) ~ "%, shaft " ~ fmt(propCr.Pshaft, 0) ~ " W, motor " ~ fmt(propCr.iMotor, 1) ~
                    " A, throttle " ~ fmt(propCr.throttle * 100, 0) ~ "%, battery " ~ fmt(propCr.iBatt, 1) ~ " A / " ~ fmt(propCr.pBatt, 0) ~ " W, overall " ~
                    fmt(propCr.T * definition.vCruise / 3.6 / propCr.pBatt * 100, 0) ~ "%");
                foilPrint(context, "foilPerfLog", "  " ~ fmt(propCr.whKm, 1) ~ " Wh/km, range " ~ fmt(propCr.range, 1) ~ " km / " ~ fmt(propCr.range / definition.vCruise * 60, 0) ~ " min powered at cruise" ~
                    (assist != undefined && assist.outOk ? " (pump/wave riding with the pod out draws nothing, so a mixed session goes further)" : "") ~ "; top speed " ~
                    (vTop < 0 ? "over 100 km/h" : (vTop == 0 ? "below take-off (full power cannot hold it)" : fmt(vTop, 1) ~ " km/h (full-power thrust = drag)")));
                if (pctx.powered)
                {
                    foilPrint(context, "foilPerfLog", "  thrust vector: pod tilt " ~ fmt(ctx.podTilt * 180 / PI, 1) ~ " deg nose-down, so at cruise it points " ~ fmt(pPw.thrustAngle, 1) ~
                        " deg to the flow (" ~ fmt(pPw.Tz, 1) ~ " N vertical at the pod, " ~ fmt(-pPw.Tz * ctx.podX, 1) ~ " Nm about the pivot); at take-off " ~
                        fmt(trimPoint(pctx, definition.vTakeoff / 3.6).thrustAngle, 1) ~ " deg, " ~ fmt(trimPoint(pctx, definition.vTakeoff / 3.6).Tz, 1) ~ " N");
                    foilPrint(context, "foilPerfLog", "  thrust line at the pod axis, Z " ~ fmt(ctx.podZ * 1000, 0) ~ " mm; drag centroid at cruise Z " ~ fmt((pPw.Mthrust + pPw.D * ctx.podZ) / pPw.D * 1000, 0) ~
                        " mm -> couple " ~ fmt(pPw.Mthrust, 1) ~ " Nm (" ~ (pPw.Mthrust < 0 ? "nose down" : "nose up") ~ "), a pure couple so the CG height does not matter; trim CG " ~
                        fmt(pCr.xcg * 1000, 1) ~ " -> " ~ fmt(pPw.xcg * 1000, 1) ~ " mm" ~ (ctx.hasStab ? ", static margin " ~ fmt((xnp - pCr.xcg) / macW * 100, 1) ~ " -> " ~
                        fmt((xnp - pPw.xcg) / macW * 100, 1) ~ "% MAC" ~ (smPwMin < 1e8 ? "; lowest under power " ~ fmt(smPwMin, 1) ~ "% at " ~ fmt(smPwMinV, 1) ~ " km/h" : "") : ""));
                }
                else
                    foilPrint(context, "foilPerfLog", "  no motor pod on Foil mast, so the thrust line height is unknown - thrust couple not in trim (enter it in Pitch Nm)");
                if (propCr.tip > 25)
                    foilPrint(context, "foilPerfLog", "  NOTE: tip speed " ~ fmt(propCr.tip, 1) ~ " m/s at cruise - expect ventilation and noise near the surface");
                foilPrint(context, "foilPerfLog", "  not modelled: ploughing before lift-off, cavitation/ventilation of the prop, pod and mast wake, acceleration (thrust above drag), and the prop's efficiency loss in oblique inflow (its axis is off the flow by thrust_angle_deg)");
            }
            foilPrint(context, "foilPerfLog", "");
            foilPrint(context, "foilPerfLog", "speed_kmh,alpha_deg,CL_wing,CL_stab,Re_wing_M,drag_N,drag_induced_N,drag_profile_N,L_D,power_W,trim_cg_mm,static_margin_pct,max_local_cl_pct,drag_mast_N,drag_body_N" ~
                (propCr != undefined ? ",thrust_N,prop_rpm,J,eta_prop_pct,motor_A,throttle_pct,batt_A,batt_W,Wh_per_km,max_thrust_N,in_limits,thrust_couple_Nm,thrust_angle_deg,thrust_vert_N,trim_cg_powered_mm,static_margin_powered_pct" : ""));
            var v = definition.vTakeoff;
            while (v <= definition.vMax + 1e-9)
            {
                const p = trimPoint(ctx, v / 3.6);
                var row = fmt(v, 1) ~ "," ~ fmt(p.alpha * 180 / PI, 2) ~ "," ~ fmt(p.CLw, 3) ~ "," ~ fmt(p.CLs, 3) ~ "," ~ fmt(p.Re / 1e6, 3) ~ "," ~
                    fmt(p.D, 1) ~ "," ~ fmt(p.Di, 1) ~ "," ~ fmt(p.D - p.Di - p.Dmast - p.Dbody, 1) ~ "," ~ fmt(p.LD, 2) ~ "," ~ fmt(p.P, 0) ~ "," ~
                    (ctx.hasStab ? fmt(p.xcg * 1000, 1) ~ "," ~ fmt((xnp - p.xcg) / macW * 100, 1) : ",") ~ "," ~
                    fmt(maxLocalClRatio(wing, Lw, p.alpha, clMaxWing, clMaxTip) * 100, 0) ~ "," ~ fmt(p.Dmast, 1) ~ "," ~ fmt(p.Dbody, 1);
                if (propCr != undefined)
                {
                    // thrust = drag at the powered ride depth, which differs from drag_N when that is the pod-in depth
                    const pp = trimPoint(pctx, v / 3.6);
                    const Tp = pp.T;
                    const o = propOperate(pr, v / 3.6, Tp);
                    row = row ~ "," ~ fmt(Tp, 1) ~ "," ~ fmt(o.rpm, 0) ~ "," ~ fmt(o.J, 3) ~ "," ~ fmt(o.eta0 * 100, 1) ~ "," ~ fmt(o.iMotor, 1) ~ "," ~
                        fmt(o.throttle * 100, 0) ~ "," ~ fmt(o.iBatt, 1) ~ "," ~ fmt(o.pBatt, 0) ~ "," ~ fmt(o.whKm, 1) ~ "," ~
                        fmt(propFullPower(pr, v / 3.6).T, 1) ~ "," ~ (o.ok ? "1" : "0") ~ "," ~ fmt(pp.Mthrust, 1) ~ "," ~ fmt(pp.thrustAngle, 1) ~ "," ~ fmt(pp.Tz, 1) ~ "," ~ fmt(pp.xcg * 1000, 1) ~ "," ~
                        (ctx.hasStab ? fmt((xnp - pp.xcg) / macW * 100, 1) : "");
                }
                foilPrint(context, "foilPerfLog", row);
                v += definition.vStep;
            }
            foilPrint(context, "foilPerfLog", "===== END =====");
        }
    });

export enum MoldKeyStyle
{
    annotation { "Name" : "Printed keys" }
    PRINTED,
    annotation { "Name" : "Dowel holes" }
    DOWEL
}

export enum TileJoint
{
    annotation { "Name" : "Dowels" }
    DOWELS,
    annotation { "Name" : "Puzzle inlay" }
    PUZZLE
}

export enum MastTaper
{
    annotation { "Name" : "Symmetric" }
    SYMMETRIC,
    annotation { "Name" : "Straight leading edge" }
    LEADING,
    annotation { "Name" : "Straight trailing edge" }
    TRAILING
}

export enum MoldOf
{
    annotation { "Name" : "The part" }
    PART,
    annotation { "Name" : "Its foam core" }
    CORE
}

export enum CoreMake
{
    annotation { "Name" : "Molded" }
    MOLDED,
    annotation { "Name" : "Milled" }
    MILLED
}

export enum MoldEjector
{
    annotation { "Name" : "Off" }
    OFF,
    annotation { "Name" : "Dowel holes (wax-filled)" }
    DOWEL,
    annotation { "Name" : "Printed flush plugs" }
    PLUG
}

export enum MoldClosing
{
    annotation { "Name" : "Clamps against a board" }
    CLAMPS,
    annotation { "Name" : "Vacuum bag round the mold" }
    BAG
}

export enum MoldSource
{
    annotation { "Name" : "Wing" }
    WING,
    annotation { "Name" : "Stabiliser" }
    STAB,
    annotation { "Name" : "Mast" }
    MAST,
    annotation { "Name" : "Fuselage" }
    FUSELAGE
}

annotation { "Feature Type Name" : "Foil mold",
             "Feature Type Description" : "Printable molds for a Foil wing, stabiliser or mast: two shells parted along each section's camber line so they release (three parts for the mast, with a plate tray), with locator keys, a pinch-off groove, plugs, undersized bolt cones, and tiles sized to your printer bed. Also works out the layup from the part (woven skins, UD caps with a cut list, tow, resin, what to buy), checks stiffness and strength, and can cut a template plate of every fabric shape for DXF export. One instance per part." }
export const foilMold = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Group Name" : "Part", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Part",
                         "Filter" : EntityType.BODY && BodyType.SOLID,
                         "MaxNumberOfPicks" : 1,
                         "Description" : "The wing or stabiliser solid to mold (the whole body, tube socket or mount pad included). One Foil mold per component - add a separate instance for the wing and for the stab." }
            definition.part is Query;

            annotation { "Name" : "Source model",
                         "Description" : "Which feature built Part; it must match the body selected above. Wing / Stabiliser: the parting follows that feature's own planform, twist, droop and section. Fuselage (build 213): parted top and bottom along its sections' mid-height, the profile the Foil fuselage publishes, so the mast pocket is a core on the upper half and the tongue a pocket in the lower; the vertical bolt holes (the hub's, countersinks included, and the stab's) are filled in the cavity - drill and countersink after cure; no caps, stiffness check or templates. Mast: laid flat 400 mm below the origin, parting on its mid-plane, three parts (left, right and a tray for the plate); the plate and the motor pod are molded with it, the pod with a plug from its cavity. Cavities and the tray are cut from the part as it stands, so direct edits above this feature are followed; only the bolt pins stay on the Foil mast's pattern." }
            definition.moldSource is MoldSource;

            annotation { "Name" : "Detail", "Default" : "PRINT",
                         "Description" : "Print: everything for the printer - groove and vents, tile seams and keys, printed-core segments, the template plate. Preview: only the two halves with the cavity, parting, plug and cones, one tile each, so a studio with molds regenerates in a fraction of the time while the wing and the joint are still being designed; the layup, stiffness and closing numbers are still reported and the notice says PREVIEW. Switch to Print once for the STLs." }
            definition.detail is MoldDetail;

            annotation { "Name" : "Mold of", "Default" : "PART",
                         "Description" : "The part: the two halves form the part's outside, as always. Its foam core: needs Core = Foam core in the layup group; the feature first builds the core body itself - the part's sections offset inward by the skins, with a groove in each face where the UD caps run, so the finished core plus caps plus skins is the part - and then, by Core made, either molds THAT (the foam cast or shaped in a mold) or splits it into sections to mill from foam sheet, tabbed in frames for two-sided cutting. No socket plug, bolt cones or mount pad in a core mold. Add it as a second Foil mold on the same part; the molded core body is left as its own part for reference." }
            definition.moldOf is MoldOf;

            if (definition.moldOf == MoldOf.CORE)
            {
                annotation { "Name" : "Core made", "Default" : "MOLDED",
                             "Description" : "How the foam core is made. Molded: the core body plus a two-half mold of it, so the foam is cast or shaped in the mold (as before). Milled: no mold - the core body alone, split along the span into sections that fit Printer X / Y (the mill bed here) and Sheet thick with their droop and twist, optionally with tabs at its mid-height sticking out of the leading and trailing edges (Tabs per edge, spread along the section) to hold it in the stock while both faces are milled - the span ends stay clean for the glue joint, and the leading and trailing edges are sanded to shape once the tabs are cut: mill the top face, turn the stock over, mill the bottom face, cut the tabs. The stock itself is not modelled - set it in your CAM so the tabs reach it, or leave Hold tabs off and let the CAM hold the part its own way. Dowel holes cross every joint as for the printed core." }
                definition.coreMake is CoreMake;

                if (definition.coreMake == CoreMake.MILLED)
                {
                    annotation { "Name" : "Sheet thick",
                                 "Description" : "Thickness of the foam sheet the sections are milled from. Limits 5-100 mm. Each section is cut short enough to fit inside it, droop and twist included (more sections for a thinner sheet); the notice reports what the tallest section needs and warns when the sheet is still thinner. Typical 20-30 mm for a wing core, 10-15 for a stab." }
                    isLength(definition.sheetThick, { (millimeter) : [5, 25, 100] } as LengthBoundSpec);

                    annotation { "Name" : "Hold tabs", "Default" : true,
                                 "Description" : "Model the holding tabs on each section: Tabs per edge on the leading edge and as many on the trailing edge, spread along the section's length, at the section's mid-height, reaching Hold tab len out into the stock and Hold tab in into the foam. On the edges, not the span ends, so the joint faces the sections glue on stay clean; cut the tabs after the second side and sand the leading and trailing edges back to shape (at a thin trailing edge the tab stands proud of the surface). Off = plain sections; add the tabs in your CAM instead (most 2.5D and 3D CAM can hold a two-sided part with its own tabs or a fixture)." }
                    definition.coreTabsOn is boolean;

                    if (definition.coreTabsOn)
                    {
                        annotation { "Name" : "Tabs per edge",
                                     "Description" : "How many tabs along each edge of a section, spread evenly along its length (2 = at a quarter and three quarters). Limits 1-6. Typical 2; 3 or 4 on a long section or a soft foam, 1 on a short tip section." }
                        isInteger(definition.coreTabsPerEdge, { (unitless) : [1, 2, 6] } as IntegerBoundSpec);

                        annotation { "Name" : "Hold tab len",
                                     "Description" : "How far each tab reaches out from the leading or trailing edge into the stock. Limits 5-100 mm. Typical 20-30 mm: long enough to bridge the cutter's path round the section and sit in uncut stock. The bed check counts a tab length ahead of and behind the section." }
                        isLength(definition.coreTabLen, { (millimeter) : [5, 25, 100] } as LengthBoundSpec);

                        annotation { "Name" : "Hold tab in",
                                     "Description" : "How far each tab reaches into the section from its edge, so it is held by the foam and not just the edge. Limits 2-50 mm. Typical 10-15 mm; more at a thin trailing edge, where the bar stands proud until the edge is sanded, less if the cap groove must stay clear (the tabs sit at mid-height, below the grooves)." }
                        isLength(definition.coreTabIn, { (millimeter) : [2, 12, 50] } as LengthBoundSpec);

                        annotation { "Name" : "Hold tab wide",
                                     "Description" : "Width of the tabs along the span. Limits 3-30 mm. Typical 6-10 mm in foam." }
                        isLength(definition.coreTabWide, { (millimeter) : [3, 8, 30] } as LengthBoundSpec);

                        annotation { "Name" : "Hold tab thick",
                                     "Description" : "Thickness of the tabs, centred on the section's mid-height. Limits 1-10 mm. Typical 2-4 mm; where the section is thinner than this the tab stands proud and is sanded back after cutting." }
                        isLength(definition.coreTabThick, { (millimeter) : [1, 3, 10] } as LengthBoundSpec);
                    }
                }
            }

            annotation { "Name" : "Parts group", "Default" : "OFF",
                         "Description" : "Off (default): every mold piece is a normal part, named. Closed / Open collect everything this feature makes - shells, tiles, plugs, pins and the template plate - into one composite part named after the source (Wing mold, Stab mold, Mast mold). Closed: the parts list shows one expandable entry and the pieces live inside it (expand it to reach a tile; export from there). Open: the pieces stay listed as parts and the group appears under Composite parts, which is how Onshape treats open composites. Closed can hide every piece inside a group that is itself hidden, which is why the default is Off." }
            definition.partsGroup is PartsGroup;

            annotation { "Name" : "Split stations",
                         "Description" : "Spanwise stations used to build the parting surface, root to tip. Limits 5-80. Typical 15-25; 22 or more for a wing with a Tip profile (a surf wing with a NACA tip needed 22, and failed at 15); 40-80 for a tip with all its sweep and droop concentrated in the last fifth of the span (Sweep exp / Drop exp of 3-4), where the parting must turn sharply. Each station is a sketch and a ruled loft, so regeneration time grows with the count. Packed toward the tip by Tip bias." }
            isInteger(definition.splitStations, { (unitless) : [5, 15, 80] } as IntegerBoundSpec);

            annotation { "Name" : "Tip bias",
                         "Description" : "How strongly the stations crowd toward the tip: station i of n sits at span fraction 1 - (1 - i/n)^bias. Limits 1-4. Typical 2. 1 = evenly spaced; 2 = close to the cosine packing used before; 3-4 = most stations in the outer third, for planforms whose sweep and droop are concentrated there. Raise this before raising Split stations." }
            isReal(definition.tipBias, { (unitless) : [1, 2, 4] } as RealBoundSpec);
        }

        annotation { "Group Name" : "Mold body", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Flange width",
                         "Description" : "Mold material around the planform, from the part's edge to the outside of the block. Limits 10-60 mm. Typical 20-30 mm for a clamped printed mold: wide enough to seat clamps and a pinch-off groove, narrow enough not to waste print time. The parting surface runs out through the flange, so the two halves meet on it all the way round." }
            isLength(definition.flangeWidth, { (millimeter) : [10, 25, 60] } as LengthBoundSpec);

            annotation { "Name" : "Base thickness",
                         "Description" : "Mold material between the cavity and the outer (clamped) face of each half, measured at the deepest point. Limits 5-40 mm. Typical 15-25 mm for a printed mold clamped against a rigid board: enough not to flex between clamps or print through to the cavity, without a long print, and it is the layer the tile keys sit in (at least Pin dia + 4 mm and Key height + 4 mm). The slicer sets walls and infill; the body is solid here." }
            isLength(definition.baseThick, { (millimeter) : [5, 20, 40] } as LengthBoundSpec);

        }

        annotation { "Group Name" : "Socket", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Socket plug", "Default" : true,
                         "Description" : "Wing molds only, when the Foil wing has a Round tube socket or a Square socket on. The socket's bore is not molded by the halves (two half cores would leave a seam down the bore): the cavity is cut from the wing as modelled, the bore's core is severed from the halves by a channel behind the rear face and becomes the plug - the bore's own shape, direct edits included - on a handle Plug extension long in the channel. Both halves get a channel behind the nacelle's rear face that holds the plug coaxial when the mold is closed: half-round for the Round socket, for the Square socket the bore's rounded rectangle, its corner the bore's corner + Pin fit. Pull the plug after cure and drill the bolt holes to the wing's pattern. Off = the bore and bolt holes are molded as half cores (not recommended)." }
            definition.plugOn is boolean;

            annotation { "Name" : "Plug extension",
                         "Description" : "How far the plug reaches behind the nacelle's rear face into the channel in the flanges. Limits 10-60 mm, and at most Flange width - 3 mm. Typical 15-20 mm: enough to hold it square and to grip when pulling. Pin fit sets the channel clearance." }
            isLength(definition.plugExt, { (millimeter) : [10, 20, 60] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Bolt cones", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Bolt cones", "Default" : true,
                         "Description" : "Tapered cones in the bolt holes, wide at the face the bolt enters, ending Cone web short of the far face: each hole comes out undersized and on pattern and releases with its half; drill to size after cure. Stab: at each Mount bolt, from the countersunk face, the through hole filled so neither half molds a pin. Wing: the Flat hub's blind holes from the pocket floor in the upper half, or with Bolts from = Wing underside its through holes from the lower half's countersinks to Cone web under the floor, the holes filled; with Socket plug on, the socket's bolt shanks from their countersinks. Fuselage: every hole, from the face its bolt enters. Never the Flat mount's holes. Off: the stab's and the flat mount's holes mold as pins from both halves, the hub's from the upper half (both halves from the underside); the socket's shanks and the fuselage's holes are filled, to drill after cure." }
            definition.conesOn is boolean;

            if (definition.conesOn)
            {
                annotation { "Name" : "Cone dia",
                             "Description" : "Diameter of each cone at the pad face, the wide end. Limits 2-12 mm. Typical 4-5 mm for M6-M8, leaving 1.5-2 mm a side to drill out to clearance. Keep it below the fuselage's Stab bolt dia so the drilled hole cleans the molded surface." }
                isLength(definition.coneDia, { (millimeter) : [2, 5, 12] } as LengthBoundSpec);

                annotation { "Name" : "Cone taper",
                             "Description" : "Half-angle of the cone. Limits 2-15 deg. Typical 5-8 deg: enough draft to pull a clamped part off without levering, on a hole that will be drilled anyway." }
                isAngle(definition.coneTaper, { (degree) : [2, 6, 15] } as AngleBoundSpec);

                annotation { "Name" : "Cone web",
                             "Description" : "Laminate left between the cone tip and the top surface, so the cone never touches the upper half and the hole is closed by a thin web you drill through. Limits 0.5-5 mm. Typical 1-1.5 mm." }
                isLength(definition.coneWeb, { (millimeter) : [0.5, 1, 5] } as LengthBoundSpec);
            }
        }

        annotation { "Group Name" : "Pinch-off", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Pinch-off groove", "Default" : true,
                         "Description" : "A channel in the lower half's parting face running right round the cavity: a narrow land at the cavity edge where the closing mold pinches the laminate and squeezes the excess resin and fibre out, then a groove for that flash to run into. Follows the planform (leading edge, tips, trailing edge, the socket's nacelle) and the parting surface down the dropped tips. Off for a mold you will bag rather than clamp." }
            definition.grooveOn is boolean;

            if (definition.grooveOn)
            {
                annotation { "Name" : "Land width",
                             "Description" : "Flat land between the cavity edge and the groove. Limits 1-10 mm. Typical 2-4 mm: narrow enough to build real pinch pressure, wide enough to print cleanly and survive the clamps." }
                isLength(definition.landWidth, { (millimeter) : [1, 3, 10] } as LengthBoundSpec);

                annotation { "Name" : "Groove width",
                             "Description" : "Width of the flash groove. Limits 1-10 mm. Typical 3-5 mm." }
                isLength(definition.grooveWidth, { (millimeter) : [1, 4, 10] } as LengthBoundSpec);

                annotation { "Name" : "Groove depth",
                             "Description" : "Depth of the flash groove below the parting face. Limits 0.5-5 mm. Typical 1-2 mm for a clamped mold at 5 % overcharge; 3 mm with a 6 mm groove for a bagged mold, whose groove is also the vent path. The notice reports the groove's volume against the overcharge's flash and warns when it is too small." }
                isLength(definition.grooveDepth, { (millimeter) : [0.5, 1.5, 5] } as LengthBoundSpec);

                annotation { "Name" : "Land gap",
                             "Description" : "How far the land sits below the parting face (build 244, user: so glass or a skin can be laid over it). 0: the halves touch on the land and pinch whatever runs out of the cavity to nothing, the earlier behaviour. Above 0: the lower half's land is lowered by this much, so the skin or a glass ply carried out of the cavity across the land is squeezed to this thickness instead of cut, and the halves bear on the flange outside the groove. Limits 0-2 mm, and at least 0.2 mm under Groove depth. Typical 0.2-0.5: the cured thickness of the plies you carry over, about 0.22 mm per 200 gsm ply at 50 % fibre." }
                isLength(definition.landGap, { (millimeter) : [0, 0, 2] } as LengthBoundSpec);
            }
        }

        annotation { "Group Name" : "Closing", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Closing", "Default" : "CLAMPS",
                         "Description" : "How the closed mold is pressed shut while the resin cures. Clamps: G or F clamps on the flanges against a rigid board, the default, any force you like but concentrated at the clamp points. Vacuum bag: the whole closed mold, tiles glued, goes inside a bag with breather over it and the atmosphere clamps it, uniformly, with a closing force of the bag pressure times the block's plan area (about 5.7 kN on a stab mold, 14.5 kN on a 950 cm2 wing mold at 85 kPa) and a pressure on the laminate of that force over the part's plan area, 1.5-4 bar. With the bag: the block's outer edges are rounded so the bag is not cut, the pinch-off groove is vented to the outside at each span end so the bag can evacuate it (a sealed groove is a pocket of air the flash cannot enter), and Overcharge should drop to 3-5 %. Reported in the notice with the groove volume against the flash volume." }
            definition.closing is MoldClosing;

            if (definition.closing == MoldClosing.BAG)
            {
                annotation { "Name" : "Bag vacuum kPa",
                             "Description" : "Vacuum the pump holds in the bag, below atmospheric, in kPa. Limits 50-100. Typical 80-90 for a shop pump (100 kPa is a perfect vacuum, unreachable). Sets the closing force and the pressure on the laminate the notice reports." }
                isReal(definition.bagVac, { (unitless) : [50, 85, 100] } as RealBoundSpec);

                annotation { "Name" : "Groove vents", "Default" : true,
                             "Description" : "A 1 mm slot from the pinch-off groove out through the flange to the block's outer face at each span end, in the lower half, as deep as the groove. Inside a bag the groove is otherwise a sealed pocket of air at atmospheric pressure, so the flash cannot flow into it and the halves stop short; the vents let the bag evacuate the groove, and the laminate through it, before the resin gels. Needs the Pinch-off groove on." }
                definition.ventOn is boolean;

                annotation { "Name" : "Edge round",
                             "Description" : "Radius on the block's twelve outer edges so the bag wraps them without being cut. Limits 0-10 mm. Typical 4-6. 0 leaves them sharp (the tiles' joint faces and the parting face are never rounded). Not applied to the mast's plate tray." }
                isLength(definition.edgeRound, { (millimeter) : [0, 5, 10] } as LengthBoundSpec);
            }

            annotation { "Name" : "Pry sections", "Default" : true,
                         "Description" : "Short V pockets across the parting line on the block's outer faces, just big enough to start a wedge or a flat bar between the halves (build 242). Not at the corners and not the whole edge: one in the middle of every stretch between tile seams, so each tile of either half gets one on each face and none straddles a joint, and more at Pry spacing along a long stretch. Open the mold by working the wedges in alternately, a little at each, so the halves come apart square along the pull. Off: plain faces." }
            definition.pryOn is boolean;

            if (definition.pryOn)
            {
                annotation { "Name" : "Pry length",
                             "Description" : "Length of each pry section along the face. Limits 10-100 mm. Typical 25-40: room for a plastic wedge or a flat screwdriver, no more. Longer sections give less flange for the clamps." }
                isLength(definition.pryLength, { (millimeter) : [10, 30, 100] } as LengthBoundSpec);

                annotation { "Name" : "Pry depth",
                             "Description" : "How far each 45 deg pocket runs into each half from the face, so the V opens 2 x this across the parting. Limits 1-8 mm. Typical 3: a wedge's tip goes in 6 mm wide. Keep it well short of the keys and the pinch-off land." }
                isLength(definition.pryDepth, { (millimeter) : [1, 3, 8] } as LengthBoundSpec);

                annotation { "Name" : "Pry spacing",
                             "Description" : "Largest gap between pry sections along a stretch of face between two seams. Limits 60-600 mm. Typical 150. A tile shorter than this gets one, in its middle." }
                isLength(definition.prySpacing, { (millimeter) : [60, 150, 600] } as LengthBoundSpec);
            }

            annotation { "Name" : "Ejectors", "Default" : MoldEjector.DOWEL,
                         "Description" : "Holes through each half into the cavity so a part that stays in a half can be pushed out (build 243). Placed only where the part is solid and both faces are smooth, checked by rays: the wing or stab root zone either side of the joint, near each end of a mast, along a fuselage. Dowel holes: a plain hole of Ejector dia; fill it flush with filleting wax before the layup, tap a dowel in to push the part out (a small round witness). Printed flush plugs (build 245): a printed plug with its head on the cavity side, in a counterbore in the cavity face, the head's face cut from the cavity; drop it in from the cavity before the layup, the laminate's pressure seats it, a punch from outside pushes it and the part inward (a faint ring at the head). Off: none." }
            definition.ejector is MoldEjector;

            if (definition.ejector != MoldEjector.OFF)
            {
                annotation { "Name" : "Ejector dia",
                             "Description" : "Diameter of each ejector hole: a stock dowel's, or a printed plug's shank. Limits 3-12 mm. Typical 6. Bigger spreads the push over more laminate, but needs a wider smooth patch to land on." }
                isLength(definition.ejectorDia, { (millimeter) : [3, 6, 12] } as LengthBoundSpec);

                if (definition.ejector == MoldEjector.PLUG)
                {
                    annotation { "Name" : "Plug fit",
                                 "Description" : "Diametral clearance between a printed plug and its hole. Limits 0.05-0.5 mm. Typical 0.15 for PETG on a tuned printer: tight enough that resin does not run past it, loose enough to punch out. The plug's head, on the cavity side, is 4 mm wider than the shank and 2.5 mm deep, in a counterbore in the cavity face." }
                    isLength(definition.ejectorFit, { (millimeter) : [0.05, 0.15, 0.5] } as LengthBoundSpec);
                }
            }
        }

        annotation { "Group Name" : "Printer", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Printer X",
                         "Description" : "Build volume across the chord (tile width). Limits 50-1000 mm. Typical 200-300. The report shows how many tiles each half needs; a tile can be rotated on the bed, so enter the bed's shorter side here and its longer side as Printer Y." }
            isLength(definition.printerX, { (millimeter) : [50, 250, 1000] } as LengthBoundSpec);

            annotation { "Name" : "Printer Y",
                         "Description" : "Build volume along the span (tile length). Limits 50-1000 mm. Typical 200-300." }
            isLength(definition.printerY, { (millimeter) : [50, 250, 1000] } as LengthBoundSpec);

            annotation { "Name" : "Printer Z",
                         "Description" : "Build height. Limits 50-1000 mm. Typical 200-300. Each half is printed cavity-up, so this only has to clear the half's own height (cavity depth plus Base thickness)." }
            isLength(definition.printerZ, { (millimeter) : [50, 250, 1000] } as LengthBoundSpec);

            annotation { "Name" : "Tile margin",
                         "Description" : "Clearance kept between a tile and the printer's limits in every axis. Limits 0-30 mm. Typical 5 mm for brims, skirts and bed-edge adhesion." }
            isLength(definition.tileMargin, { (millimeter) : [0, 5, 30] } as LengthBoundSpec);

            annotation { "Name" : "Stagger joints", "Default" : true,
                         "Description" : "Offsets the upper half's spanwise cuts by half a tile from the lower half's, so no joint runs through both halves at the same place: the assembled mold braces itself and the seams never line up through the laminate. The upper half then has one extra tile (two half-length end tiles). Off = the same cuts in both halves." }
            definition.staggerJoints is boolean;
        }

        annotation { "Group Name" : "Joints", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Tile joint", "Default" : "DOWELS",
                         "Description" : "How the tiles of each half are joined across their seams (build 235). Dowels (every earlier build): printed keys or dowel holes in the tiles' end faces, in the base layer (Key style, Pin dia). Puzzle inlay: for molds milled on a 3-axis router, which cannot reach a tile's end face - a bow-tie pocket cut from the top into the parting-face flange on each side of the cavity, straddling every seam, with a key built as a part for each, to cut from flat sheet and glue in: it locks the tiles together, and since each pocket floor is milled the same depth below its own parting face, in the cavity's setup, it pulls the parting faces, and so the cavities, flush. A milled core (Core made = Milled) gets the same pockets on its top and bottom faces across every joint. The half keys are unchanged." }
            definition.tileJoint is TileJoint;

            if (definition.tileJoint == TileJoint.PUZZLE)
            {
                annotation { "Name" : "Inlay length",
                             "Description" : "Length of each bow-tie key across its seam, centred on it. Limits 10-80 mm. Typical 25-40; longer grips more of each tile. On a drooped wing the pocket's floor and its key tilt with the flange, and the pocket grows at its ends to let the square-edged key in (the notice gives the tilt and that allowance)." }
                isLength(definition.inlayLen, { (millimeter) : [10, 30, 80] } as LengthBoundSpec);

                annotation { "Name" : "Inlay width",
                             "Description" : "Width of the bow-tie at its two ends. Limits 5-40 mm. Typical 10-14; with 2 mm each side it must fit the flange left beyond the land and the groove (25 - 3 - 4 = 18 mm with the defaults), or that pocket is skipped with the Flange width it needs." }
                isLength(definition.inlayWidth, { (millimeter) : [5, 12, 40] } as LengthBoundSpec);

                annotation { "Name" : "Inlay waist",
                             "Description" : "Width of the bow-tie at the seam, its narrowest; at most Inlay width - 2 mm. Limits 2-38 mm. Typical half the Inlay width: the flanks' angle is what locks the tiles together, so a narrower waist locks harder but leaves less key across the seam." }
                isLength(definition.inlayWaist, { (millimeter) : [2, 6, 38] } as LengthBoundSpec);

                annotation { "Name" : "Inlay depth",
                             "Description" : "Depth of each pocket into its half, measured along the normal of the flange under it: the floor follows the flange (a plane fitted to it), the walls stay vertical. Limits 2-10 mm. Typical 4-6 in a mold. A milled core's pockets take this or 25 % of the core's thickness at the key, whichever is less, below a flat floor." }
                isLength(definition.inlayDepth, { (millimeter) : [2, 5, 10] } as LengthBoundSpec);

                annotation { "Name" : "Cutter dia",
                             "Description" : "Diameter of the end mill that cuts the pockets: it sets their inside corners' radius, and the keys' outside corners are rounded the same so they drop in; the keys keep the round it leaves in their waist, and the pockets' waist corners are rounded to clear it by the Glue gap. Limits 1-8 mm. Typical 3-4." }
                isLength(definition.inlayCutter, { (millimeter) : [1, 3, 8] } as LengthBoundSpec);

                annotation { "Name" : "Glue gap",
                             "Description" : "Gap each side between a key and its pocket, added to the pocket's outline. Limits 0-0.5 mm. Typical 0.1 for epoxy, 0 for a press fit." }
                isLength(definition.inlayGap, { (millimeter) : [0, 0.1, 0.5] } as LengthBoundSpec);

                if (definition.moldOf == MoldOf.CORE && definition.coreMake == CoreMake.MILLED)
                {
                    annotation { "Name" : "Sand allow",
                                 "Description" : "Milled core only: extra thickness on each key over its pocket's depth, so it stands proud of the core and is sanded to the core's profile after gluing. Limits 0-3 mm. Typical 1." }
                    isLength(definition.inlaySand, { (millimeter) : [0, 1, 3] } as LengthBoundSpec);
                }
                else
                {
                    annotation { "Name" : "Key flush",
                                 "Description" : "How far each key sits below the parting face, along the flange's normal: its thickness is Inlay depth less this, so a key can never stop the mold closing. Limits 0-1 mm. Typical 0.1-0.2." }
                    isLength(definition.inlayFlush, { (millimeter) : [0, 0.15, 1] } as LengthBoundSpec);
                }
            }

            annotation { "Name" : "Key style",
                         "Description" : "How tiles locate on each other and the halves on one another. Printed keys: a tapered round boss on one side of every joint and a matching socket on the other, printed with the mold - nothing to buy. Bosses always point +Y (span joints), +X (chord joints) and up from the lower half, so they print without support with the halves cavity-up. Dowel holes: a plain hole either side of every joint for a steel or wooden dowel. With Tile joint = Puzzle inlay it sets the half keys only." }
            definition.keyStyle is MoldKeyStyle;

            if (definition.tileJoint != TileJoint.PUZZLE)
            {
                annotation { "Name" : "Pin dia",
                             "Description" : "Diameter at the base of each tile-joint key (or the tile dowel). Limits 3-30 mm, and at most Base thickness - 4 mm (the keys sit in the base layer) and Flange width - 4 mm. Typical 10-16 mm for printed keys, 6-8 mm for steel dowels. Two per spanwise joint sit in the front and rear flanges; one per tile crosses each chordwise joint under the cavity. All of them sit in the base layer of each half, so none can break into the cavity." }
                isLength(definition.pinDia, { (millimeter) : [3, 12, 30] } as LengthBoundSpec);
            }

            annotation { "Name" : "Half keys", "Default" : true,
                         "Description" : "Registration between the two halves: a key (or dowel hole) through the parting surface in the front and rear flanges, one pair per spanwise tile a quarter tile in from the tile joint - clear of every cut and tile key in both halves. Printed keys stand up from the lower half into sockets in the upper. Off = the halves locate on the clamps and board alone." }
            definition.keysOn is boolean;

            annotation { "Name" : "Key dia",
                         "Description" : "Base diameter of the half-to-half keys (or dowel). Limits 3-30 mm, and at most Flange width - 4 mm. Typical 12-20 mm for printed keys, 6-8 mm for dowels." }
            isLength(definition.keyDia, { (millimeter) : [3, 14, 30] } as LengthBoundSpec);

            if (definition.keyStyle == MoldKeyStyle.PRINTED)
            {
                annotation { "Name" : "Key height",
                             "Description" : "Height of every printed boss above its face; the socket is 0.3 mm deeper so the boss bottoms on the joint face, not in the socket. Limits 2-25 mm, and at most Base thickness - 4 mm (the socket must not break through the other side). Typical 8-12 mm. Taller locates better but the tip must stay over 2 mm across (see Key draft)." }
                isLength(definition.keyHeight, { (millimeter) : [2, 8, 25] } as LengthBoundSpec);

                annotation { "Name" : "Key draft",
                             "Description" : "Taper of the boss sides, so it finds its socket as the parts come together. Limits 3-30 deg. Typical 10-15 deg. Tip diameter = base - 2 x height x tan(draft), and must stay over 2 mm." }
                isAngle(definition.keyDraft, { (degree) : [3, 12, 30] } as AngleBoundSpec);
            }
            else
            {
                if (definition.tileJoint != TileJoint.PUZZLE)
                {
                    annotation { "Name" : "Pin length",
                                 "Description" : "Total tile dowel length, half in each tile. Limits 10-60 mm. Typical 20-30 mm." }
                    isLength(definition.pinLen, { (millimeter) : [10, 24, 60] } as LengthBoundSpec);
                }

                annotation { "Name" : "Key length",
                             "Description" : "Total half-to-half dowel length, half in each half. Limits 8-40 mm, and at most 2 x (Base thickness - 3 mm) so the hole never breaks through the thinner half at a dropped tip. Typical 16-20 mm." }
                isLength(definition.keyLen, { (millimeter) : [8, 16, 40] } as LengthBoundSpec);
            }

            annotation { "Name" : "Pin fit",
                         "Description" : "Clearance added on the radius of every socket over its key, or to the hole diameter over the dowel. Limits 0-0.5 mm. Typical 0.15-0.25 mm for printed key in printed socket (add more if your printer prints holes small); 0.1-0.2 for a steel dowel." }
            isLength(definition.pinFit, { (millimeter) : [0, 0.2, 0.5] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Layup", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Skin plies",
                         "Description" : "Bidirectional (woven) plies on each face of the part, full planform, laid first against the mold. Limits 0-10. Typical 1-2 for a foil wing or stab, 2-3 for a mast. They give the surface finish and torsional stiffness; the UD caps and tow carry the bending. Sized from the part's own surface area." }
            isInteger(definition.skinPlies, { (unitless) : [0, 2, 10] } as IntegerBoundSpec);

            annotation { "Name" : "Skin gsm",
                         "Description" : "Areal weight of the woven skin cloth, g/m2. Limits 50-800. Typical 160-245 (2x2 twill), 100-200 for a fine finish. Cured ply thickness is derived from this and Fibre vol %: gsm / (1780 x Vf), which gives 0.22 mm for 200 gsm at 50 %." }
            isReal(definition.skinGsm, { (unitless) : [50, 200, 800] } as RealBoundSpec);

            annotation { "Name" : "UD gsm",
                         "Description" : "Areal weight of the unidirectional spar-cap fabric, g/m2. Limits 50-1200. Typical 200-300 wet layup, 150-300 prepreg, 400-600 for a thick root. Sets the cured UD ply thickness (gsm / (1780 x Vf)) and so the cap ply count." }
            isReal(definition.udGsm, { (unitless) : [50, 300, 1200] } as RealBoundSpec);

            annotation { "Name" : "Cap width %",
                         "Description" : "Width of the UD spar caps as % of local chord, centred on the section's thickest point. Limits 10-70 %. Typical 35-50 %. Wider caps move fibre from tow into UD, which is where bending strength comes from, at the cost of more UD to cut." }
            isReal(definition.capWidthPct, { (unitless) : [10, 40, 70] } as RealBoundSpec);

            annotation { "Name" : "Cap thick %",
                         "Description" : "Thickness of the two UD caps together (top + bottom) as % of the core thickness at the thickest point - the local section less both skins. Limits 0-100 %. Typical 50-70 %. The cap ply count follows the section taper, dropping plies along the span - the console prints the cut list, per cap: cut every UD template twice, one for each face. What the skins and caps do not fill is filled with tow, so fewer skin plies means more UD at the same %." }
            isReal(definition.capThickPct, { (unitless) : [0, 60, 100] } as RealBoundSpec);

            annotation { "Name" : "Core",
                         "Description" : "What fills the section between the skins and the UD caps. Tow fill: carbon roving laid along the span, wetted out, the whole part is laminate (the heaviest and stiffest fill). Foam core: a shaped structural foam (Corecell, PVC, PET) inside the skins and caps, the way most production wings are built - a third to a half lighter, and the caps and skins carry all the bending, so the stiffness check drops; a second Foil mold with Mold of = Its foam core makes it, molded or milled from sheet (Core made). Monolithic: woven plies fill the section, as on high-modulus production wings; same weight as tow, bought as cloth. Printed core: the same core shape as the foam core, 3D printed instead - this feature generates it as a part, split to your printer bed along the span, to be glued end to end and laid up in the part mold like a foam core; no core mold needed." }
            definition.coreType is CoreType;

            if (definition.coreType == CoreType.FOAM || definition.coreType == CoreType.PRINTED)
            {
                annotation { "Name" : "Core kg/m^3",
                             "Description" : "Density of the core as built. Limits 30-1300. Typical: foam 80-100 (Corecell M80 and PVC H80 about 85 and 80, PET 100-110), 60 for a light core in a big low-speed wing, 130-200 for a hard core under a mast plate. Printed: the print's average density, walls and infill together - PLA at 15 % gyroid with 2 walls is about 350-450, PETG similar, 1240 for solid PLA." }
                isReal(definition.coreDensity, { (unitless) : [30, 85, 1300] } as RealBoundSpec);

                annotation { "Name" : "Core GPa",
                             "Description" : "Modulus of the core along the span, for the stiffness check. Limits 0.02-5. Typical: foam 0.08-0.12 for an 80-100 kg/m^3 structural foam (Corecell M80 about 0.1), 0.2-0.3 at 200. Printed: about 0.5-1 for PLA at 15-20 % infill with walls, 3.5 solid; PETG 20 % lower. Small against carbon either way: the caps and skins do the work." }
                isReal(definition.coreModulus, { (unitless) : [0.02, 0.1, 5] } as RealBoundSpec);

                annotation { "Name" : "Core shear MPa",
                             "Description" : "Shear strength of the core, for the check of the shear it carries between the UD caps (wing, stab and mast). Limits 0-20 MPa. 0 (the default) estimates it from Core kg/m^3 as a PVC structural foam: about 1.15 at 80, 2.2 at 130 and 3.5 at 200. Enter the maker's figure for another foam (Corecell M80 about 1.0, PET 100 about 0.9). Typical: foam 1-3.5, a printed lattice unknown - it has no published figure: break a coupon of the same layup in three-point bending and enter what it gives; until then the estimate is only a placeholder." }
                isReal(definition.coreShear, { (unitless) : [0, 0, 20] } as RealBoundSpec);

                if (definition.moldSource == MoldSource.FUSELAGE)
                {
                    annotation { "Name" : "Core from mast",
                                 "Description" : "Fuselage only: the core starts this far behind the mast's trailing edge; everything ahead of it - the nose, the hub bolts, the mast pocket and the stretch the wing's twist and the mast's load pass through - is laid up solid woven (build 219, user). Limits 0-100 mm. Typical 15-30 (default 20). The core ends Core end gap ahead of the stab's seat block, which stays solid for the stab's bolts." }
                    isLength(definition.fusCoreFrom, { (millimeter) : [0, 20, 100] } as LengthBoundSpec);

                    annotation { "Name" : "Core end gap",
                                 "Description" : "Fuselage only: how far ahead of the stab's seat block the core stops, so the seat and its tapped holes are solid laminate. Limits 0-50 mm. Typical 5-10." }
                    isLength(definition.fusCoreGap, { (millimeter) : [0, 5, 50] } as LengthBoundSpec);

                    annotation { "Name" : "Tail UD MPa",
                                 "Description" : "Fuselage only: the working stress the UD strips on the tail core's top and bottom are sized to under the stab's lift at the load factor (Foil performance). Limits 100-600. Typical 250-350 (default 300, two thirds of UD's 450); lower for more plies and a stiffer tail. The ply count per station and the cut list come from it." }
                    isReal(definition.fusCapStress, { (unitless) : [100, 300, 600] } as RealBoundSpec);
                }

                annotation { "Name" : "Clear joint", "Default" : true,
                             "Description" : "Wing with a joint on (Round tube or Square socket, Flat hub or Flat mount): keep the core clear of it. On: the core is two halves starting Core clear outboard of the joint's half width - the nacelle's, the hub's, or for the Flat mount the bolt heads' radius + 3 mm or half the Mount pad's width, whichever is wider - and the root zone between them is solid laminate, counted in the layup. The core mold (Mold of = Its foam core) clears the same zone. Off: one core through the root as if there were no joint, which is what to choose when the joint is added by hand afterwards or the root is cut out on the bench; the core then occupies the joint's space in the model and the layup counts core where its wall or bolts will be. No effect without a joint." }
                definition.coreClearOn is boolean;

                annotation { "Name" : "Core clear",
                             "Description" : "With Clear joint on: the core stops this far outboard of the joint's half width on each side (the nacelle's, the hub's, or the Flat mount's bolt heads + 3 mm or half its pad, whichever is wider), and the root zone between the two core halves is solid laminate (counted in the layup as tow fill). Limits 0-100 mm. Typical 10-25: the joint and the laminate around it carry the fuselage's bending and the stab arm's moment into the wing, so nothing hollow belongs there. 0 stops the core at the joint's edge. No effect without a joint." }
                isLength(definition.coreClear, { (millimeter) : [0, 15, 100] } as LengthBoundSpec);
            }

            if (definition.coreType == CoreType.TOW)
            {
            annotation { "Name" : "Tow tex",
                         "Description" : "Linear density of the carbon tow (roving) that fills the lens core, leading and trailing edges and the socket nacelle, g/km. Limits 100-4000. Typical 800 (12k); 3k = 200, 24k = 1600 tex. Used only to turn the tow mass into a length to buy." }
            isReal(definition.towTex, { (unitless) : [100, 800, 4000] } as RealBoundSpec);
            }

            annotation { "Name" : "Fibre vol %",
                         "Description" : "Fibre volume fraction of the cured laminate. Limits 30-65 %. Typical 45-50 wet layup clamped in a matched mold, 55-60 vacuum-bagged or prepreg, 35-40 wet hand layup with no pressure. Sets the cured ply thicknesses and the split of the part's volume between carbon (1.78 g/cm3) and epoxy (1.15 g/cm3)." }
            isReal(definition.fibreVolPct, { (unitless) : [30, 50, 65] } as RealBoundSpec);

            annotation { "Name" : "Overcharge %",
                         "Description" : "Extra material laid over the exact cavity fill, as %. Limits 0-30 %. Typical 5-10 % for a clamped matched-die mold: closing under pressure squeezes the excess out as flash at the pinch-off, which is what packs the laminate void-free; 3-5 % with Closing = Vacuum bag, whose 1-4 bar closes to the land but cannot force much flash out. The notice compares the flash volume with what the groove holds. 0 for a loose vacuum bag. Scales the ply counts and every material figure." }
            isReal(definition.overchargePct, { (unitless) : [0, 8, 30] } as RealBoundSpec);

            annotation { "Name" : "Cloth waste %",
                         "Description" : "Cutting waste added to the woven and UD areas to buy. Limits 0-100 %. Typical 20-30 % (bias cuts, tapered UD plies, selvedge)." }
            isReal(definition.clothWastePct, { (unitless) : [0, 25, 100] } as RealBoundSpec);

            annotation { "Name" : "Resin waste %",
                         "Description" : "Resin mixed beyond what stays in the part: mixing-pot loss, wet-out of the tow, brushes, and the flash squeezed out at the pinch-off. Limits 0-150 %. Typical 30-50 % wet layup, 10 % prepreg (only the tow needs wetting)." }
            isReal(definition.resinWastePct, { (unitless) : [0, 40, 150] } as RealBoundSpec);

            annotation { "Name" : "Cap run-out",
                         "Description" : "Mast only. Length each UD cap ply runs past the plate's underside, folded outward over the root fillet onto the plate between its fill plies, so the cap's tension enters the plate by shear instead of peeling off the corner. Limits 0-100 mm. 0 = as far as the plate edge allows (2 mm short of it). Typical 30-50 mm; the stiffness line says how much the junction needs." }
            isLength(definition.capRunOut, { (millimeter) : [0, 0, 100] } as LengthBoundSpec);

            annotation { "Name" : "Tab plies",
                         "Description" : "Mast only. UD tab plies per face interleaved with the cap plies at the plate: each runs Tab length down the mast face and Cap run-out out over the plate, alternating with the caps so the two surfaces are stitched together through the stack rather than by one bond line. Limits 0-12. Typical 3-5. They take their thickness from the tow core over Tab length; the layup line warns if that core runs out." }
            isInteger(definition.tabPlies, { (unitless) : [0, 4, 12] } as IntegerBoundSpec);

            annotation { "Name" : "Tab length",
                         "Description" : "Mast only. How far each tab ply runs down the mast face from the plate. Limits 10-200 mm. Typical 40-80 mm, at least the Cap run-out." }
            isLength(definition.tabLength, { (millimeter) : [10, 50, 200] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Stiffness", "Collapsed By Default" : true }
        {
            annotation { "Name" : "UD GPa",
                         "Description" : "Tensile modulus of the cured UD carbon along the fibre. Limits 80-200. Typical 110-130 at 50 % fibre volume wet layup, 140-160 prepreg, 200+ for high-modulus fibre. Sets the spar caps' contribution to bending stiffness." }
            isReal(definition.udModulus, { (unitless) : [80, 120, 200] } as RealBoundSpec);

            annotation { "Name" : "Woven GPa",
                         "Description" : "In-plane modulus of the cured woven skin along the span. Limits 30-100. Typical 55-65 for a 0/90 twill at 50 % fibre volume; about 15 if the skin is laid at 45 deg, in which case it adds torsion, not bending." }
            isReal(definition.wovenModulus, { (unitless) : [30, 60, 100] } as RealBoundSpec);

            if (definition.coreType == CoreType.TOW)
            {
            annotation { "Name" : "Tow GPa",
                         "Description" : "Effective modulus of the tow-filled core along the span. Limits 10-80. Typical 30 for tow laid roughly along the span, 10 for chopped or random fill. A foam core uses Core GPa, a monolithic fill uses Woven GPa." }
            isReal(definition.towModulus, { (unitless) : [10, 30, 80] } as RealBoundSpec);
            }

            annotation { "Name" : "Mast side g",
                         "Description" : "Mast load case: a sideways force of this many times the all-up weight, applied at the fuselage end with the plate held by the board and rider, bending the mast about its chord - a hard carve or a fall. Limits 0.2-3. Typical 0.5-1. Reported as the deflection at the fuselage end and the UD cap stress at the plate, with the mast's own layup, taper and thickening; the moment peaks at the plate, which is why the top is thickened." }
            isReal(definition.mastSideG, { (unitless) : [0.2, 1, 3] } as RealBoundSpec);

            annotation { "Name" : "Shear allow",
                         "Description" : "Interlaminar shear strength of the cured laminate, MPa, for the junction check at the mast plate: the cap force at the plate divided by the bonded run-out area (the cap's plate face plus both faces of every tab ply) against this value with a factor of 2. Limits 10-80. Typical 25-35 wet layup, 50-70 prepreg. The line says the run-out the junction needs at this allowable." }
            isReal(definition.shearAllow, { (unitless) : [10, 30, 80] } as RealBoundSpec);
        }

        annotation { "Group Name" : "Cut templates", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Cut templates", "Default" : false,
                         "Description" : "Makes a flat 1 mm plate beside the mold with every fabric shape cut through it: the woven skin outline (the planform developed along the droop, cut once per skin ply per face) and one tapered strip per UD cap ply from the cut list (cut twice, one per face - the tally holes say so), each grown by Trim margin. Right-click the plate's top face in Onshape and Export as DXF to get every outline in one file for a cutter or a printed paper template. The console prints the order they appear in. Off = no plate." }
            definition.templatesOn is boolean;

            annotation { "Name" : "Trim margin",
                         "Description" : "Allowance added round every template outline, for trimming and for the fabric's own slack. Limits 0-20 mm. Typical 5 mm woven, 3-5 mm UD." }
            isLength(definition.tplMargin, { (millimeter) : [0, 5, 20] } as LengthBoundSpec);

            annotation { "Name" : "Template gap",
                         "Description" : "Space between neighbouring outlines on the plate. Limits 5-40 mm. Typical 10 mm." }
            isLength(definition.tplGap, { (millimeter) : [5, 10, 40] } as LengthBoundSpec);
        }

        annotation { "Name" : "Log inputs", "Default" : true,
                     "Description" : "Prints every parameter on this feature to the FeatureScript console as one line, so the whole set can be pasted elsewhere (e.g. back to an AI assistant) along with the notice." }
        definition.logInputs is boolean;
    }
    {
        const moldLogKey = "foilMoldLog_" ~ (definition.moldSource == MoldSource.WING ? "WING" : (definition.moldSource == MoldSource.STAB ? "STAB" : (definition.moldSource == MoldSource.FUSELAGE ? "FUSELAGE" : "MAST")));
        const moldNoticeKey = "foilMoldNotice_" ~ (definition.moldSource == MoldSource.WING ? "WING" : (definition.moldSource == MoldSource.STAB ? "STAB" : (definition.moldSource == MoldSource.FUSELAGE ? "FUSELAGE" : "MAST")));
        setVariable(context, moldLogKey, "");
        setVariable(context, moldNoticeKey, "");
        if (definition.logInputs)
            foilPrint(context, moldLogKey, moldInputLog(definition));
        // Detail = Preview (build 207): the halves, cavity, parting, plug and cones only. The groove,
        // vents, keys, stagger and templates are switched off here, the tiling is one tile per half
        // and the printed-core segments are skipped below; the layup and closing numbers still run
        const preview = definition.detail != undefined && definition.detail == MoldDetail.PREVIEW;
        // Tile joint = Puzzle inlay (build 235): bow-tie keys across the tile seams (and a milled core's
        // joints), cut from the top, instead of the tiles' dowels or printed keys; skipped in Preview
        const puzzle = definition.tileJoint != undefined && definition.tileJoint == TileJoint.PUZZLE;
        if (preview)
        {
            definition.grooveOn = false;
            definition.keysOn = false;
            definition.templatesOn = false;
            definition.ventOn = false;
            definition.staggerJoints = false;
        }

        const isMast = definition.moldSource == MoldSource.MAST;
        const isFus = definition.moldSource == MoldSource.FUSELAGE;
        const isFlat = isMast || isFus;                                  // laid on its side, flat parting on the symmetry plane
        const coreMold = definition.moldOf == MoldOf.CORE;
        if (coreMold && isMast)
            throw regenError("A core mold is for a wing, a stabiliser or a fuselage's tail core: the mast has no foam core", ["moldOf"]);
        if (coreMold && definition.coreType != CoreType.FOAM)
            throw regenError(definition.coreType == CoreType.PRINTED ? "A printed core is generated as a part by this feature and needs no mold: set Mold of back to The part" : "A core mold needs Core = Foam core in the layup group", ["moldOf", "coreType"]);
        // milled core (build 231): the core body split to the bed and tabbed in sheet frames, no mold
        const milledCore = coreMold && definition.coreMake != undefined && definition.coreMake == CoreMake.MILLED;
        if (milledCore && isFlat)
            throw regenError("A milled core is for a wing or a stabiliser: the fuselage's tail core is molded or printed (Core made = Molded)", ["coreMake"]);
        var m;
        var mastM;
        if (definition.moldSource == MoldSource.WING)
            try silent { m = getVariable(context, "foilWingModel"); }
        else if (definition.moldSource == MoldSource.STAB)
        {
            try silent { m = getVariable(context, "foilStabModel"); }
            // the stab's real pivot height: Seat on tube may have shifted the part after its model
            // was built, and foilStabHeight is the value the shift was applied to
            var hStab;
            try silent { hStab = getVariable(context, "foilStabHeight"); }
            if (m != undefined && hStab != undefined)
                m.baseZ = hStab / meter;
        }
        if (isMast || definition.moldSource == MoldSource.FUSELAGE)
            try silent { mastM = getVariable(context, "foilMastModel"); }
        var fusM;
        if (isFus)
            try silent { fusM = getVariable(context, "foilFuselageModel"); }
        if (m != undefined && m.wingletOn == 1 && m.wingletAngle > 75 * degree / radian)
            throw regenError("A winglet steeper than 75 deg cannot release from a two-part mold pulled vertically: reduce Winglet angle in the " ~
                (definition.moldSource == MoldSource.WING ? "Foil wing" : "Foil stabiliser") ~ " feature (it is " ~ fmt(m.wingletAngle * 180 / PI, 0) ~ " deg)", ["moldSource"]);
        if (isMast)
        {
            if (mastM == undefined)
                throw regenError("Source model not found - add a Foil mast feature above this one");
            if (mastM.plateLength == undefined)
                throw regenError("The Foil mast above is older than this Foil mold - paste the whole Feature Studio over again so both are the same build");
            if (mastM.podOn == 1 && mastM.cavDia == undefined)
                throw regenError("The Foil mast above is older than this Foil mold - paste the whole Feature Studio over again so both are the same build");
        }
        else if (isFus)
        {
            if (fusM == undefined)
                throw regenError("Source model not found - add a Foil fuselage feature above this one");
            if (fusM.stabBoltX == undefined)
                throw regenError("The Foil fuselage above is older than this Foil mold - paste the whole Feature Studio over again so both are the same build");
        }
        else
        {
            if (m == undefined)
                throw regenError("Source model not found - add a Foil wing or Foil stabiliser feature above this one, matching Source model");
            if (m.profileName == undefined)
                throw regenError("The Foil wing / Foil stabiliser above is older than this Foil mold - paste the whole Feature Studio over again so both are the same build");
        }
        var sock;
        var hub;
        var flat;
        if (definition.moldSource == MoldSource.WING || isFus)
        {
            try silent { sock = getVariable(context, "foilWingSocket"); }
            try silent { hub = getVariable(context, "foilWingHub"); }
            try silent { flat = getVariable(context, "foilWingFlat"); }
        }
        const flatOn = flat != undefined && flat.on == 1 && !coreMold && definition.moldSource == MoldSource.WING;
        const sockOn = sock != undefined && sock.on == 1 && !coreMold && definition.moldSource == MoldSource.WING;
        const hubOn = hub != undefined && hub.on == 1 && !coreMold && definition.moldSource == MoldSource.WING;
        // the socket's shape (build 194): square or round, the nacelle's real width and height, the
        // bore's real size (clearance included); older wings publish only the round numbers
        const sockSq = sock != undefined && sock.joint != undefined && sock.joint == "SQUARE";
        const nacW = sock != undefined && sock.on == 1 ? (sock.nacelleW != undefined ? sock.nacelleW : sock.nacelleDia) * meter : 0 * meter;
        // a faired socket's tail web reaches past the nacelle: the parting follows its law out to here (build 241)
        const sockReach = sock != undefined && sock.on == 1 && sock.web != undefined && sock.web.on == 1 ? sock.web.reach * meter : 0 * meter;
        const nacH = sock != undefined && sock.on == 1 ? (sock.nacelleH != undefined ? sock.nacelleH : sock.nacelleDia) * meter : 0 * meter;
        const bW = sock != undefined && sock.on == 1 ? (sock.boreW != undefined ? sock.boreW : sock.boreDia) * meter : 0 * meter;
        const bH = sock != undefined && sock.on == 1 ? (sock.boreH != undefined ? sock.boreH : sock.boreDia) * meter : 0 * meter;
        const bR = sock != undefined && sock.on == 1 && sock.boreR != undefined ? sock.boreR * meter : 0 * meter;   // the square bore's corner radius (build 196)
        // a foam or printed core keeps clear of the joint (core mold included): it starts at the
        // nacelle's, the hub's or the flat mount's half width + Core clear on each side, and the root
        // zone between is solid laminate. flatHere, not flatOn, which is off in a core mold (build 233:
        // the core mold built a core through a flat mount's root while the part mold counted two halves)
        const flatHere = flat != undefined && flat.on == 1 && definition.moldSource == MoldSource.WING;
        const sockHere = (sock != undefined && sock.on == 1 && definition.moldSource == MoldSource.WING) || (hub != undefined && hub.on == 1 && definition.moldSource == MoldSource.WING) || flatHere;
        const jointHalfW = hub != undefined && hub.on == 1 ? hub.width / 2 * meter : (flatHere ? max(flat.headDia / 2 * meter + 3 * millimeter, flat.padW != undefined ? flat.padW / 2 * meter : 0 * meter) : nacW / 2);   // the flat mount's pad (build 227) sets the clearance where it is wider than the heads
        const coreClearY = sockHere && definition.coreClearOn != false && (definition.coreType == CoreType.FOAM || definition.coreType == CoreType.PRINTED) ?
            jointHalfW + (definition.coreClear == undefined ? 15 * millimeter : definition.coreClear) : 0 * meter;
        const coreE0 = m != undefined && coreClearY > 0 * meter ? min(coreClearY / (m.span / 2 * meter), 0.5) : 0;
        var stabRoot;
        if (definition.moldSource == MoldSource.STAB || isFus)
            try silent { stabRoot = getVariable(context, "foilStabRoot"); }
        // the stab owns its bolt pattern (Mount bolts) and pad plane; the cones need both
        const conesOn = definition.conesOn == true && !coreMold && definition.moldSource == MoldSource.STAB && stabRoot != undefined && stabRoot.boltX != undefined
            && size(stabRoot.boltX) > 0 && stabRoot.boltDia != undefined && stabRoot.boltDia > 0;
        if (definition.conesOn == true && definition.moldSource == MoldSource.STAB && !conesOn)
            foilPrint(context, moldLogKey, "STAB_CONES: off - " ~
                (stabRoot == undefined ? "no foilStabRoot variable (no Foil stabiliser above)" :
                 (stabRoot.boltX == undefined ? "the Foil stabiliser above is older than this mold - paste the whole Feature Studio again" :
                  (size(stabRoot.boltX) == 0 ? "the stab has Stab bolts = 0 (Mount bolts group)" : "the stab's Bolt dia is 0"))));

        const capStartEta = isFlat ? 1 : (m.capOn == 1 ? max(0, 1 - m.capLength / (m.span / 2)) : 1);

        // ---------------- undercut check (spanwise droop only - see note in the notice) ----------------
        var dropCheck = "ok (droop is monotonic in +Z)";
        if (!isFlat)
        {
            const h = m.span / 2;
            const td = tan(m.rootDihedral * radian);
            var sign = 0;
            var flip = false;
            for (var i = 1; i <= 40; i += 1)
            {
                const eta = capStartEta * i / 40;
                const ps = dropSlope(m, eta);
                const slope = -m.tipDrop * ps + h * td * (1 - ps); // d(zOff)/d(eta), h cancels in sign only
                const s = slope > 1e-9 ? 1 : (slope < -1e-9 ? -1 : 0);
                if (sign != 0 && s != 0 && s != sign)
                    flip = true;
                if (s != 0)
                    sign = s;
            }
            dropCheck = flip
                ? "WARNING - spanwise droop reverses direction (gull): likely undercut in +Z, the halves will not release; reduce Root dihedral or Drop exponent"
                : "ok (droop is monotonic in +Z)";
        }

        // ---------------- layup: skins + UD caps + tow, sized from the part itself ----------------
        // The part's volume (evVolume) is the laminate volume; its surface area carries the woven
        // skins; the UD caps fill Cap thick % of the section over Cap width % of the chord; tow fills
        // the rest. Fibre vol % splits every volume into carbon and epoxy. Evaluated on the original
        // part before any mold operation so the queries are fresh.
        const rhoF = 1.78;   // g/cm3 carbon fibre
        const rhoR = 1.15;   // g/cm3 cured epoxy
        const vf = definition.fibreVolPct / 100;
        const over = 1 + definition.overchargePct / 100;
        const tSkin = definition.skinGsm / (rhoF * 1e6 * vf) * 1000;    // mm cured ply
        const tUd = definition.udGsm / (rhoF * 1e6 * vf) * 1000;        // mm cured ply
        const partVol = evVolume(context, { "entities" : definition.part }) / (centimeter * centimeter * centimeter);   // cm3
        const partArea = evArea(context, { "entities" : qOwnedByBody(definition.part, EntityType.FACE) }) / (meter * meter); // m2
        // UD caps: cap thickness = Cap thick % of the local section thickness, over Cap width % of chord
        const capW = definition.capWidthPct / 100;
        const capF = definition.capThickPct / 100;
        const tSkins = 2 * definition.skinPlies * tSkin;                     // mm taken by the skins, both faces
        // mast plate: a solid block filled with woven plies between its skins (the usual hand-layup
        // choice - the tracks load it both ways, so UD would be stiff one way only); counted with the
        // skins, so it comes out of the tow. Build 117 left the whole plate as tow with no cut count
        var plateFill = 0;                                                    // woven plies inside the plate
        var plateArea = 0;                                                    // m2, one ply
        // the plate as modelled: measured off the part (a copy split at the plate's underside), so a
        // plate the user has edited by hand above this feature - fillets, chamfers, another outline, a
        // thicker plate - is what the tray, the fill count and the template follow (user). Nominal
        // numbers from the Foil mast if the measurement fails
        var plateAct;
        if (isMast && mastM.plateLength != undefined)
        {
            plateAct = moldPlateMeasure(context, id + "plateMeasure", definition.part, mastM);
            const tP = plateAct != undefined ? (plateAct.zBoard - plateAct.zTop) / millimeter : mastM.plateThick * 1000;
            plateFill = max(0, round((tP - tSkins) / tSkin));
            plateArea = plateAct != undefined ? (plateAct.x1 - plateAct.x0) * (plateAct.y1 - plateAct.y0) / (meter * meter) : mastM.plateLength * mastM.plateWidth;
            const nomL = mastM.plateLength * 1000;
            const nomW = mastM.plateWidth * 1000;
            const nomT = mastM.plateThick * 1000;
            if (plateAct == undefined)
                foilPrint(context, moldLogKey, "MAST_PLATE: could not measure the plate off the part - the tray uses the Foil mast's " ~ fmt(nomL, 1) ~ " x " ~ fmt(nomW, 1) ~ " x " ~ fmt(nomT, 1) ~ " mm");
            else
            {
                const mL = (plateAct.x1 - plateAct.x0) / millimeter;
                const mW = (plateAct.y1 - plateAct.y0) / millimeter;
                const edited = abs(mL - nomL) > 0.2 || abs(mW - nomW) > 0.2 || abs(tP - nomT) > 0.2;
                foilPrint(context, moldLogKey, "MAST_PLATE: measured off the part " ~ fmt(mL, 1) ~ " x " ~ fmt(mW, 1) ~ " x " ~ fmt(tP, 1) ~ " mm (Foil mast: " ~ fmt(nomL, 1) ~ " x " ~ fmt(nomW, 1) ~ " x " ~ fmt(nomT, 1) ~ ")" ~
                    (edited ? " - direct edits found, the tray follows the part" : ""));
            }
        }
        const skinArea = partArea * definition.skinPlies + plateArea * plateFill;   // m2 of cloth laid
        const skinVol = skinArea * tSkin / 1000 * 1e6;                      // cm3
        // the caps fill Cap thick % of the CORE inside the skins, so the skin count changes the UD
        // count and skins + caps can never exceed the section (build 114 measured against the whole
        // section, so halving the skins left the UD count unchanged - user)
        var fusCore;             // fuselage: the tail-core plan (build 219), numbers in SI
        var fusCoreWhy = "";
        var capVol = 0;          // cm3
        var capPliesRoot = 0;
        var capPliesTip = 0;
        var capLen = 0;          // m, one cap from root to the cap start (mast: its height)
        var capCut = "";         // console cut list
        var tplEnds = [];        // per UD ply: the last station index it reaches (wing / stab)
        var tplCAt = [];         // chord per station, mm, for the templates and the stiffness check
        var tplTAt = [];         // section thickness per station, mm
        var runOut = 0;          // mm, mast: cap run-out onto the plate
        var tabN = 0;            // mast: tab plies per face
        var tabLen = 0;          // mm, mast: tab length down the mast
        var tabNote = "";
        if (isMast)
        {
            // stations from the plate (s = 1, the thick end and the peak moment) down to the fuselage
            // end (s = 0), so the cut list reads like the wing's: ply k runs from the plate to the last
            // station still k plies thick per cap; the thickened top adds short plies at the plate end
            const nS = 40;
            const cTopM = mastM.chordTop != undefined ? mastM.chordTop : mastM.chord;
            const tTopM = mastM.thickTop != undefined ? mastM.thickTop : mastM.thick;
            const s0M = mastM.thickenFrom != undefined ? mastM.thickenFrom : 1;
            var tAt = makeArray(nS + 1);                                      // section thickness, mm
            var cAt = makeArray(nS + 1);                                      // chord, mm
            for (var i = 0; i <= nS; i += 1)
            {
                const sF = 1 - i / nS;
                const uM = s0M >= 1 ? 0 : min(max((sF - s0M) / (1 - s0M), 0), 1);
                cAt[i] = (mastM.chord + (cTopM - mastM.chord) * sF) * 1000;
                tAt[i] = (mastM.thick + (tTopM - mastM.thick) * uM * uM * (3 - 2 * uM)) * 1000;
                if (i > 0)
                    capVol += capW * (cAt[i] + cAt[i - 1]) / 2 * capF * max((tAt[i] + tAt[i - 1]) / 2 - tSkins, 0) * (mastM.height * 1000 / nS) / 1000;   // mm3 -> cm3
            }
            capPliesRoot = round(capF * max(tAt[0] - tSkins, 0) / 2 * over / tUd);
            capPliesTip = round(capF * max(tAt[nS] - tSkins, 0) / 2 * over / tUd);
            capLen = mastM.height;
            // junction: every cap ply runs out over the root fillet onto the plate (Cap run-out, or to
            // 2 mm short of the plate edge), and Tab plies per face of UD interleave with the caps,
            // Tab length down the mast and the same run-out out over the plate (user: alternating
            // layers of UD to tab the two surfaces together). Both displace tow / plate fill
            const roomOut = mastM.plateWidth != undefined ? max((mastM.plateWidth - tTopM) / 2 * 1000 - 2, 0) : 0;
            runOut = definition.capRunOut > 0 ? min(definition.capRunOut / millimeter, roomOut) : roomOut;
            tabN = definition.tabPlies;
            tabLen = definition.tabLength / millimeter;
            const wPl = capW * cAt[0];                                        // mm, cap width at the plate
            capVol += 2 * capPliesRoot * runOut * wPl * tUd / 1000;           // cap run-outs, both faces, cm3
            capVol += 2 * tabN * (runOut + tabLen) * wPl * tUd / 1000;        // tabs, both faces, cm3
            const coreP = max(tAt[0] - tSkins, 0) * (1 - capF);               // mm of tow core at the plate
            if (tabN > 0)
            {
                tabNote = " | tabs " ~ tabN ~ " per face x " ~ fmt(runOut + tabLen, 0) ~ " x " ~ fmt(wPl, 0) ~ " mm UD, fold at " ~ fmt(runOut, 0) ~ " mm, one after every " ~
                    max(1, ceil(capPliesRoot / tabN)) ~ " cap plies; they take " ~ fmt(2 * tabN * tUd, 1) ~ " mm of the " ~ fmt(coreP, 1) ~ " mm tow core at the plate over " ~ fmt(tabLen, 0) ~ " mm" ~
                    (2 * tabN * tUd > coreP ? " - MORE THAN THE CORE: fewer Tab plies or a thicker Top thick" : "");
            }
            capCut = "UD_CAP_PLIES (per cap, cut 2 - one for each face; outermost first; length from the plate down PLUS " ~ fmt(runOut, 0) ~ " mm run-out folded over the fillet onto the plate - fold at " ~ fmt(runOut, 0) ~ " mm from the plate end; width at the plate / at the end): ply,length_mm,width_plate_mm,width_end_mm";
            for (var k = 1; k <= capPliesRoot; k += 1)
            {
                var iEnd = 0;
                for (var i = 0; i <= nS; i += 1)
                    if (capF * max(tAt[i] - tSkins, 0) / 2 * over / tUd >= k - 0.5)
                        iEnd = i;
                iEnd = max(iEnd, 1);
                capCut = capCut ~ "\n" ~ k ~ "," ~ fmt(iEnd / nS * mastM.height * 1000 + runOut, 0) ~ "," ~ fmt(wPl, 0) ~ "," ~ fmt(capW * cAt[iEnd], 0);
                tplEnds = append(tplEnds, iEnd);
            }
            if (tabN > 0)
                capCut = capCut ~ "\nUD_TABS: " ~ tabN ~ " per face (cut " ~ 2 * tabN ~ ") x " ~ fmt(runOut + tabLen, 0) ~ " mm x " ~ fmt(wPl, 0) ~ " mm, fold at " ~ fmt(runOut, 0) ~ " mm (plate leg), " ~ fmt(tabLen, 0) ~ " mm down the mast; lay one after every " ~ max(1, ceil(capPliesRoot / tabN)) ~ " cap plies, outermost first";
            tplCAt = cAt;
            tplTAt = tAt;
        }
        else if (isFus)
        {
            // tail core (build 219): foam or printed from Core from mast behind the mast to Core end
            // gap ahead of the seat, the rest solid woven; UD strips top and bottom over the core,
            // sized from the stab's lift at n g to Tail UD MPa
            if (definition.coreType == CoreType.FOAM || definition.coreType == CoreType.PRINTED)
            {
                var loadsC;
                try silent { loadsC = getVariable(context, "foilStabLoads"); }
                var FsC = 0;
                var xStC = fusM.seatX0 != undefined ? fusM.seatX0 : 0;
                if (loadsC != undefined && loadsC.halfLift != undefined)
                    FsC = 2 * loadsC.halfLift;
                if (fusM.stabBoltX != undefined && size(fusM.stabBoltX) > 0)
                {
                    xStC = 0;
                    for (var b in fusM.stabBoltX)
                        xStC += b / size(fusM.stabBoltX);
                }
                if (fusM.seatX0 == undefined || fusM.stations == undefined || fusM.partZ == undefined)
                    fusCoreWhy = "the Foil fuselage above is older than this mold (no seat or stations) - paste the whole Feature Studio again; laid up solid";
                else
                {
                    fusCore = fusCorePlan(fusM, mastM, definition, definition.skinPlies * tSkin / 1000, tUd / 1000, FsC, xStC);
                    if (!fusCore.ok)
                    {
                        fusCoreWhy = fusCore.why;
                        fusCore = undefined;
                    }
                    else if (FsC <= 0)
                        fusCoreWhy = "no Foil performance above: the UD strips are the 1-ply minimum, not sized to a load";
                }
            }
            if (fusCore != undefined)
            {
                capVol = fusCore.capVol;
                capPliesRoot = fusCore.nMax;
                capPliesTip = fusCore.nMin;
                capLen = fusCore.x1 - fusCore.x0;
                capCut = "UD_CAP_PLIES (fuselage tail core, one strip on its top and one on its bottom, cut 2 of each; outermost first; from " ~ fmt(fusCore.x0 * 1000, 0) ~ " mm, the mast end, aft; width at the start / at the end): ply,length_mm,width_start_mm,width_end_mm";
                for (var k = 0; k < size(fusCore.plyLen); k += 1)
                    capCut = capCut ~ "\n" ~ (k + 1) ~ "," ~ fmt(fusCore.plyLen[k] * 1000, 0) ~ "," ~ fmt(fusCore.wcs[0] * 1000, 0) ~ "," ~ fmt(fusCore.plyW1[k] * 1000, 0);
            }
            else
                capCut = "UD_CAP_PLIES: none - the fuselage is laid up as skins and solid fill" ~ (fusCoreWhy != "" ? " (" ~ fusCoreWhy ~ ")" : "");
        }
        else
        {
            const nS = 40;
            const halves = m.mirror == 1 ? 2 : 1;
            const dy = capStartEta * m.span / 2 / nS;                        // m per station, one half
            var tAt = makeArray(nS + 1);                                      // local section thickness, mm
            var cAt = makeArray(nS + 1);                                      // local chord, mm
            for (var i = 0; i <= nS; i += 1)
            {
                const eta = capStartEta * i / nS;
                const chord = m.c0 * chordFactor(m, eta);
                const thickFrac = m.rootT + (m.tipT - m.rootT) * eta ^ m.thicknessExp;
                cAt[i] = chord * 1000;
                // the part keeps its depth where a tail stretches the chord (buildFoil), so the depth
                // is the fraction of the chord without the tail (build 226)
                tAt[i] = thickFrac * (chord - m.c0 * tailFactor(m, eta)) * 1000;
                if (i < nS)
                {
                    const etaM = capStartEta * (i + 0.5) / nS;
                    const cM = m.c0 * chordFactor(m, etaM);
                    const tM = (m.rootT + (m.tipT - m.rootT) * etaM ^ m.thicknessExp) * (cM - m.c0 * tailFactor(m, etaM));
                    capVol += capW * cM * capF * max(tM - tSkins / 1000, 0) * dy * 1e6 * halves;
                }
            }
            // nearest-ply rounding: ply k covers the span where the stack is at least k - 0.5 plies
            // thick, so the innermost ply is never a zero-length line (ceil gave one on build 79)
            capPliesRoot = round(capF * max(tAt[0] - tSkins, 0) / 2 * over / tUd);
            capPliesTip = round(capF * max(tAt[nS] - tSkins, 0) / 2 * over / tUd);
            capLen = capStartEta * m.span / 2 * halves;
            // cut list: ply k (outermost first) runs out to the last station still k plies thick; a
            // mirrored foil's cap is one piece across the root, so its length is both halves
            capCut = "UD_CAP_PLIES (per cap, cut 2 - one for each face; outermost first; length root-to-root" ~ (halves == 2 ? " across the centre" : "") ~ ", width at root / at the end): ply,length_mm,width_root_mm,width_end_mm";
            for (var k = 1; k <= capPliesRoot; k += 1)
            {
                var iEnd = 0;
                for (var i = 0; i <= nS; i += 1)
                    if (capF * max(tAt[i] - tSkins, 0) / 2 * over / tUd >= k - 0.5)
                        iEnd = i;
                iEnd = max(iEnd, 1);
                const len = capStartEta * iEnd / nS * m.span / 2 * halves * 1000;
                capCut = capCut ~ "\n" ~ k ~ "," ~ fmt(len, 0) ~ "," ~ fmt(capW * cAt[0], 0) ~ "," ~ fmt(capW * cAt[iEnd], 0);
                tplEnds = append(tplEnds, iEnd);
            }
            tplCAt = cAt;
            tplTAt = tAt;
        }
        foilPrint(context, moldLogKey, capCut);
        var towVol = partVol - skinVol - capVol;                             // cm3
        var towNote = "";
        if (towVol < 0)
        {
            towNote = "skins + UD caps (" ~ fmt(skinVol + capVol, 0) ~ " cm3) exceed the part (" ~ fmt(partVol, 0) ~ " cm3) - lower Cap thick %, Cap width % or Skin plies";
            towVol = 0;
        }
        // the core: tow (laminate, as the rest), foam (its own density, no fibre or resin inside it),
        // or monolithic (woven plies, bought as cloth). Build 157
        const coreType = definition.coreType == undefined ? CoreType.TOW : definition.coreType;
        const isPrinted = coreType == CoreType.PRINTED;
        const isFoam = coreType == CoreType.FOAM || isPrinted;              // both: a core of its own density, no fibre or resin inside
        // the root zone inside the core's start (clear of the socket) is laminate, not core: its share
        // of the fill volume by the section's chord x thickness along the span
        var rootFrac = 0;
        if (isFoam && coreE0 > 0)
        {
            var sIn = 0;
            var sAll = 0;
            for (var i = 0; i < 40; i += 1)
            {
                const eta = (i + 0.5) / 40;
                const ct = chordFactor(m, eta) * (chordFactor(m, eta) - tailFactor(m, eta)) * (m.rootT + (m.tipT - m.rootT) * eta ^ m.thicknessExp);
                sAll += ct;
                if (eta < coreE0)
                    sIn += ct;
            }
            rootFrac = sAll > 0 ? sIn / sAll : 0;
        }
        if (isFus && isFoam)
            rootFrac = fusCore != undefined && towVol > 0 ? max(0, 1 - fusCore.coreVol / towVol) : 1;   // the solid zones' share; all solid without a core
        const noseVolF = hubOn && hub.noseOn != undefined && hub.noseOn == 1 && hub.noseVol != undefined ? hub.noseVol : 0;   // the nose fairing (wing 1.070): filler and skin on the root
        const rootVol = towVol * rootFrac + noseVolF;                         // cm3 of laminate fill at the root
        if (isFoam)
            towVol = towVol - towVol * rootFrac;                              // the core proper
        const lamVol = isFoam ? partVol - towVol : partVol;                  // cm3 of laminate (the root fill included)
        const fibreMass = vf * lamVol * rhoF * over;                          // g, all carbon in the part
        const resinMass = (1 - vf) * lamVol * rhoR + (isFoam ? 0.05 * towVol * rhoR : 0);   // g, cured; a little resin wets a foam core's surface
        const skinMass = skinArea * definition.skinGsm * over;
        const capMass = capVol * vf * rhoF * over;
        const towMass = isFoam ? towVol * definition.coreDensity / 1000 : towVol * vf * rhoF * over;   // g: foam by density, else laminate
        const towLen = coreType == CoreType.TOW ? towMass / (definition.towTex / 1000) : 0;          // m of tow
        const fillArea = coreType == CoreType.SOLID ? towVol / (tSkin * 0.1) / 10000 : (isFus && isFoam ? rootVol / (tSkin * 0.1) / 10000 : 0);   // m2 of woven to fill a monolithic core (fuselage: its solid zones)
        const coreSheet = isFus ? (fusCore != undefined ? fusCore.hMax * 1000 : 0) : (isFlat ? 0 : max(m.rootT * m.c0 * 1000 - tSkins, 0));                    // mm, foam sheet thickness at the root
        const refArea = isFlat ? 1 : (m.area == undefined ? 1 : m.area);                             // m2, for the monolithic ply count
        const capArea = capMass / definition.udGsm;                           // m2
        const wasteC = 1 + definition.clothWastePct / 100;
        const wasteR = 1 + definition.resinWastePct / 100;
        const layupMsg = "layup " ~ fmt(partVol, 0) ~ " cm3, " ~ fmt((fibreMass + resinMass + (isFoam ? towMass : 0)) / 1000, 2) ~ " kg cured at Vf " ~ fmt(vf * 100, 0) ~ "%" ~
            (isFoam ? " with a " ~ fmt(definition.coreDensity, 0) ~ " kg/m3 " ~ (isPrinted ? "printed" : "foam") ~ " core" : (coreType == CoreType.SOLID ? " monolithic" : "")) ~
            " | skin " ~ fmt(definition.skinPlies, 0) ~ " x " ~ fmt(definition.skinGsm, 0) ~ " gsm each face (" ~ fmt(tSkin, 2) ~ " mm/ply): " ~ fmt(skinArea, 2) ~ " m2, " ~ fmt(skinMass, 0) ~ " g" ~
            (plateFill > 0 ? " incl. the plate's fill: " ~ plateFill ~ " woven plies inside its skins, " ~ fmt(plateArea * plateFill * definition.skinGsm * over, 0) ~ " g" : "") ~
            (isFus && fusCore == undefined ? " | no UD caps (solid fill throughout)" : " | UD caps " ~ fmt(definition.udGsm, 0) ~ " gsm (" ~ fmt(tUd, 2) ~ " mm/ply), " ~ fmt(capW * 100, 0) ~ "% chord: " ~ fmt(capPliesRoot, 0) ~ " plies per cap at the " ~
            (isMast ? "plate to " ~ fmt(capPliesTip, 0) ~ " at the fuselage end" : (isFus ? "mast end to " ~ fmt(capPliesTip, 0) ~ " at the seat end, on the tail core's top and bottom" : "root to " ~ fmt(capPliesTip, 0) ~ " at the tip")) ~ " (cut 2 of each), " ~ fmt(capLen * 1000, 0) ~ " mm long, " ~ fmt(capArea, 2) ~ " m2, " ~ fmt(capMass, 0) ~ " g") ~
            tabNote ~
            (coreType == CoreType.TOW ? " | tow " ~ fmt(definition.towTex, 0) ~ " tex: " ~ fmt(towMass, 0) ~ " g, " ~ fmt(towLen, 0) ~ " m" :
             (isPrinted ? " | printed core " ~ fmt(towVol, 0) ~ " cm3, " ~ fmt(towMass, 0) ~ " g at " ~ fmt(definition.coreDensity, 0) ~ " kg/m3: generated as a part, see the notice" :
              (isFoam ? " | foam core " ~ fmt(towVol, 0) ~ " cm3, " ~ fmt(towMass, 0) ~ " g: cut from sheet at least " ~ fmt(coreSheet, 0) ~ " mm thick, shaped to the cavity less " ~ fmt(tSkins / 2, 2) ~ " mm of skin each face" :
              " | monolithic fill: " ~ fmt(fillArea, 2) ~ " m2 woven (" ~ fmt(towVol / (tSkin * 0.1) / 10000 / max(refArea, 1e-6), 0) ~ " plies at the section's mean), " ~ fmt(towMass, 0) ~ " g"))) ~
            " | resin " ~ fmt(resinMass, 0) ~ " g in the part, mix " ~ fmt(resinMass * wasteR, 0) ~ " g" ~
            " | buy " ~ fmt((skinArea + fillArea) * wasteC, 2) ~ " m2 woven, " ~ fmt(capArea * wasteC, 2) ~ " m2 UD (+" ~ fmt(definition.clothWastePct, 0) ~ "%)" ~
            (isFoam && !isPrinted ? ", " ~ fmt(towVol * 1.3, 0) ~ " cm3 of foam (+30%)" : "") ~
            (rootVol > 0 && isFus ? " | solid zones (the nose to " ~ (fusCore != undefined ? fmt(fusCore.x0 * 1000, 0) : "the end") ~ " mm" ~ (fusCore != undefined ? ", and from " ~ fmt(fusCore.x1 * 1000, 0) ~ " mm through the seat" : "") ~ "): " ~ fmt(rootVol, 0) ~ " cm3 of woven fill, " ~ fmt(rootVol * vf * rhoF * over, 0) ~ " g fibre" ~ (fusCoreWhy != "" ? " (" ~ fusCoreWhy ~ ")" : "") : "") ~
            (rootVol > 0 && !isFus ? " | root zone solid: " ~ fmt(rootVol, 0) ~ " cm3 of laminate fill (" ~ fmt(rootVol * vf * rhoF * over, 0) ~ " g fibre" ~ (noseVolF > 0 ? ", " ~ fmt(noseVolF, 1) ~ " cm3 of it the nose fairing" : "") ~ ") from the centre to " ~ fmt(coreClearY / millimeter, 0) ~ " mm each side, the core clear of the joint by " ~ fmt((definition.coreClear == undefined ? 15 * millimeter : definition.coreClear) / millimeter, 0) ~ " mm" : "") ~
            ", cut list on the console";
        foilPrint(context, moldLogKey, "LAYUP: " ~ layupMsg);

        // ---------------- stiffness: the layup's bending stiffness against the published loads ----------------
        // EI per station from the caps (UD, at +/- their offset), the skins (woven, on the surface, 0.7 of
        // the extreme fibre for their curvature) and the tow core (a lens, ~0.02 c t^3); curvature M / EI
        // integrated twice from the root for the tip deflection. Wing / stab: the spanwise moment the
        // Foil performance feature publishes at its load factor. Mast: a side load at the plate.
        var stiffMsg = "";
        var coreShearWarn = "";
        {
            const Eud = definition.udModulus * 1e9;
            const Ew = definition.wovenModulus * 1e9;
            const Etow = (isFoam ? definition.coreModulus : (coreType == CoreType.SOLID ? definition.wovenModulus : definition.towModulus)) * 1e9;   // the core's modulus, whatever fills it; a printed core is a lattice, Core GPa (build 226)
            // core shear between the caps (foam or printed): allowable as entered, or estimated from
            // the density as a PVC structural foam, tau = 0.0056 rho^1.215 (1.15 MPa at 80, 3.5 at 200)
            const shearIn = definition.coreShear != undefined && definition.coreShear > 0;
            const tauAllow = !isFoam ? 0 : (shearIn ? definition.coreShear : 0.0056 * definition.coreDensity ^ 1.215);
            const tauSrc = shearIn ? "as entered" : ("estimated from " ~ fmt(definition.coreDensity, 0) ~ " kg/m3 as PVC foam" ~ (isPrinted ? "; a print's strength is unmeasured: break a coupon and enter it in Core shear MPa" : ""));
            const tsF = definition.skinPlies * tSkin / 1000;          // m, one face's skins
            if (isMast)
            {
                var loadsM;
                try silent { loadsM = getVariable(context, "foilWingLoads"); }
                if (loadsM == undefined)
                    stiffMsg = " | stiffness: add a Foil performance feature above for the mast side-load check";
                else
                {
                    // fixed at the plate (the board and rider are the anchor), the side force from the
                    // wing at the fuselage end: moment F z from the base, greatest at the plate. Build
                    // 116 had it the other way round, so the peak landed on the thin base section
                    const H = mastM.height;
                    const F = definition.mastSideG * loadsM.W;
                    const nZ = 40;
                    var slope = 0;
                    var defl = 0;
                    var sigBase = 0;
                    var sigMax = 0;             // MPa, the worst cap stress along the height ...
                    var zSigMax = 0;            // ... and where (m above the fuselage end)
                    var capForceP = 0;          // N, one cap's force at the plate
                    var wCapP = 0;              // m, cap width at the plate
                    var tauMax = 0;             // MPa, a foam or printed core's shear between the caps ...
                    var zTauMax = 0;            // ... and where (m above the fuselage end)
                    var kPrev = 0;
                    for (var i = nZ; i >= 0; i -= 1)
                    {
                        const sF = i / nZ;
                        const c = mastM.chord + ((mastM.chordTop != undefined ? mastM.chordTop : mastM.chord) - mastM.chord) * sF;
                        const s0 = mastM.thickenFrom != undefined ? mastM.thickenFrom : 1;
                        const u = s0 >= 1 ? 0 : min(max((sF - s0) / (1 - s0), 0), 1);
                        const t = mastM.thick + ((mastM.thickTop != undefined ? mastM.thickTop : mastM.thick) - mastM.thick) * u * u * (3 - 2 * u);
                        const capT = max(capF * (t - 2 * tsF), 0) / 2;
                        const wCap = capW * c;
                        const dC = t / 2 - tsF - capT / 2;
                        const Icap = 2 * (wCap * capT ^ 3 / 12 + wCap * capT * dC * dC);
                        const dS = 0.7 * (t / 2 - tsF / 2);
                        const Iskin = 2 * (c * tsF ^ 3 / 12 + c * tsF * dS * dS);
                        const Icore = 0.02 * c * t ^ 3 * max(0, 1 - (2 * capT + 2 * tsF) / t);
                        const EI = Eud * Icap + Ew * Iskin + Etow * Icore;
                        const M = F * H * sF;
                        const kap = EI > 0 ? M / EI : 0;
                        const sigHere = EI > 0 ? Eud * M * (t / 2 - tsF) / EI / 1e6 : 0;
                        if (isFoam && EI > 0)
                        {
                            // V Q / EI at mid-depth in the cap band, Q modulus-weighted per unit width
                            const coreH = max(t / 2 - tsF - capT, 0);
                            const tauHere = F * (Eud * capT * dC + Ew * tsF * (t / 2 - tsF / 2) + Etow * coreH * coreH / 2) / EI / 1e6;
                            if (tauHere > tauMax)
                            {
                                tauMax = tauHere;
                                zTauMax = sF * H;
                            }
                        }
                        if (sigHere > sigMax)
                        {
                            sigMax = sigHere;
                            zSigMax = sF * H;
                        }
                        if (i == nZ)
                        {
                            sigBase = sigHere;
                            capForceP = EI > 0 ? Eud * M * dC / EI * wCap * capT : 0;
                            wCapP = wCap;
                        }
                        if (i < nZ)
                        {
                            const dz = H / nZ;
                            const slopeNew = slope + 0.5 * (kPrev + kap) * dz;
                            defl += 0.5 * (slope + slopeNew) * dz;
                            slope = slopeNew;
                        }
                        kPrev = kap;
                    }
                    // the plate hands that moment to the board through the two tracks, Track spacing
                    // apart: one track in tension, the other in compression, shared by the bolts of a row
                    const boltT = mastM.trackSpacing != undefined && mastM.trackSpacing > 0 ? F * H / mastM.trackSpacing / max(1, mastM.boltsPerRow) / 1000 : 0;   // kN per bolt
                    const boltNote = boltT > 0 ? ", track bolts " ~ fmt(boltT, 1) ~ " kN each (M / track spacing / bolts per row - the plate's pull-through and the board's inserts must take this)" : "";
                    // junction: the cap's force leaves the UD by shear over its run-out on the plate; every
                    // tab ply adds two bonded faces. Allowable = Shear allow / 2. Plate: a beam between the
                    // two tracks, loaded by the row force at the section's edge
                    const nIf = 1 + 2 * tabN;
                    const allowJ = definition.shearAllow / 2;
                    const shearJ = runOut > 0 && wCapP > 0 ? capForceP / (runOut / 1000 * wCapP * nIf) / 1e6 : 0;
                    const needRun = wCapP > 0 ? capForceP / (allowJ * 1e6 * wCapP * nIf) * 1000 : 0;
                    const tPl = mastM.plateThick != undefined ? mastM.plateThick : 0;
                    const tTopJ = mastM.thickTop != undefined ? mastM.thickTop : mastM.thick;
                    const sigPlate = boltT > 0 && tPl > 0 ? (F * H / mastM.trackSpacing) * max(mastM.trackSpacing / 2 - tTopJ / 2, 0) * (tPl / 2) / (mastM.plateLength * tPl ^ 3 / 12) / 1e6 : 0;
                    const fillet = mastM.rootFillet != undefined ? mastM.rootFillet * 1000 : 0;
                    const junctionNote = " | junction: cap force " ~ fmt(capForceP / 1000, 1) ~ " kN at the plate, shear " ~ fmt(shearJ, 1) ~ " MPa over " ~ fmt(runOut, 0) ~ " mm run-out with " ~ tabN ~
                        " tabs per face (allow " ~ fmt(allowJ, 0) ~ " = Shear allow / 2), needs " ~ fmt(needRun, 0) ~ " mm" ~
                        (shearJ > allowJ ? " - OVER: more Tab plies, Cap run-out, Top thick or Plate width" : "") ~
                        (fillet <= 0 ? "; no Root fillet on Foil mast - the plies fold through a sharp corner" : "; root fillet " ~ fmt(fillet, 0) ~ " mm") ~
                        (sigPlate > 0 ? "; plate bending " ~ fmt(sigPlate, 0) ~ " MPa between the tracks (woven takes about 300)" : "");
                    stiffMsg = " | stiffness (" ~ fmt(definition.mastSideG, 1) ~ " g side load, " ~ fmt(F, 0) ~ " N at the fuselage, plate fixed): fuselage-end deflection " ~ fmt(defl * 1000, 1) ~
                        " mm, moment at the plate " ~ fmt(F * H, 0) ~ " Nm, UD cap stress there " ~ fmt(sigBase, 0) ~ " MPa" ~
                        (sigMax > sigBase + 1 ? ", worst " ~ fmt(sigMax, 0) ~ " MPa at " ~ fmt(zSigMax * 1000, 0) ~ " mm above the fuselage (where the thickening starts: lower Thicken from % or raise Thickness in Foil mast)" : "") ~
                        (sigMax > 450 ? " - OVER the cap limit" : "") ~ boltNote ~ junctionNote ~
                        (isFoam ? "; core shear up to " ~ fmt(tauMax, 2) ~ " MPa at " ~ fmt(zTauMax * 1000, 0) ~ " mm above the fuselage, " ~ fmt(tauAllow, 2) ~ " allowed (" ~ tauSrc ~ ")" ~ (tauMax > tauAllow ? " - OVER" : "") : "");
                    if (isFoam && tauMax > tauAllow)
                        coreShearWarn = "the " ~ (isPrinted ? "printed" : "foam") ~ " core shears: " ~ fmt(tauMax, 2) ~ " MPa between the caps at " ~ fmt(zTauMax * 1000, 0) ~ " mm above the fuselage against " ~ fmt(tauAllow, 2) ~ " allowed - a denser core (Core kg/m^3, Core shear MPa), a shear web, or Tow fill";
                    foilPrint(context, moldLogKey, "STIFFNESS: mast side " ~ fmt(definition.mastSideG, 1) ~ " g at the fuselage, plate fixed: F=" ~ fmt(F, 0) ~ " N, deflection at the fuselage " ~ fmt(defl * 1000, 1) ~ " mm, cap stress at the plate " ~ fmt(sigBase, 0) ~ " MPa, worst " ~ fmt(sigMax, 0) ~ " MPa at " ~ fmt(zSigMax * 1000, 0) ~ " mm" ~
                        (boltT > 0 ? ", track bolt tension " ~ fmt(boltT, 2) ~ " kN each" : "") ~
                        ", junction: cap force " ~ fmt(capForceP / 1000, 2) ~ " kN, shear " ~ fmt(shearJ, 2) ~ " MPa over " ~ fmt(runOut, 0) ~ " mm x (1 + 2 x " ~ tabN ~ " tabs), allow " ~ fmt(allowJ, 1) ~ ", needs " ~ fmt(needRun, 0) ~ " mm, plate bending " ~ fmt(sigPlate, 0) ~ " MPa, fillet " ~ fmt(fillet, 0) ~ " mm" ~
                        (isFoam ? ", core shear " ~ fmt(tauMax, 2) ~ " MPa at " ~ fmt(zTauMax * 1000, 0) ~ " mm, allow " ~ fmt(tauAllow, 2) : ""));
                }
            }
            else if (isFus)
            {
                // the fuselage as a cantilever from its root (the hub's back, or the socket's rear face)
                // carrying the stab's lift at the load factor: bending stiffness per station from the
                // skins as a thin-walled rounded rectangle plus the fill, curvature integrated twice
                // to the stab; skin stress at the root against woven's 300 MPa
                var loadsS;
                try silent { loadsS = getVariable(context, "foilStabLoads"); }
                if (loadsS == undefined || loadsS.halfLift == undefined)
                    stiffMsg = " | stiffness: add a Foil performance feature above (this build) for the stab-load check";
                else if (fusM.stations == undefined || fusM.rootX == undefined || fusM.stabBoltX == undefined || size(fusM.stabBoltX) == 0)
                    stiffMsg = " | stiffness: the fuselage above publishes no stations or stab bolts - paste the whole Feature Studio again";
                else
                {
                    const Fs = 2 * loadsS.halfLift;                          // N, the stab's lift at n g
                    var xSt = 0;
                    for (var b in fusM.stabBoltX)
                        xSt += b / size(fusM.stabBoltX);
                    const xR = fusM.rootX;
                    const st = fusM.stations;
                    const nI = 60;
                    var theta = 0;
                    var defl = 0;
                    var sigRoot = 0;
                    var eiRoot = 0;
                    const t = tsF;                                            // m, one face's skins
                    const fusCoreOpt = coreType == CoreType.FOAM || coreType == CoreType.PRINTED;
                    const EfSolid = fusCoreOpt ? Ew : Etow;                  // the solid zones are woven with a tail core
                    const Ecore = definition.coreModulus * 1e9;
                    var capSigMax = 0;
                    var xCapSig = 0;
                    var skinSigMax = 0;
                    var xSkinSig = 0;
                    var skinSigCore = 0;
                    for (var i = 0; i < nI; i += 1)
                    {
                        const x = xR + (xSt - xR) * (i + 0.5) / nI;
                        // section at x from the published stations
                        const scB = fusSectionAt(st, x);
                        const a = scB[0];
                        const b = scB[1];
                        const w = 2 * a;
                        const hS = 2 * b;
                        const iSkin = t * hS ^ 3 / 6 + w * t * hS ^ 2 / 2;      // m4, thin walls
                        const iFill = w * hS ^ 3 / 12;                         // m4, the fill inside
                        var ei = Ew * iSkin + EfSolid * iFill;
                        const M = Fs * (xSt - x);
                        const czB = fusCoreAtNum(fusCore, x);
                        if (czB != undefined)
                        {
                            // over the tail core: skins, the UD strips top and bottom, the core
                            const iCap = 2 * czB.wc * czB.tc * (b - t - czB.tc / 2) ^ 2;
                            const iCore = 2 * czB.ac * (2 * czB.bc) ^ 3 / 12;
                            ei = Ew * iSkin + Eud * iCap + Ecore * iCore;
                            const sC = Eud * M * (b - t) / ei / 1e6;
                            if (sC > capSigMax)
                            {
                                capSigMax = sC;
                                xCapSig = x;
                            }
                            skinSigCore = max(skinSigCore, Ew * M * b / ei / 1e6);
                        }
                        if (i == 0)
                        {
                            sigRoot = Ew * M * b / ei / 1e6;
                            eiRoot = ei;
                        }
                        if (Ew * M * b / ei / 1e6 > skinSigMax)
                        {
                            skinSigMax = Ew * M * b / ei / 1e6;
                            xSkinSig = x;
                        }
                        const dx = (xSt - xR) / nI;
                        theta += M / ei * dx;
                        defl += theta * dx;
                    }
                    const mRoot = Fs * (xSt - xR);
                    // torsion and side bending (build 217, user: the fuselage also twists between the
                    // wing, the stab and the mast). Rolling moments from a 60 / 40 split of the wing's
                    // and the stab's lift at the load factor (a carve, one foot loading) twist the
                    // fuselage from the hub to the mast and from the stab to the mast; the mast's side
                    // load (Mast side g, as the mast's own check) bends it sideways from the hub to the
                    // mast. Closed thin-walled section: Bredt's J = 4 Am^2 t / P for the skins, shear
                    // tau = T / (2 Am t), plus the fill's rectangle torsion constant; G = E / 2.6
                    var torsNote = "";
                    var loadsW;
                    try silent { loadsW = getVariable(context, "foilWingLoads"); }
                    if (loadsW != undefined && loadsW.halfLift != undefined && mastM != undefined && mastM.leX != undefined)
                    {
                        const xM = mastM.leX + mastM.chord / 2;                       // the mast's centre on the fuselage
                        const Tw = 0.2 * 2 * loadsW.halfLift * loadsW.yBar;                // Nm, wing 60 / 40
                        const Ts = 0.2 * Fs * 0.42 * loadsS.span / 2;                   // Nm, stab 60 / 40 at an elliptical centroid
                        const G = Ew / 2.6;
                        const Gf = Etow / 2.6;
                        var twist = 0;
                        var tauMax = 0;
                        var xTau = xR;
                        var tauInCore = false;
                        const segs = [[xR, xM, Tw], [xM, xSt, Ts]];
                        for (var sgm in segs)
                        {
                            const xa = min(sgm[0], sgm[1]);
                            const xb = max(sgm[0], sgm[1]);
                            const T = sgm[2];
                            if (xb - xa < 1e-4)
                                continue;
                            for (var i = 0; i < nI; i += 1)
                            {
                                const x = xa + (xb - xa) * (i + 0.5) / nI;
                                const sc = fusSectionAt(st, x);
                                const w = 2 * sc[0];
                                const hS = 2 * sc[1];
                                const rc = sc[2];
                                const Am = max((w - t) * (hS - t) - (4 - PI) * rc ^ 2, 1e-8);
                                const P = 2 * (w + hS) - (8 - 2 * PI) * rc;
                                const jSkin = 4 * Am ^ 2 * t / P;
                                const hMin = min(w, hS);
                                const hMax = max(w, hS);
                                const jFill = hMax * hMin ^ 3 / 3 * (1 - 0.63 * hMin / hMax);
                                const czT = fusCoreAtNum(fusCore, x);
                                const gj = G * jSkin + (czT != undefined ? Ecore / 2.6 * (2 * czT.ac) * (2 * czT.bc) ^ 3 / 3 * (1 - 0.63 * min(czT.ac, czT.bc) / max(czT.ac, czT.bc)) : (fusCoreOpt ? Ew / 2.6 : Gf) * jFill);
                                twist += T / gj * (xb - xa) / nI;
                                // shear: a solid section (tow or monolithic fill) carries the torque as one
                                // rectangle, tau = T / (alpha w h^2); with a foam or printed core the skins
                                // carry it alone, tau = T / (2 Am t)
                                const solidFill = czT == undefined && (coreType == CoreType.SOLID || coreType == CoreType.TOW || fusCoreOpt);
                                const alpha = 1 / (3 + 1.8 * hMin / hMax);
                                const tau = (solidFill ? T / (alpha * hMax * hMin ^ 2) : T / (2 * Am * t)) / 1e6;
                                if (tau > tauMax)
                                {
                                    tauMax = tau;
                                    xTau = x;
                                    tauInCore = czT != undefined;
                                }
                            }
                        }
                        // side bending from the mast's side load, hub to mast
                        const Fside = definition.mastSideG * loadsW.W;
                        const scR = fusSectionAt(st, xR);
                        const wR = 2 * scR[0];
                        const hR = 2 * scR[1];
                        const iSide = t * wR ^ 3 / 6 + hR * t * wR ^ 2 / 2;
                        const iSideF = hR * wR ^ 3 / 12;
                        const mSide = Fside * abs(xM - xR);
                        const sigSide = Ew * mSide * scR[0] / (Ew * iSide + EfSolid * iSideF) / 1e6;
                        const solidF = !tauInCore && (coreType == CoreType.SOLID || coreType == CoreType.TOW || fusCoreOpt);
                        const pocketInSpan = fusM.stations != undefined && mastM.chord != undefined && xM > xR && xM < xSt;
                        torsNote = " | torsion (60/40 lift split at " ~ fmt(loadsS.n, 1) ~ " g): wing " ~ fmt(Tw, 0) ~ " Nm from the hub to the mast, stab " ~ fmt(Ts, 0) ~ " Nm from the stab to the mast, shear up to " ~ fmt(tauMax, 0) ~
                            " MPa at X " ~ fmt(xTau * 1000, 0) ~ (solidF ? " in the solid section" : " in the skins alone (over the core)") ~ " (woven takes about 80)" ~ (tauMax > 80 ? " - OVER: " ~ (solidF ? "a bigger section, or more Skin plies" : "more Skin plies, or start the core further aft (Core from mast)") : "") ~
                            ", twist hub to stab " ~ fmt(twist * 180 / PI, 2) ~ " deg" ~ (pocketInSpan ? "; over the mast pocket the section is open at the top and carries the torque in its walls - the weak stretch, not in this figure" : "") ~
                            " | side load " ~ fmt(definition.mastSideG, 1) ~ " g at the mast: " ~ fmt(mSide, 0) ~ " Nm at the hub, skin stress " ~ fmt(sigSide, 0) ~ " MPa" ~ (sigSide > 300 ? " - OVER" : "");
                        foilPrint(context, moldLogKey, "TORSION: wing " ~ fmt(Tw, 1) ~ " Nm, stab " ~ fmt(Ts, 1) ~ " Nm, tauMax " ~ fmt(tauMax, 1) ~ " MPa at X " ~ fmt(xTau * 1000, 0) ~ " mm, twist " ~ fmt(twist * 180 / PI, 3) ~ " deg; side " ~ fmt(Fside, 0) ~ " N at the mast, M " ~ fmt(mSide, 1) ~ " Nm at the hub, sigma " ~ fmt(sigSide, 1) ~ " MPa");
                    }
                    else
                        torsNote = " | torsion: needs a Foil performance (this build) and a Foil mast above";
                    stiffMsg = " | stiffness at " ~ fmt(loadsS.n, 1) ~ " g: stab lift " ~ fmt(Fs, 0) ~ " N at X " ~ fmt(xSt * 1000, 0) ~ " on a " ~ fmt((xSt - xR) * 1000, 0) ~ " mm cantilever from the " ~
                        (hubOn || (hub != undefined && hub.on == 1) ? "hub's back" : "socket") ~ ", moment there " ~ fmt(mRoot, 0) ~ " Nm, skin stress " ~ fmt(sigRoot, 0) ~ " MPa there and up to " ~ fmt(skinSigMax, 0) ~ " MPa at X " ~ fmt(xSkinSig * 1000, 0) ~ " (woven takes about 300)" ~
                        (skinSigMax > 300 ? " - OVER: more Skin plies or a taller Body height" : "") ~ ", deflection at the stab " ~ fmt(defl * 1000, 1) ~ " mm, root EI " ~ fmt(eiRoot, 0) ~ " N m2" ~
                        (fusCore != undefined ? " | tail core X " ~ fmt(fusCore.x0 * 1000, 0) ~ "-" ~ fmt(fusCore.x1 * 1000, 0) ~ ": UD strips " ~ fusCore.nMax ~ " to " ~ fusCore.nMin ~ " plies top and bottom, their stress up to " ~ fmt(capSigMax, 0) ~
                            " MPa at X " ~ fmt(xCapSig * 1000, 0) ~ " (UD takes about 450)" ~ (capSigMax > 450 ? " - OVER: lower Tail UD MPa" : "") ~ ", skin stress over the core up to " ~ fmt(skinSigCore, 0) ~ " MPa" ~ (skinSigCore > 300 ? " - OVER" : "") : "") ~ torsNote;
                    foilPrint(context, moldLogKey, "STIFFNESS: fuselage " ~ fmt(loadsS.n, 1) ~ " g: stab lift " ~ fmt(Fs, 1) ~ " N, arm " ~ fmt((xSt - xR) * 1000, 0) ~ " mm, root moment " ~ fmt(mRoot, 1) ~ " Nm, skin stress " ~ fmt(sigRoot, 1) ~ " MPa at the root, max " ~ fmt(skinSigMax, 1) ~ " MPa at X " ~ fmt(xSkinSig * 1000, 0) ~ ", deflection " ~ fmt(defl * 1000, 2) ~ " mm, root EI " ~ fmt(eiRoot, 0) ~ " N m2" ~
                        (fusCore != undefined ? "; tail core " ~ fmt(fusCore.x0 * 1000, 0) ~ "-" ~ fmt(fusCore.x1 * 1000, 0) ~ " mm, UD " ~ fusCore.nMax ~ "-" ~ fusCore.nMin ~ " plies, cap stress max " ~ fmt(capSigMax, 1) ~ " MPa at X " ~ fmt(xCapSig * 1000, 0) ~ ", skin over core max " ~ fmt(skinSigCore, 1) ~ " MPa" : ""));
                }
            }
            else
            {
                var loads;
                try silent { loads = getVariable(context, definition.moldSource == MoldSource.WING ? "foilWingLoads" : "foilStabLoads"); }
                if (loads == undefined)
                    stiffMsg = " | stiffness: add a Foil performance feature above for the deflection check";
                else
                {
                    const h = m.span / 2;
                    const nSt = size(tplCAt) - 1;
                    var slope = 0;
                    var defl = 0;
                    var kPrev = 0;
                    var sigRoot = 0;
                    var eiRoot = 0;
                    var sigMax = 0;             // MPa, the largest cap stress along the span ...
                    var ySigMax = 0;            // ... and where (m from the centre)
                    var tauMax = 0;             // MPa, a foam or printed core's shear between the caps ...
                    var yTauMax = 0;            // ... and where
                    const yClear = coreClearY / meter;     // the root zone inside it is laminate, not core
                    for (var i = 0; i <= nSt; i += 1)
                    {
                        const eta = capStartEta * i / nSt;
                        const t = tplTAt[i] / 1000;
                        const c = tplCAt[i] / 1000;
                        const capT = max(capF * (t - 2 * tsF), 0) / 2;
                        const wCap = capW * c;
                        const dC = t / 2 - tsF - capT / 2;
                        const Icap = 2 * (wCap * capT ^ 3 / 12 + wCap * capT * dC * dC);
                        const dS = 0.7 * (t / 2 - tsF / 2);
                        const Iskin = 2 * (c * tsF ^ 3 / 12 + c * tsF * dS * dS);
                        const Icore = 0.02 * c * t ^ 3 * max(0, 1 - (2 * capT + 2 * tsF) / t);
                        const EI = Eud * Icap + Ew * Iskin + Etow * Icore;
                        // published moment at 21 stations, interpolated
                        const pj = eta * 20;
                        const j0 = min(floor(pj), 19);
                        const M = loads.M[j0] + (loads.M[j0 + 1] - loads.M[j0]) * (pj - j0);
                        const kap = EI > 0 ? M / EI : 0;
                        const sigHere = EI > 0 ? Eud * M * (t / 2 - tsF) / EI / 1e6 : 0;
                        if (i == 0)
                        {
                            eiRoot = EI;
                            sigRoot = sigHere;
                        }
                        if (sigHere > sigMax)
                        {
                            sigMax = sigHere;
                            ySigMax = eta * h;
                        }
                        if (isFoam && EI > 0 && eta * h >= yClear)
                        {
                            // shear: the slope of the published moment at the 20 interval midpoints,
                            // interpolated, the half lift at the root; V Q / EI at mid-depth in the cap band
                            const V = moldShearAt(loads, h, eta);
                            const coreH = max(t / 2 - tsF - capT, 0);
                            const tauHere = V * (Eud * capT * dC + Ew * tsF * (t / 2 - tsF / 2) + Etow * coreH * coreH / 2) / EI / 1e6;
                            if (tauHere > tauMax)
                            {
                                tauMax = tauHere;
                                yTauMax = eta * h;
                            }
                        }
                        if (i > 0)
                        {
                            const dy = capStartEta * h / nSt;
                            const slopeNew = slope + 0.5 * (kPrev + kap) * dy;
                            defl += 0.5 * (slope + slopeNew) * dy;
                            slope = slopeNew;
                        }
                        kPrev = kap;
                    }
                    stiffMsg = " | stiffness at " ~ fmt(loads.n, 1) ~ " g: tip deflection " ~ fmt(defl * 1000, 1) ~ " mm (" ~ fmt(defl * 1000 / loads.n, 1) ~ " mm at 1 g, " ~
                        fmt(defl / h * 100, 1) ~ "% of the half span), root moment " ~ fmt(loads.M[0], 0) ~ " Nm, UD cap stress " ~ fmt(sigRoot, 0) ~ " MPa" ~
                        (sigMax > sigRoot + 1 ? " at the root and up to " ~ fmt(sigMax, 0) ~ " MPa at " ~ fmt(ySigMax * 1000, 0) ~ " mm from the centre" : "") ~
                        (sigMax > 450 ? " - OVER the cap limit" : "") ~
                        (isFoam ? "; core shear up to " ~ fmt(tauMax, 2) ~ " MPa at " ~ fmt(yTauMax * 1000, 0) ~ " mm from the centre, " ~ fmt(tauAllow, 2) ~ " allowed (" ~ tauSrc ~ ")" ~ (tauMax > tauAllow ? " - OVER" : "") : "");
                    if (isFoam && tauMax > tauAllow)
                        coreShearWarn = "the " ~ (isPrinted ? "printed" : "foam") ~ " core shears: " ~ fmt(tauMax, 2) ~ " MPa between the caps at " ~ fmt(yTauMax * 1000, 0) ~ " mm from the centre against " ~ fmt(tauAllow, 2) ~ " allowed - a denser core (Core kg/m^3, Core shear MPa), a wider Core clear, a shear web, or Tow fill";
                    if (sockHere)
                        stiffMsg = stiffMsg ~ " (the root section at the socket bore is not checked)";
                    foilPrint(context, moldLogKey, "STIFFNESS: " ~ fmt(loads.n, 1) ~ " g: tip deflection " ~ fmt(defl * 1000, 1) ~ " mm (" ~ fmt(defl * 1000 / loads.n, 1) ~ " mm at 1 g), root EI " ~
                        fmt(eiRoot, 0) ~ " N m2, root cap stress " ~ fmt(sigRoot, 0) ~ " MPa, max " ~ fmt(sigMax, 0) ~ " MPa at " ~ fmt(ySigMax * 1000, 0) ~ " mm" ~
                        (isFoam ? ", core shear " ~ fmt(tauMax, 2) ~ " MPa at " ~ fmt(yTauMax * 1000, 0) ~ " mm, allow " ~ fmt(tauAllow, 2) : ""));
                }
            }
        }

        // ---------------- block ----------------
        const f = definition.flangeWidth;
        // the mast is molded from a copy laid flat: rotated 90 deg about X (span -> -Y, thickness ->
        // Z) and dropped to zPart, where its mid-plane - the parting - then lies
        const zPart = -400 * millimeter;
        var moldPart = definition.part;
        var coreNote = "";
        var coreVent;       // core mold: the tip vents, cut with the cavity then removed
        if (isFus && fusCore != undefined && !coreMold && !preview)
        {
            // the tail core as parts (build 219): printed, split to the printer's longest axis with
            // one 3 mm dowel on the axis across each joint; foam, one reference body to shape the foam to
            const isPr = definition.coreType == CoreType.PRINTED;
            const useL = max(max(definition.printerX, definition.printerY), definition.printerZ) - definition.tileMargin - 5 * millimeter;
            const lenC = (fusCore.x1 - fusCore.x0) * meter;
            const nSeg = isPr ? max(1, ceil(lenC / useL)) : 1;
            var segBodies = [];
            for (var k = 0; k < nSeg; k += 1)
            {
                const xa = fusCore.x0 + (fusCore.x1 - fusCore.x0) * k / nSeg;
                const xb = fusCore.x0 + (fusCore.x1 - fusCore.x0) * (k + 1) / nSeg;
                segBodies = append(segBodies, fusCoreLoft(context, id + ("fusCoreSeg" ~ k), fusCore, xa, xb, 0 * meter, 0 * meter));
            }
            var nDow = 0;
            if (nSeg > 1)
            {
                var dowels = [];
                for (var k = 1; k < nSeg; k += 1)
                {
                    const xj = fusCore.x0 + (fusCore.x1 - fusCore.x0) * k / nSeg;
                    const cz = fusCoreAtNum(fusCore, xj);
                    if (cz != undefined && cz.bc > 0.0035 && cz.ac > 0.0035)
                    {
                        dowels = append(dowels, moldPin(context, id + ("fusDowel" ~ k), vector((xj - 0.015) * meter, 0 * meter, cz.zc * meter), vector((xj + 0.015) * meter, 0 * meter, cz.zc * meter), 1.55 * millimeter));
                        nDow += 1;
                    }
                }
                if (size(dowels) > 0)
                    opBoolean(context, id + "fusDowelCut", { "tools" : qUnion(dowels), "targets" : qUnion(segBodies), "operationType" : BooleanOperationType.SUBTRACTION });
            }
            for (var k = 0; k < nSeg; k += 1)
            {
                setAttribute(context, { "entities" : segBodies[k], "name" : "foilCoreBody", "attribute" : 1 });
                setProperty(context, { "entities" : segBodies[k], "propertyType" : PropertyType.NAME, "value" : isPr ? "Fuselage printed core " ~ (k + 1) ~ " of " ~ nSeg : "Fuselage foam core" });
            }
            coreNote = " | tail core, " ~ (isPr ? "printed" : "foam") ~ ": X " ~ fmt(fusCore.x0 * 1000, 0) ~ " to " ~ fmt(fusCore.x1 * 1000, 0) ~ " mm (" ~ fmt(definition.fusCoreFrom / millimeter, 0) ~ " mm behind the mast to " ~
                fmt(definition.fusCoreGap / millimeter, 0) ~ " mm ahead of the seat), up to " ~ fmt(fusCore.hMax * 1000, 1) ~ " mm tall, " ~ fmt(fusCore.coreVol, 0) ~ " cm3, the section less " ~ fmt(definition.skinPlies * tSkin, 2) ~
                " mm of skin and " ~ fusCore.nMax ~ " to " ~ fusCore.nMin ~ " UD plies top and bottom" ~
                (isPr ? "; " ~ nSeg ~ " segment" ~ (nSeg == 1 ? "" : "s") ~ " for the bed" ~ (nDow > 0 ? ", a 3 mm dowel across each joint" : "") ~ "; print, glue end to end, wrap the UD strips and skins over it and lay up in this mold" :
                        "; shape the foam to the reference body (or mold it: a second Foil mold with Mold of = Its foam core)");
        }
        if (!isFlat && ((definition.coreType == CoreType.PRINTED && !coreMold && !preview) || milledCore))
        {
            // printed core (build 159): the same core body as the foam core, generated as a part and
            // split along the span to the longest printer axis, to print and glue end to end.
            // Milled core (build 231): the same body and split, each section then framed in its sheet
            const isPr = !milledCore;
            const skinFaceP = definition.skinPlies * tSkin * millimeter;
            const miniP = sectionDefFromModel(m);
            const coreP = moldCoreBody(context, id, m, miniP, vector(m.baseX, 0, m.baseZ) * meter, skinFaceP, capW, capF, tSkins * millimeter, definition.splitStations, definition.tipBias, 0 * meter, coreE0);
            if (coreP == undefined)
                throw regenError("No room for a " ~ (isPr ? "printed" : "milled") ~ " core: the section is thinner than the skins plus 0.6 mm everywhere - fewer Skin plies, a lighter skin or a thicker section", ["skinPlies", "skinGsm"]);
            const tabsOn = milledCore && definition.coreTabsOn != false;
            const tabOut = tabsOn ? definition.coreTabLen : 0 * meter;                         // milled with tabs: they reach this far out of the leading and trailing edges
            const tabIn = tabsOn ? definition.coreTabIn : 0 * meter;                           // and this far into the section
            const bedLong = max(definition.printerX, definition.printerY) - 2 * definition.tileMargin;
            const bedShort = min(definition.printerX, definition.printerY) - 2 * definition.tileMargin;
            const bed = bedLong;
            if (bed < 20 * millimeter)
                throw regenError("The bed is too small for a core section: raise Printer X / Y or lower Tile margin", ["printerX", "printerY", "tileMargin"]);
            const cbox = evBox3d(context, { "topology" : coreP.body, "tight" : true });
            const spanC = cbox.maxCorner[1] - cbox.minCorner[1];
            // cut positions: along the whole span, or per half when the core starts clear of the socket
            // (a cut through the root gap would split nothing). Milled: more cuts until every section
            // fits inside the sheet with its droop and twist (checked on the model's sections)
            var cutYs = [];
            var nSeg = 1;
            var nWant = coreE0 > 0 ? max(1, ceil((cbox.maxCorner[1] - coreClearY) / bed)) : max(1, ceil(spanC / bed));
            for (var tries = 0; tries < 12; tries += 1)
            {
                cutYs = [];
                var bounds = [];                                          // [ya, yb] of every section, for the sheet check
                if (coreE0 > 0)
                {
                    const halfLen = cbox.maxCorner[1] - coreClearY;
                    for (var k = 1; k < nWant; k += 1)
                    {
                        cutYs = append(cutYs, coreClearY + halfLen * k / nWant);
                        cutYs = append(cutYs, -(coreClearY + halfLen * k / nWant));
                    }
                    for (var k = 0; k < nWant; k += 1)
                        bounds = append(bounds, [coreClearY + halfLen * k / nWant, coreClearY + halfLen * (k + 1) / nWant]);
                    nSeg = 2 * nWant;
                }
                else
                {
                    nSeg = nWant;
                    for (var k = 1; k < nSeg; k += 1)
                        cutYs = append(cutYs, cbox.minCorner[1] + spanC * k / nSeg);
                    for (var k = 0; k < nSeg; k += 1)
                        bounds = append(bounds, [cbox.minCorner[1] + spanC * k / nSeg, cbox.minCorner[1] + spanC * (k + 1) / nSeg]);
                }
                if (!milledCore || nWant >= 12)
                    break;
                var tallest = 0 * meter;
                for (var b in bounds)
                    tallest = max(tallest, moldCoreZExtent(m, miniP, b[0], b[1]));
                if (tallest <= definition.sheetThick - 1 * millimeter)
                    break;
                nWant += 1;
            }
            var cutsP = [];
            for (var k = 0; k < size(cutYs); k += 1)
            {
                const yc = cutYs[k];
                cutsP = append(cutsP, moldCut(context, id + ("coreCut" ~ k), coreP.body, vector(0 * meter, yc, 0 * meter), Y_DIRECTION, cbox.minCorner - vector(1, 1, 1) * 50 * millimeter, cbox.maxCorner + vector(1, 1, 1) * 50 * millimeter));
            }
            if (size(cutsP) > 0)
                opDeleteBodies(context, id + "coreCutTools", { "entities" : qUnion(cutsP) });
            // dowel holes across each joint (user: the segments need keying): a hole along the span,
            // 15 mm into each segment, at the section's thickest point where the core is at least
            // 4 mm thick under the cap groove; diameter half that thickness, 3 to 8 mm, for a carbon
            // or hardwood rod. Not in the winglet (the joint would not be square to the span there)
            var dowels = [];
            var dowelNote = "";
            // a milled core with Tile joint = Puzzle inlay (build 235): no dowels (their holes run along
            // the span, into the joint faces, which a 3-axis router cannot reach); bow-tie inlays on the
            // top and bottom faces instead, below
            const coreInlays = milledCore && puzzle;
            for (var k = 0; k < (coreInlays ? 0 : size(cutYs)); k += 1)
            {
                const yc = cutYs[k];
                const sA = moldCoreSectionAt(m, miniP, yc);
                if (sA.ok != true || sA.winglet == true)
                    continue;                                        // not in the winglet: the joint is not square to the span there
                const chord = sA.chord;
                const thick = sA.thick;
                const xOff = sA.xOff;
                const zOff = sA.zOff;
                const placed = sA.placed;
                const np = size(placed);
                var xT = 0 * meter;
                var tMax = 0 * meter;
                var qT = 0;
                var xAt = [];                                            // per sample: chord position, thickness, mid z
                var tAt = [];
                var zAt = [];
                for (var q = 0; q < 40; q += 1)
                {
                    const xs = placed[0][0] + (placed[(np + 1) / 2 - 1][0] - placed[0][0]) * (q + 0.5) / 40;
                    var zLo = 1 * meter;
                    var zHi = -1 * meter;
                    for (var i = 0; i < np; i += 1)
                    {
                        const p = placed[i];
                        const r = placed[(i + 1) % np];
                        if ((p[0] - xs) * (r[0] - xs) <= 0 * meter * meter && abs(r[0] - p[0]) > 1e-9 * meter)
                        {
                            const z = p[1] + (r[1] - p[1]) * ((xs - p[0]) / (r[0] - p[0]));
                            zLo = min(zLo, z);
                            zHi = max(zHi, z);
                        }
                    }
                    xAt = append(xAt, xs);
                    tAt = append(tAt, zHi > zLo ? zHi - zLo : 0 * meter);
                    zAt = append(zAt, zHi > zLo ? 0.5 * (zLo + zHi) : 0 * meter);
                    if (zHi - zLo > tMax)
                    {
                        tMax = zHi - zLo;
                        xT = xs;
                        qT = q;
                    }
                }
                const capTd = capF * max(thick * chord - tSkins * millimeter, 0 * meter) / 2;
                const capHalf = capW * chord / 2;                        // the cap groove runs this far either side of the thickest point
                // two dowels per joint (user): one each side of the thickest point, about a quarter
                // chord apart, each moved toward the middle until the core is 4 mm thick there
                var placedHere = 0;
                var dNote = "";
                for (var s = -1; s <= 1; s += 2)
                {
                    var q = min(max(qT + s * 5, 0), 39);                 // 5 samples = an eighth of the chord each side
                    var ok = false;
                    var dD = 0 * meter;
                    for (var step = 0; step < 40; step += 1)
                    {
                        const inBand = abs(xAt[q] - xT) <= capHalf;
                        const tC = tAt[q] - 2 * skinFaceP - (inBand ? 2 * capTd : 0 * meter);
                        if (tC >= 4 * millimeter)
                        {
                            dD = min(8 * millimeter, 0.5 * tC);
                            ok = true;
                            break;
                        }
                        if (q == qT)
                            break;                                       // reached the middle with no room
                        q -= s;                                          // one sample toward the thickest point
                    }
                    if (!ok)
                        continue;                                        // no room on this side
                    if (q == qT && placedHere > 0)
                        continue;                                        // both sides collapsed onto the middle: one dowel
                    const cD = vector(m.baseX * meter + xOff + xAt[q], yc, m.baseZ * meter + zOff + zAt[q]);
                    dowels = append(dowels, moldPin(context, id + ("coreDowel" ~ k ~ "_" ~ (s < 0 ? "a" : "b")), cD - vector(0 * meter, 15 * millimeter, 0 * meter), cD + vector(0 * meter, 15 * millimeter, 0 * meter), dD / 2));
                    placedHere += 1;
                    dNote = dNote ~ (dNote == "" ? "" : "/") ~ fmt(dD / millimeter, 1);
                }
                if (placedHere == 0)
                    continue;
                dowelNote = dowelNote ~ (dowelNote == "" ? "" : ", ") ~ placedHere ~ " x " ~ dNote ~ " mm at y " ~ fmt(yc / millimeter, 0);
            }
            if (size(dowels) > 0)
            {
                opBoolean(context, id + "coreDowelCut", {
                            "tools" : qUnion(dowels),
                            "targets" : qBodyType(qHasAttribute("foilCoreBody"), BodyType.SOLID),
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
            }
            // puzzle inlays across the milled core's joints (build 235): a bow-tie pocket in the top face
            // and one in the bottom face of each joint, straddling it, just outside the UD cap band (where
            // the core keeps its full thickness) on the side where the core is thicker; each min(Inlay
            // depth, 25 % of the core there) deep with a flat floor, none where the core is under 6 mm.
            // Their keys are parts (below), Sand allow thicker than the pocket, sanded to the core after
            // gluing. Skipped in Preview
            var coreKeys = [];                                            // { name, x, y, z0, z1 }
            var coreInlayWarn = [];
            var coreInlayNote = "";
            if (coreInlays && !preview && size(cutYs) > 0)
            {
                const cDim = inlayDims(definition);
                const sand = definition.inlaySand != undefined ? definition.inlaySand : 1 * millimeter;
                const ysJ = sort(cutYs, function(a, b) { return (a - b) / meter; });
                var tools = [];
                var dLo = 1 * meter;
                var dHi = 0 * meter;
                var dzMax = 0 * meter;
                for (var k = 0; k < size(ysJ); k += 1)
                {
                    const yc = ysJ[k];
                    const sp = coreInlaySpot(m, miniP, yc, cDim.pLh, cDim.pWh, skinFaceP, capW, capF, tSkins * millimeter);
                    if (sp.ok != true)
                    {
                        coreInlayWarn = append(coreInlayWarn, "joint " ~ (k + 1) ~ " at y " ~ fmt(yc / millimeter, 0) ~ " has no inlay: " ~ sp.why);
                        continue;
                    }
                    if (sp.t < 6 * millimeter)
                    {
                        coreInlayWarn = append(coreInlayWarn, "joint " ~ (k + 1) ~ " at y " ~ fmt(yc / millimeter, 0) ~ " has no inlay: the core is " ~ fmt(sp.t / millimeter, 1) ~ " mm thick outside the cap band, under 6 mm - glue it on a flat table");
                        continue;
                    }
                    const d = min(definition.inlayDepth, 0.25 * sp.t);
                    dLo = min(dLo, d);
                    dHi = max(dHi, d);
                    dzMax = max(dzMax, max(max(sp.topHi - sp.zTop, sp.zTop - sp.topLo), max(sp.botHi - sp.zBot, sp.zBot - sp.botLo)));
                    tools = append(tools, inlayPrism(context, id + ("coreInlayT" ~ k), cDim.pocket, sp.x, yc, true, sp.zTop - d, sp.topHi + 2 * millimeter));
                    tools = append(tools, inlayPrism(context, id + ("coreInlayB" ~ k), cDim.pocket, sp.x, yc, true, sp.botLo - 2 * millimeter, sp.zBot + d));
                    coreKeys = append(coreKeys, { "name" : "Core key " ~ (k + 1) ~ " top", "x" : sp.x, "y" : yc, "z0" : sp.zTop - d, "z1" : sp.zTop + sand });
                    coreKeys = append(coreKeys, { "name" : "Core key " ~ (k + 1) ~ " bottom", "x" : sp.x, "y" : yc, "z0" : sp.zBot - sand, "z1" : sp.zBot + d });
                }
                if (size(tools) > 0)
                {
                    opBoolean(context, id + "coreInlayCut", {
                                "tools" : qUnion(tools),
                                "targets" : qBodyType(qHasAttribute("foilCoreBody"), BodyType.SOLID),
                                "operationType" : BooleanOperationType.SUBTRACTION
                            });
                    const tLo = dLo + sand;
                    const tHi = dHi + sand;
                    coreInlayNote = "; puzzle inlays on the top and bottom faces across " ~ size(coreKeys) / 2 ~ " of " ~ size(ysJ) ~ " joints, just outside the cap band: pockets " ~ fmt(2 * cDim.pLh / millimeter, 1) ~ " x " ~ fmt(2 * cDim.pWh / millimeter, 1) ~
                        " mm (waist " ~ fmt(2 * cDim.pwh / millimeter, 1) ~ "), " ~ (dHi - dLo > 0.05 * millimeter ? fmt(dLo / millimeter, 1) ~ "-" ~ fmt(dHi / millimeter, 1) : fmt(dHi / millimeter, 1)) ~ " mm deep (Inlay depth or a quarter of the core), inside corners R " ~ fmt(cDim.rc / millimeter, 1) ~
                        (dzMax > 0.05 * millimeter ? ", the faces change up to " ~ fmt(dzMax / millimeter, 1) ~ " mm across a key (flat floors)" : "") ~ "; " ~ size(coreKeys) ~ " keys built as parts (Core key ...) " ~ fmt(2 * cDim.lh / millimeter, 1) ~ " x " ~ fmt(2 * cDim.Wh / millimeter, 1) ~
                        " mm (waist " ~ fmt(2 * cDim.wh / millimeter, 1) ~ ") x " ~ (tHi - tLo > 0.05 * millimeter ? fmt(tLo / millimeter, 1) ~ "-" ~ fmt(tHi / millimeter, 1) : fmt(tHi / millimeter, 1)) ~ " mm, cut from " ~ fmt(ceil(tHi / millimeter - 1e-6), 0) ~
                        " mm sheet, standing " ~ fmt(sand / millimeter, 1) ~ " mm proud: glue them across the joints and sand them to the core's profile";
                }
                else
                    coreInlayNote = "; no puzzle inlays (no joint has room for one)";
            }
            const segs = evaluateQuery(context, qBodyType(qHasAttribute("foilCoreBody"), BodyType.SOLID));
            // milled: tabs on each section, bars at its mid-height out of both span ends, to hold it in
            // the stock while both faces are cut (user: tabs on the model, the stock is the CAM's)
            var sheetNeed = 0 * meter;                                    // the tallest section against the sheet
            var sheetX = 0 * meter;                                       // the largest section with its tabs
            var sheetY = 0 * meter;
            var nTabs = 0;
            var nTabsLost = 0;                                            // tabs that found no section to join
            if (milledCore)
            {
                const tabW = tabsOn ? definition.coreTabWide : 0 * meter;
                const tabT = tabsOn ? definition.coreTabThick : 0 * meter;
                for (var k = 0; k < size(segs); k += 1)
                {
                    const bx = evBox3d(context, { "topology" : segs[k], "tight" : true });
                    sheetNeed = max(sheetNeed, bx.maxCorner[2] - bx.minCorner[2]);
                    sheetX = max(sheetX, bx.maxCorner[0] - bx.minCorner[0] + 2 * tabOut);
                    sheetY = max(sheetY, bx.maxCorner[1] - bx.minCorner[1]);
                    if (!tabsOn)
                        continue;
                    // Tabs per edge on each edge, spread along the section, at the section's
                    // own mid-height there: out of the leading edge forward and the trailing edge aft, so
                    // the span ends stay clean for the joint. In a winglet the section is tilted and the
                    // bar is placed on its tilted mid-point (user: the tips need tabs on both edges too);
                    // a bar that does not meet its section is dropped, not left loose
                    var tabs = [];
                    const nPer = definition.coreTabsPerEdge == undefined ? 2 : definition.coreTabsPerEdge;
                    for (var e = 0; e < nPer; e += 1)
                    {
                        const yj = bx.minCorner[1] + (e + 0.5) / nPer * (bx.maxCorner[1] - bx.minCorner[1]);
                        const sE = moldCoreSectionAt(m, miniP, yj);
                        if (sE.ok != true)
                        {
                            nTabsLost += 2;
                            continue;
                        }
                        var xMin = 1 * meter;
                        var xMax = -1 * meter;
                        for (var p in sE.placed)
                        {
                            xMin = min(xMin, p[0]);
                            xMax = max(xMax, p[0]);
                        }
                        for (var j = 0; j < 2; j += 1)
                        {
                            // j 0: the leading edge, the bar's inner end 3 mm in; j 1: the trailing edge
                            const xEdge = j == 0 ? xMin : xMax;
                            const zz = moldSectionZAt(sE.placed, xEdge + (j == 0 ? 1 : -1) * 3 * millimeter);
                            if (zz == undefined)
                            {
                                nTabsLost += 1;
                                continue;
                            }
                            const cEdge = moldCorePoint(sE, xEdge, 0.5 * (zz[0] + zz[1]));
                            const xc = cEdge[0];
                            const ym = cEdge[1];
                            const zm = cEdge[2];
                            const xA = j == 0 ? xc - tabOut : xc - tabIn;
                            const xB = j == 0 ? xc + tabIn : xc + tabOut;
                            const tid = id + ("tab" ~ k ~ "_" ~ e ~ "_" ~ j);
                            moldBox(context, tid, vector(xA, ym - tabW / 2, zm - tabT / 2), vector(xB, ym + tabW / 2, zm + tabT / 2));
                            const hit = evCollision(context, { "tools" : qCreatedBy(tid, EntityType.BODY), "targets" : segs[k] });
                            if (size(hit) == 0)
                            {
                                opDeleteBodies(context, tid + "off", { "entities" : qCreatedBy(tid, EntityType.BODY) });
                                nTabsLost += 1;
                                continue;
                            }
                            tabs = append(tabs, qCreatedBy(tid, EntityType.BODY));
                        }
                    }
                    if (size(tabs) > 0)
                    {
                        setAttribute(context, { "entities" : qUnion(tabs), "name" : "foilCoreBody", "attribute" : 1 });
                        try silent
                        {
                            opBoolean(context, id + ("tabbed" ~ k), {
                                        "tools" : qUnion(append(tabs, segs[k])),
                                        "operationType" : BooleanOperationType.UNION
                                    });
                            nTabs += size(tabs);
                        }
                        catch
                        {
                            opDeleteBodies(context, id + ("tabsOff" ~ k), { "entities" : qUnion(tabs) });   // a tab missed the section: that section goes out bare
                            nTabsLost += size(tabs);
                        }
                    }
                }
            }
            const segsN = milledCore ? evaluateQuery(context, qBodyType(qHasAttribute("foilCoreBody"), BodyType.SOLID)) : segs;
            for (var k = 0; k < size(segsN); k += 1)
                setProperty(context, { "entities" : segsN[k], "propertyType" : PropertyType.NAME, "value" : (definition.moldSource == MoldSource.WING ? "Wing" : "Stab") ~ (isPr ? " printed core " : " foam core ") ~ (k + 1) ~ " of " ~ size(segsN) ~ (isPr ? "" : " (milled)") });
            // the core's inlay keys (build 235): parts in their pockets, made after the sections are tabbed
            // and named so neither touches them
            if (size(coreKeys) > 0)
            {
                const kDimC = inlayDims(definition);
                for (var n = 0; n < size(coreKeys); n += 1)
                {
                    const ck = coreKeys[n];
                    const cq = inlayPrism(context, id + ("coreKey" ~ n), kDimC.key, ck.x, ck.y, true, ck.z0, ck.z1);
                    setAttribute(context, { "entities" : cq, "name" : "foilInlayKey", "attribute" : 1 });
                    setProperty(context, { "entities" : cq, "propertyType" : PropertyType.NAME, "value" : ck.name });
                }
            }
            coreNote = (isPr ? " | PRINTED CORE: " : " | MILLED CORE: ") ~ size(segsN) ~ (isPr ? " segment" : " section") ~ (size(segsN) == 1 ? "" : "s") ~ " for a " ~ fmt(bedLong / millimeter, 0) ~ (isPr ? "" : " x " ~ fmt(bedShort / millimeter, 0)) ~ " mm bed (sections less " ~ fmt(definition.skinPlies * tSkin, 2) ~
                " mm of skin each face, cap grooves " ~ fmt(capW * 100, 0) ~ "% chord wide)" ~
                (isPr ? "" : "; sheet " ~ fmt(definition.sheetThick / millimeter, 0) ~ " mm, the tallest section needs " ~ fmt(sheetNeed / millimeter, 0) ~ "; up to " ~ fmt(sheetY / millimeter, 0) ~ " mm along the span x " ~ fmt(sheetX / millimeter, 0) ~ " across" ~ (tabsOn ? " with the tabs; " ~ nTabs ~ " tabs " ~ fmt(definition.coreTabWide / millimeter, 0) ~ " x " ~ fmt(definition.coreTabThick / millimeter, 0) ~ " mm, " ~ fmt(tabOut / millimeter, 0) ~ " mm out of the leading and trailing edges and " ~ fmt(tabIn / millimeter, 0) ~ " mm in, at mid-height, the span ends left clean for the joints" ~ (nTabsLost > 0 ? " (" ~ nTabsLost ~ " left out where the bar would miss the section)" : "") : "; no tabs modelled (Hold tabs off): hold the sections in the CAM")) ~
                (coreInlays ? (preview ? "; puzzle inlays skipped in Preview" : coreInlayNote) : (dowelNote == "" ? (nSeg > 1 ? "; joints too thin for dowels" : "") : "; dowel holes 30 mm long across the joints, " ~ dowelNote ~ " (carbon or hardwood rod)")) ~
                (coreE0 > 0 ? "; two core halves starting " ~ fmt(coreClearY / millimeter, 0) ~ " mm from the centre, clear of the joint: the root zone between them is laid up solid" : "") ~
                (isPr ? "; print flat, glue end to end on a flat table, then lay up in this mold" : (tabsOn ? "; set the stock in your CAM so the tabs end in it, mill the top face, turn the stock over, mill the bottom face, cut the tabs and sand the leading and trailing edges back to shape" : "; mill the top face, turn the stock over, mill the bottom face") ~ ", then glue the sections end to end on the " ~ (coreInlays ? "inlay keys" : "dowels") ~ " and lay up in the part's mold");
            if (milledCore)
            {
                // no mold to build: the sections are the output. The layup and stiffness lines still apply
                var wM = [];
                if (sheetNeed > definition.sheetThick)
                    wM = append(wM, "the tallest section needs " ~ fmt(sheetNeed / millimeter, 0) ~ " mm of sheet (droop and twist across its length) against Sheet thick " ~ fmt(definition.sheetThick / millimeter, 0) ~ " - a thicker sheet, or shorter sections (smaller Printer X / Y)");
                if (min(sheetX, sheetY) > bedShort || max(sheetX, sheetY) > bedLong)
                    wM = append(wM, "a section of " ~ fmt(sheetY / millimeter, 0) ~ " x " ~ fmt(sheetX / millimeter, 0) ~ " mm with its tabs is over the " ~ fmt(bedLong / millimeter, 0) ~ " x " ~ fmt(bedShort / millimeter, 0) ~ " mm bed");
                if (nTabsLost > 0)
                    wM = append(wM, nTabsLost ~ " tabs left out (the bar would miss the section) - hold those sections in the CAM");
                if (sheetNeed > 0 * meter && definition.printerZ < definition.sheetThick + 2 * millimeter)
                    wM = append(wM, "the sheet is taller than Printer Z (the cutter must clear it)");
                for (var cw in coreInlayWarn)
                    wM = append(wM, cw);
                const msgM = "Core sections of the " ~ (definition.moldSource == MoldSource.WING ? "wing" : "stab") ~ ", milled from sheet" ~ coreNote ~ " | " ~ layupMsg ~ stiffMsg;
                if (size(wM) > 0)
                {
                    var w = "";
                    for (var t in wM)
                        w = w ~ (w == "" ? "" : "; ") ~ t;
                    foilNotice(context, id, moldNoticeKey, msgM ~ " | WARNING: " ~ w, true);
                }
                else
                    foilNotice(context, id, moldNoticeKey, msgM, false);
                return;
            }
        }
        if (coreMold && isFus)
        {
            // the fuselage's tail core as the cavity (build 219), carried straight out through both
            // ends of the block so a poured foam vents; parted along its own mid-height
            if (fusCore == undefined)
                throw regenError("No tail core to mold: " ~ (fusCoreWhy != "" ? fusCoreWhy : "set Core to Foam core in the layup group"), ["moldOf"]);
            const coreQ = fusCoreLoft(context, id + "fusCoreM", fusCore, fusCore.x0, fusCore.x1, 0 * meter, 0 * meter);
            setAttribute(context, { "entities" : coreQ, "name" : "foilCoreBody", "attribute" : 1 });
            setProperty(context, { "entities" : coreQ, "propertyType" : PropertyType.NAME, "value" : "Fuselage foam core" });
            const vL = f + 10 * millimeter;
            const vA = fusCoreLoft(context, id + "fusVentA", fusCore, fusCore.x0, fusCore.x0, -vL, 0.5 * millimeter);
            const vB = fusCoreLoft(context, id + "fusVentB", fusCore, fusCore.x1, fusCore.x1, -0.5 * millimeter, vL);
            setAttribute(context, { "entities" : qUnion([vA, vB]), "name" : "foilCoreVent", "attribute" : 1 });
            moldPart = coreQ;
            coreVent = qUnion([vA, vB]);
            coreNote = " | CORE MOLD: cavity is the fuselage's tail core, X " ~ fmt(fusCore.x0 * 1000, 0) ~ " to " ~ fmt(fusCore.x1 * 1000, 0) ~ " mm (the section less " ~ fmt(definition.skinPlies * tSkin, 2) ~ " mm of skin and the UD strips top and bottom), open at both ends so the expanding foam vents - trim the ends, wrap the strips and skins, lay up in the fuselage mold";
        }
        if (coreMold && !isFus)
        {
            // the foam core: sections offset inward by one face's skins, the UD caps' grooves cut in
            const skinFace = definition.skinPlies * tSkin * millimeter;
            const miniC = sectionDefFromModel(m);
            const coreR = moldCoreBody(context, id, m, miniC, vector(m.baseX, 0, m.baseZ) * meter, skinFace, capW, capF, tSkins * millimeter, definition.splitStations, definition.tipBias, f + 30 * millimeter, coreE0);
            if (coreR == undefined)
                throw regenError("No room for a foam core: the section is thinner than the skins plus 0.6 mm everywhere - fewer Skin plies, a lighter skin or a thicker section", ["skinPlies", "skinGsm"]);
            setProperty(context, { "entities" : coreR.body, "propertyType" : PropertyType.NAME, "value" : (definition.moldSource == MoldSource.WING ? "Wing" : "Stab") ~ " foam core" });
            moldPart = coreR.body;
            coreVent = coreR.vent;
            coreNote = " | CORE MOLD: cavity is the foam core (sections less " ~ fmt(definition.skinPlies * tSkin, 2) ~ " mm of skin each face, cap grooves " ~ fmt(capW * 100, 0) ~ "% chord wide), open at both tips so a poured foam can expand out; the core body is kept as a part";
        }
        // stab with the pad underneath AND its tail fairing (Mount side Bottom, Tail fairing on): the
        // pad-plane prism is written for a pad on top, so the mold is built on a copy mirrored in Z
        // about the stab pivot - its pad is on top and the model, the mount map and the section are
        // mirrored to match. A Y-symmetric stab molded upside down and turned over IS the stab (build
        // 130: the pad-under stab's curtain loft failed on build 128). Without the tail there is no
        // prism (build 201), so the mold keeps the stab's own orientation: the pad is a pocket in the
        // lower half and the countersink cones hang from the upper half (build 205, user: "the stab
        // is configured the opposite")
        var flipZ = false;
        var flipNote = "";
        if (!coreMold && definition.moldSource == MoldSource.STAB && stabRoot != undefined && stabRoot.padOn == 1 && stabRoot.padSide == -1 && stabRoot.tailOn != undefined && stabRoot.tailOn == 1)
        {
            flipZ = true;
            const zFlip = m.baseZ * meter;
            opPattern(context, id + "stabFlip", {
                        "entities" : definition.part,
                        "transforms" : [mirrorAcross(plane(vector(0 * meter, 0 * meter, zFlip), Z_DIRECTION))],
                        "instanceNames" : ["f"]
                    });
            moldPart = qCreatedBy(id + "stabFlip", EntityType.BODY);
            m.incidence = -m.incidence;
            m.washout = -m.washout;
            m.tipDrop = -m.tipDrop;
            m.rootDihedral = -m.rootDihedral;
            m.camber = -m.camber;
            m.inverted = m.inverted == 1 ? 0 : 1;
            var sr = stabRoot;
            sr.padSide = 1;
            sr.cskSide = stabRoot.cskSide == undefined ? undefined : -stabRoot.cskSide;
            sr.padZ = 2 * m.baseZ - stabRoot.padZ;
            sr.mountFarZ = stabRoot.mountFarZ == undefined ? undefined : 2 * m.baseZ - stabRoot.mountFarZ;
            sr.bottomZ = 2 * m.baseZ - stabRoot.topZ;
            sr.topZ = 2 * m.baseZ - stabRoot.bottomZ;
            var cm = [];
            for (var cp in stabRoot.contour)
                cm = append(cm, [cp[0], 2 * m.baseZ - cp[1]]);
            sr.contour = cm;
            stabRoot = sr;
            flipNote = " | pad underneath in the design: molded upside down (pad up) - turn the finished part over";
        }
        if (isMast)
        {
            // the mast laid on its side: its symmetry plane (y = 0) becomes the horizontal parting
            // plane at zPart
            opPattern(context, id + "mastCopy", {
                        "entities" : definition.part,
                        "transforms" : [transform(vector(0 * meter, 0 * meter, zPart)) * rotationAround(line(vector(0, 0, 0) * meter, X_DIRECTION), 90 * degree)],
                        "instanceNames" : ["flat"]
                    });
            moldPart = qCreatedBy(id + "mastCopy", EntityType.BODY);
        }
        const pbox = evBox3d(context, { "topology" : moldPart, "tight" : true });
        var lo = vector(pbox.minCorner[0] - f, pbox.minCorner[1] - f, pbox.minCorner[2] - definition.baseThick);
        const hi = vector(pbox.maxCorner[0] + f, pbox.maxCorner[1] + f, pbox.maxCorner[2] + definition.baseThick);
        // mast: the two halves stop at the plate's underside (0.5 mm into the plate, a locating
        // recess); the plate itself is formed by a third piece, a tray, built after the cavity cut.
        // Molding the plate in the halves made a 10 mm wide, 60 mm deep slot in each (user: three
        // parts, left, right and a top piece for the plate)
        // Build 241 (user: "the top plate should only be for the top of the plate. all features should be on the
        // mold sides so it releases"): the halves run on through the plate to its board face and form its edges and
        // underside with the mast; the third piece is a lid that forms only the board face, with straight pins for
        // the bolt holes along its own pull
        if (isMast)
            lo[1] = plateAct != undefined ? -plateAct.zBoard : -(mastM.baseZ + mastM.height + mastM.plateThick) * meter;

        // ---------------- parting surface: each section's camber line, extended to the block ----------------
        // The camber (mean) line lies inside the section everywhere, so a sheet through it meets the
        // part surface exactly at the leading and trailing edges - no tongue of mold under a cambered
        // nose or tail, whatever the camber, twist or droop. Beyond the LE/TE it continues straight
        // along the local chord direction out through the flange. Where the wing's tube socket
        // nacelle sits (a body of revolution aft of the root TE), the aft extension is aimed through
        // the nacelle axis instead, so the round section also splits on its diameter.
        const e = 5 * millimeter;
        var curtain = [];
        var curtainDown = [];
        var outLE = [];     // planform outline in plan (x, y) for the pinch-off groove, -Y to +Y
        var outTE = [];
        const seam = 0.4 * millimeter;
        var mini = {};
        var h = 1 * meter;
        var base = vector(0, 0, 0) * meter;
        var padMap;         // the stab's mount (foilStabRoot) when the parting must follow its pad plane
        var wTab;           // winglet parting table (build 151), when the part has a winglet
        var wY0 = 1 * meter;    // |y| where the winglet's bend starts; stations beyond it use wTab
        var fusFilled = false;
        var fusPart = [];                                                  // fuselage: the parting profile [(x, z)] the Foil fuselage publishes
        if (isMast)
        {
            // flat parting at zPart: the curtain is one box up to it; outline = mast rectangle + plate
            moldBox(context, id + "curtainM", vector(lo[0] - e, lo[1] - e, lo[2] - e), vector(hi[0] + e, hi[1] + e, zPart));
            curtain = [qCreatedBy(id + "curtainM", EntityType.BODY)];
            if (definition.grooveOn)
            {
                moldBox(context, id + "curtainDownM", vector(lo[0] - 2 * e, lo[1] - 2 * e, lo[2] - 2 * e), vector(hi[0] + 2 * e, hi[1] + 2 * e, zPart - definition.grooveDepth));
                curtainDown = [qCreatedBy(id + "curtainDownM", EntityType.BODY)];
            }
            const leX = mastM.leX * meter;
            const teX = (mastM.leX + mastM.chord) * meter;
            const leTop = (mastM.leXTop != undefined ? mastM.leXTop : mastM.leX) * meter;
            const teTop = leTop + (mastM.chordTop != undefined ? mastM.chordTop : mastM.chord) * meter;
            const yBase = -mastM.baseZ * meter;
            const yTopM = -(mastM.baseZ + mastM.height) * meter;
            outLE = [vector(leTop, lo[1] - 10 * millimeter), vector(leTop, yTopM)];      // closes outside the halves, so no groove across the root
            outTE = [vector(teTop, lo[1] - 10 * millimeter), vector(teTop, yTopM)];
            if (mastM.podOn == 1)
            {
                // the pod laid flat: a bar across the plan at y' = -podZ, Motor dia wide, nose to rear face
                const yP = -mastM.podZ * meter;
                const rP = mastM.podDia / 2 * meter;
                const xN = mastM.podNoseX * meter;
                const xRp = mastM.podRearX * meter;
                // the mast's edges at the pod band's two edges (the taper makes them a trapezoid)
                const sA = min(max((yP - rP - yBase) / (yTopM - yBase), 0), 1);
                const sB = min(max((yP + rP - yBase) / (yTopM - yBase), 0), 1);
                const leA = leX + (leTop - leX) * sA;
                const leB = leX + (leTop - leX) * sB;
                const teA = teX + (teTop - teX) * sA;
                const teB = teX + (teTop - teX) * sB;
                outLE = concatenateArrays([outLE, [vector(leA, yP - rP), vector(min(xN, leA), yP - rP), vector(min(xN, leB), yP + rP), vector(leB, yP + rP)]]);
                outTE = concatenateArrays([outTE, [vector(teA, yP - rP), vector(xRp, yP - rP), vector(xRp, yP + rP), vector(teB, yP + rP)]]);
            }
            outLE = append(outLE, vector(leX, yBase));
            outTE = append(outTE, vector(teX, yBase));
        }
        else if (isFus)
        {
            // fuselage (build 213): parted top and bottom along its sections' mid-height, the
            // profile the Foil fuselage publishes (partZ: flat under the nose at the hub's top, a
            // 0.2 mm step inside the body's front face, then the body, tail and seat mid-heights),
            // so the mast pocket is a core on the upper half and the tongue a pocket in the lower
            // (user: a left/right split cannot release the pocket). The nose's bolt holes and the
            // stab's tapped holes are vertical - a pin from each half otherwise - so they are filled
            // in the copy the cavity is cut from; drill and countersink after cure
            if (fusM.partZ == undefined)
                throw regenError("The Foil fuselage above is older than this Foil mold (no parting profile) - paste the whole Feature Studio over again so both are the same build");
            if (coreMold)
            {
                // the core's own mid-height, held flat beyond its ends
                fusPart = [vector((fusCore.x0 - 1) * meter, fusCore.zcs[0] * meter)];
                for (var k = 0; k < size(fusCore.xs); k += 1)
                    fusPart = append(fusPart, vector(fusCore.xs[k] * meter, fusCore.zcs[k] * meter));
                fusPart = append(fusPart, vector((fusCore.x1 + 1) * meter, fusCore.zcs[size(fusCore.zcs) - 1] * meter));
            }
            else
            {
            for (var p in fusM.partZ)
                fusPart = append(fusPart, vector(p[0] * meter, p[1] * meter));
            }
            if (!coreMold)
            {
            opPattern(context, id + "fusFill", {
                        "entities" : moldPart,
                        "transforms" : [identityTransform()],
                        "instanceNames" : ["c"]
                    });
            // every vertical hole the fuselage published ([x, z0, z1, r, rHead, cskSide, pinFrom]) is
            // filled 0.3 mm inside each face, at head radius where it is countersunk, so neither half
            // molds a full-size pin (build 214 filled through the whole block and cut holes in the
            // mold - user). With Bolt cones on, a tapered cone from the countersunk face and a
            // straight undersized pin for a tapped hole are added below, each from the half that
            // forms the face it starts on; drill to size after cure
            if (fusM.holes == undefined)
                throw regenError("The Foil fuselage above is older than this Foil mold (no hole list) - paste the whole Feature Studio over again so both are the same build");
            var fillsF = [qCreatedBy(id + "fusFill", EntityType.BODY)];
            var nF = 0;
            for (var j = 0; j < size(fusM.holes); j += 1)
            {
                const hF = fusM.holes[j];
                // a blind end (build 235: the eighth field, 1 top, -1 bottom) is filled 0.3 mm past it,
                // into the solid, so no closed void is left there to become a loose island of mold
                const blind = size(hF) > 7 ? hF[7] : 0;
                const z0F = hF[1] * meter + (blind == -1 ? -0.3 : 0.3) * millimeter;
                const z1F = hF[2] * meter + (blind == 1 ? 0.3 : -0.3) * millimeter;
                if (z1F - z0F < 1 * millimeter)
                    continue;
                const rF = max(hF[3], hF[4]) * meter + 0.1 * millimeter;
                fillsF = append(fillsF, moldPin(context, id + ("fusFillP" ~ j), vector(hF[0] * meter, 0 * meter, z0F), vector(hF[0] * meter, 0 * meter, z1F), rF));
                nF += 1;
            }
            if (nF > 0)
                opBoolean(context, id + "fusFillJoin", { "tools" : qUnion(fillsF), "operationType" : BooleanOperationType.UNION });
            fusFilled = true;
            }
            // the curtain: the profile extended to the block's ends, extruded across the block
            const zBaseF = lo[2] - e;
            var prof = [vector(lo[0] - e, zBaseF), vector(lo[0] - e, fusPartZ(fusPart, lo[0] - e))];
            for (var p in fusPart)
            {
                if (p[0] > lo[0] - e + 0.01 * millimeter && p[0] < hi[0] + e - 0.01 * millimeter)
                    prof = append(prof, p);
            }
            prof = append(prof, vector(hi[0] + e, fusPartZ(fusPart, hi[0] + e)));
            prof = append(prof, vector(hi[0] + e, zBaseF));
            var cRegions = [];
            var cSketches = [];
            const ySc = [lo[1] - e, hi[1] + e];
            for (var i = 0; i < 2; i += 1)
            {
                const sid = id + ("curtainF" ~ i);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, ySc[i], 0 * meter), -Y_DIRECTION, X_DIRECTION) });
                for (var q = 0; q < size(prof); q += 1)
                    skLineSegment(sk, "p" ~ q, { "start" : prof[q], "end" : prof[(q + 1) % size(prof)] });
                skSolve(sk);
                cRegions = append(cRegions, qSketchRegion(sid));
                cSketches = append(cSketches, qCreatedBy(sid, EntityType.BODY));
            }
            opLoft(context, id + "curtainFLoft", { "profileSubqueries" : cRegions });
            opDeleteBodies(context, id + "curtainFDel", { "entities" : qUnion(cSketches) });
            curtain = [qCreatedBy(id + "curtainFLoft", EntityType.BODY)];
            if (definition.grooveOn)
            {
                opPattern(context, id + "curtainDownF", {
                            "entities" : qCreatedBy(id + "curtainFLoft", EntityType.BODY),
                            "transforms" : [transform(vector(0 * meter, 0 * meter, -definition.grooveDepth))],
                            "instanceNames" : ["d"]
                        });
                curtainDown = [qCreatedBy(id + "curtainDownF", EntityType.BODY)];
            }
            // the outline for the groove: the part's width at the parting height, by rays in +-Y on
            // the filled copy at 41 stations along its length (no opening faces sideways at that height)
            const fillQ = fusFilled ? qCreatedBy(id + "fusFill", EntityType.BODY) : moldPart;
            const nO = 40;
            var minusSide = [];
            var plusSide = [];
            for (var k = 0; k <= nO; k += 1)
            {
                const x = pbox.minCorner[0] + (pbox.maxCorner[0] - pbox.minCorner[0]) * k / nO;
                const zk = fusPartZ(fusPart, x);
                var yMinus = pbox.minCorner[1];
                var yPlus = pbox.maxCorner[1];
                try silent
                {
                    const hA = evRaycast(context, { "entities" : fillQ, "ray" : line(vector(x, hi[1] + 1 * meter, zk), vector(0, -1, 0)), "closest" : true });
                    const hB = evRaycast(context, { "entities" : fillQ, "ray" : line(vector(x, lo[1] - 1 * meter, zk), vector(0, 1, 0)), "closest" : true });
                    if (size(hA) > 0 && size(hB) > 0)
                    {
                        yPlus = hA[0].intersection[1];
                        yMinus = hB[0].intersection[1];
                    }
                }
                const xi = k == 0 ? x + 0.5 * millimeter : (k == nO ? x - 0.5 * millimeter : x);
                minusSide = append(minusSide, vector(xi, yMinus));
                plusSide = append(plusSide, vector(xi, yPlus));
            }
            outLE = minusSide;
            outTE = plusSide;
        }
        else
        {
        mini = sectionDefFromModel(m);
        h = m.span / 2 * meter;
        base = vector(m.baseX, 0, m.baseZ) * meter;
        var etas = [];
        for (var i = 0; i < definition.splitStations; i += 1)
            etas = append(etas, 1 - (1 - i / (definition.splitStations - 1)) ^ definition.tipBias);
        if (sockOn)
        {
            const rN = nacW / 2;
            if (rN < h)
                etas = append(etas, rN / h);
            // parting stations across the faired tail's web, out to its reach and a little past it, the plan radius's
            // quarter circle included
            if (sockReach > rN && sockReach < h)
            {
                for (var k = 1; k <= 5; k += 1)
                    etas = append(etas, (rN + (sockReach - rN) * k / 5) / h);
                if (sockReach + 3 * millimeter < h)
                    etas = append(etas, (sockReach + 3 * millimeter) / h);
            }
        }
        if (hubOn && hub.plan != undefined && hub.plan.on == 1)
        {
            // the hub's block and its faired tail behind the trailing edge: stations across them so the outline
            // (the pinch-off groove) follows them (build 241)
            const yr = max(hub.reach, hub.width / 2) * meter;
            for (var k = 1; k <= 8; k += 1)
                if (yr * k / 8 < h)
                    etas = append(etas, yr * k / 8 / h);
            if (yr + 3 * millimeter < h)
                etas = append(etas, (yr + 3 * millimeter) / h);
            if (hub.width / 2 * meter + 0.5 * millimeter < h)
                etas = append(etas, (hub.width / 2 * meter + 0.5 * millimeter) / h);
        }
        if (!isMast && m.tipOn == 1)
        {
            // twelve parting stations across the section blend (build 167). Build 169 tried adding
            // every loft station instead and broke molds that had passed; reverted in 171
            for (var k = 0; k <= 12; k += 1)
                etas = append(etas, m.blendFrom + (1 - m.blendFrom) * k / 12);
        }
        if (!isMast && m.bumpOn == 1)
        {
            // six parting stations per bump pitch, as the foil itself has: a ruled parting between a
            // peak and a trough would cut the corner of the wavy leading edge
            var yb = m.bumpFrom * h;
            const yEnd = min(m.bumpTo * h, h - 0.5 * millimeter);
            while (yb <= yEnd)
            {
                etas = append(etas, yb / h);
                yb += m.bumpPitch * meter / 6;
            }
        }
        // the span line's drop (build 235): the parting is ruled between its stations while the drop law
        // curves, so it strays from the law between them - 0.6 mm below a 50 mm S-curve at y 33 with the
        // default stations, outside a 0.8 mm trailing edge once the loft follows the law. Segments whose
        // chord strays more than 0.15 mm are halved, never into pieces under 3 mm, only inboard of a winglet
        etas = moldDropStations(m, etas);
        // stab mount: two stations just INSIDE the pad's edge, so the parting steps from the pad plane
        // to the camber line over 0.4 mm and that step face lies inside the part, where the cavity cut
        // removes it. Build 87 straddled the edge (+/- 0.4 mm) and left a 0.4 mm lip of the lower half
        // overhanging the skin beside the pad - unattached slivers, and an undercut
        padMap = (!coreMold && definition.moldSource == MoldSource.STAB && stabRoot != undefined && stabRoot.padOn == 1 && stabRoot.padSide != undefined && stabRoot.padRampPct != undefined) ? stabRoot : undefined;
        etas = sort(etas, function(a, b) { return a - b; });
        var uniq = [];
        for (var eta in etas)
            if (size(uniq) == 0 || eta - uniq[size(uniq) - 1] > 1e-4)
                uniq = append(uniq, eta);
        etas = uniq;
        // world y per curve, root outwards; the beyond-tip curve repeats the tip section. No station
        // sits exactly on the part's own seams - the root plane (mirror join edges) or the tip end
        // face plane: a sheet seam lying in a face or on edges of the part makes the boolean invalid
        var plus = [];
        for (var eta in etas)
            plus = append(plus, [eta, eta == 0 ? seam : (eta == 1 ? h - seam : h * eta)]);
        if (!isMast && m.wingletOn == 1)
        {
            // stations through the bend (its start and four along the arc) so the ruled curtain
            // follows the winglet, the tip station just inside the tip, and one beyond the tip
            // continued straight along the winglet, far enough in y to clear the block
            const arcEta = m.wingletR * meter * m.wingletAngle / h;
            const tipF = wingletFrame(m, 1);
            const sEnd = h + max((hi[1] + e - tipF.y) / max(cos(tipF.phi), 0.2), 5 * millimeter) + 5 * millimeter;
            wTab = moldWingletTable(m, mini, base, sEnd);
            wY0 = wTab.yStart;
            // inboard stations keep their y = eta h; those past the bend take the path's y; the eta 1
            // station moves just inside the tip; one station beyond the tip at the block edge
            var inner = [];
            for (var p in plus)
                if (p[0] < 1 - 1e-6)
                    inner = append(inner, [p[0], p[0] > m.wingletEta ? wingletFrame(m, p[0]).y : p[1]]);
            plus = inner;
            for (var k = 0; k <= 4; k += 1)
            {
                const ek = min(m.wingletEta + arcEta * k / 4, 1 - seam / h);
                plus = append(plus, [ek, wingletFrame(m, ek).y]);
            }
            plus = append(plus, [1 - seam / h, wingletFrame(m, 1 - seam / h).y]);
            plus = append(plus, [1, hi[1] + e]);
            plus = sort(plus, function(a, b) { return (a[1] - b[1]) / meter; });
            var pu = [];
            for (var p in plus)
                if (size(pu) == 0 || p[1] - pu[size(pu) - 1][1] > 0.2 * millimeter)
                    pu = append(pu, p);
            plus = pu;
        }
        else
            plus = append(plus, [1, hi[1] + e]);
        var rows = [];
        if (m.mirror == 1)
        {
            for (var i = size(plus) - 1; i >= 0; i -= 1)
                rows = append(rows, [plus[i][0], -plus[i][1]]);
        }
        else
            rows = append(rows, [0, lo[1] - e]);
        rows = concatenateArrays([rows, plus]);

        // Built as a SOLID under the camber surface (closed planar profiles: camber-line spline plus
        // three lines down to a floor below the block - the same sketch-and-loft pattern as the foil
        // itself), then booleaned with the block: lower half = block AND curtain, upper = block minus
        // lower. A surface loft through the open curves was refused by Onshape (LOFT_INVALID).
        const zFloor = lo[2] - e;
        var profiles = [];
        var sketchBodies = [];
        for (var i = 0; i < size(rows); i += 1)
        {
            const eta = rows[i][0];
            const y = rows[i][1];
            var pp;
            if (wTab != undefined && abs(y) > wY0 + 0.01 * millimeter)
                pp = moldPartingPointsWinglet(wTab, abs(y), y < 0 * meter ? -1 : 1, lo[0] - e, hi[0] + e);
            else
                pp = moldPartingPointsPad(m, mini, eta, y, base, lo[0] - e, hi[0] + e, sockOn && abs(y) <= max(nacW / 2, sockReach) * 1.0001 ? sock : undefined, undefined);
            if (abs(y) <= h + seam)
            {
                var teX = pp.camber[size(pp.camber) - 1][0];
                if (sockOn)
                {
                    // nacelle in plan: full rear-face x within its radius, faired back to the TE over R + 20 mm
                    const rN = nacW / 2;
                    const sBump = min(max(1 - (abs(y) - rN) / (rN + 20 * millimeter), 0), 1);
                    teX = teX + (max(sock.rearX * meter, teX) - teX) * sBump;
                    // a faired tail (build 241): the web and its plan radius behind the trailing edge
                    if (sock.web != undefined && sock.web.on == 1 && sock.web.edge != undefined)
                    {
                        const tx = moldPlanTailX(sock.web, abs(y) / meter);
                        if (tx > -1)
                            teX = max(teX, tx * meter);
                    }
                }
                if (hubOn && hub.plan != undefined && hub.plan.on == 1)
                {
                    // the hub's block past the trailing edge and its fairing's tail (build 241, user: the pinch-off
                    // groove did not follow the fairing)
                    const tx = moldPlanTailX(hub.plan, abs(y) / meter);
                    if (tx > -1)
                        teX = max(teX, tx * meter);
                }
                if (padMap != undefined && padMap.tailOn == 1 && abs(y) <= padMap.padWidth / 2 * meter)
                {
                    // tail fairing plan: half-width hE + (hW - hE)(1 - t)^exp -> the end x at this y
                    const hW = padMap.padWidth / 2 * meter;
                    const hE = padMap.tailEndWidth / 2 * meter;
                    const tt = abs(y) <= hE ? 1 : 1 - ((abs(y) - hE) / (hW - hE)) ^ (1 / padMap.tailExp);
                    teX = max(teX, padMap.teX * meter + padMap.tailLength * meter * tt);
                }
                outLE = append(outLE, vector(pp.camber[0][0], y));
                outTE = append(outTE, vector(teX, y));
            }
            const sid = id + ("pc" ~ i);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, y, 0 * meter), -Y_DIRECTION, X_DIRECTION) });
            // sketch (u, v) = world (x, z): horizontal line to the LE, camber spline LE -> TE,
            // horizontal line from the TE, then down, floor, up. LE and TE are vertices so the loft
            // matches them station to station and the parting tracks the camber line in between
            var sp = [];
            for (var p in pp.camber)
                sp = append(sp, vector(p[0], p[2]));
            const front = vector(pp.front[0], pp.front[2]);
            const back = vector(pp.aft[0], pp.aft[2]);
            skLineSegment(sk, "front", { "start" : front, "end" : sp[0] });
            skFitSpline(sk, "camber", { "points" : sp });
            if (pp.aftPts != undefined && size(pp.aftPts) > 0)      // the winglet stations carry none (build 241: size(undefined) on a winglet wing)
            {
                // a faired socket's tail: the parting on the web's law, then on to the block end
                var ap = [sp[size(sp) - 1]];
                for (var q in pp.aftPts)
                    ap = append(ap, vector(q[0], q[2]));
                skFitSpline(sk, "aftCurve", { "points" : ap });
                skLineSegment(sk, "aft", { "start" : ap[size(ap) - 1], "end" : back });
            }
            else
                skLineSegment(sk, "aft", { "start" : sp[size(sp) - 1], "end" : back });
            skLineSegment(sk, "down", { "start" : back, "end" : vector(back[0], zFloor) });
            skLineSegment(sk, "floor", { "start" : vector(back[0], zFloor), "end" : vector(front[0], zFloor) });
            skLineSegment(sk, "up", { "start" : vector(front[0], zFloor), "end" : front });
            skSolve(sk);
            profiles = append(profiles, qSketchRegion(sid));
            sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
        }
        // one ruled loft per pair of neighbouring stations: a two-profile loft cannot fold, which an
        // interpolating loft through 30-odd profiles of very different proportions did (LOFT_INVALID)
        for (var i = 0; i + 1 < size(profiles); i += 1)
        {
            const segId = id + ("seg" ~ i);
            opLoft(context, segId, { "profileSubqueries" : [profiles[i], profiles[i + 1]] });
            curtain = append(curtain, qCreatedBy(segId, EntityType.BODY));
        }
        // stab mount: the parting over the pad's plan is the pad-side skin (nose, ramp, pad plane out
        // to the block edge), as a prism with exactly vertical walls 0.05 mm inside the pad's own
        // walls, added to the curtain. The whole section, the pad walls and the tail fairing then sit
        // in the half away from the pad and the other half forms only the flat face (the production layout).
        // Build 87/88 did this with extra stations at the pad edge, whose sloped step face showed as
        // slivers along the T; a prism has no such face
        // Only with the tail fairing (build 201): the prism exists to keep the tail's rounded far face
        // below the parting. A pad alone is a pocket in the pad-side half - vertical walls, a faired
        // ramp - and needs no climb; with the climb the other half grew a block down to the pad plane
        // (user: "a block in the mold on top" on a pad-under stab with no tail)
        const padClimb = padMap != undefined && padMap.tailOn != undefined && padMap.tailOn == 1;
        if (padClimb)
        {
            const pp = moldPartingPointsPad(m, mini, seam / h, 0 * meter, base, lo[0] - e, hi[0] + e, undefined, padMap);
            // 0.2 mm inside the pad wall: build 89's 0.05 mm left near-coincident faces that made the
            // lower cavity cut BOOLEAN_INVALID; build 88's 0.1-0.5 mm step cut cleanly. The lower half's
            // T is 0.4 mm narrower than the pad and the upper half's slot beside the pad is 0.2 mm,
            // which prints solid and only marks the pad's top edge
            const hpW = padMap.padWidth / 2 * meter - 0.2 * millimeter;
            var padProfiles = [];
            const yP = [-hpW, hpW];
            for (var i = 0; i < 2; i += 1)
            {
                const sid = id + ("padPrism" ~ i);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, yP[i], 0 * meter), -Y_DIRECTION, X_DIRECTION) });
                // the prism top sits 0.15 mm under the pad-side skin (toward the section), so no mold
                // face coincides with the part's flat pad face or its ramp: the lower cavity cut was
                // BOOLEAN_INVALID with them coincident. The upper half then forms the top 0.15 mm of
                // the pad - a recess too shallow to print, so the halves still close on the pad face
                const dip = 0.15 * millimeter * (padMap.padSide == 1 ? -1 : 1);
                var sp = [];
                for (var q in pp.camber)
                    sp = append(sp, vector(q[0], q[2] + dip));
                const front = vector(pp.front[0], pp.front[2] + dip);
                const back = vector(pp.aft[0], pp.aft[2] + dip);
                skLineSegment(sk, "front", { "start" : front, "end" : sp[0] });
                skFitSpline(sk, "skin", { "points" : sp });
                skLineSegment(sk, "aft", { "start" : sp[size(sp) - 1], "end" : back });
                skLineSegment(sk, "down", { "start" : back, "end" : vector(back[0], zFloor) });
                skLineSegment(sk, "floor", { "start" : vector(back[0], zFloor), "end" : vector(front[0], zFloor) });
                skLineSegment(sk, "up", { "start" : vector(front[0], zFloor), "end" : front });
                skSolve(sk);
                padProfiles = append(padProfiles, qSketchRegion(sid));
                sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
            }
            opLoft(context, id + "padPrismLoft", { "profileSubqueries" : padProfiles });
            curtain = append(curtain, qCreatedBy(id + "padPrismLoft", EntityType.BODY));
        }
        opDeleteBodies(context, id + "deleteCurves", { "entities" : qUnion(sketchBodies) });
        if (definition.grooveOn)
        {
            // the same curtain lowered by Groove depth: its top is the groove floor
            opPattern(context, id + "curtainDown", {
                        "entities" : qUnion(curtain),
                        "transforms" : [transform(vector(0 * meter, 0 * meter, -definition.grooveDepth))],
                        "instanceNames" : ["d"]
                    });
            curtainDown = [qCreatedBy(id + "curtainDown", EntityType.BODY)];
        }
        }

        // ---------------- halves and cavity ----------------
        // upper = block minus everything under the camber surface; lower = a second block minus upper
        // every solid of this feature EXCEPT the lowered curtain kept for the groove: it touches the
        // block bottom, so moldHalves took it for a lower body and the cavity and channel cuts carved
        // it too - the pod pocket left a core in it that was severed, joined into the pod plug, and
        // gave the plug the curtain's identity, so the groove's gFloor consumed the plug as a tool
        // the mold's own solids: not the pinch-off tool, and not a core body this feature made (the
        // core mold's cavity master, or the printed core's segments), which live on as parts
        // (build 235: nor the puzzle inlay keys, parts that sit in the tiles' pockets)
        const solids = qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                                    qUnion([qCreatedBy(id + "curtainDown", EntityType.BODY), qCreatedBy(id + "curtainDownM", EntityType.BODY), qHasAttribute("foilCoreBody"), qHasAttribute("foilInlayKey")]));
        moldBox(context, id + "blockA", lo, hi);
        // bag closing: round the block's outer edges before anything is cut from it, so every tile
        // inherits them and the joint and parting faces stay sharp
        const roundOn = definition.closing == MoldClosing.BAG && definition.edgeRound > 0.1 * millimeter;
        var roundFailed = false;
        if (roundOn)
        {
            try silent { opFillet(context, id + "roundA", { "entities" : qCreatedBy(id + "blockA", EntityType.EDGE), "radius" : definition.edgeRound }); }
            catch { roundFailed = true; }
        }
        opBoolean(context, id + "upperCut", {
                    "tools" : qUnion(curtain),
                    "targets" : qCreatedBy(id + "blockA", EntityType.BODY),
                    "operationType" : BooleanOperationType.SUBTRACTION
                });
        moldBox(context, id + "blockB", lo, hi);
        if (roundOn)
        {
            try silent { opFillet(context, id + "roundB", { "entities" : qCreatedBy(id + "blockB", EntityType.EDGE), "radius" : definition.edgeRound }); }
            catch { roundFailed = true; }
        }
        var hv = moldHalves(context, solids, lo, hi);      // upper only: the fresh block touches both faces
        opBoolean(context, id + "lowerCut", {
                    "tools" : hv.upper,
                    "targets" : qCreatedBy(id + "blockB", EntityType.BODY),
                    "operationType" : BooleanOperationType.SUBTRACTION,
                    "keepTools" : true
                });
        // the cavity is cut from the part as it stands (build 195): the socket's bore, its countersunk
        // bolt holes, the hub's pocket, holes and fillet mold exactly as modelled, direct edits
        // included; what that leaves in the bolt holes is dealt with after the cut, below
        const plugOn = sockOn && definition.plugOn;
        var cavTool = coreVent != undefined ? qUnion([moldPart, coreVent]) : moldPart;
        if (fusFilled)
            cavTool = qCreatedBy(id + "fusFill", EntityType.BODY);
        if (plugOn && definition.plugExt > f - 3 * millimeter)
            throw regenError("Plug extension must be at most Flange width - 3 mm - the plug channel lives in the rear flange", ["plugExt", "flangeWidth"]);
        // stab with bolt cones: fill the through holes in the copy the cavity is cut from, so neither
        // half molds a pin (build 178: a pin from the half away from the countersink met the cone and
        // could not release). The countersink itself stays: it molds as a cone in the countersunk
        // half, wide at the skin, and the bolt cone below continues it
        var stabFilled = false;
        var rootSecS;
        var cskSideM = 0;
        if (conesOn)
        {
            rootSecS = moldRootSection(m, mini, base);                    // world (x, z) of the root section, tail included
            cskSideM = stabRoot.cskSide != undefined && stabRoot.cskSide != 0 ? stabRoot.cskSide : (stabRoot.padOn == 1 ? -stabRoot.padSide : -1);
            opPattern(context, id + "stabFill", {
                        "entities" : moldPart,
                        "transforms" : [identityTransform()],
                        "instanceNames" : ["c"]
                    });
            var fillsS = [qCreatedBy(id + "stabFill", EntityType.BODY)];
            // the fill covers the countersink too (head diameter), so no part of its void is left for
            // either half; the countersink is molded by the cone below, from the countersunk half
            const rHeadF = stabRoot.headDia != undefined ? stabRoot.headDia / 2 * meter : 0 * meter;
            const rF = max(stabRoot.boltDia / 2 * meter, rHeadF) + 0.1 * millimeter;
            for (var j = 0; j < size(stabRoot.boltX); j += 1)
            {
                const bx = stabRoot.boltX[j] * meter;
                var zLoS = 1 * meter;
                var zHiS = -1 * meter;
                for (var i = 0; i < size(rootSecS); i += 1)
                {
                    if (abs(rootSecS[i][0] - bx) <= rF + 0.5 * millimeter)
                    {
                        zLoS = min(zLoS, rootSecS[i][1]);
                        zHiS = max(zHiS, rootSecS[i][1]);
                    }
                }
                if (zHiS < zLoS)
                    continue;                                                   // behind the root section (in the tail): left as the part has it
                // through the pad too, when the pad sits over this bolt
                if (stabRoot.padOn == 1)
                {
                    // through the pad too, on whichever face it is (build 205: a pad-under stab is no
                    // longer flipped unless it has a tail fairing)
                    const farP = (stabRoot.mountFarZ != undefined ? stabRoot.mountFarZ : stabRoot.padZ) * meter;
                    if (stabRoot.padSide == -1)
                        zLoS = min(zLoS, farP);
                    else
                        zHiS = max(zHiS, farP);
                }
                // 0.3 mm inside each skin: the countersink cone covers the sliver of void at the
                // countersunk skin, and the 0.3 mm stub left at the far skin is a straight pin the
                // drill removes; ending outside the skins would pocket the mold floor instead
                if (zHiS - zLoS > 1 * millimeter)
                    fillsS = append(fillsS, moldPin(context, id + ("stabFillPin" ~ j), vector(bx, 0 * meter, zLoS + 0.3 * millimeter), vector(bx, 0 * meter, zHiS - 0.3 * millimeter), rF));
            }
            if (size(fillsS) > 1)
            {
                opBoolean(context, id + "stabFillJoin", { "tools" : qUnion(fillsS), "operationType" : BooleanOperationType.UNION });
                cavTool = qCreatedBy(id + "stabFill", EntityType.BODY);
                stabFilled = true;
            }
            else
                opDeleteBodies(context, id + "stabFillUnused", { "entities" : qCreatedBy(id + "stabFill", EntityType.BODY) });
        }
        // wing hub bolted from the underside (build 235): its through holes and their countersinks are
        // filled in the copy the cavity is cut from, as the stab's are, so neither half molds a pin; the
        // lower half then forms each countersink and a tapered cone to Cone web under the pocket floor
        // (below). The fill starts 0.3 mm above the highest point of the underside round the head (ray
        // casts beside it, so it never pokes out of the skin) and stops 0.3 mm under the floor
        const hubUnder = hubOn && hub.boltSide != undefined && (hub.boltSide == "UNDERSIDE" || hub.boltSide == "NUTS");
        const hubNuts = hubOn && hub.boltSide != undefined && hub.boltSide == "NUTS" && hub.recess != undefined && size(hub.recess) > 0;
        var hubFilled = false;
        if (hubUnder && definition.conesOn == true && !stabFilled && hub.boltX != undefined && size(hub.boltX) > 0 && hub.underZ != undefined && size(hub.underZ) == size(hub.boltX))
        {
            opPattern(context, id + "hubFill", {
                        "entities" : moldPart,
                        "transforms" : [identityTransform()],
                        "instanceNames" : ["c"]
                    });
            var fillsH = [qCreatedBy(id + "hubFill", EntityType.BODY)];
            const rHoleH = hub.holeDia / 2 * meter;
            const rHeadH = hubNuts ? hub.recess[0][0] * meter : (hub.boltHead != undefined && hub.boltHead > 0 ? hub.boltHead / 2 : hub.holeDia) * meter;
            const rFH = max(rHoleH, rHeadH) + 0.1 * millimeter;
            const zFH = hub.floorZ * meter;
            const offs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
            for (var j = 0; j < size(hub.boltX); j += 1)
            {
                const bx = hub.boltX[j] * meter;
                var zHiU = hub.underZ[j] * meter;
                for (var o in offs)
                {
                    const r = moldRayZ(context, moldPart, bx + o[0] * (rFH + 0.5 * millimeter), o[1] * (rFH + 0.5 * millimeter), -1 * meter, true);
                    if (r.hit && r.z < zFH - 1 * millimeter)
                        zHiU = max(zHiU, r.z);
                }
                if (zFH - zHiU > 1.6 * millimeter)
                    fillsH = append(fillsH, moldPin(context, id + ("hubFillPin" ~ j), vector(bx, 0 * meter, zHiU + 0.3 * millimeter), vector(bx, 0 * meter, zFH - 0.3 * millimeter), rFH));
            }
            if (size(fillsH) > 1)
            {
                opBoolean(context, id + "hubFillJoin", { "tools" : qUnion(fillsH), "operationType" : BooleanOperationType.UNION });
                cavTool = qCreatedBy(id + "hubFill", EntityType.BODY);
                hubFilled = true;
            }
            else
                opDeleteBodies(context, id + "hubFillUnused", { "entities" : qCreatedBy(id + "hubFill", EntityType.BODY) });
        }
        // one half at a time, so a failure names the half. The usual cause is the part's tip: the cap
        // thins the section to Cap end % of an already thin tip chord, and a boolean through a
        // sliver a few hundredths of a millimetre thick is invalid - and unmouldable in carbon anyway
        const endChord = isFlat ? 0 : m.c0 * chordFactor(m, m.capEta == undefined ? 1 : m.capEta) * 1000;   // chord at the cap start
        const tipT = isFus ? 5 : (isMast ? mastM.te * 1000 : m.tipT * endChord);                   // mm at the cap start (mast: its TE; fuselage: no thin end)
        const capEndT = isFlat ? tipT : tipT * (m.capOn == 1 ? (m.capEndT == undefined ? m.capEnd : m.capEndT) : 1);                       // mm at the very end of the cap (with plan rounding the thickness law is divided by the chord shrink, so this holds either way)
        const tipAdvice = " Tip section is " ~ fmt(tipT, 2) ~ " mm thick at the cap start, " ~ fmt(capEndT, 2) ~ " mm at its end: raise End ratio (or turn on Min tip), Cap end % or Tip thick % in the " ~
            (definition.moldSource == MoldSource.WING ? "Foil wing" : "Foil stabiliser") ~ " feature (1 mm or more molds reliably), or try more Split stations";
        // mast (build 241, user): the halves form every feature that goes right through the plate - its bolt holes, their
        // pins and countersink cones, as modelled - and the lid only the features that open onto the plate's top face
        // without going right through (a rebate, slots, a cable channel). Those are found as the air inside the plate's
        // footprint (its outline swept through its thickness), less the part and the bolt holes, that opens onto the
        // board face; they are left void in the halves (added to their cavity tool) and given to the lid
        var mastFilled = false;
        var mastTopVoids = [];      // the plate's top-face features, given to the lid
        var mastTopVol = 0 * meter ^ 3;
        var plStage = "";
        var plNote = "";
        if (isMast && plateAct != undefined)
        {
            // worked on an upright copy of the mast (the sequence checked by evaluation on the user's plate), then turned
            // flat with the mast copy's own transform. Every boolean's result is queried by its own id as well
            var plDone = false;
            try silent
            {
                const wLo = vector(plateAct.x0, plateAct.y0, plateAct.zTop);
                const wHi = vector(plateAct.x1, plateAct.y1, plateAct.zBoard);
                plStage = "the footprint";
                opPattern(context, id + "plWPart", { "entities" : definition.part, "transforms" : [identityTransform()], "instanceNames" : ["c"] });
                opPattern(context, id + "plWPart2", { "entities" : definition.part, "transforms" : [identityTransform()], "instanceNames" : ["c"] });
                moldBox(context, id + "plWBox", wLo, wHi);
                opBoolean(context, id + "plWInt", { "tools" : qUnion([qCreatedBy(id + "plWPart", EntityType.BODY), qCreatedBy(id + "plWBox", EntityType.BODY)]), "operationType" : BooleanOperationType.INTERSECTION });
                const pe = qUnion([qCreatedBy(id + "plWPart", EntityType.BODY), qCreatedBy(id + "plWBox", EntityType.BODY), qCreatedBy(id + "plWInt", EntityType.BODY)]);
                const tZ = wHi[2] - wLo[2];
                const nSh = max(2, ceil(tZ / (0.75 * millimeter)));
                var trs = [];
                var nms = [];
                for (var k = -nSh; k <= nSh; k += 1)
                {
                    if (k == 0)
                        continue;
                    trs = append(trs, transform(vector(0 * meter, 0 * meter, tZ * k / nSh)));
                    nms = append(nms, "s" ~ (k + nSh));
                }
                opPattern(context, id + "plWShift", { "entities" : pe, "transforms" : trs, "instanceNames" : nms });
                opBoolean(context, id + "plWJoin", { "tools" : qUnion([pe, qCreatedBy(id + "plWShift", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
                const fp = qUnion([pe, qCreatedBy(id + "plWShift", EntityType.BODY), qCreatedBy(id + "plWJoin", EntityType.BODY)]);
                // the columns outside the footprint (through features: the outline's corners, a narrower edge) stay with the halves
                plStage = "the through columns";
                moldBox(context, id + "plWThru", wLo, wHi);
                opBoolean(context, id + "plWThruCut", { "tools" : fp, "targets" : qCreatedBy(id + "plWThru", EntityType.BODY), "operationType" : BooleanOperationType.SUBTRACTION });
                const thru = qUnion([qCreatedBy(id + "plWThru", EntityType.BODY), qCreatedBy(id + "plWThruCut", EntityType.BODY)]);
                // the bolt holes and their countersinks: the halves' (as modelled), kept out of the lid's share
                plStage = "the bolt holes";
                var cutters = [thru];
                if (mastM.trackSpacing != undefined && mastM.boltsPerRow != undefined && mastM.boltsPerRow > 0)
                {
                    const xcF = (mastM.plateXc != undefined ? mastM.plateXc : mastM.leX + mastM.chord / 2) * meter;
                    const rowSpanF = (mastM.boltsPerRow - 1) * mastM.plateBoltPitch * meter;
                    const rFill = (mastM.plateHeadDia != undefined && mastM.countersink == 1 ? mastM.plateHeadDia / 2 : mastM.plateBoltDia / 2) * meter + 0.2 * millimeter;
                    var nF = 0;
                    for (var row = 0; row < 2; row += 1)
                    {
                        for (var j = 0; j < mastM.boltsPerRow; j += 1)
                        {
                            const bx = xcF - rowSpanF / 2 + j * mastM.plateBoltPitch * meter;
                            const by = (row == 0 ? -1 : 1) * mastM.trackSpacing / 2 * meter;
                            cutters = append(cutters, moldPin(context, id + ("plWHole" ~ nF), vector(bx, by, wLo[2] - 1 * millimeter), vector(bx, by, wHi[2] + 1 * millimeter), rFill));
                            nF += 1;
                        }
                    }
                }
                // the air: the plate's box less the part, the bolt holes and the through columns
                plStage = "the air in the plate";
                moldBox(context, id + "plWEnv", wLo, wHi);
                setAttribute(context, { "entities" : qCreatedBy(id + "plWEnv", EntityType.BODY), "name" : "foilPlateEnv", "attribute" : 1 });
                opBoolean(context, id + "plWEnvCut", { "tools" : qCreatedBy(id + "plWPart2", EntityType.BODY), "targets" : qHasAttribute("foilPlateEnv"), "operationType" : BooleanOperationType.SUBTRACTION });
                opBoolean(context, id + "plWEnvCut2", { "tools" : qUnion(cutters), "targets" : qHasAttribute("foilPlateEnv"), "operationType" : BooleanOperationType.SUBTRACTION });
                // the pockets that open onto the board face are the lid's
                plStage = "sorting the pockets";
                var rest = [];
                for (var b in evaluateQuery(context, qHasAttribute("foilPlateEnv")))
                {
                    const bb = evBox3d(context, { "topology" : b, "tight" : true });
                    var vol = 0 * meter ^ 3;
                    try silent
                    {
                        vol = evVolume(context, { "entities" : b });
                    }
                    if (bb.maxCorner[2] > wHi[2] - 0.05 * millimeter && vol > 0.5 * millimeter ^ 3)
                    {
                        mastTopVoids = append(mastTopVoids, b);
                        mastTopVol += vol;
                    }
                    else
                        rest = append(rest, b);
                }
                if (size(rest) > 0)
                    opDeleteBodies(context, id + "plWRest", { "entities" : qUnion(rest) });
                // a share bigger than a fifth of the plate's box is not pockets (the part did not come out of the box)
                const boxVol = (wHi[0] - wLo[0]) * (wHi[1] - wLo[1]) * (wHi[2] - wLo[2]);
                if (mastTopVol > 0.2 * boxVol)
                {
                    plNote = " (the plate's top-face pockets came out at " ~ fmt(mastTopVol / boxVol * 100, 0) ~ " % of the plate's box, too big to be pockets - left to the halves; send this line)";
                    opDeleteBodies(context, id + "plWBig", { "entities" : qUnion(mastTopVoids) });
                    mastTopVoids = [];
                    mastTopVol = 0 * meter ^ 3;
                }
                if (size(mastTopVoids) > 0)
                {
                    // turned flat with the mast copy, then left void in the halves and given to the lid
                    plStage = "turning the pockets flat";
                    opTransform(context, id + "plWFlat", { "bodies" : qUnion(mastTopVoids),
                                "transform" : transform(vector(0 * meter, 0 * meter, zPart)) * rotationAround(line(vector(0, 0, 0) * meter, X_DIRECTION), 90 * degree) });
                    setAttribute(context, { "entities" : qHasAttribute("foilPlateEnv"), "name" : "foilMastTopVoid", "attribute" : 1 });
                    opPattern(context, id + "mastFill", { "entities" : cavTool, "transforms" : [identityTransform()], "instanceNames" : ["c"] });
                    opPattern(context, id + "mastTopCopy", { "entities" : qHasAttribute("foilMastTopVoid"), "transforms" : [identityTransform()], "instanceNames" : ["c"] });
                    opBoolean(context, id + "mastFillJoin", { "tools" : qUnion([qCreatedBy(id + "mastFill", EntityType.BODY), qCreatedBy(id + "mastTopCopy", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
                    cavTool = qUnion([qCreatedBy(id + "mastFill", EntityType.BODY), qCreatedBy(id + "mastFillJoin", EntityType.BODY)]);
                    mastFilled = true;
                }
                plDone = true;
            }
            try silent
            {
                opDeleteBodies(context, id + "plWTidy", { "entities" : qUnion([qCreatedBy(id + "plWPart", EntityType.BODY), qCreatedBy(id + "plWPart2", EntityType.BODY), qCreatedBy(id + "plWBox", EntityType.BODY),
                            qCreatedBy(id + "plWInt", EntityType.BODY), qCreatedBy(id + "plWShift", EntityType.BODY), qCreatedBy(id + "plWJoin", EntityType.BODY), qCreatedBy(id + "plWThru", EntityType.BODY),
                            qCreatedBy(id + "plWThruCut", EntityType.BODY), qCreatedBy(id + "plWEnvCut", EntityType.BODY), qCreatedBy(id + "plWEnvCut2", EntityType.BODY)]) });
            }
            if (!plDone)
            {
                plNote = " (the plate's top-face features were not separated - it stopped at " ~ plStage ~ "; the halves form them - send this line)";
                mastTopVoids = [];
                mastTopVol = 0 * meter ^ 3;
                try silent
                {
                    opDeleteBodies(context, id + "plFail", { "entities" : qUnion([qHasAttribute("foilPlateEnv"), qCreatedBy(id + "mastTopCopy", EntityType.BODY)]) });
                }
                if (mastFilled)
                {
                    try silent
                    {
                        opDeleteBodies(context, id + "plFailFill", { "entities" : qCreatedBy(id + "mastFill", EntityType.BODY) });
                    }
                    cavTool = coreVent != undefined ? qUnion([moldPart, coreVent]) : moldPart;
                    mastFilled = false;
                }
            }
        }
        hv = moldHalves(context, solids, lo, hi);
        try
        {
            opBoolean(context, id + "cavityUpper", {
                        "tools" : cavTool,
                        "targets" : hv.upper,
                        "operationType" : BooleanOperationType.SUBTRACTION,
                        "keepTools" : true
                    });
        }
        catch
        {
            throw regenError("Could not cut the cavity into the UPPER half." ~ tipAdvice, ["splitStations"]);
        }
        hv = moldHalves(context, solids, lo, hi);
        try
        {
            opBoolean(context, id + "cavityLower", {
                        "tools" : cavTool,
                        "targets" : hv.lower,
                        "operationType" : BooleanOperationType.SUBTRACTION,
                        "keepTools" : true
                    });
        }
        catch
        {
            throw regenError("Could not cut the cavity into the LOWER half." ~ tipAdvice, ["splitStations"]);
        }
        if (stabFilled || fusFilled || hubFilled || mastFilled)
            opDeleteBodies(context, id + "deleteStabFill", { "entities" : cavTool });
        if (flipZ)
            opDeleteBodies(context, id + "deleteStabFlip", { "entities" : moldPart });
        // the core mold's open tips run out through the end flanges: the puzzle inlays keep clear (build 235)
        var coreVentBoxes = [];
        if (coreVent != undefined && puzzle)
        {
            for (var vb in evaluateQuery(context, coreVent))
            {
                const bb = evBox3d(context, { "topology" : vb, "tight" : true });
                coreVentBoxes = append(coreVentBoxes, [bb.minCorner[0], bb.maxCorner[0], bb.minCorner[1], bb.maxCorner[1]]);
            }
        }
        if (coreVent != undefined)
            opDeleteBodies(context, id + "deleteCoreVent", { "entities" : coreVent });

        // ---------------- joint holes: the part's own shape, cleared where a pin would tie the plug ----------------
        // (build 195) The cavity is cut from the part as it stands, so the socket's countersinks, the
        // hub's pocket and its fillet mold exactly as modelled. What the cut leaves in the bolt
        // holes is mold: with the socket plug on, the pins in the nacelle's walls are cleared (they
        // would tie the bore's core to the halves) - the countersink stays, molded by the upper half
        // as a cone wide at the skin - and with Bolt cones on, the hub's straight pins are cleared
        // for the tapered cones below. Drill to size after cure
        var jointClearNote = "";
        var rayMiss = 0;
        if (plugOn && sock.pins > 0)
        {
            const zAx = sock.axisZ * meter;
            const zTopN = zAx + nacH / 2;
            const pinSpan = (sock.pins - 1) * sock.pinPitch * meter;
            const rHoleS = sock.pinDia / 2 * meter;
            const rHeadS = sock.pinHeadDia != undefined && sock.pinCsk != undefined && sock.pinCsk == 1 ? sock.pinHeadDia / 2 * meter : rHoleS;
            const hCsk = rHeadS - rHoleS;
            const rC = rHoleS + 0.3 * millimeter;
            var clears = [];
            for (var j = 0; j < sock.pins; j += 1)
            {
                const px = sock.pinCenterX * meter - pinSpan / 2 + j * sock.pinPitch * meter;
                // the nacelle's real top and bottom and the bore's real ceiling and floor at this
                // bolt, by ray casts just beside the hole (the nominal numbers when a cast fails)
                const xq = px + rHeadS + 0.5 * millimeter;
                const top = moldRayZ(context, moldPart, xq, 0 * meter, 1 * meter, false);
                const bot = moldRayZ(context, moldPart, xq, 0 * meter, -1 * meter, true);
                const ceilH = moldRayZ(context, moldPart, xq, 0 * meter, zAx, true);
                const floorH = moldRayZ(context, moldPart, xq, 0 * meter, zAx, false);
                if (!top.hit || !bot.hit || !ceilH.hit || !floorH.hit)
                    rayMiss += 1;
                const zTopA = top.hit ? top.z : zTopN;
                const zBotA = bot.hit ? bot.z : zAx - nacH / 2;
                const zCeil = ceilH.hit ? ceilH.z : zAx + bH / 2;
                const zFloor = floorH.hit ? floorH.z : zAx - bH / 2;
                // upper wall: from the countersink's bottom (or 0.2 mm inside the skin when the skin
                // is below the countersink there) to just past the bore's ceiling; lower wall: from
                // just past the bore's floor to 0.2 mm short of the skin, so the halves' faces are
                // not dimpled - the 0.2 mm stub is a witness mark for the drill
                const zU0 = zTopN - hCsk < zTopA - 0.2 * millimeter ? zTopN - hCsk - 0.05 * millimeter : zTopA - 0.2 * millimeter;
                clears = append(clears, moldPin(context, id + ("sockClearU" ~ j), vector(px, 0 * meter, zU0), vector(px, 0 * meter, zCeil + 0.05 * millimeter), rC));
                clears = append(clears, moldPin(context, id + ("sockClearL" ~ j), vector(px, 0 * meter, zFloor - 0.05 * millimeter), vector(px, 0 * meter, zBotA + 0.2 * millimeter), rC));
            }
            hv = moldHalves(context, solids, lo, hi);
            opBoolean(context, id + "sockClearCut", {
                        "tools" : qUnion(clears),
                        "targets" : qUnion([hv.upper, hv.lower]),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            jointClearNote = "; " ~ sock.pins ~ " bolt shank" ~ (sock.pins == 1 ? "" : "s") ~ " cleared through the nacelle's walls, the countersink" ~ (sock.pins == 1 ? "" : "s") ~ " molded by the upper half";
        }
        if (hubOn && !hubUnder && definition.conesOn && hub.boltX != undefined && size(hub.boltX) > 0)
        {
            const rH = hub.holeDia / 2 * meter + 0.3 * millimeter;
            var clearsH = [];
            for (var j = 0; j < size(hub.boltX); j += 1)
            {
                const bx = hub.boltX[j] * meter;
                // the pocket floor as it is, by a ray cast beside the hole
                const fl = moldRayZ(context, moldPart, bx + rH + 1 * millimeter, 0 * meter, 1 * meter, false);
                if (!fl.hit)
                    rayMiss += 1;
                const zF = fl.hit ? fl.z : hub.floorZ * meter;
                clearsH = append(clearsH, moldPin(context, id + ("hubClear" ~ j), vector(bx, 0 * meter, zF + 0.05 * millimeter), vector(bx, 0 * meter, zF - hub.holeDepth * meter - 0.5 * millimeter), rH));
            }
            hv = moldHalves(context, solids, lo, hi);
            opBoolean(context, id + "hubClearCut", {
                        "tools" : qUnion(clearsH),
                        "targets" : hv.upper,
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            // where the parting crosses a hole, the lower block keeps an island of the hole's volume that
            // the cavity cut severs from its half: a loose slug on the hole's axis, touching neither
            // block face (build 226). Delete any such body
            var slugs = [];
            for (var b in evaluateQuery(context, moldFloating(context, solids, lo, hi)))
            {
                const sb = evBox3d(context, { "topology" : b, "tight" : true });
                const cx = (sb.minCorner[0] + sb.maxCorner[0]) / 2;
                const cy = (sb.minCorner[1] + sb.maxCorner[1]) / 2;
                for (var bxS in hub.boltX)
                    if (abs(cx - bxS * meter) < rH && abs(cy) < rH)
                    {
                        slugs = append(slugs, b);
                        break;
                    }
            }
            if (size(slugs) > 0)
                opDeleteBodies(context, id + "hubSlugs", { "entities" : qUnion(slugs) });
        }

        // from here on the halves (and later the tiles) are found by geometry after every operation -
        // a body touching the block's top face is upper, one touching the bottom is lower - because a
        // query frozen before a boolean can come back empty after it (build 59 and 61 failures)

        var trayNote = "";
        if (isMast)
        {
            // plate tray: the third piece. Plate outline + flange in x, the block's full height in z',
            // Base thickness beyond the plate's board face in y', opening at the halves' end faces. The
            // mast copy cuts the plate pocket into it; the plate's bolt holes come out as pins
            // sized from the measured plate (plateAct, flat frame: y' = -z, z' = y + zPart); the bolt
            // pattern stays on the Foil mast's own centre and rows
            const pA = plateAct != undefined;
            const xcNom = (mastM.plateXc != undefined ? mastM.plateXc : mastM.leX + mastM.chord / 2) * meter;
            const xcT = pA ? (plateAct.x0 + plateAct.x1) / 2 : xcNom;
            const hlT = pA ? (plateAct.x1 - plateAct.x0) / 2 : mastM.plateLength / 2 * meter;
            const hwT = pA ? (plateAct.y1 - plateAct.y0) / 2 : mastM.plateWidth / 2 * meter;
            const zcT = pA ? (plateAct.y0 + plateAct.y1) / 2 + zPart : zPart;
            const yPlateT = pA ? -plateAct.zBoard : -(mastM.baseZ + mastM.height + mastM.plateThick) * meter;
            const tPlateT = -yPlateT - (mastM.baseZ + mastM.height) * meter;     // the plate's thickness as modelled
            moldBox(context, id + "plateTray", vector(xcT - hlT - f, yPlateT - definition.baseThick, lo[2]), vector(xcT + hlT + f, lo[1], hi[2]));
            setAttribute(context, { "entities" : qCreatedBy(id + "plateTray", EntityType.BODY), "name" : "foilPlateTray", "attribute" : 1 });
            opBoolean(context, id + "trayCut", {
                        "tools" : moldPart,
                        "targets" : qHasAttribute("foilPlateTray"),
                        "operationType" : BooleanOperationType.SUBTRACTION,
                        "keepTools" : true
                    });
            // the copy's holes leave pins carrying the countersink at their free end (the mast's
            // countersinks are on its underside, which faces the tray's opening): mushroom heads that
            // would lock the plate in (user). Clear each of them with a cylinder of the head diameter
            // + 0.3 mm (a box over the whole pocket, build 172 and before, squared off any edited
            // plate outline) and stand straight pins instead, 0.5 mm under the bolt diameter, on the
            // mast's own pattern; countersink after cure
            // the lid forms the board face and the top-face features only; the bolt holes, pins and countersink cones are
            // the halves' (build 241, user)
            if (size(mastTopVoids) > 0)
                opBoolean(context, id + "trayTopJoin", { "tools" : qUnion([qHasAttribute("foilPlateTray"), qHasAttribute("foilMastTopVoid")]), "operationType" : BooleanOperationType.UNION });
            const trayX = 2 * (hlT + f);
            const trayZ = hi[2] - lo[2];
            trayNote = " | plate lid " ~ fmt(trayX / millimeter, 0) ~ " x " ~ fmt(trayZ / millimeter, 0) ~ " x " ~ fmt((lo[1] - yPlateT + definition.baseThick) / millimeter, 0) ~
                " mm forming the plate's board face" ~ (size(mastTopVoids) > 0 ? " and " ~ size(mastTopVoids) ~ " feature" ~ (size(mastTopVoids) == 1 ? "" : "s") ~ " open to it, not through (" ~ fmt(mastTopVol / (centimeter ^ 3), 2) ~ " cm3)" : "") ~
                "; the halves form the plate's edges, underside and everything that goes through it, the bolt holes' pins and countersink cones as modelled" ~ (pA ? " (the plate as modelled, " ~ fmt(tPlateT / millimeter, 1) ~ " mm)" : "") ~
                (trayX > definition.printerX - definition.tileMargin || trayZ > definition.printerY - definition.tileMargin ? " (WARNING: larger than the bed - reduce Flange width)" : "");
            opDeleteBodies(context, id + "deleteMastCopy", { "entities" : moldPart });
        }
        // ---------------- pod plug: the pod's inside, whatever it is ----------------
        // The cavity cut leaves the pod's internal void as cores of mold, one per half, joined to the
        // block only through the pod's rear opening. A channel almost the pod's radius behind the rear
        // face severs them, whatever the opening's shape; the severed cores are then exactly the
        // void - the placeholder pocket or any custom inside modelled before this feature (motor
        // tabs, a hollowed shell) - and are joined to a handle in the channel as "Mast pod plug".
        // The plug's shoulder forms the pod's rear face. With undercuts inside, print the plug as a
        // sacrificial core.
        const podPlug = isMast && mastM.podOn == 1;
        // specks of mold the cavity cut loose (under 1 mm3: a hair-thin gap between a thin web and the parting,
        // a tip sliver) are deleted, so neither plug adopts them nor do they count as floating keys (build 241)
        var nSpecks = moldDropSpecks(context, id + "specks0", solids, lo, hi);
        var podPlugLen = 0 * meter;
        var podPlugQ;
        var podPlugNote = "";
        if (podPlug)
        {
            // the pod's axis in the laid-flat frame, with its tilt (world rotation about Y becomes a
            // rotation about z' here, so the axis stays in the parting plane): rear-face centre and
            // direction from the pod centre
            const tilt = mastM.podTilt != undefined ? mastM.podTilt : 0;
            const xC = mastM.podX * meter;
            const Lr = (mastM.podRearX - mastM.podX) * meter;
            const ax = vector(cos(tilt * radian), -sin(tilt * radian), 0);          // nose-down tilt: the rear rises (world +Z -> -y')
            const cR = vector(xC, -mastM.podZ * meter, zPart) + Lr * ax;
            const xR = cR[0];
            const rH = mastM.podDia / 2 * meter - 1 * millimeter;               // handle: 1 mm inside the pod's outer radius
            podPlugLen = min(definition.plugExt, (hi[0] - 2 * millimeter - xR) / max(cos(tilt * radian), 0.5));
            const chan = moldPin(context, id + "podChan", cR - 0.5 * millimeter * ax, cR + (podPlugLen + 1 * millimeter) * ax, rH + definition.pinFit);
            hv = moldHalves(context, solids, lo, hi);
            opBoolean(context, id + "podChanCut", {
                        "tools" : chan,
                        "targets" : qUnion([hv.upper, hv.lower]),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            // everything that is now neither an upper nor a lower body is a core of the void
            const cores = evaluateQuery(context, moldFloating(context, solids, lo, hi));
            const handle = moldPin(context, id + "podHandle", cR - 0.5 * millimeter * ax, cR + podPlugLen * ax, rH);
            if (size(cores) > 0)
                opBoolean(context, id + "podPlugJoin", { "tools" : qUnion(append(cores, handle)), "operationType" : BooleanOperationType.UNION });
            // the merged body keeps a core's identity, not the handle's (build 97: CANNOT_RESOLVE_ENTITIES
            // on the handle query) - so find the plug by geometry too: the one body touching neither face
            podPlugQ = moldFloating(context, solids, lo, hi);
            // an attribute survives every later boolean, unlike a creation query or a box test
            setAttribute(context, { "entities" : podPlugQ, "name" : "foilPodPlug", "attribute" : 1 });
            const pb = evBox3d(context, { "topology" : podPlugQ, "tight" : true });
            foilPrint(context, moldLogKey, "MAST_PLUG: cores=" ~ size(cores) ~ "; depth_mm=" ~ fmt((xR - pb.minCorner[0]) / millimeter, 1) ~ "; handle_mm=" ~ fmt(podPlugLen / millimeter, 1));
            podPlugNote = "; pod plug = the pod's inside (" ~ fmt((xR - pb.minCorner[0]) / millimeter, 0) ~ " mm deep, " ~ size(cores) ~ " core" ~ (size(cores) == 1 ? "" : "s") ~
                ") on a " ~ fmt(2 * rH / millimeter, 0) ~ " mm handle " ~ fmt(podPlugLen / millimeter, 0) ~ " mm long behind the rear face" ~
                (size(cores) == 0 ? " - no void found in the pod: is Cavity length 0, or the inside closed off?" : "; with undercuts inside, print it as a sacrificial core");
        }
        var sockCores = 0;
        if (plugOn)
        {
            // plug channel in both halves, behind the nacelle's rear face: it severs the bore's core
            const zAx = sock.axisZ * meter;
            const xR = sock.rearX * meter;
            var chan;
            if (sockSq)
            {
                roundedBoxX(context, id + "plugChan", xR - 1 * millimeter, xR + definition.plugExt + 1 * millimeter, zAx, bW / 2 + definition.pinFit, bH / 2 + definition.pinFit, bR + definition.pinFit);
                chan = qCreatedBy(id + "plugChan" + "loft", EntityType.BODY);
            }
            else
                chan = moldPin(context, id + "plugChan", vector(xR - 1 * millimeter, 0 * meter, zAx), vector(xR + definition.plugExt + 1 * millimeter, 0 * meter, zAx), bW / 2 + definition.pinFit);
            hv = moldHalves(context, solids, lo, hi);
            opBoolean(context, id + "plugChanCut", {
                        "tools" : chan,
                        "targets" : qUnion([hv.upper, hv.lower]),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            // the severed cores - the bore's own shape, one per half, whatever was modelled - joined
            // to a handle in the channel as the socket plug (the pod plug's method, build 123)
            nSpecks += moldDropSpecks(context, id + "specks1", solids, lo, hi);
            const cores = evaluateQuery(context, moldFloating(context, solids, lo, hi));
            sockCores = size(cores);
            var handle;
            if (sockSq)
            {
                roundedBoxX(context, id + "plugHandle", xR - 1.5 * millimeter, xR + definition.plugExt, zAx, bW / 2, bH / 2, bR);
                handle = qCreatedBy(id + "plugHandle" + "loft", EntityType.BODY);
            }
            else
                handle = moldPin(context, id + "plugHandle", vector(xR - 1.5 * millimeter, 0 * meter, zAx), vector(xR + definition.plugExt, 0 * meter, zAx), bW / 2);
            if (size(cores) > 0)
                opBoolean(context, id + "sockPlugJoin", { "tools" : qUnion(append(cores, handle)), "operationType" : BooleanOperationType.UNION });
            setAttribute(context, { "entities" : moldFloating(context, solids, lo, hi), "name" : "foilSockPlug", "attribute" : 1 });
        }

        // ---------------- socket bolt cones and hub hole cones (upper half) ----------------
        // Countersunk socket bolts (build 194): a 90 deg countersink cone at head diameter on the
        // nacelle's top, then the tapered undersized shank down to Cone web above the bore, all hanging
        // from the upper half, which forms the countersunk face. The hub's blind holes likewise hang
        // from the pocket's boss. Drill to size after cure
        var nSockCones = 0;
        var nHubCones = 0;
        {
            var topCones = [];
            const r0t = definition.coneDia / 2;
            if (plugOn && definition.conesOn && sock.pins > 0)
            {
                // the shank cone hangs from the molded countersink (or the skin), its top buried in it
                const zAx = sock.axisZ * meter;
                const zTopN = zAx + nacH / 2;                       // the nacelle's top over the socket
                const pinSpan = (sock.pins - 1) * sock.pinPitch * meter;
                const rHoleS = sock.pinDia / 2 * meter;
                const rHeadS = sock.pinHeadDia != undefined && sock.pinCsk != undefined && sock.pinCsk == 1 ? sock.pinHeadDia / 2 * meter : rHoleS;
                const hCsk = rHeadS - rHoleS;
                const hShank = (zTopN - (zAx + bH / 2)) - definition.coneWeb;   // to a web above the bore
                for (var j = 0; j < sock.pins; j += 1)
                {
                    const px = sock.pinCenterX * meter - pinSpan / 2 + j * sock.pinPitch * meter;
                    if (hShank - hCsk > 1 * millimeter)
                    {
                        topCones = append(topCones, moldFrustum(context, id + ("sockCone" ~ j), vector(px, 0 * meter, zTopN - hCsk + 0.5 * millimeter), vector(px, 0 * meter, zTopN - hShank), r0t, max(r0t - (hShank - hCsk) * tan(definition.coneTaper), 0.5 * millimeter)));
                        nSockCones += 1;
                    }
                }
            }
            if (hubOn && !hubUnder && definition.conesOn && hub.boltX != undefined && size(hub.boltX) > 0)
            {
                const zF = hub.floorZ * meter;
                const hHub = hub.holeDepth * meter - definition.coneWeb;
                for (var j = 0; j < size(hub.boltX); j += 1)
                {
                    const bx = hub.boltX[j] * meter;
                    if (hHub > 1 * millimeter)
                    {
                        topCones = append(topCones, moldFrustum(context, id + ("hubCone" ~ j), vector(bx, 0 * meter, zF + 0.5 * millimeter), vector(bx, 0 * meter, zF - hHub), r0t, max(r0t - hHub * tan(definition.coneTaper), 0.5 * millimeter)));
                        nHubCones += 1;
                    }
                }
            }
            if (size(topCones) > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "topConeJoin", {
                            "tools" : qUnion(append(topCones, hv.upper)),
                            "operationType" : BooleanOperationType.UNION
                        });
            }
        }

        // ---------------- hub bolts from the wing's underside: countersinks and cones (lower half, build 235) ----------------
        // The stab's method: a 90 deg countersink cone at head diameter on the lower skin, then a tapered
        // undersized cone to Cone web under the pocket floor (its tip held at 1 mm across, as the hub's
        // own cones are), both from the lower half, which forms the underside. The holes were filled
        // before the cavity cut, so these are the only things in them; drill to clearance after cure
        var nHubUnderCones = 0;
        var hubUnderNote = "";
        if (hubFilled)
        {
            var dnCones = [];
            const zFU = hub.floorZ * meter;
            const rHoleU = hub.holeDia / 2 * meter;
            const rHeadU = (hub.boltHead != undefined && hub.boltHead > 0 ? hub.boltHead / 2 : hub.holeDia) * meter;
            const r0u = definition.coneDia / 2;
            for (var j = 0; j < size(hub.boltX); j += 1)
            {
                const bx = hub.boltX[j] * meter;
                const zB = hub.underZ[j] * meter;
                const hCone = (zFU - zB) - definition.coneWeb;
                if (hCone < 1 * millimeter)
                {
                    hubUnderNote = hubUnderNote ~ " hub bolt at X " ~ fmt(bx / millimeter, 0) ~ ": no cone, the laminate under the pocket floor is too thin - drill it after cure;";
                    continue;
                }
                dnCones = append(dnCones, moldFrustum(context, id + ("hubUCone" ~ j), vector(bx, 0 * meter, zB - 0.5 * millimeter), vector(bx, 0 * meter, zB + hCone), r0u, max(r0u - hCone * tan(definition.coneTaper), 0.5 * millimeter)));
                if (hubNuts)
                {
                    // nut inserts (build 241): the flange's recess and the barrel's bore as bosses on the lower half,
                    // at the wing's hand-fit size
                    for (var q = 0; q < size(hub.recess); q += 1)
                        dnCones = append(dnCones, moldPin(context, id + ("hubNutBoss" ~ j ~ "_" ~ q), vector(bx, 0 * meter, zB - 0.5 * millimeter), vector(bx, 0 * meter, zB + hub.recess[q][1] * meter), hub.recess[q][0] * meter));
                }
                else if (rHeadU > rHoleU + 0.05 * millimeter)
                {
                    const hCsk = min(rHeadU - rHoleU, hCone);
                    dnCones = append(dnCones, moldFrustum(context, id + ("hubUCsk" ~ j), vector(bx, 0 * meter, zB - 0.5 * millimeter), vector(bx, 0 * meter, zB + hCsk), rHeadU + 0.5 * millimeter, rHeadU - hCsk));
                }
                nHubUnderCones += 1;
            }
            if (size(dnCones) > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "hubUConeJoin", {
                            "tools" : qUnion(append(dnCones, hv.lower)),
                            "operationType" : BooleanOperationType.UNION
                        });
            }
        }

        // ---------------- fuselage: cones and pins for its holes (build 215) ----------------
        // Countersunk holes: a 90 deg countersink cone at head diameter on the countersunk face, then a
        // tapered undersized shank to Cone web short of the far face, both from the half that forms
        // that face (the stab's method). Tapped holes: a straight pin 0.5 mm under the tapping drill
        // from the face the bolt enters, to Cone web short of the far face. Drill to size after cure
        var nFusCones = 0;
        var nFusPins = 0;
        var fusConeNote = "";
        if (isFus && !coreMold && definition.conesOn == true && fusM.holes != undefined)
        {
            var upQ = [];
            var dnQ = [];
            for (var j = 0; j < size(fusM.holes); j += 1)
            {
                const hF = fusM.holes[j];
                const xF = hF[0] * meter;
                const zLoF = hF[1] * meter;
                const zHiF = hF[2] * meter;
                const rHole = hF[3] * meter;
                const rHeadF = hF[4] * meter;
                const fromTop = hF[6] > 0;
                const zBase = fromTop ? zHiF : zLoF;
                const dz = fromTop ? -1 : 1;
                const hCone = (zHiF - zLoF) - definition.coneWeb;
                if (hCone < 1 * millimeter)
                {
                    fusConeNote = fusConeNote ~ " hole at X " ~ fmt(xF / millimeter, 0) ~ " skipped (too short for a cone);";
                    continue;
                }
                if (rHeadF > rHole + 0.3 * millimeter)
                {
                    // countersunk: cone tapered from 0.7 mm under the hole, countersink at head diameter
                    const r0F = max(rHole - 0.7 * millimeter, definition.coneDia / 2);
                    const r1F = max(r0F - hCone * tan(definition.coneTaper), 0.5 * millimeter);
                    const cq = moldFrustum(context, id + ("fcone" ~ j), vector(xF, 0 * meter, zBase - dz * 0.5 * millimeter), vector(xF, 0 * meter, zBase + dz * hCone), r0F, r1F);
                    const hCsk = min(rHeadF - rHole, hCone);
                    const kq = moldFrustum(context, id + ("fcsk" ~ j), vector(xF, 0 * meter, zBase - dz * 0.5 * millimeter), vector(xF, 0 * meter, zBase + dz * hCsk), rHeadF + 0.5 * millimeter, rHole);
                    if (fromTop)
                        upQ = concatenateArrays([upQ, [cq, kq]]);
                    else
                        dnQ = concatenateArrays([dnQ, [cq, kq]]);
                    nFusCones += 1;
                }
                else
                {
                    // tapped or plain: a straight pin 0.5 mm under the hole
                    const rP = max(rHole - 0.25 * millimeter, 0.5 * millimeter);
                    const pq = moldFrustum(context, id + ("fpin" ~ j), vector(xF, 0 * meter, zBase - dz * 0.5 * millimeter), vector(xF, 0 * meter, zBase + dz * hCone), rP, rP);
                    if (fromTop)
                        upQ = append(upQ, pq);
                    else
                        dnQ = append(dnQ, pq);
                    nFusPins += 1;
                }
            }
            if (size(upQ) > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "fusConeJoinU", { "tools" : qUnion(append(upQ, hv.upper)), "operationType" : BooleanOperationType.UNION });
            }
            if (size(dnQ) > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "fusConeJoinL", { "tools" : qUnion(append(dnQ, hv.lower)), "operationType" : BooleanOperationType.UNION });
            }
            foilPrint(context, moldLogKey, "FUSELAGE_CONES: holes=" ~ size(fusM.holes) ~ "; cones=" ~ nFusCones ~ "; pins=" ~ nFusPins ~ (fusConeNote != "" ? ";" ~ fusConeNote : ""));
        }

        // ---------------- bolt cones (lower half, on the fuselage's bolt pattern) ----------------
        // A frustum per bolt from just inside the lower half's pad face up to Cone web under the root
        // section's top surface at that X, unioned into the lower half. Undersized and drafted: the
        // part pulls off and the holes are drilled to clearance after cure.
        var coneNote = "";
        var nCones = 0;
        if (conesOn)
        {
            // the cone stands on the COUNTERSUNK face, in the half that forms it, wide end at the skin,
            // and tapers through the section to Cone web short of the other skin (user, build 178:
            // the pins must always start from the side with the countersink). The through hole was
            // filled before the cavity cut, so this cone and the molded countersink above it are the
            // only things in the hole; drill to clearance after cure. A pad over the far face stays
            // solid above the web
            const sideDn = cskSideM == 1;                          // countersink on top: cone points down
            const r0 = definition.coneDia / 2;
            var coneQs = [];
            var coneLog = "STAB_CONES: cskSide=" ~ cskSideM ~ "; padOn=" ~ stabRoot.padOn ~ "; baseX_mm=" ~ fmt(base[0] / millimeter, 1) ~ "; baseZ_mm=" ~ fmt(base[2] / millimeter, 1);
            for (var j = 0; j < size(stabRoot.boltX); j += 1)
            {
                const bx = stabRoot.boltX[j] * meter;
                // the two skins over the bolt's footprint: the cone starts at the countersunk one
                var zTop = -1 * meter;
                var zBot = 1 * meter;
                var found = false;
                const rHole = stabRoot.boltDia / 2 * meter;
                for (var i = 0; i < size(rootSecS); i += 1)
                {
                    if (abs(rootSecS[i][0] - bx) <= rHole + 0.5 * millimeter)
                    {
                        zTop = max(zTop, rootSecS[i][1]);
                        zBot = min(zBot, rootSecS[i][1]);
                        found = true;
                    }
                }
                coneLog = coneLog ~ "; bolt" ~ j ~ ": X_mm=" ~ fmt(bx / millimeter, 1) ~ (found ? " top_mm=" ~ fmt(zTop / millimeter, 2) ~ " bot_mm=" ~ fmt(zBot / millimeter, 2) : " none");
                if (!found)
                {
                    coneNote = coneNote ~ " bolt at X " ~ fmt(bx / millimeter, 0) ~ " skipped (behind the root section, in the tail - drill it after cure);";
                    continue;
                }
                const zBase = sideDn ? zTop : zBot;                    // the countersunk skin
                const zFar = sideDn ? zBot : zTop;
                const hCone = abs(zFar - zBase) - definition.coneWeb;
                const r1 = r0 - hCone * tan(definition.coneTaper);
                coneLog = coneLog ~ " h_mm=" ~ fmt(hCone / millimeter, 2) ~ " rTip_mm=" ~ fmt(r1 / millimeter, 2);
                if (hCone < 1 * millimeter || r1 < 0.5 * millimeter)
                {
                    coneNote = coneNote ~ " bolt at X " ~ fmt(bx / millimeter, 0) ~ " skipped (section too thin for the cone);";
                    continue;
                }
                if (stabRoot.headDia != undefined && stabRoot.headDia > 0 && (stabRoot.headDia - stabRoot.boltDia) / 2 * meter > hCone)
                    coneNote = coneNote ~ " bolt at X " ~ fmt(bx / millimeter, 0) ~ ": its countersink (" ~ fmt((stabRoot.headDia - stabRoot.boltDia) / 2 * 1000, 1) ~ " mm deep) is deeper than the " ~ fmt((zTop - zBot) / millimeter, 1) ~
                        " mm section allows - the molded countersink is a flat disc; move the bolt forward, a smaller Bolt, or Countersink off in the Foil stabiliser;";
                const dz = sideDn ? -1 : 1;
                const cq = moldFrustum(context, id + ("cone" ~ j), vector(bx, 0 * meter, zBase - dz * 0.5 * millimeter), vector(bx, 0 * meter, zBase + dz * hCone), r0, r1);
                coneQs = append(coneQs, cq);
                // the countersink itself, from the same half: a 90 deg cone at head diameter on the
                // skin, narrowing to the hole; clipped to the tapered cone's height in a thin section
                const rHeadC = stabRoot.headDia != undefined ? stabRoot.headDia / 2 * meter : 0 * meter;
                if (rHeadC > rHole)
                {
                    const hCsk = min(rHeadC - rHole, hCone);
                    coneQs = append(coneQs, moldFrustum(context, id + ("csk" ~ j), vector(bx, 0 * meter, zBase - dz * 0.5 * millimeter), vector(bx, 0 * meter, zBase + dz * hCsk), rHeadC + 0.5 * millimeter, rHeadC - hCsk));
                }
                nCones += 1;
            }
            foilPrint(context, moldLogKey, coneLog ~ "; made=" ~ nCones);
            if (nCones > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "coneJoin", {
                            "tools" : qUnion(append(coneQs, sideDn ? hv.upper : hv.lower)),
                            "operationType" : BooleanOperationType.UNION
                        });
            }
        }

        // ---------------- pinch-off groove (lower half, before the tiles) ----------------
        // annulus between the outline offset by Land width and by Land + Groove width, as a prism
        // through the whole block, minus the lowered curtain: what is left lies within Groove depth
        // below the parting surface, and only that is cut from the lower half
        var nGroove = 0;
        var grooveFailed = false;
        var landOn = false;          // build 244: the land lowered by Land gap
        var landFailed = false;
        var nVents = 0;
        var grooveVol = 0;      // cm3
        var loop = [];          // the outline the groove follows, LE then TE back
        const flashVol = partVol * definition.overchargePct / 100;   // cm3 the overcharge squeezes out
        if (definition.grooveOn)
        {
            loop = outLE;
            for (var i = size(outTE) - 1; i >= 0; i -= 1)
                loop = append(loop, outTE[i]);
            const inner = moldOffsetLoop(loop, definition.landWidth);
            const outer = moldOffsetLoop(loop, definition.landWidth + definition.grooveWidth);
            // prisms stay inside the block height so moldHalves never mistakes them for a half. If the
            // offset outline cannot be lofted the mold is finished without its groove and says so,
            // rather than failing whole (build 134)
            try silent
            {
                moldPrism(context, id + "gOuter", outer, lo[2] + e, hi[2] - e);
                moldPrism(context, id + "gInner", inner, lo[2] + e / 2, hi[2] - e / 2);
            }
            catch
            {
                grooveFailed = true;
                opDeleteBodies(context, id + "gFailDel", { "entities" : qUnion([qCreatedBy(id + "gOuter", EntityType.BODY), qCreatedBy(id + "gInner", EntityType.BODY),
                            qCreatedBy(id + "gOuter" + "p0", EntityType.BODY), qCreatedBy(id + "gOuter" + "p1", EntityType.BODY), qCreatedBy(id + "gInner" + "p0", EntityType.BODY), qCreatedBy(id + "gInner" + "p1", EntityType.BODY)]) });
            }
        }
        if (definition.grooveOn && !grooveFailed)
        {
            opBoolean(context, id + "gRing", {
                        "tools" : qCreatedBy(id + "gInner", EntityType.BODY),
                        "targets" : qCreatedBy(id + "gOuter", EntityType.BODY),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            // bag closing: vent slots from the groove to the block's outer face at each span end,
            // 1 mm wide, trimmed to the groove's depth by the same lowered curtain (before the curtain
            // is consumed by the groove's own floor cut). A loop end lying outside the block (the
            // mast's plate end, which already runs off the block) needs none
            var ventQ = [];
            if (definition.closing == MoldClosing.BAG && definition.ventOn)
            {
                const gw = definition.landWidth + definition.grooveWidth;
                for (var k = 0; k < 2; k += 1)
                {
                    const iE = k == 0 ? 0 : size(outLE) - 1;
                    const xe = (outLE[iE][0] + outTE[iE][0]) / 2;
                    const ye = (outLE[iE][1] + outTE[iE][1]) / 2;
                    const inside = k == 0 ? ye - gw > lo[1] + 1 * millimeter : ye + gw < hi[1] - 1 * millimeter;
                    if (inside)
                    {
                        const y0 = k == 0 ? lo[1] - e : ye + definition.landWidth + definition.grooveWidth / 2;
                        const y1 = k == 0 ? ye - definition.landWidth - definition.grooveWidth / 2 : hi[1] + e;
                        moldBox(context, id + ("vent" ~ k), vector(xe - 0.5 * millimeter, y0, lo[2] + e), vector(xe + 0.5 * millimeter, y1, hi[2] - e));
                        ventQ = append(ventQ, qCreatedBy(id + ("vent" ~ k), EntityType.BODY));
                    }
                }
                if (size(ventQ) > 0)
                    opBoolean(context, id + "ventFloor", {
                                "tools" : qUnion(curtainDown),
                                "targets" : qUnion(ventQ),
                                "operationType" : BooleanOperationType.SUBTRACTION,
                                "keepTools" : true
                            });
            }
            // land gap (build 244): a ring from the cavity's outline out to Land width, its floor the groove's lowered
            // curtain moved back up by Groove depth less Land gap, cut from the lower half with the groove
            const landGap = definition.landGap == undefined ? 0 * meter : definition.landGap;
            if (landGap > 0.005 * millimeter)
            {
                if (landGap > definition.grooveDepth - 0.2 * millimeter)
                    throw regenError("Land gap must be at least 0.2 mm under Groove depth, so the flash still has a groove to run into", ["landGap", "grooveDepth"]);
                try silent
                {
                    moldPrism(context, id + "lOuter", moldOffsetLoop(loop, definition.landWidth), lo[2] + e / 4, hi[2] - e / 4);
                    moldPrism(context, id + "lInner", loop, lo[2] + e / 8, hi[2] - e / 8);
                    opBoolean(context, id + "lRing", {
                                "tools" : qCreatedBy(id + "lInner", EntityType.BODY),
                                "targets" : qCreatedBy(id + "lOuter", EntityType.BODY),
                                "operationType" : BooleanOperationType.SUBTRACTION
                            });
                    opPattern(context, id + "landDown", {
                                "entities" : qUnion(curtainDown),
                                "transforms" : [transform(vector(0 * meter, 0 * meter, definition.grooveDepth - landGap))],
                                "instanceNames" : ["l"]
                            });
                    opBoolean(context, id + "lFloor", {
                                "tools" : qCreatedBy(id + "landDown", EntityType.BODY),
                                "targets" : qCreatedBy(id + "lOuter", EntityType.BODY),
                                "operationType" : BooleanOperationType.SUBTRACTION
                            });
                    landOn = true;
                }
                if (!landOn)
                {
                    landFailed = true;
                    try silent { opDeleteBodies(context, id + "lFailDel", { "entities" : qUnion([qCreatedBy(id + "lOuter", EntityType.BODY), qCreatedBy(id + "lInner", EntityType.BODY), qCreatedBy(id + "landDown", EntityType.BODY)]) }); }
                }
            }
            nVents = size(ventQ);
            opBoolean(context, id + "gFloor", {
                        "tools" : qUnion(curtainDown),
                        "targets" : qCreatedBy(id + "gOuter", EntityType.BODY),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            if (podPlug)
            {
                // no pinch-off round the pod (user): clear the ring from the pod's band, nose to the
                // block's aft edge, so the plug channel and the pod flanks stay ungrooved
                const yP = -mastM.podZ * meter;
                const rP = mastM.podDia / 2 * meter + definition.landWidth + definition.grooveWidth + 1 * millimeter +
                    (mastM.podTilt != undefined ? abs(sin(mastM.podTilt * radian)) * mastM.podLength / 2 * meter : 0 * meter);
                moldBox(context, id + "gPodClear", vector(mastM.podNoseX * meter - definition.landWidth - definition.grooveWidth - 1 * millimeter, yP - rP, lo[2]),
                        vector(hi[0] + e, yP + rP, hi[2]));
                opBoolean(context, id + "gPodClearCut", {
                            "tools" : qCreatedBy(id + "gPodClear", EntityType.BODY),
                            "targets" : qCreatedBy(id + "gOuter", EntityType.BODY),
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
            }
            hv = moldHalves(context, solids, lo, hi);
            opBoolean(context, id + "gCut", {
                        "tools" : qCreatedBy(id + "gOuter", EntityType.BODY),
                        "targets" : hv.lower,
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            if (landOn)
            {
                if (podPlug)
                {
                    // as the groove: no land round the pod
                    const yPl = -mastM.podZ * meter;
                    const rPl = mastM.podDia / 2 * meter + definition.landWidth + definition.grooveWidth + 1 * millimeter +
                        (mastM.podTilt != undefined ? abs(sin(mastM.podTilt * radian)) * mastM.podLength / 2 * meter : 0 * meter);
                    moldBox(context, id + "lPodClear", vector(mastM.podNoseX * meter - definition.landWidth - definition.grooveWidth - 1 * millimeter, yPl - rPl, lo[2]),
                            vector(hi[0] + e, yPl + rPl, hi[2]));
                    opBoolean(context, id + "lPodClearCut", {
                                "tools" : qCreatedBy(id + "lPodClear", EntityType.BODY),
                                "targets" : qCreatedBy(id + "lOuter", EntityType.BODY),
                                "operationType" : BooleanOperationType.SUBTRACTION
                            });
                }
                hv = moldHalves(context, solids, lo, hi);
                try silent
                {
                    opBoolean(context, id + "lCut", {
                                "tools" : qCreatedBy(id + "lOuter", EntityType.BODY),
                                "targets" : hv.lower,
                                "operationType" : BooleanOperationType.SUBTRACTION
                            });
                }
                catch
                {
                    landFailed = true;
                    landOn = false;
                    try silent { opDeleteBodies(context, id + "lCutDel", { "entities" : qCreatedBy(id + "lOuter", EntityType.BODY) }); }
                }
            }
            if (nVents > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "ventCut", {
                            "tools" : qUnion(ventQ),
                            "targets" : hv.lower,
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
            }
            nGroove = 1;
            // what the groove holds against what the overcharge squeezes out
            var per = 0 * meter;
            for (var i = 0; i < size(loop); i += 1)
                per += norm(loop[(i + 1) % size(loop)] - loop[i]);
            grooveVol = per * definition.grooveWidth * definition.grooveDepth / (centimeter * centimeter * centimeter);
        }

        // ---------------- tiles ----------------
        // each half is cut along the span into nY tiles and, if a tile would still be wider than the
        // printer, across the chord into nX. Dowel holes are drilled first, centred on each cut, in
        // the base layer (always solid, base/2 from the outer face); the cuts then leave half a hole
        // in each neighbour. Upper cuts are offset half a tile when Stagger joints is on
        const Lv = hi - lo;
        const L = Lv / millimeter;
        const useXv = definition.printerX - definition.tileMargin;
        const useYv = definition.printerY - definition.tileMargin;
        const useZ = (definition.printerZ - definition.tileMargin) / millimeter;
        const nX = preview ? 1 : ceil(Lv[0] / useXv);
        const nY = preview ? 1 : ceil(Lv[1] / useYv);
        const tileX = Lv[0] / nX;
        const tileY = Lv[1] / nY;
        const stagger = definition.staggerJoints && nY > 1;
        // the tile keys' own limits only when there are tile keys (build 235: none with Puzzle inlay)
        const pinDiaV = definition.pinDia != undefined ? definition.pinDia : 12 * millimeter;
        if (!puzzle && pinDiaV > definition.baseThick - 4 * millimeter)
            throw regenError("Pin dia must be at most Base thickness - 4 mm - the tile keys live in the base layer", ["pinDia", "baseThick"]);
        if ((!puzzle && pinDiaV > f - 4 * millimeter) || definition.keyDia > f - 4 * millimeter)
            throw regenError("Pin dia and Key dia must be at most Flange width - 4 mm - the keys sit in the flanges", ["pinDia", "keyDia", "flangeWidth"]);

        var yCutsL = [];
        for (var k = 1; k < nY; k += 1)
            yCutsL = append(yCutsL, lo[1] + k * tileY);
        var yCutsU = yCutsL;
        if (stagger)
        {
            yCutsU = [];
            for (var k = 1; k <= nY; k += 1)
                yCutsU = append(yCutsU, lo[1] + (k - 0.5) * tileY);
        }
        // no spanwise seam through the stab's pad and tail, or through the wing's nacelle: a cut that
        // lands within the keep-out is moved to its edge, if the two tiles it makes still fit the bed
        const podTiltSpread = isMast && mastM.podOn == 1 && mastM.podTilt != undefined ? abs(sin(mastM.podTilt * radian)) * mastM.podLength / 2 * meter : 0 * meter;
        const keepY = padMap != undefined ? padMap.padWidth / 2 * meter + 5 * millimeter :
            (sockOn ? max(nacW / 2, sockReach) + 5 * millimeter : (hubOn ? (hub.reach != undefined ? max(hub.reach, hub.width / 2) : hub.width / 2) * meter + 5 * millimeter : (isMast && mastM.podOn == 1 ? mastM.podDia / 2 * meter + podTiltSpread + 5 * millimeter : 0 * meter)));
        const keepC = isMast && mastM.podOn == 1 ? -mastM.podZ * meter : 0 * meter;    // band centre (the mast's pod lies at y' = -podZ)
        const keepName = padMap != undefined ? "stab pad" : (sockOn ? "nacelle" : (hubOn ? "hub" : "pod"));
        var cutNote = "";
        if (keepY > 0 * meter)
        {
            const lists = [yCutsL, yCutsU];
            var fixed = [];
            for (var li = 0; li < 2; li += 1)
            {
                var cuts = lists[li];
                for (var k = 0; k < size(cuts); k += 1)
                {
                    if (abs(cuts[k] - keepC) >= keepY)
                        continue;
                    const prev = k == 0 ? lo[1] : cuts[k - 1];
                    const next = k == size(cuts) - 1 ? hi[1] : cuts[k + 1];
                    var moved = false;
                    for (var sgn in [cuts[k] >= keepC ? 1 : -1, cuts[k] >= keepC ? -1 : 1])
                    {
                        const yc = keepC + sgn * keepY;
                        if (!moved && yc - prev <= useYv && next - yc <= useYv && yc - prev > 20 * millimeter && next - yc > 20 * millimeter)
                        {
                            cuts[k] = yc;
                            moved = true;
                        }
                    }
                    if (!moved)
                        cutNote = " (a spanwise seam still crosses the " ~ keepName ~ " - the tiles either side would not fit the bed)";
                    else
                        cutNote = " (seam moved off the " ~ keepName ~ ")";
                }
                fixed = append(fixed, cuts);
            }
            yCutsL = fixed[0];
            yCutsU = fixed[1];
        }
        var xCuts = [];
        for (var k = 1; k < nX; k += 1)
            xCuts = append(xCuts, lo[0] + k * tileX);
        // with the tube socket on, keep the nacelle and its bore core in one tile: put a single
        // chordwise cut just ahead of where the nacelle starts, if both tiles still fit the printer
        var chordCutNote = "";
        if ((sockOn || hubOn) && nX == 2)
        {
            // the hub's nose fairing (build 235) runs ahead of the hub: the cut goes ahead of it too
            const xHubFront = hubOn && hub.noseOn != undefined && hub.noseOn == 1 ? min(hub.x0, hub.noseX0) * meter : (hubOn ? hub.x0 * meter : 0 * meter);
            const xc = (sockOn ? sock.axisX * meter : xHubFront) - 5 * millimeter;
            if (xc - lo[0] <= useXv && hi[0] - xc <= useXv && xc - lo[0] > 20 * millimeter)
            {
                xCuts = [xc];
                chordCutNote = sockOn ? " (ahead of the tube socket)" : " (ahead of the hub)";
            }
            else
                chordCutNote = sockOn ? " (through the tube socket - a narrower Flange width or a wider printer would let it clear)" : " (through the hub - a narrower Flange width or a wider printer would let it clear)";
        }

        const printed = definition.keyStyle == MoldKeyStyle.PRINTED;
        var rT = 0 * meter;
        if (printed)
        {
            rT = pinDiaV / 2 - definition.keyHeight * tan(definition.keyDraft);
            const rTk = definition.keyDia / 2 - definition.keyHeight * tan(definition.keyDraft);
            if ((!puzzle && rT < 1 * millimeter) || rTk < 1 * millimeter)
                throw regenError("Key tip would be under 2 mm across - lower Key height or Key draft, or raise Pin dia / Key dia", ["keyHeight", "keyDraft", "pinDia", "keyDia"]);
            if (definition.keyHeight > definition.baseThick - 4 * millimeter)
                throw regenError("Key height must be at most Base thickness - 4 mm so the sockets stay inside the base layer", ["keyHeight", "baseThick"]);
        }

        // dowel holes (Dowel holes style) - drilled before the cuts, centred on each cut
        const rHole = (pinDiaV + definition.pinFit) / 2;
        const hp = printed || puzzle || definition.pinLen == undefined ? 0 * meter : definition.pinLen / 2;
        const zPinU = hi[2] - definition.baseThick / 2;
        const zPinL = lo[2] + definition.baseThick / 2;
        const xFront = lo[0] + f / 2;
        const xAft = hi[0] - f / 2;
        var nPins = 0;
        var nSkippedKeys = 0;      // key positions with no tile under them (a seam crossing the plug channel)
        for (var side = 0; side < (printed || puzzle ? 0 : 2); side += 1)
        {
            const yCuts = side == 0 ? yCutsU : yCutsL;
            const zPin = side == 0 ? zPinU : zPinL;
            var holes = [];
            for (var yc in yCuts)
            {
                holes = append(holes, moldPin(context, id + ("h" ~ side ~ "f" ~ size(holes)), vector(xFront, yc - hp, zPin), vector(xFront, yc + hp, zPin), rHole));
                holes = append(holes, moldPin(context, id + ("h" ~ side ~ "a" ~ size(holes)), vector(xAft, yc - hp, zPin), vector(xAft, yc + hp, zPin), rHole));
            }
            // chordwise joints: one pin per spanwise tile, at that tile's mid-span
            var bounds = concatenateArrays([[lo[1]], yCuts, [hi[1]]]);
            for (var xc in xCuts)
                for (var k = 0; k + 1 < size(bounds); k += 1)
                {
                    const ym = 0.5 * (bounds[k] + bounds[k + 1]);
                    holes = append(holes, moldPin(context, id + ("h" ~ side ~ "x" ~ size(holes)), vector(xc - hp, ym, zPin), vector(xc + hp, ym, zPin), rHole));
                }
            nPins += size(holes);
            if (size(holes) > 0 && !printed)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + ("drill" ~ side), {
                            "tools" : qUnion(holes),
                            "targets" : side == 0 ? hv.upper : hv.lower,
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
            }
        }

        // registration keys: vertical holes through the parting surface in both flanges, subtracted
        // from both halves at once so each gets its half. Height comes from the parting itself
        var nKeys = 0;
        if (definition.keysOn && !printed)
        {
            if (definition.keyLen / 2 > definition.baseThick - 3 * millimeter)
                throw regenError("Key length must be at most 2 x (Base thickness - 3 mm) - the hole would break through the thinner half", ["keyLen", "baseThick"]);
            const rKey = (definition.keyDia + definition.pinFit) / 2;
            const hk = definition.keyLen / 2;
            var keys = [];
            for (var k = 0; k < nY; k += 1)
            {
                var yk = lo[1] + (k + 0.25) * tileY;
                if (keepY > 0 * meter && abs(yk - keepC) < keepY + rKey + 2 * millimeter)
                    yk = keepC + (yk >= keepC ? 1 : -1) * (keepY + rKey + 2 * millimeter);   // clear of the pad / nacelle / pod channel
                var zf = zPart;
                var za = zPart;
                if (!isFlat)
                {
                    const pp = wTab != undefined && abs(yk) > wY0 ? moldPartingPointsWinglet(wTab, abs(yk), yk < 0 * meter ? -1 : 1, lo[0] - e, hi[0] + e) : moldPartingPointsPad(m, mini, min(abs(yk) / h, 1), yk, base, lo[0] - e, hi[0] + e, sockOn && abs(yk) <= max(sock.nacelleDia / 2 * meter, sockReach) * 1.0001 ? sock : undefined, abs(yk) < (padMap != undefined ? padMap.padWidth / 2 * meter : 0 * meter) ? padMap : undefined);
                    zf = pp.front[2];
                    za = pp.aft[2];
                }
                else if (isFus)
                {
                    zf = fusPartZ(fusPart, xFront);
                    za = fusPartZ(fusPart, xAft);
                }
                keys = append(keys, moldPin(context, id + ("kf" ~ k), vector(xFront, yk, zf - hk), vector(xFront, yk, zf + hk), rKey));
                keys = append(keys, moldPin(context, id + ("ka" ~ k), vector(xAft, yk, za - hk), vector(xAft, yk, za + hk), rKey));
            }
            nKeys = size(keys);
            hv = moldHalves(context, solids, lo, hi);
            opBoolean(context, id + "keyCut", {
                        "tools" : qUnion(keys),
                        "targets" : qUnion([hv.upper, hv.lower]),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
        }

        // ---------------- puzzle inlays across the tile seams (build 235) ----------------
        // A bow-tie pocket straddling every seam in the parting-face flange on each side of the cavity -
        // beyond its edge, the land and the groove, centred in what is left with 2 mm to spare each side
        // - cut from the top before the halves are cut into tiles, so each tile gets its half. Spanwise
        // seams: one pocket ahead of the cavity (LE) and one behind it (TE); chordwise seams: one in the
        // flange at each end of the seam (-Y, +Y). The floor is flat, Inlay depth into the half below the
        // flange top at the key's centre (a ray cast on the half); the keys are built at the end as parts,
        // Key flush thinner. A pocket that would reach a half key, a plug or pod channel, a vent or
        // another seam moves along its flange, or is skipped with a warning, as is one whose flange is
        // too narrow (with the Flange width it needs)
        var inlayKeys = [];          // the keys to build: { name, origin (on the floor), normal, xDir, thick }
        var inlayWarn = [];
        var inlayNote = "";
        if (puzzle && !preview)
        {
            const iDim = inlayDims(definition);
            const lhP = iDim.pLh;                                   // the pocket's half extents in plan
            const whP = iDim.pWh;
            const dIn = definition.inlayDepth;
            const flush = definition.inlayFlush != undefined ? definition.inlayFlush : 0.15 * millimeter;
            // the cavity's outline, grown by the land and the groove when there is one
            var cav = outLE;
            for (var i = size(outTE) - 1; i >= 0; i -= 1)
                cav = append(cav, outTE[i]);
            const band = definition.grooveOn ? definition.landWidth + definition.grooveWidth : 0 * meter;
            const edgeLoop = band > 0 * meter ? moldOffsetLoop(cav, band) : cav;
            var exMin = 1 * meter;
            var exMax = -1 * meter;
            var eyMin = 1 * meter;
            var eyMax = -1 * meter;
            for (var pE in edgeLoop)
            {
                exMin = min(exMin, pE[0]);
                exMax = max(exMax, pE[0]);
                eyMin = min(eyMin, pE[1]);
                eyMax = max(eyMax, pE[1]);
            }
            // keep-outs in plan, 1 mm round each: the half keys (where both styles put them), the socket
            // plug's channel, the pod plug's, the bag's groove vents, a core mold's open tips
            var keep = [];
            if (definition.keysOn)
            {
                const rK = definition.keyDia / 2 + definition.pinFit + 1 * millimeter;
                const rMove = printed ? definition.keyDia / 2 : (definition.keyDia + definition.pinFit) / 2;
                for (var k = 0; k < nY; k += 1)
                {
                    var yk = lo[1] + (k + 0.25) * tileY;
                    if (keepY > 0 * meter && abs(yk - keepC) < keepY + rMove + 2 * millimeter)
                        yk = keepC + (yk >= keepC ? 1 : -1) * (keepY + rMove + 2 * millimeter);
                    keep = append(keep, { "x0" : xFront - rK, "x1" : xFront + rK, "y0" : yk - rK, "y1" : yk + rK, "what" : "a half key" });
                    keep = append(keep, { "x0" : xAft - rK, "x1" : xAft + rK, "y0" : yk - rK, "y1" : yk + rK, "what" : "a half key" });
                }
            }
            if (plugOn)
            {
                const hwC = bW / 2 + definition.pinFit + 1 * millimeter;
                keep = append(keep, { "x0" : sock.rearX * meter - 2 * millimeter, "x1" : sock.rearX * meter + definition.plugExt + 2 * millimeter, "y0" : -hwC, "y1" : hwC, "what" : "the socket plug's channel" });
            }
            if (podPlug)
                keep = append(keep, { "x0" : mastM.podRearX * meter - 2 * millimeter, "x1" : hi[0] + 1 * millimeter, "y0" : keepC - keepY, "y1" : keepC + keepY, "what" : "the pod plug's channel" });
            if (nVents > 0)
            {
                for (var iE in [0, size(outLE) - 1])
                {
                    const xe = (outLE[iE][0] + outTE[iE][0]) / 2;
                    keep = append(keep, { "x0" : xe - 1.5 * millimeter, "x1" : xe + 1.5 * millimeter, "y0" : lo[1] - 1 * millimeter, "y1" : hi[1] + 1 * millimeter, "what" : "a groove vent" });
                }
            }
            for (var vb in coreVentBoxes)
                keep = append(keep, { "x0" : vb[0] - 2 * millimeter, "x1" : vb[1] + 2 * millimeter, "y0" : vb[2] - 2 * millimeter, "y1" : vb[3] + 2 * millimeter, "what" : "the core's open tip" });
            // where each pocket goes, half by half
            var plan = [];
            for (var side = 0; side < 2; side += 1)
            {
                const hName = isMast ? (side == 0 ? "left" : "right") : (side == 0 ? "upper" : "lower");
                const ySeams = side == 0 ? yCutsU : yCutsL;
                for (var dir = 0; dir < 2; dir += 1)
                {
                    // dir 0: the spanwise seams (cuts at y, the key along Y); dir 1: the chordwise seams
                    const seams = dir == 0 ? ySeams : xCuts;
                    for (var k = 0; k < size(seams); k += 1)
                    {
                        const sc = seams[k];
                        // the cavity's edge along the seam over the pocket's whole length
                        var cLo = 1 * meter;
                        var cHi = -1 * meter;
                        var hitAny = false;
                        for (var q = -2; q <= 2; q += 1)
                        {
                            const span = loopSpanAt(edgeLoop, sc + lhP * q / 2, dir == 0);
                            if (span != undefined)
                            {
                                cLo = min(cLo, span[0]);
                                cHi = max(cHi, span[1]);
                                hitAny = true;
                            }
                        }
                        if (!hitAny)
                        {
                            cLo = dir == 0 ? exMin : eyMin;
                            cHi = dir == 0 ? exMax : eyMax;
                        }
                        // this pocket keeps clear of every other seam of its half too
                        var kp = keep;
                        for (var yq in ySeams)
                            if (dir == 1 || abs(yq - sc) > 0.01 * millimeter)
                                kp = append(kp, { "x0" : lo[0] - 1 * millimeter, "x1" : hi[0] + 1 * millimeter, "y0" : yq - 1 * millimeter, "y1" : yq + 1 * millimeter, "what" : "another tile seam" });
                        for (var xq in xCuts)
                            if (dir == 0 || abs(xq - sc) > 0.01 * millimeter)
                                kp = append(kp, { "x0" : xq - 1 * millimeter, "x1" : xq + 1 * millimeter, "y0" : lo[1] - 1 * millimeter, "y1" : hi[1] + 1 * millimeter, "what" : "a chordwise tile seam" });
                        const bLo = dir == 0 ? lo[0] : lo[1];
                        const bHi = dir == 0 ? hi[0] : hi[1];
                        for (var ei = 0; ei < 2; ei += 1)
                        {
                            const tag = dir == 0 ? (ei == 0 ? "LE" : "TE") : (ei == 0 ? "-Y" : "+Y");
                            const nm = "Tile key " ~ hName ~ (dir == 0 ? " seam " : " chord seam ") ~ (k + 1) ~ " " ~ tag;
                            const a = ei == 0 ? bLo + 2 * millimeter + whP : cHi + 2 * millimeter + whP;
                            const b = ei == 0 ? cLo - 2 * millimeter - whP : bHi - 2 * millimeter - whP;
                            if (b < a)
                            {
                                const room = ei == 0 ? cLo - bLo : bHi - cHi;
                                const need = 2 * whP + 4 * millimeter;
                                inlayWarn = append(inlayWarn, nm ~ " skipped: its flange leaves " ~ fmt(room / millimeter, 1) ~ " mm beyond the " ~ (band > 0 * meter ? "groove" : "cavity") ~ " and the pocket needs " ~ fmt(need / millimeter, 1) ~
                                    " (Flange width " ~ fmt(ceil((f + need - room) / millimeter), 0) ~ " mm or more, or a narrower Inlay width)");
                                continue;
                            }
                            const pl = inlayPlace(kp, a, b, sc, dir == 0, lhP, whP);
                            if (pl.c == undefined)
                            {
                                inlayWarn = append(inlayWarn, nm ~ " skipped: it would reach " ~ pl.why ~ " wherever it sits in its flange");
                                continue;
                            }
                            plan = append(plan, { "side" : side, "name" : nm, "x" : dir == 0 ? pl.c : sc, "y" : dir == 0 ? sc : pl.c, "alongY" : dir == 0, "keep" : kp });
                        }
                    }
                }
            }
            // the flange under each pocket (build 235, the user's main wing: on a drooped wing a flat floor left a
            // 30 mm key 3-4 mm proud of the face the other half closes on, which stops the mold closing). Ray
            // casts on its half before any pocket is cut (the upper half's flange top is its underside) at the
            // key's centre, its ends and halfway along its axis, and either side across it; a plane fitted
            // through them (least squares about the centre). The floor is that plane moved Inlay depth into
            // the half along its normal; the walls stay vertical for a 3-axis cutter (a vertical prism of the
            // plan outline intersected with a slab on the floor plane); the key, a flat square-edged plate
            // Inlay depth less Key flush thick, lies on the floor with its face Key flush from the plane all
            // along it, its footprint centred on the pocket. Tilted, a square-edged plate's ends lean t tan
            // (tilt) out of vertical, so the pocket is t tan(tilt along the key) longer at each end, and its
            // flanks give the plate's lean and foreshortening room (Python twin: inlay_tilt_allowance); the
            // wedges fill with glue. The grown pocket is checked against its keep-outs again
            hv = moldHalves(context, solids, lo, hi);
            var cutU = [];
            var cutL = [];
            var tiltMax = 0;                      // tan of the steepest key's tilt, and which key
            var tiltAt = "";
            var endMax = 0 * meter;               // the largest end allowance
            var nSteep = 0;                       // keys tilted more than 12 deg
            var proudMax = 0 * meter;             // where the flange curves off the fitted plane by more than Key flush
            var proudAt = "";
            const tK = dIn - flush;               // the key's thickness
            const samp = [[0, 0], [1, 0], [-1, 0], [0.5, 0], [-0.5, 0], [0, 1], [0, -1]];   // (along / half length, across / half width)
            for (var n = 0; n < size(plan); n += 1)
            {
                const pc = plan[n];
                const up = pc.side == 0;
                const body = up ? hv.upper : hv.lower;
                const zRay = up ? lo[2] - 10 * millimeter : hi[2] + 10 * millimeter;
                var zs = [];
                for (var sp in samp)
                {
                    const da = sp[0] * lhP;
                    const dc = sp[1] * whP;
                    const r = moldRayZ(context, body, pc.x + (pc.alongY ? dc : da), pc.y + (pc.alongY ? da : dc), zRay, up);
                    zs = append(zs, r.hit ? r.z : undefined);
                }
                if (zs[0] == undefined)
                {
                    inlayWarn = append(inlayWarn, pc.name ~ " skipped: no flange face found under it");
                    continue;
                }
                // the plane z = zc + gu a + gv c (a along the key, c across it), slopes from the pairs that both hit
                var gNum = 0 * meter * meter;
                var gDen = 0 * meter * meter;
                for (var pr in [[1, 2, 1], [3, 4, 0.5]])
                {
                    if (zs[pr[0]] != undefined && zs[pr[1]] != undefined)
                    {
                        gNum += (zs[pr[0]] - zs[pr[1]]) * pr[2] * lhP;
                        gDen += 2 * (pr[2] * lhP) * (pr[2] * lhP);
                    }
                }
                const gu = gDen > 0 * meter * meter ? gNum / gDen : 0;
                const gv = zs[5] != undefined && zs[6] != undefined ? (zs[5] - zs[6]) / (2 * whP) : 0;
                var aSum = 0 * meter;
                var aN = 0;
                var zLoF = zs[0];
                var zHiF = zs[0];
                for (var i = 0; i < size(samp); i += 1)
                {
                    if (zs[i] != undefined)
                    {
                        aSum += zs[i] - gu * samp[i][0] * lhP - gv * samp[i][1] * whP;
                        aN += 1;
                        zLoF = min(zLoF, zs[i]);
                        zHiF = max(zHiF, zs[i]);
                    }
                }
                const zc = aSum / aN;
                // where the face strays from the plane toward the other half by more than Key flush (a parting
                // station's kink or a tip's camber under the key), the key's face stands proud of it
                var proud = 0 * meter;
                for (var i = 0; i < size(samp); i += 1)
                {
                    if (zs[i] != undefined)
                    {
                        const zPl = zc + gu * samp[i][0] * lhP + gv * samp[i][1] * whP;
                        proud = max(proud, (up ? zs[i] - zPl : zPl - zs[i]) - flush);
                    }
                }
                const gx = pc.alongY ? gv : gu;
                const gy = pc.alongY ? gu : gv;
                const tanT = sqrt(gu * gu + gv * gv);
                const nU = vector(-gx, -gy, 1) / sqrt(1 + tanT * tanT);              // the plane's unit normal, up
                const gA = abs(gu);
                const gC = abs(gv);
                const tw = gA * gC;
                const dEnd = tK * gA + iDim.Wh * tw;                                  // the end allowance
                const dFl = iDim.s * (tK / 2 * gA + iDim.lh * (sqrt(1 + gA * gA) - 1)) + tK / 2 * gC + (iDim.s + 1) * iDim.Wh * tw;
                const lhT = lhP + dEnd;                                               // the pocket's half extents, tilt allowed
                const pwhT = iDim.pwh + dFl;
                const whT = pwhT + iDim.s * lhT;
                const chk = inlayPlace(pc.keep, pc.alongY ? pc.x : pc.y, pc.alongY ? pc.x : pc.y, pc.alongY ? pc.y : pc.x, pc.alongY, lhT, whT);
                if (chk.c == undefined)
                {
                    inlayWarn = append(inlayWarn, pc.name ~ " skipped: tilted " ~ fmt(atan(tanT) / degree, 1) ~ " deg with the flange, its longer pocket would reach " ~ chk.why);
                    continue;
                }
                const segsT = inlayOutline(lhT, pwhT, iDim.s, iDim.rc, max(iDim.rc - definition.inlayGap, 0.05 * millimeter));
                const zFl = up ? zc + dIn * sqrt(1 + tanT * tanT) : zc - dIn * sqrt(1 + tanT * tanT);   // the floor at the centre
                const reach = gA * lhT + gC * whT;                                    // the plane's rise across the footprint
                const zP0 = up ? min(zLoF, zc - reach) - 1 * millimeter : zFl - reach - 1 * millimeter;
                const zP1 = up ? zFl + reach + 1 * millimeter : max(zHiF, zc + reach) + 1 * millimeter;
                const nS = up ? -1 * nU : nU;                                         // from the floor into the pocket (and the key's way)
                const axis = pc.alongY ? vector(0, 1, 0) : vector(1, 0, 0);
                const uDir = normalize(vector(axis[0], axis[1], gx * axis[0] + gy * axis[1]));   // in the plane, over the key's axis in plan
                const prism = inlayPrism(context, id + ("inlayP" ~ n), segsT, pc.x, pc.y, pc.alongY, zP0, zP1);
                // the floor: a slab on the tilted floor plane, BEYOND it (away from the pocket), subtracted
                // from the prism, so the prism keeps its identity as the tool. An INTERSECTION of the two
                // consumed both and left nothing that qCreatedBy(prism) or (slab) resolved (the user's
                // CANNOT_RESOLVE_ENTITIES at the halves' inlay cut)
                const beyond = inlaySlab(context, id + ("inlaySl" ~ n), vector(pc.x, pc.y, zFl), -1 * nS, uDir, lhT + 3 * millimeter, whT + 3 * millimeter, zP1 - zP0 + 2 * reach + 10 * millimeter);
                var floorOk = false;
                try silent
                {
                    opBoolean(context, id + ("inlayI" ~ n), {
                                "tools" : beyond,
                                "targets" : prism,
                                "operationType" : BooleanOperationType.SUBTRACTION
                            });
                    floorOk = true;
                }
                if (!floorOk || size(evaluateQuery(context, prism)) == 0)
                {
                    try silent { opDeleteBodies(context, id + ("inlayDx" ~ n), { "entities" : qUnion([prism, beyond]) }); }
                    inlayWarn = append(inlayWarn, pc.name ~ " skipped: its tilted pocket could not be built");
                    continue;
                }
                const tool = prism;
                if (up)
                    cutU = append(cutU, tool);
                else
                    cutL = append(cutL, tool);
                // the key on the floor, its footprint centred on the pocket's: its face on the floor is moved half
                // its thickness against the normal's lean
                const bx = pc.x - tK / 2 * nS[0];
                const by = pc.y - tK / 2 * nS[1];
                inlayKeys = append(inlayKeys, { "name" : pc.name, "origin" : vector(bx, by, zFl + gx * (bx - pc.x) + gy * (by - pc.y)), "normal" : nS, "xDir" : uDir, "thick" : tK });
                if (tanT > tiltMax)
                {
                    tiltMax = tanT;
                    tiltAt = pc.name;
                }
                if (tanT > 0.2126)
                    nSteep += 1;
                endMax = max(endMax, dEnd);
                if (proud > proudMax)
                {
                    proudMax = proud;
                    proudAt = pc.name;
                }
            }
            if (size(cutU) > 0 && size(evaluateQuery(context, qUnion(cutU))) > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "inlayCutU", {
                            "tools" : qUnion(cutU),
                            "targets" : hv.upper,
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
            }
            if (size(cutL) > 0 && size(evaluateQuery(context, qUnion(cutL))) > 0)
            {
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + "inlayCutL", {
                            "tools" : qUnion(cutL),
                            "targets" : hv.lower,
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
            }
            const sheetK = ceil(tK / millimeter - 1e-6);
            inlayNote = size(yCutsU) + size(yCutsL) + size(xCuts) == 0 ? "puzzle inlays: none - one tile per half, no seams to key" :
                "puzzle inlays: " ~ size(inlayKeys) ~ " bow-tie pockets " ~ fmt(2 * lhP / millimeter, 1) ~ " x " ~ fmt(2 * whP / millimeter, 1) ~ " mm (waist " ~ fmt(2 * iDim.pwh / millimeter, 1) ~ ") on a level flange, " ~ fmt(dIn / millimeter, 1) ~
                " mm deep along the flange's normal, straddling the tile seams in the parting-face flanges, inside corners R " ~ fmt(iDim.rc / millimeter, 1) ~ " (the " ~ fmt(definition.inlayCutter / millimeter, 1) ~ " mm cutter), the waist's outside corners R " ~ fmt(max(iDim.rc - definition.inlayGap, 0.05 * millimeter) / millimeter, 2) ~
                ", walls vertical: mill each from the top in its tile's cavity setup | " ~
                size(inlayKeys) ~ " keys built as parts (Tile key ...), " ~ fmt(2 * iDim.lh / millimeter, 1) ~ " x " ~ fmt(2 * iDim.Wh / millimeter, 1) ~ " mm (waist " ~ fmt(2 * iDim.wh / millimeter, 1) ~ ") x " ~ fmt(tK / millimeter, 2) ~
                " mm thick, square-edged, corners rounded R " ~ fmt(iDim.rc / millimeter, 1) ~ " as the cutter leaves them: cut from " ~ fmt(sheetK, 0) ~ " mm sheet" ~ (sheetK - tK / millimeter > 0.01 ? " faced to " ~ fmt(tK / millimeter, 2) : "") ~
                ", glue each into its pocket across the seam, " ~ fmt(flush / millimeter, 2) ~ " mm under the parting face" ~
                (tiltMax > 0.0009 ? "; floors and keys follow the flange: tilt up to " ~ fmt(atan(tiltMax) / degree, 1) ~ " deg (" ~ tiltAt ~ "), end gap up to " ~ fmt(endMax / millimeter, 2) ~ " mm beyond the Glue gap (glue-filled)" : "") ~
                (size(inlayWarn) > 0 ? "; " ~ size(inlayWarn) ~ " skipped (see the warning)" : "");
            if (nSteep > 0)
                inlayWarn = append(inlayWarn, nSteep ~ " inlay key" ~ (nSteep == 1 ? "" : "s") ~ " tilt more than 12 deg with the flange, up to " ~ fmt(atan(tiltMax) / degree, 1) ~ " deg (" ~ tiltAt ~ "): a shorter Inlay length, or move the seam (another Printer Y)");
            if (proudMax > 0.02 * millimeter)
                inlayWarn = append(inlayWarn, "the flange curves off the plane its key follows (" ~ proudAt ~ "): that key stands " ~ fmt(proudMax / millimeter, 2) ~ " mm proud of the parting face - sand it flush after gluing, before closing the mold, or a shorter Inlay length");
        }

        // cuts: upper first (everything except the still-single lower body), then the lower, then the
        // chordwise cuts through everything
        var cutBodies = [];
        var kc = 0;
        for (var yc in yCutsU)
        {
            hv = moldHalves(context, solids, lo, hi);
            cutBodies = append(cutBodies, moldCut(context, id + ("cut" ~ kc), hv.upper, vector(0 * meter, yc, 0 * meter), Y_DIRECTION, lo, hi));
            kc += 1;
        }
        for (var yc in yCutsL)
        {
            hv = moldHalves(context, solids, lo, hi);
            cutBodies = append(cutBodies, moldCut(context, id + ("cut" ~ kc), hv.lower, vector(0 * meter, yc, 0 * meter), Y_DIRECTION, lo, hi));
            kc += 1;
        }
        for (var xc in xCuts)
        {
            hv = moldHalves(context, solids, lo, hi);
            cutBodies = append(cutBodies, moldCut(context, id + ("cut" ~ kc), qUnion([hv.upper, hv.lower]), vector(xc, 0 * meter, 0 * meter), X_DIRECTION, lo, hi));
            kc += 1;
        }
        if (size(cutBodies) > 0)
            opDeleteBodies(context, id + "deleteCuts", { "entities" : qUnion(cutBodies) });

        // ---------------- printed keys (after the cuts, so no boss straddles a joint) ----------------
        if (printed)
        {
            const rB = pinDiaV / 2;
            const hb = definition.keyHeight;
            const fit = definition.pinFit;
            var kk = 0;
            for (var side = 0; side < (puzzle ? 0 : 2); side += 1)
            {
                const yCuts = side == 0 ? yCutsU : yCutsL;
                const zPin = side == 0 ? zPinU : zPinL;
                var locs = [];
                for (var yc in yCuts)
                {
                    locs = append(locs, [vector(xFront, yc, zPin), Y_DIRECTION]);
                    locs = append(locs, [vector(xAft, yc, zPin), Y_DIRECTION]);
                }
                const bounds = concatenateArrays([[lo[1]], yCuts, [hi[1]]]);
                for (var xc in xCuts)
                    for (var k = 0; k + 1 < size(bounds); k += 1)
                        locs = append(locs, [vector(xc, 0.5 * (bounds[k] + bounds[k + 1]), zPin), X_DIRECTION]);
                for (var loc in locs)
                {
                    if (moldPrintedKey(context, id + ("tk" ~ (kk + nSkippedKeys)), solids, lo, hi, side, side,
                            loc[0] - 1 * millimeter * loc[1], loc[0] + (hb + 1 * millimeter) * loc[1], loc[0], loc[1], rB, rT, hb, fit))
                        kk += 1;
                    else
                        nSkippedKeys += 1;
                }
            }
            nPins = kk;
            if (definition.keysOn)
            {
                const rBk = definition.keyDia / 2;
                const rTk = rBk - hb * tan(definition.keyDraft);
                for (var k = 0; k < nY; k += 1)
                {
                    var yk = lo[1] + (k + 0.25) * tileY;
                    if (keepY > 0 * meter && abs(yk - keepC) < keepY + rBk + 2 * millimeter)
                        yk = keepC + (yk >= keepC ? 1 : -1) * (keepY + rBk + 2 * millimeter);   // clear of the pad / nacelle / pod channel
                    var zf = zPart;
                    var za = zPart;
                    if (!isFlat)
                    {
                        const pp = wTab != undefined && abs(yk) > wY0 ? moldPartingPointsWinglet(wTab, abs(yk), yk < 0 * meter ? -1 : 1, lo[0] - e, hi[0] + e) : moldPartingPointsPad(m, mini, min(abs(yk) / h, 1), yk, base, lo[0] - e, hi[0] + e, sockOn && abs(yk) <= max(sock.nacelleDia / 2 * meter, sockReach) * 1.0001 ? sock : undefined, abs(yk) < (padMap != undefined ? padMap.padWidth / 2 * meter : 0 * meter) ? padMap : undefined);
                        zf = pp.front[2];
                        za = pp.aft[2];
                    }
                    else if (isFus)
                    {
                        zf = fusPartZ(fusPart, xFront);
                        za = fusPartZ(fusPart, xAft);
                    }
                    const pts = [vector(xFront, yk, zf), vector(xAft, yk, za)];
                    for (var j = 0; j < 2; j += 1)
                    {
                        if (moldPrintedKey(context, id + ("hk" ~ k ~ "_" ~ j), solids, lo, hi, 1, 0, pts[j], pts[j], pts[j], Z_DIRECTION, rBk, rTk, hb, fit))
                            nKeys += 1;
                        else
                            nSkippedKeys += 1;
                    }
                }
            }
        }

        // ---------------- plate tray keys (mast): two printed keys on the tray's opening face ----------------
        if (isMast)
        {
            const pA = plateAct != undefined;
            const xcT = pA ? (plateAct.x0 + plateAct.x1) / 2 : (mastM.plateXc != undefined ? mastM.plateXc : mastM.leX + mastM.chord / 2) * meter;
            const zcT = pA ? (plateAct.y0 + plateAct.y1) / 2 + zPart : zPart;
            const hbT = definition.keyHeight;
            const rBT = definition.keyDia / 2;
            const rTT = rBT - hbT * tan(definition.keyDraft);
            const zK = (pA ? (plateAct.y1 - plateAct.y0) / 2 : mastM.plateWidth / 2 * meter) + definition.baseThick / 2;      // in the flange beyond the plate
            for (var k = 0; k < 2; k += 1)
            {
                const pk = vector(xcT, lo[1], zcT + (k == 0 ? zK : -zK));
                const dY = Y_DIRECTION;
                const sockT = moldFrustum(context, id + ("trayKeyS" ~ k), pk - 1 * millimeter * dY, pk + (hbT + 0.3 * millimeter) * dY, rBT + definition.pinFit, rTT + definition.pinFit);
                hv = moldHalves(context, solids, lo, hi);
                opBoolean(context, id + ("trayKeyCut" ~ k), {
                            "tools" : sockT,
                            "targets" : moldTileAt(context, k == 0 ? hv.upper : hv.lower, pk + 2 * millimeter * dY),
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
                const bossT = moldFrustum(context, id + ("trayKeyB" ~ k), pk - 1 * millimeter * dY, pk + hbT * dY, rBT, rTT);
                opBoolean(context, id + ("trayKeyJoin" ~ k), {
                            "tools" : qUnion([qHasAttribute("foilPlateTray"), bossT]),
                            "operationType" : BooleanOperationType.UNION
                        });
            }
        }
        // ---------------- pry sections (build 242) ----------------
        // User: Easy Composites chamfer the parting line "to allow a wedge tool to pry it open"; "areas not corners to
        // start the mold opening, not the entire length but sections"; "no larger than 100 mm"; "only large enough to take
        // a wedge". A 45 deg V across the parting on each outer face: a square bar turned 45 deg about the face's run,
        // centred on the parting line, found by a ray up into the upper half 0.5 mm inside the face, cut from both halves.
        // Along each face, one in the middle of every stretch between seams (both halves' seams merged, so each tile gets
        // one and none straddles a joint), more at Pry spacing on a long stretch; none in the plug / pad channel band, none
        // within 10 mm of a corner, none on the mast's board-face end (the plate tray covers it)
        var nPry = 0;
        var pryFaces = 0;
        if (definition.pryOn == true && !preview)
        {
            const pL = definition.pryLength;
            const pD = definition.pryDepth;
            const pSp = definition.prySpacing;
            const sq = pD * sqrt(2);
            for (var fi = 0; fi < 4; fi += 1)
            {
                const ax = fi < 2 ? 0 : 1;                                  // the face's normal axis: X faces run along Y, Y faces along X
                const run = 1 - ax;
                if (isMast && fi == 2)
                    continue;
                const face = fi % 2 == 0 ? lo[ax] : hi[ax];
                const inward = fi % 2 == 0 ? 1 : -1;
                var seams = run == 1 ? concatenateArrays([yCutsU, yCutsL]) : xCuts;
                seams = concatenateArrays([[lo[run] + 10 * millimeter], seams, [hi[run] - 10 * millimeter]]);
                seams = sort(seams, function(a, b) { return a - b; });
                var placed = 0;
                for (var k = 0; k + 1 < size(seams); k += 1)
                {
                    const a = seams[k] + (k == 0 ? 0 * meter : 5 * millimeter);
                    const b = seams[k + 1] - (k + 2 == size(seams) ? 0 * meter : 5 * millimeter);
                    if (b - a < pL)
                        continue;
                    const n = max(1, round((b - a) / pSp));
                    for (var i = 0; i < n; i += 1)
                    {
                        const t = min(max(a + (b - a) * (i + 0.5) / n, a + pL / 2), b - pL / 2);
                        if (run == 1 && keepY > 0 * meter && abs(t - keepC) < keepY + pL / 2)
                            continue;
                        const xr = ax == 0 ? face + inward * 0.5 * millimeter : t;
                        const yr = ax == 0 ? t : face + inward * 0.5 * millimeter;
                        hv = moldHalves(context, solids, lo, hi);
                        const r = moldRayZ(context, hv.upper, xr, yr, lo[2] - 20 * millimeter, true);
                        if (!r.hit || r.z > hi[2] - 2 * pD || r.z < lo[2] + 2 * pD)
                            continue;
                        const c = ax == 0 ? vector(face, t, r.z) : vector(t, face, r.z);
                        const half = ax == 0 ? vector(sq / 2, pL / 2, sq / 2) : vector(pL / 2, sq / 2, sq / 2);
                        const pid = id + ("pry" ~ fi ~ "_" ~ placed);
                        moldBox(context, pid, c - half, c + half);
                        opTransform(context, pid + "rot", {
                                    "bodies" : qCreatedBy(pid, EntityType.BODY),
                                    "transform" : rotationAround(line(c, run == 1 ? Y_DIRECTION : X_DIRECTION), 45 * degree)
                                });
                        var ok = false;
                        try silent
                        {
                            opBoolean(context, pid + "cut", {
                                        "tools" : qCreatedBy(pid, EntityType.BODY),
                                        "targets" : qUnion([hv.upper, hv.lower]),
                                        "operationType" : BooleanOperationType.SUBTRACTION
                                    });
                            ok = true;
                        }
                        if (!ok)
                            try silent { opDeleteBodies(context, pid + "del", { "entities" : qCreatedBy(pid, EntityType.BODY) }); }
                        else
                        {
                            nPry += 1;
                            placed += 1;
                        }
                    }
                }
                if (placed > 0)
                    pryFaces += 1;
            }
            foilPrint(context, moldLogKey, "PRY: " ~ nPry ~ " sections " ~ fmt(definition.pryLength / millimeter, 0) ~ " mm long, 45 deg, " ~ fmt(definition.pryDepth / millimeter, 1) ~ " mm into each half, on " ~ pryFaces ~ " faces");
        }

        // ---------------- ejector holes (build 243) ----------------
        // User: pins "to hammer complex deep part out of a mold"; a choice of dowel or printed plug. Spots from rays, not from
        // the model: along each candidate line the part's thickness from the two halves' cavity faces, the thickest spot
        // whose rim is smooth on both faces (no pin, pocket or cone edge within Ejector dia / 2 + 1.5 mm). Wing / stab: lines
        // either side of the joint, the first that passes nearest the centre (the solid root zone); mast: lines near each
        // end; fuselage: the centreline, one per third of its length. Each spot gets a hole through both halves
        var nEject = 0;
        var ejectAt = [];
        var ejectStr = "";
        if (definition.ejector != undefined && definition.ejector != MoldEjector.OFF && !preview)
        {
            const rE = definition.ejectorDia / 2;
            const plugs = definition.ejector == MoldEjector.PLUG;
            const fitE = plugs ? (definition.ejectorFit == undefined ? 0.15 * millimeter : definition.ejectorFit) / 2 : 0.1 * millimeter;
            const zB = lo[2] - 20 * millimeter;
            const zA = hi[2] + 20 * millimeter;
            const rim = rE + (plugs ? 2 * millimeter : 0 * meter) + 1.5 * millimeter;
            const headE = 2.5 * millimeter;                                   // build 245: a plug's head depth, on the cavity side
            hv = moldHalves(context, solids, lo, hi);
            // candidate lines: [axis of the scan (0 = along X at fixed y, 1 = along Y at fixed x), the fixed coordinate, group]
            var lines = [];
            if (isFus)
                lines = [[0, 0 * meter, 0]];
            else if (isMast)
            {
                const yTopE = -(mastM.baseZ + mastM.height) * meter;
                const yBaseE = -mastM.baseZ * meter;
                for (var c in [15, 25, 40, 60])
                {
                    lines = append(lines, [0, yTopE + c * millimeter, 0]);
                    lines = append(lines, [0, yBaseE - c * millimeter, 1]);
                }
            }
            else
            {
                const c0 = max(12 * millimeter, keepY + rim + 2 * millimeter);
                for (var c in [0, 4, 8, 14, 22, 32, 45])
                {
                    lines = append(lines, [0, c0 + c * millimeter, 0]);
                    lines = append(lines, [0, -c0 - c * millimeter, 1]);
                }
            }
            var groupDone = [false, false];
            var spots = [];
            for (var ln in lines)
            {
                if (!isFus && groupDone[ln[2]])
                    continue;
                // scan along X between the flanges
                var samples = [];
                const nS = floor((hi[0] - lo[0] - 2 * f) / (3 * millimeter));
                for (var i = 0; i <= nS; i += 1)
                {
                    const x = lo[0] + f + (hi[0] - lo[0] - 2 * f) * i / max(nS, 1);
                    const pr = moldEjectProbe(context, hv.upper, hv.lower, x, ln[1], zB, zA, rim, false);
                    if (pr.ok)
                        samples = append(samples, [x, pr.t]);
                }
                if (size(samples) == 0)
                    continue;
                if (isFus)
                {
                    // one per third of the part's length
                    const xa = samples[0][0];
                    const xb = samples[size(samples) - 1][0];
                    for (var g = 0; g < 3; g += 1)
                    {
                        var part = [];
                        for (var smp in samples)
                            if (smp[0] >= xa + (xb - xa) * g / 3 && smp[0] <= xa + (xb - xa) * (g + 1) / 3)
                                part = append(part, smp);
                        part = sort(part, function(a, b) { return b[1] - a[1]; });
                        for (var j = 0; j < min(size(part), 8); j += 1)
                        {
                            const pr = moldEjectProbe(context, hv.upper, hv.lower, part[j][0], ln[1], zB, zA, rim, true);
                            if (pr.ok)
                            {
                                spots = append(spots, [part[j][0], ln[1], pr.zU, pr.zL, pr.t]);
                                break;
                            }
                        }
                    }
                }
                else
                {
                    samples = sort(samples, function(a, b) { return b[1] - a[1]; });
                    for (var j = 0; j < min(size(samples), 8); j += 1)
                    {
                        const pr = moldEjectProbe(context, hv.upper, hv.lower, samples[j][0], ln[1], zB, zA, rim, true);
                        if (pr.ok)
                        {
                            spots = append(spots, [samples[j][0], ln[1], pr.zU, pr.zL, pr.t]);
                            groupDone[ln[2]] = true;
                            break;
                        }
                    }
                }
            }
            for (var sp in spots)
            {
                for (var side = 0; side < 2; side += 1)
                {
                    const up = side == 0;
                    const zOut = up ? hi[2] : lo[2];
                    const zCav = up ? sp[2] : sp[3];
                    const sg = up ? 1 : -1;                                   // outward
                    const dIn = min(0.5 * millimeter, sp[4] / 3);              // past the cavity face, into the part's space
                    const eid = id + ("ej" ~ nEject ~ "_" ~ side);
                    hv = moldHalves(context, solids, lo, hi);
                    const tile = moldTileAt(context, up ? hv.upper : hv.lower, vector(sp[0], sp[1], zCav + sg * 2 * millimeter));
                    if (size(evaluateQuery(context, tile)) == 0)
                        continue;
                    var plugQ;
                    if (plugs)
                    {
                        // the plug (build 245, user: "ejector pins have to be pushed into the mold, you have a head that would
                        // prevent this"; "the head could be on the inside"): the head at the cavity end, in a counterbore in the
                        // cavity face, so the laminate's pressure seats it on the counterbore's shoulder and a punch from outside
                        // pushes it, and the part, inward. Shank and head as one, kept only where the tile's copy is, so the head's
                        // face is the cavity's and the shank's end flush with the outer face; found after the hole is cut by the
                        // point it holds (a boolean's result keeps no reliable identity)
                        opPattern(context, eid + "copy", { "entities" : tile, "transforms" : [identityTransform()], "instanceNames" : ["c"] });
                        const shank = moldPin(context, eid + "shank", vector(sp[0], sp[1], zOut + sg * 1 * millimeter), vector(sp[0], sp[1], zCav - sg * dIn), rE - fitE);
                        const head = moldPin(context, eid + "head", vector(sp[0], sp[1], zCav - sg * dIn), vector(sp[0], sp[1], zCav + sg * headE), rE + 2 * millimeter - fitE);
                        opBoolean(context, eid + "plugJoin", { "tools" : qUnion([shank, head]), "operationType" : BooleanOperationType.UNION });
                        opBoolean(context, eid + "plugTrim", {
                                    "tools" : qUnion([qCreatedBy(eid + "copy", EntityType.BODY), qCreatedBy(eid + "shank", EntityType.BODY), qCreatedBy(eid + "head", EntityType.BODY)]),
                                    "operationType" : BooleanOperationType.INTERSECTION
                                });
                        plugQ = true;
                    }
                    var cutters = [moldPin(context, eid + "hole", vector(sp[0], sp[1], zOut + sg * 1 * millimeter), vector(sp[0], sp[1], zCav - sg * dIn), rE + (plugs ? 0 * meter : 0.1 * millimeter))];
                    if (plugs)
                        cutters = append(cutters, moldPin(context, eid + "cbore", vector(sp[0], sp[1], zCav - sg * dIn), vector(sp[0], sp[1], zCav + sg * headE), rE + 2 * millimeter));
                    opBoolean(context, eid + "cut", { "tools" : qUnion(cutters), "targets" : tile, "operationType" : BooleanOperationType.SUBTRACTION });
                    if (plugs)
                        plugQ = qContainsPoint(qBodyType(qEverything(EntityType.BODY), BodyType.SOLID), vector(sp[0], sp[1], (zOut + zCav) / 2));
                    if (plugs)
                        setAttribute(context, { "entities" : plugQ, "name" : "foilEjectPlug", "attribute" : true });
                    if (plugs)
                        setProperty(context, { "entities" : plugQ, "propertyType" : PropertyType.NAME, "value" : "Ejector plug " ~ (nEject + 1) ~ (up ? " (upper)" : " (lower)") });
                }
                nEject += 1;
                ejectStr = ejectStr ~ (size(ejectAt) > 0 ? "; " : "") ~ "X " ~ fmt(sp[0] / millimeter, 0) ~ " Y " ~ fmt(sp[1] / millimeter, 0) ~ " (" ~ fmt(sp[4] / millimeter, 1) ~ " mm thick)";
                ejectAt = append(ejectAt, "X " ~ fmt(sp[0] / millimeter, 0) ~ " Y " ~ fmt(sp[1] / millimeter, 0) ~ " (" ~ fmt(sp[4] / millimeter, 1) ~ " mm thick)");
            }
            foilPrint(context, moldLogKey, "EJECT: " ~ (plugs ? "printed plugs " : "dowel holes ") ~ fmt(definition.ejectorDia / millimeter, 1) ~ " mm, " ~ nEject ~ " spot" ~ (nEject == 1 ? "" : "s") ~ " through both halves" ~ (nEject > 0 ? ": " ~ ejectStr : " - no smooth solid spot found"));
        }

        // ---------------- mast release check (build 241, user: "did you check if your mast changes release?") ----------------
        // A fresh flat copy of the mast; the lid slid off the board face, and the tiles at the plate end of each half slid down
        // the mast (the user: "the mold will slip down from the top plate when the lower section is released") and, for
        // comparison, apart across the parting. Any slide that runs into the part is a lock
        var releaseNote = "";
        var releaseWarn = "";
        if (isMast)
        {
            opPattern(context, id + "relPart", {
                        "entities" : definition.part,
                        "transforms" : [transform(vector(0 * meter, 0 * meter, zPart)) * rotationAround(line(vector(0, 0, 0) * meter, X_DIRECTION), 90 * degree)],
                        "instanceNames" : ["r"]
                    });
            const relPart = qCreatedBy(id + "relPart", EntityType.BODY);
            const yUr = -(mastM.baseZ + mastM.height) * meter;
            hv = moldHalves(context, solids, lo, hi);
            var endU = [];
            var endL = [];
            for (var side = 0; side < 2; side += 1)
            {
                for (var b in evaluateQuery(context, side == 0 ? hv.upper : hv.lower))
                {
                    if (evBox3d(context, { "topology" : b, "tight" : false }).minCorner[1] < yUr + 2 * millimeter)
                    {
                        if (side == 0)
                            endU = append(endU, b);
                        else
                            endL = append(endL, b);
                    }
                }
            }
            const along = [0.3 * millimeter, 1 * millimeter, 3 * millimeter, 8 * millimeter, 15 * millimeter, 25 * millimeter];
            const lidLock = moldSlideLocks(context, id + "relLid", qHasAttribute("foilPlateTray"), relPart, -Y_DIRECTION, along);
            const uDownAt = size(endU) > 0 ? moldSlideLockAt(context, id + "relUd", qUnion(endU), relPart, Y_DIRECTION, along, zPart) : "";
            const lDownAt = size(endL) > 0 ? moldSlideLockAt(context, id + "relLd", qUnion(endL), relPart, Y_DIRECTION, along, zPart) : "";
            const uDown = uDownAt != "";
            const lDown = lDownAt != "";
            const uOpen = size(endU) > 0 && moldSlideLocks(context, id + "relUo", qUnion(endU), relPart, Z_DIRECTION, along);
            const lOpen = size(endL) > 0 && moldSlideLocks(context, id + "relLo", qUnion(endL), relPart, -Z_DIRECTION, along);
            opDeleteBodies(context, id + "relPartDel", { "entities" : relPart });
            releaseNote = " | release check: lid off the board face " ~ (lidLock ? "LOCKS" : "releases") ~ "; the plate-end tiles slid down the mast " ~ (uDown || lDown ? "LOCK (" ~ (uDown ? "upper" : "") ~ (uDown && lDown ? " and " : "") ~ (lDown ? "lower" : "") ~ ")" : "release") ~
                ", pulled apart across the parting " ~ (uOpen || lOpen ? "lock" : "release") ~ (uOpen || lOpen ? " (the bolt pins and cones stand across that pull: slide them down the mast first)" : "");
            foilPrint(context, moldLogKey, "MAST_RELEASE: lid " ~ (lidLock ? "LOCKS" : "ok") ~ "; upper end tile down " ~ (uDown ? "LOCKS " ~ uDownAt : "ok") ~ ", apart " ~ (uOpen ? "locks" : "ok") ~ "; lower end tile down " ~ (lDown ? "LOCKS " ~ lDownAt : "ok") ~ ", apart " ~ (lOpen ? "locks" : "ok") ~
                "; end tiles " ~ size(endU) ~ " / " ~ size(endL));
            if (lidLock || uDown || lDown)
                releaseWarn = ("the mast mold's release check found a lock (" ~ (lidLock ? "the lid off the board face" : "") ~ (lidLock && (uDown || lDown) ? ", " : "") ~ (uDown || lDown ? "a plate-end tile slid down the mast" : "") ~ ") - a feature stands across that pull; see MAST_RELEASE on the console");
        }

        // ---------------- slivers (build 235) ----------------
        // A knife-edge tip (Tip cap Tapered with Min tip off and a low End ratio) leaves zero-volume
        // slivers where the cavity cut or the parting split meets it: bodies that touch neither block
        // face (tight boxes, as moldFloating) and hold under 0.05 cm3 (evVolume, or the tight box when it
        // cannot be measured), and are not a plug or the tray. Deleted here and reported on their own
        // line, so the tile count and the "key bodies did not attach" warning see only real bodies
        var nSlivers = 0;
        {
            var slivers = [];
            const keepQ = qUnion([qHasAttribute("foilSockPlug"), qHasAttribute("foilPodPlug"), qHasAttribute("foilPlateTray")]);
            const vMin = 0.05 * centimeter * centimeter * centimeter;
            for (var b in evaluateQuery(context, qSubtraction(solids, keepQ)))
            {
                const sb = evBox3d(context, { "topology" : b, "tight" : true });
                if (sb.maxCorner[2] > hi[2] - 0.5 * millimeter || sb.minCorner[2] < lo[2] + 0.5 * millimeter)
                    continue;                                                     // on a block face: a tile
                const dv = sb.maxCorner - sb.minCorner;
                var vol = dv[0] * dv[1] * dv[2];
                try silent
                {
                    vol = evVolume(context, { "entities" : b });
                }
                if (vol < vMin)
                    slivers = append(slivers, b);
            }
            if (size(slivers) > 0)
            {
                opDeleteBodies(context, id + "slivers", { "entities" : qUnion(slivers) });
                nSlivers = size(slivers);
            }
        }

        // ---------------- parting self-check (build 235) ----------------
        // At eight spanwise points (from 2 % of the half span to 95 % or a winglet's bend) and either side
        // of every tile seam, a horizontal ray finds the part's real trailing and leading edge, and vertical
        // rays 0.5, 1 and 2 mm inside each (1 mm beside a seam) compare the halves' first faces with the
        // part's skins: the upper half's from below should be the top skin, the lower half's from above the
        // bottom skin. More than 0.05 mm off means the parting leaves the section there and one half laps
        // round the edge, an undercut. Not over a joint (nacelle, hub, flat mount, stab pad) or a mirrored
        // stab mold; silent on success, a console line either way
        var partingWarn = [];
        if (!isFlat && !flipZ)
        {
            const hY = m.span / 2 * meter;
            const yEnd = hY * min(0.95, m.wingletOn == 1 ? m.wingletEta - 0.01 : 0.95);
            const yKeep = padMap != undefined ? padMap.padWidth / 2 * meter + 2 * millimeter :
                (sockOn ? max(nacW / 2 + 20 * millimeter, sockReach) + 5 * millimeter : (hubOn ? (hub.reach != undefined ? max(hub.reach, hub.width / 2) : hub.width / 2) * meter + 5 * millimeter : (flatOn ? jointHalfW + 5 * millimeter : 0 * meter)));
            var pts = [];                                                      // [y, offsets]
            for (var j = 0; j < 8; j += 1)
                pts = append(pts, [0.02 * hY + (yEnd - 0.02 * hY) * j / 7, [0.5, 1, 2]]);
            for (var yq in concatenateArrays([yCutsU, yCutsL]))
                for (var sy in [-1.5, 1.5])
                    pts = append(pts, [yq + sy * millimeter, [1]]);
            hv = moldHalves(context, solids, lo, hi);
            var worst = [0 * meter, 0 * meter];                                // TE, LE: how far the parting leaves the section
            var worstY = [0 * meter, 0 * meter];
            var worstUp = [true, true];                                        // true: the lower half laps over (parting above the top skin)
            var nChecked = 0;
            for (var pq in pts)
            {
                const y = pq[0];
                if (abs(y) < yKeep || abs(y) > yEnd)
                    continue;
                const sq = moldCoreSectionAt(m, mini, y);
                if (sq.ok != true || sq.winglet == true)
                    continue;
                const np = size(sq.placed);
                var iTe = 0;
                var iLe = 0;
                for (var i = 0; i < np; i += 1)
                {
                    if (sq.placed[i][0] > sq.placed[iTe][0])
                        iTe = i;
                    if (sq.placed[i][0] < sq.placed[iLe][0])
                        iLe = i;
                }
                for (var edge = 0; edge < 2; edge += 1)
                {
                    // the model's edge, then the part's own along a horizontal ray toward it
                    const pe = edge == 0 ? moldCorePoint(sq, sq.placed[iTe][0], 0.5 * (sq.placed[0][1] + sq.placed[np - 1][1])) : moldCorePoint(sq, sq.placed[iLe][0], sq.placed[iLe][1]);
                    const dirX = edge == 0 ? -1 : 1;
                    var xEdge = pe[0];
                    try silent
                    {
                        const hits = evRaycast(context, { "entities" : moldPart, "ray" : line(vector(pe[0] - dirX * 20 * millimeter, y, pe[2]), vector(dirX, 0, 0)), "closest" : true });
                        if (size(hits) > 0)
                            xEdge = hits[0].intersection[0];
                    }
                    for (var dOff in pq[1])
                    {
                        const x = xEdge + dirX * dOff * millimeter;
                        const zTopP = moldRayZ(context, moldPart, x, y, hi[2] + 10 * millimeter, false);
                        const zBotP = moldRayZ(context, moldPart, x, y, lo[2] - 10 * millimeter, true);
                        const zUp = moldRayZ(context, hv.upper, x, y, lo[2] - 10 * millimeter, true);
                        const zLw = moldRayZ(context, hv.lower, x, y, hi[2] + 10 * millimeter, false);
                        if (!zTopP.hit || !zBotP.hit || !zUp.hit || !zLw.hit)
                            continue;
                        nChecked += 1;
                        const lapO = zUp.z - zTopP.z;                          // the upper half's face above the top skin
                        const lapU = zBotP.z - zLw.z;                          // the lower half's face below the bottom skin
                        if (lapO > worst[edge])
                        {
                            worst[edge] = lapO;
                            worstY[edge] = y;
                            worstUp[edge] = true;
                        }
                        if (lapU > worst[edge])
                        {
                            worst[edge] = lapU;
                            worstY[edge] = y;
                            worstUp[edge] = false;
                        }
                    }
                }
            }
            for (var edge = 0; edge < 2; edge += 1)
            {
                if (worst[edge] > 0.05 * millimeter)
                    partingWarn = append(partingWarn, "the parting leaves the section by " ~ fmt(worst[edge] / millimeter, 2) ~ " mm near the " ~ (edge == 0 ? "trailing" : "leading") ~ " edge at y = " ~ fmt(worstY[edge] / millimeter, 0) ~ " mm: the " ~
                        (worstUp[edge] ? "lower half laps over" : "upper half laps under") ~ " the " ~ (edge == 0 ? "TE" : "LE") ~ " - this build's droop stations should prevent it; report with the mold's inputs");
            }
            foilPrint(context, moldLogKey, "PARTING_CHECK: " ~ nChecked ~ " points checked; TE worst " ~ fmt(worst[0] / millimeter, 3) ~ " mm at y " ~ fmt(worstY[0] / millimeter, 0) ~ (worstUp[0] ? " (over)" : " (under)") ~
                "; LE worst " ~ fmt(worst[1] / millimeter, 3) ~ " mm at y " ~ fmt(worstY[1] / millimeter, 0) ~ (worstUp[1] ? " (over)" : " (under)"));
        }

        // ---------------- names ----------------
        // "<Wing|Stab> mold <upper|lower> <k> of <n>" from the -Y end, with fwd/aft when cut across the chord
        const nTilesU = (stagger ? nY + 1 : nY) * nX;
        const nTilesL = nY * nX;
        hv = moldHalves(context, solids, lo, hi);
        // anything that is neither an upper nor a lower tile at this point is a key that did not attach;
        // the mast's plate tray spans the block's height and is not a tile either (build 226)
        const nTray = isMast ? size(evaluateQuery(context, qHasAttribute("foilPlateTray"))) : 0;
        nSpecks += moldDropSpecks(context, id + "specks2", solids, lo, hi);
        if (nSpecks > 0)
            foilPrint(context, moldLogKey, "MOLD_SPECKS: " ~ nSpecks ~ " loose bodies under 1 mm3 deleted (specks the cavity cut free: a thin web against the parting, a tip sliver)");
        const nEjPlugs = size(evaluateQuery(context, qHasAttribute("foilEjectPlug")));     // printed ejector plugs (build 243) are parts of their own
        const nFloating = size(evaluateQuery(context, solids)) - hv.nUpper - hv.nLower - (podPlug ? 1 : 0) - (plugOn ? 1 : 0) - nTray - nEjPlugs;
        const partName = (definition.moldSource == MoldSource.WING ? "Wing " : (isMast ? "Mast " : (isFus ? "Fuselage " : "Stab "))) ~ (coreMold ? "core mold" : "mold");
        for (var side = 0; side < 2; side += 1)
        {
            const tiles = moldSortTiles(context, side == 0 ? hv.upper : hv.lower);
            const nRows = size(tiles) / nX;
            for (var i = 0; i < size(tiles); i += 1)
            {
                const row = floor(i / nX) + 1;
                const col = i % nX;
                const nm = partName ~ (isMast ? (side == 0 ? " left " : " right ") : (side == 0 ? " upper " : " lower ")) ~ row ~ " of " ~ nRows ~
                    (nX > 1 ? (col == 0 ? " fwd" : (col == nX - 1 ? " aft" : " mid" ~ col)) : "");
                setProperty(context, { "entities" : tiles[i], "propertyType" : PropertyType.NAME, "value" : nm });
            }
        }
        // ---------------- puzzle inlay keys (build 235): one part per pocket, sitting in it ----------------
        // The nominal bow-tie (the pocket less the Glue gap, corners rounded as the cutter leaves them), a
        // square-edged plate Inlay depth less Key flush thick lying on its pocket's floor, which follows
        // the flange; made after every mold operation and kept out of the tile counts by their attribute.
        // Export them flat and cut them from sheet: every key is the same profile
        if (size(inlayKeys) > 0)
        {
            const kDim = inlayDims(definition);
            for (var n = 0; n < size(inlayKeys); n += 1)
            {
                const kk = inlayKeys[n];
                const kq = inlayPlate(context, id + ("inlayKey" ~ n), kDim.key, kk.origin, kk.normal, kk.xDir, kk.thick);
                setAttribute(context, { "entities" : kq, "name" : "foilInlayKey", "attribute" : 1 });
                setProperty(context, { "entities" : kq, "propertyType" : PropertyType.NAME, "value" : kk.name });
            }
        }
        // ---------------- socket plug part ----------------
        var sockPlugLost = false;
        if (plugOn)
        {
            const sq = qHasAttribute("foilSockPlug");
            if (size(evaluateQuery(context, sq)) > 0)
                setProperty(context, { "entities" : sq, "propertyType" : PropertyType.NAME, "value" : "Wing socket plug" });
            else
                sockPlugLost = true;
        }
        if (isMast)
            setProperty(context, { "entities" : qHasAttribute("foilPlateTray"), "propertyType" : PropertyType.NAME, "value" : "Mast plate mold" });
        var plugLost = false;
        if (podPlug)
        {
            var pq = qHasAttribute("foilPodPlug");
            if (size(evaluateQuery(context, pq)) == 0)
                pq = moldFloating(context, solids, lo, hi);
            if (size(evaluateQuery(context, pq)) > 0)
                setProperty(context, { "entities" : pq, "propertyType" : PropertyType.NAME, "value" : "Mast pod plug" });
            else
                plugLost = true;
        }
        const nAll = size(evaluateQuery(context, solids));
        const hUp = (hi[2] - lo[2]) / millimeter;     // a half is at most the block height
        var warnings = [];
        if (releaseWarn != "")
            warnings = append(warnings, releaseWarn);
        // closing: what presses the halves together
        var closingNote = "";
        {
            const blockArea = (hi[0] - lo[0]) * (hi[1] - lo[1]) / (centimeter * centimeter);         // cm2, plan
            const partPlan = (pbox.maxCorner[0] - pbox.minCorner[0]) * (pbox.maxCorner[1] - pbox.minCorner[1]) / (centimeter * centimeter);
            if (definition.closing == MoldClosing.BAG)
            {
                const forceN = definition.bagVac * 1000 * blockArea * 1e-4;                           // Pa x m2
                const lamBar = definition.bagVac / 100 * blockArea / max(partPlan, 1);
                closingNote = " | closing: vacuum bag at " ~ fmt(definition.bagVac, 0) ~ " kPa gives " ~ fmt(forceN / 1000, 1) ~ " kN on the " ~ fmt(blockArea, 0) ~ " cm2 block, " ~
                    fmt(lamBar, 1) ~ " bar on the laminate" ~ (roundOn && !roundFailed ? "; outer edges rounded " ~ fmt(definition.edgeRound / millimeter, 0) ~ " mm" : "") ~
                    (roundFailed ? "; EDGE ROUND FAILED (the tiles are sharp-edged: pad the corners under the bag)" : "") ~
                    "; glue the tiles first, breather over the whole mold, check the flange gap with feelers before the resin gels";
                if (definition.overchargePct > 6)
                    warnings = append(warnings, "Overcharge " ~ fmt(definition.overchargePct, 0) ~ " % is more than a bag can squeeze out: 3-5 % with Closing = Vacuum bag");
                if (definition.grooveOn && nVents == 0 && definition.ventOn)
                    warnings = append(warnings, "no groove vents were cut (both loop ends lie outside the block) - the groove is a sealed pocket in the bag; check the flange gap");
            }
            else
                closingNote = " | closing: clamps on the flanges against a rigid board (" ~ fmt(blockArea, 0) ~ " cm2 block; a vacuum bag would give " ~ fmt(85 * 1000 * blockArea * 1e-4 / 1000, 1) ~ " kN at 85 kPa)";
            if (sockOn && !definition.plugOn)
                warnings = append(warnings, "the tube socket is molded by the halves as two half cores (a seam down the bore, and its pin holes as pins from both halves): turn Socket plug on in the Socket group");
            if (plugOn && sockCores == 0)
                warnings = append(warnings, "no core of the bore was found after the plug channel cut, so the socket plug is only its handle: is the bore open at the rear face, or does a bolt hole off the Foil wing's pattern still tie the bore to a half? Inspect the halves");
            if (rayMiss > 0)
                warnings = append(warnings, rayMiss ~ " ray cast" ~ (rayMiss == 1 ? "" : "s") ~ " at the joint's bolt holes met nothing on the part (nominal heights used for clearing the pins there): check the pins and countersinks in the halves");
            if (sockPlugLost)
                warnings = append(warnings, "the socket plug body was not found after the channel cut - inspect the bodies");
            if (nGroove > 0 && grooveVol > 0 && flashVol > grooveVol)
                warnings = append(warnings, "the pinch-off groove holds " ~ fmt(grooveVol, 0) ~ " cm3 but " ~ fmt(definition.overchargePct, 0) ~ " % overcharge makes " ~ fmt(flashVol, 0) ~ " cm3 of flash: deepen Groove depth, widen Groove width, or lower Overcharge %");
        }
        const nExtra = (plugOn ? 1 : 0) + (podPlug ? 1 : 0) + nTray + nEjPlugs;
        if (hv.nUpper != nTilesU || hv.nLower != nTilesL || nAll != nTilesU + nTilesL + nExtra)
            warnings = append(warnings, "expected " ~ nTilesU ~ " upper and " ~ nTilesL ~ " lower tiles" ~ (plugOn ? " plus the socket plug" : "") ~ (podPlug ? " plus the pod plug" : "") ~ (nTray > 0 ? " plus the plate tray" : "") ~ (nEjPlugs > 0 ? " plus " ~ nEjPlugs ~ " ejector plugs" : "") ~ ", found " ~ hv.nUpper ~ " / " ~ hv.nLower ~ " (" ~ nAll ~ " bodies) - a cut or the cavity split something unexpectedly; inspect the bodies");
        if (hUp > useZ)
            warnings = append(warnings, "the block is " ~ fmt(hUp, 0) ~ " mm tall, over the " ~ fmt(useZ, 0) ~ " mm usable print height - reduce Base thickness or tip droop, or use a taller printer");
        if (tipT < 1 && !isFlat)
            warnings = append(warnings, "tip section only " ~ fmt(tipT, 2) ~ " mm thick where the cap starts - too thin to lay up; raise End ratio (or turn on Min tip) in the Foil " ~
                (definition.moldSource == MoldSource.WING ? "wing" : "stabiliser") ~ ", or Tip thick %. The cap beyond it runs out to " ~ fmt(capEndT, 2) ~ " mm and is tow and resin");
        if (sockOn && !plugOn)
            warnings = append(warnings, "socket nacelle molded in with its bore as a half core in each half - turn Socket plug on for a seamless bore");
        if (dropCheck != "ok (droop is monotonic in +Z)")
            warnings = append(warnings, dropCheck);
        if (towNote != "")
            warnings = append(warnings, towNote);
        if (coreShearWarn != "")
            warnings = append(warnings, coreShearWarn);
        if (nFloating > 0)
            warnings = append(warnings, nFloating ~ " key bodies did not attach to a tile and are floating as their own parts - please report this with the mold's inputs");
        if (grooveFailed)
            warnings = append(warnings, "pinch-off groove skipped: its offset outline could not be built (a narrow tail plan, usually) - the mold is complete without it; add a groove by hand or turn Pinch-off off; please report this with the mold's inputs");
        if (plugLost)
            warnings = append(warnings, "the pod plug was made but is no longer a separate body by the end - please report the MAST_PLUG console lines");
        for (var iw in inlayWarn)
            warnings = append(warnings, iw);
        for (var pw in partingWarn)
            warnings = append(warnings, pw);
        if (hubUnderNote != "")
            warnings = append(warnings, "hub cones:" ~ hubUnderNote);

        const msg = "Mold block " ~ fmt(L[0], 0) ~ " x " ~ fmt(L[1], 0) ~ " x " ~ fmt(L[2], 0) ~ " mm (chord x span x height)" ~
            " | tiles: " ~ (isMast ? "left " : "upper ") ~ nTilesU ~ (isMast ? ", right " : ", lower ") ~ nTilesL ~ " = " ~ (nTilesU + nTilesL) ~ " prints, up to " ~ fmt(tileY / millimeter, 0) ~ " x " ~ fmt(tileX / millimeter, 0) ~
            " mm on the bed (" ~ nY ~ " along the span" ~ cutNote ~ (nX > 1 ? " x " ~ nX ~ " across the chord" ~ chordCutNote : "") ~ (stagger ? ", staggered" : "") ~ "; usable " ~
            fmt(useYv / millimeter, 0) ~ " x " ~ fmt(useXv / millimeter, 0) ~ " x " ~ fmt(useZ, 0) ~ ")" ~
            (puzzle ? (preview ? "" : " | " ~ inlayNote) ~ (nKeys > 0 ? " | " ~ nKeys ~ " half keys " ~ fmt(definition.keyDia / millimeter, 0) ~ " mm" : "") :
                " | " ~ nPins ~ (printed ? " printed tile keys " : " tile dowels ") ~ fmt(pinDiaV / millimeter, 0) ~ " mm" ~ (nKeys > 0 ? ", " ~ nKeys ~ " half keys " ~ fmt(definition.keyDia / millimeter, 0) ~ " mm" : "")) ~
            (nSkippedKeys > 0 ? ", " ~ nSkippedKeys ~ " skipped where a seam crosses the plug channel" : "") ~
            flipNote ~ coreNote ~
            (nEject > 0 ? " | " ~ nEject ~ " ejector " ~ (definition.ejector == MoldEjector.PLUG ? "plug" : "hole") ~ (nEject == 1 ? "" : "s") ~ " " ~ fmt(definition.ejectorDia / millimeter, 0) ~ " mm through each half where the part is solid (" ~ ejectStr ~ ")" ~
                (definition.ejector == MoldEjector.PLUG ? ": each has its head on the cavity side - wax it, drop it in from the cavity before the layup (the laminate's pressure seats the head on its shoulder), punch it in from outside to push the part out" : ": fill flush with filleting wax before the layup, tap a dowel in to push the part out") : "") ~
            (nPry > 0 ? " | " ~ nPry ~ " pry sections, " ~ fmt(definition.pryLength / millimeter, 0) ~ " mm V pockets across the parting on " ~ pryFaces ~ " faces: open with wedges in them, worked alternately so the halves part square" : "") ~
            (nSlivers > 0 ? " | " ~ nSlivers ~ " sliver" ~ (nSlivers == 1 ? "" : "s") ~ " under 0.05 cm3 removed" ~
                (definition.moldSource == MoldSource.WING || definition.moldSource == MoldSource.STAB ? " (a knife-edge tip: turn on Min tip or raise End ratio in the Foil " ~ (definition.moldSource == MoldSource.WING ? "wing" : "stabiliser") ~ ")" : "") : "") ~
            (isMast ? " | mast laid flat 400 mm below the origin, parting on its mid-plane: left and right halves for the blade and the plate's edges, plus a lid for its board face" ~ trayNote ~ plNote ~ releaseNote ~
                (podPlug ? "; pod molded with the mast" ~ podPlugNote : "") : "") ~
            (isFus && !coreMold ? " | fuselage parted top and bottom along its sections' mid-height (flat under the nose at the hub's top): the mast pocket is a core on the upper half, the tongue a pocket in the lower; the hub's bolt holes, their countersinks and the stab's tapped holes are vertical and are filled in the cavity - drill and countersink after cure" : "") ~
            (plugOn ? " | socket plug = the bore as modelled (" ~ sockCores ~ " core" ~ (sockCores == 1 ? "" : "s") ~ ") on a " ~ (sockSq ? fmt(bW / millimeter, 1) ~ " x " ~ fmt(bH / millimeter, 1) : fmt(bW / millimeter, 1)) ~ " mm handle " ~ fmt(definition.plugExt / millimeter, 0) ~ " mm long, channel in both flanges" ~ jointClearNote ~
                (nSockCones > 0 ? "; " ~ nSockCones ~ " tapered shank cones below them, drill through after cure" : "; drill the bolt holes after cure") : "") ~
            (flatOn ? " | flat mount: " ~ size(flat.boltX) ~ " through holes mold as pins from both halves, the countersinks on the upper half's; drill through after cure and clean the seam at the parting" ~ (flat.padBody != undefined && flat.padBody == 1 ? "; the mount pad under the root molds in the half that forms the underside, its pins standing from the seat face" : "") : "") ~
            (isFus && !coreMold ? " | " ~ (definition.conesOn == true ? nFusCones ~ " tapered cones with their countersinks and " ~ nFusPins ~ " straight pins on the fuselage's holes, each from the half that forms the face the bolt enters, " ~ fmt(definition.coneWeb / millimeter, 1) ~ " mm web at the far face; drill to size after cure" ~ (fusConeNote != "" ? " |" ~ fusConeNote : "") : "the fuselage's holes are filled (Bolt cones off): drill and countersink after cure") : "") ~
            (hubOn ? " | hub molded as modelled (pocket, fillet" ~ (hub.noseOn != undefined && hub.noseOn == 1 ? ", nose fairing" : "") ~ ", holes)" ~
                (hubUnder ? (hub.boltX == undefined || size(hub.boltX) == 0 ? "" : (nHubUnderCones > 0 ? ": its " ~ nHubUnderCones ~ " through holes from the wing's underside are filled, and the lower half forms each " ~ (hubNuts ? "nut insert's bore and flange recess (at the wing's hand-fit size; ream if tight)" : "countersink") ~ " and a tapered cone " ~ fmt(definition.coneDia / millimeter, 1) ~ " mm to " ~ fmt(definition.coneWeb / millimeter, 1) ~ " mm under the pocket floor; drill to clearance after cure" :
                    ": its through holes from the wing's underside mold as pins from both halves, the countersinks on the lower half's (Bolt cones would form them from the lower half alone)")) :
                (nHubCones > 0 ? ": " ~ nHubCones ~ " tapered cones replace its straight hole pins on the pocket's boss; drill to size after cure" : ": its blind holes mold as straight pins from the pocket's boss (Bolt cones would taper them)")) : "") ~
            (nCones > 0 ? " | " ~ nCones ~ " bolt cones " ~ fmt(definition.coneDia / millimeter, 1) ~ " mm at " ~ fmt(definition.coneTaper / degree, 0) ~ " deg on the stab's pattern, " ~ fmt(definition.coneWeb / millimeter, 1) ~ " mm web at the far skin, standing on the " ~ (cskSideM == 1 ? "top" : "underside") ~ " face with the countersink molded around each; the part's own holes are not molded - drill to " ~ fmt(stabRoot.boltDia * 1000, 1) ~ " mm" ~ (stabRoot.headDia != undefined && stabRoot.headDia > 0 ? " and countersink " ~ fmt(stabRoot.headDia * 1000, 1) ~ " mm" : "") ~ " after cure" : "") ~
            (definition.conesOn == true && definition.moldSource == MoldSource.STAB && nCones == 0 ? " | no bolt cones: " ~
                (stabRoot == undefined ? "no Foil stabiliser above this feature" :
                 (stabRoot.boltX == undefined ? "the Foil stabiliser above is older than this Foil mold - paste the whole Feature Studio again" :
                  (size(stabRoot.boltX) == 0 ? "the stab has no Mount bolts" :
                   (stabRoot.padOn != 1 ? "the stab's Mount pad is off" : "every bolt was skipped (see below)")))) : "") ~
            (coneNote != "" ? " |" ~ coneNote : "") ~
            (nGroove > 0 ? " | pinch-off: land " ~ fmt(definition.landWidth / millimeter, 1) ~ " mm" ~ (landOn ? " lowered " ~ fmt(definition.landGap / millimeter, 2) ~ " mm in the lower half, so about " ~ fmt(definition.landGap / (0.22 * millimeter), 1) ~ " plies of 200 gsm carry out over it and the halves bear outside the groove" : "") ~ (landFailed ? " (Land gap could not be cut: the land is left at the parting)" : "") ~ ", groove " ~ fmt(definition.grooveWidth / millimeter, 1) ~ " x " ~ fmt(definition.grooveDepth / millimeter, 1) ~ " mm in the lower half, holds " ~ fmt(grooveVol, 0) ~ " cm3 against " ~ fmt(flashVol, 0) ~ " cm3 of flash at " ~ fmt(definition.overchargePct, 0) ~ " % overcharge" ~
                (nVents > 0 ? ", vented to the outside at " ~ nVents ~ (nVents == 1 ? " end" : " ends") : "") : "") ~
            closingNote ~
            " | " ~ layupMsg ~ stiffMsg;
        if (size(warnings) > 0)
        {
            var w = "";
            for (var s in warnings)
                w = w ~ (w == "" ? "" : "; ") ~ s;
            foilNotice(context, id, moldNoticeKey, (preview ? "PREVIEW (halves only, one tile each; set Detail = Print for the STLs) | " : "") ~ msg ~ " | WARNING: " ~ w, true);
        }
        else
            foilNotice(context, id, moldNoticeKey, (preview ? "PREVIEW (halves only, one tile each; set Detail = Print for the STLs) | " : "") ~ msg, false);

        // ---------------- cut templates: one flat plate, every ply outline cut through it ----------------
        // Built last, below the block, so no mold operation ever sees it. Export its top face as DXF.
        if (definition.templatesOn)
        {
            const mg = definition.tplMargin;
            const gap = definition.tplGap;
            const zP = lo[2] - 60 * millimeter;
            var shapes = [];            // each: array of 2D points (u along the chord, v along the developed span), closed
            var names = [];
            var cuts = [];              // how many pieces to cut from each outline: one tally hole per cut on the plate
            if (isMast)
            {
                // skins: one face developed (chord + thickness, at the plate and at the fuselage end) x
                // height, the plate end at the bottom of the strip, plus the plate's top face; UD: the
                // tapered strips of the cut list, plate end at the bottom
                const cBotM = (mastM.chord + mastM.thick) * meter;
                const cTopS = ((mastM.chordTop != undefined ? mastM.chordTop : mastM.chord) + (mastM.thickTop != undefined ? mastM.thickTop : mastM.thick)) * meter;
                const hM = mastM.height * meter;
                shapes = append(shapes, [vector(-mg, -mg), vector(cTopS + mg, -mg), vector(cBotM + mg, hM + mg), vector(-mg, hM + mg)]);
                names = append(names, "mast skin (one face, plate end at the bottom of the strip, cut " ~ definition.skinPlies * 2 ~ ")");
                cuts = append(cuts, definition.skinPlies * 2);
                const pl = plateAct != undefined ? plateAct.x1 - plateAct.x0 : mastM.plateLength * meter;
                const pw = plateAct != undefined ? plateAct.y1 - plateAct.y0 : mastM.plateWidth * meter;
                shapes = append(shapes, [vector(-mg, -mg), vector(pl + mg, -mg), vector(pl + mg, pw + mg), vector(-mg, pw + mg)]);
                names = append(names, "plate (cut " ~ (definition.skinPlies * 2 + plateFill) ~ ": " ~ definition.skinPlies * 2 ~ " skins + " ~ plateFill ~ " fill)");
                cuts = append(cuts, definition.skinPlies * 2 + plateFill);
                // UD caps: the plate end at v = 0 with the run-out below it and a 2 mm notch in each
                // edge at the fold line; tabs the same with Tab length above the fold
                const nSM = size(tplCAt) - 1;
                const rO = runOut * millimeter;
                const nk = 2 * millimeter;
                const wP = capW * tplCAt[0] * millimeter;                     // at the plate
                for (var k = 0; k < size(tplEnds); k += 1)
                {
                    const lenK = tplEnds[k] / nSM * hM;
                    const wE = capW * tplCAt[tplEnds[k]] * millimeter;        // at the ply's end
                    var strip = [vector(-mg, -rO - mg), vector(wP + mg, -rO - mg)];
                    if (rO > 0)
                        strip = concatenateArrays([strip, [vector(wP + mg, -nk), vector(wP + mg - nk, 0 * meter), vector(wP + mg, nk)]]);
                    strip = concatenateArrays([strip, [vector(wE + mg, lenK + mg), vector(-mg, lenK + mg)]]);
                    if (rO > 0)
                        strip = concatenateArrays([strip, [vector(-mg, nk), vector(-mg + nk, 0 * meter), vector(-mg, -nk)]]);
                    shapes = append(shapes, strip);
                    names = append(names, "UD ply " ~ (k + 1) ~ " (" ~ fmt(lenK / millimeter, 0) ~ " mm from the plate" ~ (rO > 0 ? " + " ~ fmt(runOut, 0) ~ " mm run-out, fold at the notches" : "") ~ ", cut 2)");
                    cuts = append(cuts, 2);
                }
                if (tabN > 0)
                {
                    const tL = tabLen * millimeter;
                    shapes = append(shapes, [vector(-mg, -rO - mg), vector(wP + mg, -rO - mg), vector(wP + mg, -nk), vector(wP + mg - nk, 0 * meter), vector(wP + mg, nk),
                            vector(wP + mg, tL + mg), vector(-mg, tL + mg), vector(-mg, nk), vector(-mg + nk, 0 * meter), vector(-mg, -nk)]);
                    names = append(names, "UD tab (" ~ fmt(runOut, 0) ~ " mm on the plate + " ~ fmt(tabLen, 0) ~ " mm down the mast, fold at the notches, cut " ~ 2 * tabN ~ ")");
                    cuts = append(cuts, 2 * tabN);
                }
            }
            else if (isFus)
            {
                // skins: one strip per half (upper and lower), its width at each station half the
                // section's perimeter, laid along the fuselage; the same outline cuts both halves
                if (fusM.stations != undefined)
                {
                    var stripF = [];
                    const st = fusM.stations;
                    for (var k = 0; k < size(st); k += 1)
                    {
                        const halfP = 2 * (st[k][1] + st[k][2]) * meter - (4 - PI) * st[k][3] * meter;
                        stripF = append(stripF, vector(st[k][0] * meter - (k == 0 ? mg : 0 * meter), halfP / 2 + mg));
                    }
                    for (var k = size(st) - 1; k >= 0; k -= 1)
                    {
                        const halfP = 2 * (st[k][1] + st[k][2]) * meter - (4 - PI) * st[k][3] * meter;
                        stripF = append(stripF, vector(st[k][0] * meter + (k == size(st) - 1 ? mg : 0 * meter), -halfP / 2 - mg));
                    }
                    shapes = append(shapes, stripF);
                    names = append(names, "fuselage skin - one strip per half, upper and lower, its width half the section's perimeter (cut " ~ definition.skinPlies * 2 ~ ": " ~ definition.skinPlies ~ " per half)");
                    cuts = append(cuts, definition.skinPlies * 2);
                }
                if (fusCore != undefined)
                {
                    for (var k = 0; k < size(fusCore.plyLen); k += 1)
                    {
                        const L = fusCore.plyLen[k] * meter + 2 * mg;
                        const w0 = fusCore.wcs[0] * meter / 2 + mg;
                        const w1 = fusCore.plyW1[k] * meter / 2 + mg;
                        shapes = append(shapes, [vector(-w0, 0 * meter), vector(w0, 0 * meter), vector(w1, L), vector(-w1, L)]);
                        names = append(names, "tail UD ply " ~ (k + 1) ~ " (" ~ fmt(fusCore.plyLen[k] * 1000, 0) ~ " mm from the mast end, cut 2: top and bottom)");
                        cuts = append(cuts, 2);
                    }
                }
            }
            else
            {
                // developed span: arc length along the droop / dihedral curve, per station of a fine grid
                const nT = 60;
                const hh = m.span / 2 * meter;
                var sDev = makeArray(nT + 1);
                var xLE = makeArray(nT + 1);
                var cT = makeArray(nT + 1);
                var zPrev = 0 * meter;
                sDev[0] = 0 * meter;
                for (var i = 0; i <= nT; i += 1)
                {
                    const eta = i / nT;
                    const chord = m.c0 * meter * chordFactor(m, eta) * (m.capOn == 1 && m.planRound != 1 && eta > capStartEta ? (1 - (1 - m.capEnd) * (eta - capStartEta) / max(1 - capStartEta, 1e-6)) : 1);
                    const fD = dropShape(m, eta);
                    const zOff = -m.tipDrop * meter * fD + hh * tan(m.rootDihedral * radian) * (eta - fD);
                    if (i > 0)
                        sDev[i] = sDev[i - 1] + sqrt((hh / nT) * (hh / nT) + (zOff - zPrev) * (zOff - zPrev));
                    zPrev = zOff;
                    const tailAdd = m.c0 * meter * tailFactor(m, eta);
                    const chordBase = (chord - tailAdd) / capPlanFactor(m, eta);
                    const xOff = m.sweepTip * meter * eta ^ m.sweepExp + (m.pivotFrac - m.align) * (chordBase - m.c0 * meter) + m.pivotFrac * tailAdd + (0.5 - m.pivotFrac) * (chordBase - (chord - tailAdd));
                    xLE[i] = xOff - m.pivotFrac * chord;
                    cT[i] = chord;
                }
                const both = m.mirror == 1;
                // woven skin: the whole developed planform (both halves if mirrored), LE and TE curves.
                // Every second station: the sketch stays a few hundred lines rather than thousands
                var skin = [];
                const idxS = tplIndices(both ? -nT : 0, nT, 2);
                for (var i in idxS)
                {
                    const a = abs(i);
                    skin = append(skin, vector(xLE[a] - mg, (i < 0 ? -1 : 1) * (sDev[a] + (a == nT ? mg : 0 * meter))));
                }
                for (var q = size(idxS) - 1; q >= 0; q -= 1)
                {
                    const i = idxS[q];
                    const a = abs(i);
                    skin = append(skin, vector(xLE[a] + cT[a] + mg, (i < 0 ? -1 : 1) * (sDev[a] + (a == nT ? mg : 0 * meter))));
                }
                shapes = append(shapes, skin);
                names = append(names, "woven skin - one outline, cut " ~ definition.skinPlies * 2 ~ " (" ~ definition.skinPlies ~ " per face" ~
                    (definition.skinPlies >= 2 ? "; turn the weave 45 deg on the outer ply of each face for torsion" : "") ~ ")");
                cuts = append(cuts, definition.skinPlies * 2);
                // UD plies: a strip about the thickest-point line (30 % chord), half-width Cap width % / 2
                // of the local chord, out to the ply's end station, grown by the margin
                const nSL = size(tplCAt) - 1;
                for (var k = 0; k < size(tplEnds); k += 1)
                {
                    const etaEnd = capStartEta * tplEnds[k] / nSL;
                    const iEndT = max(1, round(etaEnd * nT));
                    var strip = [];
                    const idxU = tplIndices(both ? -iEndT : 0, iEndT, max(1, round(iEndT / 10)));
                    for (var i in idxU)
                    {
                        const a = abs(i);
                        const xc = xLE[a] + 0.3 * cT[a];
                        strip = append(strip, vector(xc - capW * cT[a] / 2 - mg, (i < 0 ? -1 : 1) * (sDev[a] + (a == iEndT ? mg : 0 * meter))));
                    }
                    for (var q = size(idxU) - 1; q >= 0; q -= 1)
                    {
                        const i = idxU[q];
                        const a = abs(i);
                        const xc = xLE[a] + 0.3 * cT[a];
                        strip = append(strip, vector(xc + capW * cT[a] / 2 + mg, (i < 0 ? -1 : 1) * (sDev[a] + (a == iEndT ? mg : 0 * meter))));
                    }
                    shapes = append(shapes, strip);
                    names = append(names, "UD ply " ~ (k + 1) ~ " (" ~ fmt(2 * (sDev[iEndT] + mg) / millimeter * (both ? 1 : 0.5), 0) ~ " mm, cut 2)");
                    cuts = append(cuts, 2);
                }
            }
            // layout: shapes side by side along X, each in its own column, centred on a common V axis
            var uOff = 0 * meter;
            var vMax = -10 * meter;
            var vMin = 10 * meter;       // the plate is sized from the shapes' real extent (build 123: the
            var cols = [];               // mast's one-sided shapes left half the plate empty)
            for (var sh in shapes)
            {
                var uMin = 1 * meter;
                var uMax = -1 * meter;
                for (var q in sh)
                {
                    uMin = min(uMin, q[0]);
                    uMax = max(uMax, q[0]);
                    vMax = max(vMax, q[1]);
                    vMin = min(vMin, q[1]);
                }
                cols = append(cols, uOff - uMin);
                uOff += (uMax - uMin) + gap;
            }
            const plateW = uOff - gap + 2 * gap;
            var maxCuts = 1;
            for (var cnt in cuts)
                maxCuts = max(maxCuts, cnt);
            const tallyRows = ceil(maxCuts / 10);                       // tally holes wrap 10 to a row (a 40-ply plate)
            const tallyH = 6 * millimeter * tallyRows + 6 * millimeter;          // room for the tally rows under each shape
            const plateH = (vMax - vMin) + 2 * gap + tallyH;
            const x0P = lo[0] - plateW - 50 * millimeter;
            const y0P = lo[1];
            moldBox(context, id + "tplPlate", vector(x0P, y0P, zP), vector(x0P + plateW, y0P + plateH, zP + 1 * millimeter));
            const sid = id + "tplSketch";
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(x0P + gap, y0P + gap + tallyH - vMin, zP + 1 * millimeter), Z_DIRECTION, X_DIRECTION) });
            for (var n = 0; n < size(shapes); n += 1)
            {
                const sh = shapes[n];
                var uMinS = 1 * meter;
                var vMinS = 1 * meter;
                for (var q = 0; q < size(sh); q += 1)
                {
                    const a = sh[q];
                    const b = sh[(q + 1) % size(sh)];
                    uMinS = min(uMinS, a[0]);
                    vMinS = min(vMinS, a[1]);
                    if (norm(b - a) > 0.01 * millimeter)
                        skLineSegment(sk, "s" ~ n ~ "_" ~ q, { "start" : vector(a[0] + cols[n], a[1]), "end" : vector(b[0] + cols[n], b[1]) });
                }
                // tally: one 3 mm hole per piece to cut, rows of 10 under the shape's lower-left corner
                for (var t = 0; t < cuts[n]; t += 1)
                    skCircle(sk, "t" ~ n ~ "_" ~ t, { "center" : vector(uMinS + cols[n] + 2 * millimeter + (t % 10) * 6 * millimeter, vMinS - 6 * millimeter - floor(t / 10) * 6 * millimeter), "radius" : 1.5 * millimeter });
            }
            skSolve(sk);
            opExtrude(context, id + "tplCut", {
                        "entities" : qSketchRegion(sid),
                        "direction" : -Z_DIRECTION,
                        "endBound" : BoundingType.BLIND,
                        "endDepth" : 3 * millimeter
                    });
            opBoolean(context, id + "tplCutDo", {
                        "tools" : qCreatedBy(id + "tplCut", EntityType.BODY),
                        "targets" : qCreatedBy(id + "tplPlate", EntityType.BODY),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            opDeleteBodies(context, id + "tplSketchDel", { "entities" : qCreatedBy(sid, EntityType.BODY) });
            setProperty(context, { "entities" : qCreatedBy(id + "tplPlate", EntityType.BODY), "propertyType" : PropertyType.NAME,
                        "value" : (definition.moldSource == MoldSource.WING ? "Wing" : (isMast ? "Mast" : (isFus ? "Fuselage" : "Stab"))) ~ " cut templates" });
            var key = "TEMPLATES (left to right on the plate, +" ~ fmt(mg / millimeter, 0) ~ " mm margin; the 3 mm holes under each shape (rows of 10) are its cut count; export the plate's top face as DXF):";
            for (var n = 0; n < size(names); n += 1)
                key = key ~ "\n" ~ (n + 1) ~ ": " ~ names[n];
            foilPrint(context, moldLogKey, key);
        }

        // ---------------- parts group: one open composite of everything this feature made ----------------
        if (definition.partsGroup != PartsGroup.OFF)
        {
            try silent
            {
                opCreateCompositePart(context, id + "group", {
                            "bodies" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                            "closed" : definition.partsGroup == PartsGroup.CLOSED
                        });
                setProperty(context, { "entities" : qBodyType(qCreatedBy(id + "group", EntityType.BODY), BodyType.COMPOSITE), "propertyType" : PropertyType.NAME,
                            "value" : (definition.moldSource == MoldSource.WING ? "Wing" : (isMast ? "Mast" : (isFus ? "Fuselage" : "Stab"))) ~ " mold" });
            }
        }
    });

/** Integer indices from a to b inclusive at the given stride, always ending on b (and passing 0 when the range straddles it). */
function tplIndices(a is number, b is number, stride is number) returns array
{
    var out = [];
    var i = a;
    while (i < b)
    {
        out = append(out, i);
        i += stride;
    }
    out = append(out, b);
    return out;
}

/** Solid box between two opposite corners, as a loft of two rectangles (the pattern this file already relies on). */
/**
 * The mast's plate as modelled, measured off the part: a copy (offset 2 m in Y so nothing coincides)
 * is split 0.05 mm above the plate's underside plane and the bounding boxes of the pieces on the
 * plate side are merged. Returns { x0, x1, y0, y1 (world), zTop (the underside plane), zBoard (the
 * board face) } or undefined when the split or the query fails; every temporary body is deleted
 * either way. Direct edits to the plate above the mold (fillets, chamfers, an outline, thickness)
 * are then what the tray follows (build 173).
 */
function moldPlateMeasure(context is Context, mid is Id, part is Query, mastM is map)
{
    const off = 2 * meter;
    const zTop = (mastM.baseZ + mastM.height) * meter;
    var result;
    try silent
    {
        opPattern(context, mid + "copy", {
                    "entities" : part,
                    "transforms" : [transform(vector(0 * meter, off, 0 * meter))],
                    "instanceNames" : ["p"]
                });
        const copy = qCreatedBy(mid + "copy", EntityType.BODY);
        const cb = evBox3d(context, { "topology" : copy, "tight" : true });
        const tool = moldCut(context, mid + "cut", copy, vector(0 * meter, off, zTop + 0.05 * millimeter), Z_DIRECTION, cb.minCorner, cb.maxCorner);
        const pieces = qUnion([copy, qCreatedBy(mid + "cut" + "split", EntityType.BODY), qCreatedBy(mid + "cut" + "split2", EntityType.BODY)]);
        var pb;
        for (var b in evaluateQuery(context, pieces))
        {
            const bb = evBox3d(context, { "topology" : b, "tight" : true });
            if (bb.minCorner[2] > zTop - 0.2 * millimeter)
            {
                if (pb == undefined)
                    pb = bb;
                else
                    pb = { "minCorner" : vector(min(pb.minCorner[0], bb.minCorner[0]), min(pb.minCorner[1], bb.minCorner[1]), min(pb.minCorner[2], bb.minCorner[2])),
                           "maxCorner" : vector(max(pb.maxCorner[0], bb.maxCorner[0]), max(pb.maxCorner[1], bb.maxCorner[1]), max(pb.maxCorner[2], bb.maxCorner[2])) };
            }
        }
        opDeleteBodies(context, mid + "del", { "entities" : qUnion([pieces, tool]) });
        if (pb != undefined && pb.maxCorner[2] > zTop + 0.5 * millimeter)
            result = { "x0" : pb.minCorner[0], "x1" : pb.maxCorner[0], "y0" : pb.minCorner[1] - off, "y1" : pb.maxCorner[1] - off,
                       "zTop" : zTop, "zBoard" : pb.maxCorner[2] };
    }
    // anything left behind by a failure part-way
    try silent
    {
        opDeleteBodies(context, mid + "del2", { "entities" : qUnion([qCreatedBy(mid + "copy", EntityType.BODY), qCreatedBy(mid + "cut" + "plane", EntityType.BODY),
                    qCreatedBy(mid + "cut" + "sheet", EntityType.BODY), qCreatedBy(mid + "cut" + "split", EntityType.BODY), qCreatedBy(mid + "cut" + "split2", EntityType.BODY)]) });
    }
    return result;
}

/**
 * The root section (eta 0) of a wing or stab as world (x, z) points, placed exactly as buildFoil places
 * station 0: root tail, plan alignment, bumps and incidence included, no sweep, droop or winglet at
 * the root. For the stab's bolt holes, which may sit in the root tail (build 179).
 */
function moldRootSection(m is map, mini is map, base is Vector) returns array
{
    const h = m.span / 2 * meter;
    const chord0 = m.c0 * meter * chordFactor(m, 0);
    const tailAdd = m.c0 * meter * tailFactor(m, 0);
    const thick0 = m.rootT * (chord0 - tailAdd) / chord0;
    const twist = m.incidence * radian;
    const chordBase = (chord0 - tailAdd) / capPlanFactor(m, 0);
    const alignShift = (m.pivotFrac - m.align) * (chordBase - m.c0 * meter) + m.pivotFrac * tailAdd + (0.5 - m.pivotFrac) * (chordBase - (chord0 - tailAdd));
    const bump = bumpOffset(m, 0, h);
    const chord = chord0 + bump;
    const thick = thick0 * chord0 / chord;
    const xOff = alignShift - (1 - m.pivotFrac) * bump;
    const sec = buildSectionAt(mini, thick, min(m.teThick * meter, 0.03 * chord) / chord, 40, sectionWeightAt(mini, 0));
    const placed = placeSection(sec, chord, m.pivotFrac, cos(twist), sin(twist));
    var out = [];
    for (var q in placed)
        out = append(out, vector(base[0] + xOff + q[0], base[2] + q[1]));
    return out;
}

function moldBox(context is Context, boxId is Id, lo is Vector, hi is Vector)
{
    var sketchBodies = [];
    var profiles = [];
    for (var k = 0; k < 2; k += 1)
    {
        const z = k == 0 ? lo[2] : hi[2];
        const sid = boxId + ("r" ~ k);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, 0 * meter, z), Z_DIRECTION, X_DIRECTION) });
        const c = [vector(lo[0], lo[1]), vector(hi[0], lo[1]), vector(hi[0], hi[1]), vector(lo[0], hi[1])];
        for (var j = 0; j < 4; j += 1)
            skLineSegment(sk, "s" ~ j, { "start" : c[j], "end" : c[(j + 1) % 4] });
        skSolve(sk);
        profiles = append(profiles, qSketchRegion(sid));
        sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
    }
    opLoft(context, boxId, { "profileSubqueries" : profiles });
    opDeleteBodies(context, boxId + "del", { "entities" : qUnion(sketchBodies) });
}

/** Tiles of one half ordered by span position (-Y first), then chord position (-X first). */
function moldSortTiles(context is Context, tiles is Query) returns array
{
    var rows = [];
    for (var b in evaluateQuery(context, tiles))
    {
        const bx = evBox3d(context, { "topology" : b, "tight" : false });
        rows = append(rows, { "q" : b, "y" : (bx.minCorner[1] + bx.maxCorner[1]) / 2 / meter, "x" : (bx.minCorner[0] + bx.maxCorner[0]) / 2 / meter });
    }
    rows = sort(rows, function(a, b) { return abs(a.y - b.y) > 1e-4 ? a.y - b.y : a.x - b.x; });
    var out = [];
    for (var r in rows)
        out = append(out, r.q);
    return out;
}

/**
 * Closed loop offset outward by d: each edge shifted along its outward normal, convex corners
 * bevelled (both offset endpoints kept), reflex corners mitred (the two offset edges intersected)
 * so the result does not cross itself. pts are 2D (x, y) with units.
 */
function moldOffsetLoop(pts is array, d is ValueWithUnits) returns array
{
    const n = size(pts);
    var area2 = 0 * meter * meter;
    for (var i = 0; i < n; i += 1)
        area2 += pts[i][0] * pts[(i + 1) % n][1] - pts[(i + 1) % n][0] * pts[i][1];
    const sgn = area2 > 0 * meter * meter ? 1 : -1;
    var starts = [];
    var ends = [];
    var dirs = [];
    for (var i = 0; i < n; i += 1)
    {
        const a = pts[i];
        const b = pts[(i + 1) % n];
        const t = b - a;
        const len = norm(t);
        if (len < 1e-6 * meter)
            continue;
        const u = t / len;
        const nrm = vector(u[1], -u[0]) * sgn;
        starts = append(starts, a + nrm * d);
        ends = append(ends, b + nrm * d);
        dirs = append(dirs, u);
    }
    const ne = size(starts);
    var out = [];
    for (var i = 0; i < ne; i += 1)
    {
        const j = (i + 1) % ne;
        const cross = (dirs[i][0] * dirs[j][1] - dirs[i][1] * dirs[j][0]) * sgn;
        if (cross >= -1e-9)
        {
            out = append(out, ends[i]);            // convex or straight: bevel
        }
        else
        {
            // reflex: intersect edge i (ends[i] - dirs[i] s) with edge j (starts[j] + dirs[j] t).
            // Build 134 tried a miter limit here (bevel when the intersection is far) and it removed
            // the groove from every mold - this is the build 51-133 code, which works on the wing,
            // the pad-top stab and the mast; a loop that still cannot be lofted is skipped upstream
            const w = starts[j] - ends[i];
            const den = dirs[i][0] * dirs[j][1] - dirs[i][1] * dirs[j][0];
            const sPar = (w[0] * dirs[j][1] - w[1] * dirs[j][0]) / den;
            out = append(out, ends[i] + dirs[i] * sPar);
            starts[j] = out[size(out) - 1];
        }
    }
    // drop the bevel duplicates: each edge contributes its start when it differs from the previous point
    var loop = [];
    for (var i = 0; i < ne; i += 1)
    {
        const p = starts[i];
        if (size(loop) == 0 || norm(p - loop[size(loop) - 1]) > 1e-6 * meter)
            loop = append(loop, p);
        const q = out[i];
        if (norm(q - loop[size(loop) - 1]) > 1e-6 * meter)
            loop = append(loop, q);
    }
    return loop;
}

/** Prism of a closed 2D (x, y) loop between z0 and z1, as a loft of two polygon sketches. */
function moldPrism(context is Context, prismId is Id, loop is array, z0 is ValueWithUnits, z1 is ValueWithUnits)
{
    var sketchBodies = [];
    var profiles = [];
    const zs = [z0, z1];
    for (var k = 0; k < 2; k += 1)
    {
        const sid = prismId + ("p" ~ k);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, 0 * meter, zs[k]), Z_DIRECTION, X_DIRECTION) });
        for (var i = 0; i < size(loop); i += 1)
            skLineSegment(sk, "e" ~ i, { "start" : loop[i], "end" : loop[(i + 1) % size(loop)] });
        skSolve(sk);
        profiles = append(profiles, qSketchRegion(sid));
        sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
    }
    opLoft(context, prismId, { "profileSubqueries" : profiles });
    opDeleteBodies(context, prismId + "del", { "entities" : qUnion(sketchBodies) });
}

/**
 * Every solid of this feature sorted by which block face it touches: upper touches the top only, lower the
 * bottom only. Called immediately before every operation that needs a half or a tile - the transient
 * queries evaluateQuery returns are only valid until the next operation changes the context, so no body
 * reference is ever held across one.
 */
/** The bodies among solids that touch neither the block's top nor its bottom face: cores, plugs, loose keys. */
/**
 * True when the bodies, slid along dir by any of the distances, run into the part: a mold piece that cannot come off
 * that way (build 241). Clashes that only touch (abut) do not count.
 */
function moldSlideLocks(context is Context, baseId is Id, bodies is Query, part is Query, dir is Vector, dists is array) returns boolean
{
    return moldSlideLockAt(context, baseId, bodies, part, dir, dists, undefined) != "";
}

/**
 * Where the bodies, slid along dir by the distances in turn, first run into the part: "" when they never do, else the
 * overlap's box in the mast's own frame (x, y = z' - zPart, z = -y') and the distance, from an intersection of the slid
 * copy with a copy of the part (build 241: to find which feature locks a mold piece). zPart undefined: no box.
 */
function moldSlideLockAt(context is Context, baseId is Id, bodies is Query, part is Query, dir is Vector, dists is array, zPart) returns string
{
    var res = "";
    for (var k = 0; k < size(dists); k += 1)
    {
        if (res != "")
            break;
        const sid = baseId + ("d" ~ k);
        try silent
        {
            opPattern(context, sid, { "entities" : bodies, "transforms" : [transform(dir * dists[k])], "instanceNames" : ["m"] });
            const cl = evCollision(context, { "tools" : qCreatedBy(sid, EntityType.BODY), "targets" : part });
            var hit = false;
            for (var c in cl)
            {
                if (c["type"] == ClashType.INTERFERE || c["type"] == ClashType.TARGET_IN_TOOL || c["type"] == ClashType.TOOL_IN_TARGET)
                    hit = true;
            }
            if (hit)
            {
                res = "at " ~ fmt(dists[k] / millimeter, 1) ~ " mm";
                if (zPart != undefined)
                {
                    try silent
                    {
                        opPattern(context, sid + "p", { "entities" : part, "transforms" : [identityTransform()], "instanceNames" : ["q"] });
                        opBoolean(context, sid + "x", { "tools" : qUnion([qCreatedBy(sid, EntityType.BODY), qCreatedBy(sid + "p", EntityType.BODY)]), "operationType" : BooleanOperationType.INTERSECTION });
                        const ov = qUnion([qCreatedBy(sid, EntityType.BODY), qCreatedBy(sid + "p", EntityType.BODY), qCreatedBy(sid + "x", EntityType.BODY)]);
                        const bx = evBox3d(context, { "topology" : ov, "tight" : true });
                        res = res ~ ", overlap at X " ~ fmt(bx.minCorner[0] / millimeter, 0) ~ "-" ~ fmt(bx.maxCorner[0] / millimeter, 0) ~ ", Y " ~ fmt((bx.minCorner[2] - zPart) / millimeter, 0) ~ "-" ~ fmt((bx.maxCorner[2] - zPart) / millimeter, 0) ~
                            ", Z " ~ fmt(-bx.maxCorner[1] / millimeter, 0) ~ "-" ~ fmt(-bx.minCorner[1] / millimeter, 0) ~ " mm (the mast's own frame, after the slide)";
                    }
                }
            }
        }
        try silent
        {
            opDeleteBodies(context, sid + "del", { "entities" : qUnion([qCreatedBy(sid, EntityType.BODY), qCreatedBy(sid + "p", EntityType.BODY), qCreatedBy(sid + "x", EntityType.BODY)]) });
        }
    }
    return res;
}

/** Deletes the floating bodies under 1 mm3 (specks the cavity cut loose); returns how many. */
function moldDropSpecks(context is Context, id is Id, solids is Query, lo is Vector, hi is Vector) returns number
{
    var specks = [];
    for (var b in evaluateQuery(context, moldFloating(context, solids, lo, hi)))
    {
        var v = 1 * meter ^ 3;
        try silent
        {
            v = evVolume(context, { "entities" : b });
        }
        if (v < 1 * millimeter ^ 3)
            specks = append(specks, b);
    }
    if (size(specks) > 0)
        opDeleteBodies(context, id, { "entities" : qUnion(specks) });
    return size(specks);
}

function moldFloating(context is Context, solids is Query, lo is Vector, hi is Vector) returns Query
{
    // tight boxes: a loose box on a lofted core can overshoot the block face and hide the body
    var fl = [];
    for (var b in evaluateQuery(context, solids))
    {
        const bx = evBox3d(context, { "topology" : b, "tight" : true });
        if (bx.maxCorner[2] <= hi[2] - 0.5 * millimeter && bx.minCorner[2] >= lo[2] + 0.5 * millimeter)
            fl = append(fl, b);
    }
    return qUnion(fl);
}

function moldHalves(context is Context, solids is Query, lo is Vector, hi is Vector) returns map
{
    var up = [];
    var dn = [];
    for (var b in evaluateQuery(context, solids))
    {
        if (getAttribute(context, { "entity" : b, "name" : "foilEjectPlug" }) == true)
            continue;                                                         // a printed ejector plug is not a tile (build 243)
        const bx = evBox3d(context, { "topology" : b, "tight" : false });
        const top = bx.maxCorner[2] > hi[2] - 0.5 * millimeter;
        const bottom = bx.minCorner[2] < lo[2] + 0.5 * millimeter;
        if (top && !bottom)
            up = append(up, b);
        else if (bottom && !top)
            dn = append(dn, b);
        // touching both (an uncut block) or neither (a tool) is not a half
    }
    return { "upper" : qUnion(up), "lower" : qUnion(dn), "nUpper" : size(up), "nLower" : size(dn) };
}

/** Cylinder between two centre points (axis along X, Y or Z). Returns its body query. */
/**
 * Height of the body's surface met by a ray from (x, y, z0) straight up (up true) or down. hit is
 * false when nothing is met, or when the cast itself failed (the caller uses its nominal number).
 */
function moldRayZ(context is Context, body is Query, x is ValueWithUnits, y is ValueWithUnits, z0 is ValueWithUnits, up is boolean) returns map
{
    var res = { "hit" : false, "z" : 0 * meter };
    try silent
    {
        const hits = evRaycast(context, { "entities" : body, "ray" : line(vector(x, y, z0), vector(0, 0, up ? 1 : -1)), "closest" : true });
        if (size(hits) > 0)
        {
            const z = hits[0].intersection[2];
            res = { "hit" : true, "z" : z };
        }
    }
    return res;
}

/**
 * The fuselage's tail core (build 219), all numbers SI: stations from Core from mast behind the
 * mast's trailing edge (the fuselage's root without a mast) to Core end gap ahead of the stab's
 * seat, each the published section less one face's skins, less UD strips top and bottom whose ply
 * count carries the stab's lift Fs (N, at the stab bolts' mean X xSt) at Tail UD MPa across the
 * section's flat width. Returns ok false with a reason when there is no room.
 */
function fusCorePlan(fusM is map, mastM, definition is map, tFace is number, tUd is number, Fs is number, xSt is number) returns map
{
    const st = fusM.stations;
    var prof = [];
    for (var p in fusM.partZ)
        prof = append(prof, vector(p[0] * meter, p[1] * meter));
    const xM = mastM != undefined && mastM.leX != undefined ? mastM.leX + mastM.chord : fusM.rootX;
    const x0 = xM + definition.fusCoreFrom / meter;
    var x1 = fusM.seatX0 - definition.fusCoreGap / meter;
    if (x1 - x0 < 0.03)
        return { "ok" : false, "why" : "no room for a tail core between " ~ fmt(x0 * 1000, 0) ~ " and " ~ fmt(x1 * 1000, 0) ~ " mm (shorten Core from mast or Core end gap); laid up solid" };
    const nS = 12;
    const sig = definition.fusCapStress * 1e6;
    var xs = [];
    var zcs = [];
    var acs = [];
    var bcs = [];
    var rcs = [];
    var ns = [];
    var wcs = [];
    var tcs = [];
    for (var k = 0; k <= nS; k += 1)
    {
        const x = x0 + (x1 - x0) * k / nS;
        const sc = fusSectionAt(st, x);
        const a = sc[0];
        const b = sc[1];
        const r = sc[2];
        const wc = max(2 * a - 2 * r, 0.002);
        const h = 2 * b - 2 * tFace;
        const M = Fs * max(xSt - x, 0);
        const A = h > 0.001 ? M / (h * sig) : 0;
        const n = max(1, ceil(A / (wc * tUd)));
        const tc = n * tUd;
        const ac = a - tFace;
        const bc = b - tFace - tc;
        if (bc < 0.001 || ac < 0.001)
            break;
        xs = append(xs, x);
        zcs = append(zcs, fusPartZ(prof, x * meter) / meter);
        acs = append(acs, ac);
        bcs = append(bcs, bc);
        rcs = append(rcs, min(max(r - tFace, 0.0003), 0.45 * min(ac, bc)));
        ns = append(ns, n);
        wcs = append(wcs, wc);
        tcs = append(tcs, tc);
    }
    if (size(xs) < 3)
        return { "ok" : false, "why" : "the section is too thin for a core under the skins and UD strips; laid up solid" };
    var coreVol = 0;
    var capVol = 0;
    var nMax = 0;
    var nMin = 1000;
    var hMax = 0;
    for (var k = 0; k < size(xs); k += 1)
    {
        nMax = max(nMax, ns[k]);
        nMin = min(nMin, ns[k]);
        hMax = max(hMax, 2 * bcs[k]);
        if (k > 0)
        {
            const dx = xs[k] - xs[k - 1];
            const a0 = 4 * acs[k - 1] * bcs[k - 1] - (4 - PI) * rcs[k - 1] ^ 2;
            const a1 = 4 * acs[k] * bcs[k] - (4 - PI) * rcs[k] ^ 2;
            coreVol += 0.5 * (a0 + a1) * dx * 1e6;
            capVol += (wcs[k - 1] * tcs[k - 1] + wcs[k] * tcs[k]) * dx * 1e6;
        }
    }
    var plyLen = [];
    var plyW1 = [];
    for (var j = 1; j <= nMax; j += 1)
    {
        var last = 0;
        for (var k = 0; k < size(xs); k += 1)
            if (ns[k] >= j)
                last = k;
        plyLen = append(plyLen, max(xs[last] - xs[0], 0.02));
        plyW1 = append(plyW1, wcs[last]);
    }
    return { "ok" : true, "x0" : xs[0], "x1" : xs[size(xs) - 1], "xs" : xs, "zcs" : zcs, "acs" : acs, "bcs" : bcs, "rcs" : rcs, "ns" : ns, "wcs" : wcs, "tcs" : tcs,
             "coreVol" : coreVol, "capVol" : capVol, "nMax" : nMax, "nMin" : nMin, "hMax" : hMax, "plyLen" : plyLen, "plyW1" : plyW1 };
}

/** The tail core's section at x (SI number) interpolated from its plan: {ac, bc, rc, zc, tc, wc}; undefined outside the core or with no plan. */
function fusCoreAtNum(plan, x is number)
{
    if (plan == undefined || x < plan.x0 || x > plan.x1)
        return undefined;
    const xs = plan.xs;
    for (var k = 0; k < size(xs) - 1; k += 1)
    {
        if (x >= xs[k] && x <= xs[k + 1])
        {
            const u = xs[k + 1] - xs[k] > 1e-9 ? (x - xs[k]) / (xs[k + 1] - xs[k]) : 0;
            return { "ac" : plan.acs[k] + u * (plan.acs[k + 1] - plan.acs[k]), "bc" : plan.bcs[k] + u * (plan.bcs[k + 1] - plan.bcs[k]),
                     "rc" : plan.rcs[k] + u * (plan.rcs[k + 1] - plan.rcs[k]), "zc" : plan.zcs[k] + u * (plan.zcs[k + 1] - plan.zcs[k]),
                     "tc" : plan.tcs[k] + u * (plan.tcs[k + 1] - plan.tcs[k]), "wc" : plan.wcs[k] + u * (plan.wcs[k + 1] - plan.wcs[k]) };
        }
    }
    return undefined;
}

/**
 * A loft of the tail core's rounded-rectangle sections from xa to xb (SI numbers, within the plan),
 * with the start and end moved by dxa and dxb (a vent: the end section carried straight out).
 * The body is returned as a query; the sketches are deleted here.
 */
function fusCoreLoft(context is Context, idB is Id, plan is map, xa is number, xb is number, dxa is ValueWithUnits, dxb is ValueWithUnits) returns Query
{
    var secs = [[xa, dxa]];
    for (var x in plan.xs)
        if (x > xa + 0.0005 && x < xb - 0.0005)
            secs = append(secs, [x, 0 * meter]);
    secs = append(secs, [xb, dxb]);
    var regions = [];
    var sketches = [];
    for (var k = 0; k < size(secs); k += 1)
    {
        const cz = fusCoreAtNum(plan, min(max(secs[k][0], plan.x0), plan.x1));
        const sid = idB + ("s" ~ k);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(secs[k][0] * meter + secs[k][1], 0 * meter, cz.zc * meter), X_DIRECTION, Y_DIRECTION) });
        roundedRect(sk, cz.ac * meter, cz.bc * meter, max(cz.rc * meter, 0.2 * millimeter));
        skSolve(sk);
        regions = append(regions, qSketchRegion(sid));
        sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
    }
    opLoft(context, idB + "loft", { "profileSubqueries" : regions });
    opDeleteBodies(context, idB + "del", { "entities" : qUnion(sketches) });
    return qCreatedBy(idB + "loft", EntityType.BODY);
}

/** Fuselage section [a, b, r] (SI half-width, half-height, corner radius) at x from the published stations, linear between them, held beyond the ends. */
function fusSectionAt(st is array, x is number) returns array
{
    if (x <= st[0][0])
        return [st[0][1], st[0][2], st[0][3]];
    for (var k = 0; k < size(st) - 1; k += 1)
    {
        if (x >= st[k][0] && x <= st[k + 1][0])
        {
            if (st[k + 1][0] - st[k][0] < 1e-6)
                return [st[k + 1][1], st[k + 1][2], st[k + 1][3]];
            const u = (x - st[k][0]) / (st[k + 1][0] - st[k][0]);
            return [st[k][1] + u * (st[k + 1][1] - st[k][1]), st[k][2] + u * (st[k + 1][2] - st[k][2]), st[k][3] + u * (st[k + 1][3] - st[k][3])];
        }
    }
    const l = size(st) - 1;
    return [st[l][1], st[l][2], st[l][3]];
}

/** Height of a fuselage parting profile [(x, z)] at x: piecewise linear, flat beyond its ends, a vertical step where two points share an x. */
function fusPartZ(prof is array, x is ValueWithUnits) returns ValueWithUnits
{
    if (size(prof) == 0)
        return 0 * meter;
    if (x <= prof[0][0])
        return prof[0][1];
    for (var i = 0; i < size(prof) - 1; i += 1)
    {
        if (x >= prof[i][0] && x <= prof[i + 1][0])
        {
            if (prof[i + 1][0] - prof[i][0] < 0.001 * millimeter)
                return prof[i + 1][1];
            return prof[i][1] + (x - prof[i][0]) / (prof[i + 1][0] - prof[i][0]) * (prof[i + 1][1] - prof[i][1]);
        }
    }
    return prof[size(prof) - 1][1];
}

function moldPin(context is Context, pinId is Id, c0 is Vector, c1 is Vector, r is ValueWithUnits) returns Query
{
    return moldFrustum(context, pinId, c0, c1, r, r);
}

/** The surface's section at model span position yc (either side), placed as placeSection leaves it: points
    [px along the chord from the pivot, pz up in the section's own plane]. A local point sits in the model at
    moldCorePoint(sec, px, pz). In a winglet the station is found from the frame's y (the span line bends up, so
    y runs slower than the developed eta) and the section is tilted by phi; "winglet" says so, for callers that
    want square sections only (the joint dowels). ok false only beyond the tip. */
function moldCoreSectionAt(m is map, mini is map, yc is ValueWithUnits) returns map
{
    const hD = m.span / 2 * meter;
    var etaD = min(abs(yc) / hD, 1);
    var frame = wingletFrame(m, etaD);
    if (m.wingletOn == 1 && abs(yc) > wingletFrame(m, m.wingletEta).y)
    {
        // the developed station whose span line passes |yc|: bisection on the frame's y
        if (abs(yc) > wingletFrame(m, 1).y + 1 * millimeter)
            return { "ok" : false, "eta" : 1 };
        var lo = m.wingletEta;
        var hi = 1;
        for (var i = 0; i < 30; i += 1)
        {
            const mid = 0.5 * (lo + hi);
            if (wingletFrame(m, mid).y < abs(yc))
                lo = mid;
            else
                hi = mid;
        }
        etaD = 0.5 * (lo + hi);
        frame = wingletFrame(m, etaD);
    }
    const chord0 = m.c0 * meter * chordFactor(m, etaD);
    const tailAdd = m.c0 * meter * tailFactor(m, etaD);
    const thick0 = (m.rootT + (m.tipT - m.rootT) * etaD ^ m.thicknessExp) * (chord0 - tailAdd) / chord0;
    const twist = (m.incidence - m.washout * etaD ^ m.washoutExp) * radian;
    const chordBase = (chord0 - tailAdd) / capPlanFactor(m, etaD);
    const alignShift = (m.pivotFrac - m.align) * (chordBase - m.c0 * meter) + m.pivotFrac * tailAdd + (0.5 - m.pivotFrac) * (chordBase - (chord0 - tailAdd));
    const bump = bumpOffset(m, etaD, hD);
    const chord = chord0 + bump;
    const thick = thick0 * chord0 / chord;
    const xOff = m.sweepTip * meter * etaD ^ m.sweepExp + alignShift - (1 - m.pivotFrac) * bump;
    const sec = buildSectionAt(mini, thick, min(m.teThick * meter, 0.03 * chord) / chord, 40, sectionWeightAt(mini, etaD));
    const placed = placeSection(sec, chord, m.pivotFrac, cos(twist), sin(twist));
    return { "ok" : true, "eta" : etaD, "placed" : placed, "chord" : chord, "thick" : thick, "xOff" : xOff, "zOff" : frame.z,
             "winglet" : frame.on == true, "fy" : frame.y, "phi" : frame.phi, "side" : yc < 0 * meter ? -1 : 1, "baseX" : m.baseX * meter, "baseZ" : m.baseZ * meter };
}

/** A section-local point (px along the chord, pz up in the section plane) of moldCoreSectionAt's result in the
    model: the frame's y and z, the section tilted by phi as moldWingletTable tilts it (py = y - pz sin phi,
    pz = z + pz cos phi), mirrored to the section's side. */
function moldCorePoint(sec is map, px is ValueWithUnits, pz is ValueWithUnits) returns Vector
{
    return vector(sec.baseX + sec.xOff + px, sec.side * (sec.fy - pz * sin(sec.phi)), sec.baseZ + sec.zOff + pz * cos(sec.phi));
}

/** Lower and upper surface of a placed section at chord position xs: [zLo, zHi], or undefined off the section. */
function moldSectionZAt(placed is array, xs is ValueWithUnits)
{
    const np = size(placed);
    var zLo = 1 * meter;
    var zHi = -1 * meter;
    for (var i = 0; i < np; i += 1)
    {
        const p = placed[i];
        const r = placed[(i + 1) % np];
        if ((p[0] - xs) * (r[0] - xs) <= 0 * meter * meter && abs(r[0] - p[0]) > 1e-9 * meter)
        {
            const z = p[1] + (r[1] - p[1]) * ((xs - p[0]) / (r[0] - p[0]));
            zLo = min(zLo, z);
            zHi = max(zHi, z);
        }
    }
    return zHi > zLo ? [zLo, zHi] : undefined;
}

/**
 * A milled core's puzzle inlay at the joint yc (build 235). The core's sections at the joint and at the
 * inlay's two ends (yc +/- lh), each with its UD cap band (Cap width % of the chord about the section's
 * thickest point, where the core carries the cap's groove); the key goes just outside the band - ahead
 * of it or behind it, whichever leaves the thicker core at the key's centre - with 1 mm to the band and
 * 1 mm inside the core's ends at all three sections. Returns { ok, why, x (world centre), t (the core's
 * thickness there), zTop, zBot (its faces there), topHi, topLo, botHi, botLo (the faces over the key's
 * footprint, half width wh) }, world coordinates; not in a winglet (the joint is not square there).
 */
function coreInlaySpot(m is map, mini is map, yc is ValueWithUnits, lh is ValueWithUnits, wh is ValueWithUnits, skinFace is ValueWithUnits, capW is number, capF is number, tSkins is ValueWithUnits) returns map
{
    const ys = [yc - lh, yc, yc + lh];
    var secs = [];
    var cores = [];
    var bandLo = 1 * meter;
    var bandHi = -1 * meter;
    var xIn = -1 * meter;                                          // the core's x range common to the three sections
    var xOut = 1 * meter;
    for (var i = 0; i < 3; i += 1)
    {
        const sq = moldCoreSectionAt(m, mini, ys[i]);
        if (sq.ok != true || sq.winglet == true)
            return { "ok" : false, "why" : "it is in the winglet" };
        const capT = capF * max(sq.thick * sq.chord - tSkins, 0 * meter) / 2;
        const core = coreOutline(sq.placed, skinFace, capW * sq.chord, capT);
        if (core == undefined)
            return { "ok" : false, "why" : "the section has no core" };
        // the section's thickest point, the band's centre (as the dowels and the core outline place it)
        const np = size(sq.placed);
        const xTe = sq.placed[0][0];
        const xNose = sq.placed[(np + 1) / 2 - 1][0];
        var xT = xTe;
        var tMax = 0 * meter;
        for (var k = 0; k < 40; k += 1)
        {
            const xs = xTe + (xNose - xTe) * (k + 0.5) / 40;
            const zz = moldSectionZAt(sq.placed, xs);
            if (zz != undefined && zz[1] - zz[0] > tMax)
            {
                tMax = zz[1] - zz[0];
                xT = xs;
            }
        }
        const x0w = moldCorePoint(sq, 0 * meter, 0 * meter)[0];  // the section's local x = 0 in the world
        bandLo = min(bandLo, x0w + xT - capW * sq.chord / 2);
        bandHi = max(bandHi, x0w + xT + capW * sq.chord / 2);
        xIn = max(xIn, x0w + core.upper[size(core.upper) - 1][0]);
        xOut = min(xOut, x0w + core.upper[0][0]);
        secs = append(secs, sq);
        cores = append(cores, core);
    }
    // the faces of a core outline at world x on section i: [top, bottom] in world z, or undefined
    var best;
    for (var c in [bandHi + 1 * millimeter + wh, bandLo - 1 * millimeter - wh])
    {
        if (c - wh < xIn + 1 * millimeter || c + wh > xOut - 1 * millimeter)
            continue;
        var faces = [];
        for (var i = 0; i < 3; i += 1)
        {
            const sq = secs[i];
            const x0w = moldCorePoint(sq, 0 * meter, 0 * meter)[0];
            var lowR = [];                                         // the lower face, tail -> nose like the upper
            for (var k = size(cores[i].lower) - 1; k >= 0; k -= 1)
                lowR = append(lowR, cores[i].lower[k]);
            for (var dx in [-wh, 0 * meter, wh])
            {
                const px = c + dx - x0w;
                faces = append(faces, [moldCorePoint(sq, px, coreYAt(cores[i].upper, px))[2], moldCorePoint(sq, px, coreYAt(lowR, px))[2], i == 1 && dx == 0 * meter]);
            }
        }
        var cTop = 0 * meter;
        var cBot = 0 * meter;
        var topHi = -1 * meter;
        var topLo = 1 * meter;
        var botHi = -1 * meter;
        var botLo = 1 * meter;
        for (var fc in faces)
        {
            if (fc[2])
            {
                cTop = fc[0];
                cBot = fc[1];
            }
            topHi = max(topHi, fc[0]);
            topLo = min(topLo, fc[0]);
            botHi = max(botHi, fc[1]);
            botLo = min(botLo, fc[1]);
        }
        if (best == undefined || cTop - cBot > best.t)
            best = { "ok" : true, "why" : "", "x" : c, "t" : cTop - cBot, "zTop" : cTop, "zBot" : cBot, "topHi" : topHi, "topLo" : topLo, "botHi" : botHi, "botLo" : botLo };
    }
    if (best == undefined)
        return { "ok" : false, "why" : "the key does not fit between the cap band and the core's ends" };
    return best;
}

/** Height a core section between ya and yb takes in Z - droop, twist and thickness together - for the sheet it
    is milled from. Nine sections sampled along it; the skins are ignored (the core is thinner). */
function moldCoreZExtent(m is map, mini is map, ya is ValueWithUnits, yb is ValueWithUnits) returns ValueWithUnits
{
    var zMin = 1 * meter;
    var zMax = -1 * meter;
    for (var q = 0; q <= 8; q += 1)
    {
        const sq = moldCoreSectionAt(m, mini, ya + (yb - ya) * q / 8);
        if (sq.ok != true)
            continue;
        for (var p in sq.placed)
        {
            const z = moldCorePoint(sq, p[0], p[1])[2];
            zMin = min(zMin, z);
            zMax = max(zMax, z);
        }
    }
    return zMax > zMin ? zMax - zMin : 0 * meter;
}

/** Truncated cone from c0 (radius r0) to c1 (radius r1), as a loft of two circles. Returns its body query. */
function moldFrustum(context is Context, pinId is Id, c0 is Vector, c1 is Vector, r0 is ValueWithUnits, r1 is ValueWithUnits) returns Query
{
    const axis = normalize(c1 - c0);
    const xdir = abs(axis[0]) > 0.5 ? Y_DIRECTION : X_DIRECTION;
    const cs = [c0, c1];
    const rs = [r0, r1];
    var regions = [];
    for (var i = 0; i < 2; i += 1)
    {
        const sid = pinId + ("c" ~ i);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(cs[i], axis, xdir) });
        skCircle(sk, "c", { "center" : vector(0, 0) * meter, "radius" : rs[i] });
        skSolve(sk);
        regions = append(regions, qSketchRegion(sid));
    }
    opLoft(context, pinId + "loft", { "profileSubqueries" : regions });
    opDeleteBodies(context, pinId + "del", { "entities" : qUnion([qCreatedBy(pinId + "c0", EntityType.BODY), qCreatedBy(pinId + "c1", EntityType.BODY)]) });
    return qCreatedBy(pinId + "loft", EntityType.BODY);
}

/**
 * Puzzle inlay (build 235): the bow-tie key and its pocket from the dialog. The key is two dovetails
 * back to back, Inlay length along its axis (across the seam, centred on it), Inlay width at its ends
 * and Inlay waist at the seam; the pocket is the key grown by Glue gap all round, which is again a
 * bow-tie with the same flank slope s. The pocket's four end corners (its inside corners) take the
 * cutter's radius rc and the key's the same, so it drops in. At the waist the key keeps the round a
 * cutter leaves in its inside corners (rc) and the pocket's waist, the tile's outside corner, is
 * rounded concentric with it (rc - g), so the gap is Glue gap everywhere and no edge of the pocket
 * lies on the seam the tiles are later split along. Half sizes: lh (length), wh (waist), Wh (ends);
 * pLh, pwh, pWh the pocket's. key and pocket are outlines for inlayPrism.
 */
function inlayDims(definition is map) returns map
{
    if (definition.inlayWaist > definition.inlayWidth - 2 * millimeter)
        throw regenError("Inlay waist must be at most Inlay width - 2 mm: the bow-tie's flanks are what lock the tiles together", ["inlayWaist", "inlayWidth"]);
    const lh = definition.inlayLen / 2;
    const wh = definition.inlayWaist / 2;
    const s = (definition.inlayWidth / 2 - wh) / lh;
    const q = sqrt(1 + s * s);
    const g = definition.inlayGap;
    const rc = definition.inlayCutter / 2;
    const pLh = lh + g;
    const pwh = wh + g * q;
    return { "s" : s, "rc" : rc, "lh" : lh, "wh" : wh, "Wh" : wh + s * lh, "pLh" : pLh, "pwh" : pwh, "pWh" : pwh + s * pLh,
             "key" : inlayOutline(lh, wh, s, rc, rc), "pocket" : inlayOutline(pLh, pwh, s, rc, max(rc - g, 0.05 * millimeter)) };
}

/**
 * A bow-tie outline in local (u along its axis, v across), centred on the origin: half length lh, half
 * waist wh, flank slope s (half width at the ends wh + s lh), the four end corners rounded with radius
 * rc and the two waist corners with rw. Returned as a closed chain of { "line" : [a, b] } and
 * { "arc" : [a, mid, b] }.
 */
function inlayOutline(lh is ValueWithUnits, wh is ValueWithUnits, s is number, rc is ValueWithUnits, rw is ValueWithUnits) returns array
{
    const q = sqrt(1 + s * s);
    const Wh = wh + s * lh;
    const th = PI / 2 - atan(s) / radian;                  // the interior angle at an end corner
    const t = rc / tan((th / 2) * radian);                 // the end round's tangent length from its corner
    const tw = rw * s;                                     // the waist round's (the flanks turn by 2 atan s there)
    if (t > Wh - 0.05 * millimeter || t + tw > lh * q - 0.05 * millimeter)
        throw regenError("Cutter dia is too large for the inlay: its corner radius takes " ~ fmt(t / millimeter, 1) ~ " mm of each side of a " ~ fmt(2 * Wh / millimeter, 1) ~ " mm end - a smaller Cutter dia, or a wider Inlay width", ["inlayCutter", "inlayWidth"]);
    const dm = rc / sin((th / 2) * radian) - rc;           // end corner to its round's middle, along the bisector
    const bu = -1 / q;
    const bv = -(1 + s / q);
    const bl = sqrt(bu * bu + bv * bv);
    // the +u +v end corner: where its round leaves the end, its middle, where it meets the flank; the
    // waist round's end on the +u flank and its middle (its centre is at (0, wh + rw q)); the other
    // corners are their mirror images
    const pE = vector(lh, Wh - t);
    const pM = vector(lh + dm * bu / bl, Wh + dm * bv / bl);
    const pF = vector(lh - t / q, Wh - t * s / q);
    const wR = vector(rw * s / q, wh + rw * s * s / q);
    const wM = vector(0 * meter, wh + rw * (q - 1));
    return [
            { "line" : [inlayFlip(pE, 1, -1), pE] },
            { "arc" : [pE, pM, pF] },
            { "line" : [pF, wR] },
            { "arc" : [wR, wM, inlayFlip(wR, -1, 1)] },
            { "line" : [inlayFlip(wR, -1, 1), inlayFlip(pF, -1, 1)] },
            { "arc" : [inlayFlip(pF, -1, 1), inlayFlip(pM, -1, 1), inlayFlip(pE, -1, 1)] },
            { "line" : [inlayFlip(pE, -1, 1), inlayFlip(pE, -1, -1)] },
            { "arc" : [inlayFlip(pE, -1, -1), inlayFlip(pM, -1, -1), inlayFlip(pF, -1, -1)] },
            { "line" : [inlayFlip(pF, -1, -1), inlayFlip(wR, -1, -1)] },
            { "arc" : [inlayFlip(wR, -1, -1), inlayFlip(wM, 1, -1), inlayFlip(wR, 1, -1)] },
            { "line" : [inlayFlip(wR, 1, -1), inlayFlip(pF, 1, -1)] },
            { "arc" : [inlayFlip(pF, 1, -1), inlayFlip(pM, 1, -1), inlayFlip(pE, 1, -1)] }
        ];
}

/** A local outline point mirrored: (su u, sv v). */
function inlayFlip(p is Vector, su is number, sv is number) returns Vector
{
    return vector(su * p[0], sv * p[1]);
}

/**
 * An inlay outline (inlayOutline) on the plane through origin with unit normal n, its axis (local u)
 * along xDir (perpendicular to n), extruded along n by thick: a key lying on a tilted pocket floor, or
 * with n vertical a pocket's prism (build 235). The outline is symmetric, so the sketch's handedness
 * does not matter. The sketch is deleted here; returns the solid's query. pid must be unique per call.
 */
function inlayPlate(context is Context, pid is Id, segs is array, origin is Vector, n is Vector, xDir is Vector, thick is ValueWithUnits) returns Query
{
    const sid = pid + "sk";
    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(origin, n, xDir) });
    for (var i = 0; i < size(segs); i += 1)
    {
        const sg = segs[i];
        if (sg.arc != undefined)
            skArc(sk, "a" ~ i, { "start" : sg.arc[0], "mid" : sg.arc[1], "end" : sg.arc[2] });
        else
            skLineSegment(sk, "l" ~ i, { "start" : sg.line[0], "end" : sg.line[1] });
    }
    skSolve(sk);
    opExtrude(context, pid + "ex", {
                "entities" : qSketchRegion(sid),
                "direction" : n,
                "endBound" : BoundingType.BLIND,
                "endDepth" : thick
            });
    opDeleteBodies(context, pid + "del", { "entities" : qCreatedBy(sid, EntityType.BODY) });
    return qCreatedBy(pid + "ex", EntityType.BODY);
}

/** An inlay outline as a vertical prism from z0 up to z1 about the plan point (cx, cy), its axis along Y (alongY) or X. */
function inlayPrism(context is Context, pid is Id, segs is array, cx is ValueWithUnits, cy is ValueWithUnits, alongY is boolean, z0 is ValueWithUnits, z1 is ValueWithUnits) returns Query
{
    return inlayPlate(context, pid, segs, vector(cx, cy, z0), Z_DIRECTION, alongY ? Y_DIRECTION : X_DIRECTION, z1 - z0);
}

/**
 * A slab on a tilted pocket floor (build 235): a rectangle 2 hu x 2 hv on the plane through origin with
 * unit normal n (hu along xDir), extruded along n by depth. Intersected with the pocket's vertical prism
 * it leaves the pocket above (or below) the floor. Returns its body.
 */
function inlaySlab(context is Context, pid is Id, origin is Vector, n is Vector, xDir is Vector, hu is ValueWithUnits, hv is ValueWithUnits, depth is ValueWithUnits) returns Query
{
    const sid = pid + "sk";
    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(origin, n, xDir) });
    const c = [vector(-hu, -hv), vector(hu, -hv), vector(hu, hv), vector(-hu, hv)];
    for (var k = 0; k < 4; k += 1)
        skLineSegment(sk, "s" ~ k, { "start" : c[k], "end" : c[(k + 1) % 4] });
    skSolve(sk);
    opExtrude(context, pid + "ex", {
                "entities" : qSketchRegion(sid),
                "direction" : n,
                "endBound" : BoundingType.BLIND,
                "endDepth" : depth
            });
    opDeleteBodies(context, pid + "del", { "entities" : qCreatedBy(sid, EntityType.BODY) });
    return qCreatedBy(pid + "ex", EntityType.BODY);
}

/**
 * Where a closed (x, y) loop crosses the line y = c (horizontal) or x = c: [lowest, highest] of the other
 * coordinate there, or undefined when the loop does not reach the line (build 235: the cavity's edge
 * along a tile seam).
 */
function loopSpanAt(loop is array, c is ValueWithUnits, horizontal is boolean)
{
    const n = size(loop);
    const a = horizontal ? 1 : 0;
    const b = horizontal ? 0 : 1;
    var lo;
    var hi;
    for (var i = 0; i < n; i += 1)
    {
        const p = loop[i];
        const r = loop[(i + 1) % n];
        if ((p[a] - c) * (r[a] - c) <= 0 * meter * meter && abs(r[a] - p[a]) > 1e-9 * meter)
        {
            const v = p[b] + (c - p[a]) / (r[a] - p[a]) * (r[b] - p[b]);
            lo = lo == undefined ? v : min(lo, v);
            hi = hi == undefined ? v : max(hi, v);
        }
    }
    return lo == undefined ? undefined : [lo, hi];
}

/**
 * A puzzle inlay's centre along its flange (build 235): the free coordinate between a and b (the room
 * with its clearances already taken off), as near the middle as the keep-out boxes allow, in 0.5 mm
 * steps out from it. fixed is the other coordinate (the seam); alongY says the key's axis is along Y,
 * so the free coordinate is X; lh and wh are the pocket's half extents along and across its axis.
 * Returns { c } or { why }, the first keep-out met at the middle.
 */
function inlayPlace(keep is array, a is ValueWithUnits, b is ValueWithUnits, fixed is ValueWithUnits, alongY is boolean, lh is ValueWithUnits, wh is ValueWithUnits) returns map
{
    const mid = 0.5 * (a + b);
    const nStep = floor((b - a) / millimeter);               // 0.5 mm steps either side of the middle
    var why = "";
    for (var k = 0; k <= 2 * nStep; k += 1)
    {
        const c = mid + (k % 2 == 0 ? 1 : -1) * ceil(k / 2) * 0.5 * millimeter;
        if (c < a - 0.001 * millimeter || c > b + 0.001 * millimeter)
            continue;
        const x0 = alongY ? c - wh : fixed - lh;
        const x1 = alongY ? c + wh : fixed + lh;
        const y0 = alongY ? fixed - lh : c - wh;
        const y1 = alongY ? fixed + lh : c + wh;
        var hit = "";
        for (var kb in keep)
        {
            if (x1 > kb.x0 && x0 < kb.x1 && y1 > kb.y0 && y0 < kb.y1)
            {
                hit = kb.what;
                break;
            }
        }
        if (hit == "")
            return { "c" : c };
        if (why == "")
            why = hit;
    }
    return { "why" : why == "" ? "nothing (no room)" : why };
}

/**
 * One printed key across a joint at point p, boss pointing along d. The socket (radius + fit, 0.3 mm
 * deeper) is cut into the tile of half sideB (0 upper, 1 lower) whose footprint holds pB, then the
 * boss is joined to the tile of half sideA holding pA, base sunk 1 mm in. Both tiles are looked up
 * after their tool body exists, never held across an operation.
 */
/**
 * One printed key across a tile seam: a socket cut into the tile under pB, a boss joined to the
 * tile under pA. Returns false and makes nothing when either point is not on a tile - a seam
 * that crosses the socket plug channel has its flange cut away there, and build 127 joined the
 * boss to the nearest tile anyway, leaving it floating as its own part.
 */
function moldPrintedKey(context is Context, keyId is Id, solids is Query, lo is Vector, hi is Vector, sideA is number, sideB is number,
    pA is Vector, pB is Vector, p is Vector, d is Vector, rB is ValueWithUnits, rT is ValueWithUnits, hb is ValueWithUnits, fit is ValueWithUnits) returns boolean
{
    const sink = 1 * millimeter;
    var hv = moldHalves(context, solids, lo, hi);
    const nearB = moldTileNear(context, sideB == 0 ? hv.upper : hv.lower, pB);
    const nearA = moldTileNear(context, sideA == 0 ? hv.upper : hv.lower, pA);
    if (nearA.d > 1 * millimeter || nearB.d > 1 * millimeter)
        return false;
    const sock = moldFrustum(context, keyId + "s", p - sink * d, p + (hb + 0.3 * millimeter) * d, rB + fit, rT + fit);
    opBoolean(context, keyId + "cut", { "tools" : sock, "targets" : nearB.body, "operationType" : BooleanOperationType.SUBTRACTION });
    const boss = moldFrustum(context, keyId + "b", p - sink * d, p + hb * d, rB, rT);
    hv = moldHalves(context, solids, lo, hi);
    opBoolean(context, keyId + "join", { "tools" : qUnion([moldTileAt(context, sideA == 0 ? hv.upper : hv.lower, pA), boss]), "operationType" : BooleanOperationType.UNION });
    return true;
}

/** The nearest tile (of one half) to point pt, and its distance. */
function moldTileNear(context is Context, tiles is Query, pt is Vector) returns map
{
    // nearest body to the point (the key points lie on or just inside their tile, so the distance
    // is ~0). Build 82 used loose bounding-box containment, which on the drooped wing tips matched
    // a neighbouring tile first: the boss was "unioned" with a body it never touched and was left
    // floating as its own part
    var best;
    var bestD = 1 * meter;
    for (var b in evaluateQuery(context, tiles))
    {
        const d = evDistance(context, { "side0" : b, "side1" : pt }).distance;
        if (best == undefined || d < bestD)
        {
            best = b;
            bestD = d;
        }
    }
    if (best == undefined)
        throw regenError("No tile found under a key position - inspect the bodies");
    return { "body" : best, "d" : bestD };
}

/** The tile (of one half) nearest to point pt. */
/**
 * Ejector probe (build 243): at (x, y), the cavity's top (a ray up into the upper half from below) and bottom (a ray down
 * into the lower half from above), and whether both faces are smooth across a rim of radius rr (four rays each within
 * 1 mm of the centre's). t is the part's thickness there; ok needs t over 1 mm and both rims smooth.
 */
function moldEjectProbe(context is Context, upper is Query, lower is Query, x is ValueWithUnits, y is ValueWithUnits, zBelow is ValueWithUnits, zAbove is ValueWithUnits, rr is ValueWithUnits, rim is boolean) returns map
{
    const cu = moldRayZ(context, upper, x, y, zBelow, true);
    const cl = moldRayZ(context, lower, x, y, zAbove, false);
    if (!cu.hit || !cl.hit || cu.z - cl.z < 1 * millimeter)
        return { "ok" : false, "t" : 0 * meter };
    if (rim)
    {
        for (var d in [[1, 0], [-1, 0], [0, 1], [0, -1]])
        {
            const u = moldRayZ(context, upper, x + d[0] * rr, y + d[1] * rr, zBelow, true);
            const l = moldRayZ(context, lower, x + d[0] * rr, y + d[1] * rr, zAbove, false);
            if (!u.hit || !l.hit || abs(u.z - cu.z) > 1 * millimeter || abs(l.z - cl.z) > 1 * millimeter)
                return { "ok" : false, "t" : cu.z - cl.z };
        }
    }
    return { "ok" : true, "t" : cu.z - cl.z, "zU" : cu.z, "zL" : cl.z };
}

function moldTileAt(context is Context, tiles is Query, pt is Vector) returns Query
{
    return moldTileNear(context, tiles, pt).body;
}

/**
 * Splits targets with a plane through origin, normal n. Tries a construction plane first; if
 * Onshape refuses that as a split tool, a planar sheet lofted between two lines. Returns the
 * tool body to delete afterwards.
 */
function moldCut(context is Context, cutId is Id, targets is Query, origin is Vector, n is Vector, lo is Vector, hi is Vector) returns Query
{
    const big = 2 * max(hi[0] - lo[0], max(hi[1] - lo[1], hi[2] - lo[2]));
    try
    {
        opPlane(context, cutId + "plane", { "plane" : plane(origin, n), "width" : big, "height" : big });
        opSplitPart(context, cutId + "split", { "targets" : targets, "tool" : qCreatedBy(cutId + "plane", EntityType.FACE) });
        return qCreatedBy(cutId + "plane", EntityType.BODY);
    }
    catch
    {
        // sheet: two parallel lines in the cut plane, lofted as a surface
        const xdir = abs(n[1]) > 0.5 ? X_DIRECTION : Y_DIRECTION;   // in-plane direction
        const c = origin;
        const zlo = lo[2] - 10 * millimeter;
        const zhi = hi[2] + 10 * millimeter;
        var edges = [];
        for (var i = 0; i < 2; i += 1)
        {
            const sid = cutId + ("l" ~ i);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(c, n, xdir) });
            const z = i == 0 ? zlo : zhi;
            skLineSegment(sk, "e", { "start" : vector(-big, z - c[2]), "end" : vector(big, z - c[2]) });
            skSolve(sk);
            edges = append(edges, qCreatedBy(sid, EntityType.EDGE));
        }
        opLoft(context, cutId + "sheet", { "profileSubqueries" : edges, "bodyType" : ToolBodyType.SURFACE });
        opDeleteBodies(context, cutId + "dl", { "entities" : qUnion([qCreatedBy(cutId + "l0", EntityType.BODY), qCreatedBy(cutId + "l1", EntityType.BODY)]) });
        opSplitPart(context, cutId + "split2", { "targets" : targets, "tool" : qCreatedBy(cutId + "sheet", EntityType.FACE) });
        return qCreatedBy(cutId + "sheet", EntityType.BODY);
    }
}

/**
 * World points of the parting curve at one station: the section's camber line (mean of upper and
 * lower), placed with the same chord, twist, sweep and droop as buildFoil, extended straight along
 * the local chord direction to xMin forward and xMax aft. With a socket map, the aft run is aimed
 * through the nacelle axis instead.
 */
/**
 * Parting curve at one station. With a stab mount map (foilStabRoot with padOn) the parting over the pad's
 * plan (|y| within Pad width / 2) is the pad-side skin of the part instead of the camber line: the
 * nose, the ramp up to the pad plane, then the pad plane itself out to the block edge. The whole
 * section, the pad's side walls and the tail fairing then sit in the half away from the pad, and
 * the other half only forms the flat pad face - the production mold layout. Nothing changes off the pad.
 */
function moldPartingPointsPad(m is map, mini is map, eta is number, y is ValueWithUnits, base is Vector, xMin is ValueWithUnits, xMax is ValueWithUnits, sock, pad) returns map
{
    const onPad = pad != undefined && pad.padOn == 1 && pad.padSide != 0 && abs(y) <= pad.padWidth / 2 * meter;
    const h = m.span / 2 * meter;
    const chord0 = m.c0 * meter * chordFactor(m, eta);
    const tailAdd = m.c0 * meter * tailFactor(m, eta);
    const thick0 = (m.rootT + (m.tipT - m.rootT) * eta ^ m.thicknessExp) * (chord0 - tailAdd) / chord0;
    const twist = (m.incidence - m.washout * eta ^ m.washoutExp) * radian;
    const chordBase = (chord0 - tailAdd) / capPlanFactor(m, eta);
    const alignShift = (m.pivotFrac - m.align) * (chordBase - m.c0 * meter) + m.pivotFrac * tailAdd + (0.5 - m.pivotFrac) * (chordBase - (chord0 - tailAdd));
    const fDropM = dropShape(m, eta);
    const bump = bumpOffset(m, eta, h);                  // leading-edge bumps, as buildFoil places them
    const chord = chord0 + bump;
    const thick = thick0 * chord0 / chord;
    const xOff = m.sweepTip * meter * eta ^ m.sweepExp + alignShift - (1 - m.pivotFrac) * bump;
    const zOff = -m.tipDrop * meter * fDropM + h * tan(m.rootDihedral * radian) * (eta - fDropM);
    const cosT = cos(twist);
    const sinT = sin(twist);

    // the parting line of a vertical pull is the section's silhouette from above: from its most
    // forward point to its most aft point, along the midline of its vertical extent at each x.
    // Computed on the PLACED (twisted, scaled) outline, so it is exact for any profile - a mean line
    // through the profile table's (0, 0) is not: E818's drooped nose has its lower surface above that
    // point and the mean line left the section there (tongue in the upper half, BOOLEAN_INVALID)
    const teFrac = min(m.teThick * meter, 0.03 * chord) / chord;
    const sec = buildSectionAt(mini, thick, teFrac, 40, sectionWeightAt(mini, eta));
    const placed = placeSection(sec, chord, m.pivotFrac, cosT, sinT);
    const np = size(placed);
    var iMin = 0;
    var iMax = 0;
    for (var i = 1; i < np; i += 1)
    {
        if (placed[i][0] < placed[iMin][0])
            iMin = i;
        if (placed[i][0] > placed[iMax][0])
            iMax = i;
    }
    const xNose = placed[iMin][0];
    const xTail = placed[iMax][0] - 0.1 * millimeter;      // just ahead of the trailing-edge face
    const origin = base + vector(xOff, y, zOff);
    // 30 samples, cosine-packed towards nose and tail: an aft-loaded section (E818) bends its
    // midline hard where it is under a millimetre thick, and a coarser spline strays outside it
    const nS = 30;
    var cam = [origin + vector(placed[iMin][0], 0 * meter, placed[iMin][1])];
    // pad: plane and ramp in this station's frame (the pad plane is horizontal in world)
    var padRel = 0 * meter;
    var xR0 = 0 * meter;
    var xR1 = 0 * meter;
    if (onPad)
    {
        padRel = pad.padZ * meter - origin[2];
        xR0 = pad.padX0 * meter - origin[0];
        xR1 = pad.leX * meter - origin[0] + pad.padRampPct / 100 * (pad.teX - pad.leX) * meter;
    }
    for (var k = 1; k < nS; k += 1)
    {
        const xs = xNose + (xTail - xNose) * 0.5 * (1 - cos((PI * k / (nS - 1)) * radian));
        var zLo = 1 * meter;
        var zHi = -1 * meter;
        for (var i = 0; i < np; i += 1)
        {
            const p = placed[i];
            const q = placed[(i + 1) % np];
            if ((p[0] - xs) * (q[0] - xs) <= 0 * meter * meter && abs(q[0] - p[0]) > 1e-9 * meter)
            {
                const z = p[1] + (q[1] - p[1]) * ((xs - p[0]) / (q[0] - p[0]));
                zLo = min(zLo, z);
                zHi = max(zHi, z);
            }
        }
        if (onPad)
        {
            // pad-side skin with the mount's own ramp law (smoothstep from the nose to Pad ramp %)
            const skin = pad.padSide == 1 ? zHi : zLo;
            const t = min(max((xs - xR0) / (xR1 - xR0), 0), 1);
            const sm = t * t * (3 - 2 * t);
            cam = append(cam, origin + vector(xs, 0 * meter, skin + (padRel - skin) * sm));
        }
        else
            cam = append(cam, origin + vector(xs, 0 * meter, 0.5 * (zLo + zHi)));
    }
    const le = cam[0];
    const te = cam[size(cam) - 1];

    // horizontal runs out to xMin forward and xMax aft (a corner at the LE/TE is fine for the loft;
    // an extension collinear with a straight mean line was not). At the wing socket the aft run
    // rises to the nacelle axis, so its round section splits within 0.05 mm of a diameter. Over the
    // pad the aft run is the pad plane itself, which also forms the tail fairing's flat face
    const front = vector(xMin, y, le[2]);
    const aft = vector(xMax, y, onPad ? origin[2] + padRel : (sock == undefined ? te[2] : sock.axisZ * meter));
    // a faired socket's tail (build 241): behind the trailing edge the parting follows the web's own law, the
    // trailing edge's height plus this station's droop easing to the socket's axis by the tail's end, so it runs
    // through the web and then through the nacelle's diameter; the end point is the axis as before
    var aftPts = [];
    if (!onPad && sock != undefined && sock.web != undefined && sock.web.on == 1)
    {
        const wb = sock.web;
        const dz = te[2] / meter - wb.z0;        // this station's droop against the root's trailing edge
        const xa = te[0] / meter;
        const xb = min(wb.x1, xMax / meter - 1e-3);
        if (xb > xa + 2e-3)
        {
            for (var k = 1; k <= 12; k += 1)
            {
                const xq = xa + (xb - xa) * k / 12;
                aftPts = append(aftPts, vector(xq * meter, y, (fairWebZ(xq, wb.x0, wb.x1, wb.z0, wb.s0, wb.z1) + fairWebW(xq, wb.x0, wb.x1) * dz) * meter));
            }
        }
    }
    return { "front" : front, "camber" : cam, "aft" : aft, "aftPts" : aftPts };
}

/**
 * How far aft the part reaches behind the trailing edge at half-span ya (m, numbers), from a published plan map
 * (xTE, yf, rp, edge [[x, half width]]): the largest x whose edge half width is at least ya, and the plan radius's
 * quarter circle (radius rp, tangent to the trailing edge and to the edge at yf); -2 where nothing reaches.
 */
function moldPlanTailX(pl is map, ya is number) returns number
{
    var best = -2;
    const ed = pl.edge;
    for (var i = 0; i < size(ed); i += 1)
    {
        if (ed[i][1] >= ya - 1e-9)
            best = max(best, ed[i][0]);
        if (i + 1 < size(ed))
        {
            const y0 = ed[i][1];
            const y1 = ed[i + 1][1];
            if ((ya - y0) * (ya - y1) <= 0 && abs(y1 - y0) > 1e-9)
                best = max(best, ed[i][0] + (ed[i + 1][0] - ed[i][0]) * (ya - y0) / (y1 - y0));
        }
    }
    if (pl.rp != undefined && pl.rp > 1e-6 && ya >= pl.yf && ya <= pl.yf + pl.rp)
        best = max(best, pl.xTE + pl.rp - sqrt(max(0, pl.rp * pl.rp - (pl.yf + pl.rp - ya) * (pl.yf + pl.rp - ya))));
    return best;
}

/**
 * Winglet parting table (build 151): the part's mid-thickness surface over the bent tip, sampled on
 * sub-stations along the span line from the bend start to sEnd (beyond the tip, where the tip
 * section is repeated), as world points on the +Y side. Row j holds x[i], y[i], z[i] for i = 0 (LE)
 * to nS - 1 (TE), each on that sub-station's own tilted section plane, so every point is on the true
 * mid-surface. moldPartingPointsWinglet cuts the table with a vertical plane, which is exact to the
 * table's spacing; build 149's "lift the midline by 1 / cos(phi)" left slivers at the LE/TE and the
 * cavity cut failed.
 */
function moldWingletTable(m is map, mini is map, base is Vector, sEnd is ValueWithUnits) returns map
{
    const h = m.span / 2 * meter;
    const s0 = m.wingletEta * h;
    const N = 48;
    const nS = 30;
    var rows = [];
    for (var j = 0; j <= N; j += 1)
    {
        const sj = s0 + (sEnd - s0) * j / N;
        var wf = wingletFrame(m, sj / h);
        if (sj > h)
        {
            // beyond the tip the parting runs FLAT outward at the tip's height, not on up the
            // winglet's line: continued at 45 deg it reached the block's top face at the edge, the
            // lower half then touched top and bottom and moldHalves no longer saw it as a half
            // (CANNOT_RESOLVE_ENTITIES cutting the LOWER cavity, build 151)
            const tf = wingletFrame(m, 1);
            wf = { "on" : true, "y" : tf.y + (sj - h), "z" : tf.z, "phi" : 0 * degree };
        }
        const eta = min(sj / h, 1);
        const chord = m.c0 * meter * chordFactor(m, eta);
        const tailAdd = m.c0 * meter * tailFactor(m, eta);
        const thick = (m.rootT + (m.tipT - m.rootT) * eta ^ m.thicknessExp) * (chord - tailAdd) / chord;
        const twist = (m.incidence - m.washout * eta ^ m.washoutExp) * radian;
        const chordBase = (chord - tailAdd) / capPlanFactor(m, eta);
        const alignShift = (m.pivotFrac - m.align) * (chordBase - m.c0 * meter) + m.pivotFrac * tailAdd + (0.5 - m.pivotFrac) * (chordBase - (chord - tailAdd));
        const bump = bumpOffset(m, eta, h);
        const chordB = chord + bump;
        const xOff = m.sweepTip * meter * eta ^ m.sweepExp + alignShift - (1 - m.pivotFrac) * bump;
        const teFrac = min(m.teThick * meter, 0.03 * chordB) / chordB;
        const sec = buildSectionAt(mini, thick * chord / chordB, teFrac, 40, sectionWeightAt(mini, eta));
        const placed = placeSection(sec, chordB, m.pivotFrac, cos(twist), sin(twist));
        const np = size(placed);
        var iMin = 0;
        var iMax = 0;
        for (var i = 1; i < np; i += 1)
        {
            if (placed[i][0] < placed[iMin][0])
                iMin = i;
            if (placed[i][0] > placed[iMax][0])
                iMax = i;
        }
        const xNose = placed[iMin][0];
        const xTail = placed[iMax][0] - 0.1 * millimeter;
        var lx = [placed[iMin][0]];
        var lz = [placed[iMin][1]];
        for (var k = 1; k < nS; k += 1)
        {
            const xs = xNose + (xTail - xNose) * 0.5 * (1 - cos((PI * k / (nS - 1)) * radian));
            var zLo = 1 * meter;
            var zHi = -1 * meter;
            for (var i = 0; i < np; i += 1)
            {
                const p = placed[i];
                const q = placed[(i + 1) % np];
                if ((p[0] - xs) * (q[0] - xs) <= 0 * meter * meter && abs(q[0] - p[0]) > 1e-9 * meter)
                {
                    const z = p[1] + (q[1] - p[1]) * ((xs - p[0]) / (q[0] - p[0]));
                    zLo = min(zLo, z);
                    zHi = max(zHi, z);
                }
            }
            lx = append(lx, xs);
            lz = append(lz, 0.5 * (zLo + zHi));
        }
        const vy = -sin(wf.phi);
        const vz = cos(wf.phi);
        var px = [];
        var py = [];
        var pz = [];
        for (var i = 0; i < nS; i += 1)
        {
            px = append(px, base[0] + xOff + lx[i]);
            py = append(py, wf.y + lz[i] * vy);
            pz = append(pz, base[2] + wf.z + lz[i] * vz);
        }
        rows = append(rows, { "x" : px, "y" : py, "z" : pz });
    }
    return { "rows" : rows, "nS" : nS, "yStart" : wingletFrame(m, m.wingletEta).y };
}

/** Parting points of the winglet mid-surface on the vertical plane |y| = yAbs; sgnY picks the side. */
function moldPartingPointsWinglet(tab is map, yAbs is ValueWithUnits, sgnY is number, xMin is ValueWithUnits, xMax is ValueWithUnits) returns map
{
    const rows = tab.rows;
    const nR = size(rows);
    var cam = [];
    for (var i = 0; i < tab.nS; i += 1)
    {
        var j = 0;
        while (j < nR - 2 && rows[j + 1].y[i] < yAbs)
            j += 1;
        const y0 = rows[j].y[i];
        const y1 = rows[j + 1].y[i];
        const t = y1 > y0 ? min(max((yAbs - y0) / (y1 - y0), 0), 1) : 0;
        cam = append(cam, vector(rows[j].x[i] + t * (rows[j + 1].x[i] - rows[j].x[i]), sgnY * yAbs, rows[j].z[i] + t * (rows[j + 1].z[i] - rows[j].z[i])));
    }
    return { "front" : vector(xMin, sgnY * yAbs, cam[0][2]), "camber" : cam, "aft" : vector(xMax, sgnY * yAbs, cam[tab.nS - 1][2]) };
}

/**
 * Foam core body (build 158): the part's sections offset inward by one face's skin thickness, with
 * the UD caps' grooves cut into both faces where the caps run, lofted through the part's own
 * stations (with its bumps and winglet frame). skinFace, tSkins are lengths; capW is the cap width
 * as a fraction of chord; capF the caps' share of the core thickness. Returns the body (mirrored
 * and joined if the part is), or undefined when no station has room for a core.
 */
function moldCoreBody(context is Context, id is Id, m is map, mini is map, base is Vector, skinFace is ValueWithUnits, capW is number, capF is number, tSkins is ValueWithUnits, nStations is number, tipBias is number, ventLen is ValueWithUnits, e0 is number)
{
    const h = m.span / 2 * meter;
    var etas = [];
    const N = max(nStations, 24);
    for (var i = 0; i <= N; i += 1)
        etas = append(etas, 1 - (1 - i / N) ^ tipBias);
    if (m.bumpOn == 1)
    {
        var yb = m.bumpFrom * h;
        const yEnd = min(m.bumpTo * h, h);
        while (yb <= yEnd)
        {
            etas = append(etas, yb / h);
            yb += m.bumpPitch * meter / 6;
        }
    }
    if (m.wingletOn == 1)
    {
        const arcEta = m.wingletR * meter * m.wingletAngle / h;
        for (var k = 0; k <= 4; k += 1)
            etas = append(etas, min(m.wingletEta + arcEta * k / 4, 1));
    }
    etas = sort(etas, function(a, b) { return a - b; });
    var uniq = [];
    for (var e in etas)
    {
        const ec = min(max(e, 0), 0.995);        // from the root plane itself, so the mirrored halves meet and join (build 160: 0.002 left a 1.9 mm gap, two core bodies)
        if (size(uniq) == 0 || ec - uniq[size(uniq) - 1] > 1e-3)
            uniq = append(uniq, ec);
    }
    if (e0 > 0)
    {
        // the core starts clear of the socket: its first station at e0, nothing inboard (build 176)
        var outer = [e0];
        for (var e in uniq)
            if (e > e0 + 1e-3)
                outer = append(outer, e);
        uniq = outer;
    }
    var profiles = [];
    var sketches = [];
    var lastCore;                                                            // the outermost core outline and its frame, for the tip vent
    var lastOrigin;
    var lastNormal;
    for (var i = 0; i < size(uniq); i += 1)
    {
        const eta = uniq[i];
        const chord0 = m.c0 * meter * chordFactor(m, eta);
        const tailAdd = m.c0 * meter * tailFactor(m, eta);
        const thick0 = (m.rootT + (m.tipT - m.rootT) * eta ^ m.thicknessExp) * (chord0 - tailAdd) / chord0;
        const twist = (m.incidence - m.washout * eta ^ m.washoutExp) * radian;
        const chordBase = (chord0 - tailAdd) / capPlanFactor(m, eta);
        const alignShift = (m.pivotFrac - m.align) * (chordBase - m.c0 * meter) + m.pivotFrac * tailAdd + (0.5 - m.pivotFrac) * (chordBase - (chord0 - tailAdd));
        const bump = bumpOffset(m, eta, h);
        const chord = chord0 + bump;
        var thick = thick0 * chord0 / chord;
        if (m.capOn == 1 && m.capLength > 0)
        {
            // the tip cap's thickness law, as buildFoil applies it
            const capStartEta = 1 - m.capLength / (m.span / 2);
            if (eta > capStartEta)
            {
                const d = min((eta - capStartEta) / (1 - capStartEta), 1);
                const eT = m.capEndT == undefined ? m.capEnd : m.capEndT;     // build 239: the thickness's own end fraction
                thick = thick * (eT + (1 - eT) * sqrt(max(1 - d * d, 0))) / (m.planRound == 1 ? capPlanFactor(m, eta) : 1);
            }
        }
        const xOff = m.sweepTip * meter * eta ^ m.sweepExp + alignShift - (1 - m.pivotFrac) * bump;
        const wf = wingletFrame(m, eta);
        const teFrac = min(m.teThick * meter, 0.03 * chord) / chord;
        const sec = buildSectionAt(mini, thick, teFrac, 40, sectionWeightAt(mini, eta));
        const placed = placeSection(sec, chord, m.pivotFrac, cos(twist), sin(twist));
        const capT = capF * max(thick * chord - tSkins, 0 * meter) / 2;      // one cap's thickness here
        const core = coreOutline(placed, skinFace, capW * chord, capT);
        if (core == undefined)
            break;                                                           // too thin from here out: the core ends
        const origin = base + vector(xOff, wf.y, wf.z);
        const nrm = vector(0, -cos(wf.phi), -sin(wf.phi));
        profiles = append(profiles, coreSketch(context, id + ("core" ~ i), origin, nrm, core));
        sketches = append(sketches, qCreatedBy(id + ("core" ~ i), EntityType.BODY));
        lastCore = core;
        lastOrigin = origin;
        lastNormal = nrm;
    }
    if (size(profiles) < 2)
        return undefined;
    opLoft(context, id + "coreLoft", { "profileSubqueries" : profiles });
    // tip vent (user: leave the tips open so a poured foam can expand out): the outermost core
    // section carried straight out along +Y past the block's side, cut with the cavity and then
    // removed, so the cavity is a channel open at the tip. Straight in Y, not up a winglet, so it
    // stays with the parting's flat continuation beyond the tip. ventLen 0 = no vent (printed core)
    const withVent = ventLen > 0 * meter;
    var ventQ = qNothing();
    if (withVent)
    {
        const v0 = coreSketch(context, id + "ventA", lastOrigin, lastNormal, lastCore);
        const v1 = coreSketch(context, id + "ventB", lastOrigin + vector(0 * meter, ventLen, 0 * meter), lastNormal, lastCore);
        opLoft(context, id + "coreVent", { "profileSubqueries" : [v0, v1] });
        sketches = append(sketches, qCreatedBy(id + "ventA", EntityType.BODY));
        sketches = append(sketches, qCreatedBy(id + "ventB", EntityType.BODY));
        ventQ = qCreatedBy(id + "coreVent", EntityType.BODY);
    }
    opDeleteBodies(context, id + "coreSketches", { "entities" : qUnion(sketches) });
    if (m.mirror == 1)
    {
        opPattern(context, id + "coreMirror", {
                    "entities" : qCreatedBy(id + "coreLoft", EntityType.BODY),
                    "transforms" : [mirrorAcross(plane(WORLD_ORIGIN, Y_DIRECTION))],
                    "instanceNames" : ["left"]
                });
        if (withVent)
        {
            opPattern(context, id + "ventMirror", {
                        "entities" : qCreatedBy(id + "coreVent", EntityType.BODY),
                        "transforms" : [mirrorAcross(plane(WORLD_ORIGIN, Y_DIRECTION))],
                        "instanceNames" : ["left"]
                    });
            ventQ = qUnion([qCreatedBy(id + "coreVent", EntityType.BODY), qCreatedBy(id + "ventMirror", EntityType.BODY)]);
        }
        if (e0 <= 0)
            opBoolean(context, id + "coreJoin", {
                        "tools" : qUnion([qCreatedBy(id + "coreLoft", EntityType.BODY), qCreatedBy(id + "coreMirror", EntityType.BODY)]),
                        "operationType" : BooleanOperationType.UNION
                    });   // with a start eta the two halves never meet: they stay two bodies
    }
    // the core is whatever solid this feature has made so far that is not a vent (a union's result
    // is not reliably "created by" either of its inputs); tag both so later queries stay valid
    const coreQ = qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), ventQ);
    setAttribute(context, { "entities" : coreQ, "name" : "foilCoreBody", "attribute" : 1 });
    if (withVent)
        setAttribute(context, { "entities" : ventQ, "name" : "foilCoreVent", "attribute" : 1 });   // an empty query throws (printed core, build 161)
    return { "body" : qHasAttribute("foilCoreBody"), "vent" : withVent ? qHasAttribute("foilCoreVent") : undefined };
}

/** One core section as a closed sketch region on the plane (origin, normal, X): upper spline, nose line, lower spline, tail line. */
function coreSketch(context is Context, sid is Id, origin is Vector, nrm is Vector, core is map) returns Query
{
    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(origin, nrm, X_DIRECTION) });
    skFitSpline(sk, "upper", { "points" : core.upper });
    skLineSegment(sk, "nose", { "start" : core.upper[size(core.upper) - 1], "end" : core.lower[0] });
    skFitSpline(sk, "lower", { "points" : core.lower });
    skLineSegment(sk, "tail", { "start" : core.lower[size(core.lower) - 1], "end" : core.upper[0] });
    skSolve(sk);
    return qSketchRegion(sid);
}

/**
 * Core outline of one placed section: the closed loop offset inward along its normals by skin,
 * re-read as upper and lower curves of x, clipped where they come within 0.6 mm of each other
 * (a blunt nose and tail), with each face lowered by capT over a band bandW wide centred on the
 * thickest point (the UD cap's groove, ramped over a tenth of the band at each edge). Returns
 * { upper : TE -> nose, lower : nose -> TE } as sketch points, or undefined if nothing is left.
 */
function coreOutline(placed is array, skin is ValueWithUnits, bandW is ValueWithUnits, capT is ValueWithUnits)
{
    const n = size(placed);
    var area2 = 0 * meter * meter;
    for (var i = 0; i < n; i += 1)
    {
        const j = (i + 1) % n;
        area2 += placed[i][0] * placed[j][1] - placed[j][0] * placed[i][1];
    }
    const sgn = area2 > 0 * meter * meter ? 1 : -1;                          // CCW: the left normal points in
    var off = [];
    for (var i = 0; i < n; i += 1)
    {
        // one-sided tangents at the two trailing-edge corners: a tangent across the TE face pushed
        // the corner point back along the chord and the face walk below broke on it
        const a = i == 0 ? placed[0] : placed[i - 1];
        const b = i == n - 1 ? placed[n - 1] : placed[i + 1];
        var tx = (b[0] - a[0]) / meter;
        var ty = (b[1] - a[1]) / meter;
        const len = sqrt(tx * tx + ty * ty);
        if (len < 1e-12)
            continue;
        tx = tx / len;
        ty = ty / len;
        off = append(off, vector(placed[i][0] - sgn * ty * skin, placed[i][1] + sgn * tx * skin));
    }
    // the loop runs upper TE -> LE -> lower TE; split at the original nose, then keep the part of
    // each offset curve that is still monotonic in x from the TE end (the offset folds at the nose)
    const nLE = (n + 1) / 2 - 1;
    var up = [];                                                              // TE -> nose, x decreasing
    for (var i = 0; i <= nLE && i < size(off); i += 1)
    {
        if (size(up) > 0 && off[i][0] >= up[size(up) - 1][0])
            break;
        up = append(up, off[i]);
    }
    var lo = [];                                                              // TE -> nose too (walk the lower curve backwards)
    for (var i = size(off) - 1; i >= nLE; i -= 1)
    {
        if (size(lo) > 0 && off[i][0] >= lo[size(lo) - 1][0])
            break;
        lo = append(lo, off[i]);
    }
    if (size(up) < 3 || size(lo) < 3)
        return undefined;
    const xTail = min(up[0][0], lo[0][0]);
    const xNose0 = max(up[size(up) - 1][0], lo[size(lo) - 1][0]);
    if (xTail - xNose0 < 2 * millimeter)
        return undefined;
    const gap = 0.6 * millimeter;
    // fine scan for where the faces close up at the tail and at the nose
    const nScan = 120;
    var xA;
    var xB;
    for (var k = 0; k <= nScan; k += 1)
    {
        const x = xTail - (xTail - xNose0) * k / nScan;
        const t = coreYAt(up, x) - coreYAt(lo, x);
        if (t >= gap)
        {
            if (xA == undefined)
                xA = x;
            xB = x;
        }
    }
    if (xA == undefined || xA - xB < 2 * millimeter)
        return undefined;
    // thickest point of the core, for the cap band
    var xT = xA;
    var tMax = 0 * meter;
    for (var k = 0; k <= 60; k += 1)
    {
        const x = xA - (xA - xB) * k / 60;
        const t = coreYAt(up, x) - coreYAt(lo, x);
        if (t > tMax)
        {
            tMax = t;
            xT = x;
        }
    }
    var upper = [];
    var lower = [];
    const nS = 32;
    for (var k = 0; k <= nS; k += 1)
    {
        const x = xA - (xA - xB) * 0.5 * (1 - cos((PI * k / nS) * radian));   // TE -> nose, cosine packed at both ends
        var yu = coreYAt(up, x);
        var yl = coreYAt(lo, x);
        const dx = abs(x - xT);
        if (capT > 0 * meter && dx < bandW / 2)
        {
            const edge = 0.1 * bandW / 2;
            const ramp = dx > bandW / 2 - edge ? (bandW / 2 - dx) / edge : 1;
            const cut = min(capT * ramp, (yu - yl - gap) / 2);
            yu = yu - cut;
            yl = yl + cut;
        }
        upper = append(upper, vector(x, yu));
        lower = append(lower, vector(x, yl));
    }
    var lowerFwd = [];                                                        // nose -> TE
    for (var k = size(lower) - 1; k >= 0; k -= 1)
        lowerFwd = append(lowerFwd, lower[k]);
    return { "upper" : upper, "lower" : lowerFwd };
}

/** y of a polyline (points with x decreasing) at x, linear, clamped at its ends. */
function coreYAt(pts is array, x is ValueWithUnits) returns ValueWithUnits
{
    const last = size(pts) - 1;
    if (x >= pts[0][0])
        return pts[0][1];
    if (x <= pts[last][0])
        return pts[last][1];
    for (var i = 0; i < last; i += 1)
    {
        if (x <= pts[i][0] && x >= pts[i + 1][0] && pts[i][0] > pts[i + 1][0])
        {
            const t = (pts[i][0] - x) / (pts[i][0] - pts[i + 1][0]);
            return pts[i][1] + t * (pts[i + 1][1] - pts[i][1]);
        }
    }
    return pts[last][1];
}

function profileFromName(name is string) returns FoilProfile
{
    if (name == "E817") return FoilProfile.E817;
    if (name == "E818") return FoilProfile.E818;
    if (name == "NACA63412") return FoilProfile.NACA63412;
    if (name == "CLARKY") return FoilProfile.CLARKY;
    if (name == "MRC16") return FoilProfile.MRC16;
    if (name == "MH18") return FoilProfile.MH18;
    if (name == "H105") return FoilProfile.H105;
    return FoilProfile.NACA4;
}

function moldInputLog(definition is map) returns string
{
    return "MOLD_INPUTS: toolVersion=" ~ FOIL_MOLD_VERSION
        ~ "; moldSource=" ~ (definition.moldSource == MoldSource.WING ? "WING" : (definition.moldSource == MoldSource.MAST ? "MAST" : (definition.moldSource == MoldSource.FUSELAGE ? "FUSELAGE" : "STAB")))
        ~ "; detail=" ~ (definition.detail != undefined && definition.detail == MoldDetail.PREVIEW ? "PREVIEW" : "PRINT") ~ "; partsGroup=" ~ (definition.partsGroup == PartsGroup.CLOSED ? "CLOSED" : (definition.partsGroup == PartsGroup.OPEN ? "OPEN" : "OFF")) ~ "; splitStations=" ~ definition.splitStations ~ "; tipBias=" ~ fmt(definition.tipBias, 2) ~ "; templatesOn=" ~ (definition.templatesOn ? "1" : "0") ~ "; udModulus=" ~ fmt(definition.udModulus, 0) ~ "; wovenModulus=" ~ fmt(definition.wovenModulus, 0) ~ "; towModulus=" ~ fmt(definition.towModulus, 0) ~ "; mastSideG=" ~ fmt(definition.mastSideG, 2)
        ~ "; flangeWidth_mm=" ~ fmt(definition.flangeWidth / millimeter, 1)
        ~ "; baseThick_mm=" ~ fmt(definition.baseThick / millimeter, 1)
        ~ "; plugOn=" ~ (definition.plugOn ? "1" : "0") ~ "; plugExt_mm=" ~ fmt(definition.plugExt / millimeter, 1)
        ~ "; conesOn=" ~ (definition.conesOn == true ? "1" : "0")
        ~ (definition.conesOn == true ? "; coneDia_mm=" ~ fmt(definition.coneDia / millimeter, 2) ~ "; coneTaper_deg=" ~ fmt(definition.coneTaper / degree, 1) ~ "; coneWeb_mm=" ~ fmt(definition.coneWeb / millimeter, 2) : "")
        ~ "; closing=" ~ (definition.closing == MoldClosing.BAG ? "BAG" : "CLAMPS")
        ~ (definition.closing == MoldClosing.BAG ? "; bagVac_kPa=" ~ fmt(definition.bagVac, 0) ~ "; ventOn=" ~ (definition.ventOn ? "1" : "0") ~ "; edgeRound_mm=" ~ fmt(definition.edgeRound / millimeter, 1) : "")
        ~ "; grooveOn=" ~ (definition.grooveOn ? "1" : "0")
        ~ (definition.grooveOn ? "; landWidth_mm=" ~ fmt(definition.landWidth / millimeter, 1) ~ "; grooveWidth_mm=" ~ fmt(definition.grooveWidth / millimeter, 1) ~ "; grooveDepth_mm=" ~ fmt(definition.grooveDepth / millimeter, 2) ~ "; landGap_mm=" ~ fmt((definition.landGap == undefined ? 0 * meter : definition.landGap) / millimeter, 2) : "")
        ~ "; printerX_mm=" ~ fmt(definition.printerX / millimeter, 0)
        ~ "; printerY_mm=" ~ fmt(definition.printerY / millimeter, 0)
        ~ "; printerZ_mm=" ~ fmt(definition.printerZ / millimeter, 0)
        ~ "; tileMargin_mm=" ~ fmt(definition.tileMargin / millimeter, 1)
        ~ "; staggerJoints=" ~ (definition.staggerJoints ? "1" : "0")
        ~ "; keyStyle=" ~ (definition.keyStyle == MoldKeyStyle.PRINTED ? "PRINTED" : "DOWEL")
        ~ (definition.keyStyle == MoldKeyStyle.PRINTED ? "; keyHeight_mm=" ~ fmt(definition.keyHeight / millimeter, 1) ~ "; keyDraft_deg=" ~ fmt(definition.keyDraft / degree, 1) : "")
        ~ "; pinDia_mm=" ~ (definition.pinDia != undefined ? fmt(definition.pinDia / millimeter, 2) : "-")
        ~ (definition.keyStyle == MoldKeyStyle.DOWEL ? "; pinLen_mm=" ~ (definition.pinLen != undefined ? fmt(definition.pinLen / millimeter, 1) : "-") : "")
        ~ "; pinFit_mm=" ~ fmt(definition.pinFit / millimeter, 2)
        ~ "; keysOn=" ~ (definition.keysOn ? "1" : "0")
        ~ "; keyDia_mm=" ~ fmt(definition.keyDia / millimeter, 2)
        ~ (definition.keyStyle == MoldKeyStyle.DOWEL ? "; keyLen_mm=" ~ fmt(definition.keyLen / millimeter, 1) : "")
        ~ "; skinPlies=" ~ fmt(definition.skinPlies, 0)
        ~ "; skinGsm=" ~ fmt(definition.skinGsm, 0)
        ~ "; udGsm=" ~ fmt(definition.udGsm, 0)
        ~ "; capWidthPct=" ~ fmt(definition.capWidthPct, 1)
        ~ "; capThickPct=" ~ fmt(definition.capThickPct, 1)
        ~ "; moldOf=" ~ (definition.moldOf == MoldOf.CORE ? "CORE" : "PART")
        ~ (definition.moldOf == MoldOf.CORE ? "; coreMake=" ~ (definition.coreMake != undefined && definition.coreMake == CoreMake.MILLED ? "MILLED" : "MOLDED") : "")
        ~ (definition.moldOf == MoldOf.CORE && definition.coreMake != undefined && definition.coreMake == CoreMake.MILLED ? "; sheetThick_mm=" ~ fmt(definition.sheetThick / millimeter, 1) ~ "; coreTabsOn=" ~ (definition.coreTabsOn != false ? "1" : "0") ~ (definition.coreTabsOn != false ? "; coreTabsPerEdge=" ~ (definition.coreTabsPerEdge == undefined ? 2 : definition.coreTabsPerEdge) ~ "; coreTabLen_mm=" ~ fmt(definition.coreTabLen / millimeter, 1) ~ "; coreTabIn_mm=" ~ fmt(definition.coreTabIn / millimeter, 1) ~ "; coreTabWide_mm=" ~ fmt(definition.coreTabWide / millimeter, 1) ~ "; coreTabThick_mm=" ~ fmt(definition.coreTabThick / millimeter, 1) : "") : "")
        ~ "; core=" ~ (definition.coreType == CoreType.FOAM ? "FOAM" : (definition.coreType == CoreType.SOLID ? "SOLID" : (definition.coreType == CoreType.PRINTED ? "PRINTED" : "TOW")))
        ~ ((definition.coreType == CoreType.FOAM || definition.coreType == CoreType.PRINTED) && definition.moldSource == MoldSource.FUSELAGE ? "; fusCoreFrom_mm=" ~ fmt(definition.fusCoreFrom / millimeter, 1) ~ "; fusCoreGap_mm=" ~ fmt(definition.fusCoreGap / millimeter, 1) ~ "; fusCapStress=" ~ fmt(definition.fusCapStress, 0) : "")
        ~ (definition.coreType == CoreType.FOAM || definition.coreType == CoreType.PRINTED ? "; coreDensity=" ~ fmt(definition.coreDensity, 0) ~ "; coreModulus=" ~ fmt(definition.coreModulus, 2) ~ "; coreShear=" ~ fmt(definition.coreShear == undefined ? 0 : definition.coreShear, 2) : "")
        ~ (definition.coreType == CoreType.TOW ? "; towTex=" ~ fmt(definition.towTex, 0) : "")
        ~ (definition.coreType == CoreType.FOAM || definition.coreType == CoreType.PRINTED ? "; coreClearOn=" ~ (definition.coreClearOn ? "1" : "0") ~ "; coreClear_mm=" ~ fmt(definition.coreClear / millimeter, 1) : "")
        ~ "; fibreVolPct=" ~ fmt(definition.fibreVolPct, 1)
        ~ "; overchargePct=" ~ fmt(definition.overchargePct, 1)
        ~ "; clothWastePct=" ~ fmt(definition.clothWastePct, 1)
        ~ "; resinWastePct=" ~ fmt(definition.resinWastePct, 1)
        ~ "; capRunOut_mm=" ~ fmt(definition.capRunOut / millimeter, 1) ~ "; tabPlies=" ~ definition.tabPlies ~ "; tabLength_mm=" ~ fmt(definition.tabLength / millimeter, 1)
        ~ "; shearAllow=" ~ fmt(definition.shearAllow, 1)
        ~ "; pryOn=" ~ (definition.pryOn == true ? "1; pryLength_mm=" ~ fmt(definition.pryLength / millimeter, 1) ~ "; pryDepth_mm=" ~ fmt(definition.pryDepth / millimeter, 1) ~ "; prySpacing_mm=" ~ fmt(definition.prySpacing / millimeter, 0) : "0")
        ~ "; ejector=" ~ (definition.ejector == undefined ? "OFF" : (definition.ejector == MoldEjector.PLUG ? "PLUG; ejectorDia_mm=" ~ fmt(definition.ejectorDia / millimeter, 1) ~ "; ejectorFit_mm=" ~ fmt(definition.ejectorFit / millimeter, 2) : (definition.ejector == MoldEjector.DOWEL ? "DOWEL; ejectorDia_mm=" ~ fmt(definition.ejectorDia / millimeter, 1) : "OFF")))
        ~ "; tileJoint=" ~ (definition.tileJoint != undefined && definition.tileJoint == TileJoint.PUZZLE ? "PUZZLE" : "DOWELS")
        ~ (definition.tileJoint != undefined && definition.tileJoint == TileJoint.PUZZLE ? "; inlayLen_mm=" ~ fmt(definition.inlayLen / millimeter, 1) ~ "; inlayWidth_mm=" ~ fmt(definition.inlayWidth / millimeter, 1)
            ~ "; inlayWaist_mm=" ~ fmt(definition.inlayWaist / millimeter, 1) ~ "; inlayDepth_mm=" ~ fmt(definition.inlayDepth / millimeter, 1) ~ "; inlayCutter_mm=" ~ fmt(definition.inlayCutter / millimeter, 1)
            ~ "; inlayGap_mm=" ~ fmt(definition.inlayGap / millimeter, 2)
            ~ (definition.inlayFlush != undefined ? "; inlayFlush_mm=" ~ fmt(definition.inlayFlush / millimeter, 2) : "")
            ~ (definition.inlaySand != undefined ? "; inlaySand_mm=" ~ fmt(definition.inlaySand / millimeter, 1) : "") : "");
}

annotation { "Feature Type Name" : "Foil mast",
             "Feature Type Description" : "Hydrofoil mast from the fuselage to a bolted board plate: symmetric sections, chord taper on the leading or trailing edge, thickening toward the plate, a root fillet into the plate, bolts chosen by size, and an optional motor pod with a placeholder motor cavity that the Foil mold turns into a plug. Positioned from the wing's root pivot." }
export const foilMast = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Group Name" : "Mast", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Height",
                         "Description" : "Mast length from its base (top of the fuselage) to the underside of the board plate. Limits 300-1300 mm. Typical 600-1000 mm; eFoil masts often 650-850 mm. Longer = more clearance in chop, more drag and more bending at the base." }
            isLength(definition.mastHeight, { (millimeter) : [300, 750, 1300] } as LengthBoundSpec);

            annotation { "Name" : "Width",
                         "Description" : "Mast chord (fore-aft width). Limits 60-200 mm. Typical 100-140 mm. Wider = stiffer in bending and torsion, more wetted area and drag." }
            isLength(definition.mastWidth, { (millimeter) : [60, 120, 200] } as LengthBoundSpec);

            annotation { "Name" : "Thickness",
                         "Description" : "Maximum mast thickness (side to side). Limits 6-40 mm, and 4-25 % of Width. Typical 13-19 mm (about 11-15 % of chord). Thinner = less drag and spray; thicker = stiffer and stronger. The notice reports the resulting t/c." }
            isLength(definition.mastThick, { (millimeter) : [6, 16, 40] } as LengthBoundSpec);

            annotation { "Name" : "TE thickness",
                         "Description" : "Trailing edge thickness of the mast section. Limits 0.1-3 mm, and at most 3 % of Width. Typical 0.6-1.0 mm for wet-laid carbon in printed molds." }
            isLength(definition.mastTe, { (millimeter) : [0.1, 0.8, 3] } as LengthBoundSpec);

            annotation { "Name" : "Points/surface",
                         "Description" : "Limits 10-120. Typical 30-40. Cosine-spaced points on each side of the symmetric NACA 00xx mast section." }
            isInteger(definition.mastPoints, { (unitless) : [10, 36, 120] } as IntegerBoundSpec);
        }

        annotation { "Group Name" : "Taper and top", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Top chord",
                         "Description" : "Chord of the mast at the top, where it meets the plate; Width is the chord at the base. Limits 30-400 mm. Typical equal to Width (no taper), or 10-30 % more for stiffness where the bending moment peaks, or less for a slimmer mast where it pierces the surface." }
            isLength(definition.topChord, { (millimeter) : [30, 120, 400] } as LengthBoundSpec);

            annotation { "Name" : "Taper side",
                         "Description" : "Where the chord change goes. Symmetric: both edges move equally about the mid-chord. Straight leading edge: the leading edge stays vertical and the trailing edge moves. Straight trailing edge: the trailing edge stays vertical and the leading edge moves. Only matters when Top chord differs from Width." }
            definition.mastTaper is MastTaper;

            annotation { "Name" : "Top thick",
                         "Description" : "Section thickness at the top of the mast; Thickness is the value at the base. Limits 4-40 mm, and 4-25 % of the local chord. Typical equal to Thickness, or 20-50 % more to carry the bending and torsion where the mast meets the plate. The section stays a NACA 00xx, scaled." }
            isLength(definition.topThick, { (millimeter) : [4, 16, 40] } as LengthBoundSpec);

            annotation { "Name" : "Thicken from %",
                         "Description" : "Height, as % of Height from the base, where the thickness starts to grow from Thickness toward Top thick, following a smooth S-curve to the top. Limits 0-95 %. Typical 60-80 %: the lower mast keeps its drag-optimised section and only the loaded top end thickens." }
            isReal(definition.thickenFrom, { (unitless) : [0, 70, 95] } as RealBoundSpec);

            annotation { "Name" : "Root fillet",
                         "Description" : "Fillet radius where the mast meets the plate's underside, all round the section. Limits 0-30 mm. Typical 8-15 mm; 0 = sharp corner. Gives the UD caps and the tab plies a radius to turn through into the plate instead of a 90 deg fold, and spreads the peel at the corner where the side-load moment peaks. Held to 2 mm less than the room between the section and the plate edge. The fillet runs round the section's surface and stops at the trailing-edge line (a 0.8 mm edge cannot carry it), leaving a notch of TE thickness there; the console's MAST_FILLET line reports the seam and the attempt used." }
            isLength(definition.rootFillet, { (millimeter) : [0, 10, 30] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Position", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Mast X",
                         "Description" : "Mast leading edge position along X relative to the wing root pivot (world origin), positive = aft. Limits -300 to +300 mm. Typical -40 to 0 mm, i.e. the mast sits over the forward part of the wing. With a Round or Square socket on the wing it must stand behind the socket's rear face, on the tube or bar; the notice warns when it is ahead of it. This is where the rider's weight enters the foil, so compare it with the Foil performance trim CG." }
            isLength(definition.mastX, { (millimeter) : [-300, -20, 300] } as LengthBoundSpec);

            annotation { "Name" : "Base height",
                         "Description" : "Z of the mast's bottom end, measured from the wing root pivot. Limits -150 to +150 mm; negative is normal when the mast sits in a Foil fuselage pocket, whose floor can be below the pivot. Typical: the value the Foil fuselage warning asks for, so the mast sits on the pocket floor." }
            isLength(definition.baseHeight, { (millimeter) : [-150, 30, 150] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Motor pod", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Motor pod", "Default" : false,
                         "Description" : "Adds a streamlined motor pod on the mast (eFoil). Off for pump, SUP, surf, wing, wind and kite foils." }
            definition.podOn is boolean;

            if (definition.podOn)
            {
                annotation { "Name" : "Motor dia",
                             "Description" : "Pod outside diameter (motor can plus housing). Limits 30-150 mm. Typical 60-90 mm for eFoil motors." }
                isLength(definition.podDia, { (millimeter) : [30, 70, 150] } as LengthBoundSpec);

                annotation { "Name" : "Pod height",
                             "Description" : "Height of the pod centreline above the mast base. Limits 0-1200 mm, and the pod must stay within the mast height. Typical 100-250 mm; lower keeps the prop deeper, higher keeps it away from the wing." }
                isLength(definition.podHeight, { (millimeter) : [0, 150, 1200] } as LengthBoundSpec);

                annotation { "Name" : "Nose start %",
                             "Description" : "Where the blend starts along the mast chord, as % from the mast leading edge. Limits 0-80 %. Typical 2-10 %: an early start gives the longest, gentlest blend and least drag. The first section matches the mast's own thickness there, so the pod grows out of the mast faces and never protrudes ahead of the mast." }
                isReal(definition.podNoseStartPct, { (unitless) : [0, 5, 80] } as RealBoundSpec);

                annotation { "Name" : "Fairing length",
                             "Description" : "Length of the blend from the mast section to the full motor diameter. Limits 20-400 mm. Typical 2-3 x Motor dia; longer means a gentler flank angle and lower drag. Must fit between the nose tip and the rear face." }
                isLength(definition.podFairLength, { (millimeter) : [20, 150, 400] } as LengthBoundSpec);

                annotation { "Name" : "Blend height %",
                             "Description" : "Height of the first blend section as % of the motor diameter. Limits 30-100 %. Typical 70-100 %. 100 % = the pod starts at full motor height and grows only in width out of the mast faces; lower also tapers it vertically for a softer entry." }
                isReal(definition.podBlendHeightPct, { (unitless) : [30, 100, 100] } as RealBoundSpec);

                annotation { "Name" : "Aft extension",
                             "Description" : "How far the pod extends behind the mast trailing edge, ending in a flat rear face for modelling the motor mount by hand. Limits 0-400 mm. Typical 60-150 mm, enough to clear the mast for the motor and prop." }
                isLength(definition.podAft, { (millimeter) : [0, 100, 400] } as LengthBoundSpec);

                annotation { "Name" : "Cavity dia",
                             "Description" : "Diameter of the placeholder motor cavity in the pod's rear face. Limits 5-140 mm, and at most Motor dia minus 4 mm (2 mm of pod wall each side). Typical 20 mm as a placeholder, a small locating pocket to open out to the motor by hand. The Foil mold molds the pod's outside with the mast and makes a plug of this cavity, pulled after cure." }
                isLength(definition.cavDia, { (millimeter) : [5, 20, 140] } as LengthBoundSpec);

                annotation { "Name" : "Cavity length",
                             "Description" : "Depth of the placeholder cavity from the pod's flat rear face forward. Limits 2-400 mm; shortened if it would run into the nose blend. Typical 10 mm as a placeholder, then the motor can length plus 5 mm once it is chosen." }
                isLength(definition.cavLength, { (millimeter) : [2, 10, 400] } as LengthBoundSpec);

                annotation { "Name" : "Pod tilt",
                             "Description" : "Rotation of the whole pod about its centre, nose-down positive. Limits -15 to 15 deg. Typical 5-8 deg for an eFoil: the board rides nose-up at low speed, so a nose-down pod keeps the prop nearer the flow at take-off and its thrust's downward component behind the CG lifts the nose against the thrust-height couple. 0 = axis parallel to the fuselage. Foil performance reports the thrust angle to the flow at every speed." }
                isAngle(definition.podTilt, { (degree) : [-15, 0, 15] } as AngleBoundSpec);
            }
        }

        annotation { "Group Name" : "Plate", "Collapsed By Default" : true }
        {
            annotation { "Name" : "Plate length",
                         "Description" : "Board plate length along X. Limits 80-300 mm. Typical 150-180 mm." }
            isLength(definition.plateLength, { (millimeter) : [80, 165, 300] } as LengthBoundSpec);

            annotation { "Name" : "Plate width",
                         "Description" : "Board plate width across Y; must exceed Track spacing plus a bolt diameter. Limits 60-200 mm. Typical 110-130 mm." }
            isLength(definition.plateWidth, { (millimeter) : [60, 120, 200] } as LengthBoundSpec);

            annotation { "Name" : "Plate thick",
                         "Description" : "Board plate thickness. Limits 4-30 mm. Typical 8-12 mm; must be deeper than the countersink." }
            isLength(definition.plateThick, { (millimeter) : [4, 10, 30] } as LengthBoundSpec);

            annotation { "Name" : "Track spacing",
                         "Description" : "Distance between the two rows of bolts (the board's two tracks). Limits 30-180 mm. Typical 90 mm, the common twin-track spacing; check your board." }
            isLength(definition.trackSpacing, { (millimeter) : [30, 90, 180] } as LengthBoundSpec);

            annotation { "Name" : "Bolts/row",
                         "Description" : "Bolts in each of the two rows. Limits 1-4. Typical 2." }
            isInteger(definition.boltsPerRow, { (unitless) : [1, 2, 4] } as IntegerBoundSpec);

            annotation { "Name" : "Bolt pitch",
                         "Description" : "Spacing between bolts along each row, centred on the plate. Limits 10-200 mm. Typical 40-60 mm. Ignored with one bolt per row." }
            isLength(definition.boltPitch, { (millimeter) : [10, 40, 200] } as LengthBoundSpec);

            annotation { "Name" : "Bolt", "Default" : "M8",
                         "Description" : "The track bolts. Sets the plate's clearance hole (M6 6.5, M8 8.5 mm: 0.1 mm looser than the stab's close fit, since four holes must line up with the tracks) and the countersink. Typical M8 (most boards), M6 on some. Custom hole sizes: type the hole below." }
            definition.plateBolt is BoltSize;

            if (definition.plateBolt == BoltSize.CUSTOM)
            {
                annotation { "Name" : "Bolt dia",
                             "Description" : "Bolt clearance hole diameter (Custom only). Limits 3-12 mm. Typical 8.5 mm for M8, 6.5 mm for M6." }
                isLength(definition.boltDia, { (millimeter) : [3, 8.5, 12] } as LengthBoundSpec);
            }

            annotation { "Name" : "Countersink", "Default" : true,
                         "Description" : "90 deg countersink for flat-head bolts on the plate's underside (the mast side), to the ISO 10642 head diameter of the chosen Bolt (M6 13.4, M8 17.9 mm; Custom: twice the hole). Bolts go in from below, through the plate, into the board's track nuts, so the heads sit flush with the underside." }
            definition.countersink is boolean;
        }

        annotation { "Name" : "Log inputs", "Default" : true,
                     "Description" : "Prints every parameter on this feature to the FeatureScript console as one line, so the whole set can be pasted elsewhere (e.g. back to an AI assistant)." }
        definition.logInputs is boolean;
    }
    {
        setVariable(context, "foilMastLog", "");
        setVariable(context, "foilMastNotice", "");
        if (definition.logInputs)
            foilPrint(context, "foilMastLog", mastInputLog(definition));

        // ---------------- validation ----------------
        const c = definition.mastWidth;
        const tc = definition.mastThick / c;
        if (tc < 0.04 || tc > 0.25)
            throw regenError("Mast thickness must be 4-25% of Width (currently " ~ fmt(tc * 100, 1) ~ "%)", ["mastThick", "mastWidth"]);
        const cTop = definition.topChord;
        const tTop = definition.topThick;
        if (tTop / cTop < 0.04 || tTop / cTop > 0.25)
            throw regenError("Top thick must be 4-25% of Top chord (currently " ~ fmt(tTop / cTop * 100, 1) ~ "%)", ["topThick", "topChord"]);
        if (definition.mastTe > 0.03 * c)
            throw regenError("Mast TE thickness exceeds 3% of Width", ["mastTe"]);
        const dBolt = definition.plateBolt == BoltSize.CUSTOM ? definition.boltDia : (boltDims(definition.plateBolt).clear + 0.1) * millimeter;
        const headR = boltHead(definition.plateBolt, dBolt) / 2;   // 90 deg countersunk head, ISO 10642 dk (Custom: twice the hole)
        const cskDepth = headR - dBolt / 2;
        if (definition.countersink && cskDepth >= definition.plateThick)
            throw regenError("Countersink is deeper than the plate - use a thicker plate or a smaller Bolt", ["plateThick", "plateBolt"]);
        if (definition.plateWidth < definition.trackSpacing + 2 * headR)
            throw regenError("Plate width must exceed Track spacing plus a bolt head", ["plateWidth", "trackSpacing"]);
        if (definition.trackSpacing / 2 - headR < max(definition.mastThick, definition.topThick) / 2 + 1 * millimeter)
            throw regenError("Bolt heads under the plate would hit the mast - increase Track spacing or choose a smaller Bolt", ["trackSpacing", "plateBolt"]);
        const rowSpan = (definition.boltsPerRow - 1) * definition.boltPitch;
        if (definition.plateLength < rowSpan + 2 * headR)
            throw regenError("Plate length is too short for the bolt row", ["plateLength", "boltPitch", "boltsPerRow"]);

        const z0 = definition.baseHeight;
        const z1 = z0 + definition.mastHeight;
        const x0 = definition.mastX;
        var sketchBodies = [];

        // the wing's socket under the mast foot (build 233): with a Round or Square socket the tube or
        // bar enters at the nacelle's rear face, so a foot ahead of it stands on the nacelle. Foil
        // fuselage warns too; this covers a home-built bar with no Foil fuselage. Read, never set
        var sockNote = "";
        {
            var sockW;
            try silent { sockW = getVariable(context, "foilWingSocket"); }
            if (sockW != undefined && sockW.on == 1 && sockW.rearX != undefined && x0 < sockW.rearX * meter - 0.05 * millimeter)
            {
                const xR = sockW.rearX * meter;
                var fixes = [];
                const xFix = ceil(xR / millimeter);
                if (xFix <= 300)
                    fixes = append(fixes, "Mast X " ~ fmt(xFix, 0) ~ " mm or more");
                if (sockW.teX != undefined && sockW.fullX != undefined && sockW.rearFair != undefined)
                {
                    // the wing's Rear extension that ends the nacelle at the foot, where its bore and
                    // fairing still fit behind the blend
                    const rFix = floor((x0 - sockW.teX * meter) / millimeter);
                    if (rFix >= 0 && sockW.teX * meter + rFix * millimeter - max(sockW.depth, sockW.rearFair) * meter >= sockW.fullX * meter)
                        fixes = append(fixes, "the wing's Rear extension " ~ fmt(rFix, 0) ~ " mm or less");
                }
                sockNote = " | WARNING: the mast's leading edge (X " ~ fmt(x0 / millimeter, 0) ~ " mm) is ahead of the rear face of the wing's " ~
                    (sockW.joint != undefined && sockW.joint == "SQUARE" ? "square" : "round") ~ " socket (X " ~ fmt(xR / millimeter, 0) ~
                    " mm), so the mast foot stands on the nacelle, not on the fuselage or bar behind it" ~
                    (size(fixes) == 2 ? ": set " ~ fixes[0] ~ ", or " ~ fixes[1] : (size(fixes) == 1 ? ": set " ~ fixes[0] : ""));
            }
        }

        // ---------------- mast: loft through horizontal sections up the height ----------------
        // chord runs linearly from Width at the base to Top chord at the top, the change taken at
        // both edges, the trailing edge or the leading edge (Taper side); thickness holds Thickness up
        // to Thicken from %, then eases to Top thick with a smoothstep. plane normal +Z with
        // x-direction X gives sketch u = world X, v = world Y (thickness sideways)
        const nSec = (abs(cTop - c) < 0.01 * millimeter && abs(tTop - definition.mastThick) < 0.01 * millimeter) ? 2 : 13;
        var mastRegions = [];
        for (var i = 0; i < nSec; i += 1)
        {
            const sFrac = i / (nSec - 1);
            const law = mastLaw(definition, sFrac);
            const secI = naca4Section(0, 0.4, law.t / law.c, definition.mastTe / law.c, definition.mastPoints);
            const ptsI = placeSection(secI, law.c, 0, 1, 0); // leading edge at the sketch origin, no rotation
            const sid = id + ("mastSec" ~ i);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(law.xLE, 0 * meter, z0 + definition.mastHeight * sFrac), Z_DIRECTION, X_DIRECTION) });
            skFitSpline(sk, "surface", { "points" : ptsI });
            skLineSegment(sk, "trailingEdge", { "start" : ptsI[0], "end" : ptsI[size(ptsI) - 1] });
            skSolve(sk);
            mastRegions = append(mastRegions, qSketchRegion(sid));
            sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
        }
        opLoft(context, id + "mastLoft", { "profileSubqueries" : mastRegions });
        const lawTop = mastLaw(definition, 1);

        // ---------------- plate: loft between two rectangles, centred on the top chord ----------------
        const xc = lawTop.xLE + lawTop.c / 2;
        const hl = definition.plateLength / 2;
        const hw = definition.plateWidth / 2;
        const corners = [vector(-hl, -hw), vector(hl, -hw), vector(hl, hw), vector(-hl, hw)];
        var plateRegions = [];
        const pzs = [z1, z1 + definition.plateThick];
        for (var i = 0; i < 2; i += 1)
        {
            const sid = id + ("plateSec" ~ i);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(xc, 0 * meter, pzs[i]), Z_DIRECTION, X_DIRECTION) });
            for (var k = 0; k < 4; k += 1)
                skLineSegment(sk, "edge" ~ k, { "start" : corners[k], "end" : corners[(k + 1) % 4] });
            skSolve(sk);
            plateRegions = append(plateRegions, qSketchRegion(sid));
            sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
        }
        opLoft(context, id + "plateLoft", { "profileSubqueries" : plateRegions });

        // ---------------- bolt holes (and countersinks) cut from the plate ----------------
        var holeIds = [];
        const zTop = z1 + definition.plateThick;
        const e = 0.5 * millimeter;
        var n = 0;
        for (var row = 0; row < 2; row += 1)
        {
            const by = (row == 0 ? -1 : 1) * definition.trackSpacing / 2;
            for (var j = 0; j < definition.boltsPerRow; j += 1)
            {
                const bx = xc - rowSpan / 2 + j * definition.boltPitch;
                // through hole
                const holeBase = id + ("hole" ~ n);
                holeIds = append(holeIds, circleLoft(context, holeBase, bx, by, z1 - e, dBolt / 2, zTop + e, dBolt / 2));
                sketchBodies = append(sketchBodies, qCreatedBy(holeBase + "a", EntityType.BODY));
                sketchBodies = append(sketchBodies, qCreatedBy(holeBase + "b", EntityType.BODY));
                if (definition.countersink)
                {
                    // 90 deg cone on the UNDERSIDE (mast side): bolts go in from below, through the plate,
                    // into the board's track nuts. Head diameter at the underside, narrowing upward.
                    const cskBase = id + ("csk" ~ n);
                    holeIds = append(holeIds, circleLoft(context, cskBase, bx, by, z1 - e, headR + e, z1 + cskDepth, dBolt / 2));
                    sketchBodies = append(sketchBodies, qCreatedBy(cskBase + "a", EntityType.BODY));
                    sketchBodies = append(sketchBodies, qCreatedBy(cskBase + "b", EntityType.BODY));
                }
                n += 1;
            }
        }

        // ---------------- motor pod: loft through circular sections along X ----------------
        var podNote = "no pod";
        var podZ = 0 * meter;
        var podXc = 0 * meter;
        if (definition.podOn)
        {
            // Pod blends out of the mast from Nose start %, reaches full motor diameter after
            // Fairing length, then runs as a cylinder to a flat rear face Aft extension behind the TE.
            const R = definition.podDia / 2;
            podZ = z0 + definition.podHeight;
            if (definition.podHeight - R < 0 * meter || definition.podHeight + R > definition.mastHeight)
                throw regenError("Motor pod does not fit within the mast height at this Pod height", ["podHeight", "podDia"]);
            const lawP = mastLaw(definition, definition.podHeight / definition.mastHeight);
            const xNose = lawP.xLE + lawP.c * definition.podNoseStartPct / 100;
            const xRear = lawP.xLE + lawP.c + definition.podAft;
            const Lf = definition.podFairLength;
            if (xNose + Lf > xRear)
                throw regenError("Fairing length does not fit between the nose tip and the rear face - shorten it, move Nose start % forward or add Aft extension", ["podFairLength", "podNoseStartPct", "podAft"]);
            podXc = (xNose + xRear) / 2;
            // Blend: elliptical sections in the YZ plane. The first matches the mast's own
            // half-thickness at the nose start (inset 5 % so it sits just inside the mast faces);
            // width and height ease to the motor radius with (1 - cos(pi s)) / 2, which has zero
            // slope at both ends - the pod swells out of the mast and meets the cylinder tangent.
            const tcM = lawP.t / lawP.c;
            const teM = definition.mastTe / lawP.c;
            const w0 = 0.95 * lawP.c * nacaHalfThickness(tcM, teM, definition.podNoseStartPct / 100);
            const h0 = R * definition.podBlendHeightPct / 100;
            var xs = [];
            var ays = [];
            var azs = [];
            const nB = 10;
            for (var k = 0; k <= nB; k += 1)
            {
                const sb = k / nB;
                const ease = (1 - cos((PI * sb) * radian)) / 2;
                xs = append(xs, xNose + Lf * sb);
                ays = append(ays, w0 + (R - w0) * ease);
                azs = append(azs, h0 + (R - h0) * ease);
            }
            if (xRear - (xNose + Lf) > 0.5 * millimeter)
            {
                xs = append(xs, xRear);
                ays = append(ays, R);
                azs = append(azs, R);
            }
            var podRegions = [];
            for (var k = 0; k < size(xs); k += 1)
            {
                const sid = id + ("podSec" ~ k);
                // plane normal +X with x-direction Y gives sketch u = world Y, v = world Z
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(xs[k], 0 * meter, podZ), X_DIRECTION, Y_DIRECTION) });
                ellipseSplines(sk, ays[k], azs[k], 24);
                skSolve(sk);
                podRegions = append(podRegions, qSketchRegion(sid));
                sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
            }
            opLoft(context, id + "podLoft", { "profileSubqueries" : podRegions });
            if (abs(definition.podTilt) > 0.01 * degree)
                opTransform(context, id + "podTilt", {
                            "bodies" : qCreatedBy(id + "podLoft", EntityType.BODY),
                            "transform" : rotationAround(line(vector(podXc, 0 * meter, podZ), Y_DIRECTION), -definition.podTilt)   // +Y rotation lifts the nose, so nose-down is negative
                        });
            podNote = "pod " ~ fmt(definition.podDia / millimeter, 0) ~ " mm, blends from the mast at X " ~ fmt(xNose / millimeter, 0) ~ " mm to full diameter at X " ~ fmt((xNose + Lf) / millimeter, 0) ~ " mm, flat rear face at X " ~
                fmt(xRear / millimeter, 0) ~ " mm, Z " ~ fmt(podZ / millimeter, 0) ~ " mm";
        }

        opDeleteBodies(context, id + "deleteSketches", { "entities" : qUnion(sketchBodies) });

        // holes out of the plate first, then join mast + plate (+ pod)
        var holeQueries = [];
        for (var h in holeIds)
            holeQueries = append(holeQueries, qCreatedBy(h, EntityType.BODY));
        opBoolean(context, id + "cutHoles", {
                    "targets" : qCreatedBy(id + "plateLoft", EntityType.BODY),
                    "tools" : qUnion(holeQueries),
                    "operationType" : BooleanOperationType.SUBTRACTION
                });
        var parts = [qCreatedBy(id + "mastLoft", EntityType.BODY), qCreatedBy(id + "plateLoft", EntityType.BODY)];
        if (definition.podOn)
            parts = append(parts, qCreatedBy(id + "podLoft", EntityType.BODY));
        opBoolean(context, id + "join", { "tools" : qUnion(parts), "operationType" : BooleanOperationType.UNION });
        // root fillet: the edges the union made where the section meets the plate's underside (they
        // all lie in that plane; the pod's junction edges lie far below it). The mold follows it
        // because its cavity is cut from this part. Held inside the plate with 2 mm to spare
        var rF = 0 * meter;
        var filletNote = "";
        if (definition.rootFillet > 0)
        {
            const roomY = (definition.plateWidth - lawTop.t) / 2 - 2 * millimeter;
            const roomX = (definition.plateLength - lawTop.c) / 2 - 2 * millimeter;
            rF = min(definition.rootFillet, min(roomY, roomX));
            if (rF < 0.5 * millimeter)
            {
                rF = 0 * meter;
                filletNote = " · no root fillet: no room on the plate (widen Plate width / Plate length)";
            }
            else
            {
                // the seam: edges of the joined solid lying flat in the plate's underside plane and
                // inside the section's footprint (the plate outline, its vertical corners and the
                // countersink rims all touch that plane too, so pick by bounding box, not by query)
                var seam = [];
                const solidJ = qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID);
                for (var e in evaluateQuery(context, qIntersectsPlane(qOwnedByBody(solidJ, EntityType.EDGE), plane(vector(0 * meter, 0 * meter, z1), Z_DIRECTION))))
                {
                    const bx = evBox3d(context, { "topology" : e });
                    if (bx.maxCorner[2] - bx.minCorner[2] < 0.02 * millimeter &&
                        abs(bx.minCorner[1]) < lawTop.t / 2 + 0.5 * millimeter && abs(bx.maxCorner[1]) < lawTop.t / 2 + 0.5 * millimeter &&
                        bx.minCorner[0] > lawTop.xLE - 0.5 * millimeter && bx.maxCorner[0] < lawTop.xLE + lawTop.c + 0.5 * millimeter)
                        seam = append(seam, e);
                }
                // the seam is the section's fit spline plus its 0.8 mm trailing-edge line: a ladder of
                // attempts, each silent so the feature always regenerates - all edges, then without
                // tangent propagation, then the long edges only (a tiny TE notch is cosmetic), then half
                // the radius. Console MAST_FILLET says what was found and what worked
                var diag = "MAST_FILLET: " ~ size(seam) ~ " seam edges at Z " ~ fmt(z1 / millimeter, 1) ~ " mm";
                var longEdges = [];
                for (var e in seam)
                {
                    const bx = evBox3d(context, { "topology" : e });
                    const len = evLength(context, { "entities" : e });
                    diag = diag ~ "; edge " ~ fmt(len / millimeter, 1) ~ " mm long, X " ~ fmt(bx.minCorner[0] / millimeter, 1) ~ ".." ~ fmt(bx.maxCorner[0] / millimeter, 1) ~ ", Y " ~ fmt(bx.minCorner[1] / millimeter, 1) ~ ".." ~ fmt(bx.maxCorner[1] / millimeter, 1);
                    if (len > 3 * millimeter)
                        longEdges = append(longEdges, e);
                }
                if (size(seam) == 0)
                {
                    filletNote = " · ROOT FILLET: no seam edges found at the plate underside (send the console's MAST_FILLET line)";
                    rF = 0 * meter;
                }
                else
                {
                    // build 121 in Onshape: only "long edges only, no propagation" works - the 0.8 mm
                    // TE line edge cannot carry a 10 mm fillet, so it is left as a notch of TE thickness
                    const attempts = [
                        { "name" : "long edges only, no propagation", "edges" : longEdges, "r" : rF, "prop" : false },
                        { "name" : "all edges", "edges" : seam, "r" : rF, "prop" : true },
                        { "name" : "long edges at half radius", "edges" : longEdges, "r" : rF / 2, "prop" : false },
                        { "name" : "all edges at half radius", "edges" : seam, "r" : rF / 2, "prop" : true }
                    ];
                    var done = false;
                    var tried = "";
                    for (var a = 0; a < size(attempts) && !done; a += 1)
                    {
                        const at = attempts[a];
                        if (size(at.edges) == 0)
                            continue;
                        try silent
                        {
                            opFillet(context, id + ("rootFillet" ~ a), { "entities" : qUnion(at.edges), "radius" : at.r, "tangentPropagation" : at.prop });
                            done = true;
                            rF = at.r;
                            filletNote = " · root fillet " ~ fmt(rF / millimeter, 1) ~ " mm (" ~ at.name ~ ")" ~ (rF < definition.rootFillet - 0.01 * millimeter ? " - held below Root fillet" : "");
                            diag = diag ~ " | OK: " ~ at.name ~ " at " ~ fmt(at.r / millimeter, 1) ~ " mm";
                        }
                        if (!done)
                            tried = tried ~ (tried == "" ? "" : ", ") ~ at.name ~ " at " ~ fmt(at.r / millimeter, 1) ~ " mm";
                    }
                    if (!done)
                    {
                        diag = diag ~ " | FAILED: " ~ tried;
                        filletNote = " · ROOT FILLET FAILED (" ~ tried ~ ") - add a manual Fillet feature on this seam between Foil mast and Foil mold; the mold cuts its cavity from the part so it will follow";
                        rF = 0 * meter;
                    }
                }
                foilPrint(context, "foilMastLog", diag);
            }
        }
        // motor cavity: a blind bore from the pod's rear face, the placeholder the mold's plug follows
        var cavR = 0 * meter;
        var cavL = 0 * meter;
        var podRearX = 0 * meter;
        var podNoseX = 0 * meter;
        if (definition.podOn)
        {
            const lawP2 = mastLaw(definition, definition.podHeight / definition.mastHeight);
            podRearX = lawP2.xLE + lawP2.c + definition.podAft;
            podNoseX = lawP2.xLE + lawP2.c * definition.podNoseStartPct / 100;
            cavR = min(definition.cavDia, definition.podDia - 4 * millimeter) / 2;
            if (cavR < definition.cavDia / 2 - 0.01 * millimeter)
                podNote = podNote ~ " (Cavity dia limited to " ~ fmt(2 * cavR / millimeter, 0) ~ " mm for 2 mm of wall)";
            cavL = min(definition.cavLength, podRearX - podNoseX - 2 * millimeter);
            if (cavL < definition.cavLength - 0.01 * millimeter)
                podNote = podNote ~ " (Cavity length shortened to " ~ fmt(cavL / millimeter, 0) ~ " mm to clear the nose)";
            const cid = id + "podCav";
            xCylinder(context, cid, podRearX - cavL, podRearX + 1 * millimeter, 0 * meter, podZ, cavR);
            if (abs(definition.podTilt) > 0.01 * degree)
                opTransform(context, id + "podCavTilt", {
                            "bodies" : qCreatedBy(cid + "loft", EntityType.BODY),
                            "transform" : rotationAround(line(vector(podXc, 0 * meter, podZ), Y_DIRECTION), -definition.podTilt)
                        });
            opBoolean(context, id + "podCavCut", {
                        "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(cid + "loft", EntityType.BODY)),
                        "tools" : qCreatedBy(cid + "loft", EntityType.BODY),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
            opDeleteBodies(context, id + "deleteCavSketches", { "entities" : qUnion([qCreatedBy(cid + "s0", EntityType.BODY), qCreatedBy(cid + "s1", EntityType.BODY)]) });
            podNote = podNote ~ ", cavity " ~ fmt(2 * cavR / millimeter, 0) ~ " x " ~ fmt(cavL / millimeter, 0) ~ " mm from the rear face";
        }
        nameSolids(context, id, "Mast");

        // ---------------- publish ----------------
        setVariable(context, "foilMastModel", {
                    "chord" : c / meter, "thick" : definition.mastThick / meter, "tc" : tc,
                    "chordTop" : cTop / meter, "thickTop" : tTop / meter, "thickenFrom" : definition.thickenFrom / 100,
                    "taperSide" : definition.mastTaper == MastTaper.SYMMETRIC ? 0 : (definition.mastTaper == MastTaper.LEADING ? 1 : 2),
                    "leXTop" : lawTop.xLE / meter, "plateXc" : xc / meter,
                    "te" : definition.mastTe / meter, "points" : definition.mastPoints,
                    "height" : definition.mastHeight / meter, "baseZ" : z0 / meter, "leX" : x0 / meter,
                    "podOn" : definition.podOn ? 1 : 0,
                    "podDia" : definition.podOn ? definition.podDia / meter : 0,
                    "podLength" : definition.podOn ? (definition.mastX + c + definition.podAft - (definition.mastX + c * definition.podNoseStartPct / 100)) / meter : 0,
                    "podFairLength" : definition.podOn ? definition.podFairLength / meter : 0,
                    "podZ" : podZ / meter, "podX" : podXc / meter,
                    "podRearX" : podRearX / meter, "podNoseX" : podNoseX / meter, "cavDia" : 2 * cavR / meter, "cavLength" : cavL / meter,
                    "podTilt" : definition.podOn ? definition.podTilt / radian : 0,
                    "plateLength" : definition.plateLength / meter, "plateWidth" : definition.plateWidth / meter, "plateThick" : definition.plateThick / meter,
                    "trackSpacing" : definition.trackSpacing / meter, "boltsPerRow" : definition.boltsPerRow, "plateBoltPitch" : definition.boltPitch / meter,
                    "plateBoltDia" : dBolt / meter, "plateHeadDia" : 2 * headR / meter, "countersink" : definition.countersink ? 1 : 0,
                    "rootFillet" : rF / meter
                });

        foilNotice(context, id, "foilMastNotice",
            "Mast " ~ fmt(definition.mastHeight / millimeter, 0) ~ " mm · chord " ~ fmt(c / millimeter, 0) ~
            (abs(cTop - c) > 0.01 * millimeter ? " -> " ~ fmt(cTop / millimeter, 0) ~ " at the top (" ~ (definition.mastTaper == MastTaper.SYMMETRIC ? "symmetric" : (definition.mastTaper == MastTaper.LEADING ? "straight LE" : "straight TE")) ~ ")" : "") ~
            " mm · t/c " ~ fmt(tc * 100, 1) ~ "%" ~
            (abs(tTop - definition.mastThick) > 0.01 * millimeter ? " · thickens from " ~ fmt(definition.thickenFrom, 0) ~ "% height to " ~ fmt(tTop / millimeter, 1) ~ " mm at the top" : "") ~
            " · LE " ~ fmt(x0 / millimeter, 0) ~ " mm, TE " ~ fmt((x0 + c) / millimeter, 0) ~ " mm from wing pivot" ~ filletNote ~
            " | " ~ podNote ~
            " | plate " ~ fmt(definition.plateLength / millimeter, 0) ~ " x " ~ fmt(definition.plateWidth / millimeter, 0) ~ " mm, " ~
            fmt(2 * definition.boltsPerRow, 0) ~ " bolts on " ~ fmt(definition.trackSpacing / millimeter, 0) ~ " mm tracks" ~ sockNote, sockNote != "");
    });

/**
 * Chord, thickness and leading-edge X of the mast at height fraction s (0 base, 1 top): chord linear
 * from Width to Top chord with the change at both edges / the TE / the LE (Taper side); thickness
 * constant to Thicken from %, then a smoothstep to Top thick.
 */
function mastLaw(definition is map, s is number) returns map
{
    const c0 = definition.mastWidth;
    const c1 = definition.topChord;
    const cs = c0 + (c1 - c0) * s;
    var xLE = definition.mastX;
    if (definition.mastTaper == MastTaper.SYMMETRIC)
        xLE = definition.mastX + (c0 - cs) / 2;
    else if (definition.mastTaper == MastTaper.TRAILING)
        xLE = definition.mastX + (c0 - cs);
    const s0 = definition.thickenFrom / 100;
    const u = s0 >= 1 ? 0 : min(max((s - s0) / (1 - s0), 0), 1);
    const sm = u * u * (3 - 2 * u);
    const t = definition.mastThick + (definition.topThick - definition.mastThick) * sm;
    return { "c" : cs, "t" : t, "xLE" : xLE };
}

/** Half-thickness / chord of the symmetric NACA 00xx section at chord fraction x (same law as naca4Section). */
function nacaHalfThickness(t is number, teFrac is number, x is number) returns number
{
    const xc = min(max(x, 0), 1);
    return 5 * t * (0.2969 * sqrt(xc) - 0.1260 * xc - 0.3516 * xc ^ 2 + 0.2843 * xc ^ 3 - 0.1036 * xc ^ 4) + 0.5 * teFrac * xc;
}

/**
 * Ellipse with half-axes a (sketch u) and b (sketch v) as two fitted splines, upper and lower
 * halves, sharing their two end points exactly so the region closes. Every section built this
 * way has the same topology (two edges), which keeps a loft through them well matched.
 */
/** Rounded rectangle, half-width a (sketch u), half-height b (sketch v), corner radius r: four lines and four arcs. */
/**
 * Rounded box along X from x0 to x1, centred on (y 0, zAxis), half sizes halfW (Y) x halfH (Z),
 * corner radius r (a plain box below 0.05 mm): a loft of two roundedRect sections. The body is
 * qCreatedBy(baseId + "loft", BODY) either way; the sketches are deleted here.
 */
function roundedBoxX(context is Context, baseId is Id, x0 is ValueWithUnits, x1 is ValueWithUnits, zAxis is ValueWithUnits, halfW is ValueWithUnits, halfH is ValueWithUnits, r is ValueWithUnits)
{
    if (r < 0.05 * millimeter)
    {
        moldBox(context, baseId + "loft", vector(x0, -halfW, zAxis - halfH), vector(x1, halfW, zAxis + halfH));
        return;
    }
    const xs = [x0, x1];
    var regions = [];
    var sketches = [];
    for (var i = 0; i < 2; i += 1)
    {
        const sid = baseId + ("s" ~ i);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(xs[i], 0 * meter, zAxis), X_DIRECTION, Y_DIRECTION) });
        roundedRect(sk, halfW, halfH, r);
        skSolve(sk);
        regions = append(regions, qSketchRegion(sid));
        sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
    }
    opLoft(context, baseId + "loft", { "profileSubqueries" : regions });
    opDeleteBodies(context, baseId + "del", { "entities" : qUnion(sketches) });
}

function roundedRect(sketch is Sketch, a is ValueWithUnits, b is ValueWithUnits, r is ValueWithUnits)
{
    const rr = min(r, min(a, b) * 0.9);
    const c = rr * (1 - sqrt(0.5));                                       // arc mid-point inset
    skLineSegment(sketch, "top", { "start" : vector(-a + rr, b), "end" : vector(a - rr, b) });
    skArc(sketch, "c1", { "start" : vector(a - rr, b), "mid" : vector(a - c, b - c), "end" : vector(a, b - rr) });
    skLineSegment(sketch, "right", { "start" : vector(a, b - rr), "end" : vector(a, -b + rr) });
    skArc(sketch, "c2", { "start" : vector(a, -b + rr), "mid" : vector(a - c, -b + c), "end" : vector(a - rr, -b) });
    skLineSegment(sketch, "bottom", { "start" : vector(a - rr, -b), "end" : vector(-a + rr, -b) });
    skArc(sketch, "c3", { "start" : vector(-a + rr, -b), "mid" : vector(-a + c, -b + c), "end" : vector(-a, -b + rr) });
    skLineSegment(sketch, "left", { "start" : vector(-a, -b + rr), "end" : vector(-a, b - rr) });
    skArc(sketch, "c4", { "start" : vector(-a, b - rr), "mid" : vector(-a + c, b - c), "end" : vector(-a + rr, b) });
}

/**
 * The nacelle's outline at angle th (m): the ellipse (a, b), or for the square socket the rounded rectangle (half
 * sizes a, b, corners 0.3 x the smaller, as roundedRect builds it) met by a ray from the centre at th.
 */
function fairPt(sq is boolean, a is number, b is number, th is number) returns array
{
    const c = cos(th * radian);
    const sn = sin(th * radian);
    if (!sq)
        return [a * c, b * sn];
    const rc = min(0.3 * min(a, b), 0.9 * min(a, b));
    if (abs(c) > 1e-12)
    {
        const t = a / abs(c);
        if (abs(t * sn) <= b - rc)
            return [t * c, t * sn];
    }
    if (abs(sn) > 1e-12)
    {
        const t = b / abs(sn);
        if (abs(t * c) <= a - rc)
            return [t * c, t * sn];
    }
    const cy = c >= 0 ? a - rc : -(a - rc);
    const cz = sn >= 0 ? b - rc : -(b - rc);
    const dc = c * cy + sn * cz;
    const t = dc + sqrt(max(0, dc * dc - (cy * cy + cz * cz) + rc * rc));
    return [t * c, t * sn];
}

/** The angle on the near (+y) side where the outline crosses the line z = L (bisection; z rises with th there). */
function fairCross(sq is boolean, a is number, b is number, L is number) returns number
{
    var lo = -PI / 2;
    var hi = PI / 2;
    for (var it = 0; it < 50; it += 1)
    {
        const mid = 0.5 * (lo + hi);
        if (fairPt(sq, a, b, mid)[1] < L)
            lo = mid;
        else
            hi = mid;
    }
    return 0.5 * (lo + hi);
}

/** fairPt with y divided by k: the outline in the space squeezed across by Fairing spread, where the fillet is a circle. */
function fairPtK(sq is boolean, a is number, b is number, th is number, k is number) returns array
{
    const p = fairPt(sq, a, b, th);
    return [p[0] / k, p[1]];
}

/** Closest point of the outline (a, b) to (py, pz), on its upper (z >= 0) or lower half and a quarter past: distance and angle, numbers in m. */
function fairClosest(sq is boolean, a is number, b is number, py is number, pz is number, upper is boolean, k is number) returns map
{
    // the near side's half and a quarter past it: behind the trailing edge the web can sit below (above) the
    // centre, where the tangent point of the upper (lower) fillet falls under (over) the side
    var d0 = inf;
    var th0 = 0;
    const N = 120;
    for (var i = 0; i <= N; i += 1)
    {
        const th = upper ? -PI / 2 + 1.5 * PI * i / N : PI / 2 - 1.5 * PI * i / N;
        const q = fairPtK(sq, a, b, th, k);
        const d = sqrt((py - q[0]) ^ 2 + (pz - q[1]) ^ 2);
        if (d < d0)
        {
            d0 = d;
            th0 = th;
        }
    }
    var h = 1.5 * PI / N;
    for (var it = 0; it < 25; it += 1)
    {
        for (var t in [th0 - h, th0 + h])
        {
            const q = fairPtK(sq, a, b, t, k);
            const d = sqrt((py - q[0]) ^ 2 + (pz - q[1]) ^ 2);
            if (d < d0)
            {
                d0 = d;
                th0 = t;
            }
        }
        h = h / 2;
    }
    return { "d" : d0, "th" : th0 };
}

/**
 * The circle of radius r tangent to the line z = L (above it for the upper side, below for the lower) and
 * externally to the ellipse (a, b), on the +y side: centre, the tangent angle on the ellipse, the foot on the line.
 * The twin: the fairing prototype (bisection on the centre's y). Undefined when no such circle exists.
 */
function fairFillet(sq is boolean, a is number, b is number, L is number, r is number, upper is boolean, k is number)
{
    // in the space squeezed across by k (Fairing spread): a circle there is the fillet stretched k times wider than
    // tall back in the section, and an affine map keeps its tangency to the outline and to the line
    const zc = upper ? L + r : L - r;
    const yE = fairPtK(sq, a, b, fairCross(sq, a, b, L), k)[0];
    var lo = yE;          // a centre above the crossing is never more than r from the ellipse (inside it, one can be: build 241's tail kink)
    var hi = yE + 3 * r + a / k;
    if (fairClosest(sq, a, b, hi, zc, upper, k).d - r < 0)
        return undefined;
    for (var it = 0; it < 40; it += 1)
    {
        const mid = 0.5 * (lo + hi);
        if (fairClosest(sq, a, b, mid, zc, upper, k).d - r > 0)
            hi = mid;
        else
            lo = mid;
    }
    return { "yc" : hi, "zc" : zc, "th" : fairClosest(sq, a, b, hi, zc, upper, k).th, "foot" : hi };
}

/** The round nacelle's half width and half height (m) at x, by the socket's own blend and rear-fairing laws. */
function fairHalfAt(definition is map, x is ValueWithUnits, xStart is ValueWithUnits, xFull is ValueWithUnits, xFairStart is ValueWithUnits, R is ValueWithUnits,
    h0 is ValueWithUnits, rLip is ValueWithUnits, aw is number, ah is number) returns array
{
    if (x < xFull)
    {
        const sb = max(0, (x - xStart) / (xFull - xStart));
        return [aw, (h0 / meter + (ah - h0 / meter) * (1 - cos((PI * sb) * radian)) / 2)];
    }
    if (x > xFairStart && definition.nacelleRearFair > 0.5 * millimeter)
    {
        const sF = min(1, (x - xFairStart) / definition.nacelleRearFair);
        const f = 1 + (rLip / R - 1) * (1 - cos((PI * sF) * radian)) / 2;
        return [aw * f, ah * f];
    }
    return [aw, ah];
}

/** A smooth minimum of two non-negative numbers ((p^-6 + q^-6)^(-1/6)), so a radius capped by the room for it has no corner. */
function fairSmin(p is number, q is number) returns number
{
    if (p <= 0 || q <= 0)
        return max(0, min(p, q));
    return (p ^ -6 + q ^ -6) ^ (-1 / 6);
}

/**
 * The faired tail's web height (m, world) at x: the trailing edge's height ahead of it; behind it a cubic Hermite
 * from the trailing edge's height, along the camber line's slope there, to the socket's axis, level, at x1; the
 * axis from there. The wing builds the web on it and the mold parts on it (the published web map), so the parting
 * runs through the web everywhere and through the nacelle's diameter behind the tail.
 */
function fairWebZ(x is number, xTE is number, x1 is number, zTE is number, sTE is number, zEnd is number) returns number
{
    if (x >= x1)
        return zEnd;
    if (x <= xTE)
        return zTE;
    const L = x1 - xTE;
    const u = (x - xTE) / L;
    return (2 * u ^ 3 - 3 * u ^ 2 + 1) * zTE + (u ^ 3 - 2 * u ^ 2 + u) * L * sTE + (-2 * u ^ 3 + 3 * u ^ 2) * zEnd;
}

/** The weight of the span line's drop on the tail's web at x: 1 at the trailing edge, easing to 0 at x1. */
function fairWebW(x is number, xTE is number, x1 is number) returns number
{
    if (x <= xTE)
        return 1;
    const u = min(1, (x - xTE) / (x1 - xTE));
    return 1 - u * u * (3 - 2 * u);
}

/** The round nacelle's section centre at x: the root's mid-thickness at the blend's start, easing to the socket's axis. */
function fairCentreAt(definition is map, x is ValueWithUnits, xStart is ValueWithUnits, xFull is ValueWithUnits, axisZ is ValueWithUnits) returns ValueWithUnits
{
    if (x >= xFull)
        return axisZ;
    const sb = max(0, (x - xStart) / (xFull - xStart));
    return axisZ - definition.socketHeight * (1 + cos((PI * sb) * radian)) / 2;
}

/** One side's arc, from the foot on the line round to the tangent point on the ellipse, narc points (m). */
function fairArc(sq is boolean, f is map, a is number, b is number, r is number, upper is boolean, narc is number, ks is number) returns array
{
    const tp = fairPtK(sq, a, b, f.th, ks);
    const ty = tp[0];
    const tz = tp[1];
    const ang0 = upper ? -PI / 2 : PI / 2;
    var ang1 = atan2(tz - f.zc, ty - f.yc) / radian;
    if (upper && ang1 > ang0 + PI)
        ang1 -= 2 * PI;
    if (!upper && ang1 < ang0 - PI)
        ang1 += 2 * PI;
    var pts = [];
    for (var k = 0; k < narc; k += 1)
    {
        const ang = ang0 + (ang1 - ang0) * k / (narc - 1);
        pts = append(pts, [ks * (f.yc + r * cos(ang * radian)), f.zc + r * sin(ang * radian)]);
    }
    return pts;
}

/** The span line's height (m) at span y (m) from the root, by the wing's drop and dihedral laws. */
function fairDrop(model is map, y is number) returns number
{
    return moldDropZ(model, min(1, max(0, y / (model.span / 2))));
}

/**
 * One side of a faired nacelle section, densely: the foot on the line z = L (plus the span line's drop there,
 * weighted by w) and the fillet of radius r round to the nacelle ellipse (a, b), as [y, z] points (m), foot first;
 * th is the angle on the ellipse where the cap begins. r under 0.2 mm has no arc: the foot is where the ellipse
 * crosses the line, so the outline shrinks continuously to the plain ellipse. Undefined when no fillet fits.
 */
function fairSide(sq is boolean, a is number, b is number, L is number, r is number, upper is boolean, model is map, w is number, k is number)
{
    var Lf = L + w * fairDrop(model, a);
    for (var pass = 0; pass < 2; pass += 1)
    {
        if (r < 0.2e-3)
        {
            const th = fairCross(sq, a, b, min(0.98 * b, max(-0.98 * b, Lf)));
            const foot = fairPt(sq, a, b, th)[0];
            if (pass == 0)
            {
                Lf = L + w * fairDrop(model, foot);
                continue;
            }
            return { "pts" : [fairPt(sq, a, b, th)], "foot" : foot, "th" : th, "L" : Lf };
        }
        const f = fairFillet(sq, a, b, Lf, r, upper, k);
        if (f == undefined)
            return undefined;
        if (pass == 0)
        {
            Lf = L + w * fairDrop(model, k * f.yc);
            continue;
        }
        return { "pts" : fairArc(sq, f, a, b, r, upper, 20, k), "foot" : k * f.yc, "th" : f.th, "L" : Lf };
    }
    return undefined;
}

/** A polyline ([y, z] in m) resampled to M points evenly spaced along its length, its ends kept. */
function fairResample(pts is array, M is number) returns array
{
    var cum = [0];
    for (var i = 1; i < size(pts); i += 1)
        cum = append(cum, cum[i - 1] + sqrt((pts[i][0] - pts[i - 1][0]) ^ 2 + (pts[i][1] - pts[i - 1][1]) ^ 2));
    const total = cum[size(cum) - 1];
    var out = [pts[0]];
    var j = 1;
    for (var k = 1; k < M - 1; k += 1)
    {
        const t = total * k / (M - 1);
        while (j < size(pts) - 1 && cum[j] < t)
            j += 1;
        const seg = cum[j] - cum[j - 1];
        const u = seg > 0 ? (t - cum[j - 1]) / seg : 0;
        out = append(out, [pts[j - 1][0] + (pts[j][0] - pts[j - 1][0]) * u, pts[j - 1][1] + (pts[j][1] - pts[j - 1][1]) * u]);
    }
    return append(out, pts[size(pts) - 1]);
}

/**
 * One closed half of a faired section (the top or the bottom), dense: the web out to ye (when it reaches past the
 * feet), the fillet, the cap over the ellipse to the far side, the mirrored fillet and web; then resampled evenly.
 */
function fairHalfCurve(sq is boolean, f is map, a is number, b is number, upper is boolean, ye is number, Lw is number, w is number, model is map, web is boolean, M is number) returns array
{
    var pts = [];
    if (web)
    {
        for (var k = 0; k < 10; k += 1)
        {
            const y = ye + (f.foot - ye) * k / 10;
            pts = append(pts, [y, Lw + w * fairDrop(model, y)]);
        }
    }
    for (var p in f.pts)
        pts = append(pts, p);
    const nCap = 80;
    for (var j = 1; j < nCap; j += 1)
    {
        const th = upper ? f.th + (PI - 2 * f.th) * j / nCap : f.th + (-PI - 2 * f.th) * j / nCap;
        pts = append(pts, fairPt(sq, a, b, th));
    }
    for (var j = size(f.pts) - 1; j >= 0; j -= 1)
        pts = append(pts, [-f.pts[j][0], f.pts[j][1]]);
    if (web)
    {
        for (var k = 9; k >= 0; k -= 1)
        {
            const y = ye + (f.foot - ye) * k / 10;
            pts = append(pts, [-y, Lw + w * fairDrop(model, y)]);
        }
    }
    return fairResample(pts, M);
}

/**
 * The faired round nacelle (build 241): one loft from the root's thickest point to the socket's rear face, every
 * section the nacelle ellipse with a short side flat (where the ellipse is vertical, so it stays smooth) and,
 * where the fairing is active, a concave fillet each side tangent to the ellipse and to a line 0.4 mm inside the
 * skin (with the span line's drop at its foot), closed through the wing's inside. Radius: from where the nacelle
 * stands 1.5 mm out of both skins, growing to Fairing radius by mid-root; with a tail it holds to the trailing
 * edge and the trailing edge carries on as a web (inside its thickness, following its droop) that leaves the
 * trailing edge on a plan radius, shrinks and eases back to the nacelle's mid-height over Fairing tail; without
 * one it eases to nothing ahead of the trailing edge. Held under 90 % of the nacelle's height out of the skin.
 */
function buildFairedNacelle(context is Context, id is Id, definition is map, m is map, upper is array, lower is array, axisZ is ValueWithUnits, xStart is ValueWithUnits,
    xFull is ValueWithUnits, xFairStart is ValueWithUnits, xRear is ValueWithUnits, xTE is ValueWithUnits, R is ValueWithUnits, h0 is ValueWithUnits, rLip is ValueWithUnits, sq is boolean, Rw is ValueWithUnits, Rh is ValueWithUnits) returns map
{
    const delta = 0.4e-3;
    const aw0 = Rw / meter;
    const ah0 = Rh / meter;
    const rMax = definition.fairingRadius / meter;
    const spread = definition.fairingSpread == undefined ? 1 : definition.fairingSpread;
    const a0 = R / meter;
    const model = m.model;
    var stage = "the scan of the root";
    var res = undefined;
    var done = false;
    var x0 = undefined;
    var x1 = undefined;
    var rUsed = 0;
    var tailOn = false;
    var rp = 0 * meter;
    var hw = 0.25e-3;
    var footTail = 0;
    var reach = 0;
    var planEdge = [];          // [x, half width] of the tail behind the trailing edge, for the mold's outline
    var sTE = 0;
    var zTEn = 0;
    var plateNote = "";
    try silent
    {
        const NS = 80;
        for (var k = 0; k <= NS; k += 1)
        {
            const x = xStart + (xTE - xStart) * k / NS;
            const zc = fairCentreAt(definition, x, xStart, xFull, axisZ);
            const su = (profileZAtClamped(upper, x) - zc) / meter;
            const sl = (profileZAtClamped(lower, x) - zc) / meter;
            const hb = fairHalfAt(definition, x, xStart, xFull, xFairStart, R, h0, rLip, aw0, ah0)[1];
            const out = min(hb - su, hb + sl);
            if (x0 == undefined && out >= 1.5e-3)
                x0 = x;
            if (x0 != undefined && su - sl >= 2.5e-3 && out >= 1.5e-3)
                x1 = x;
        }
        const tailLen = definition.fairingTail == undefined ? 0 * meter : min(definition.fairingTail, xRear - xTE - 3 * millimeter);
        tailOn = tailLen >= 5 * millimeter;
        if (tailOn && x0 != undefined)
            x1 = xTE + tailLen;
        if (x0 == undefined || x1 == undefined || x1 - x0 < 10 * millimeter)
            res = { "on" : 0, "note" : " | root fairing: not built - the nacelle stands out of the wing for less than 10 mm of the root" };
        if (res == undefined)
        {
            stage = "the stations";
            rp = tailOn ? min(definition.fairingRadius, 0.8 * tailLen) : 0 * meter;
            hw = max(0.25e-3, 0.4 * definition.teThickness / meter);
            const zTE = (profileZAtClamped(upper, xTE) + profileZAtClamped(lower, xTE)) / 2;
            const zM3 = (profileZAtClamped(upper, xTE - 3 * millimeter) + profileZAtClamped(lower, xTE - 3 * millimeter)) / 2;
            sTE = (zTE - zM3) / (3 * millimeter);      // the camber line's slope at the trailing edge
            zTEn = zTE / meter;
            // the nose, from the thickest point to x0 where the nacelle first stands 1.5 mm clear of both skins: plain
            // ellipses (a lumpy nose came from faired sections lying almost wholly inside the wing)
            stage = "the nose";
            var nRegions = [];
            var nSketches = [];
            for (var k = 0; k <= (x0 - xStart > 2 * millimeter ? 8 : -1); k += 1)
            {
                const x = xStart + (x0 - xStart) * k / 8;
                const ab = fairHalfAt(definition, x, xStart, xFull, xFairStart, R, h0, rLip, aw0, ah0);
                const sid = id + ("fnNose" ~ k);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(x, 0 * meter, fairCentreAt(definition, x, xStart, xFull, axisZ)), X_DIRECTION, Y_DIRECTION) });
                if (sq)
                    roundedRect(sk, ab[0] * meter, ab[1] * meter, min(ab[0], ab[1]) * 0.3 * meter);
                else
                    ellipseSplines(sk, ab[0] * meter, ab[1] * meter, 24);
                skSolve(sk);
                nRegions = append(nRegions, qSketchRegion(sid));
                nSketches = append(nSketches, qCreatedBy(sid, EntityType.BODY));
            }
            if (size(nRegions) > 1)
            {
                opLoft(context, id + "nacelleNose", { "profileSubqueries" : nRegions });
                opDeleteBodies(context, id + "fnNoseSketches", { "entities" : qUnion(nSketches) });
            }
            stage = "the stations";
            var raw = [];
            if (tailOn)
            {
                for (var k = 0; k <= 16; k += 1)
                    raw = append(raw, (x0 + (xTE - x0) * k / 16) / meter);
                for (var k = 1; k <= 16; k += 1)
                    raw = append(raw, (xTE + tailLen * k / 16) / meter);
            }
            else
            {
                for (var k = 0; k <= 16; k += 1)
                    raw = append(raw, (x0 + (x1 - x0) * k / 16) / meter);
            }
            if (definition.nacelleRearFair > 0.5 * millimeter && rLip < R - 0.001 * millimeter)
            {
                for (var k = 0; k <= 5; k += 1)
                    raw = append(raw, (xFairStart + definition.nacelleRearFair * k / 5) / meter);
            }
            else
                raw = append(raw, xRear / meter);
            raw = sort(raw, function(p, q) { return p - q; });
            var stations = [];
            for (var v in raw)
            {
                if (v >= x0 / meter - 1e-9 && v <= xRear / meter + 1e-9 && (size(stations) == 0 || v - stations[size(stations) - 1] >= 0.5e-3))
                    stations = append(stations, v);
            }
            if (size(stations) > 1 && xRear / meter - stations[size(stations) - 1] > 1e-6)
                stations[size(stations) - 1] = xRear / meter;     // end on the rear face
            var regions = [];
            var sketches = [];
            var ok = true;
            const nc = 14;
            for (var k = 0; k < size(stations); k += 1)
            {
                const x = stations[k] * meter;
                stage = "station " ~ k ~ " of " ~ (size(stations) - 1) ~ " (X " ~ fmt(x / millimeter, 1) ~ ")";
                const zc = fairCentreAt(definition, x, xStart, xFull, axisZ);
                const ab = fairHalfAt(definition, x, xStart, xFull, xFairStart, R, h0, rLip, aw0, ah0);
                const a = ab[0];
                const b = ab[1];
                // the radius law
                var r = 0;
                if (x >= x0 && x <= x1)
                {
                    var up = 1;
                    var dn = 1;
                    if (tailOn)
                    {
                        const uu = min(1, (x - x0) / (0.5 * (xTE - x0)));
                        up = uu * uu * (3 - 2 * uu);
                        if (x > xTE)
                        {
                            const ud = min(1, (x - xTE) / (x1 - xTE));
                            dn = 1 - ud * ud * (3 - 2 * ud);
                        }
                    }
                    else
                    {
                        const u = (x - x0) / (x1 - x0);
                        up = u >= 0.5 ? 1 : (u * 2) * (u * 2) * (3 - 2 * u * 2);
                        dn = u <= 0.75 ? 1 : 1 - ((u - 0.75) * 4) * ((u - 0.75) * 4) * (3 - 2 * (u - 0.75) * 4);
                    }
                    r = rMax * up * dn;
                }
                // the lines the fillets run into: inside the skin (or the web) ahead of the trailing edge; the web
                // behind it, easing to the nacelle's side as the tail ends
                var Lu = 0;
                var Ll = 0;
                var w = 1;
                if (x <= xTE)
                {
                    const su = (profileZAtClamped(upper, x) - zc) / meter;
                    const sl = (profileZAtClamped(lower, x) - zc) / meter;
                    const zm = (su + sl) / 2;
                    Lu = max(min(su - delta, b - 1e-3), zm + hw);
                    Ll = min(max(sl + delta, -b + 1e-3), zm - hw);
                }
                else
                {
                    var e = 1;
                    if (tailOn && x < x1)
                    {
                        const ue = (x - xTE) / (x1 - xTE);
                        e = ue * ue * (3 - 2 * ue);
                    }
                    // the web on the shared law (fairWebZ), which the mold also parts on (user, with pictures of the
                    // mold: a web off the mold's parting was split by it)
                    const zw = tailOn ? fairWebZ(x / meter, xTE / meter, x1 / meter, zTE / meter, sTE, axisZ / meter) - zc / meter : (zTE - zc) / meter;
                    Lu = zw + hw;
                    Ll = zw - hw;
                    w = 1 - e;
                }
                const ru = fairSmin(r, 0.9 * (b - Lu));
                const rl = fairSmin(r, 0.9 * (b + Ll));
                const fu = fairSide(sq, a, b, Lu, ru, true, model, w, spread);
                const fl = fairSide(sq, a, b, Ll, rl, false, model, w, spread);
                if (fu == undefined || fl == undefined)
                {
                    ok = false;
                    break;
                }
                rUsed = max(rUsed, min(ru, rl));
                // the web's reach past the feet: only where the plan radius just behind the trailing edge widens it
                // (a point a hair past the foot made the fitted spline loop where it turns up the ellipse)
                const extra = 0;     // the plan radius at the trailing edge is its own spanwise sheet (a loft along X cannot turn tangent to the TE)
                const ye = max(fu.foot, fl.foot) + extra;
                if (x >= xTE)
                {
                    reach = max(reach, ye);
                    planEdge = append(planEdge, [x / meter, ye]);
                }
                if (tailOn && abs(x - (xTE + rp)) < 0.3 * millimeter)
                    footTail = ye;
                const zt = Lu + w * fairDrop(model, ye);
                const zb = Ll + w * fairDrop(model, ye);
                // where the trailing edge thins to the web, a side whose foot falls short of the other's carries on along
                // its own line to it: with Fairing spread the upper foot can land 20 mm further out, and the span line's
                // droop over that put it under the lower foot (the section crossed itself and the loft failed)
                const nearTE = x > xTE - 5 * millimeter;
                const webU = extra >= 0.5e-3 || (nearTE && ye - fu.foot >= 0.5e-3);
                const webL = extra >= 0.5e-3 || (nearTE && ye - fl.foot >= 0.5e-3);
                const M = 41;
                var top = [];
                for (var p in fairHalfCurve(sq, fu, a, b, true, ye, Lu, w, model, webU, M))
                    top = append(top, vector(p[0], p[1]) * meter);
                var bot = [];
                for (var p in fairHalfCurve(sq, fl, a, b, false, ye, Ll, w, model, webL, M))
                    bot = append(bot, vector(p[0], p[1]) * meter);
                const sid = id + ("fnSec" ~ k);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(x, 0 * meter, zc), X_DIRECTION, Y_DIRECTION) });
                skFitSpline(sk, "top", { "points" : top });
                skFitSpline(sk, "bot", { "points" : bot });
                skLineSegment(sk, "left", { "start" : top[size(top) - 1], "end" : bot[size(bot) - 1] });
                skLineSegment(sk, "right", { "start" : bot[0], "end" : top[0] });
                skSolve(sk);
                regions = append(regions, qSketchRegion(sid));
                sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
            }
            if (!ok)
                res = { "on" : 0, "note" : " | root fairing: not built (no fillet fits at " ~ stage ~ "), so the nacelle is plain" };
            else
            {
                stage = "the loft";
                var lofted = false;
                try silent
                {
                    opLoft(context, id + "nacelleLoft", { "profileSubqueries" : regions });
                    lofted = true;
                }
                if (size(sketches) > 0)
                    opDeleteBodies(context, id + "fnSketches", { "entities" : qUnion(sketches) });
                if (!lofted)
                    res = { "on" : 0, "note" : " | root fairing: not built (the loft failed), so the nacelle is plain - send this line" };
                if (lofted && tailOn && rp > 1 * millimeter && footTail > 0)
                {
                    // the plan radius where the tail leaves the trailing edge: a sheet lofted spanwise, each XZ section a
                    // thin strip at the trailing edge's height and droop from 0.5 mm inside the wing back to the quarter
                    // circle of radius rp tangent to the trailing edge and to the web's edge at rp behind it
                    stage = "the trailing-edge radius";
                    const hp = 0.8 * hw;
                    const rpm = rp / meter;
                    const yf = footTail;
                    var ys = [];
                    for (var k = 0; k <= 12; k += 1)
                        ys = append(ys, yf - 1e-3 + (rpm * 0.97 + 1e-3) * (1 - cos((PI / 2 * k / 12) * radian)));
                    var yAll = [];
                    for (var k = size(ys) - 1; k >= 0; k -= 1)
                        yAll = append(yAll, -ys[k]);
                    yAll = append(yAll, 0);
                    for (var y in ys)
                        yAll = append(yAll, y);
                    var pRegions = [];
                    var pSketches = [];
                    for (var k = 0; k < size(yAll); k += 1)
                    {
                        const ya = abs(yAll[k]);
                        const xBack = ya <= yf ? rpm : rpm - sqrt(max(0, rpm * rpm - (ya - yf - rpm) * (ya - yf - rpm)));
                        const yd = ya <= yf ? yf : ya;
                        // the strip along X: the web's centre (the trailing edge's height ahead of it) and the droop at
                        // this span, weighted as the web's is
                        var topP = [];
                        var botP = [];
                        for (var q = 0; q <= 8; q += 1)
                        {
                            const xq = xTE / meter - 0.5e-3 + (xBack + 0.5e-3) * q / 8;
                            var wq = 1;
                            if (xq > xTE / meter)
                            {
                                const uq = min(1, (xq - xTE / meter) / (x1 / meter - xTE / meter));
                                wq = 1 - uq * uq * (3 - 2 * uq);
                            }
                            const zq = fairWebZ(xq, xTE / meter, x1 / meter, zTE / meter, sTE, axisZ / meter) + wq * fairDrop(model, yd);
                            topP = append(topP, vector(xq, zq + hp) * meter);
                            botP = append(botP, vector(xq, zq - hp) * meter);
                        }
                        const sid = id + ("fnPlate" ~ k);
                        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, yAll[k] * meter, 0 * meter), -Y_DIRECTION, X_DIRECTION) });
                        skFitSpline(sk, "top", { "points" : topP });
                        skFitSpline(sk, "bot", { "points" : botP });
                        skLineSegment(sk, "front", { "start" : botP[0], "end" : topP[0] });
                        skLineSegment(sk, "back", { "start" : topP[8], "end" : botP[8] });
                        skSolve(sk);
                        pRegions = append(pRegions, qSketchRegion(sid));
                        pSketches = append(pSketches, qCreatedBy(sid, EntityType.BODY));
                    }
                    var plated = false;
                    try silent
                    {
                        opLoft(context, id + "nacellePlate", { "profileSubqueries" : pRegions });
                        plated = true;
                    }
                    opDeleteBodies(context, id + "fnPlateSketches", { "entities" : qUnion(pSketches) });
                    if (!plated)
                        plateNote = " (the trailing-edge radius did not loft)";
                }
            }
        }
        done = true;
    }
    if (!done)
        return { "on" : 0, "note" : " | root fairing: not built - it stopped at " ~ stage ~ ", so the nacelle is plain (send this line)" };
    if (res != undefined)
        return res;
    return { "on" : 1, "rMax" : rUsed, "x0" : x0 / meter, "x1" : x1 / meter,
             "web" : tailOn ? { "on" : 1, "x0" : xTE / meter, "x1" : x1 / meter, "z0" : zTEn, "s0" : sTE, "z1" : axisZ / meter, "reach" : reach + rp / meter + 1e-3,
                                  "xTE" : xTE / meter, "yf" : footTail, "rp" : rp / meter, "edge" : planEdge } : { "on" : 0 },
             "note" : " | root fairing: one loft with the nacelle, faired into the skin from X " ~ fmt(x0 / millimeter, 0) ~ " mm, radius up to " ~ fmt(rUsed * 1000, 1) ~ " mm" ~ (abs(spread - 1) > 1e-6 ? " up the nacelle, " ~ fmt(spread, 2) ~ " times that along the skin" : "") ~
                 (rUsed < rMax - 0.05e-3 ? " (held to 90 % of the nacelle's height out of the skin; Fairing radius " ~ fmt(rMax * 1000, 0) ~ ")" : "") ~
                 (tailOn ? ", full to the trailing edge and on " ~ fmt((x1 - xTE) / millimeter, 0) ~ " mm behind it as a tail: the trailing edge carried as a " ~ fmt(2 * hw * 1000, 1) ~
                     " mm web following its droop, leaving the trailing edge on a " ~ fmt(rp / millimeter, 0) ~ " mm radius seen from above" ~ plateNote :
                  ", easing to nothing " ~ fmt((xTE - x1) / millimeter, 0) ~ " mm ahead of the trailing edge") };
}

function ellipseSplines(sketch is Sketch, a is ValueWithUnits, b is ValueWithUnits, n is number)
{
    var upper = [];
    var lower = [];
    for (var k = 0; k <= n; k += 1)
    {
        const th = PI * k / n;
        upper = append(upper, vector(a * cos(th * radian), b * sin(th * radian)));
        lower = append(lower, vector(-a * cos(th * radian), -b * sin(th * radian)));
    }
    // force exact shared end points: upper runs (a,0) -> (-a,0), lower runs (-a,0) -> (a,0)
    upper[0] = vector(a, 0 * meter);
    upper[n] = vector(-a, 0 * meter);
    lower[0] = vector(-a, 0 * meter);
    lower[n] = vector(a, 0 * meter);
    skFitSpline(sketch, "upper", { "points" : upper });
    skFitSpline(sketch, "lower", { "points" : lower });
}

/**
 * Z of a section outline at X, by linear interpolation between consecutive points (the first
 * segment spanning X wins). pts are chord-scaled (X, Z) Vectors as returned by placeSection.
 */
function profileZAt(pts is array, x is ValueWithUnits) returns ValueWithUnits
{
    for (var i = 0; i < size(pts) - 1; i += 1)
    {
        const xa = pts[i][0];
        const xb = pts[i + 1][0];
        if (xa != xb && (x - xa) * (x - xb) <= 0 * meter * meter)
            return pts[i][1] + (x - xa) / (xb - xa) * (pts[i + 1][1] - pts[i][1]);
    }
    throw regenError("Mount pad or bolt reaches outside the stab root chord - move Flat start or Bolt 1 at toward the pivot, or shorten Bolt pitch", ["flatStart", "bolt1At", "boltPitch"]);
}

/** Horizontal cylinder along X, radius r, from x0 to x1, axis at (y, z) - two ellipseSplines sections lofted. Returns the loft id. */
function xCylinder(context is Context, baseId is Id, x0 is ValueWithUnits, x1 is ValueWithUnits, y is ValueWithUnits, z is ValueWithUnits, r is ValueWithUnits) returns Id
{
    const xs = [x0, x1];
    var regions = [];
    for (var i = 0; i < 2; i += 1)
    {
        const sid = baseId + ("s" ~ i);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(xs[i], y, z), X_DIRECTION, Y_DIRECTION) });
        ellipseSplines(sk, r, r, 24);
        skSolve(sk);
        regions = append(regions, qSketchRegion(sid));
    }
    const loftId = baseId + "loft";
    opLoft(context, loftId, { "profileSubqueries" : regions });
    return loftId;
}

/**
 * Wing root tube socket: a low-drag nacelle about an X axis through the root section's
 * mid-thickness at its thickest point. It starts there hidden inside the wing (full tube width,
 * 95 % of the wing thickness), eases up to a round section over Blend length, runs past the
 * trailing edge by Rear extension, and eases down onto the tube over Rear fairing. Unioned
 * with the wing, then a bore open at the rear face
 * and optional vertical pin holes cut through nacelle, wing and bore. The root section is rebuilt
 * with the same buildSection / placeSection calls buildFoil used, so the axis follows camber,
 * thickness and incidence. Returns { "model" : published map, "note" : notice text }.
 */
/**
 * D in plan: a semicircle of radius hw at the front (x0) and a square back at x1, lofted flat
 * between z0 and z1 (build 200: the back is square so the open pocket and the fuselage meet it
 * flat). The body is qCreatedBy(baseId + "loft", BODY); the sketches are deleted here.
 */
function hubStadium(context is Context, baseId is Id, x0 is ValueWithUnits, x1 is ValueWithUnits, hw is ValueWithUnits, z0 is ValueWithUnits, z1 is ValueWithUnits)
{
    var sketches = [];
    var regions = [];
    const zs = [z0, z1];
    for (var i = 0; i < 2; i += 1)
    {
        const sid = baseId + ("s" ~ i);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, 0 * meter, zs[i]), Z_DIRECTION, X_DIRECTION) });
        skLineSegment(sk, "s0", { "start" : vector(x0 + hw, -hw), "end" : vector(x1, -hw) });
        skLineSegment(sk, "a0", { "start" : vector(x1, -hw), "end" : vector(x1, hw) });
        skLineSegment(sk, "s1", { "start" : vector(x1, hw), "end" : vector(x0 + hw, hw) });
        skArc(sk, "a1", { "start" : vector(x0 + hw, hw), "mid" : vector(x0, 0 * meter), "end" : vector(x0 + hw, -hw) });
        skSolve(sk);
        regions = append(regions, qSketchRegion(sid));
        sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
    }
    opLoft(context, baseId + "loft", { "profileSubqueries" : regions });
    opDeleteBodies(context, baseId + "del", { "entities" : qUnion(sketches) });
}

/**
 * The skin's height under (x, y): a ray cast straight down onto the body. ok is false when the cast
 * itself failed (the caller falls back to fixed margins), hit is false when there is no body under
 * the point (off the wing's planform).
 */
function hubSkin(context is Context, body is Query, x is ValueWithUnits, y is ValueWithUnits) returns map
{
    var res = { "ok" : false, "hit" : false, "z" : 0 * meter };
    try silent
    {
        const hits = evRaycast(context, { "entities" : body, "ray" : line(vector(x, y, 1 * meter), vector(0, 0, -1)), "closest" : true });
        if (size(hits) > 0)
        {
            const z = hits[0].intersection[2];
            res = { "ok" : true, "hit" : true, "z" : z };
        }
        else
            res = { "ok" : true, "hit" : false, "z" : 0 * meter };
    }
    return res;
}

/**
 * The line the hub fairing's arc runs into and its section's bottom (m, world) at plan point (x, y), numbers in m:
 * ahead of the trailing edge 0.4 mm inside the top skin and the mid-thickness (the root section shifted by the span
 * line's drop), the bottom easing up to the trailing edge's height over its last 4 mm; behind it the web, the
 * trailing edge's upper half on its own height and droop, its bottom on the mold's parting.
 */
function hubFairLines(upper is array, lower is array, model is map, xTE is number, zTE is number, webT is number, x is number, y is number) returns array
{
    const d = fairDrop(model, abs(y));
    if (x <= xTE)
    {
        const su = profileZAtClamped(upper, x * meter) / meter + d;
        const sl = profileZAtClamped(lower, x * meter) / meter + d;
        const u = min(1, max(0, (x - (xTE - 4e-3)) / 4e-3));
        const bot = (su + sl) / 2 - webT * (1 - u * u * (3 - 2 * u));
        return [max(su - 0.4e-3, bot + webT), bot];
    }
    return [zTE + d + webT, zTE + d];
}

/**
 * One section of the hub fairing at the outline point (px, py) with outward normal (nx, ny), numbers in m: the arc
 * tangent to the wall (u 0) and to the line through its foot (its slope along the normal taken there), radius rLaw
 * held under 90 % of the wall's height above the line and its foot 3 mm behind the leading edge (0.3 mm at least);
 * a hub top under the line sinks the arc into the wing with it. The twin: hub_twin.py section().
 */
function hubFairSection(upper is array, lower is array, model is map, xTE is number, zTE is number, webT is number, xLE is number, zTop is number, rLaw is number,
    px is number, py is number, nx is number, ny is number, k is number) returns map
{
    const eps = 1e-3;
    const rmin = 0.3e-3;
    const hwall = zTop - hubFairLines(upper, lower, model, xTE, zTE, webT, px, py)[0];
    var r = hwall > 0 ? max(rmin, fairSmin(max(rLaw, rmin), 0.9 * hwall)) : rmin;
    if (nx < -1e-6)
        r = max(rmin, min(r, (px - xLE - 3e-3) / (-nx * k)));
    var uf = k * r;
    var s = 0;
    var La = 0;
    var zc = 0;
    var t = r;
    for (var it = 0; it < 3; it += 1)
    {
        const L0 = hubFairLines(upper, lower, model, xTE, zTE, webT, px + nx * uf, py + ny * uf)[0];
        const L1 = hubFairLines(upper, lower, model, xTE, zTE, webT, px + nx * (uf + 0.5e-3), py + ny * (uf + 0.5e-3))[0];
        s = (L1 - L0) / 0.5e-3;
        La = L0 - s * uf;
        // a circle in the space squeezed across by k (Fairing spread), where the line's slope is k s
        const ks = k * s;
        zc = La + ks * r + r * sqrt(1 + ks * ks);
        t = k * (r + ks * (zc - La)) / (1 + ks * ks);
        uf = t;
    }
    const sk = k * s;
    if (zc > zTop - 0.3e-3)
    {
        const sink = zc - (zTop - 0.3e-3);
        zc -= sink;
        La -= sink;
        t = k * (r + sk * (zc - La)) / (1 + sk * sk);
    }
    const footz = La + s * t;
    var ang1 = atan2(footz - zc, t / k - r) / radian;
    if (ang1 < PI)
        ang1 += 2 * PI;                            // the lower-left quarter: the concave side, round the corner
    const am = 0.5 * (PI + ang1);
    const na = min(12, max(3, round(r * (k + 1) / 1e-3) + 1));
    var arc = [];
    for (var j = 0; j < na; j += 1)
    {
        const ang = PI + (ang1 - PI) * j / (na - 1);
        arc = append(arc, [k * (r + r * cos(ang * radian)), zc + r * sin(ang * radian)]);
    }
    arc[0] = [0, zc];
    arc[na - 1] = [t, footz];
    const nb = min(9, max(3, round((t + eps) / 1.5e-3) + 1));
    var bots = [];
    for (var q = 0; q < nb; q += 1)
    {
        const u = -eps + (t + eps) * q / (nb - 1);
        bots = append(bots, [u, hubFairLines(upper, lower, model, xTE, zTE, webT, px + nx * u, py + ny * u)[1]]);
    }
    bots[nb - 1] = [t, min(bots[nb - 1][1], footz - 0.1e-3)];
    return { "r" : r, "zc" : zc, "foot" : t, "footz" : footz, "mid" : [k * (r + r * cos(am * radian)), zc + r * sin(am * radian)], "arc" : arc, "bots" : bots, "hwall" : hwall };
}

/**
 * The flat hub's root fairing (build 241, wing 1.064; twin designs/jason/tuning/fairing/hub_twin.py): one body lofted
 * along the hub's D in plan, from its back on one side, round the front, to its back on the other; every section
 * lies in the plane normal to the outline (YZ planes along the sides, radial planes round the front) and is the
 * region between the wall (0.3 mm inside it), a concave arc tangent to the wall and to a line 0.4 mm inside the skin,
 * its foot, and a bottom inside the wing (hubFairSection). With the hub running 5 mm or more past the trailing edge
 * the radius holds to the trailing edge and eases to nothing over Fairing tail, its line there the top of a web on
 * the trailing edge's height and droop (its bottom on the mold's parting), and a sheet lofted spanwise each side
 * gives the plan radius where the web leaves the trailing edge; otherwise it eases to nothing at the hub's back or
 * just ahead of the trailing edge. Returns on, rMax, reach (m from the centreline), note.
 */
function buildHubFairing(context is Context, id is Id, definition is map, m is map, upper is array, lower is array, x0v is ValueWithUnits, x1v is ValueWithUnits,
    hwv is ValueWithUnits, zTopv is ValueWithUnits, xLEv is ValueWithUnits, xTEv is ValueWithUnits, noseWall is number) returns map
{
    // noseWall: the pocket's front wall (m) when the nose fairing takes the hub's front (wing 1.070): the fairing then
    // runs the sides only, from the back to a section on the wall that the nose fairing shares; -1 otherwise
    const model = m.model;
    const x0 = x0v / meter;
    const x1 = x1v / meter;
    const hw = hwv / meter;
    const zTop = zTopv / meter;
    const xLE = xLEv / meter;
    const xTE = xTEv / meter;
    const xc = x0 + hw;
    const rMax = definition.fairingRadius / meter;
    const spread = definition.fairingSpread == undefined ? 1 : definition.fairingSpread;
    const zTE = (profileZAtClamped(upper, xTEv) + profileZAtClamped(lower, xTEv)) / 2 / meter;
    const webT = max(0.25e-3, 0.5 * definition.teThickness / meter);
    const tailLen = min(definition.fairingTail == undefined ? 0 : definition.fairingTail / meter, x1 - xTE);
    const tailOn = tailLen >= 5e-3;
    const xEnd = tailOn ? xTE + tailLen : min(x1, xTE) - 0.5e-3;
    const ease = tailOn ? 0 : max(10e-3, 0.25 * (xEnd - x0));
    if (xEnd - xc < 3e-3)
        return { "on" : 0, "note" : " | root fairing: not built - the hub's sides end within 3 mm of its rounded front" };
    var stage = "the outline";
    var res = undefined;
    var done = false;
    var rUsed = 0;
    var reach = hw;
    var plateNote = "";
    var pieceNote = "";
    var rp = 0;
    var yfT = hw;
    var planEdge = [];          // [x, half width] of the faired tail behind the trailing edge, for the mold's outline
    var sideFrom = -1;          // with the nose fairing on: where the sides start (the pocket's front wall, or the D's rear corner)
    try silent
    {
        // the outline: [plane origin x, angle phi of the outward normal], +y side from the back forward, round the
        // front, back along -y
        var xs = [];
        if (tailOn)
        {
            for (var k = 12; k >= 0; k -= 1)
                xs = append(xs, xTE + tailLen * k / 12);
            for (var k = 11; k >= 0; k -= 1)
                xs = append(xs, xc + (xTE - xc) * k / 12);
        }
        else
        {
            for (var k = 16; k >= 0; k -= 1)
                xs = append(xs, xc + (xEnd - xc) * k / 16);
        }
        if (x1 > xEnd + 0.5e-3)
            xs = concatenateArrays([[x1, 0.5 * (x1 + xEnd)], xs]);   // the wall strip on to the hub's back, the radius at its least
        var sx = [];
        for (var v in xs)
        {
            if (size(sx) == 0 || sx[size(sx) - 1] - v >= 0.5e-3)
                sx = append(sx, v);
        }
        // with the nose fairing on, the sides end on the pocket's front wall (or the D's rear corner when the wall is
        // ahead of it, as on the Standard hub), where the nose fairing's last section is this one
        sideFrom = noseWall > 0 ? max(noseWall, xc) : -1;
        if (sideFrom > 0)
        {
            var sxW = [];
            for (var v in sx)
            {
                if (v > sideFrom + 0.3e-3)
                    sxW = append(sxW, v);
            }
            sx = append(sxW, sideFrom);
        }
        else
            sx[size(sx) - 1] = xc;
        var path = [];
        for (var v in sx)
            path = append(path, [v, PI / 2]);
        for (var k = 1; k < 18; k += 1)
            path = append(path, [xc, PI / 2 + PI * k / 18]);
        for (var k = size(sx) - 1; k >= 0; k -= 1)
            path = append(path, [sx[k], 3 * PI / 2]);
        // the sections first; then one loft for each stretch where the hub stands 0.6 mm or more out of the line
        // (a hub sunk under the skin at its front has none there: build 241, the user's -10 mm test)
        var secs = [];
        for (var k = 0; k < size(path); k += 1)
        {
            const ox = path[k][0];
            const ph = path[k][1];
            const nx = abs(cos(ph * radian)) < 1e-12 ? 0 : cos(ph * radian);
            const ny = sin(ph * radian);
            const px = ox + hw * nx;
            const py = hw * ny;
            stage = "section " ~ k ~ " of " ~ (size(path) - 1) ~ " (X " ~ fmt(px * 1000, 1) ~ ", Y " ~ fmt(py * 1000, 1) ~ ")";
            var rL = rMax;
            if (tailOn && px > xTE)
            {
                const u = min(1, (px - xTE) / tailLen);
                rL = rMax * (1 - u * u * (3 - 2 * u));
            }
            if (px > xEnd)
                rL = 0;
            else if (!tailOn)
            {
                const u = min(1, max(0, (px - (xEnd - ease)) / ease));
                rL = rMax * (1 - u * u * (3 - 2 * u));
            }
            const f = hubFairSection(upper, lower, model, xTE, zTE, webT, xLE, zTop, rL, px, py, nx, ny, spread);
            if (ny > 0.999 && px >= xTE && f.hwall >= 0.6e-3)
                planEdge = append(planEdge, [px, hw + f.foot]);
            const onFront = sideFrom > 0 && (abs(ny) < 0.999 || px < sideFrom - 0.1e-3);   // the D front and anything ahead of the wall: the nose fairing's
            secs = append(secs, { "ox" : ox, "ph" : ph, "nx" : nx, "ny" : ny, "f" : f, "ok" : f.hwall >= 0.6e-3 && !onFront });
        }
        var runs = [];
        var cur = [];
        for (var k = 0; k < size(secs); k += 1)
        {
            if (secs[k].ok)
                cur = append(cur, k);
            if (!secs[k].ok || k == size(secs) - 1)
            {
                if (size(cur) >= 3)
                    runs = append(runs, cur);
                cur = [];
            }
        }
        var sketches = [];
        var nLoft = 0;
        var nFail = 0;
        for (var ri = 0; ri < size(runs); ri += 1)
        {
            var regions = [];
            for (var k in runs[ri])
            {
                const sc = secs[k];
                const f = sc.f;
                stage = "sketch " ~ k ~ " of " ~ (size(secs) - 1);
                rUsed = max(rUsed, f.r);
                reach = max(reach, hw + f.foot);
                const sid = id + ("hubFairSec" ~ k);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(sc.ox, 0, 0) * meter, vector(sin(sc.ph * radian), -cos(sc.ph * radian), 0), vector(sc.nx, sc.ny, 0)) });
                const nb = size(f.bots);
                // the outer 1 mm of the hub's wall, to its top, then the arc: the arc is tangent to this body's own wall
                // (a fillet body touching the hub's wall tangentially would not join it)
                skLineSegment(sk, "in", { "start" : vector(hw + f.bots[0][0], f.bots[0][1]) * meter, "end" : vector(hw + f.bots[0][0], zTop) * meter });
                skLineSegment(sk, "top", { "start" : vector(hw + f.bots[0][0], zTop) * meter, "end" : vector(hw, zTop) * meter });
                skLineSegment(sk, "wall", { "start" : vector(hw, zTop) * meter, "end" : vector(hw, f.zc) * meter });
                if (abs(spread - 1) < 1e-6)
                    skArc(sk, "arc", { "start" : vector(hw, f.zc) * meter, "mid" : vector(hw + f.mid[0], f.mid[1]) * meter, "end" : vector(hw + f.foot, f.footz) * meter });
                else
                {
                    var ap = [];
                    for (var q in f.arc)
                        ap = append(ap, vector(hw + q[0], q[1]) * meter);
                    skFitSpline(sk, "arc", { "points" : ap });     // a quarter ellipse, Fairing spread wide to 1 tall
                }
                skLineSegment(sk, "side", { "start" : vector(hw + f.foot, f.footz) * meter, "end" : vector(hw + f.bots[nb - 1][0], f.bots[nb - 1][1]) * meter });
                var bp = [];
                for (var j = nb - 1; j >= 0; j -= 1)
                    bp = append(bp, vector(hw + f.bots[j][0], f.bots[j][1]) * meter);
                skFitSpline(sk, "bot", { "points" : bp });
                skSolve(sk);
                regions = append(regions, qSketchRegion(sid));
                sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
            }
            stage = "the loft";
            try silent
            {
                opLoft(context, id + ("hubFairLoft" ~ ri), { "profileSubqueries" : regions });
                nLoft += 1;
            }
            catch
            {
                nFail += 1;
            }
        }
        if (size(sketches) > 0)
            opDeleteBodies(context, id + "hubFairSketches", { "entities" : qUnion(sketches) });
        const lofted = nLoft > 0;
        if (size(runs) == 0)
            res = { "on" : 0, "note" : " | root fairing: not built - the hub stands nowhere 0.6 mm out of the skin (raise Hub above apex)" };
        else if (!lofted)
            res = { "on" : 0, "note" : " | root fairing: not built (the loft failed), so the hub is square-cornered - send this line" };
        else if (nFail > 0)
            pieceNote = pieceNote ~ " (" ~ nFail ~ " of its " ~ size(runs) ~ " lofts failed - send this line)";
        if (size(runs) > 1)
            pieceNote = pieceNote ~ (sideFrom > 0 ? " (along the sides from the pocket's front wall, the nose fairing taking the front)" : " (in " ~ size(runs) ~ " pieces: the hub stands out of the skin only along its sides)");
        rp = tailOn ? min(rMax, 0.8 * tailLen) : 0;
        if (lofted && tailOn && rp > 1e-3)
        {
            // the plan radius where the web leaves the trailing edge: a sheet each side lofted spanwise, each XZ section
            // a strip inside the web (the trailing edge's upper half) from 0.5 mm inside the wing back to the quarter
            // circle of radius rp tangent to the trailing edge and to the web's edge at rp behind it
            stage = "the trailing-edge radius";
            const yf = hw + hubFairSection(upper, lower, model, xTE, zTE, webT, xLE, zTop, rMax * (1 - min(1, rp / tailLen) * min(1, rp / tailLen) * (3 - 2 * min(1, rp / tailLen))), xTE + rp, hw, 0, 1, spread).foot;
            var plated = 0;
            for (var side = 0; side < 2; side += 1)
            {
                const sg = side == 0 ? 1 : -1;
                var pRegions = [];
                var pSketches = [];
                for (var k = 0; k <= 12; k += 1)
                {
                    const ya = yf - 1e-3 + (rp * 0.97 + 1e-3) * (1 - cos((PI / 2 * k / 12) * radian));
                    const xBack = ya <= yf ? rp : rp - sqrt(max(0, rp * rp - (ya - yf - rp) * (ya - yf - rp)));
                    const zq = zTE + fairDrop(model, ya);
                    const xa = xTE - 0.5e-3;
                    const xb = xTE + max(xBack, 0.3e-3);
                    const sid = id + ("hubFairPlate" ~ side ~ "s" ~ k);
                    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0, sg * ya, 0) * meter, -Y_DIRECTION, X_DIRECTION) });
                    skLineSegment(sk, "bot", { "start" : vector(xa, zq + 0.1 * webT) * meter, "end" : vector(xb, zq + 0.1 * webT) * meter });
                    skLineSegment(sk, "back", { "start" : vector(xb, zq + 0.1 * webT) * meter, "end" : vector(xb, zq + 0.9 * webT) * meter });
                    skLineSegment(sk, "top", { "start" : vector(xb, zq + 0.9 * webT) * meter, "end" : vector(xa, zq + 0.9 * webT) * meter });
                    skLineSegment(sk, "front", { "start" : vector(xa, zq + 0.9 * webT) * meter, "end" : vector(xa, zq + 0.1 * webT) * meter });
                    skSolve(sk);
                    pRegions = append(pRegions, qSketchRegion(sid));
                    pSketches = append(pSketches, qCreatedBy(sid, EntityType.BODY));
                }
                try silent
                {
                    opLoft(context, id + ("hubFairPlate" ~ side), { "profileSubqueries" : pRegions });
                    plated += 1;
                }
                opDeleteBodies(context, id + ("hubFairPlateSk" ~ side), { "entities" : qUnion(pSketches) });
            }
            if (plated < 2)
                plateNote = " (the trailing-edge radius did not loft)";
            reach = max(reach, yf + rp);
            yfT = yf;
        }
        done = true;
    }
    if (!done)
    {
        try silent
        {
            opDeleteBodies(context, id + "hubFairStop", { "entities" : qUnion([qCreatedBy(id + "hubFairLoft0", EntityType.BODY), qCreatedBy(id + "hubFairLoft1", EntityType.BODY), qCreatedBy(id + "hubFairLoft2", EntityType.BODY), qCreatedBy(id + "hubFairLoft3", EntityType.BODY), qCreatedBy(id + "hubFairPlate0", EntityType.BODY), qCreatedBy(id + "hubFairPlate1", EntityType.BODY)]) });
        }
        return { "on" : 0, "note" : " | root fairing: not built - it stopped at " ~ stage ~ ", so the hub is square-cornered (send this line)" };
    }
    if (res != undefined)
        return res;
    return { "on" : 1, "rMax" : rUsed, "reach" : reach, "edge" : planEdge, "yf" : yfT, "rp" : tailOn ? rp : 0,
             "note" : (sideFrom > 0 ? " | root fairing along the hub's sides from the pocket's front wall (the nose fairing is the front): radius up to " : " | root fairing round the hub's sides and front: radius up to ") ~ fmt(rUsed * 1000, 1) ~ " mm" ~ (abs(spread - 1) > 1e-6 ? " up the wall, " ~ fmt(spread, 2) ~ " times that along the skin" : "") ~
                 (rUsed < rMax - 0.05e-3 ? " (held to 90 % of the wall's height above the skin; Fairing radius " ~ fmt(rMax * 1000, 0) ~ ")" : "") ~
                 ", its foot up to " ~ fmt(reach * 1000, 1) ~ " mm from the centreline" ~ pieceNote ~
                 (tailOn ? ", full to the trailing edge and on " ~ fmt(tailLen * 1000, 0) ~ " mm behind it on a " ~ fmt(webT * 1000, 2) ~ " mm web, the trailing edge's upper half on its own height, leaving the trailing edge on a " ~
                     fmt(rp * 1000, 0) ~ " mm radius seen from above" ~ plateNote :
                  ", easing to nothing by X " ~ fmt(xEnd * 1000, 0) ~ (x1 < xTE ? " mm, the hub's back" : " mm, just ahead of the trailing edge")) };
}

/**
 * The hub's nose fairing, properly faired (build 241, wing 1.070; twin designs/jason/tuning/fairing/nose_twin.py): a
 * production foil's nose - a ridge on the top skin ahead of the fuselage rising to the fuselage's top at the pocket's
 * front wall, its feet sweeping into the skin. One body lofted through YZ sections from a nose point (xF0) to the wall
 * (xW). Each section is a crown (a superellipse of half-width a and height H above the skin, exponent n: Top shape, 1 a
 * pointed ridge, 2 round, large flat) with a concave arc of radius r each side tangent to the crown's side and to a
 * line 0.4 mm inside the skin, squeezed across by Fairing spread, and a bottom 40 % of the thickness inside the wing.
 * The FOOT line is the plan: a superellipse (Nose fullness) from the nose to the root fairing's foot at the wall,
 * reached by the hub's front (x0) and held, so it is widest at the fuselage and runs on behind the wall; the crown's
 * edge keeps the wall's crown-to-foot ratio along the nose, and over the hub sits on the hub's full width (the block is
 * 0.5 mm narrower under the fairings) and as wide as its top needs to clear the hub's top; H rises as a smoothstep to
 * Nose height above the hub's top; n eases from Top shape over the first 70 % of the nose to flat at the wall, where
 * the last section is the root fairing's own wall section (hubFairSection at xW) with the bar's box on top, so the side
 * fairing runs on from it as one surface. Unioned with the wing. Returns on, vol (cm3), foot (the wall's, from the
 * centreline), warn, note.
 */
function buildNoseFairing(context is Context, id is Id, definition is map, m is map, upper is array, lower is array, xF0v is ValueWithUnits, xWv is ValueWithUnits,
    x0v is ValueWithUnits, hwv is ValueWithUnits, zTopv is ValueWithUnits, noseHv is ValueWithUnits, xLEv is ValueWithUnits, xTEv is ValueWithUnits, allSolid is Query) returns map
{
    const model = m.model;
    const xF0 = xF0v / meter;
    const xW = xWv / meter;
    const x0 = x0v / meter;
    const hw = hwv / meter;
    const zTop = zTopv / meter;
    const xLE = xLEv / meter;
    const xTE = xTEv / meter;
    const noseH = noseHv / meter;
    const rCrown = definition.hubNoseRound == undefined ? 0 : definition.hubNoseRound / meter;
    const nTop = definition.hubNoseShape == undefined ? 1.5 : definition.hubNoseShape;
    const mPlan = definition.hubNoseFull == undefined ? 1.5 : definition.hubNoseFull;
    const spread = definition.fairingSpread == undefined ? 1 : definition.fairingSpread;
    const rMax = definition.fairingRadius / meter;
    const zTE = (profileZAtClamped(upper, xTEv) + profileZAtClamped(lower, xTEv)) / 2 / meter;
    const webT = max(0.25e-3, 0.5 * definition.teThickness / meter);
    const nFlat = 12;
    const delta = 0.4e-3;
    // the root fairing's section on the wall: this body's last section is it with the bar's box on top
    const rootSec = hubFairSection(upper, lower, model, xTE, zTE, webT, xLE, zTop, rMax, xW, hw, 0, 1, spread);
    const fWall = hw + rootSec.foot;
    const zTopF = zTop + noseH;
    const nS = 12;
    var regions = [];
    var sketches = [];
    var gRidge = [];           // guide curves through the sections' vertices: the ridge, the crown's edges, the feet
    var gTanR = [];
    var gTanL = [];
    var gFootR = [];
    var gFootL = [];
    var built = false;
    var vol = 0;
    var warn = "";
    var stage = "the sections";
    try silent
    {
        // the nose: a point 0.3 mm under the skin, the loft's first profile, where every guide starts (a section there
        // folds the surface into a beak: the user's Ultra, 2026-10-12)
        stage = "the nose point";
        const zN = profileZAtClamped(upper, xF0v) / meter - 0.3e-3;
        var skN = newSketchOnPlane(context, id + "noseTip", { "sketchPlane" : plane(vector(xF0, 0, 0) * meter, X_DIRECTION, Y_DIRECTION) });
        skPoint(skN, "tip", { "position" : vector(0, zN) * meter });
        skSolve(skN);
        regions = append(regions, qCreatedBy(id + "noseTip", EntityType.VERTEX));
        sketches = append(sketches, qCreatedBy(id + "noseTip", EntityType.BODY));
        const tip = vector(xF0, 0, zN) * meter;
        gRidge = append(gRidge, tip);
        gTanR = append(gTanR, tip);
        gTanL = append(gTanL, tip);
        gFootR = append(gFootR, tip);
        gFootL = append(gFootL, tip);
        for (var k = 1; k <= nS; k += 1)
        {
            const x = xF0 + (xW - xF0) * k / nS;
            stage = "section " ~ k ~ " at X " ~ fmt(x * 1000, 1);
            const skin = profileZAtClamped(upper, x * meter) / meter;
            const thick = skin - profileZAtClamped(lower, x * meter) / meter;
            const bot = skin - 0.4 * thick;
            const sid = id + ("noseSec" ~ k);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(x, 0, 0) * meter, X_DIRECTION, Y_DIRECTION) });
            {
                // the laws along the nose (the twin's)
                // every section the same seven edges (two crown splines, two arc splines, two feet, the bottom), so the
                // loft matches them: the wall's is the root fairing's wall section as a near-box (n 12, a hw, r its own)
                // the foot line: a teardrop to the wall's foot (Nose fullness); the hub has no front of its own ahead
                // of the wall (its block starts there), so nothing has to be cleared
                const sH = (x - xF0) / (xW - xF0);
                var f = fWall * (1 - (1 - sH) ^ mPlan) ^ (1 / mPlan);
                f = max(f, 2.5e-3);                                      // the nose section 3 mm wide, not a sliver
                const Hw = zTopF - profileZAtClamped(upper, xWv) / meter;
                const H = 0.5e-3 + (Hw - 0.5e-3) * sH * sH * (3 - 2 * sH);
                const xN0 = x0 - 0.3 * (x0 - xF0);
                const sN = min(1, max(0, (x - xN0) / max(1e-9, xW - xN0)));
                const n = k == nS ? nFlat : nTop + (nFlat - nTop) * sN * sN * (3 - 2 * sN);
                const zL = skin - delta;
                const zA = skin + H;
                var a = (hw / fWall) * f;
                if (k == nS)
                    a = hw;
                a = max(1e-3, min(a, f - 0.6e-3));
                const r = max(0.3e-3, min(0.9 * H, (f - a) / spread));
                // the crown, apex to its foot at (a, zL): the superellipse (Top shape) along the nose, blending by arc
                // length into a rounded box (flat top, Crown round on the corner, a vertical side) at the wall, so the
                // back face's corners are the bar's or the hub body's
                const M = 24;
                var se = [];
                for (var j = 0; j <= 2 * M; j += 1)
                {
                    const t = j / (2 * M);
                    se = append(se, [a * t, zL + (zA - zL) * (1 - t ^ n) ^ (1 / n)]);
                }
                var cum = [0];
                for (var j = 1; j <= 2 * M; j += 1)
                    cum = append(cum, cum[j - 1] + sqrt((se[j][0] - se[j - 1][0]) ^ 2 + (se[j][1] - se[j - 1][1]) ^ 2));
                const rc = min(rCrown, min(0.9 * a, 0.9 * (zA - zL)));
                const lTop = a - rc;
                const lArc = rc * PI / 2;
                const lTot = lTop + lArc + (zA - rc - zL);
                const wB = sN * sN * (3 - 2 * sN);
                var cr = [];
                var jj = 1;
                for (var j = 0; j <= M; j += 1)
                {
                    // the superellipse at this fraction of its length
                    const sL = cum[2 * M] * j / M;
                    while (jj < 2 * M && cum[jj] < sL)
                        jj += 1;
                    const u = cum[jj] - cum[jj - 1] > 1e-12 ? (sL - cum[jj - 1]) / (cum[jj] - cum[jj - 1]) : 0;
                    const pS = [se[jj - 1][0] + u * (se[jj][0] - se[jj - 1][0]), se[jj - 1][1] + u * (se[jj][1] - se[jj - 1][1])];
                    // the rounded box at the same fraction of its length
                    const sB = lTot * j / M;
                    var pB = [a, zA - rc - (sB - lTop - lArc)];
                    if (sB <= lTop)
                        pB = [sB, zA];
                    else if (sB <= lTop + lArc)
                    {
                        const ang = (sB - lTop) / max(rc, 1e-9);
                        pB = [a - rc + rc * sin(ang * radian), zA - rc + rc * cos(ang * radian)];
                    }
                    cr = append(cr, [pS[0] + (pB[0] - pS[0]) * wB, pS[1] + (pB[1] - pS[1]) * wB]);
                }
                cr[0] = [0, zA];
                cr[M] = [a, zL];
                // the arc's centre at (yc, zL + r), where the crown's outward offset by r crosses that height
                var off = [];
                for (var j = 0; j <= M; j += 1)
                {
                    const p0 = cr[max(0, j - 1)];
                    const p1 = cr[min(M, j + 1)];
                    const dy = p1[0] - p0[0];
                    const dz = p1[1] - p0[1];
                    const ln = max(1e-12, sqrt(dy * dy + dz * dz));
                    off = append(off, [cr[j][0] - r * dz / ln, cr[j][1] + r * dy / ln]);
                }
                var i = 1;
                for (var j = M; j > 0; j -= 1)
                {
                    if (off[j][1] <= zL + r && zL + r <= off[j - 1][1])
                    {
                        i = j;
                        break;
                    }
                }
                const tt = (zL + r - off[i][1]) / max(1e-12, off[i - 1][1] - off[i][1]);
                const yc = off[i][0] + tt * (off[i - 1][0] - off[i][0]);
                const zc = zL + r;
                const yt = cr[i][0] + tt * (cr[i - 1][0] - cr[i][0]);
                const zt = cr[i][1] + tt * (cr[i - 1][1] - cr[i][1]);
                var ang0 = atan2(zt - zc, yt - yc) / radian;
                if (ang0 < 0)
                    ang0 += 2 * PI;
                const ang1 = 1.5 * PI;
                const na = 9;
                var arc = [];
                for (var j = 0; j < na; j += 1)
                {
                    const ang = ang0 + (ang1 - ang0) * j / (na - 1);
                    arc = append(arc, [yt + (yc + r * cos(ang * radian) - yt) * spread, zc + r * sin(ang * radian)]);
                }
                arc[0] = [yt, zt];
                const foot = arc[na - 1][0];
                arc[na - 1] = [foot, zL];
                gRidge = append(gRidge, vector(x, 0, zA) * meter);
                gTanR = append(gTanR, vector(x, yt, zt) * meter);
                gTanL = append(gTanL, vector(x, -yt, zt) * meter);
                gFootR = append(gFootR, vector(x, foot, zL) * meter);
                gFootL = append(gFootL, vector(x, -foot, zL) * meter);
                for (var sg = -1; sg <= 1; sg += 2)
                {
                    const tag = sg > 0 ? "R" : "L";
                    var cp = [];
                    for (var j = 0; j < i; j += 1)
                        cp = append(cp, vector(sg * cr[j][0], cr[j][1]) * meter);
                    cp = append(cp, vector(sg * yt, zt) * meter);
                    skFitSpline(sk, "crown" ~ tag, { "points" : cp });
                    var ap = [];
                    for (var q in arc)
                        ap = append(ap, vector(sg * q[0], q[1]) * meter);
                    skFitSpline(sk, "arc" ~ tag, { "points" : ap });
                    skLineSegment(sk, "foot" ~ tag, { "start" : vector(sg * foot, zL) * meter, "end" : vector(sg * (foot + 1e-3), bot) * meter });
                }
                skLineSegment(sk, "bot", { "start" : vector(-(foot + 1e-3), bot) * meter, "end" : vector(foot + 1e-3, bot) * meter });
            }
            skSolve(sk);
            regions = append(regions, qSketchRegion(sid));
            sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
        }
        // the guides hold the loft's surface along the ridge, the crown's edges and the feet (without them it twists
        // between the sections: lumpy on the user's Ultra, 2026-10-12)
        stage = "the guides";
        const guides = [["noseGRidge", gRidge], ["noseGTanR", gTanR], ["noseGTanL", gTanL], ["noseGFootR", gFootR], ["noseGFootL", gFootL]];
        var guideQ = [];
        for (var g in guides)
        {
            opFitSpline(context, id + g[0], { "points" : g[1] });
            guideQ = append(guideQ, qCreatedBy(id + g[0], EntityType.EDGE));
            sketches = append(sketches, qCreatedBy(id + g[0], EntityType.BODY));
        }
        stage = "the loft";
        var lofted = false;
        try silent
        {
            opLoft(context, id + "noseLoft", { "profileSubqueries" : regions, "guideSubqueries" : guideQ });
            lofted = true;
        }
        if (!lofted)
        {
            opLoft(context, id + "noseLoft", { "profileSubqueries" : regions });
            warn = " the nose fairing lofted without its guide curves (they would not take), so its surface may ripple between sections;";
        }
        vol = evVolume(context, { "entities" : qCreatedBy(id + "noseLoft", EntityType.BODY) }) / (centimeter ^ 3);
        stage = "the join";
        const noseQ = qCreatedBy(id + "noseLoft", EntityType.BODY);
        if (size(evCollision(context, { "tools" : noseQ, "targets" : qSubtraction(allSolid, noseQ) })) == 0)
        {
            opDeleteBodies(context, id + "noseOff", { "entities" : noseQ });
            warn = " the nose fairing did not meet the wing and was left out - send the console's WING_INPUTS line;";
        }
        else
        {
            opBoolean(context, id + "noseJoin", {
                        "tools" : allSolid,
                        "operationType" : BooleanOperationType.UNION
                    });
            built = true;
        }
    }
    catch
    {
        warn = " NOSE FAIRING FAILED at " ~ stage ~ " (left out) - send the console's WING_INPUTS line;";
        try silent
        {
            opDeleteBodies(context, id + "noseFailDel", { "entities" : qCreatedBy(id + "noseLoft", EntityType.BODY) });
        }
    }
    if (size(sketches) > 0)
        opDeleteBodies(context, id + "noseSketches", { "entities" : qUnion(sketches) });
    return { "on" : built ? 1 : 0, "vol" : vol, "foot" : fWall * meter, "warn" : warn, "note" : "" };
}

/**
 * A box in a YZ sketch (u = y, v = z): -a to a across, z0 to z1 up, its two top corners rounded at r (square when r
 * is under 0.05 mm). The hub body's first sections with the wing's nose fairing on (fuselage 5.008).
 */
function boxTopRound(sketch is Sketch, a is ValueWithUnits, z0 is ValueWithUnits, z1 is ValueWithUnits, r is ValueWithUnits)
{
    skLineSegment(sketch, "bot", { "start" : vector(-a, z0), "end" : vector(a, z0) });
    if (r > 0.05 * millimeter)
    {
        const c = 0.7071067811865476;
        skLineSegment(sketch, "sideR", { "start" : vector(a, z0), "end" : vector(a, z1 - r) });
        skArc(sketch, "cornerR", { "start" : vector(a, z1 - r), "mid" : vector(a - r + r * c, z1 - r + r * c), "end" : vector(a - r, z1) });
        skLineSegment(sketch, "top", { "start" : vector(a - r, z1), "end" : vector(-(a - r), z1) });
        skArc(sketch, "cornerL", { "start" : vector(-(a - r), z1), "mid" : vector(-(a - r + r * c), z1 - r + r * c), "end" : vector(-a, z1 - r) });
        skLineSegment(sketch, "sideL", { "start" : vector(-a, z1 - r), "end" : vector(-a, z0) });
    }
    else
    {
        skLineSegment(sketch, "sideR", { "start" : vector(a, z0), "end" : vector(a, z1) });
        skLineSegment(sketch, "top", { "start" : vector(a, z1), "end" : vector(-a, z1) });
        skLineSegment(sketch, "sideL", { "start" : vector(-a, z1), "end" : vector(-a, z0) });
    }
}

/**
 * A prism along X from xa to xb whose YZ section is the hub's V pocket (pocket true) or the tongue that fits it:
 * walls at +-hwP, the floor zSh at the walls falling (or rising) straight to zAp on the centreline, closed by a
 * line at zTopL; the shoulders rounded at rSh, the apex at rAp (0 sharp). The twin: tuning/hub_v/hub_v_twin.py. The
 * body is qCreatedBy(baseId, BODY); the sketch is deleted.
 */
function hubVPrism(context is Context, baseId is Id, xa is ValueWithUnits, xb is ValueWithUnits, hwP is ValueWithUnits, zSh is ValueWithUnits, zAp is ValueWithUnits,
    zTopL is ValueWithUnits, rSh is ValueWithUnits, rAp is ValueWithUnits, pocket is boolean)
{
    const sid = baseId + "sk";
    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(xa, 0 * meter, 0 * meter), X_DIRECTION, Y_DIRECTION) });
    const P = [vector(-hwP, zTopL), vector(-hwP, zSh), vector(0 * meter, zAp), vector(hwP, zSh), vector(hwP, zTopL)];
    const R = [0 * meter, rSh, rAp, rSh, 0 * meter];
    // each corner: where its arc leaves the incoming and joins the outgoing segment, and its mid-point
    var ins = [P[0]];
    var outs = [P[0]];
    var mids = [undefined];
    for (var i = 1; i < 4; i += 1)
    {
        const u = normalize(P[i - 1] - P[i]);
        const v = normalize(P[i + 1] - P[i]);
        const c = dot(u, v);
        const th = acos(max(-1, min(1, c)));
        if (R[i] < 0.05 * millimeter || th / radian > PI - 1e-6)
        {
            ins = append(ins, P[i]);
            outs = append(outs, P[i]);
            mids = append(mids, undefined);
            continue;
        }
        const t = R[i] / tan(th / 2);
        const bis = normalize(u + v);
        const cen = P[i] + bis * (R[i] / sin(th / 2));
        ins = append(ins, P[i] + u * t);
        outs = append(outs, P[i] + v * t);
        mids = append(mids, cen - bis * R[i]);
    }
    ins = append(ins, P[4]);
    outs = append(outs, P[4]);
    for (var i = 0; i < 4; i += 1)
    {
        skLineSegment(sk, "l" ~ i, { "start" : outs[i], "end" : ins[i + 1] });
        if (i + 1 < 4 && mids[i + 1] != undefined)
            skArc(sk, "a" ~ (i + 1), { "start" : ins[i + 1], "mid" : mids[i + 1], "end" : outs[i + 1] });
    }
    skLineSegment(sk, "top", { "start" : P[4], "end" : P[0] });
    skSolve(sk);
    opExtrude(context, baseId, { "entities" : qSketchRegion(sid), "direction" : X_DIRECTION, "endBound" : BoundingType.BLIND, "endDepth" : xb - xa });
    opDeleteBodies(context, baseId + "del", { "entities" : qCreatedBy(sid, EntityType.BODY) });
}

/**
 * Flat hub with a recessed pocket (build 185): a flat-topped hub blended onto the root (a rounded
 * rectangle in plan, rising from the root's mid-thickness to Hub height above the top skin), a
 * pocket recessed into its top for the fuselage's tongue, and blind holes from the pocket floor for
 * bolts that come down through the fuselage. Publishes foilWingHub; the socket map is off.
 *
 * The join fillet (build 195) is built where it cannot fail. A fillet of radius r needs a wall at
 * least r tall along its whole edge, and with the hub's top level with the apex the wall is 0 tall
 * at the front; so the hub is first built Hub fillet + margin taller than any skin under it, the
 * part of it below the skin is thrown away (the block minus a copy of the wing, keeping the piece
 * that reaches the top), the rest is unioned onto the wing - the join is then one closed loop on
 * the top skin, walls tall everywhere, the best case a fillet has - the loop is filleted, and the
 * top is cut back to Hub above apex with a box that has the wing's shape removed from it. Where
 * the wall was shorter than the radius the cut leaves the fillet's lower arc: the top fades into
 * the skin through a flare instead of a step. The filleted block stops Hub fillet + 2.5 mm ahead of
 * the trailing edge (checked on the real skin by ray casts at the fillet's feet, walked forward
 * until every foot lands on the wing); the rest of the hub, on the thin trailing edge and beyond
 * it, is a plain block with its underside level with the trailing edge, joined afterwards.
 *
 * Build 235: Bolts from = Wing underside (Custom hub) makes the holes clearance holes from the lower
 * skin to the pocket floor, countersunk in the lower skin, and reports the laminate between each
 * countersink and the floor; Nose fairing adds a hump ahead of the pocket for a bar's square nose,
 * built after the pocket so its back face is the pocket's front wall. foilWingHub carries boltSide,
 * underZ (where each hole enters), cskDepth, tapDia, boltDia and noseOn / noseX0 / noseX1 / noseTopZ.
 */
/** The hub's dimensions as built: the standard's fixed numbers, or the dialog's (Custom). Position fields and the nose fairing pass through. */
function hubEffective(definition is map) returns map
{
    if (definition.hubStd == undefined || definition.hubStd == HubStandard.CUSTOM)
        return definition;
    var d = definition;
    d.hubWidth = 40 * millimeter;
    d.hubLength = 92 * millimeter;
    d.hubFillet = 3 * millimeter;
    d.pocketWidth = 24 * millimeter;
    d.pocketLength = 70 * millimeter;
    d.pocketFrom = 20 * millimeter;
    d.pocketDepth = 5 * millimeter;
    d.pocketClear = 0.15 * millimeter;
    d.hubBolts = 3;
    d.hubHoleDia = 0 * millimeter;
    d.hubBoltPitch = 20 * millimeter;
    d.hubBolt1From = 15 * millimeter;
    d.hubHoleDepth = 10 * millimeter;
    d.hubBoltSide = HubBoltSide.FUSELAGE;             // the standard's bolts come down through the fuselage (build 235)
    return d;
}

function buildWingHub(context is Context, id is Id, rawDefinition is map, m is map) returns map
{
    const definition = hubEffective(rawDefinition);
    const c0 = m.rootChord;
    const n = definition.pointsPerSurface;
    const pf = pivotFraction(definition.pivot);
    const teLocal = min(definition.teThickness, 0.03 * c0);
    const sec = buildSection(definition, definition.rootThickness / 100, teLocal / c0, n);
    const pts = placeSection(sec, c0, pf, cos(definition.incidence), sin(definition.incidence));
    var upper = [];
    var lower = [];
    for (var i = 0; i < n; i += 1)
        upper = append(upper, pts[i]);
    for (var i = n - 1; i < size(pts); i += 1)
        lower = append(lower, pts[i]);
    const xLE = -pf * c0;
    const xTE = (1 - pf) * c0;
    // the apex: the highest point of the top skin, and the mid-thickness at the thickest point
    var zApex = -1 * meter;
    var xApex = 0 * meter;
    var zMid = 0 * meter;
    var bestT = 0 * meter;
    for (var k = 1; k < 120; k += 1)
    {
        const x = xLE + c0 * k / 120;
        const zu = profileZAt(upper, x);
        const zl = profileZAt(lower, x);
        if (zu > zApex)
        {
            zApex = zu;
            xApex = x;
        }
        if (zu - zl > bestT)
        {
            bestT = zu - zl;
            zMid = 0.5 * (zu + zl);
        }
    }
    const hw = definition.hubWidth / 2;
    const fairOn = definition.rootFairing == true;
    const rF = fairOn ? 0 * meter : definition.hubFillet;    // the root fairing (build 241) takes the join fillet's place
    if (definition.hubLength < hw + 2 * millimeter)
        throw regenError("Hub length must be at least half Hub width + 2 mm: the hub's front is a semicircle of half its width", ["hubLength", "hubWidth"]);
    // the hub starts at the apex and runs aft, its top level with the apex (user: no higher than the
    // root profile, and only behind its highest point). Held far enough behind the leading edge for
    // the front fillet's foot, and ahead of the trailing edge
    var x0 = xApex + definition.hubFromApex;
    var placeNote = "";
    const xFrontMin = xLE + rF + 4 * millimeter;
    if (x0 < xFrontMin)
    {
        placeNote = placeNote ~ " (moved aft to X " ~ fmt(xFrontMin / millimeter, 0) ~ " mm: the front of the hub was within Hub fillet + 4 mm of the leading edge)";
        x0 = xFrontMin;
    }
    if (x0 > xTE - hw - 2 * millimeter)
        throw regenError("Hub from apex puts the hub's front behind the trailing edge", ["hubFromApex"]);
    var x1 = x0 + definition.hubLength;                // may run past the trailing edge as a block
    const zTop = zApex + definition.hubHeight;
    const pDepth = definition.pocketDepth;
    // the pocket floor's V (build 241): vd > 0 a groove (the centreline below the walls' floor), < 0 a ridge. The
    // centreline, where the bolts are, stays at Pocket depth: a groove raises the floor at the walls by V depth
    // instead of sinking the centre (user: keep the depth below the bolts), a ridge raises the centre
    const vOn = definition.hubFloor != undefined && definition.hubFloor != HubFloor.FLAT;
    var vNote = "";
    var vWarn = "";
    var vd = 0 * meter;
    if (vOn)
    {
        vd = definition.hubFloor == HubFloor.VGROOVE ? definition.hubVDepth : -definition.hubVDepth;
        if (abs(vd) > pDepth - 0.5 * millimeter)
        {
            vNote = " (V " ~ (vd > 0 * meter ? "groove" : "ridge") ~ " held to " ~ fmt((pDepth - 0.5 * millimeter) / millimeter, 1) ~ " mm, Pocket depth less 0.5)";
            vd = (vd > 0 * meter ? 1 : -1) * (pDepth - 0.5 * millimeter);
        }
        if (vd > 0 * meter && pDepth - vd < 1.5 * millimeter)
            vWarn = " the V groove leaves the pocket's walls only " ~ fmt((pDepth - vd) / millimeter, 1) ~ " mm tall at its sides (the tongue's edges are thin there and the walls barely locate it): a smaller V depth or a deeper Pocket depth;";
        if (vd < 0 * meter && pDepth + vd < 1.5 * millimeter)
            vWarn = " the V ridge leaves the pocket only " ~ fmt((pDepth + vd) / millimeter, 1) ~ " mm deep over its crest (the tongue is that thin over the bolts): a smaller V depth or a deeper Pocket depth;";
    }
    const vr = vOn ? definition.hubVFillet : 0 * meter;
    const floorC = vd > 0 * meter ? zTop - pDepth : zTop - pDepth - vd;   // the floor on the centreline, where the bolts are
    const zFloor = floorC + vd;                       // the floor at the walls
    const floorMin = min(zFloor, floorC);
    // underside: flat, level with the trailing edge (its mid-thickness, user build 188), or 0.3 mm
    // above the lower skin where a reflexed section rises past that
    var zBot = 0.5 * (profileZAt(upper, xTE - 0.5 * millimeter) + profileZAt(lower, xTE - 0.5 * millimeter));
    var zLowMin = zBot;
    if (x0 < xTE - 1 * millimeter)
    {
        for (var k = 0; k <= 40; k += 1)
        {
            const x = x0 + (xTE - 1 * millimeter - x0) * k / 40;
            if (x > xLE + 0.5 * millimeter && x < xTE - 0.5 * millimeter)
            {
                const zl = profileZAt(lower, x);
                zBot = max(zBot, zl + 0.3 * millimeter);
                zLowMin = min(zLowMin, zl);
            }
        }
    }
    // a top sunk below the section's centre takes the underside down with it: 4 mm of floor under
    // the pocket stays behind the trailing edge (build 200)
    var sunkNote = "";
    if (floorMin - 4 * millimeter < zBot)
    {
        zBot = floorMin - 4 * millimeter;
        zLowMin = min(zLowMin, zBot);
        sunkNote = " (underside dropped to Z " ~ fmt(zBot / millimeter, 1) ~ " mm for 4 mm of floor under the pocket)";
    }

    // ---- the wing as it stands, and a copy of it for the ray casts and the cut-back tool ----
    const wingBodies = evaluateQuery(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID));
    const wingQ = qUnion(wingBodies);
    opPattern(context, id + "hubWingCopy", {
                "entities" : wingQ,
                "transforms" : [identityTransform()],
                "instanceNames" : ["c"]
            });
    const wingCopy = qCreatedBy(id + "hubWingCopy", EntityType.BODY);
    const allSolid = qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID);

    // ---- the join fillet, built where it cannot fail (see the comment above) ----
    var filletNote = "";
    var rUsed = 0 * meter;
    var xEnd = x1;                                      // where the filleted block ends
    var filletBuilt = false;
    var rayOk = true;
    if (rF > 0.05 * millimeter && definition.mirror)
    {
        const foot = rF + 2 * millimeter;               // the fillet's foot on the skin, plus a margin
        const ys = [0 * meter, hw, -hw, hw + foot, -hw - foot];
        // the front: every foot ahead of the semicircle must land on the wing; else the hub moves aft
        var shift = 0 * meter;
        for (var t = 0; t < 30; t += 1)
        {
            var allHit = true;
            for (var y in ys)
            {
                const p = hubSkin(context, wingCopy, x0 + shift - foot, y);
                if (!p.ok)
                {
                    rayOk = false;
                    break;
                }
                if (!p.hit)
                    allHit = false;
            }
            if (!rayOk || allHit)
                break;
            shift += 2 * millimeter;
        }
        if (rayOk && shift > 0 * meter)
        {
            placeNote = placeNote ~ " (moved aft " ~ fmt(shift / millimeter, 0) ~ " mm so the front fillet stays on the top skin)";
            x0 += shift;
            x1 = x0 + definition.hubLength;
        }
        // the rear: the filleted block ends Hub fillet + 2.5 mm ahead of the trailing edge, walked
        // forward until every foot behind it lands on the wing (the local trailing edge at the
        // hub's sides may be ahead of the root's)
        xEnd = min(x1, xTE - foot - 0.5 * millimeter);
        for (var t = 0; t < 40; t += 1)
        {
            if (!rayOk)
                break;
            var allHit = true;
            for (var y in ys)
            {
                const p = hubSkin(context, wingCopy, xEnd + foot, y);
                if (!p.ok)
                {
                    rayOk = false;
                    break;
                }
                if (!p.hit)
                    allHit = false;
            }
            if (!rayOk || allHit)
                break;
            xEnd -= 2 * millimeter;
        }
        if (!rayOk)
            xEnd = min(x1, xTE - foot - 8 * millimeter);
        // how high the skin reaches under the hub, for the tall block's top
        var zSkinMax = -1 * meter;
        if (rayOk)
        {
            const xs = [x0 - foot, x0, x0 + hw, 0.5 * (x0 + xEnd), xEnd, xEnd + foot];
            for (var x in xs)
            {
                for (var y in ys)
                {
                    const p = hubSkin(context, wingCopy, x, y);
                    if (p.ok && p.hit)
                        zSkinMax = max(zSkinMax, p.z);
                }
            }
        }
        const mTall = rayOk && zSkinMax > -0.9 * meter ? max(zSkinMax + foot - zTop, foot) : foot + 8 * millimeter + max(0 * meter, -definition.hubHeight);
        if (xEnd < x0 + hw + 1 * millimeter)
            filletNote = " (no join fillet: the hub starts too close to the trailing edge for one; move it forward with Hub from apex)";
        else
        {
            const flatRear = xEnd < x1 - 0.01 * millimeter;       // the filleted block ends with a flat wall inside the hub
            const zLow = zLowMin - 15 * millimeter;
            hubStadium(context, id + "hubTall", x0, xEnd, hw, zLow, zTop + mTall);   // a D to xEnd: square there whether that is inside the hub or its back
            // the block minus the wing: the piece reaching the top is the part of the hub above the skin
            opBoolean(context, id + "hubTallCut", {
                        "targets" : qSubtraction(allSolid, qUnion([wingQ, wingCopy])),
                        "tools" : wingCopy,
                        "operationType" : BooleanOperationType.SUBTRACTION,
                        "keepTools" : true
                    });
            const pieces = evaluateQuery(context, qSubtraction(allSolid, qUnion([wingQ, wingCopy])));
            var upperPiece;
            var zBest = -1 * meter;
            var zBestMin = 0 * meter;
            var others = [];
            for (var b in pieces)
            {
                const bx = evBox3d(context, { "topology" : b, "tight" : true });
                if (bx.maxCorner[2] > zBest)
                {
                    if (upperPiece != undefined)
                        others = append(others, upperPiece);
                    zBest = bx.maxCorner[2];
                    zBestMin = bx.minCorner[2];
                    upperPiece = b;
                }
                else
                    others = append(others, b);
            }
            if (size(others) > 0)
                opDeleteBodies(context, id + "hubTallLower", { "entities" : qUnion(others) });
            if (upperPiece == undefined || zBestMin < zLow + 1 * millimeter)
            {
                // the block was not split by the wing (it is off the wing somewhere): no loop to fillet
                if (upperPiece != undefined)
                    opDeleteBodies(context, id + "hubTallOff", { "entities" : upperPiece });
                filletNote = " (no join fillet: the hub's plan runs off the wing; shorten Hub width or move it with Hub from apex)";
            }
            else
            {
                opBoolean(context, id + "hubJoin", {
                            "tools" : qUnion([wingQ, upperPiece]),
                            "operationType" : BooleanOperationType.UNION
                        });
                // the join: every edge the union made inside the block's plan, less any fragment of
                // the wing's own centre seam (Y extent nil at Y 0)
                const xBlockEnd = flatRear ? xEnd : x1;
                var loop = [];
                for (var ed in evaluateQuery(context, qCreatedBy(id + "hubJoin", EntityType.EDGE)))
                {
                    const eb = evBox3d(context, { "topology" : ed, "tight" : true });
                    const seam = eb.maxCorner[1] - eb.minCorner[1] < 0.05 * millimeter && abs(eb.maxCorner[1]) < 0.05 * millimeter;
                    if (!seam && eb.minCorner[0] > x0 - 1 * millimeter && eb.maxCorner[0] < xBlockEnd + 1 * millimeter && abs(eb.minCorner[1]) < hw + 1 * millimeter && abs(eb.maxCorner[1]) < hw + 1 * millimeter)
                        loop = append(loop, ed);
                }
                const ladder = [rF, 0.6 * rF, 0.35 * rF];
                var a = 0;
                if (size(loop) == 0)
                    filletNote = " (no join fillet: no join edges found - send the console's WING_INPUTS line)";
                else
                {
                    for (var k = 0; k < size(ladder); k += 1)
                    {
                        if (rUsed > 0 * meter || ladder[k] < 0.3 * millimeter)
                            continue;
                        try silent
                        {
                            opFillet(context, id + ("hubFillet" ~ k), { "entities" : qUnion(loop), "radius" : ladder[k], "tangentPropagation" : false });
                            rUsed = ladder[k];
                            a = k;
                        }
                    }
                    if (rUsed > 0 * meter)
                    {
                        filletBuilt = true;
                        filletNote = ", " ~ fmt(rUsed / millimeter, 1) ~ " mm fillet round the join" ~ (a > 0 ? " (held below Hub fillet: " ~ fmt(rF / millimeter, 0) ~ " mm failed)" : "") ~
                            (flatRear ? " to X " ~ fmt(xEnd / millimeter, 0) ~ " mm, " ~ fmt((xTE - xEnd) / millimeter, 0) ~ " mm ahead of the trailing edge (square from there)" : "");
                    }
                    else
                        filletNote = " (JOIN FILLET FAILED at " ~ fmt(rF / millimeter, 0) ~ ", " ~ fmt(0.6 * rF / millimeter, 1) ~ " and " ~ fmt(0.35 * rF / millimeter, 1) ~ " mm: left sharp - send the console's WING_INPUTS line)";
                }
                // cut the top back to Hub above apex, and the fillet's material behind the flat rear
                // wall, with tools that have the wing's own shape removed so the skin is never touched
                var cutQs = [qCreatedBy(id + "hubCutTop", EntityType.BODY)];
                moldBox(context, id + "hubCutTop", vector(x0 - foot - 3 * millimeter, -hw - foot - 3 * millimeter, zTop), vector(xBlockEnd + foot + 3 * millimeter, hw + foot + 3 * millimeter, zTop + mTall + 5 * millimeter));
                if (flatRear)
                {
                    moldBox(context, id + "hubCutRear", vector(xEnd, -hw - foot - 3 * millimeter, zLow), vector(xEnd + foot + 3 * millimeter, hw + foot + 3 * millimeter, zTop + mTall + 5 * millimeter));
                    cutQs = append(cutQs, qCreatedBy(id + "hubCutRear", EntityType.BODY));
                }
                setAttribute(context, { "entities" : qUnion(cutQs), "name" : "foilHubTool", "attribute" : 1 });
                const toolQ = qUnion(append(cutQs, qHasAttribute("foilHubTool")));
                opBoolean(context, id + "hubCutShape", {
                            "targets" : toolQ,
                            "tools" : wingCopy,
                            "operationType" : BooleanOperationType.SUBTRACTION,
                            "keepTools" : true
                        });
                opBoolean(context, id + "hubCutBack", {
                            "targets" : qSubtraction(allSolid, qUnion([wingCopy, toolQ])),
                            "tools" : toolQ,
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
            }
        }
    }
    else if (rF > 0.05 * millimeter)
        filletNote = " (no join fillet: it needs the mirrored wing)";
    else if (fairOn)
        filletNote = " (no join fillet: the root fairing takes its place)";
    opDeleteBodies(context, id + "hubWingCopyDel", { "entities" : wingCopy });
    // the rest of the hub - all of it when there is no fillet - as a plain block, underside level
    // with the trailing edge
    if (!filletBuilt || x1 > xEnd + 0.01 * millimeter)
    {
        // with the root fairing its body carries the hub's outer wall: the block stands 0.5 mm inside it (build 241)
        const shrink = fairOn && definition.mirror ? 0.5 * millimeter : 0 * meter;
        if (definition.hubNoseOn == true && fairOn && definition.mirror)
        {
            // the nose fairing is the hub's front (wing 1.070, the user: "just remove the front of the hub, this is a
            // new front"): the block runs from 1 mm ahead of the pocket's front wall back, square at the front
            moldBox(context, id + "hubRear", vector(x0 + definition.pocketFrom - definition.pocketClear - 1 * millimeter, -(hw - shrink), zBot), vector(x1, hw - shrink, zTop));
        }
        else
            hubStadium(context, id + "hubRear", x0 + shrink, x1, hw - shrink, zBot, zTop);
        if (filletBuilt)
        {
            moldBox(context, id + "hubRearTrim", vector(x0 - 5 * millimeter, -hw - 5 * millimeter, zBot - 5 * millimeter), vector(xEnd - 1 * millimeter, hw + 5 * millimeter, zTop + 5 * millimeter));
            opBoolean(context, id + "hubRearTrimCut", {
                        "targets" : qCreatedBy(id + "hubRear" + "loft", EntityType.BODY),
                        "tools" : qCreatedBy(id + "hubRearTrim", EntityType.BODY),
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
        }
        opBoolean(context, id + "hubRearJoin", {
                    "tools" : allSolid,
                    "operationType" : BooleanOperationType.UNION
                });
    }
    // the root fairing round the hub's sides and front (build 241, wing 1.064)
    var fair = { "on" : 0, "note" : "" };
    if (fairOn)
    {
        if (!definition.mirror)
            fair = { "on" : 0, "note" : " | root fairing: not built - it needs the mirrored wing" };
        else
        {
            const noseWallX = definition.hubNoseOn == true ? (x0 + definition.pocketFrom - definition.pocketClear) / meter : -1;
            fair = buildHubFairing(context, id, definition, m, upper, lower, x0, x1, hw, zTop, xLE, xTE, noseWallX);
            if (fair.on == 1)
            {
                var fairJoined = false;
                try silent
                {
                    opBoolean(context, id + "hubFairJoin", {
                                "tools" : allSolid,
                                "operationType" : BooleanOperationType.UNION
                            });
                    fairJoined = true;
                }
                if (!fairJoined)
                {
                    try silent
                    {
                        opDeleteBodies(context, id + "hubFairDel", { "entities" : qUnion([qCreatedBy(id + "hubFairLoft0", EntityType.BODY), qCreatedBy(id + "hubFairLoft1", EntityType.BODY), qCreatedBy(id + "hubFairLoft2", EntityType.BODY), qCreatedBy(id + "hubFairLoft3", EntityType.BODY), qCreatedBy(id + "hubFairPlate0", EntityType.BODY), qCreatedBy(id + "hubFairPlate1", EntityType.BODY)]) });
                    }
                    fair = { "on" : 0, "note" : " | root fairing: not built (it would not join the wing), so the hub is square-cornered and 1 mm narrower - send this line" };
                }
            }
        }
    }
    // pocket: a recess in the top face, the tongue plus the clearance each side, from its front wall
    // out through the hub's square back (build 200: open, part of the fuselage interface)
    const cl = definition.pocketClear;
    const px0 = x0 + definition.pocketFrom;
    if (px0 > x1 - 10 * millimeter)
        throw regenError("Pocket from puts the pocket's front wall within 10 mm of the hub's back", ["pocketFrom", "hubLength"]);
    const px1 = x1;
    const pw = definition.pocketWidth / 2 + cl;
    // bolts from the wing's underside (build 235): where each hole enters, read off the wing by a ray
    // cast up its axis (0.3 mm off the centre seam) before any tool exists - the lower skin, or the
    // hub's flat underside behind the trailing edge; the root section's lower skin if the cast fails
    const nuts = definition.hubBoltSide != undefined && definition.hubBoltSide == HubBoltSide.NUTS;
    const under = (definition.hubBoltSide != undefined && definition.hubBoltSide == HubBoltSide.UNDERSIDE) || nuts;   // through holes from the underside
    var underAt = [];
    var underRayMiss = 0;
    if (under)
    {
        for (var j = 0; j < definition.hubBolts; j += 1)
        {
            const bx = px0 + definition.hubBolt1From + j * definition.hubBoltPitch;
            const inC = bx > xLE + 0.5 * millimeter && bx < xTE - 0.5 * millimeter;
            const zNom = inC ? profileZAtClamped(lower, bx) : zBot;
            const ray = moldRayZ(context, allSolid, bx, 0.3 * millimeter, -1 * meter, true);
            const good = ray.hit && ray.z < floorC - 0.5 * millimeter && ray.z > zNom - 10 * millimeter;
            if (!good)
                underRayMiss += 1;
            underAt = append(underAt, good ? ray.z : zNom);
        }
    }
    var toolIds = [];
    var sketches = [];
    if (vOn)
        hubVPrism(context, id + "hubPocket", px0 - cl, x1 + 1 * millimeter, pw, zFloor, floorC, zTop + 1 * millimeter, vr, vr, true);
    else
        moldBox(context, id + "hubPocket", vector(px0 - cl, -pw, zFloor), vector(x1 + 1 * millimeter, pw, zTop + 1 * millimeter));
    // a floor sunk below the lower skin would open the pocket through the wing
    var floorNote = "";
    for (var k = 0; k <= 20; k += 1)
    {
        const x = px0 + (x1 - px0) * k / 20;
        if (x > xLE + 0.5 * millimeter && x < xTE - 0.5 * millimeter && floorMin < profileZAt(lower, x) + 1.5 * millimeter && floorNote == "")
            floorNote = " the pocket floor (Z " ~ fmt(floorMin / millimeter, 1) ~ ") is within 1.5 mm of the lower skin at X " ~ fmt(x / millimeter, 0) ~ " - the pocket breaks through the wing there (raise Hub above apex or shallow the pocket);";
    }
    toolIds = append(toolIds, id + "hubPocket");
    // the holes, on the centreline: blind from the pocket floor for bolts down through the fuselage, or
    // (build 235) clearance holes from the wing's underside to the pocket floor with a 90 deg countersink
    // in the lower skin to the head diameter, the flat mount's holes upside down
    const tap = definition.hubBolt == BoltSize.CUSTOM ? 5 * millimeter : boltDims(definition.hubBolt).tap * millimeter;
    const clearD = definition.hubBolt == BoltSize.CUSTOM ? (definition.hubHoleDia > 0.5 * millimeter ? definition.hubHoleDia : 6.4 * millimeter) : boltDims(definition.hubBolt).clear * millimeter;
    const holeD = under ? clearD : (definition.hubHoleDia > 0.5 * millimeter ? definition.hubHoleDia : tap);
    const headR = boltHead(definition.hubBolt, clearD) / 2;
    const cskD = nuts ? 0 * meter : headR - clearD / 2;
    // nut inserts (build 241): the barrel's bore and the flange's flush recess, from the underside
    const nutFit = nuts ? definition.hubNutFit : 0 * meter;
    const nutR = nuts ? definition.hubNutDia / 2 + nutFit / 2 : 0 * meter;
    const nutL = nuts ? definition.hubNutLen : 0 * meter;
    const nutFR = nuts ? definition.hubNutFlange / 2 + nutFit / 2 : 0 * meter;
    const nutFT = nuts ? definition.hubNutFlangeT : 0 * meter;
    var boltXs = [];
    var underZs = [];
    var wallNote = "";
    var minWall = 1 * meter;
    for (var j = 0; j < definition.hubBolts; j += 1)
    {
        const bx = px0 + definition.hubBolt1From + j * definition.hubBoltPitch;
        if (bx + holeD / 2 > x1 - 2 * millimeter)
        {
            wallNote = wallNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ " is past the hub's back (shorten Bolt pitch or Bolt 1 from);";
            continue;
        }
        const base = id + ("hubHole" ~ j);
        if (nuts)
        {
            // through hole for the bolt; from the underside the insert's bore and its flange's flush recess. The
            // laminate between the insert's top and the pocket floor is what the bolt clamps
            const zU = underAt[j];
            const wall = floorC - (zU + nutFT + nutL);
            minWall = min(minWall, wall);
            if (wall < 1 * millimeter)
                wallNote = wallNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ ": the nut insert's top is " ~ (wall < 0 * meter ? fmt(-wall / millimeter, 1) ~ " mm into the pocket" : "only " ~ fmt(wall / millimeter, 1) ~ " mm under the pocket floor") ~
                    " - the bolt would not clamp the laminate (a shorter Insert length, raise Hub above apex, or move the bolt where the root is thicker);";
            toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, zU - 2 * millimeter, holeD / 2, max(zFloor, floorC) + 1 * millimeter, holeD / 2));
            sketches = append(sketches, qCreatedBy(base + "a", EntityType.BODY));
            sketches = append(sketches, qCreatedBy(base + "b", EntityType.BODY));
            const nb = id + ("hubNut" ~ j);
            toolIds = append(toolIds, circleLoft(context, nb, bx, 0 * meter, zU - 2 * millimeter, nutR, zU + nutFT + nutL, nutR));
            sketches = append(sketches, qCreatedBy(nb + "a", EntityType.BODY));
            sketches = append(sketches, qCreatedBy(nb + "b", EntityType.BODY));
            const fb = id + ("hubNutF" ~ j);
            toolIds = append(toolIds, circleLoft(context, fb, bx, 0 * meter, zU - 2 * millimeter, nutFR, zU + nutFT, nutFR));
            sketches = append(sketches, qCreatedBy(fb + "a", EntityType.BODY));
            sketches = append(sketches, qCreatedBy(fb + "b", EntityType.BODY));
            underZs = append(underZs, zU / meter);
        }
        else if (under)
        {
            // the laminate left under the head: from the countersink's narrow end up to the pocket floor
            const zU = underAt[j];
            const wall = floorC - (zU + cskD);
            minWall = min(minWall, wall);
            if (wall < 0 * meter)
                wallNote = wallNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ ": its countersink breaks " ~ fmt(-wall / millimeter, 1) ~ " mm into the pocket (raise Hub above apex, a shallower Pocket depth, a smaller Hub bolt, or move it where the root is thicker with Bolt 1 from / Bolt pitch);";
            else if (wall < 2 * millimeter)
                wallNote = wallNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ ": only " ~ fmt(wall / millimeter, 1) ~ " mm of laminate between its countersink and the pocket floor (raise Hub above apex, a shallower Pocket depth, a smaller Hub bolt, or move it where the root is thicker with Bolt 1 from / Bolt pitch);";
            toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, zU - 2 * millimeter, holeD / 2, max(zFloor, floorC) + 1 * millimeter, holeD / 2));
            sketches = append(sketches, qCreatedBy(base + "a", EntityType.BODY));
            sketches = append(sketches, qCreatedBy(base + "b", EntityType.BODY));
            if (cskD > 0.05 * millimeter)
            {
                const cb = id + ("hubCsk" ~ j);
                toolIds = append(toolIds, circleLoft(context, cb, bx, 0 * meter, zU - 2 * millimeter, headR + 2 * millimeter, zU + cskD, holeD / 2));
                sketches = append(sketches, qCreatedBy(cb + "a", EntityType.BODY));
                sketches = append(sketches, qCreatedBy(cb + "b", EntityType.BODY));
            }
            underZs = append(underZs, zU / meter);
        }
        else
        {
            const zEnd = floorC - definition.hubHoleDepth;
            // wall under the hole: the lower skin at this X inside the chord, else the hub's flat underside
            const zUnder = bx > xLE + 0.5 * millimeter && bx < xTE - 0.5 * millimeter ? profileZAt(lower, bx) : zBot;
            if (zEnd < zUnder + 1.5 * millimeter)
                wallNote = wallNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ ": " ~ fmt(definition.hubHoleDepth / millimeter, 0) ~ " mm hole leaves " ~ fmt(max(zEnd - zUnder, 0 * meter) / millimeter, 1) ~ " mm under it (shorten Hole depth);";
            toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, zEnd, holeD / 2, max(zFloor, floorC) + 1 * millimeter, holeD / 2));
            sketches = append(sketches, qCreatedBy(base + "a", EntityType.BODY));
            sketches = append(sketches, qCreatedBy(base + "b", EntityType.BODY));
        }
        boltXs = append(boltXs, bx / meter);
    }
    var toolQs = [];
    for (var tid in toolIds)
        toolQs = append(toolQs, qCreatedBy(tid, EntityType.BODY));
    opBoolean(context, id + "hubCut", {
                "targets" : qSubtraction(allSolid, qUnion(toolQs)),
                "tools" : qUnion(toolQs),
                "operationType" : BooleanOperationType.SUBTRACTION
            });
    if (size(sketches) > 0)
        opDeleteBodies(context, id + "hubSketches", { "entities" : qUnion(sketches) });

    // ---- the clamp with nut inserts (build 241): what full preload buys against twist and yaw ----
    // Preload 70 % of A4-70 stainless's 450 MPa yield on the stress area (0.58 d^2); twist before the face opens
    // about the hub's edge, n F x half width; yaw before it slips, friction 0.3 x n F at the face's mean radius
    // from the bolt row's centre; bearing under each flange. Estimates for the notice, not a structural check
    var nutClampNote = "";
    if (nuts && size(boltXs) > 0)
    {
        const dB = (definition.hubBolt == BoltSize.CUSTOM ? clearD / 1.07 : boltDims(definition.hubBolt).dia * millimeter) / meter;
        const F = 0.7 * 450e6 * 0.58 * dB * dB;                          // N per bolt
        const nB = size(boltXs);
        var xc = 0;
        for (var bxv in boltXs)
            xc += bxv / nB;
        var rSum = 0;
        for (var i = 0; i < 12; i += 1)
            for (var k = 0; k < 6; k += 1)
                rSum += sqrt((x0 / meter + (x1 - x0) / meter * (i + 0.5) / 12 - xc) ^ 2 + (hw / meter * (2 * (k + 0.5) / 6 - 1)) ^ 2);
        const rMean = rSum / 72;
        const aFl = PI / 4 * ((2 * nutFR / meter) ^ 2 - (holeD / meter) ^ 2);
        nutClampNote = "; clamp at full preload (A4-70, about " ~ fmt(F / 1000, 1) ~ " kN a bolt, " ~ fmt(nB * F / 1000, 0) ~ " kN in all): twist before the face opens about " ~ fmt(nB * F * hw / meter, 0) ~
            " Nm, yaw before it slips about " ~ fmt(0.3 * nB * F * rMean, 0) ~ " Nm (friction 0.3), " ~ fmt(F / aFl / 1e6, 0) ~ " MPa under each flange (estimates)";
    }

    // ---- nose fairing (build 241, wing 1.070): the hub's front faired, the Omen way, as one lofted body ----
    // buildNoseFairing; needs the root fairing, whose wall section it shares so the sides run on as one surface
    var noseNote = "";
    var noseWarn = "";
    var noseBuilt = false;
    var noseVol = 0;
    const xW = px0 - cl;                                          // the pocket's front wall
    var xF0 = xW;
    var zTopF = zTop;
    // Nose height 0: the hub body's default top, Body height 22 above the hub's underside (the user: the defaults match
    // the tool's own fuselage; a bar is the custom case)
    const noseHIn = definition.hubNoseOn == true && definition.hubNoseHeight != undefined ? definition.hubNoseHeight : 0 * meter;
    const noseH = noseHIn > 0.05 * millimeter ? noseHIn : max(zBot + 22 * millimeter - zTop, 0.5 * millimeter);
    if (definition.hubNoseOn == true)
    {
        zTopF = zTop + noseH;
        xF0 = xW - definition.hubNoseLen;
        const xMin = xLE + 0.1 * (xTE - xLE);
        if (xF0 < xMin)
        {
            noseNote = " (its nose point held at 10 % of the chord, " ~ fmt((xMin - xLE) / millimeter, 0) ~ " mm behind the leading edge: Fairing length " ~ fmt((xW - xMin) / millimeter, 0) ~ " mm reaches it)";
            xF0 = xMin;
        }
        if (fair.on != 1)
            noseWarn = " the nose fairing needs the root fairing (turn Root fairing on, with the mirrored wing) - not built;";
        else if (xW - xF0 < 8 * millimeter)
            noseWarn = " the nose fairing has under 8 mm between its nose point and the pocket's front wall - not built; move the hub aft with Hub from apex or lengthen Pocket from;";
        else
        {
            const nf = buildNoseFairing(context, id, definition, m, upper, lower, xF0, xW, x0, hw, zTop, noseH, xLE, xTE, allSolid);
            noseBuilt = nf.on == 1;
            noseVol = nf.vol;
            noseWarn = noseWarn ~ nf.warn;
            if (!noseBuilt)   // an error, not a notice line and nothing built (user: "errors are better than silent failures")
                throw regenError("Nose fairing:" ~ nf.warn ~ " turn it off, or change Fairing length, Nose height or the hub", ["hubNoseOn", "hubNoseLen", "hubNoseHeight"]);
            if (noseBuilt)
                noseNote = " | nose fairing from X " ~ fmt(xF0 / millimeter, 0) ~ " (" ~ fmt((xW - xF0) / millimeter, 0) ~ " mm ahead of the pocket's front wall) rising to " ~ fmt(noseH / millimeter, 1) ~
                    " mm above the hub's top at the wall (Z " ~ fmt(zTopF / millimeter, 1) ~ ", " ~ fmt((zTopF - zApex) / millimeter, 1) ~ " mm above the root section's apex); back face " ~ fmt(2 * hw / millimeter, 0) ~ " x " ~
                    fmt(noseH / millimeter, 1) ~ " mm flat on the wall's plane for the " ~ (noseHIn > 0.05 * millimeter ? "bar's or the hub body's front" : "hub body's front (Nose height 0: its default Body height, 22 above the hub's underside)") ~
                    (definition.hubNoseRound > 0.05 * millimeter ? " (top corners R " ~ fmt(definition.hubNoseRound / millimeter, 1) ~ ")" : "") ~
                    ", feet " ~ fmt(nf.foot / millimeter, 1) ~ " mm from the centreline at the wall, the side fairing's; " ~ fmt(noseVol, 1) ~ " cm3" ~ nf.note ~ noseNote;
        }
    }
    return {
            "model" : { "on" : 0, "joint" : "HUB" },
            "hub" : { "on" : 1, "x0" : x0 / meter, "x1" : x1 / meter, "apexX" : xApex / meter, "width" : definition.hubWidth / meter, "topZ" : zTop / meter, "floorZ" : floorC / meter, "floorWallZ" : zFloor / meter,
                      "floor" : !vOn ? "FLAT" : (vd > 0 * meter ? "VGROOVE" : "VRIDGE"), "vDepth" : vd / meter, "vFillet" : vr / meter, "floorC" : floorC / meter,
                      "midZ" : zMid / meter, "botZ" : zBot / meter, "pocketX0" : (px0 - cl) / meter, "pocketX1" : px1 / meter, "openRear" : 1, "pocketW" : 2 * pw / meter, "pocketDepth" : pDepth / meter,
                      "tongueW" : definition.pocketWidth / meter, "tongueL" : definition.pocketLength / meter, "clear" : cl / meter,
                      "boltX" : boltXs, "holeDia" : holeD / meter, "holeDepth" : (under ? 0 * meter : definition.hubHoleDepth) / meter, "boltName" : boltDims(definition.hubBolt).name,
                      "boltClear" : (under ? clearD : (definition.hubBolt == BoltSize.CUSTOM ? holeD + 0.5 * millimeter : boltDims(definition.hubBolt).clear * millimeter)) / meter,
                      "boltHead" : (under && !nuts ? 2 * headR : boltHead(definition.hubBolt, definition.hubBolt == BoltSize.CUSTOM ? holeD + 0.5 * millimeter : boltDims(definition.hubBolt).clear * millimeter)) / meter,
                      "std" : definition.hubStd == undefined || definition.hubStd == HubStandard.CUSTOM ? "CUSTOM" : "STANDARD",
                      "leX" : xLE / meter, "teX" : xTE / meter, "fillet" : rUsed / meter, "filletTo" : (filletBuilt ? xEnd : x0) / meter,
                      "boltSide" : nuts ? "NUTS" : (under ? "UNDERSIDE" : "FUSELAGE"),
                      "recess" : nuts ? [[nutFR / meter, nutFT / meter], [nutR / meter, (nutFT + nutL) / meter]] : [], "underZ" : underZs, "cskDepth" : (under ? cskD : 0 * meter) / meter,
                      "tapDia" : (definition.hubBolt == BoltSize.CUSTOM ? 0.78 * clearD : boltDims(definition.hubBolt).tap * millimeter) / meter,
                      "boltDia" : (definition.hubBolt == BoltSize.CUSTOM ? clearD / 1.07 : boltDims(definition.hubBolt).dia * millimeter) / meter,
                      "noseOn" : noseBuilt ? 1 : 0, "noseX0" : xF0 / meter, "noseX1" : xW / meter, "noseTopZ" : zTopF / meter, "noseW" : definition.hubWidth / meter,
                      "noseRound" : (definition.hubNoseOn == true && definition.hubNoseRound != undefined ? definition.hubNoseRound : 0 * meter) / meter, "noseVol" : noseVol,
                      "fairing" : fair.on, "fairingR" : fair.on == 1 ? fair.rMax : 0, "reach" : fair.on == 1 ? fair.reach : definition.hubWidth / 2 / meter,
                      "plan" : x1 > xTE + 0.5 * millimeter ? { "on" : 1, "xTE" : xTE / meter, "yf" : fair.on == 1 ? fair.yf : hw / meter, "rp" : fair.on == 1 ? fair.rp : 0,
                                 "edge" : concatenateArrays([fair.on == 1 ? fair.edge : [], [[xTE / meter, hw / meter], [x1 / meter, hw / meter]]]) } : { "on" : 0 } },
            "note" : (noseBuilt ? " | flat hub " ~ fmt(definition.hubWidth / millimeter, 0) ~ " x " ~ fmt((x1 - xW) / millimeter, 0) ~ " mm from the pocket's front wall at X " ~ fmt(xW / millimeter, 0) ~ " mm (the nose fairing is its front)"
                : " | flat hub " ~ fmt(definition.hubWidth / millimeter, 0) ~ " x " ~ fmt((x1 - x0) / millimeter, 0) ~ " mm from X " ~ fmt(x0 / millimeter, 0) ~ " mm") ~
                (abs(x0 - xApex) < 0.01 * millimeter ? " (the apex)" : "") ~ placeNote ~ ", underside level with the trailing edge at Z " ~ fmt(zBot / millimeter, 1) ~ sunkNote ~ ", top " ~ fmt(definition.hubHeight / millimeter, 1) ~
                " mm above the apex at Z " ~ fmt(zTop / millimeter, 1) ~ " (square back)" ~ filletNote ~ (!rayOk ? " (ray casts failed: fixed margins used - send the console's WING_INPUTS line)" : "") ~
                "; pocket " ~ fmt(2 * pw / millimeter, 1) ~ " wide x " ~ fmt(pDepth / millimeter, 1) ~
                " mm deep" ~ (vOn ? " with a V " ~ (vd > 0 * meter ? "groove " : "ridge ") ~ fmt(abs(vd) / millimeter, 1) ~ " mm " ~ (vd > 0 * meter ? "deep" : "high") ~ " on its centreline, filleted " ~ fmt(vr / millimeter, 1) ~ " mm" ~ vNote : "") ~ " from its front wall at X " ~ fmt((px0 - cl) / millimeter, 0) ~ " mm out through the square back at X " ~ fmt(x1 / millimeter, 0) ~ " (" ~ fmt((x1 - px0 + cl) / millimeter, 0) ~ " mm long, for a " ~ fmt(definition.pocketLength / millimeter, 0) ~ " mm tongue); " ~
                (nuts ? size(boltXs) ~ " x " ~ boltDims(definition.hubBolt).name ~ " bolts down through the fuselage and the wing (holes " ~ fmt(holeD / millimeter, 1) ~ " mm) into flanged nut inserts in the underside: bore " ~ fmt(2 * nutR / millimeter, 2) ~
                    " x " ~ fmt((nutFT + nutL) / millimeter, 1) ~ " mm, flange recess " ~ fmt(2 * nutFR / millimeter, 2) ~ " x " ~ fmt(nutFT / millimeter, 1) ~ " mm flush with the skin" ~
                    (size(boltXs) > 0 ? "; least laminate clamped between an insert and the pocket floor " ~ fmt(minWall / millimeter, 1) ~ " mm" : "") ~ nutClampNote ~
                    "; keep Clear joint on in Foil mold with a Core clear so the inserts sit in solid laminate, which carries the clamp" :
                (under ? size(boltXs) ~ " x " ~ boltDims(definition.hubBolt).name ~ " clearance holes " ~ fmt(holeD / millimeter, 1) ~ " mm up through the wing from its underside to the pocket floor, countersunk " ~ fmt(2 * headR / millimeter, 1) ~
                    " mm at 90 deg in the lower skin so the heads sit flush, for bolts up into the bar or the fuselage's tongue, which is tapped" ~
                    (size(boltXs) > 0 ? "; least laminate under a head " ~ fmt(minWall / millimeter, 1) ~ " mm (countersink to pocket floor)" : "") ~
                    (underRayMiss > 0 ? " (" ~ underRayMiss ~ " ray cast" ~ (underRayMiss == 1 ? "" : "s") ~ " up the bolt axis met nothing: the root section's lower skin used)" : "") ~
                    "; keep Clear joint on in Foil mold with a Core clear so the bolts pass through solid laminate, not foam" :
                    size(boltXs) ~ " blind holes " ~ fmt(holeD / millimeter, 1) ~ " mm x " ~ fmt(definition.hubHoleDepth / millimeter, 0) ~ " mm for " ~ boltDims(definition.hubBolt).name ~ " bolts down through the fuselage")) ~
                noseNote ~ fair.note ~
                (wallNote != "" || floorNote != "" || noseWarn != "" || vWarn != "" ? " | WARNING:" ~ floorNote ~ vWarn ~ wallNote ~ noseWarn : "")
        };
}

/** profileZAt with x held inside the polyline's own x range, so a lookup a hair past an end cannot throw. */
function profileZAtClamped(pts is array, x is ValueWithUnits) returns ValueWithUnits
{
    var lo = pts[0][0];
    var hi = pts[0][0];
    for (var p in pts)
    {
        lo = min(lo, p[0]);
        hi = max(hi, p[0]);
    }
    return profileZAt(pts, min(max(x, lo), hi));
}

/**
 * The line a wing bolted straight onto a flat bar seats on (build 227): the lower convex hull of the
 * root's underside, and of its edges the one under the bolts' resultant at xr - a rigid body clamped
 * down onto a plane rests on that edge. Returns the edge's angle to the bar, positive = rising toward
 * the trailing edge in the modelled frame, so the wing as built runs at Incidence + this angle. A
 * Clark Y's flat gives one long edge (2.1 deg from its chord); a cambered NACA underside gives a short
 * one on its curve, and rocks. lower: the underside LE -> TE in the modelled (incidence-rotated) frame.
 */
function seatLineAngle(lower is array, xr is ValueWithUnits) returns ValueWithUnits
{
    var pts = [];
    for (var p in lower)
        if (size(pts) == 0 || p[0] > pts[size(pts) - 1][0] + 1e-9 * meter)
            pts = append(pts, p);
    var hull = [];
    for (var p in pts)
    {
        while (size(hull) >= 2)
        {
            const a = hull[size(hull) - 2];
            const b = hull[size(hull) - 1];
            const cross = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]);
            if (cross <= 0 * meter * meter)
                hull = subArray(hull, 0, size(hull) - 1);
            else
                break;
        }
        hull = append(hull, p);
    }
    if (size(hull) < 2)
        return 0 * radian;
    var k = 0;
    for (var i = 0; i < size(hull) - 1; i += 1)
        if (xr >= hull[i][0])
            k = i;
    return atan2((hull[k + 1][1] - hull[k][1]) / meter, (hull[k + 1][0] - hull[k][0]) / meter);
}

/**
 * Mount pad under the root for the Flat mount (build 227, user: "when the front wing fuselage joint is
 * directly bolted it needs a pad to set the incidence"). Worked in a mirrored frame z' = -z, as the
 * stab's pad is, so the pad stands "above" the seat surface: top = the root's own lower surface,
 * lifted 0.5 mm into the wing so the union overlaps; bottom = a flat horizontal face Pad height beyond
 * the underside's lowest point; Pad width across the span; from Flat start (or a ramp from 1 mm
 * behind the nose) to the trailing edge. A side prism intersected with a plan prism, unioned with the
 * wing. Where the underside already lies on the pad plane over the pad's length nothing is built.
 * upper TE -> LE, lower LE -> TE, world frame with the root pivot at the origin.
 * Returns { on, bodyOn, padZ (world Z of the seat face), xFlat, xStart, note }.
 */
function buildWingFlatPad(context is Context, id is Id, definition is map, upper is array, lower is array) returns map
{
    var surf = [];
    for (var p in lower)
        surf = append(surf, vector(p[0], -p[1]));
    var far = [];
    for (var i = size(upper) - 1; i >= 0; i -= 1)
        far = append(far, vector(upper[i][0], -upper[i][1]));
    var xMin = surf[0][0];
    var xMax = surf[0][0];
    var zTopM = surf[0][1];
    for (var p in surf)
    {
        xMin = min(xMin, p[0]);
        xMax = max(xMax, p[0]);
        zTopM = max(zTopM, p[1]);
    }
    const hair = 0.05 * millimeter;
    const x0 = xMin + 1 * millimeter;
    var padH = definition.flatPadHeight;
    var padM = zTopM + padH;
    var fitNote = "";
    var xRamp = xMin + definition.flatPadStart;
    if (xRamp < x0 + 5 * millimeter)
    {
        fitNote = " | WARNING: Flat start " ~ fmt(definition.flatPadStart / millimeter, 0) ~ " mm is too close to the leading edge - held 6 mm behind it";
        xRamp = x0 + 5 * millimeter;
    }
    if (xRamp > xMax - 5 * millimeter)
    {
        fitNote = " | WARNING: Flat start " ~ fmt(definition.flatPadStart / millimeter, 0) ~ " mm is at or behind the trailing edge (root chord " ~ fmt((xMax - xMin) / millimeter, 0) ~ " mm) - held 5 mm ahead of it; move Flat start forward";
        xRamp = xMax - 5 * millimeter;
    }
    // an underside that already lies on the pad plane over the pad's length (a Clark Y's flat drawn
    // at 2.1 deg with Pad height 0) needs no pad body: its own flat is the seat
    var padGap = 0 * meter;
    for (var k = 0; k <= 24; k += 1)
    {
        const x = xRamp + (xMax - hair - xRamp) * k / 24;
        padGap = max(padGap, padM - profileZAtClamped(surf, x));
    }
    const flatPad = padGap < 0.2 * millimeter;
    // a pad face ON the lowest point (Pad height under 0.3 mm) meets the skin along a line wherever
    // that point lies inside the pad: the side faces pinch to nothing there and the wing is
    // non-manifold, which only shows when the mold cuts its cavity (build 238: MRC-16, lowest point
    // 36 mm behind the LE, failed the LOWER cut; NACA 3 %/40, 1.3 mm inside the pad, passed)
    var heightNote = "";
    if (!flatPad && padH < 0.3 * millimeter)
    {
        heightNote = " (Pad height raised to 0.3 mm so the face clears the skin; the incidence it sets is unchanged)";
        padH = 0.3 * millimeter;
        padM = zTopM + padH;
    }
    const rampOn = definition.flatPadRamp != false;
    const xStart = rampOn ? x0 : xRamp;
    const hw = definition.flatPadWidth / 2;
    var bodyNote = "";
    if (!flatPad)
    {
        // ---- side profile (x, z'), closed: ramp or square front, the flat face, the end, the skin inside ----
        var ramp = [];
        if (rampOn)
        {
            for (var k = 0; k <= 12; k += 1)
            {
                const t = k / 12;
                const x = x0 + (xRamp - x0) * t;
                const sm = t * t * (3 - 2 * t);
                const zs = profileZAtClamped(surf, x);
                ramp = append(ramp, vector(x, zs + (padM - zs) * sm));
            }
        }
        else
            ramp = [vector(xRamp, padM)];
        var bottom = [];                                          // inside the wing, TE -> start
        for (var k = 0; k <= 24; k += 1)
        {
            const x = xMax - hair - (xMax - hair - xStart) * k / 24;
            const zs = profileZAtClamped(surf, x);
            const zf = profileZAtClamped(far, x);
            const lift = min(0.5 * millimeter, 0.4 * max(zs - zf, 0 * meter));
            bottom = append(bottom, vector(x, zs - lift));
        }
        var sketches = [];
        var side = [];
        const yS = [-(hw + 2 * millimeter), hw + 2 * millimeter];
        for (var i = 0; i < 2; i += 1)
        {
            const sid = id + ("flatPadSide" ~ i);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, yS[i], 0 * meter), -Y_DIRECTION, X_DIRECTION) });
            var rampW = [];
            for (var q in ramp)
                rampW = append(rampW, vector(q[0], -q[1]));
            var botW = [];
            for (var q in bottom)
                botW = append(botW, vector(q[0], -q[1]));
            if (rampOn)
                skFitSpline(sk, "ramp", { "points" : rampW });
            const pFlatEnd = vector(xMax + hair, -padM);
            skLineSegment(sk, "flat", { "start" : rampW[size(rampW) - 1], "end" : pFlatEnd });
            skLineSegment(sk, "end", { "start" : pFlatEnd, "end" : botW[0] });
            skFitSpline(sk, "inner", { "points" : botW });
            skLineSegment(sk, "nose", { "start" : botW[size(botW) - 1], "end" : rampW[0] });   // the square front with the ramp off
            skSolve(sk);
            side = append(side, qSketchRegion(sid));
            sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
        }
        opLoft(context, id + "flatPadSideLoft", { "profileSubqueries" : side });

        // ---- plan outline (x, y), closed ----
        var zLoW = -padM;
        var zHiW = -padM;
        for (var q in ramp)
        {
            zLoW = min(zLoW, -q[1]);
            zHiW = max(zHiW, -q[1]);
        }
        for (var q in bottom)
        {
            zLoW = min(zLoW, -q[1]);
            zHiW = max(zHiW, -q[1]);
        }
        zLoW = zLoW - 2 * millimeter;
        zHiW = zHiW + 2 * millimeter;
        var plan = [];
        const zP = [zLoW, zHiW];
        for (var i = 0; i < 2; i += 1)
        {
            const sid = id + ("flatPadPlan" ~ i);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, 0 * meter, zP[i]), Z_DIRECTION, X_DIRECTION) });
            const a = vector(xStart - 0.5 * millimeter, hw);
            const b = vector(xMax, hw);
            const c = vector(xMax, -hw);
            const d = vector(xStart - 0.5 * millimeter, -hw);
            skLineSegment(sk, "front", { "start" : d, "end" : a });
            skLineSegment(sk, "sideP", { "start" : a, "end" : b });
            skLineSegment(sk, "sideN", { "start" : c, "end" : d });
            skLineSegment(sk, "aft", { "start" : b, "end" : c });
            skSolve(sk);
            plan = append(plan, qSketchRegion(sid));
            sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
        }
        opLoft(context, id + "flatPadPlanLoft", { "profileSubqueries" : plan });
        opBoolean(context, id + "flatPadShape", {
                    "tools" : qUnion([qCreatedBy(id + "flatPadSideLoft", EntityType.BODY), qCreatedBy(id + "flatPadPlanLoft", EntityType.BODY)]),
                    "operationType" : BooleanOperationType.INTERSECTION
                });
        opBoolean(context, id + "flatPadJoin", {
                    "tools" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                    "operationType" : BooleanOperationType.UNION
                });
        opDeleteBodies(context, id + "flatPadSketches", { "entities" : qUnion(sketches) });
        bodyNote = rampOn ? "" : " (square front at Flat start, no ramp)";
    }
    else
        bodyNote = " (no pad body: the underside already lies on the pad plane within " ~ fmt(padGap / millimeter, 2) ~ " mm - its own flat is the seat)";
    return {
            "on" : true, "bodyOn" : !flatPad, "padZ" : -padM, "xFlat" : xRamp, "xStart" : xStart,
            "note" : " | mount pad under the root: " ~ fmt(2 * hw / millimeter, 0) ~ " mm wide, seat face " ~ fmt(padH / millimeter, 1) ~ " mm below the underside's lowest point at Z " ~
                fmt(-padM / millimeter, 1) ~ " mm, flat from X " ~ fmt(xRamp / millimeter, 0) ~ " mm (" ~ fmt((xRamp - xMin) / millimeter, 0) ~ " mm behind the LE" ~ (rampOn ? ", ramp from the nose" : "") ~ ") to the TE" ~ bodyNote ~ heightNote ~ fitNote
        };
}

/**
 * Flat mount (build 197): a home-build flat-bar layout. Countersunk clearance holes go straight down
 * through the root on the centreline, from Bolt 1 from behind the leading edge at Bolt pitch, for bolts
 * into a flat fuselage bar under the wing's underside. Each hole is checked against the root chord
 * (skipped outside it) and the laminate left under its head (warned below 2 mm). Build 227: a Mount
 * pad under the root (buildWingFlatPad) seats the wing on the bar at the modelled incidence; the holes
 * run through it; the notice reports the underside's seat line (seatLineAngle) and the angle the wing
 * would take on a bare bar. Publishes foilWingFlat; the socket and hub maps are off.
 */
function buildWingFlat(context is Context, id is Id, definition is map, m is map) returns map
{
    const c0 = m.rootChord;
    const n = definition.pointsPerSurface;
    const pf = pivotFraction(definition.pivot);
    const teLocal = min(definition.teThickness, 0.03 * c0);
    const sec = buildSection(definition, definition.rootThickness / 100, teLocal / c0, n);
    const pts = placeSection(sec, c0, pf, cos(definition.incidence), sin(definition.incidence));
    var upper = [];
    var lower = [];
    for (var i = 0; i < n; i += 1)
        upper = append(upper, pts[i]);
    for (var i = n - 1; i < size(pts); i += 1)
        lower = append(lower, pts[i]);
    const xLE = -pf * c0;
    const xTE = (1 - pf) * c0;
    const holeD = definition.flatBolt == BoltSize.CUSTOM ? definition.flatBoltDia : boltDims(definition.flatBolt).clear * millimeter;
    const headR = boltHead(definition.flatBolt, holeD) / 2;
    const cskD = definition.flatCsk ? headR - holeD / 2 : 0 * meter;
    // the bolt positions first: the seat line is taken under their resultant
    var boltAt = [];
    var wallNote = "";
    for (var j = 0; j < definition.flatBolts; j += 1)
    {
        const bx = xLE + definition.flatBolt1From + j * definition.flatPitch;
        if (bx - headR < xLE + 1.5 * millimeter || bx + headR > xTE - 1.5 * millimeter)
        {
            wallNote = wallNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ " falls outside the root chord (skipped: shorten Bolt pitch or move Bolt 1 from);";
            continue;
        }
        boltAt = append(boltAt, bx);
    }
    var xr = 0 * meter;
    for (var bx in boltAt)
        xr = xr + bx / size(boltAt);
    const seat = seatLineAngle(lower, xr);                         // the underside's line on a bare bar
    const asBuilt = definition.incidence + seat;
    const seatDeg = seat / degree;

    // ---- the pad that sets the incidence against the bar (build 227) ----
    const padOn = definition.flatPadOn == true;
    var pad = { "on" : false };
    if (padOn)
        pad = buildWingFlatPad(context, id, definition, upper, lower);
    var seatNote = "";
    if (padOn)
        seatNote = "; sets the modelled Incidence " ~ fmt(definition.incidence / degree, 1) ~ " deg against the bar (on its bare underside the wing would seat at " ~ fmt(asBuilt / degree, 1) ~ " deg: seat line " ~ fmt(seatDeg, 1) ~ " deg off the bar)";
    else if (abs(seatDeg) < 0.05)
        seatNote = " | no mount pad: the underside's seat line already lies on the bar, so the wing seats at the modelled " ~ fmt(definition.incidence / degree, 1) ~ " deg";
    else
        seatNote = " | WARNING: no mount pad - bolted flat on its bare underside the wing seats at " ~ fmt(asBuilt / degree, 1) ~ " deg, not the modelled " ~ fmt(definition.incidence / degree, 1) ~
            " (its seat line is " ~ fmt(seatDeg, 1) ~ " deg off the bar); turn Mount pad on, or set Incidence to " ~ fmt(asBuilt / degree, 1) ~ " to analyse it as built";

    // ---- the holes, through the pad and the wing ----
    var toolIds = [];
    var sketches = [];
    var boltXs = [];
    var bottomZs = [];
    var minWall = 1 * meter;
    for (var bx in boltAt)
    {
        const j = size(boltXs);
        const zu = profileZAt(upper, bx);
        const zl = profileZAt(lower, bx);
        const zb = padOn ? min(zl, pad.padZ) : zl;                // the face the bolt enters: the pad's seat or the skin
        const wall = (zu - zb) - cskD;
        minWall = min(minWall, wall);
        if (wall < 2 * millimeter)
            wallNote = wallNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ ": only " ~ fmt(wall / millimeter, 1) ~ " mm of laminate under the head" ~ (padOn ? ", pad included" : "") ~ " (a thicker section, a smaller bolt, or Countersink off);";
        const base = id + ("flatHole" ~ j);
        toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, zb - 2 * millimeter, holeD / 2, zu + 2 * millimeter, holeD / 2));
        sketches = append(sketches, qCreatedBy(base + "a", EntityType.BODY));
        sketches = append(sketches, qCreatedBy(base + "b", EntityType.BODY));
        if (cskD > 0.05 * millimeter)
        {
            const cb = id + ("flatCsk" ~ j);
            toolIds = append(toolIds, circleLoft(context, cb, bx, 0 * meter, zu - cskD, holeD / 2, zu + 2 * millimeter, headR + 2 * millimeter));
            sketches = append(sketches, qCreatedBy(cb + "a", EntityType.BODY));
            sketches = append(sketches, qCreatedBy(cb + "b", EntityType.BODY));
        }
        boltXs = append(boltXs, bx / meter);
        bottomZs = append(bottomZs, zb / meter);
    }
    if (size(toolIds) > 0)
    {
        var toolQs = [];
        for (var tid in toolIds)
            toolQs = append(toolQs, qCreatedBy(tid, EntityType.BODY));
        opBoolean(context, id + "flatCut", {
                    "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qUnion(toolQs)),
                    "tools" : qUnion(toolQs),
                    "operationType" : BooleanOperationType.SUBTRACTION
                });
        opDeleteBodies(context, id + "flatSketches", { "entities" : qUnion(sketches) });
    }
    const nm = boltDims(definition.flatBolt).name;
    return {
            "model" : { "on" : 0, "joint" : "FLAT" },
            "hub" : { "on" : 0 },
            "flat" : { "on" : 1, "boltX" : boltXs, "bottomZ" : bottomZs, "holeDia" : holeD / meter, "headDia" : 2 * headR / meter, "csk" : definition.flatCsk ? 1 : 0,
                       "cskDepth" : cskD / meter, "pitch" : definition.flatPitch / meter, "boltName" : nm, "leX" : xLE / meter, "teX" : xTE / meter,
                       "padOn" : padOn ? 1 : 0, "padBody" : padOn && pad.bodyOn ? 1 : 0, "padW" : (padOn ? definition.flatPadWidth : 0 * meter) / meter,
                       "padZ" : (padOn ? pad.padZ : 0 * meter) / meter, "padX0" : (padOn ? pad.xStart : 0 * meter) / meter, "padFlatX" : (padOn ? pad.xFlat : 0 * meter) / meter,
                       "seatDeg" : seatDeg, "asBuiltDeg" : asBuilt / degree },
            "note" : " | flat mount: " ~ size(boltXs) ~ " x " ~ nm ~ (definition.flatCsk ? " countersunk" : "") ~ " through holes " ~ fmt(holeD / millimeter, 1) ~ " mm on the centreline from X " ~
                fmt((xLE + definition.flatBolt1From) / millimeter, 0) ~ " mm at " ~ fmt(definition.flatPitch / millimeter, 0) ~ " mm pitch, bolted down through the wing onto a flat fuselage bar under its underside" ~
                (size(boltXs) > 0 ? "; least laminate under a head " ~ fmt(minWall / millimeter, 1) ~ " mm" : "") ~ (padOn ? pad.note : "") ~ seatNote ~ (wallNote != "" ? " | WARNING:" ~ wallNote : "")
        };
}

function buildWingSocket(context is Context, id is Id, definition is map, m is map) returns map
{
    if (!definition.socketOn)
        return { "model" : { "on" : 0 }, "note" : "", "hub" : { "on" : 0 } };
    if (definition.wingJoint == WingJoint.HUB)
        return buildWingHub(context, id, definition, m);
    if (definition.wingJoint == WingJoint.FLAT)
        return buildWingFlat(context, id, definition, m);

    // ---- axis: mid-thickness at the thickest point of the root section ----
    const c0 = m.rootChord;
    const n = definition.pointsPerSurface;
    const pf = pivotFraction(definition.pivot);
    const teLocal = min(definition.teThickness, 0.03 * c0);
    const sec = buildSection(definition, definition.rootThickness / 100, teLocal / c0, n);
    const pts = placeSection(sec, c0, pf, cos(definition.incidence), sin(definition.incidence));
    var upper = [];
    var lower = [];
    for (var i = 0; i < n; i += 1)
        upper = append(upper, pts[i]);
    for (var i = n - 1; i < size(pts); i += 1)
        lower = append(lower, pts[i]);
    const xLE = -pf * c0;
    var bestT = 0 * meter;
    var axisX = 0 * meter;
    var axisZ = 0 * meter;
    for (var k = 1; k < 60; k += 1)
    {
        const x = xLE + c0 * k / 60;
        const zu = profileZAt(upper, x);
        const zl = profileZAt(lower, x);
        if (zu - zl > bestT)
        {
            bestT = zu - zl;
            axisX = x;
            axisZ = (zu + zl) / 2;
        }
    }

    // ---- dimensions and checks ----
    // SQUARE: the nacelle is sized by the bore's larger side, so the wall is at least Wall at the corners' width
    const rTube = definition.wingJoint == WingJoint.SQUARE ? max(definition.boreWidth, definition.boreHeight) / 2 : definition.tubeDia / 2;
    const rBore = rTube + definition.tubeClearance / 2;
    axisZ = axisZ + definition.socketHeight;          // Socket height: the bore's axis off the mid-thickness (build 190)
    const R = rTube + definition.socketWall;
    // SQUARE: the nacelle is a rounded rectangle sized to the bore, wall all round
    const isSq = definition.wingJoint == WingJoint.SQUARE;
    const Rw = isSq ? definition.boreWidth / 2 + definition.tubeClearance / 2 + definition.socketWall : R;   // half width (Y)
    const Rh = isSq ? definition.boreHeight / 2 + definition.tubeClearance / 2 + definition.socketWall : R;  // half height (Z)
    // the rear face keeps Mouth wall % of the wall around the bore (build 233; half before), never more
    // than the nacelle itself
    const mouthFrac = definition.mouthWallPct == undefined ? 0.5 : definition.mouthWallPct / 100;
    const rLip = min(rBore + mouthFrac * definition.socketWall, R);
    const xTE = (1 - pf) * c0;
    const xStart = axisX;                              // thickest point of the root
    const xFull = xStart + definition.socketBlend;
    const xRear = xTE + definition.socketRearExt;
    const xFairStart = xRear - definition.nacelleRearFair;
    const h0 = 0.95 * bestT / 2;                       // start section hidden inside the wing
    if (Rh <= bestT / 2)
        throw regenError("Nacelle height (" ~ fmt(2 * Rh / millimeter, 1) ~ " mm) is no bigger than the root thickness (" ~ fmt(bestT / millimeter, 1) ~ " mm) - increase " ~ (isSq ? "Bore height" : "Tube dia") ~ " or Wall", [isSq ? "boreHeight" : "tubeDia", "socketWall"]);
    if (xFull > xFairStart)
        throw regenError("Blend length + Rear fairing do not fit between the root's thickest point and the rear face - shorten them or add Rear extension", ["socketBlend", "nacelleRearFair", "socketRearExt"]);
    const rRear = rLip; // diameter the taper actually reaches at the rear face - this is what Foil fuselage matches, not R
    if (xRear - definition.socketDepth < xFull)
        throw regenError("Socket depth reaches forward into the blend, where the nacelle is not yet full diameter - shorten Socket depth, shorten Blend length or add Rear extension", ["socketDepth", "socketBlend", "socketRearExt"]);
    if (xRear - definition.socketDepth < xLE)
        throw regenError("Socket depth reaches past the wing's own leading edge (X " ~ fmt(xLE / millimeter, 0) ~ " mm) - the bore would poke through the nose. Shorten Socket depth", ["socketDepth"]);
    const pinSpan = (definition.socketPins - 1) * definition.socketPinPitch;
    const pinD = definition.socketPinBolt == BoltSize.CUSTOM ? definition.socketPinDia : (boltDims(definition.socketPinBolt).clear + 0.1) * millimeter;
    if (definition.socketPins > 0 && pinSpan + 2 * pinD > definition.socketDepth)
        throw regenError("Pins do not fit within Socket depth", ["socketPins", "socketPinPitch", "socketDepth"]);
    // the bolt passes down through the tube, or through the bar's width on the Square socket (build 233:
    // checked against half the bar's larger side before)
    if (!isSq && pinD >= rTube)
        throw regenError("Pin bolt should be well under half the tube diameter", ["socketPinBolt", "tubeDia"]);
    if (isSq && pinD >= definition.boreWidth / 2)
        throw regenError("The bolt hole (" ~ fmt(pinD / millimeter, 1) ~ " mm) must be under half the Bore width (" ~ fmt(definition.boreWidth / 2 / millimeter, 1) ~ " mm), the side of the bar it passes through - choose a smaller Bolt", ["socketPinBolt", "boreWidth"]);

    // the bore wholly behind the trailing edge (build 233): whenever Rear extension > Socket depth (the
    // defaults, 90 and 80, on any root) the whole tube or bar is held in a pod behind the wing. A
    // notice line, not a warning, since the round socket was drawn that way: it says so and gives the
    // Socket depth or Rear extension that brings the bore's front 10 mm under the wing, each only where
    // it fits its limits and the blend and fairing
    const xBore = xRear - definition.socketDepth;
    var boreNote = "";
    if (xBore > xTE)
    {
        const xWant = xTE - 10 * millimeter;
        var fixes = [];
        if (xWant >= xFull)
        {
            const dFix = ceil((xRear - xWant) / millimeter);
            if (dFix <= 300)
                fixes = append(fixes, "Socket depth " ~ fmt(dFix, 0) ~ " mm");
            const rFix = floor((definition.socketRearExt - (xBore - xWant)) / millimeter);
            if (rFix >= 0 && xTE + rFix * millimeter - definition.nacelleRearFair >= xFull)
                fixes = append(fixes, "Rear extension " ~ fmt(rFix, 0) ~ " mm");
        }
        const bFix = floor((xWant - xStart) / millimeter);
        var fixText = "";
        if (size(fixes) == 2)
            fixText = fixes[0] ~ " or " ~ fixes[1];
        else if (size(fixes) == 1)
            fixText = fixes[0];
        else if (bFix >= 10)
            fixText = "Blend length " ~ fmt(bFix, 0) ~ " mm or less first (the bore cannot start inside the blend, which ends at X " ~ fmt(xFull / millimeter, 0) ~ "), then a longer Socket depth";
        boreNote = " | the bore starts " ~ fmt((xBore - xTE) / millimeter, 0) ~ " mm behind the root trailing edge (X " ~ fmt(xBore / millimeter, 0) ~ " mm), so none of the " ~ (isSq ? "bar" : "tube") ~
            " is under the wing: the joint is a pod behind it" ~ (fixText != "" ? ": " ~ fixText ~ " puts 10 mm of it under the wing" : ": the root is too short to reach under it");
    }

    // ---- nacelle sections along X: half-width a (Y), half-height b (Z) ----
    // Blend: full tube width across the span (hidden in the wing, which is wide in Y), height eased
    // from just inside the wing thickness to R with (1 - cos(pi s)) / 2 - zero slope at both ends,
    // so the nacelle rises smoothly out of the upper and lower surfaces.
    var xs = [];
    var halfW = [];
    var halfH = [];
    var cz = [];      // section centres: the blend starts on the root's mid-thickness and eases to the socket's axis (user: with Socket height the front must stay inside the chord's height)
    const nB = 10;
    for (var k = 0; k <= nB; k += 1)
    {
        const sb = k / nB;
        xs = append(xs, xStart + definition.socketBlend * sb);
        halfW = append(halfW, Rw);
        halfH = append(halfH, h0 + (Rh - h0) * (1 - cos((PI * sb) * radian)) / 2);
        cz = append(cz, axisZ - definition.socketHeight * (1 + cos((PI * sb) * radian)) / 2);   // from mid-thickness to the axis
    }
    if (definition.nacelleRearFair > 0.5 * millimeter && rLip < R - 0.001 * millimeter)   // Mouth wall % 100: no taper, the full section to the rear face
    {
        const nF = 5;
        for (var k = 0; k <= nF; k += 1)
        {
            const sF = k / nF;
            const f = 1 + (rLip / R - 1) * (1 - cos((PI * sF) * radian)) / 2;    // the lip's shrink, as a fraction
            xs = append(xs, xFairStart + definition.nacelleRearFair * sF);
            halfW = append(halfW, Rw * f);
            halfH = append(halfH, Rh * f);
            cz = append(cz, axisZ);
        }
    }
    else
    {
        xs = append(xs, xRear);
        halfW = append(halfW, Rw);
        halfH = append(halfH, Rh);
        cz = append(cz, axisZ);
    }
    // ---- the nacelle: with Root fairing (round socket) one loft whose sections carry the fairing (build 241,
    // user: smooth joins, no seams), else the plain ellipses ----
    var fair = { "on" : 0, "note" : "" };
    var nacelleBuilt = false;
    if (definition.rootFairing == true)
    {
        var fairDone = false;
        try silent
        {
            fair = buildFairedNacelle(context, id, definition, m, upper, lower, axisZ, xStart, xFull, xFairStart, xRear, xTE, R, h0, rLip, isSq, Rw, Rh);
            fairDone = true;
        }
        if (!fairDone)
            fair = { "on" : 0, "note" : " | root fairing: not built - it raised an error, so the nacelle is plain (send this line)" };
        nacelleBuilt = fair.on == 1;
        if (!nacelleBuilt)
        {
            var left = [qCreatedBy(id + "nacelleLoft", EntityType.BODY), qCreatedBy(id + "nacelleNose", EntityType.BODY), qCreatedBy(id + "nacellePlate", EntityType.BODY)];
            for (var k = 0; k <= 30; k += 1)
                left = append(left, qCreatedBy(id + ("fnPlate" ~ k), EntityType.BODY));
            for (var k = 0; k <= 80; k += 1)
                left = append(left, qCreatedBy(id + ("fnSec" ~ k), EntityType.BODY));
            for (var k = 0; k <= 8; k += 1)
                left = append(left, qCreatedBy(id + ("fnNose" ~ k), EntityType.BODY));
            try silent { opDeleteBodies(context, id + "fairCleanup", { "entities" : qUnion(left) }); }
        }
    }
    var joinedFaired = false;
    if (nacelleBuilt)
    {
        try silent
        {
            opBoolean(context, id + "nacelleJoin", {
                        "tools" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                        "operationType" : BooleanOperationType.UNION
                    });
            joinedFaired = true;
        }
        if (!joinedFaired)
        {
            try silent { opDeleteBodies(context, id + "fairUnionFail", { "entities" : qUnion([qCreatedBy(id + "nacelleLoft", EntityType.BODY), qCreatedBy(id + "nacelleNose", EntityType.BODY), qCreatedBy(id + "nacellePlate", EntityType.BODY)]) }); }
            fair = { "on" : 0, "note" : " | root fairing: not built (its union with the wing failed), so the nacelle is plain - send this line" };
            nacelleBuilt = false;
        }
    }
    if (!nacelleBuilt)
    {
        var sketchBodies = [];
        var regions = [];
        for (var k = 0; k < size(xs); k += 1)
        {
            if (k == 0 || xs[k] - xs[k - 1] >= 0.2 * millimeter)      // skip a duplicate station at the nose/body joint
            {
                const sid = id + ("nacSec" ~ k);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(xs[k], 0 * meter, cz[k]), X_DIRECTION, Y_DIRECTION) });
                if (isSq)
                    roundedRect(sk, halfW[k], halfH[k], min(halfW[k], halfH[k]) * 0.3);
                else
                    ellipseSplines(sk, halfW[k], halfH[k], 24);
                skSolve(sk);
                regions = append(regions, qSketchRegion(sid));
                sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
            }
        }
        opLoft(context, id + (joinedFaired || fair.note == "" ? "nacelleLoft" : "nacelleLoftPlain"), { "profileSubqueries" : regions });
        opDeleteBodies(context, id + "deleteNacelleSketchesP", { "entities" : qUnion(sketchBodies) });
            opBoolean(context, id + "nacelleJoinPlain", {
                    "tools" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                    "operationType" : BooleanOperationType.UNION
                });
    }

    // ---- bore (open at the rear face) and vertical pin holes ----
    const e = 0.5 * millimeter;
    var toolIds = [];
    if (definition.wingJoint == WingJoint.SQUARE)
    {
        // rectangular bore: the bar's width x height plus half the (diametral) clearance each side,
        // its corners rounded as an extruded bar's are (Bore corner, build 196), in the same nacelle
        const hw = definition.boreWidth / 2 + definition.tubeClearance / 2;
        const hh = definition.boreHeight / 2 + definition.tubeClearance / 2;
        roundedBoxX(context, id + "bore", xRear - definition.socketDepth, xRear + e, axisZ, hw, hh, definition.boreCorner + definition.tubeClearance / 2);
        toolIds = append(toolIds, id + "bore");
    }
    else
        toolIds = append(toolIds, xCylinder(context, id + "bore", xRear - definition.socketDepth, xRear + e, 0 * meter, axisZ, rBore));
    var toolSketches = isSq ? [] : [qCreatedBy(id + "bore" + "s0", EntityType.BODY), qCreatedBy(id + "bore" + "s1", EntityType.BODY)];
    const xPinC = xRear - definition.socketDepth / 2;
    // countersunk bolts (build 190): the through hole plus a 90 deg countersink in the nacelle's top
    // to the bolt's head diameter, so the heads sit flush
    const headR = boltHead(definition.socketPinBolt, pinD) / 2;
    const cskD = headR - pinD / 2;
    for (var j = 0; j < definition.socketPins; j += 1)
    {
        const px = xPinC - pinSpan / 2 + j * definition.socketPinPitch;
        const pbase = id + ("pin" ~ j);
        toolIds = append(toolIds, circleLoft(context, pbase, px, 0 * meter, axisZ - Rh - e, pinD / 2, axisZ + Rh + e, pinD / 2));
        toolSketches = append(toolSketches, qCreatedBy(pbase + "a", EntityType.BODY));
        toolSketches = append(toolSketches, qCreatedBy(pbase + "b", EntityType.BODY));
        const cbase = id + ("pinCsk" ~ j);
        toolIds = append(toolIds, circleLoft(context, cbase, px, 0 * meter, axisZ + Rh - cskD, pinD / 2, axisZ + Rh + 2 * millimeter, headR + 2 * millimeter));
        toolSketches = append(toolSketches, qCreatedBy(cbase + "a", EntityType.BODY));
        toolSketches = append(toolSketches, qCreatedBy(cbase + "b", EntityType.BODY));
    }
    if (size(toolSketches) > 0)
        opDeleteBodies(context, id + "deleteToolSketches", { "entities" : qUnion(toolSketches) });
    var toolQueries = [];
    for (var t in toolIds)
        toolQueries = append(toolQueries, qCreatedBy(t, EntityType.BODY));
    const tools = qUnion(toolQueries);
    opBoolean(context, id + "socketCut", {
                "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), tools),
                "tools" : tools,
                "operationType" : BooleanOperationType.SUBTRACTION
            });

    // the rear face as built: the nacelle scaled by rLip / R (the fairing's own law), and the wall it
    // leaves round the bore - the thinner side's on the Square socket
    const fEnd = rLip / R;
    const mouthW = isSq ? min(Rw * fEnd - (definition.boreWidth + definition.tubeClearance) / 2, Rh * fEnd - (definition.boreHeight + definition.tubeClearance) / 2) : rLip - rBore;
    const rearText = isSq ? fmt(2 * Rw * fEnd / millimeter, 1) ~ " x " ~ fmt(2 * Rh * fEnd / millimeter, 1) : fmt(2 * rRear / millimeter, 1);
    return {
            "hub" : { "on" : 0 },
            "model" : { "on" : 1, "joint" : definition.wingJoint == WingJoint.SQUARE ? "SQUARE" : "ROUND",
                        "boreW" : (definition.wingJoint == WingJoint.SQUARE ? definition.boreWidth + definition.tubeClearance : 2 * rBore) / meter, "boreH" : (definition.wingJoint == WingJoint.SQUARE ? definition.boreHeight + definition.tubeClearance : 2 * rBore) / meter,
                        "boreR" : (definition.wingJoint == WingJoint.SQUARE ? definition.boreCorner + definition.tubeClearance / 2 : 0 * meter) / meter,
                        "axisX" : axisX / meter, "axisZ" : axisZ / meter, "rearX" : xRear / meter, "fullX" : xFull / meter,
                        "tubeDia" : definition.tubeDia / meter, "boreDia" : 2 * rBore / meter,
                        "nacelleDia" : 2 * R / meter, "rearDia" : 2 * rRear / meter, "depth" : definition.socketDepth / meter,
                        "pins" : definition.socketPins, "pinPitch" : definition.socketPinPitch / meter,
                        "pinDia" : pinD / meter, "pinBolt" : boltDims(definition.socketPinBolt).name, "pinCenterX" : xPinC / meter,
                        "pinHeadDia" : 2 * headR / meter, "pinCsk" : 1, "nacelleW" : 2 * Rw / meter, "nacelleH" : 2 * Rh / meter, "axisOffset" : definition.socketHeight / meter,
                        "teX" : xTE / meter, "rearExt" : definition.socketRearExt / meter, "rearFair" : definition.nacelleRearFair / meter, "mouthWall" : mouthW / meter,
                        "fairing" : fair.on, "fairingR" : fair.on == 1 ? fair.rMax : 0, "fairingX0" : fair.on == 1 ? fair.x0 : 0, "fairingX1" : fair.on == 1 ? fair.x1 : 0,
                        "web" : fair.on == 1 && fair.web != undefined ? fair.web : { "on" : 0 } },
            "note" : (isSq ? " | square socket: " ~ fmt(definition.boreWidth / millimeter, 0) ~ " x " ~ fmt(definition.boreHeight / millimeter, 0) ~ " mm bore (corners R " ~ fmt(definition.boreCorner / millimeter, 1) ~ "), nacelle " ~ fmt(2 * Rw / millimeter, 0) ~ " x " ~ fmt(2 * Rh / millimeter, 0) :
                      " | tube socket: " ~ fmt(definition.tubeDia / millimeter, 1) ~ " mm tube, nacelle " ~ fmt(2 * R / millimeter, 0)) ~
                " mm, blends from the thickest point (X " ~ fmt(xStart / millimeter, 0) ~ ", Z " ~ fmt(axisZ / millimeter, 1) ~ " mm) to full diameter at X " ~
                fmt(xFull / millimeter, 0) ~ ", root TE at X " ~ fmt(xTE / millimeter, 0) ~ (fEnd > 0.9999 ? ", full size to the rear face at X " : ", tapers to " ~ rearText ~ " mm by the rear face at X ") ~
                fmt(xRear / millimeter, 0) ~ " mm, mouth wall " ~ fmt(mouthW / millimeter, 1) ~ " mm, bore " ~ fmt(definition.socketDepth / millimeter, 0) ~ " mm deep from X " ~ fmt(xBore / millimeter, 0) ~ boreNote ~ fair.note
        };
}

/**
 * Solid of revolution about a vertical axis at (x, y): lofts a circle of radius r0 at height z0
 * to a circle of radius r1 at height z1 (a cylinder when r0 == r1, a cone otherwise). Sketch ids
 * are baseId + "a" and baseId + "b"; the caller deletes the sketch bodies. Returns the loft id.
 */
function circleLoft(context is Context, baseId is Id, x is ValueWithUnits, y is ValueWithUnits,
    z0 is ValueWithUnits, r0 is ValueWithUnits, z1 is ValueWithUnits, r1 is ValueWithUnits) returns Id
{
    const idA = baseId + "a";
    const idB = baseId + "b";
    var ska = newSketchOnPlane(context, idA, { "sketchPlane" : plane(vector(x, y, z0), Z_DIRECTION, X_DIRECTION) });
    skCircle(ska, "c", { "center" : vector(0, 0) * meter, "radius" : r0 });
    skSolve(ska);
    var skb = newSketchOnPlane(context, idB, { "sketchPlane" : plane(vector(x, y, z1), Z_DIRECTION, X_DIRECTION) });
    skCircle(skb, "c", { "center" : vector(0, 0) * meter, "radius" : r1 });
    skSolve(skb);
    const loftId = baseId + "loft";
    opLoft(context, loftId, { "profileSubqueries" : [qSketchRegion(idA), qSketchRegion(idB)] });
    return loftId;
}

function mastInputLog(definition is map) returns string
{
    var s = "MAST_INPUTS: toolVersion=" ~ FOIL_MAST_VERSION
        ~ "; mastHeight_mm=" ~ fmt(definition.mastHeight / millimeter, 1)
        ~ "; topChord_mm=" ~ fmt(definition.topChord / millimeter, 1) ~ "; taperSide=" ~ (definition.mastTaper == MastTaper.SYMMETRIC ? "SYMMETRIC" : (definition.mastTaper == MastTaper.LEADING ? "LEADING" : "TRAILING"))
        ~ "; topThick_mm=" ~ fmt(definition.topThick / millimeter, 1) ~ "; thickenFromPct=" ~ fmt(definition.thickenFrom, 0)
        ~ "; mastWidth_mm=" ~ fmt(definition.mastWidth / millimeter, 1)
        ~ "; mastThick_mm=" ~ fmt(definition.mastThick / millimeter, 2)
        ~ "; mastTe_mm=" ~ fmt(definition.mastTe / millimeter, 2)
        ~ "; mastPoints=" ~ fmt(definition.mastPoints, 0)
        ~ "; mastX_mm=" ~ fmt(definition.mastX / millimeter, 1)
        ~ "; baseHeight_mm=" ~ fmt(definition.baseHeight / millimeter, 1)
        ~ "; podOn=" ~ (definition.podOn ? "true" : "false");
    if (definition.podOn)
        s = s ~ "; podDia_mm=" ~ fmt(definition.podDia / millimeter, 1) ~ "; podTilt_deg=" ~ fmt(definition.podTilt / degree, 1)
            ~ "; podHeight_mm=" ~ fmt(definition.podHeight / millimeter, 1)
            ~ "; podNoseStartPct=" ~ fmt(definition.podNoseStartPct, 1)
            ~ "; podFairLength_mm=" ~ fmt(definition.podFairLength / millimeter, 1)
            ~ "; podBlendHeightPct=" ~ fmt(definition.podBlendHeightPct, 1)
            ~ "; podAft_mm=" ~ fmt(definition.podAft / millimeter, 1)
            ~ "; cavDia_mm=" ~ fmt(definition.cavDia / millimeter, 1) ~ "; cavLength_mm=" ~ fmt(definition.cavLength / millimeter, 1);
    s = s ~ "; plateLength_mm=" ~ fmt(definition.plateLength / millimeter, 1)
        ~ "; plateWidth_mm=" ~ fmt(definition.plateWidth / millimeter, 1)
        ~ "; plateThick_mm=" ~ fmt(definition.plateThick / millimeter, 1)
        ~ "; trackSpacing_mm=" ~ fmt(definition.trackSpacing / millimeter, 1)
        ~ "; boltsPerRow=" ~ fmt(definition.boltsPerRow, 0)
        ~ "; boltPitch_mm=" ~ fmt(definition.boltPitch / millimeter, 1)
        ~ "; bolt=" ~ boltDims(definition.plateBolt).name ~ "; boltDia_mm=" ~ fmt((definition.plateBolt == BoltSize.CUSTOM ? definition.boltDia : (boltDims(definition.plateBolt).clear + 0.1) * millimeter) / millimeter, 2)
        ~ "; countersink=" ~ (definition.countersink ? "true" : "false")
        ~ "; rootFillet_mm=" ~ fmt(definition.rootFillet / millimeter, 1);
    return s;
}




annotation { "Feature Type Name" : "Foil fuselage",
             "Feature Type Description" : "Round hydrofoil fuselage: a spigot into the Foil wing's tube socket, a body running past the mast to a tapered tail, seated on the stabiliser's mount pad with blind tapped holes on its bolt pattern (stab under or on top), and an optional mast pocket. Conflicts are shown as warnings that name the fix in the other feature." }
export const foilFuselage = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Group Name" : "Body", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Parallel aft",
                         "Description" : "How far the full-diameter body continues behind the mast trailing edge before it tapers. Limits 0-300 mm. Typical 20-60 mm." }
            isLength(definition.fusParAft, { (millimeter) : [0, 40, 300] } as LengthBoundSpec);

            annotation { "Name" : "Tail dia",
                         "Description" : "Body diameter under the stab, after the taper. Limits 6-60 mm; clamped to the body diameter. Typical: equal to Tube dia (no taper before the stab - the fuselage is a high-stress part and the stab block needs a full body under it), tapering only in the tip. Smaller only for a lightly loaded foil." }
            isLength(definition.fusTailDia, { (millimeter) : [6, 24, 60] } as LengthBoundSpec);

            annotation { "Name" : "Overhang",
                         "Description" : "Where the fuselage ends: the X of its pointed tip, measured from the stab root trailing edge. Positive = behind the stab, negative = the tip ends under the stab. Limits -200 to +300 mm. Typical 40-80 mm (tip fully behind the stab, untouched by the seat)." }
            isLength(definition.overhang, { (millimeter) : [-200, 60, 300] } as LengthBoundSpec);

            annotation { "Name" : "Tip length",
                         "Description" : "Length of the elliptical tip, from Tail dia down to a point. Independent of Overhang, so the tip is always a full ellipse. Limits 5-200 mm. Typical 2-3 x Tail dia; longer is lower drag." }
            isLength(definition.tipLength, { (millimeter) : [5, 40, 200] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Stab seat", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Seat margin",
                         "Description" : "Extra seat (and block) length beyond the stab root chord at each end (never past the fuselage tip). Limits 0-30 mm. Typical 2-5 mm." }
            isLength(definition.seatMargin, { (millimeter) : [0, 3, 30] } as LengthBoundSpec);

            annotation { "Name" : "Stab bolt dia",
                         "Description" : "Tapping drill for the stab bolts, used ONLY when the Foil stabiliser's Bolt is set to Custom hole sizes; with a named bolt (M4-M10) the drill comes from the stab (M6 5.0, M8 6.8 mm) and this field is ignored. Limits 3-10 mm. Typical 6.8 (M8) or 5 (M6). The positions come from the stab's Mount bolts (Bolt 1 at, Bolt pitch), so the two always match." }
            isLength(definition.stabBoltDia, { (millimeter) : [3, 6.8, 10] } as LengthBoundSpec);

            annotation { "Name" : "Bolt depth",
                         "Description" : "Depth of each blind tapped hole from the seat plane into the body. Limits 3-40 mm. Typical 1.5-2 x bolt diameter. With the fuselage over the stab (the stab's Mount side Top) the hole goes up: the depth available is the pad plane's drop below the axis plus the local radius, less 1 mm of wall (about 15 mm on a 24 mm tail seated 4 mm under the axis). A hole that would break through is skipped with the fix named." }
            isLength(definition.boltDepth, { (millimeter) : [3, 14, 40] } as LengthBoundSpec);
        }

        annotation { "Group Name" : "Mast pocket", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Mast pocket", "Default" : true,
                         "Description" : "Cuts a pocket in the top of the fuselage for the mast's bottom end, shaped to the Foil mast's own section plus Clearance. Its position AND depth follow the mast: the floor is at the mast's Base height, so moving the mast reshapes the pocket. Needs a Foil mast feature above this one." }
            definition.pocketOn is boolean;

            if (definition.pocketOn)
            {
                annotation { "Name" : "Clearance",
                             "Description" : "Gap between the mast and the pocket walls, all round. Limits 0-2 mm. Typical 0.1-0.3 mm for a bonded or bolted fit." }
                isLength(definition.pocketClearance, { (millimeter) : [0, 0.2, 2] } as LengthBoundSpec);
            }
        }

        annotation { "Group Name" : "Hub body", "Collapsed By Default" : false }
        {
            annotation { "Name" : "Body", "Default" : "AUTO",
                         "Description" : "Which fuselage this is. Follow the wing's joint (default): the round tube when the wing has a Round tube socket, the hub body when it has the flat hub; a Square socket is refused (build 233: it takes a flat bar, which this feature does not model - use your own bar). Hub body (build 208, from the user's template): a nose the shape of the hub sitting on its top with a tongue in the pocket, bolted down through it; a rounded body carrying the mast; a tail to the stab's seat whose length follows the stab's Arm; a seat block the stab bolts to. Round tube: the socket fuselage, whatever the wing has." }
            definition.fusBody is FusBody;

            if (definition.fusBody != FusBody.TUBE)
            {
                annotation { "Name" : "Nose height",
                             "Description" : "Height of the nose above the hub's top face at its front; it rises from there to the body's top at the hub's back. Limits 1-20 mm. Typical 4-6 (template 5)." }
                isLength(definition.noseHeight, { (millimeter) : [1, 5, 20] } as LengthBoundSpec);

                annotation { "Name" : "Body height",
                             "Description" : "Height of the body from the hub's underside (its bottom is level with the hub's) to its top, all the way to section 1. Limits 10-40 mm. Typical 20-24 (template 22): the top must clear the hub's top by 3 mm, and the mast pocket goes down from it to the mast's Base height." }
                isLength(definition.bodyHeight, { (millimeter) : [10, 22, 40] } as LengthBoundSpec);

                annotation { "Name" : "Body width",
                             "Description" : "Width of the body at section 1, where it stops narrowing from the hub's width. Limits 12-40 mm. Typical 22-26 (template 24); wider than the mast pocket's thickness plus 6 mm." }
                isLength(definition.bodyWidth, { (millimeter) : [12, 24, 40] } as LengthBoundSpec);

                annotation { "Name" : "Body length",
                             "Description" : "From the hub's back (section 3) to section 1, where the tail's taper to the stab begins. Limits 50-400 mm. Typical 150-170 (template 163); the mast must lie within it, and the tail from section 1 to the stab's seat takes whatever the stab's Arm leaves." }
                isLength(definition.bodyLength, { (millimeter) : [50, 160, 400] } as LengthBoundSpec);

                annotation { "Name" : "Tail depth",
                             "Description" : "Height of the section at the stab's seat and of the seat block, on the far side of the pad plane from the stab. Limits 4-20 mm. Typical 8 (template 7.7); the stab's bolts tap through it when Bolt depth is more than this." }
                isLength(definition.tailDepth, { (millimeter) : [4, 8, 20] } as LengthBoundSpec);

                annotation { "Name" : "End width",
                             "Description" : "Plan width of the seat block at its end, Seat margin behind the stab's trailing edge. Limits 2-20 mm. Typical 4-8 (template 7)." }
                isLength(definition.endWidth, { (millimeter) : [2, 6, 20] } as LengthBoundSpec);

                annotation { "Name" : "Edge round",
                             "Description" : "Radius on the nose's top edges and the corners of every section. Limits 0-10 mm. Typical 4-5 (template 5); held to 45 % of a section's smaller half-size." }
                isLength(definition.edgeRound, { (millimeter) : [0, 5, 10] } as LengthBoundSpec);

                annotation { "Name" : "Nose countersink", "Default" : true,
                             "Description" : "Countersinks the hub's bolt holes into the nose's top to the bolt's head diameter, so the heads sit flush. Off: plain holes for button heads." }
                definition.noseCsk is boolean;
            }
        }

        annotation { "Name" : "Wing pin holes", "Default" : true,
                     "Description" : "Holes through the spigot matching the wing socket's Pins, Pin bolt and Pin pitch, at the same clearance size." }
        definition.matchWingPins is boolean;

        annotation { "Name" : "Log inputs", "Default" : true,
                     "Description" : "Prints every parameter on this feature to the FeatureScript console as one line, so the whole set can be pasted elsewhere (e.g. back to an AI assistant)." }
        definition.logInputs is boolean;
    }
    {
        setVariable(context, "foilFuselageLog", "");
        setVariable(context, "foilFuselageNotice", "");
        if (definition.logInputs)
            foilPrint(context, "foilFuselageLog", fuselageInputLog(definition));

        // ---------------- neighbours (read, never set) ----------------
        var sock;
        var stabRoot;
        var mast;
        var hub;
        try silent { sock = getVariable(context, "foilWingSocket"); }
        try silent { stabRoot = getVariable(context, "foilStabRoot"); }
        try silent { mast = getVariable(context, "foilMastModel"); }
        try silent { hub = getVariable(context, "foilWingHub"); }
        if (stabRoot == undefined)
            throw regenError("The fuselage needs a Foil stabiliser above it");
        if (stabRoot.padSide == undefined || stabRoot.boltX == undefined)
            throw regenError("The Foil stabiliser above is older than this Foil fuselage - paste the whole Feature Studio over again so both are the same build");
        // the hub body (build 208): the wing's flat hub, or asked for by Body
        const hubOnW = hub != undefined && hub.on == 1;
        const wantHub = definition.fusBody == FusBody.HUB || (definition.fusBody != FusBody.TUBE && hubOnW);
        if (wantHub)
        {
            if (!hubOnW)
                throw regenError("Body = Hub body needs a Foil wing above with Joint = Flat hub with pocket; the wing has none", ["fusBody"]);
            buildHubFuselage(context, id, definition, hub, stabRoot, mast);
            return;
        }
        if (sock == undefined || sock.on != 1)
            throw regenError(hubOnW ? "The wing has a flat hub: set Body = Follow the wing's joint or Hub body" : "The fuselage needs a Foil wing above it with Fuselage joint on and Joint = Round tube socket");
        // build 233: the Square socket takes a flat bar; this body is a round tube on a round spigot
        // (it read the hidden Tube dia), so it cannot fill that bore
        if (sock.joint != undefined && sock.joint == "SQUARE")
            throw regenError("The wing has a Square socket, which takes a flat bar: Foil fuselage builds a round tube on a round spigot and cannot fill it. Use your own bar (suppress this feature), or set the wing's Joint to Round tube socket");

        var warnings = [];
        const e = 0.5 * millimeter;
        const R = sock.rearDia / 2 * meter;              // flush with the socket's own rear-face diameter
        const rSp = sock.tubeDia / 2 * meter;            // spigot fits the bore
        const zA = sock.axisZ * meter;
        const xRear = sock.rearX * meter;
        const xFront = (sock.rearX - sock.depth) * meter;
        const rT = min(definition.fusTailDia / 2, R);       // clamped: no more than the body
        if (stabRoot.padSide == undefined || stabRoot.boltX == undefined)
            throw regenError("The Foil stabiliser above is older than this Foil fuselage - paste the whole Feature Studio over again so both are the same build");
        const sLE = stabRoot.leX * meter;
        const sTE = stabRoot.teX * meter;
        // the stab owns the joint: Mount side Top = this fuselage passes over the stab and seats on the
        // pad plane (the production layout); Bottom or no pad = the stab sits on top of the fuselage tail
        const over = stabRoot.padSide == 1;
        const sBot = over ? (stabRoot.padOn == 1 ? stabRoot.padZ : stabRoot.topZ) * meter : stabRoot.bottomZ * meter;   // the plane the fuselage seats on: the pad face, or the bare root skin (build 199)
        const hasTail = over && stabRoot.tailOn == 1;
        const xSeat0 = sLE - definition.seatMargin;
        // with a stab tail fairing the fuselage ends where the tail ends and its tip is the upper
        // half of that taper (starting at the stab trailing edge); otherwise Overhang + Tip length
        const xEnd = hasTail ? stabRoot.tailEndX * meter : sTE + definition.overhang;
        // with a tail fairing the tip tapers from the stab's Tail start (fixed to its pivot, build 125),
        // not from its trailing edge, so the fuselage is the same for every stab with the same Arm
        const xTip = hasTail ? min(stabRoot.tailStartX != undefined ? stabRoot.tailStartX * meter : sTE, xEnd - 1 * millimeter) : xEnd - definition.tipLength;
        const xTail = min(xSeat0, xTip);                  // body reaches Tail dia here

        var xPar = xRear + definition.fusParAft;
        if (mast != undefined)
        {
            const mLE = mast.leX * meter;
            const mTE = (mast.leX + mast.chord) * meter;
            xPar = max(mTE, xRear) + definition.fusParAft;
            if (mLE < xRear)
                warnings = append(warnings, "the mast leading edge (X " ~ fmt(mLE / millimeter, 0) ~ " mm) is over the wing socket, not the fuselage - set Foil mast's Mast X to at least " ~ fmt(xRear / millimeter, 0) ~ " mm");
            if (!definition.pocketOn && abs(mast.baseZ * meter - (zA + R)) > 0.5 * millimeter)
                warnings = append(warnings, "the mast base (Z " ~ fmt(mast.baseZ * 1000, 1) ~ " mm) does not sit on the fuselage top - set Foil mast's Base height to " ~
                    fmt((zA + R) / millimeter, 1) ~ " mm, or turn on Mast pocket");
        }
        if (xPar >= xTail - 1 * millimeter)
        {
            warnings = append(warnings, "the parallel section runs into the tail taper - shortened; move the mast forward, the stab aft, or reduce Parallel aft");
            xPar = xTail - 1 * millimeter;
        }
        if (xPar <= xRear)
            throw regenError("No room for the body between the wing socket and the tail - move the stab aft (Arm), or increase Overhang", ["overhang"]);

        // ---------------- body profile (same stations as the reference model) ----------------
        var holesF = [];          // every vertical hole, for the mold: [x, z0, z1, r, rHead, cskSide, pinFrom] (SI)
        var xs = [xRear, xPar];
        var rs = [R, R];
        for (var k = 1; k <= 8; k += 1)
        {
            const s = k / 8;
            xs = append(xs, xPar + (xTail - xPar) * s);
            rs = append(rs, R + (rT - R) * (1 - cos((PI * s) * radian)) / 2);   // zero slope both ends
        }
        if (xTip - xTail > 0.2 * millimeter)
        {
            xs = append(xs, xTip);
            rs = append(rs, rT);
        }
        var zcs = [];              // section centre drop below the axis (0 except in a tail-matched tip)
        for (var k = 0; k < size(xs); k += 1)
            zcs = append(zcs, 0 * meter);
        for (var k = 1; k <= 10; k += 1)
        {
            const t = k / 10;
            if (hasTail && stabRoot.tailEndWidth != undefined)
            {
                // the upper half of the stab's own tail taper: radius scaled from its plan law, the
                // circle dropping to stay tangent to the pad plane once it is smaller than the drop
                const hW = stabRoot.padWidth / 2 * meter;
                const hE = stabRoot.tailEndWidth / 2 * meter;
                const r = max(rT * (hE + (hW - hE) * (1 - t) ^ stabRoot.tailExp) / hW, 0.001 * rT);
                xs = append(xs, xTip + (xEnd - xTip) * t);
                rs = append(rs, r);
                // the circle dips 0.3 mm below the pad plane rather than sitting tangent to it: the
                // seat cut was BOOLEAN_INVALID with the plane tangent to the tip's cylinders
                zcs = append(zcs, max(0 * meter, zA - (sBot + r) + 0.3 * millimeter));
            }
            else
            {
                // true quarter-ellipse: x and r from one shared angle
                const phi = (PI / 2 * t) * radian;
                xs = append(xs, xTip + (xEnd - xTip) * sin(phi));
                rs = append(rs, max(rT * cos(phi), 0.001 * rT));
                zcs = append(zcs, 0 * meter);
            }
        }
        var sketchBodies = [];
        var regions = [];
        for (var k = 0; k < size(xs); k += 1)
        {
            const sid = id + ("sec" ~ k);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(xs[k], 0 * meter, zA - zcs[k]), X_DIRECTION, Y_DIRECTION) });
            ellipseSplines(sk, rs[k], rs[k], 24);
            skSolve(sk);
            regions = append(regions, qSketchRegion(sid));
            sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
        }
        opLoft(context, id + "bodyLoft", { "profileSubqueries" : regions });
        xCylinder(context, id + "spigot", xFront, xRear + 1 * millimeter, 0 * meter, zA, rSp);
        sketchBodies = append(sketchBodies, qCreatedBy(id + "spigot" + "s0", EntityType.BODY));
        sketchBodies = append(sketchBodies, qCreatedBy(id + "spigot" + "s1", EntityType.BODY));
        opBoolean(context, id + "joinSpigot", {
                    "tools" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                    "operationType" : BooleanOperationType.UNION
                });

        // ---------------- tools: seat, blind stab bolt holes, wing pin holes ----------------
        var toolIds = [];
        var seatNote = " | no stab seat";
        // the tapping drill: from the stab's named bolt, else this feature's own field (Custom)
        const tapFromStab = stabRoot.tapDia != undefined && stabRoot.tapDia > 0;
        const tapDia = tapFromStab ? stabRoot.tapDia * meter : definition.stabBoltDia;
        const tapNote = tapFromStab ? " for " ~ stabRoot.boltName : "";
        if (!tapFromStab && stabRoot.boltDia != undefined && stabRoot.boltDia > 0 && stabRoot.boltDia * meter < definition.stabBoltDia + 0.3 * millimeter)
            warnings = append(warnings, "the stab's clearance hole (" ~ fmt(stabRoot.boltDia * 1000, 1) ~ " mm) is not bigger than this feature's tapping drill (" ~ fmt(definition.stabBoltDia / millimeter, 1) ~
                " mm) - pick a named Bolt in Foil stabiliser, or for M6 set its Bolt dia 6.4 and Stab bolt dia 5 here; for M8, 8.4 and 6.8");
        var boltXs = [];      // world X of every stab bolt hole actually made
        const xSeat1 = min(sTE + definition.seatMargin, xEnd);
        const padW = stabRoot.padWidth != undefined && stabRoot.padWidth > 0 ? stabRoot.padWidth * meter : 2 * R;
        const rb = tapDia / 2;
        const stabBolts = stabRoot.boltX;
        var blockNote = "";
        var seatOn = false;
        var holeDir = 1;           // holes start at the seat plane and go +1 up into the body (over) or -1 down (under)
        if (over)
        {
            // fuselage over the stab: the seat is the underside, cut flat at the pad plane. A round
            // tail gives a full-width flat only if the plane sits a few mm under the axis
            const drop = zA - sBot;
            if (drop < -0.01 * millimeter)
                warnings = append(warnings, "the stab's pad plane (Z " ~ fmt(sBot / millimeter, 1) ~ " mm) is above the fuselage centreline (Z " ~ fmt(zA / millimeter, 1) ~
                    " mm), so there is nothing to seat on - set Foil stabiliser's Height to 0 or below (-4 mm is typical); no seat cut");
            else
            {
                seatOn = true;
                holeDir = 1;
                const seatW = drop < rT ? 2 * sqrt(rT * rT - drop * drop) : 2 * rT;
                if (drop > rT)
                    warnings = append(warnings, "the pad plane is " ~ fmt((drop - rT) / millimeter, 1) ~ " mm below the tube - the stab's Block to body carries it that far under the body (or set Foil stabiliser's Height nearer the centreline, -4 mm is typical, for a flush seat");
                else if (seatW < padW - 1 * millimeter && !(stabRoot.blockOn != undefined && stabRoot.blockOn == 1))
                    warnings = append(warnings, "the flat seat on the tube is only " ~ fmt(seatW / millimeter, 1) ~ " mm wide against a " ~ fmt(padW / millimeter, 0) ~
                        " mm pad - turn the Foil stabiliser's Block to body on (cheeks beside the tube), or set its Height closer to 0 for a wider flat");
                // seat: everything below the stab's mount contour (ramp from the nose, then the pad
                // plane) from the seat start to the end of the fuselage - a prism whose top is that
                // contour, lofted across the body. Build 104 cut a flat plane at the pad plane and
                // left a wedge open over the ramp (user: "a large gap at the front of the stab")
                const hw = max(R, padW / 2) + 1 * millimeter;
                const zBelow = zA - R - 2 * millimeter;
                var top = [];
                if (stabRoot.contour != undefined && size(stabRoot.contour) > 1)
                {
                    top = append(top, vector(xSeat0, stabRoot.contour[0][1] * meter));
                    for (var cp in stabRoot.contour)
                        if (cp[0] * meter > xSeat0 + 0.2 * millimeter && cp[0] * meter < xEnd - 0.2 * millimeter)
                            top = append(top, vector(cp[0] * meter, cp[1] * meter));
                }
                else
                    top = append(top, vector(xSeat0, sBot));
                top = append(top, vector(xEnd + e, sBot));
                // the cut's floor must lie under every point of the contour - with a deep seat the
                // ramp's nose end sits below the tube and the region folded over itself (build 135:
                // LOFT_FAILED at Height -10 on a 19 mm tail)
                var zBelowC = zBelow;
                for (var tp in top)
                    zBelowC = min(zBelowC, tp[1] - 2 * millimeter);
                var seatRegions = [];
                const ySeat = [-hw, hw];
                for (var i = 0; i < 2; i += 1)
                {
                    const sid = id + ("seatSec" ~ i);
                    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, ySeat[i], 0 * meter), -Y_DIRECTION, X_DIRECTION) });
                    if (size(top) > 2)
                        skFitSpline(sk, "contour", { "points" : top });
                    else
                        skLineSegment(sk, "contour", { "start" : top[0], "end" : top[1] });
                    skLineSegment(sk, "aft", { "start" : top[size(top) - 1], "end" : vector(xEnd + e, zBelowC) });
                    skLineSegment(sk, "floor", { "start" : vector(xEnd + e, zBelowC), "end" : vector(xSeat0, zBelowC) });
                    skLineSegment(sk, "fore", { "start" : vector(xSeat0, zBelowC), "end" : top[0] });
                    skSolve(sk);
                    seatRegions = append(seatRegions, qSketchRegion(sid));
                    sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
                }
                opLoft(context, id + "seatCut", { "profileSubqueries" : seatRegions });
                toolIds = append(toolIds, id + "seatCut");
                seatNote = " | seats on the stab's mount contour, X " ~ fmt(xSeat0 / millimeter, 0) ~ "-" ~ fmt(xEnd / millimeter, 0) ~ ", pad plane Z " ~ fmt(sBot / millimeter, 1) ~
                    " mm (" ~ fmt(drop / millimeter, 1) ~ " mm under the axis)" ~ (hasTail ? ", tip over the stab's tail to X " ~ fmt(xEnd / millimeter, 0) : "") ~ blockNote;
            }
        }
        else
        {
            // stab on top of the fuselage (Mount side Bottom): seat cut down to the stab's
            // lowest point, block from the axis up to it, holes down from the seat
            if (sBot > zA + rT)
                warnings = append(warnings, "the stab sits " ~ fmt((sBot - zA - rT) / millimeter, 1) ~ " mm above the fuselage - its Block to body fills the gap when on; else lower Foil stabiliser's Height by that much; no seat cut");
            else if (sBot < zA)
                warnings = append(warnings, "the stab's lowest point is below the fuselage axis - raise Foil stabiliser's Height by " ~ fmt((zA + 0.5 * rT - sBot) / millimeter, 1) ~ " mm; no seat cut");
            else
            {
                seatOn = true;
                holeDir = -1;
                const hw = R + 1 * millimeter;
                const corners = [vector(xSeat0, -hw), vector(xSeat1 + e, -hw), vector(xSeat1 + e, hw), vector(xSeat0, hw)];
                const zs = [sBot, zA + R + 1 * millimeter];
                var boxRegions = [];
                for (var i = 0; i < 2; i += 1)
                {
                    const sid = id + ("seatSec" ~ i);
                    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, 0 * meter, zs[i]), Z_DIRECTION, X_DIRECTION) });
                    for (var k = 0; k < 4; k += 1)
                        skLineSegment(sk, "edge" ~ k, { "start" : corners[k], "end" : corners[(k + 1) % 4] });
                    skSolve(sk);
                    boxRegions = append(boxRegions, qSketchRegion(sid));
                    sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
                }
                opLoft(context, id + "seatCut", { "profileSubqueries" : boxRegions });
                toolIds = append(toolIds, id + "seatCut");
                seatNote = " | stab seat on top, X " ~ fmt(xSeat0 / millimeter, 0) ~ "-" ~ fmt(xSeat1 / millimeter, 0) ~ " at Z " ~ fmt(sBot / millimeter, 1) ~ " mm" ~ blockNote;
            }
        }
        // blind tapped holes on the stab's own bolt pattern, from the seat plane into the body; each
        // must sit on the seat and leave >= 1 mm of wall beyond its end at its own X
        if (seatOn)
        {
            var made = 0;
            const xSeatEnd = over ? xEnd : xSeat1;
            for (var j = 0; j < size(stabBolts); j += 1)
            {
                const bx = stabBolts[j] * meter;
                const rLocal = min(profileRadiusAt(xs, rs, bx - rb), profileRadiusAt(xs, rs, bx + rb));
                const zcLocal = max(profileRadiusAt(xs, zcs, bx - rb), profileRadiusAt(xs, zcs, bx + rb));
                const zFar = holeDir > 0 ? zA - zcLocal + rLocal : zA - rLocal;            // body surface beyond the hole
                // the seat surface at this bolt: the mount contour where it is a ramp, else the pad plane
                var zSeat = sBot;
                if (over && stabRoot.contour != undefined && size(stabRoot.contour) > 1)
                {
                    const cpts = stabRoot.contour;
                    for (var i = 0; i < size(cpts) - 1; i += 1)
                        if (bx >= cpts[i][0] * meter && bx <= cpts[i + 1][0] * meter)
                            zSeat = (cpts[i][1] + (cpts[i + 1][1] - cpts[i][1]) * (bx / meter - cpts[i][0]) / (cpts[i + 1][0] - cpts[i][0])) * meter;
                }
                const zHoleEnd = zSeat + holeDir * definition.boltDepth;
                const wall = holeDir * (zFar - zHoleEnd);
                if (bx - rb < xSeat0 || bx + rb > xSeatEnd)
                    warnings = append(warnings, "stab bolt at X " ~ fmt(bx / millimeter, 0) ~ " mm skipped - it is off the seat; change Foil stabiliser's Bolt 1 at or Bolt pitch");
                else if (wall < 1 * millimeter)
                {
                    const maxDepth = holeDir * (zFar - zSeat) - 1 * millimeter;
                    warnings = append(warnings, "stab bolt at X " ~ fmt(bx / millimeter, 0) ~ " mm skipped - the body is only " ~ fmt((holeDir * (zFar - zSeat)) / millimeter, 1) ~ " mm deep there and a " ~
                        fmt(definition.boltDepth / millimeter, 0) ~ " mm hole would " ~
                        (wall < 0 * meter ? "break through by " ~ fmt(-wall / millimeter, 1) ~ " mm" : "leave only " ~ fmt(wall / millimeter, 1) ~ " mm") ~
                        ". Fix: Bolt depth to " ~ fmt(max(maxDepth, 0 * meter) / millimeter, 1) ~ " mm or less" ~
                        (over ? ", or lower Foil stabiliser's Height by " ~ fmt((definition.boltDepth + 1 * millimeter - holeDir * (zFar - zSeat)) / millimeter, 1) ~ " mm" :
                                ", or move the bolt forward onto the full Tail dia (Foil stabiliser's Bolt from LE / Bolt pitch)"));
                }
                else
                {
                    const base = id + ("stabBolt" ~ j);
                    const z0 = min(zSeat - holeDir * e, zHoleEnd);
                    const z1 = max(zSeat - holeDir * e, zHoleEnd);
                    holesF = append(holesF, [bx / meter, min(zSeat, zHoleEnd) / meter, max(zSeat, zHoleEnd) / meter, rb / meter, 0, 0, holeDir > 0 ? -1 : 1]);
                    toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, z0, rb, z1, rb));
                    sketchBodies = append(sketchBodies, qCreatedBy(base + "a", EntityType.BODY));
                    sketchBodies = append(sketchBodies, qCreatedBy(base + "b", EntityType.BODY));
                    boltXs = append(boltXs, bx / meter);
                    made += 1;
                }
            }
            seatNote = seatNote ~ ", " ~ fmt(made, 0) ~ " of " ~ size(stabBolts) ~ " tapped holes " ~ fmt(tapDia / millimeter, 1) ~ " mm" ~ tapNote ~ (size(stabBolts) == 0 ? " (the stab has no Mount bolts)" : "");
        }
        var pocketNote = "";
        var pkOn = false;                 // a mast pocket was cut: the mold's parting must dip under its floor (build 214)
        var pkX0 = 0 * meter;
        var pkX1 = 0 * meter;
        var pkFloor = 0 * meter;
        if (definition.pocketOn)
        {
            if (mast == undefined)
                warnings = append(warnings, "Mast pocket is on but there is no Foil mast above this feature - add one, or turn Mast pocket off; no pocket cut");
            else if (mast.baseZ * meter >= zA + R)
                warnings = append(warnings, "the mast base (Z " ~ fmt(mast.baseZ * 1000, 1) ~ " mm) is above the fuselage top (Z " ~ fmt((zA + R) / millimeter, 1) ~
                    " mm), so there is no pocket to cut - lower Foil mast's Base height (e.g. to " ~ fmt((zA + R - 20 * millimeter) / millimeter, 1) ~ " mm for a 20 mm deep pocket)");
            else
            {
                // floor follows the mast: its Base height, limited to leave >= 2 mm under the floor
                const zTop = zA + R;
                const zMin = zA - R + 2 * millimeter;
                var zFloor = mast.baseZ * meter;
                if (zFloor < zMin)
                {
                    warnings = append(warnings, "the mast base (Z " ~ fmt(zFloor / millimeter, 1) ~ " mm) is too low - the pocket would leave less than 2 mm under its floor. Pocket stopped at Z " ~
                        fmt(zMin / millimeter, 1) ~ " mm; raise Foil mast's Base height to at least " ~ fmt(zMin / millimeter, 1) ~ " mm");
                    zFloor = zMin;
                }
                const cl = definition.pocketClearance;
                const mc = mast.chord * meter;
                const pc = mc + 2 * cl;                               // pocket chord
                const pt = mast.thick * meter + 2 * cl;               // pocket thickness
                const psec = naca4Section(0, 0.4, pt / pc, (mast.te * meter + 2 * cl) / pc, mast.points);
                const ppts = placeSection(psec, pc, 0, 1, 0);
                const pzs = [zFloor, zA + R + 1 * millimeter];
                var pRegions = [];
                for (var i = 0; i < 2; i += 1)
                {
                    const sid = id + ("pocketSec" ~ i);
                    // same plane convention as the mast itself: normal +Z, sketch u = X, v = Y
                    var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(mast.leX * meter - cl, 0 * meter, pzs[i]), Z_DIRECTION, X_DIRECTION) });
                    skFitSpline(sk, "surface", { "points" : ppts });
                    skLineSegment(sk, "trailingEdge", { "start" : ppts[0], "end" : ppts[size(ppts) - 1] });
                    skSolve(sk);
                    pRegions = append(pRegions, qSketchRegion(sid));
                    sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
                }
                opLoft(context, id + "pocketCut", { "profileSubqueries" : pRegions });
                toolIds = append(toolIds, id + "pocketCut");
                pocketNote = " | mast pocket " ~ fmt((zTop - zFloor) / millimeter, 1) ~ " mm deep (floor at the mast base, Z " ~ fmt(zFloor / millimeter, 1) ~ " mm)";
                pkOn = true;
                pkX0 = mast.leX * meter - cl;
                pkX1 = (mast.leX + mast.chord) * meter + cl;
                pkFloor = zFloor;
            }
        }
        if (definition.matchWingPins && sock.pins > 0)
        {
            const pSpan = (sock.pins - 1) * sock.pinPitch * meter;
            for (var j = 0; j < sock.pins; j += 1)
            {
                const px = sock.pinCenterX * meter - pSpan / 2 + j * sock.pinPitch * meter;
                const base = id + ("wingPin" ~ j);
                holesF = append(holesF, [px / meter, (zA - rSp) / meter, (zA + rSp) / meter, sock.pinDia / 2, 0, 0, 1]);
                toolIds = append(toolIds, circleLoft(context, base, px, 0 * meter, zA - rSp - e, sock.pinDia / 2 * meter, zA + rSp + e, sock.pinDia / 2 * meter));
                sketchBodies = append(sketchBodies, qCreatedBy(base + "a", EntityType.BODY));
                sketchBodies = append(sketchBodies, qCreatedBy(base + "b", EntityType.BODY));
            }
        }
        opDeleteBodies(context, id + "deleteSketches", { "entities" : qUnion(sketchBodies) });
        if (size(toolIds) > 0)
        {
            var toolQueries = [];
            for (var t in toolIds)
                toolQueries = append(toolQueries, qCreatedBy(t, EntityType.BODY));
            const tools = qUnion(toolQueries);
            opBoolean(context, id + "cutTools", {
                        "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), tools),
                        "tools" : tools,
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
        }

        // external wetted area from the profile itself (frustum sum), rear face to tip - the solid's
        // own faces include the spigot, holes and pocket, which are not in the flow
        var wetExt = 0 * meter * meter;
        for (var k = 0; k < size(xs) - 1; k += 1)
            wetExt += PI * (rs[k] + rs[k + 1]) * sqrt((xs[k + 1] - xs[k]) ^ 2 + (rs[k + 1] - rs[k]) ^ 2);
        nameSolids(context, id, "Fuselage");
        // one body is the whole fuselage; anything more is a piece a cut severed or a part that never
        // joined, and its X range says which
        const fusBodies = evaluateQuery(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID));
        if (size(fusBodies) > 1)
        {
            var extra = "";
            for (var b in fusBodies)
            {
                const bb = evBox3d(context, { "topology" : b, "tight" : true });
                extra = extra ~ (extra == "" ? "" : ", ") ~ "X " ~ fmt(bb.minCorner[0] / millimeter, 0) ~ " to " ~ fmt(bb.maxCorner[0] / millimeter, 0) ~ " mm";
            }
            warnings = append(warnings, "this feature made " ~ size(fusBodies) ~ " bodies instead of one (" ~ extra ~ ") - a cut severed the fuselage or the spigot did not join; if two whole fuselages are listed, a second Foil fuselage feature exists in the Part Studio");
        }
        setVariable(context, "foilFuselageModel", {
                    "xFront" : xFront / meter, "xEnd" : xEnd / meter, "axisZ" : zA / meter,
                    "dia" : 2 * R / meter, "tailDia" : 2 * rT / meter,
                    "len" : (xEnd - xRear) / meter, "wettedExt" : wetExt / (meter * meter),
                    "stabBoltX" : boltXs, "stabBoltDia" : tapDia / meter,
                    "partZ" : fusPartProfile([vector(xFront - 10 * millimeter, zA), vector(xEnd + 10 * millimeter, zA)], pkOn, pkX0, pkX1, pkFloor),
                    "holes" : holesF, "stations" : fusStationsRound(xs, rs), "rootX" : xRear / meter, "seatX0" : xSeat0 / meter,
                    "wetted" : evArea(context, { "entities" : qOwnedByBody(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), EntityType.FACE) }) / (meter * meter)
                });
        foilNotice(context, id, "foilFuselageNotice",
            "Body " ~ fmt(2 * R / millimeter, 1) ~ " mm from X " ~ fmt(xRear / millimeter, 0) ~ ", parallel to X " ~ fmt(xPar / millimeter, 0) ~
            ", " ~ fmt(2 * rT / millimeter, 0) ~ " mm from X " ~ fmt(xTail / millimeter, 0) ~ ", elliptical tip X " ~ fmt(xTip / millimeter, 0) ~
            "-" ~ fmt(xEnd / millimeter, 0) ~ " mm (stab TE at X " ~ fmt(sTE / millimeter, 0) ~ ")" ~ seatNote ~ pocketNote, false);
        var fw = "";
        if (size(warnings) > 0)
        {
            var w = "Conflicts (fix in the named feature): ";
            for (var i = 0; i < size(warnings); i += 1)
                w = w ~ (i > 0 ? " · " : "") ~ warnings[i];
            foilNotice(context, id, "foilFuselageNotice", w, true);
            fw = " | " ~ w;
        }
        // console echo, so a pasted log carries the seat / bolt outcome without the notice
        var bxs = "";
        for (var b in boltXs)
            bxs = bxs ~ (bxs == "" ? "" : ",") ~ fmt(b * 1000, 1);
        foilPrint(context, "foilFuselageLog", "FUSELAGE_SEAT:" ~ seatNote ~ "; boltX_mm=[" ~ bxs ~ "]" ~ fw);
    });

/**
 * The mold's parting profile for a fuselage, as [x, z] pairs in metres (build 213/214): the given
 * polyline (x ascending, a vertical step where two points share an x), with a dip under the mast
 * pocket when one was cut - 0.2 mm inside the pocket's ends and 0.3 mm under its floor - so the
 * upper half's pocket core reaches the floor and no slab of the lower half is left trapped in it.
 */
function fusPartProfile(pts is array, pkOn is boolean, pkX0 is ValueWithUnits, pkX1 is ValueWithUnits, pkFloor is ValueWithUnits) returns array
{
    var out = [];
    const zDip = pkFloor - 0.3 * millimeter;
    const xa = pkX0 - 0.2 * millimeter;
    const xb = pkX1 + 0.2 * millimeter;
    var dipped = false;
    for (var i = 0; i < size(pts); i += 1)
    {
        const p = pts[i];
        if (pkOn && !dipped && i > 0 && pts[i - 1][0] < xa && p[0] > xb)
        {
            // the pocket lies within this segment: interpolate its two ends and dip between them
            const q = pts[i - 1];
            const zA = q[1] + (xa - q[0]) / (p[0] - q[0]) * (p[1] - q[1]);
            const zB = q[1] + (xb - q[0]) / (p[0] - q[0]) * (p[1] - q[1]);
            if (zDip < min(zA, zB))
            {
                out = append(out, [xa / meter, zA / meter]);
                out = append(out, [xa / meter, zDip / meter]);
                out = append(out, [xb / meter, zDip / meter]);
                out = append(out, [xb / meter, zB / meter]);
            }
            dipped = true;
        }
        out = append(out, [p[0] / meter, p[1] / meter]);
    }
    return out;
}

/** Round sections as [x, a, b, r] (SI) for the mold's templates and stiffness: a circle is a rounded square of half-size r with corner radius r. */
function fusStationsRound(xs is array, rs is array) returns array
{
    var out = [];
    for (var k = 0; k < size(xs); k += 1)
        out = append(out, [xs[k] / meter, rs[k] / meter, rs[k] / meter, rs[k] / meter]);
    return out;
}

/** Radius of a piecewise-linear station profile (xs ascending) at x; 0 outside it. */
function profileRadiusAt(xs is array, rs is array, x is ValueWithUnits) returns ValueWithUnits
{
    if (x < xs[0] || x > xs[size(xs) - 1])
        return 0 * meter;
    for (var i = 0; i < size(xs) - 1; i += 1)
    {
        if (x >= xs[i] && x <= xs[i + 1])
        {
            if (xs[i + 1] - xs[i] <= 0 * meter)
                return rs[i];
            return rs[i] + (x - xs[i]) / (xs[i + 1] - xs[i]) * (rs[i + 1] - rs[i]);
        }
    }
    return rs[size(rs) - 1];
}

/**
 * Hub body (build 208): the fuselage for a wing with the flat hub, built from the user's template.
 * Nose, section 3 forward: the hub's own D in plan sitting on the hub's top face, a tongue into the
 * open pocket, a top rising from Nose height above the hub at the front to the body's top at the
 * hub's back, edges rounded, countersunk clearance holes on the hub's bolt pattern. Body, section 3
 * to section 1: a rounded section Body height tall narrowing from the hub's width to Body width over
 * Body length, bottom level with the hub's underside, the mast pocket cut from its top. Tail, section
 * 1 to section 2: a loft to the stab's seat start, where the section is the pad's width by Tail
 * depth with its top (or bottom, fuselage over the stab) on the pad plane. Seat: that section carried
 * to the stab's trailing edge plus Seat margin, tapering in plan to End width, with the stab's bolt
 * holes tapped through it. Returns nothing; publishes foilFuselageModel and the notice like the tube.
 */
function buildHubFuselage(context is Context, id is Id, definition is map, hub is map, stabRoot is map, mast)
{
    var warnings = [];
    const e = 0.5 * millimeter;
    // ---- the hub, world (the map is in metres) ----
    const x0 = hub.x0 * meter;
    const x1 = hub.x1 * meter;
    const hw = hub.width / 2 * meter;
    const zTopH = hub.topZ * meter;
    const zBotH = hub.botZ * meter;
    const cl = (hub.clear != undefined ? hub.clear : 0.00015) * meter;
    const pX0 = hub.pocketX0 * meter;                                   // the pocket's front wall (clearance included)
    const tongueW = (hub.tongueW != undefined ? hub.tongueW : hub.pocketW - 2 * (hub.clear != undefined ? hub.clear : 0)) * meter;
    const pDepth = hub.pocketDepth * meter;
    const noseF = hub.noseOn != undefined && hub.noseOn == 1;          // the wing's nose fairing takes the nose (wing 1.070): a flat face on the wall
    const zNose = noseF ? hub.noseTopZ * meter : zTopH + definition.noseHeight;
    const xNose0 = noseF ? pX0 : x0;                                    // where this body starts: the wall's plane, or the hub's front
    const zBody = zBotH + definition.bodyHeight;                        // the body's top
    if (zBody < zTopH + 3 * millimeter)
        throw regenError("Body height puts the body's top under the hub's top + 3 mm - raise Body height (the hub is " ~ fmt((zTopH - zBotH) / millimeter, 1) ~ " mm from its underside to its top)", ["bodyHeight"]);
    if (zNose > zBody + 0.01 * millimeter)
    {
        // an error, not a quiet adjustment (user: "errors are better than silent failures")
        if (noseF)
            throw regenError("the wing's nose fairing tops out at Z " ~ fmt(zNose / millimeter, 1) ~ " mm, above this body's top (Z " ~ fmt(zBody / millimeter, 1) ~ ", Body height " ~ fmt(definition.bodyHeight / millimeter, 1) ~ ") - set Body height to " ~ fmt((zNose - zBotH) / millimeter, 1) ~ " or more, or lower Nose height on the Foil wing", ["bodyHeight"]);
        throw regenError("Nose height puts the nose's front above the body's top - lower Nose height or raise Body height", ["noseHeight", "bodyHeight"]);
    }
    const rE = definition.edgeRound;
    // ---- the stab ----
    const sLE = stabRoot.leX * meter;
    const sTE = stabRoot.teX * meter;
    const over = stabRoot.padSide == 1;
    const sBot = over ? (stabRoot.padOn == 1 ? stabRoot.padZ : stabRoot.topZ) * meter : stabRoot.bottomZ * meter;
    const padW = stabRoot.padWidth != undefined && stabRoot.padWidth > 0 ? stabRoot.padWidth * meter : 20 * millimeter;
    const xSeat0 = sLE - definition.seatMargin;
    const xSeat1 = sTE + definition.seatMargin;
    const tD = definition.tailDepth;
    const zSeatTop = over ? sBot + tD : sBot;
    const zSeatBot = over ? sBot : sBot - tD;
    const xS1 = x1 + definition.bodyLength;                              // section 1
    if (xS1 > xSeat0 - 20 * millimeter)
        throw regenError("Body length runs into the stab's seat (section 1 at X " ~ fmt(xS1 / millimeter, 0) ~ ", seat from X " ~ fmt(xSeat0 / millimeter, 0) ~ " mm) - shorten Body length or lengthen the stab's Arm", ["bodyLength"]);
    var sketchBodies = [];

    var noseRound = 0 * meter;
    var noseFaceR = 0 * meter;             // the flat face's top corners with the wing's nose fairing on
    if (noseF)
    {
        // the wing's nose fairing takes the nose: this body starts with a flat face on the pocket's front wall, the
        // fairing's back face (the hub's width, Nose height above the hub's top, Crown round on its top corners), and
        // grows to the body's top and Edge round by the hub's back
        const rcF = min(hub.noseRound != undefined ? hub.noseRound * meter : 0 * meter, min(0.45 * hw, 0.45 * (zNose - zTopH)));
        const rcB = max(min(rE, min(0.45 * hw, 0.45 * (zBody - zTopH))), 0 * meter);
        noseFaceR = rcF;
        const secF = [[pX0, zNose, rcF], [x1 + e, zBody, rcB]];
        var fRegions = [];
        for (var i = 0; i < 2; i += 1)
        {
            const sid = id + ("noseFace" ~ i);
            var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(secF[i][0], 0 * meter, 0 * meter), X_DIRECTION, Y_DIRECTION) });
            boxTopRound(sk, hw, zTopH, secF[i][1], secF[i][2]);
            skSolve(sk);
            fRegions = append(fRegions, qSketchRegion(sid));
            sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
        }
        opLoft(context, id + "noseSideLoft", { "profileSubqueries" : fRegions });
    }
    else
    {
    // ---- nose: side profile (X, Z) intersected with the hub's D in plan ----
    const yS = [-(hw + 2 * millimeter), hw + 2 * millimeter];
    var sideRegions = [];
    for (var i = 0; i < 2; i += 1)
    {
        const sid = id + ("noseSide" ~ i);
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(0 * meter, yS[i], 0 * meter), -Y_DIRECTION, X_DIRECTION) });
        const a = vector(x0 - 1 * millimeter, zTopH);
        const b = vector(x1 + e, zTopH);
        const c = vector(x1 + e, zBody);
        const d = vector(x0 - 1 * millimeter, zNose + (zBody - zNose) * (-1 * millimeter) / (x1 - x0));
        skLineSegment(sk, "bottom", { "start" : a, "end" : b });
        skLineSegment(sk, "back", { "start" : b, "end" : c });
        skLineSegment(sk, "top", { "start" : c, "end" : d });
        skLineSegment(sk, "front", { "start" : d, "end" : a });
        skSolve(sk);
        sideRegions = append(sideRegions, qSketchRegion(sid));
        sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
    }
    opLoft(context, id + "noseSideLoft", { "profileSubqueries" : sideRegions });
    hubStadium(context, id + "noseD", x0, x1 + e, hw, zTopH - 1 * millimeter, zBody + 5 * millimeter);
    opBoolean(context, id + "noseShape", {
                "tools" : qUnion([qCreatedBy(id + "noseSideLoft", EntityType.BODY), qCreatedBy(id + "noseD" + "loft", EntityType.BODY)]),
                "operationType" : BooleanOperationType.INTERSECTION
            });
    // round the nose's top edges (the intersection's edges above the hub's top); ladder, sharp if none takes
    if (rE > 0.1 * millimeter)
    {
        var topEdges = [];
        for (var ed in evaluateQuery(context, qCreatedBy(id + "noseShape", EntityType.EDGE)))
        {
            const eb = evBox3d(context, { "topology" : ed, "tight" : true });
            if (eb.minCorner[2] > zTopH + 0.5 * millimeter)
                topEdges = append(topEdges, ed);
        }
        const ladder = [rE, 0.6 * rE, 0.35 * rE];
        for (var k = 0; k < size(ladder); k += 1)
        {
            if (noseRound > 0 * meter || size(topEdges) == 0)
                continue;
            try silent
            {
                opFillet(context, id + ("noseRound" ~ k), { "entities" : qUnion(topEdges), "radius" : ladder[k], "tangentPropagation" : false });
                noseRound = ladder[k];
            }
        }
    }
    }
    // ---- tongue into the open pocket ----
    // the tongue's underside on the wing's pocket floor (build 241: a V groove or ridge, offset up by the clearance
    // along each face, its corners at the pocket's radius less the clearance where the pocket's is convex, plus it
    // where concave; twin tuning/hub_v/hub_v_twin.py)
    const vdF = hub.vDepth != undefined ? hub.vDepth * meter : 0 * meter;
    const pwF = tongueW / 2 + cl;                                         // the pocket's half width
    const kF = cl * sqrt(1 + (vdF / pwF) * (vdF / pwF));
    const zWallF = hub.floorWallZ != undefined ? hub.floorWallZ * meter : zTopH - pDepth;   // the pocket floor at its walls
    const zT0 = abs(vdF) > 0.01 * millimeter ? zWallF - vdF + kF : zTopH - pDepth + cl;   // the tongue's underside on the centreline
    if (abs(vdF) > 0.01 * millimeter)
    {
        const rV = hub.vFillet != undefined ? hub.vFillet * meter : 0 * meter;
        const rSh = rV > 0.05 * millimeter ? max(rV - cl, 0.2 * millimeter) : 0 * meter;
        const rAp = rV > 0.05 * millimeter ? (vdF > 0 * meter ? max(rV - cl, 0.2 * millimeter) : rV + cl) : 0 * meter;
        hubVPrism(context, id + "tongue", pX0 + cl, x1 + e, tongueW / 2, zWallF - vdF * cl / pwF + kF, zT0, zTopH + 1 * millimeter, rSh, rAp, false);
    }
    else
        moldBox(context, id + "tongue", vector(pX0 + cl, -tongueW / 2, zTopH - pDepth + cl), vector(x1 + e, tongueW / 2, zTopH + 1 * millimeter));

    // ---- body, tail and seat: lofts of rounded sections sharing their end sections ----
    const hh = definition.bodyHeight / 2;
    const zcB = zBotH + hh;
    const secs = [
        { "id" : "secHub", "x" : x1, "a" : hw, "b" : hh, "zc" : zcB },
        { "id" : "sec1", "x" : xS1, "a" : definition.bodyWidth / 2, "b" : hh, "zc" : zcB },
        { "id" : "sec2", "x" : xSeat0, "a" : padW / 2, "b" : tD / 2, "zc" : (zSeatTop + zSeatBot) / 2 },
        { "id" : "secEnd", "x" : xSeat1, "a" : definition.endWidth / 2, "b" : tD / 2, "zc" : (zSeatTop + zSeatBot) / 2 }
    ];
    var regionOf = {};
    for (var sd in secs)
    {
        const sid = id + sd.id;
        var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(sd.x, 0 * meter, sd.zc), X_DIRECTION, Y_DIRECTION) });
        roundedRect(sk, sd.a, sd.b, max(min(rE, 0.45 * min(sd.a, sd.b)), 0.2 * millimeter));
        skSolve(sk);
        regionOf[sd.id] = qSketchRegion(sid);
        sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
    }
    opLoft(context, id + "bodyLoft", { "profileSubqueries" : [regionOf.secHub, regionOf.sec1] });
    opLoft(context, id + "tailLoft", { "profileSubqueries" : [regionOf.sec1, regionOf.sec2] });
    opLoft(context, id + "seatLoft", { "profileSubqueries" : [regionOf.sec2, regionOf.secEnd] });
    opBoolean(context, id + "hubJoin", {
                "tools" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                "operationType" : BooleanOperationType.UNION
            });

    // ---- tools: mast pocket, the hub's bolt holes through the nose, the stab's tapped holes ----
    var toolIds = [];
    var pocketNote = "";
    var pkOn = false;                     // a mast pocket was cut: the mold's parting must dip under its floor (build 214)
    var pkX0 = 0 * meter;
    var pkX1 = 0 * meter;
    var pkFloor = 0 * meter;
    if (definition.pocketOn)
    {
        if (mast == undefined)
            warnings = append(warnings, "Mast pocket is on but there is no Foil mast above this feature - add one, or turn Mast pocket off; no pocket cut");
        else if (mast.baseZ * meter >= zBody)
            warnings = append(warnings, "the mast base (Z " ~ fmt(mast.baseZ * 1000, 1) ~ " mm) is above the body's top (Z " ~ fmt(zBody / millimeter, 1) ~ " mm), so there is no pocket to cut - lower Foil mast's Base height");
        else
        {
            const zMin = zBotH + 2 * millimeter;
            var zFloor = mast.baseZ * meter;
            if (zFloor < zMin)
            {
                warnings = append(warnings, "the mast base (Z " ~ fmt(zFloor / millimeter, 1) ~ " mm) is too low - the pocket would leave less than 2 mm under its floor. Pocket stopped at Z " ~ fmt(zMin / millimeter, 1) ~ " mm; raise Foil mast's Base height");
                zFloor = zMin;
            }
            const mLE = mast.leX * meter;
            const mTE = (mast.leX + mast.chord) * meter;
            if (mLE < x1 + 2 * millimeter || mTE > xS1 - 2 * millimeter)
                warnings = append(warnings, "the mast (X " ~ fmt(mLE / millimeter, 0) ~ " to " ~ fmt(mTE / millimeter, 0) ~ " mm) is not within the body between the hub's back (X " ~ fmt(x1 / millimeter, 0) ~ ") and section 1 (X " ~ fmt(xS1 / millimeter, 0) ~ " mm) - move Foil mast's Mast X or lengthen Body length");
            const pcl = definition.pocketClearance;
            const mc = mast.chord * meter;
            const pc = mc + 2 * pcl;
            const pt = mast.thick * meter + 2 * pcl;
            const psec = naca4Section(0, 0.4, pt / pc, (mast.te * meter + 2 * pcl) / pc, mast.points);
            const ppts = placeSection(psec, pc, 0, 1, 0);
            const pzs = [zFloor, zBody + 1 * millimeter];
            var pRegions = [];
            for (var i = 0; i < 2; i += 1)
            {
                const sid = id + ("pocketSec" ~ i);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(mLE - pcl, 0 * meter, pzs[i]), Z_DIRECTION, X_DIRECTION) });
                skFitSpline(sk, "surface", { "points" : ppts });
                skLineSegment(sk, "trailingEdge", { "start" : ppts[0], "end" : ppts[size(ppts) - 1] });
                skSolve(sk);
                pRegions = append(pRegions, qSketchRegion(sid));
                sketchBodies = append(sketchBodies, qCreatedBy(sid, EntityType.BODY));
            }
            opLoft(context, id + "pocketCut", { "profileSubqueries" : pRegions });
            toolIds = append(toolIds, id + "pocketCut");
            pocketNote = " | mast pocket " ~ fmt((zBody - zFloor) / millimeter, 1) ~ " mm deep (floor at the mast base, Z " ~ fmt(zFloor / millimeter, 1) ~ " mm)";
            pkOn = true;
            pkX0 = mLE - pcl;
            pkX1 = mTE + pcl;
            pkFloor = zFloor;
        }
    }
    // the hub's bolts: clearance holes down through the nose and tongue, countersunk on top; or (build
    // 235, the wing's Bolts from = Wing underside) blind tapped holes up from the tongue's underside,
    // about 1.5 x the bolt's diameter deep, less where the nose is lower (1 mm left under its top)
    var nNose = 0;
    var holesF = [];                       // every vertical hole, for the mold: [x, z0, z1, r, rHead, cskSide, pinFrom, blind end (1 top, -1 bottom, 0 through)] (SI)
    const rC = (hub.boltClear != undefined ? hub.boltClear : hub.holeDia + 0.0005) / 2 * meter;
    const rH = hub.boltHead != undefined && hub.boltHead > 0 ? hub.boltHead / 2 * meter : 0 * meter;
    var noseBoltNote = "";
    const fromUnder = hub.boltSide != undefined && hub.boltSide == "UNDERSIDE";
    if (hub.boltX != undefined && fromUnder)
    {
        const rTap = (hub.tapDia != undefined && hub.tapDia > 0 ? hub.tapDia : 0.78 * hub.holeDia) / 2 * meter;
        const dBolt = (hub.boltDia != undefined && hub.boltDia > 0 ? hub.boltDia : hub.holeDia / 1.07) * meter;
        // the tongue's underside on the centreline: zT0, above (a V groove or ridge moves it)
        var dMin = 1 * meter;
        var shortNote = "";
        for (var j = 0; j < size(hub.boltX); j += 1)
        {
            const bx = hub.boltX[j] * meter;
            if (bx - rTap < pX0 + cl + 1 * millimeter || bx + rTap > x1 - 1 * millimeter)
            {
                warnings = append(warnings, "the hub's bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ " mm is off the tongue (X " ~ fmt((pX0 + cl) / millimeter, 0) ~ " to " ~ fmt(x1 / millimeter, 0) ~ ") - no hole; move the wing's Bolt 1 from or Bolt pitch");
                continue;
            }
            const zTopAt = zNose + (zBody - zNose) * (bx - xNose0) / (x1 - xNose0);
            const dHole = min(1.5 * dBolt, zTopAt - 1 * millimeter - zT0);
            if (dHole < 2 * millimeter)
            {
                warnings = append(warnings, "the hub's bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ " mm has no room for a thread in the nose (" ~ fmt((zTopAt - zT0) / millimeter, 1) ~ " mm deep there) - no hole; raise Nose height");
                continue;
            }
            if (dHole < 1 * dBolt)
                shortNote = shortNote ~ " bolt " ~ (j + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ " gets only " ~ fmt(dHole / millimeter, 1) ~ " mm of thread (the nose is " ~ fmt((zTopAt - zT0) / millimeter, 1) ~ " mm deep there);";
            dMin = min(dMin, dHole);
            const base = id + ("noseTap" ~ j);
            holesF = append(holesF, [bx / meter, zT0 / meter, (zT0 + dHole) / meter, rTap / meter, 0, 0, -1, 1]);
            toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, zT0 - 1 * millimeter, rTap, zT0 + dHole, rTap));
            sketchBodies = append(sketchBodies, qCreatedBy(base + "a", EntityType.BODY));
            sketchBodies = append(sketchBodies, qCreatedBy(base + "b", EntityType.BODY));
            nNose += 1;
        }
        if (shortNote != "")
            warnings = append(warnings, "short threads for the wing's bolts:" ~ shortNote ~ " raise Nose height or the wing's Pocket depth, or use a smaller Hub bolt");
        noseBoltNote = "; " ~ nNose ~ " x " ~ (hub.boltName != undefined ? hub.boltName : "") ~ " blind tapped holes " ~ fmt(2 * rTap / millimeter, 1) ~ " mm up from the tongue's underside" ~
            (nNose > 0 ? ", " ~ fmt(dMin / millimeter, 1) ~ " mm deep or more" : "") ~ " for the wing's bolts, which come up through it from its underside (no holes or countersinks on the nose)";
    }
    if (hub.boltX != undefined && !fromUnder)
    {
        for (var j = 0; j < size(hub.boltX); j += 1)
        {
            const bx = hub.boltX[j] * meter;
            if (bx - rC < x0 + 1 * millimeter || bx + rC > x1 - 1 * millimeter)
                continue;
            const zTopAt = zNose + (zBody - zNose) * (bx - xNose0) / (x1 - xNose0);
            const base = id + ("noseBolt" ~ j);
            holesF = append(holesF, [bx / meter, zT0 / meter, zTopAt / meter, rC / meter, (definition.noseCsk && rH > rC + 0.3 * millimeter ? rH : 0 * meter) / meter, definition.noseCsk && rH > rC + 0.3 * millimeter ? 1 : 0, 1, 0]);
            toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, min(zT0, zTopH - pDepth) - 1 * millimeter, rC, zTopAt + 2 * millimeter, rC));
            sketchBodies = append(sketchBodies, qCreatedBy(base + "a", EntityType.BODY));
            sketchBodies = append(sketchBodies, qCreatedBy(base + "b", EntityType.BODY));
            if (definition.noseCsk && rH > rC + 0.3 * millimeter)
            {
                const cb = id + ("noseCsk" ~ j);
                toolIds = append(toolIds, circleLoft(context, cb, bx, 0 * meter, zTopAt - (rH - rC), rC, zTopAt + 2 * millimeter, rH + 2 * millimeter));
                sketchBodies = append(sketchBodies, qCreatedBy(cb + "a", EntityType.BODY));
                sketchBodies = append(sketchBodies, qCreatedBy(cb + "b", EntityType.BODY));
            }
            nNose += 1;
        }
        noseBoltNote = "; " ~ nNose ~ " x " ~ (hub.boltName != undefined ? hub.boltName : "") ~ " clearance holes " ~ fmt(2 * rC / millimeter, 1) ~ " mm" ~
            (definition.noseCsk && rH > rC + 0.3 * millimeter ? " countersunk " ~ fmt(2 * rH / millimeter, 1) ~ " mm on top" : "") ~ (hub.boltSide != undefined && hub.boltSide == "NUTS" ? " down through the wing into its nut inserts" : " down into the hub's blind holes");
    }
    // the stab's bolts: tapped through the seat block, or blind to Bolt depth when the block is deeper
    const tapFromStab = stabRoot.tapDia != undefined && stabRoot.tapDia > 0;
    const tapDia = tapFromStab ? stabRoot.tapDia * meter : definition.stabBoltDia;
    const rb = tapDia / 2;
    var boltXs = [];
    var made = 0;
    const through = definition.boltDepth >= tD - 1 * millimeter;
    if (stabRoot.boltX != undefined)
    {
        for (var j = 0; j < size(stabRoot.boltX); j += 1)
        {
            const bx = stabRoot.boltX[j] * meter;
            if (bx - rb < xSeat0 + 1 * millimeter || bx + rb > xSeat1 - 1 * millimeter)
            {
                warnings = append(warnings, "stab bolt at X " ~ fmt(bx / millimeter, 0) ~ " mm skipped - off the seat block (X " ~ fmt(xSeat0 / millimeter, 0) ~ " to " ~ fmt(xSeat1 / millimeter, 0) ~ "); change the stab's Bolt 1 at or Bolt pitch, or Seat margin");
                continue;
            }
            const base = id + ("stabBolt" ~ j);
            const z0 = through ? zSeatBot - 1 * millimeter : (over ? sBot - e : sBot - definition.boltDepth);
            const z1 = through ? zSeatTop + 1 * millimeter : (over ? sBot + definition.boltDepth : sBot + e);
            holesF = append(holesF, [bx / meter, (through ? zSeatBot : (over ? sBot : sBot - definition.boltDepth)) / meter, (through ? zSeatTop : (over ? sBot + definition.boltDepth : sBot)) / meter, rb / meter, 0, 0, over ? -1 : 1, through ? 0 : (over ? 1 : -1)]);
            toolIds = append(toolIds, circleLoft(context, base, bx, 0 * meter, z0, rb, z1, rb));
            sketchBodies = append(sketchBodies, qCreatedBy(base + "a", EntityType.BODY));
            sketchBodies = append(sketchBodies, qCreatedBy(base + "b", EntityType.BODY));
            boltXs = append(boltXs, bx / meter);
            made += 1;
        }
    }
    opDeleteBodies(context, id + "deleteSketches", { "entities" : qUnion(sketchBodies) });
    if (size(toolIds) > 0)
    {
        var toolQueries = [];
        for (var t in toolIds)
            toolQueries = append(toolQueries, qCreatedBy(t, EntityType.BODY));
        const tools = qUnion(toolQueries);
        opBoolean(context, id + "cutTools", {
                    "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), tools),
                    "tools" : tools,
                    "operationType" : BooleanOperationType.SUBTRACTION
                });
    }

    // ---- wetted area from the sections (rounded-rectangle perimeters), model, notice ----
    const perim = function(a, b, r) { return 4 * (a + b) - (8 - 2 * PI) * r; };
    var wetExt = 0 * meter * meter;
    for (var k = 0; k < size(secs) - 1; k += 1)
    {
        const p0 = perim(secs[k].a, secs[k].b, max(min(rE, 0.45 * min(secs[k].a, secs[k].b)), 0.2 * millimeter));
        const p1 = perim(secs[k + 1].a, secs[k + 1].b, max(min(rE, 0.45 * min(secs[k + 1].a, secs[k + 1].b)), 0.2 * millimeter));
        wetExt += 0.5 * (p0 + p1) * (secs[k + 1].x - secs[k].x);
    }
    wetExt += (2 * hw + 2 * (zBody - zTopH)) * (x1 - x0);                  // the nose's top and sides, roughly
    nameSolids(context, id, "Fuselage");
    const fusBodies = evaluateQuery(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID));
    if (size(fusBodies) > 1)
    {
        var extra = "";
        for (var b in fusBodies)
        {
            const bb = evBox3d(context, { "topology" : b, "tight" : true });
            extra = extra ~ (extra == "" ? "" : ", ") ~ "X " ~ fmt(bb.minCorner[0] / millimeter, 0) ~ " to " ~ fmt(bb.maxCorner[0] / millimeter, 0) ~ " mm";
        }
        warnings = append(warnings, "this feature made " ~ size(fusBodies) ~ " bodies instead of one (" ~ extra ~ ") - a section did not join or a cut severed the body; inspect them");
    }
    const dEq = 2 * sqrt(definition.bodyWidth * definition.bodyHeight / PI);
    const dTailEq = 2 * sqrt(padW * tD / PI);
    setVariable(context, "foilFuselageModel", {
                "xFront" : x0 / meter, "xEnd" : xSeat1 / meter, "axisZ" : zcB / meter,
                "dia" : dEq / meter, "tailDia" : dTailEq / meter,
                "len" : (xSeat1 - x0) / meter, "wettedExt" : wetExt / (meter * meter),
                "stabBoltX" : boltXs, "stabBoltDia" : tapDia / meter, "body" : "HUB",
                "partZ" : fusPartProfile([vector(x0 - 10 * millimeter, zTopH), vector(x1 + 0.2 * millimeter, zTopH), vector(x1 + 0.2 * millimeter, zcB), vector(xS1, zcB),
                                          vector(xSeat0, (zSeatTop + zSeatBot) / 2), vector(xSeat1 + 10 * millimeter, (zSeatTop + zSeatBot) / 2)], pkOn, pkX0, pkX1, pkFloor),
                "holes" : holesF, "rootX" : x1 / meter, "seatX0" : xSeat0 / meter,
                "stations" : [[x0 / meter, hw / meter, (zNose - (zTopH - pDepth)) / 2 / meter, rE / meter], [x1 / meter, hw / meter, (zBody - (zTopH - pDepth)) / 2 / meter, rE / meter],
                              [x1 / meter, hw / meter, hh / meter, min(rE, 0.45 * min(hw, hh)) / meter], [xS1 / meter, definition.bodyWidth / 2 / meter, hh / meter, min(rE, 0.45 * min(definition.bodyWidth / 2, hh)) / meter],
                              [xSeat0 / meter, padW / 2 / meter, tD / 2 / meter, min(rE, 0.45 * min(padW / 2, tD / 2)) / meter], [xSeat1 / meter, definition.endWidth / 2 / meter, tD / 2 / meter, min(rE, 0.45 * min(definition.endWidth / 2, tD / 2)) / meter]],
                "wetted" : evArea(context, { "entities" : qOwnedByBody(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), EntityType.FACE) }) / (meter * meter)
            });
    const seatNote = " | seat " ~ fmt(padW / millimeter, 0) ~ " x " ~ fmt(tD / millimeter, 0) ~ " mm " ~ (over ? "over" : "under") ~ " the stab's pad plane (Z " ~ fmt(sBot / millimeter, 1) ~ ") from X " ~ fmt(xSeat0 / millimeter, 0) ~
        " to " ~ fmt(xSeat1 / millimeter, 0) ~ " mm, tapering to " ~ fmt(definition.endWidth / millimeter, 0) ~ " mm; " ~ made ~ " of " ~ (stabRoot.boltX == undefined ? 0 : size(stabRoot.boltX)) ~ " tapped holes " ~ fmt(tapDia / millimeter, 1) ~ " mm" ~
        (tapFromStab ? " for " ~ stabRoot.boltName : "") ~ (through ? " through the block" : " " ~ fmt(definition.boltDepth / millimeter, 0) ~ " mm deep");
    foilNotice(context, id, "foilFuselageNotice",
        (noseF ? "Hub body: a flat face on the pocket's front wall (X " ~ fmt(pX0 / millimeter, 0) ~ " mm), " ~ fmt(2 * hw / millimeter, 0) ~ " wide x " ~ fmt((zNose - zTopH) / millimeter, 1) ~ " mm above the hub's top (Z " ~ fmt(zTopH / millimeter, 1) ~ "), the wing's nose fairing ahead of it, rising to the body's top at Z "
            : "Hub body: nose " ~ fmt(2 * hw / millimeter, 0) ~ " x " ~ fmt((x1 - x0) / millimeter, 0) ~ " mm on the hub's top (Z " ~ fmt(zTopH / millimeter, 1) ~ "), " ~ fmt(definition.noseHeight / millimeter, 0) ~ " mm tall at the front rising to the body's top at Z ") ~
        fmt(zBody / millimeter, 1) ~ (noseF ? ", its top corners R " ~ fmt(noseFaceR / millimeter, 1) ~ " at the face (the wing's Crown round) to Edge round by the hub's back" : (noseRound > 0 * meter ? ", edges rounded " ~ fmt(noseRound / millimeter, 1) : ", edges sharp (the round failed)")) ~ "; tongue " ~ fmt(tongueW / millimeter, 1) ~ " x " ~ fmt((pDepth - cl) / millimeter, 2) ~ " mm into the pocket from X " ~ fmt((pX0 + cl) / millimeter, 0) ~
        noseBoltNote ~ " | body " ~ fmt(definition.bodyHeight / millimeter, 0) ~ " mm tall from " ~ fmt(2 * hw / millimeter, 0) ~ " to " ~ fmt(definition.bodyWidth / millimeter, 0) ~ " mm wide at section 1, X " ~ fmt(xS1 / millimeter, 0) ~
        " | tail to the seat at X " ~ fmt(xSeat0 / millimeter, 0) ~ " (" ~ fmt((xSeat0 - xS1) / millimeter, 0) ~ " mm, set by the stab's Arm)" ~ seatNote ~ pocketNote ~
        " (Parallel aft, Tail dia, Overhang and Tip length are the round tube's and do nothing here)", false);
    var fw = "";
    if (size(warnings) > 0)
    {
        var w = "Conflicts (fix in the named feature): ";
        for (var i = 0; i < size(warnings); i += 1)
            w = w ~ (i > 0 ? " · " : "") ~ warnings[i];
        foilNotice(context, id, "foilFuselageNotice", w, true);
        fw = " | " ~ w;
    }
    var bxs = "";
    for (var b in boltXs)
        bxs = bxs ~ (bxs == "" ? "" : ",") ~ fmt(b * 1000, 1);
    foilPrint(context, "foilFuselageLog", "FUSELAGE_SEAT: hub body" ~ seatNote ~ "; boltX_mm=[" ~ bxs ~ "]" ~ fw);
}

function fuselageInputLog(definition is map) returns string
{
    return "FUSELAGE_INPUTS: toolVersion=" ~ FOIL_FUSELAGE_VERSION
        ~ "; fusBody=" ~ (definition.fusBody == FusBody.HUB ? "HUB" : (definition.fusBody == FusBody.TUBE ? "TUBE" : "AUTO"))
        ~ (definition.fusBody != FusBody.TUBE ? "; noseHeight_mm=" ~ fmt(definition.noseHeight / millimeter, 1) ~ "; bodyHeight_mm=" ~ fmt(definition.bodyHeight / millimeter, 1) ~ "; bodyWidth_mm=" ~ fmt(definition.bodyWidth / millimeter, 1)
            ~ "; bodyLength_mm=" ~ fmt(definition.bodyLength / millimeter, 1) ~ "; tailDepth_mm=" ~ fmt(definition.tailDepth / millimeter, 1) ~ "; endWidth_mm=" ~ fmt(definition.endWidth / millimeter, 1) ~ "; edgeRound_mm=" ~ fmt(definition.edgeRound / millimeter, 1) ~ "; noseCsk=" ~ (definition.noseCsk ? "1" : "0") : "")
        ~ "; fusParAft_mm=" ~ fmt(definition.fusParAft / millimeter, 1)
        ~ "; fusTailDia_mm=" ~ fmt(definition.fusTailDia / millimeter, 1)
        ~ "; overhang_mm=" ~ fmt(definition.overhang / millimeter, 1)
        ~ "; tipLength_mm=" ~ fmt(definition.tipLength / millimeter, 1)

        ~ "; seatMargin_mm=" ~ fmt(definition.seatMargin / millimeter, 1)
        ~ "; stabBoltDia_mm=" ~ fmt(definition.stabBoltDia / millimeter, 2)
        ~ "; boltDepth_mm=" ~ fmt(definition.boltDepth / millimeter, 1)
        ~ "; pocketOn=" ~ (definition.pocketOn ? "true" : "false")
        ~ (definition.pocketOn ? "; pocketClearance_mm=" ~ fmt(definition.pocketClearance / millimeter, 2) : "")
        ~ "; matchWingPins=" ~ (definition.matchWingPins ? "true" : "false");
}


// ---------------------------------------------------------------------------
// Performance library (all SI numbers: m, m^2, rad, N)
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Input logging - prints every parameter as one pasteable line
// ---------------------------------------------------------------------------

function enumStr_tipProfile(p is TipProfile) returns string
{
    if (p == TipProfile.NACA4) return "NACA4";
    if (p == TipProfile.E817) return "E817";
    if (p == TipProfile.E818) return "E818";
    if (p == TipProfile.NACA63412) return "NACA63412";
    if (p == TipProfile.CLARKY) return "CLARKY";
    if (p == TipProfile.MRC16) return "MRC16";
    if (p == TipProfile.MH18) return "MH18";
    if (p == TipProfile.H105) return "H105";
    return "SAME";
}

/** The FoilProfile a TipProfile names (SAME is never passed here). */
function tipToFoilProfile(p is TipProfile) returns FoilProfile
{
    if (p == TipProfile.E817) return FoilProfile.E817;
    if (p == TipProfile.E818) return FoilProfile.E818;
    if (p == TipProfile.NACA63412) return FoilProfile.NACA63412;
    if (p == TipProfile.CLARKY) return FoilProfile.CLARKY;
    if (p == TipProfile.MRC16) return FoilProfile.MRC16;
    if (p == TipProfile.MH18) return FoilProfile.MH18;
    if (p == TipProfile.H105) return FoilProfile.H105;
    return FoilProfile.NACA4;
}

/**
 * Section map for one surface, from a feature definition (buildFoil) or a published model map
 * (the mold): the root keys buildSection reads (profile, camber, camberPos, invertSection) plus
 * the tip section (tipOn, tipProfile as a FoilProfile, tipCamber, tipCamberPos, blendFrom as a
 * fraction). Build 166.
 */
function sectionDefFromDefinition(definition is map) returns map
{
    const tipOn = definition.tipProfile != undefined && definition.tipProfile != TipProfile.SAME;
    return { "profile" : definition.profile, "camber" : definition.camber, "camberPos" : definition.camberPos, "invertSection" : definition.invertSection == true,
             "tipOn" : tipOn, "tipProfile" : tipOn ? tipToFoilProfile(definition.tipProfile) : definition.profile,
             "tipCamber" : tipOn && definition.tipCamber != undefined ? definition.tipCamber : 0, "tipCamberPos" : tipOn && definition.tipCamberPos != undefined ? definition.tipCamberPos : 40,
             "blendFrom" : tipOn ? definition.blendFrom / 100 : 0 };
}

function sectionDefFromModel(m is map) returns map
{
    const tipOn = m.tipOn == 1;
    return { "profile" : profileFromName(m.profileName), "camber" : m.camber, "camberPos" : m.camberPos, "invertSection" : m.inverted == 1,
             "tipOn" : tipOn, "tipProfile" : tipOn ? profileFromName(m.tipProfileName) : profileFromName(m.profileName),
             "tipCamber" : tipOn ? m.tipCamber : 0, "tipCamberPos" : tipOn ? m.tipCamberPos : 40, "blendFrom" : tipOn ? m.blendFrom : 0 };
}

/** The tip section's own map, for buildSection / sectionAlpha0Cm0. */
function tipSectionDef(d is map) returns map
{
    return { "profile" : d.tipProfile, "camber" : d.tipCamber, "camberPos" : d.tipCamberPos, "invertSection" : d.invertSection };
}

/** Share of the tip section at eta: 0 out to blendFrom, then a smoothstep to 1 at the tip. */
function sectionWeightAt(d is map, eta is number) returns number
{
    if (d.tipOn != true || eta <= d.blendFrom)
        return 0;
    const u = min((eta - d.blendFrom) / max(1 - d.blendFrom, 1e-6), 1);
    return u * u * (3 - 2 * u);
}

/**
 * The section at one station: the root's, the tip's, or a point-by-point blend of the two (both
 * are sampled on the same cosine x stations with the same point count, so index i is the same
 * chordwise place on each).
 */
function buildSectionAt(d is map, thick is number, teFrac is number, n is number, w is number) returns array
{
    if (w <= 0)
        return buildSection(d, thick, teFrac, n);
    const tipPts = buildSection(tipSectionDef(d), thick, teFrac, n);
    if (w >= 1)
        return tipPts;
    const rootPts = buildSection(d, thick, teFrac, n);
    var out = [];
    for (var i = 0; i < size(rootPts); i += 1)
        out = append(out, rootPts[i] * (1 - w) + tipPts[i] * w);
    return out;
}

function enumStr_profile(p is FoilProfile) returns string
{
    if (p == FoilProfile.E817) return "E817";
    if (p == FoilProfile.E818) return "E818";
    if (p == FoilProfile.NACA63412) return "NACA63412";
    if (p == FoilProfile.CLARKY) return "CLARKY";
    if (p == FoilProfile.MRC16) return "MRC16";
    if (p == FoilProfile.MH18) return "MH18";
    if (p == FoilProfile.H105) return "H105";
    return "NACA4";
}

function enumStr_polarSource(p is PolarSource) returns string
{
    if (p == PolarSource.POLAR) return "POLAR";
    if (p == PolarSource.BUILTIN) return "BUILTIN";
    return "ANALYTIC";
}

function enumStr_pivot(p is FoilPivot) returns string
{
    if (p == FoilPivot.LEADING_EDGE) return "LEADING_EDGE";
    if (p == FoilPivot.TRAILING_EDGE) return "TRAILING_EDGE";
    return "QUARTER_CHORD";
}

function enumStr_tipCap(t is TipCap) returns string
{
    return t == TipCap.TAPERED ? "TAPERED" : (t == TipCap.ROUND_PLAN ? "ROUND_PLAN" : "FLAT");
}

/** Shared fields common to the wing and the stab, one "key=value" list, no trailing separator. */
function commonFoilLog(definition is map) returns string
{
    var s = "profile=" ~ enumStr_profile(definition.profile);
    if (definition.profile == FoilProfile.NACA4)
        s = s ~ "; camber=" ~ fmt(definition.camber, 2) ~ "; camberPos=" ~ fmt(definition.camberPos, 1);
    s = s ~ "; tipProfile=" ~ (definition.tipProfile == undefined ? "SAME" : enumStr_tipProfile(definition.tipProfile));
    if (definition.tipProfile != undefined && definition.tipProfile != TipProfile.SAME)
    {
        if (definition.tipProfile == TipProfile.NACA4)
            s = s ~ "; tipCamber=" ~ fmt(definition.tipCamber, 2) ~ "; tipCamberPos=" ~ fmt(definition.tipCamberPos, 1);
        s = s ~ "; blendFrom=" ~ fmt(definition.blendFrom, 1);
    }
    s = s ~ "; rootThickness=" ~ fmt(definition.rootThickness, 2)
        ~ "; tipThickness=" ~ fmt(definition.tipThickness, 2)
        ~ "; teThickness_mm=" ~ fmt(definition.teThickness / millimeter, 3)
        ~ "; pointsPerSurface=" ~ fmt(definition.pointsPerSurface, 0)
        ~ "; planformMode=" ~ (definition.planformMode == PlanformMode.AREA_AR ? "AREA_AR" : "SPAN_CHORD");
    if (definition.planformMode == PlanformMode.AREA_AR)
        s = s ~ "; targetArea_cm2=" ~ fmt(definition.targetArea, 1)
            ~ "; aspectRatio=" ~ fmt(definition.aspectRatio, 2)
            ~ "; areaDefinition=" ~ (definition.areaDefinition == AreaDefinition.PROJECTED ? "PROJECTED" : "DEVELOPED");
    else
        s = s ~ "; span_mm=" ~ fmt(definition.span / millimeter, 1)
            ~ "; rootChord_mm=" ~ fmt(definition.rootChord / millimeter, 1);
    s = s ~ "; chordShape=" ~ (definition.chordShape == ChordShape.SUPERELLIPSE ? "SUPERELLIPSE" : (definition.chordShape == ChordShape.DOUBLE ? "DOUBLE" : "LINEAR"));
    if (definition.chordShape == ChordShape.SUPERELLIPSE)
        s = s ~ "; superN=" ~ fmt(definition.superN, 2) ~ "; endRatio=" ~ fmt(definition.endRatio, 3);
    else if (definition.chordShape == ChordShape.DOUBLE)
        s = s ~ "; breakPct=" ~ fmt(definition.breakPct, 1) ~ "; midRatio=" ~ fmt(definition.midRatio, 3) ~ "; blendPct=" ~ fmt(definition.blendPct, 1) ~ "; tipRatio=" ~ fmt(definition.tipRatio, 3);
    else
        s = s ~ "; tipRatio=" ~ fmt(definition.tipRatio, 3);
    s = s ~ "; minTipOn=" ~ (definition.minTipOn == true ? "1" : "0") ~ (definition.minTipOn == true ? "; minTip_mm=" ~ fmt(definition.minTip / millimeter, 2) : "");
    s = s ~ "; stations=" ~ fmt(definition.stations, 0)
        ~ "; mirror=" ~ (definition.mirror ? "true" : "false")
        ~ "; planformAlign=" ~ fmt(definition.planformAlign, 1)
        ~ "; sweepTip_mm=" ~ fmt(definition.sweepTip / millimeter, 1)
        ~ "; sweepExp=" ~ fmt(definition.sweepExp, 2)
        ~ "; tipDrop_mm=" ~ fmt(definition.tipDrop / millimeter, 1)
        ~ "; bumps=" ~ (definition.bumpOn == true ? "1" : "0")
        ~ (definition.bumpOn == true ? "; bumpAmp_mm=" ~ fmt(definition.bumpAmp / millimeter, 1) ~ "; bumpPitch_mm=" ~ fmt(definition.bumpPitch / millimeter, 1) ~ "; bumpFrom=" ~ fmt(definition.bumpFrom, 1) ~ "; bumpTo=" ~ fmt(definition.bumpTo, 1) : "")
        ~ "; winglet=" ~ (definition.winglet == Winglet.UP ? "UP" : (definition.winglet == Winglet.DOWN ? "DOWN" : "OFF"))
        ~ (definition.winglet != Winglet.OFF ? "; wingletArea_cm2=" ~ fmt(definition.wingletArea, 1) ~ "; wingletAngle_deg=" ~ fmt(definition.wingletAngle / degree, 1) ~ "; wingletRadius_mm=" ~ fmt(definition.wingletRadius / millimeter, 1) : "")
        ~ "; dropLaw=" ~ (definition.dropLaw == DropLaw.SCURVE ? "SCURVE" : "POWER") ~ (definition.dropLaw == DropLaw.SCURVE ? "" : "; dropExp=" ~ fmt(definition.dropExp, 2))
        ~ "; dropFrom=" ~ fmt(definition.dropFrom == undefined ? 0 : definition.dropFrom, 1) ~ "; dropTo=" ~ fmt(definition.dropTo == undefined ? 100 : definition.dropTo, 1)
        ~ "; rootDihedral_deg=" ~ fmt(definition.rootDihedral / degree, 2)
        ~ "; washout_deg=" ~ fmt(definition.washout / degree, 2)
        ~ "; washoutExp=" ~ fmt(definition.washoutExp, 2)
        ~ "; thicknessExp=" ~ fmt(definition.thicknessExp, 2)
        ~ "; incidence_deg=" ~ fmt(definition.incidence / degree, 2)
        ~ "; pivot=" ~ enumStr_pivot(definition.pivot)
        ~ "; tipCap=" ~ enumStr_tipCap(definition.tipCap);
    if (definition.tipCap != TipCap.FLAT)
        s = s ~ "; capLength_mm=" ~ fmt(definition.capLength / millimeter, 2) ~ "; capEnd=" ~ fmt(definition.capEnd, 1);
    s = s ~ "; polarSource=" ~ enumStr_polarSource(definition.polarSource);
    if (definition.polarSource == PolarSource.POLAR)
        s = s ~ "; polarAlpha0_deg=" ~ fmt(definition.polarAlpha0 / degree, 2)
            ~ "; polarCla=" ~ fmt(definition.polarCla, 3) ~ "; polarCm0=" ~ fmt(definition.polarCm0, 4)
            ~ "; polarRe1_M=" ~ fmt(definition.polarRe1, 3) ~ "; polarClmax1=" ~ fmt(definition.polarClmax1, 3)
            ~ "; polarCdmin1=" ~ fmt(definition.polarCdmin1, 4) ~ "; polarClcd1=" ~ fmt(definition.polarClcd1, 3) ~ "; polarK1=" ~ fmt(definition.polarK1, 4)
            ~ "; polarRe2_M=" ~ fmt(definition.polarRe2, 3) ~ "; polarClmax2=" ~ fmt(definition.polarClmax2, 3)
            ~ "; polarCdmin2=" ~ fmt(definition.polarCdmin2, 4) ~ "; polarClcd2=" ~ fmt(definition.polarClcd2, 3) ~ "; polarK2=" ~ fmt(definition.polarK2, 4);
    return s;
}

function wingInputLog(definition is map) returns string
{
    var s = "WING_INPUTS: toolVersion=" ~ FOIL_WING_VERSION ~ "; " ~ commonFoilLog(definition)
        ~ "; socketOn=" ~ (definition.socketOn ? "true" : "false");
    if (definition.socketOn)
        s = s ~ "; joint=" ~ (definition.wingJoint == WingJoint.HUB ? "HUB" : (definition.wingJoint == WingJoint.FLAT ? "FLAT" : (definition.wingJoint == WingJoint.SQUARE ? "SQUARE" : "ROUND")));
    if (definition.socketOn && definition.wingJoint == WingJoint.FLAT)
        s = s ~ "; flatBolts=" ~ definition.flatBolts ~ "; flatBolt=" ~ boltDims(definition.flatBolt).name ~ (definition.flatBolt == BoltSize.CUSTOM ? "; flatBoltDia_mm=" ~ fmt(definition.flatBoltDia / millimeter, 2) : "")
            ~ "; flatBolt1From_mm=" ~ fmt(definition.flatBolt1From / millimeter, 1) ~ "; flatPitch_mm=" ~ fmt(definition.flatPitch / millimeter, 1) ~ "; flatCsk=" ~ (definition.flatCsk ? "1" : "0")
            ~ "; flatPadOn=" ~ (definition.flatPadOn == true ? "1" : "0")
            ~ (definition.flatPadOn == true ? "; flatPadWidth_mm=" ~ fmt(definition.flatPadWidth / millimeter, 1) ~ "; flatPadHeight_mm=" ~ fmt(definition.flatPadHeight / millimeter, 1)
                ~ "; flatPadStart_mm=" ~ fmt(definition.flatPadStart / millimeter, 1) ~ "; flatPadRamp=" ~ (definition.flatPadRamp != false ? "1" : "0") : "");
    if (definition.socketOn && definition.wingJoint == WingJoint.HUB)
    {
        const hd = hubEffective(definition);
        s = s ~ "; hubStd=" ~ (hd.hubStd == undefined || hd.hubStd == HubStandard.CUSTOM ? "CUSTOM" : "STANDARD") ~ "; hubWidth_mm=" ~ fmt(hd.hubWidth / millimeter, 1) ~ "; hubLength_mm=" ~ fmt(hd.hubLength / millimeter, 1) ~ "; hubFromApex_mm=" ~ fmt(hd.hubFromApex / millimeter, 1)
            ~ "; hubHeight_mm=" ~ fmt(hd.hubHeight / millimeter, 1) ~ "; hubFillet_mm=" ~ fmt(hd.hubFillet / millimeter, 1) ~ "; pocketWidth_mm=" ~ fmt(hd.pocketWidth / millimeter, 1) ~ "; pocketLength_mm=" ~ fmt(hd.pocketLength / millimeter, 1)
            ~ "; pocketFrom_mm=" ~ fmt(hd.pocketFrom / millimeter, 1) ~ "; pocketDepth_mm=" ~ fmt(hd.pocketDepth / millimeter, 1) ~ "; pocketClear_mm=" ~ fmt(hd.pocketClear / millimeter, 2)
            ~ "; hubBolts=" ~ hd.hubBolts ~ "; hubBolt=" ~ boltDims(hd.hubBolt).name ~ "; hubHoleDia_mm=" ~ fmt(hd.hubHoleDia / millimeter, 2) ~ "; hubBoltPitch_mm=" ~ fmt(hd.hubBoltPitch / millimeter, 1)
            ~ "; hubBolt1From_mm=" ~ fmt(hd.hubBolt1From / millimeter, 1) ~ "; hubHoleDepth_mm=" ~ fmt(hd.hubHoleDepth / millimeter, 1)
            ~ "; hubBoltSide=" ~ (hd.hubBoltSide != undefined && hd.hubBoltSide == HubBoltSide.UNDERSIDE ? "UNDERSIDE" : (hd.hubBoltSide != undefined && hd.hubBoltSide == HubBoltSide.NUTS ? "NUTS" : "FUSELAGE"))
            ~ (hd.hubBoltSide != undefined && hd.hubBoltSide == HubBoltSide.NUTS ? "; hubNutDia_mm=" ~ fmt(hd.hubNutDia / millimeter, 2) ~ "; hubNutLen_mm=" ~ fmt(hd.hubNutLen / millimeter, 1) ~ "; hubNutFlange_mm=" ~ fmt(hd.hubNutFlange / millimeter, 2) ~ "; hubNutFlangeT_mm=" ~ fmt(hd.hubNutFlangeT / millimeter, 2) ~ "; hubNutFit_mm=" ~ fmt(hd.hubNutFit / millimeter, 2) : "")
            ~ "; hubFloor=" ~ (hd.hubFloor == undefined || hd.hubFloor == HubFloor.FLAT ? "FLAT" : (hd.hubFloor == HubFloor.VGROOVE ? "VGROOVE" : "VRIDGE"))
            ~ (hd.hubFloor != undefined && hd.hubFloor != HubFloor.FLAT ? "; hubVDepth_mm=" ~ fmt(hd.hubVDepth / millimeter, 1) ~ "; hubVFillet_mm=" ~ fmt(hd.hubVFillet / millimeter, 1) : "")
            ~ "; hubNoseOn=" ~ (hd.hubNoseOn == true ? "1" : "0")
            ~ (hd.hubNoseOn == true ? "; hubNoseLen_mm=" ~ fmt(hd.hubNoseLen / millimeter, 1) ~ "; hubNoseHeight_mm=" ~ fmt(hd.hubNoseHeight / millimeter, 1) ~ "; hubNoseShape=" ~ fmt(hd.hubNoseShape, 2) ~ "; hubNoseFull=" ~ fmt(hd.hubNoseFull, 2) ~ "; hubNoseRound_mm=" ~ fmt(hd.hubNoseRound / millimeter, 1) : "")
            ~ "; rootFairing=" ~ (definition.rootFairing == true ? "true" : "false") ~ (definition.rootFairing == true ? "; fairingRadius_mm=" ~ fmt(definition.fairingRadius / millimeter, 1) ~ "; fairingSpread=" ~ fmt(definition.fairingSpread == undefined ? 1 : definition.fairingSpread, 2) ~ "; fairingTail_mm=" ~ fmt((definition.fairingTail == undefined ? 0 * meter : definition.fairingTail) / millimeter, 1) : "");
    }
    if (definition.socketOn && definition.wingJoint == WingJoint.SQUARE)
        s = s ~ "; boreWidth_mm=" ~ fmt(definition.boreWidth / millimeter, 1) ~ "; boreHeight_mm=" ~ fmt(definition.boreHeight / millimeter, 1) ~ "; boreCorner_mm=" ~ fmt(definition.boreCorner / millimeter, 1);
    if (definition.socketOn && definition.wingJoint != WingJoint.HUB && definition.wingJoint != WingJoint.FLAT)
        s = s ~ "; socketHeight_mm=" ~ fmt(definition.socketHeight / millimeter, 1) ~ "; tubeDia_mm=" ~ fmt(definition.tubeDia / millimeter, 2)
            ~ "; tubeClearance_mm=" ~ fmt(definition.tubeClearance / millimeter, 2)
            ~ "; socketWall_mm=" ~ fmt(definition.socketWall / millimeter, 2)
            ~ "; socketBlend_mm=" ~ fmt(definition.socketBlend / millimeter, 1)
            ~ "; socketRearExt_mm=" ~ fmt(definition.socketRearExt / millimeter, 1)
            ~ "; nacelleRearFair_mm=" ~ fmt(definition.nacelleRearFair / millimeter, 1)
            ~ "; rootFairing=" ~ (definition.rootFairing == true ? "true" : "false") ~ (definition.rootFairing == true ? "; fairingRadius_mm=" ~ fmt(definition.fairingRadius / millimeter, 1) ~ "; fairingSpread=" ~ fmt(definition.fairingSpread == undefined ? 1 : definition.fairingSpread, 2) ~ "; fairingTail_mm=" ~ fmt((definition.fairingTail == undefined ? 0 * meter : definition.fairingTail) / millimeter, 1) : "")
            ~ "; mouthWallPct=" ~ fmt(definition.mouthWallPct, 0)
            ~ "; socketDepth_mm=" ~ fmt(definition.socketDepth / millimeter, 1)
            ~ "; socketPins=" ~ fmt(definition.socketPins, 0)
            ~ "; socketPinBolt=" ~ boltDims(definition.socketPinBolt).name ~ "; socketPinDia_mm=" ~ fmt((definition.socketPinBolt == BoltSize.CUSTOM ? definition.socketPinDia : (boltDims(definition.socketPinBolt).clear + 0.1) * millimeter) / millimeter, 2)
            ~ "; socketPinPitch_mm=" ~ fmt(definition.socketPinPitch / millimeter, 1);
    return s;
}

/**
 * The stab pad's skins at x, in the mount's mirrored frame (z' = sgn z), build 234: [lowest pad-side
 * skin, highest far skin] over the root (surf and far, LE -> TE, clamped lookups) and every section
 * across the pad's width that reaches x (across: maps with pts, local outlines from moldCoreSectionAt).
 * A straight-across underside between the two lies inside each of them.
 */
function stabPadSkinAt(surf is array, far is array, across is array, sgn is number, x is ValueWithUnits) returns array
{
    var zs = profileZAtClamped(surf, x);
    var zf = profileZAtClamped(far, x);
    for (var s in across)
    {
        const r = moldSectionZAt(s.pts, x);
        if (r == undefined)
            continue;
        zs = min(zs, sgn == 1 ? r[1] : -r[0]);
        zf = max(zf, sgn == 1 ? r[0] : -r[1]);
    }
    return [zs, zf];
}

/**
 * Stab mount pad: a wedge under the stab root. Profile in the XZ plane (same sketch frame as the
 * foil sections: plane normal -Y, u = X, v = Z, origin at the stab pivot): top = the root's own
 * lower surface raised 0.5 mm into the stab (so the union overlaps rather than meeting on a
 * coincident face), bottom = a flat horizontal line Pad height below the lowest point of that
 * surface over the pad. Lofted between two copies at y = +/- Pad width / 2, unioned with the stab.
 * Returns { on, bottomRel (pad bottom Z relative to the stab pivot), note }.
 */
/**
 * Production-style mount on the stab root (the production layout): a flat pad face on the fuselage side, faired
 * from the leading edge, the full root chord long, optionally continued aft as a tapered tail
 * fairing; plus through bolt holes on the centreline. Built as the intersection of a side-view prism
 * (x-z profile lofted across the span) and a plan-view prism (x-y outline lofted through the height),
 * so a flat face, a curved ramp, a concave plan taper and a sloping tail all come from two sketches.
 * Mount side Bottom is the same geometry mirrored in z. Returns local (pivot-relative) measures.
 */
function buildStabMount(context is Context, id is Id, definition is map, m is map) returns map
{
    const off = { "on" : false, "side" : 1, "padRel" : 0 * meter, "endRel" : 0 * meter, "tailOn" : false, "boltX" : [], "contour" : [], "rampPct" : 0, "tailLen" : 0 * meter, "tailStartRel" : 0 * meter, "note" : "", "blockOn" : false, "farRel" : 0 * meter };
    const pts = m.rootPts;
    const n = (size(pts) + 1) / 2;
    var upper = [];
    var lower = [];
    var xMin = 1 * meter;
    var xMax = -1 * meter;
    for (var i = 0; i < size(pts); i += 1)
    {
        if (i < n)
            upper = append(upper, pts[i]);          // upper TE -> LE
        if (i >= n - 1)
            lower = append(lower, pts[i]);          // LE -> lower TE
        xMin = min(xMin, pts[i][0]);
        xMax = max(xMax, pts[i][0]);
    }
    // an inverted tabulated profile keeps its point order, so "upper" by index is the geometric
    // lower surface: swap them by the mid-chord Z so the pad, its ramp and the countersink land on
    // the right faces (build 143: an inverted Clark Y with the pad on top failed the side loft)
    const xMid = 0.5 * (xMin + xMax);
    if (profileZAt(upper, xMid) < profileZAt(lower, xMid))
    {
        const tmp = upper;
        upper = reverse(lower);   // stays TE -> LE
        lower = reverse(tmp);     // stays LE -> TE
    }
    var result = off;
    var sgn = definition.mountSide == PadSide.BOTTOM ? -1 : 1;   // +1: fuselage over the stab (mount on top), -1: under (build 199: pad or no pad)
    var padM = 0 * meter;      // pad plane in the mirrored frame (z' = sgn * z)
    var padX = [];             // x span of the pad body on the centreline, and of a block's fill there with
    var blockX = [];           // the height it reaches (mirrored frame): the countersink check counts both
    var blockFarM = 0 * meter; // (build 234, user)
    var xEnd = xMax;
    const arm = definition.arm;
    const hgt = definition.height;
    var sketches = [];
    result.side = sgn;
    if (definition.padOn)
    {
        // pad-facing surface in the mirrored frame, as points sorted LE -> TE
        var surf = [];
        if (sgn == 1)
        {
            for (var i = size(upper) - 1; i >= 0; i -= 1)
                surf = append(surf, upper[i]);
        }
        else
        {
            for (var pnt in lower)
                surf = append(surf, vector(pnt[0], -pnt[1]));
        }
        var far = [];              // far surface, same frame (for the overlap lift and the TE point)
        if (sgn == 1)
            far = lower;
        else
            for (var i = size(upper) - 1; i >= 0; i -= 1)
                far = append(far, vector(upper[i][0], -upper[i][1]));
        var zTopM = -1 * meter;
        for (var pnt in surf)
            zTopM = max(zTopM, pnt[1]);
        padM = zTopM + definition.padHeight;
        const chord = xMax - xMin;
        const hair = 0.05 * millimeter;
        const x0 = xMin + 1 * millimeter;                       // the ramp leaves the skin 1 mm behind the nose
        const rampOn = definition.padRamp != false;
        // the fixed interface: Flat start, Tail start and Tail end are mm from the pivot, so the seat
        // plane, its length and the fuselage tip are the same for every stab with the same Arm (build
        // 125). Held inside the section where it does not fit, with a warning in the note: 6 mm behind
        // the nose for the ramp's 5 mm, 2 mm for a square front (build 234: the 6 mm held the user's
        // square front at Flat start -8 back to -7 on a stab whose LE is at -13)
        var fitNote = "";
        var xRamp = definition.flatStart;
        const xFront = x0 + (rampOn ? 5 : 1) * millimeter;
        if (xRamp < xFront)
        {
            fitNote = fitNote ~ " | WARNING: Flat start " ~ fmt(definition.flatStart / millimeter, 0) ~ " mm is " ~
                (definition.flatStart < xMin ? "ahead of the leading edge" : "within " ~ fmt((xFront - xMin) / millimeter, 0) ~ " mm of the leading edge") ~
                " (LE at " ~ fmt(xMin / millimeter, 1) ~ " mm) - held at " ~ fmt(xFront / millimeter, 1) ~ " mm" ~ (rampOn ? " for the ramp" : "") ~ "; move Flat start aft to keep the interface fixed";
            xRamp = xFront;
        }
        if (xRamp > xMax - 5 * millimeter)
        {
            fitNote = fitNote ~ " | WARNING: Flat start " ~ fmt(definition.flatStart / millimeter, 0) ~ " mm is behind the trailing edge (" ~ fmt(xMax / millimeter, 0) ~ " mm) - held 5 mm ahead of it; move Flat start forward";
            xRamp = xMax - 5 * millimeter;
        }
        const tailOn = definition.tailOn == true;
        var xTailStart = xMax;
        if (tailOn)
        {
            xEnd = max(definition.tailEnd, xMax + 5 * millimeter);
            if (xEnd > definition.tailEnd + hair)
                fitNote = fitNote ~ " | WARNING: Tail end " ~ fmt(definition.tailEnd / millimeter, 0) ~ " mm is inside the root (TE at " ~ fmt(xMax / millimeter, 0) ~ " mm) - held 5 mm behind the TE; move Tail end aft";
            xTailStart = min(max(definition.tailStart, xMax), xEnd - 5 * millimeter);
            if (xTailStart > definition.tailStart + hair)
                fitNote = fitNote ~ " | WARNING: the trailing edge (" ~ fmt(xMax / millimeter, 0) ~ " mm) is behind Tail start " ~ fmt(definition.tailStart / millimeter, 0) ~ " mm - the taper starts at the TE; move Tail start aft to keep the fuselage tip fixed";
        }
        else
            xEnd = xMax;
        // clamped: a thick trailing edge turned by the incidence puts the pad side's TE point up to
        // TE x sin(incidence) ahead of xMax, past the hair (build 234)
        const zTE = profileZAtClamped(surf, xMax - hair);       // trailing-edge point (upper and lower meet)
        const hw = definition.padWidth / 2;

        // the sections across the pad's width (build 234): at every eighth of half the Pad width,
        // placed as buildFoil places its stations (root tail, alignment, sweep, drop:
        // moldCoreSectionAt), as local outlines. The underside and the ramp follow the lowest
        // pad-side skin of these and the root, so the pad overlaps every section it covers; the root
        // alone left it floating where the sections beside it are lower (near the nose, and at a root
        // tail's trailing edge, which curves forward across the pad)
        var across = [];
        {
            const miniA = sectionDefFromModel(m.model);
            for (var j = 1; j <= 8; j += 1)
            {
                const sec = moldCoreSectionAt(m.model, miniA, hw * j / 8);
                if (sec.ok != true || sec.winglet)
                    continue;
                var q = [];
                var te = -1 * meter;
                for (var p in sec.placed)
                {
                    q = append(q, vector(sec.xOff + p[0], sec.zOff + p[1]));
                    te = max(te, sec.xOff + p[0]);
                }
                across = append(across, { "y" : hw * j / 8, "pts" : q, "te" : te });
            }
        }

        // a pad-side skin that is already flat at the pad plane over the pad's length (a Clark Y's
        // flat side with Pad height 0) needs no pad body: the skin is the seat, and a ramp would only
        // fill the leading edge's round with a block (build 202, user)
        var padGap = 0 * meter;
        for (var k = 0; k <= 24; k += 1)
        {
            const x = xRamp + (xMax - hair - xRamp) * k / 24;
            padGap = max(padGap, padM - profileZAtClamped(surf, x));
        }
        const flatPad = padGap < 0.2 * millimeter;
        const xStart = rampOn ? x0 : xRamp;                       // where the pad body begins
        var bodyNote = "";

        // ---- side profile (x, z'), closed ----
        // ramp: a smoothstep from the skin just behind the nose up to the pad plane at Flat start; or,
        // with Front ramp off, a square front face there; or, with no pad body, just the contour
        var ramp = [];
        if (flatPad)
            ramp = [vector(x0, profileZAt(surf, x0)), vector(xRamp, padM)];
        else if (rampOn)
        {
            for (var k = 0; k <= 12; k += 1)
            {
                const t = k / 12;
                const x = x0 + (xRamp - x0) * t;
                const sm = t * t * (3 - 2 * t);
                const zs = stabPadSkinAt(surf, far, across, sgn, x)[0];   // from the lowest skin across the pad (build 234)
                ramp = append(ramp, vector(x, zs + (padM - zs) * sm));
            }
        }
        else
            ramp = [vector(xRamp, padM)];
        if (!flatPad)
        {
            // inside every section across the pad: the lowest pad-side skin less the lift, the lift
            // within 40 % of the thinnest, so it never leaves through the far skin. Spaced as sin from
            // the TE, so the points crowd toward the start, where a square front near the nose meets
            // the skin's tightest curve (even steps were 3 mm apart there; build 234)
            var bottom = [];                                          // inside the stab, TE -> start
            for (var k = 0; k <= 24; k += 1)
            {
                const x = k == 24 ? xStart : xMax - hair - (xMax - hair - xStart) * sin((PI / 2 * k / 24) * radian);
                const zz = stabPadSkinAt(surf, far, across, sgn, x);
                var lift = min(0.5 * millimeter, 0.4 * max(zz[0] - zz[1], 0 * meter));
                if (k == 24 && rampOn)
                    lift = max(lift, hair);                           // the nose line under the ramp's start is never zero-length
                bottom = append(bottom, vector(x, zz[0] - lift));
            }
            padX = [xStart, xMax];
            var side = [];
            const yS = [-(definition.padWidth / 2 + 2 * millimeter), definition.padWidth / 2 + 2 * millimeter];
            for (var i = 0; i < 2; i += 1)
            {
                const sid = id + ("mountSide" ~ i);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(arm, yS[i], hgt), -Y_DIRECTION, X_DIRECTION) });
                var rampW = [];
                for (var q in ramp)
                    rampW = append(rampW, vector(q[0], sgn * q[1]));
                var botW = [];
                for (var q in bottom)
                    botW = append(botW, vector(q[0], sgn * q[1]));
                if (rampOn)
                    skFitSpline(sk, "ramp", { "points" : rampW });
                const pFlatEnd = vector(xMax + hair, sgn * padM);
                skLineSegment(sk, "flat", { "start" : rampW[size(rampW) - 1], "end" : pFlatEnd });
                skLineSegment(sk, "end", { "start" : pFlatEnd, "end" : botW[0] });
                skFitSpline(sk, "inner", { "points" : botW });
                skLineSegment(sk, "nose", { "start" : botW[size(botW) - 1], "end" : rampW[0] });   // the square front face with the ramp off
                skSolve(sk);
                side = append(side, qSketchRegion(sid));
                sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
            }
            opLoft(context, id + "mountSideLoft", { "profileSubqueries" : side });

            // ---- plan outline (x, y), closed ----
            var zLoW = 1 * meter;
            var zHiW = -1 * meter;
            for (var q in ramp)
            {
                zLoW = min(zLoW, sgn * q[1]);
                zHiW = max(zHiW, sgn * q[1]);
            }
            for (var q in bottom)
            {
                zLoW = min(zLoW, sgn * q[1]);
                zHiW = max(zHiW, sgn * q[1]);
            }
            zLoW = min(zLoW, sgn * padM) - 2 * millimeter;
            zHiW = max(zHiW, sgn * padM) + 2 * millimeter;
            // aft edge: square across at the root TE, or, where a root tail curves the trailing edge
            // forward across the pad by more than 0.2 mm and no Tail fairing carries on behind it, the
            // trailing edge itself, so the pad's corners do not hang behind it (build 234, user)
            var aftEdge = [];                                         // +hw -> -hw, empty = square
            if (!tailOn && size(across) == 8)
            {
                var teMin = xMax;
                for (var s in across)
                    teMin = min(teMin, s.te);
                if (teMin < xMax - 0.2 * millimeter)
                {
                    const xLo = xStart + 1 * millimeter;              // never forward of the pad's front
                    for (var j = 7; j >= 0; j -= 1)
                        aftEdge = append(aftEdge, vector(min(max(across[j].te, xLo), xMax), across[j].y));
                    aftEdge = append(aftEdge, vector(xMax, 0 * meter));
                    for (var j = 0; j <= 7; j += 1)
                        aftEdge = append(aftEdge, vector(min(max(across[j].te, xLo), xMax), -across[j].y));
                }
            }
            var plan = [];
            const zP = [zLoW, zHiW];
            for (var i = 0; i < 2; i += 1)
            {
                const sid = id + ("mountPlan" ~ i);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(arm, 0 * meter, hgt + zP[i]), Z_DIRECTION, X_DIRECTION) });
                const a = vector(xStart - 0.5 * millimeter, hw);
                const b = size(aftEdge) > 0 ? aftEdge[0] : vector(xMax, hw);
                const c = size(aftEdge) > 0 ? aftEdge[size(aftEdge) - 1] : vector(xMax, -hw);
                const d = vector(xStart - 0.5 * millimeter, -hw);
                skLineSegment(sk, "front", { "start" : d, "end" : a });
                skLineSegment(sk, "sideP", { "start" : a, "end" : b });
                skLineSegment(sk, "sideN", { "start" : c, "end" : d });
                if (size(aftEdge) > 0)
                    skFitSpline(sk, "aft", { "points" : aftEdge });
                else
                    skLineSegment(sk, "aft", { "start" : b, "end" : c });
                skSolve(sk);
                plan = append(plan, qSketchRegion(sid));
                sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
            }
            opLoft(context, id + "mountPlanLoft", { "profileSubqueries" : plan });
            opBoolean(context, id + "mountShape", {
                        "tools" : qUnion([qCreatedBy(id + "mountSideLoft", EntityType.BODY), qCreatedBy(id + "mountPlanLoft", EntityType.BODY)]),
                        "operationType" : BooleanOperationType.INTERSECTION
                    });
            bodyNote = (rampOn ? "" : " (square front at Flat start, no ramp)") ~ (size(aftEdge) > 0 ? "; aft end on the trailing edge, which the root tail curves forward across the pad" : "");
        }
        else
            bodyNote = " (no pad body: the section's own flat is the seat, within " ~ fmt(padGap / millimeter, 2) ~ " mm of the pad plane)";
        // ---- block to the fuselage's centreline (build 198, moved here from the fuselage) ----
        // pad width, from the pad face out to the fuselage's centreline plane, less the fuselage's
        // round, so the stab carries its own mount: cheeks beside a tube narrower than the pad, a
        // full-width fill where the pad face is set beyond the tube's radius, nothing at all where
        // the tube's flat at the pad face is already as wide as the pad
        var blockMade = false;
        var farRel = padM;                                        // outermost solid on the centreline (mirrored frame)
        var blockNote = "";
        if (definition.stabBlock == true)
        {
            const blockH = -sgn * definition.height;                // pad face to the centreline
            const R = definition.fusDia / 2;
            const seatW = blockH < R ? 2 * sqrt(R * R - blockH * blockH) : 0 * meter;
            const xB0 = xRamp;
            const xB1 = tailOn ? max(xTailStart, xMax) : xMax;
            if (blockH < 0.2 * millimeter)
                blockNote = "; no block to the body (the pad face is at or beyond the centreline)";
            else if (seatW > 2 * hw - 3 * millimeter)
                blockNote = "; no block to the body needed (the fuselage's flat at the pad face is " ~ fmt(seatW / millimeter, 0) ~ " mm wide)";
            else if (xB1 - xB0 < 3 * millimeter)
                blockNote = "; no block to the body (no flat pad length for it)";
            else
            {
                const zF = hgt + sgn * (padM - hair);
                const zC = hgt + sgn * (padM + blockH);
                moldBox(context, id + "stabBlock", vector(arm + xB0, -hw, min(zF, zC)), vector(arm + xB1, hw, max(zF, zC)));
                const tid = xCylinder(context, id + "stabBlockTube", arm + xB0 - 5 * millimeter, arm + xB1 + 5 * millimeter, 0 * meter, zC, R + 0.1 * millimeter);
                sketches = append(sketches, qCreatedBy(id + "stabBlockTube" + "s0", EntityType.BODY));
                sketches = append(sketches, qCreatedBy(id + "stabBlockTube" + "s1", EntityType.BODY));
                opBoolean(context, id + "stabBlockCut", {
                            "targets" : qCreatedBy(id + "stabBlock", EntityType.BODY),
                            "tools" : qCreatedBy(tid, EntityType.BODY),
                            "operationType" : BooleanOperationType.SUBTRACTION
                        });
                blockMade = size(evaluateQuery(context, qUnion([qCreatedBy(id + "stabBlock", EntityType.BODY), qCreatedBy(id + "stabBlockCut", EntityType.BODY)]))) > 0;
                if (blockH > R)
                {
                    farRel = padM + (blockH - R);
                    if (blockMade)
                    {
                        blockX = [xB0, xB1];          // a fill on the bolt line, out to farRel (build 234)
                        blockFarM = farRel;
                    }
                }
                blockNote = blockMade ? "; block to the body " ~ fmt(blockH / millimeter, 1) ~ " mm out to the centreline, " ~ fmt(2 * hw / millimeter, 0) ~ " x " ~ fmt((xB1 - xB0) / millimeter, 0) ~ " mm round a " ~ fmt(definition.fusDia / millimeter, 0) ~ " mm fuselage" ~
                    (blockH > R ? " (fills " ~ fmt((blockH - R) / millimeter, 1) ~ " mm under it)" : " (cheeks beside it)") : "; the block to the body lies inside the fuselage's round (nothing added)";
            }
        }
        // ---- tail fairing: a loft of sections along x, flat at the pad plane, a superellipse below
        // whose exponent runs from 12 (a near-rectangle matching the pad body at the trailing edge)
        // to 2 (a half-ellipse at the end), so the edges round off progressively like a fuselage tail.
        // Plan half-width tapers concavely, the far face linearly to End thick. Pairwise ruled lofts,
        // unioned, as the mold does (a single multi-profile loft folded there)
        if (tailOn)
        {
            const nT = 8;
            const hwE = definition.tailEndWidth / 2;
            const dTE = padM - (zTE - 0.5 * millimeter);              // depth at the trailing edge, down to just inside the skin
            var tailRegions = [];
            // stations: just inside the TE, at Tail start if that is aft of the TE (full width between),
            // then nT over the taper to Tail end
            var xsT = [xMax - 1 * millimeter];
            if (xTailStart > xMax + 1 * millimeter)
                xsT = append(xsT, xTailStart);
            for (var k = 1; k <= nT; k += 1)
                xsT = append(xsT, xTailStart + (xEnd - xTailStart) * k / nT);
            for (var k = 0; k < size(xsT); k += 1)
            {
                const x = xsT[k];
                const t = min(max((x - xTailStart) / (xEnd - xTailStart), 0), 1);
                const h = hwE + (hw - hwE) * (1 - t) ^ 1.6;
                const d = dTE + (definition.tailEndThick - dTE) * t;
                const pw = 12 - 10 * t;
                var loop = [];
                for (var q = 0; q <= 24; q += 1)
                {
                    const th = PI + PI * q / 24;
                    const cth = cos(th * radian);
                    const sth = sin(th * radian);
                    const yy = h * (cth < 0 ? -1 : 1) * abs(cth) ^ (2 / pw);
                    const zz = padM - d * abs(sth) ^ (2 / pw);
                    loop = append(loop, vector(yy, sgn * zz));
                }
                const sid = id + ("tailSec" ~ k);
                var sk = newSketchOnPlane(context, sid, { "sketchPlane" : plane(vector(arm + x, 0 * meter, hgt), X_DIRECTION, Y_DIRECTION) });
                skFitSpline(sk, "u", { "points" : loop });
                skLineSegment(sk, "top", { "start" : loop[size(loop) - 1], "end" : loop[0] });
                skSolve(sk);
                tailRegions = append(tailRegions, qSketchRegion(sid));
                sketches = append(sketches, qCreatedBy(sid, EntityType.BODY));
            }
            // one smooth loft through every section (the sections are similar and monotonic, unlike
            // the mold curtain's); pairwise ruled lofts, which read as terraces, only as a fallback
            var smooth = true;
            try silent
            {
                opLoft(context, id + "tailLoft", { "profileSubqueries" : tailRegions });
            }
            catch
            {
                smooth = false;
            }
            if (!smooth)
            {
                var tailBodies = [];
                for (var k = 0; k < size(tailRegions) - 1; k += 1)
                {
                    const lid = id + ("tailLoftR" ~ k);
                    opLoft(context, lid, { "profileSubqueries" : [tailRegions[k], tailRegions[k + 1]] });
                    tailBodies = append(tailBodies, qCreatedBy(lid, EntityType.BODY));
                }
                opBoolean(context, id + "tailJoin", { "tools" : qUnion(tailBodies), "operationType" : BooleanOperationType.UNION });
            }
        }
        opBoolean(context, id + "mountJoin", {
                    "tools" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                    "operationType" : BooleanOperationType.UNION
                });
        // the mount contour the fuselage seats on: ramp from the nose, then the flat pad plane to the end
        var contour = [];
        for (var q in ramp)
            contour = append(contour, [(arm + q[0]) / meter, (hgt + sgn * q[1]) / meter]);
        contour = append(contour, [(arm + xEnd) / meter, (hgt + sgn * padM) / meter]);
        result = { "on" : true, "side" : sgn, "padRel" : sgn * padM, "endRel" : xEnd, "tailOn" : tailOn, "boltX" : [], "contour" : contour,
                   "rampPct" : (xRamp - xMin) / chord * 100, "tailLen" : xEnd - xMax, "tailStartRel" : xTailStart,
                   "note" : " | mount pad " ~ (sgn == 1 ? "on top" : "underneath") ~ ", face " ~ fmt(definition.padHeight / millimeter, 1) ~ " mm off the skin at Z " ~
                       fmt(sgn * padM / millimeter, 1) ~ " mm from the pivot, " ~ fmt(definition.padWidth / millimeter, 0) ~ " mm wide; fixed interface from the pivot: flat from " ~ fmt(xRamp / millimeter, 0) ~ " mm (" ~ (rampOn && !flatPad ? "ramp from " : "") ~ "the LE at " ~ fmt(xMin / millimeter, 0) ~ ")" ~
                       (tailOn ? ", full width to " ~ fmt(xTailStart / millimeter, 0) ~ ", tail to " ~ fmt(xEnd / millimeter, 0) ~ " mm ending " ~ fmt(definition.tailEndWidth / millimeter, 0) ~ " x " ~ fmt(definition.tailEndThick / millimeter, 0) ~ " mm" : " to the TE at " ~ fmt(xMax / millimeter, 0) ~ " mm (no tail: the interface follows the chord)") ~ bodyNote ~ fitNote ~ blockNote };
        result.blockOn = blockMade;
        result.farRel = sgn * farRel;
    }

    // ---- bolt holes, through everything on the centreline ----
    if (definition.stabBolts > 0)
    {
        var bolts = [];
        var tools = [];
        var skipped = "";
        var nCsk = 0;
        var cskWarn = "";
        const rb = stabBoltClear(definition) / 2;
        const cskOut = sgn == -1 ? 1 : -1;                            // countersink face: +1 top, -1 underside (away from the fuselage, Mount side)
        for (var k = 0; k < definition.stabBolts; k += 1)
        {
            const bx = definition.bolt1At + k * definition.boltPitch;
            if (bx + rb > xEnd - 0.5 * millimeter || bx - rb < xMin + 0.5 * millimeter)
            {
                skipped = skipped ~ " bolt " ~ (k + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ " mm from the pivot is off the root" ~ (definition.padOn && definition.tailOn == true ? "/tail" : "") ~ " - change Bolt 1 at or Bolt pitch;";
                continue;
            }
            const base = id + ("stabBolt" ~ k);
            tools = append(tools, qCreatedBy(circleLoft(context, base, arm + bx, 0 * meter, hgt - 60 * millimeter, rb, hgt + 60 * millimeter, rb), EntityType.BODY));
            sketches = append(sketches, qCreatedBy(base + "a", EntityType.BODY));
            sketches = append(sketches, qCreatedBy(base + "b", EntityType.BODY));
            bolts = append(bolts, bx);
            // countersink on the far face (away from the pad; the underside with no pad): a 90 deg cone
            // from just outside the skin, head diameter wide, narrowing to the hole over its depth
            if (definition.boltCsk && bx > xMin + 0.5 * millimeter && bx < xMax - 0.5 * millimeter)
            {
                const dOut = cskOut;                                  // outward, away from the pad
                const farPts = cskOut == 1 ? upper : lower;
                const zFar = hgt + profileZAt(farPts, bx);
                const rHead = boltHead(definition.boltSize, 2 * rb) / 2;
                const cskD = rHead - rb;
                var tLoc = abs(profileZAt(upper, bx) - profileZAt(lower, bx));
                // the pad, and a block's fill on the bolt line, are material under the head too, from the
                // countersunk skin to the face the fuselage seats on (build 234, user: count the pad as
                // the wing's flat mount does)
                var tWith = "";
                const inPad = size(padX) == 2 && bx >= padX[0] && bx <= padX[1];
                const inBlock = size(blockX) == 2 && bx >= blockX[0] && bx <= blockX[1];
                if (inPad || inBlock)
                {
                    const zCsk = sgn == 1 ? profileZAt(lower, bx) : -profileZAt(upper, bx);   // countersunk skin, mirrored frame
                    const tMount = (inBlock ? blockFarM : padM) - zCsk;
                    if (tMount > tLoc)
                    {
                        tLoc = tMount;
                        tWith = inBlock ? (inPad ? ", pad and block included" : ", block included") : ", pad included";
                    }
                }
                if (cskD > tLoc - 1 * millimeter)
                    cskWarn = cskWarn ~ (cskWarn == "" ? "" : "; ") ~ "bolt " ~ (k + 1) ~ " at X " ~ fmt(bx / millimeter, 0) ~ ": the " ~ boltDims(definition.boltSize).name ~ " countersink is " ~ fmt(cskD / millimeter, 1) ~
                        " mm deep in a " ~ fmt(tLoc / millimeter, 1) ~ " mm section" ~ tWith ~ " (" ~ fmt(max(tLoc - cskD, 0 * meter) / millimeter, 1) ~ " mm of laminate under the head) - move it forward with Bolt 1 at or Bolt pitch, choose a smaller Bolt, or turn Countersink off";
                const cb = id + ("stabCsk" ~ k);
                tools = append(tools, qCreatedBy(circleLoft(context, cb, arm + bx, 0 * meter, zFar + dOut * 2 * millimeter, rHead + 2 * millimeter, zFar - dOut * cskD, rb), EntityType.BODY));
                sketches = append(sketches, qCreatedBy(cb + "a", EntityType.BODY));
                sketches = append(sketches, qCreatedBy(cb + "b", EntityType.BODY));
                nCsk += 1;
            }
        }
        if (size(tools) > 0)
        {
            const toolQ = qUnion(tools);
            opBoolean(context, id + "stabBoltCut", {
                        "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), toolQ),
                        "tools" : toolQ,
                        "operationType" : BooleanOperationType.SUBTRACTION
                    });
        }
        result.boltX = bolts;
        result.cskSide = nCsk > 0 ? cskOut : 0;
        result.cskWarn = cskWarn;
        result.note = result.note ~ " | " ~ size(bolts) ~ " " ~ boltDims(definition.boltSize).name ~ " bolt holes " ~ fmt(stabBoltClear(definition) / millimeter, 1) ~ " mm at " ~ fmt(definition.bolt1At / millimeter, 0) ~
            " mm from the pivot" ~ (size(bolts) > 1 ? ", pitch " ~ fmt(definition.boltPitch / millimeter, 0) ~ " mm" : "") ~
            (nCsk > 0 ? ", " ~ nCsk ~ " countersunk " ~ fmt(boltHead(definition.boltSize, stabBoltClear(definition)) / millimeter, 1) ~ " mm on the " ~ (sgn == -1 ? "top" : "underside") : "") ~ (skipped != "" ? " |" ~ skipped : "");
    }
    if (size(sketches) > 0)
        opDeleteBodies(context, id + "deleteMountSketches", { "entities" : qUnion(sketches) });
    return result;
}

function stabInputLog(definition is map, pivotZ is ValueWithUnits) returns string
{
    var s = "STAB_INPUTS: toolVersion=" ~ FOIL_STAB_VERSION ~ "; " ~ commonFoilLog(definition)
        ~ "; arm_mm=" ~ fmt(definition.arm / millimeter, 1)
        ~ "; rootTailOn=" ~ (definition.rootTailOn == true ? "1" : "0")
        ~ (definition.rootTailOn == true ? "; rootTailLen_mm=" ~ fmt(definition.rootTailLen / millimeter, 1) ~ "; rootTailSpan=" ~ fmt(definition.rootTailSpan, 1) : "")
        ~ "; height_mm=" ~ fmt(definition.height / millimeter, 1) ~ "; pivotZ_mm=" ~ fmt(pivotZ / millimeter, 1)
        ~ "; stabLink=" ~ (definition.stabLink == StabLink.LINKED ? "LINKED" : "INDEPENDENT");
    if (definition.stabLink == StabLink.LINKED)
        s = s ~ "; linkAreaRatio=" ~ fmt(definition.linkAreaRatio, 3)
            ~ "; linkAROffset=" ~ fmt(definition.linkAROffset, 2)
            ~ "; linkThicknessOffset=" ~ fmt(definition.linkThicknessOffset, 2)
            ~ "; linkDecalage_deg=" ~ fmt(definition.linkDecalage / degree, 2)
            ;
    if (definition.profile != FoilProfile.NACA4)
        s = s ~ "; invertSection=" ~ (definition.invertSection ? "1" : "0");
    s = s ~ "; mountSide=" ~ (definition.mountSide == PadSide.BOTTOM ? "BOTTOM" : "TOP") ~ "; padOn=" ~ (definition.padOn ? "true" : "false");
    if (definition.padOn)
    {
        s = s ~ "; padWidth_mm=" ~ fmt(definition.padWidth / millimeter, 1)
            ~ "; padHeight_mm=" ~ fmt(definition.padHeight / millimeter, 1) ~ "; padRamp=" ~ (definition.padRamp != false ? "1" : "0") ~ "; stabBlock=" ~ (definition.stabBlock == true ? "1" : "0") ~ (definition.stabBlock == true ? "; fusDia_mm=" ~ fmt(definition.fusDia / millimeter, 1) : "")
            ~ "; flatStart_mm=" ~ fmt(definition.flatStart / millimeter, 1)
            ~ "; tailOn=" ~ (definition.tailOn ? "true" : "false");
        if (definition.tailOn)
            s = s ~ "; tailStart_mm=" ~ fmt(definition.tailStart / millimeter, 1) ~ "; tailEnd_mm=" ~ fmt(definition.tailEnd / millimeter, 1)
                ~ "; tailEndWidth_mm=" ~ fmt(definition.tailEndWidth / millimeter, 1)
                ~ "; tailEndThick_mm=" ~ fmt(definition.tailEndThick / millimeter, 1);
    }
    s = s ~ "; stabBolts=" ~ fmt(definition.stabBolts, 0);
    if (definition.stabBolts > 0)
        s = s ~ "; bolt1At_mm=" ~ fmt(definition.bolt1At / millimeter, 1)
            ~ "; boltPitch_mm=" ~ fmt(definition.boltPitch / millimeter, 1)
            ~ "; bolt=" ~ boltDims(definition.boltSize).name ~ "; boltDia_mm=" ~ fmt(stabBoltClear(definition) / millimeter, 2) ~ "; boltCsk=" ~ (definition.boltCsk ? "true" : "false");
    return s;
}

/** The stab's clearance hole: from the Bolt dropdown, or the typed Bolt dia when Custom. */
function stabBoltClear(definition is map) returns ValueWithUnits
{
    return definition.boltSize == BoltSize.CUSTOM ? definition.boltDia : boltDims(definition.boltSize).clear * millimeter;
}

function perfInputLog(definition is map) returns string
{
    return "PERFORMANCE_INPUTS: toolVersion=" ~ FOIL_PERF_VERSION ~ "; mass_kg=" ~ fmt(definition.mass, 1)
        ~ "; extMoment_Nm=" ~ fmt(definition.extMoment, 1)
        ~ "; density=" ~ fmt(definition.density, 1)
        ~ "; waterTemp_C=" ~ fmt(definition.waterTemp, 1)
        ~ "; depth_mm=" ~ fmt(definition.depth / millimeter, 1)
        ~ "; vTakeoff_kmh=" ~ fmt(definition.vTakeoff, 1)
        ~ "; vCruise_kmh=" ~ fmt(definition.vCruise, 1)
        ~ "; vMax_kmh=" ~ fmt(definition.vMax, 1)
        ~ "; tubercleCredits=" ~ (definition.tubercleCredits != false ? "1" : "0")
        ~ "; vStep_kmh=" ~ fmt(definition.vStep, 2)
        ~ "; clMax=" ~ fmt(definition.clMax, 2)
        ~ "; laminar_pct=" ~ fmt(definition.laminar, 1)
        ~ "; otherDrag_cm2=" ~ fmt(definition.otherDrag, 1)
        ~ "; loadFactor_g=" ~ fmt(definition.loadFactor, 1)
        ~ "; capStress_MPa=" ~ fmt(definition.capStress, 0)
        ~ "; capWidth_pct=" ~ fmt(definition.capWidth, 1)
        ~ "; propOn=" ~ (definition.propOn ? "1" : "0")
        ~ (definition.propOn
            ? "; propDia_mm=" ~ fmt(definition.propDia / millimeter, 1)
            ~ "; propPD=" ~ fmt(definition.propPD, 3)
            ~ "; propEAR=" ~ fmt(definition.propEAR, 3)
            ~ "; propBlades=" ~ definition.propBlades
            ~ "; propHub_mm=" ~ fmt(definition.propHub / millimeter, 1)
            ~ "; motorKv=" ~ fmt(definition.motorKv, 1)
            ~ "; torqueConst=" ~ fmt(definition.torqueConst, 2)
            ~ "; cells=" ~ definition.cells
            ~ "; cellVolts=" ~ fmt(definition.cellVolts, 2)
            ~ "; gearRatio=" ~ fmt(definition.gearRatio, 2)
            ~ "; currentLimit_A=" ~ fmt(definition.currentLimit, 1)
            ~ "; windingR_mOhm=" ~ fmt(definition.windingR, 1)
            ~ "; gearEff_pct=" ~ fmt(definition.gearEff, 1)
            ~ "; escEff_pct=" ~ fmt(definition.escEff, 1)
            ~ "; packAh=" ~ fmt(definition.packAh, 1)
            ~ "; usable_pct=" ~ fmt(definition.usable, 1)
            : "");
}


function fmt(x is number, d is number) returns string
{
    const k = 10 ^ d;
    return toString(round(x * k) / k);
}

/** Kinematic viscosity of water, m^2/s (Poiseuille fit), +5 % for seawater. */
function waterViscosity(T is number, rho is number) returns number
{
    const nu = 1.792e-6 / (1 + 0.0337 * T + 0.000221 * T * T);
    return rho > 1010 ? nu * 1.05 : nu;
}

function chordAt(m is map, eta is number) returns number
{
    return m.c0 * chordFactor(m, eta);
}

/** Gaussian elimination with partial pivoting. */
function solveLinear(A is array, b is array) returns array
{
    const n = size(b);
    var M = A;
    var v = b;
    for (var k = 0; k < n; k += 1)
    {
        var p = k;
        for (var i = k + 1; i < n; i += 1)
            if (abs(M[i][k]) > abs(M[p][k]))
                p = i;
        if (p != k)
        {
            const tr = M[k];
            M[k] = M[p];
            M[p] = tr;
            const tv = v[k];
            v[k] = v[p];
            v[p] = tv;
        }
        for (var i = k + 1; i < n; i += 1)
        {
            const f = M[i][k] / M[k][k];
            var row = M[i];
            for (var j = k; j < n; j += 1)
                row[j] = row[j] - f * M[k][j];
            M[i] = row;
            v[i] = v[i] - f * v[k];
        }
    }
    var x = makeArray(n, 0);
    for (var i = n - 1; i >= 0; i -= 1)
    {
        var s = v[i];
        for (var j = i + 1; j < n; j += 1)
            s -= M[i][j] * x[j];
        x[i] = s / M[i][i];
    }
    return x;
}

/**
 * Prandtl lifting line (Glauert, symmetric odd terms). y = (b/2) cos(theta).
 * Solved twice: per radian of body angle (Aa) and for twist + zero-lift angle (A0),
 * so A(alpha) = A0 + alpha Aa. Sweep and anhedral are not modelled here; their roll effect is
 * rollResponse's (build 230).
 */
function liftingLine(m is map, a0 is number, M is number) returns map
{
    // a winglet is credited as effective span for induced drag: projected span plus 0.9 x its
    // height across the pair (the usual first estimate); the chord law still runs over eta
    const b = m.wingletOn == 1 ? m.spanProj + 0.9 * m.wingletHeight : m.span;
    const AR = b * b / m.area;
    var rows = [];
    var ra = [];
    var r0 = [];
    var thetas = [];
    for (var j = 1; j <= M; j += 1)
    {
        const th = j * PI / (2 * M);
        const st = sin(th * radian);
        const eta = cos(th * radian);
        const mu = a0 * chordAt(m, eta) / (4 * b);
        var row = [];
        for (var k = 1; k <= M; k += 1)
        {
            const nn = 2 * k - 1;
            row = append(row, sin(nn * th * radian) * (mu * nn + st));
        }
        rows = append(rows, row);
        const twist = m.incidence - m.washout * eta ^ m.washoutExp;
        ra = append(ra, mu * st);
        r0 = append(r0, mu * st * (twist - alpha0At(m, eta)));
        thetas = append(thetas, th);
    }
    const Aa = solveLinear(rows, ra);
    const A0 = solveLinear(rows, r0);
    return { "Aa" : Aa, "A0" : A0, "AR" : AR, "M" : M, "b" : b, "thetas" : thetas,
            "CL0" : PI * AR * A0[0], "CLa" : PI * AR * Aa[0] };
}

function lltInducedDrag(L is map, alpha is number) returns number
{
    var s = 0;
    for (var k = 0; k < L.M; k += 1)
        s += (2 * k + 1) * (L.A0[k] + alpha * L.Aa[k]) ^ 2;
    return PI * L.AR * s;
}

function spanEfficiency(L is map) returns number
{
    var s = 0;
    for (var k = 0; k < L.M; k += 1)
        s += (2 * k + 1) * L.Aa[k] ^ 2;
    return L.Aa[0] ^ 2 / s;
}

/** Local section cl at theta for body angle alpha. */
function lltLocalCl(m is map, L is map, alpha is number, th is number) returns number
{
    var s = 0;
    for (var k = 0; k < L.M; k += 1)
        s += (L.A0[k] + alpha * L.Aa[k]) * sin((2 * k + 1) * th * radian);
    return 4 * L.b * s / chordAt(m, cos(th * radian));
}

/** Highest local cl inboard of 95 % span. */
/** Zero-lift angle at eta: the root's, blending into the tip section's from Blend from % (build 166). */
function alpha0At(m is map, eta is number) returns number
{
    if (m.tipOn != 1 || m.alpha0Tip == undefined)
        return m.alpha0;
    const b = m.blendFrom;
    if (eta <= b)
        return m.alpha0;
    const u = min((eta - b) / max(1 - b, 1e-6), 1);
    return m.alpha0 + (m.alpha0Tip - m.alpha0) * u * u * (3 - 2 * u);
}

/** Section CL max at eta, blending root and tip values the same way. */
function clMaxAt(m is map, eta is number, clRoot is number, clTip is number) returns number
{
    if (m.tipOn != 1)
        return clRoot;
    const b = m.blendFrom;
    if (eta <= b)
        return clRoot;
    const u = min((eta - b) / max(1 - b, 1e-6), 1);
    return clRoot + (clTip - clRoot) * u * u * (3 - 2 * u);
}

/** Highest local cl / section CL max across the span (tip 5 % excluded), as a fraction. */
function maxLocalClRatio(m is map, L is map, alpha is number, clRoot is number, clTip is number) returns number
{
    var best = -1e9;
    for (var th in L.thetas)
    {
        const eta = cos(th * radian);
        if (eta <= 0.95)
            best = max(best, lltLocalCl(m, L, alpha, th) / clMaxAt(m, eta, clRoot, clTip));
    }
    return best;
}

/** Body angle at which the first section (inboard of 95 % span) reaches clMax. */
function stallAlpha(m is map, L is map, clRoot is number, clTip is number) returns number
{
    var best = 1e9;
    for (var th in L.thetas)
    {
        const eta = cos(th * radian);
        if (eta > 0.95)
            continue;
        const c0 = lltLocalCl(m, L, 0, th);
        const ca = lltLocalCl(m, L, 1, th) - c0;
        if (ca > 0)
            best = min(best, (clMaxAt(m, eta, clRoot, clTip) - c0) / ca);
    }
    return best;
}

/**
 * Stall angle with leading-edge tubercles (build 232): the first station inboard of 95 % span to reach f x its CL
 * max, where inside the tubercle range the local cl is raised by the chord's share of half the tubercle height, which
 * is the troughs' cl (the twin at 120 modes: a 2.6 % chord ripple gives a 2.5 % cl ripple - the loading cannot follow
 * a ripple shorter than a chord, so the cl does the opposite of the chord). ripple false = the smooth wing at f x CL max.
 */
function tubercleStallAlpha(m is map, L is map, clRoot is number, clTip is number, f is number, ripple is boolean) returns number
{
    var best = 1e9;
    for (var th in L.thetas)
    {
        const eta = cos(th * radian);
        if (eta > 0.95)
            continue;
        const rp = ripple && eta >= m.bumpFrom && eta <= m.bumpTo ? 0.5 * m.bumpAmp / chordAt(m, eta) : 0;
        const c0 = lltLocalCl(m, L, 0, th) * (1 + rp);
        const ca = lltLocalCl(m, L, 1, th) * (1 + rp) - c0;
        if (ca > 0)
            best = min(best, (f * clMaxAt(m, eta, clRoot, clTip) - c0) / ca);
    }
    return best;
}

/** Speed, m/s, at which the foil's lift coefficient at body angle a (wing plus stab, the trim's linear model) carries the weight; -1 if it cannot. */
function speedAtAlpha(ctx is map, a is number) returns number
{
    if (a >= 1e8)
        return -1;
    const Sw = ctx.wing.area;
    const Ss = ctx.hasStab ? ctx.stab.area : 0;
    const cl = Sw * (ctx.Lw.CL0 + ctx.Lw.CLa * a) + Ss * (ctx.C1 + ctx.C2 * a);
    return cl > 0 ? sqrt(2 * ctx.W / (ctx.rho * cl)) : -1;
}

/** A speed in m/s as km/h text, "n/a" when it has no value. */
function kmh(v is number) returns string
{
    return v > 0 ? fmt(v * 3.6, 1) : "n/a";
}

/** Spanwise lift centroid as a fraction of the half span. */
/**
 * Bending moment along the half span, N m, at 21 stations (eta = j / 20 from the root), for a half-wing
 * lift halfLift distributed like the lifting line's circulation at alpha: M(y0) = integral over y > y0
 * of L'(y) (y - y0) dy. Cantilever from the root.
 */
function lltMoments(L is map, alpha is number, span is number, halfLift is number) returns array
{
    const N = 100;
    const h = span / 2;
    var lp = makeArray(N + 1);
    var tot = 0;
    // a stab flies with download: its circulation is negative along the whole span, and clipping
    // it at zero gave it no load at all (build 162: stab "deflection 0 mm, 0 MPa"). Use the
    // distribution's own sign, so the moments are the magnitude of the load whichever way it acts
    var raw = makeArray(N + 1);
    var sum = 0;
    for (var i = 0; i <= N; i += 1)
    {
        const th = acos(i / N);                       // y = h cos(theta)
        var gam = 0;
        for (var k = 0; k < L.M; k += 1)
            gam += (L.A0[k] + alpha * L.Aa[k]) * sin((2 * k + 1) * th);
        raw[i] = gam;
        sum += gam;
    }
    const sgn = sum < 0 ? -1 : 1;
    for (var i = 0; i <= N; i += 1)
    {
        lp[i] = max(sgn * raw[i], 0);
        tot += (i == 0 || i == N ? 0.5 : 1) * lp[i];
    }
    const dy = h / N;
    const scale = tot > 0 ? halfLift / (tot * dy) : 0;   // N/m per unit gam
    var out = [];
    for (var j = 0; j <= 20; j += 1)
    {
        const y0 = h * j / 20;
        var M = 0;
        for (var i = 0; i <= N; i += 1)
        {
            const y = h * i / N;
            if (y > y0)
                M += (i == N ? 0.5 : 1) * lp[i] * scale * (y - y0) * dy;
        }
        out = append(out, M);
    }
    return out;
}

function lltCentroid(L is map, alpha is number) returns number
{
    const N = 200;
    var num = 0;
    var den = 0;
    for (var i = 0; i <= N; i += 1)
    {
        const th = PI / 2 * i / N;
        const w = (i == 0 || i == N) ? 1 : ((i % 2 == 1) ? 4 : 2);
        var gam = 0;
        for (var k = 0; k < L.M; k += 1)
            gam += (L.A0[k] + alpha * L.Aa[k]) * sin((2 * k + 1) * th * radian);
        const st = sin(th * radian); // dy = (b/2) sin(theta) dtheta
        num += w * gam * cos(th * radian) * st;
        den += w * gam * st;
    }
    return den != 0 ? num / den : 0;
}

function simpsonEta(m is map, kind is number) returns number
{
    const N = 200;
    var s = 0;
    for (var i = 0; i <= N; i += 1)
    {
        const eta = i / N;
        const w = (i == 0 || i == N) ? 1 : ((i % 2 == 1) ? 4 : 2);
        const c = chordAt(m, eta);
        var v = c;
        if (kind == 1) // chord x quarter-chord x position
            v = c * (m.baseX + m.sweepTip * eta ^ m.sweepExp + (m.pivotFrac - m.align) * (c - m.c0) + (0.25 - m.pivotFrac) * c);
        else if (kind == 2) // chord x thickness
            v = c * (m.rootT + (m.tipT - m.rootT) * eta ^ m.thicknessExp);
        s += w * v;
    }
    return s / (3 * N);
}

/** Area-weighted quarter-chord position (aerodynamic centre), m aft of the wing root pivot. */
function acX(m is map) returns number
{
    return simpsonEta(m, 1) / simpsonEta(m, 0);
}

function meanThickness(m is map) returns number
{
    return simpsonEta(m, 2) / simpsonEta(m, 0);
}

/**
 * Drag of the non-lifting parts at speed V (N): mast = friction on both sides of the SUBMERGED
 * area x a 2D thickness form factor, plus Hoerner spray drag 0.24 q t^2 where it pierces the
 * surface; motor pod (scaled by its wetted fraction, plus spray on its waterline width when it
 * breaks the surface; zero when fully out) and fuselage = body-of-revolution friction x fineness form factor
 * 1 + 1.5 (d/L)^1.5 + 7 (d/L)^3 on their external wetted area. Junction/interference drag and the
 * pod's base drag (normally filled by the prop) are not included - use Other cm^2 for those.
 */
function partsDrag(ctx is map, V is number) returns map
{
    const q = 0.5 * ctx.rho * V * V;
    var mast = 0;
    var spray = 0;      // mast spray only
    var podSpray = 0;
    var body = 0;
    var podFric = 0;    // pod friction only (no spray)
    var fus = 0;
    if (ctx.mastOn && ctx.mastSub > 0)
    {
        // strip by strip over the wetted span (build 241, user: a mast thickened below the waterline was missed by the
        // one section at half the submerged depth): friction x form factor at each strip's own chord and thickness,
        // spray at the waterline's thickness (twin designs/jason/tuning/mast_ultra1150.py)
        const nS = 12;
        for (var i = 0; i < nS; i += 1)
        {
            const st = mastStrip(ctx, (i + 0.5) / nS * ctx.mastSub / ctx.mastH);
            mast += q * 2 * skinFriction(V * st[0] / ctx.nu, ctx.lam) * formFactor(st[1] / st[0]) * st[0] * ctx.mastSub / nS;
        }
        if (ctx.mastPierces)
            spray = q * 0.24 * mastStrip(ctx, ctx.mastSub / ctx.mastH)[1] ^ 2;
        mast += spray;
    }
    if (ctx.podOn && ctx.podFrac > 0)
    {
        // friction on the wetted part only, plus spray where the pod breaks the surface
        podFric = q * skinFriction(V * ctx.podL / ctx.nu, ctx.lam) * bodyFormFactor(ctx.podD / ctx.podL) * ctx.podSwet * ctx.podFrac;
        podSpray = q * 0.24 * ctx.podSprayT ^ 2;
        body += podFric + podSpray;
    }
    if (ctx.fusOn)
    {
        fus = q * skinFriction(V * ctx.fusL / ctx.nu, ctx.lam) * bodyFormFactor(ctx.fusD / ctx.fusL) * ctx.fusSwet;
        body += fus;
    }
    var junc = 0;
    var faces = 0;
    if (ctx.joints != undefined && ctx.joints.on)
    {
        for (var j in ctx.joints.junctions)
            junc += j[0] * junctionDrag(q, j[1], j[2], j[4]);
        for (var f in ctx.joints.faces)
            faces += faceDrag(q, f[0], f[1], f[2]);
    }
    return { "mast" : mast, "spray" : spray, "podSpray" : podSpray, "body" : body,
             "pod" : podFric, "fus" : fus, "joints" : junc + faces, "junctions" : junc, "faces" : faces };
}

function finishWord(finish is string) returns string
{
    return finish == "LOFT" ? "lofted" : (finish == "BARE" ? "bare" : "filleted");
}

/** The joints' drag finishes: junction factor on Hoerner's corner, and the face Cd front / back. */
function jointFactor(finish is string) returns number
{
    return finish == "LOFT" ? 0.1 : (finish == "BARE" ? 1 : 0.5);
}

function faceCd(side is string, finish is string) returns number
{
    if (side == "front")
        return finish == "LOFT" ? 0.04 : (finish == "BARE" ? 0.8 : 0.15);
    return finish == "LOFT" ? 0.02 : (finish == "BARE" ? 0.2 : 0.15);
}

/**
 * Interference drag (N) of one junction where a strut or wing root of thickness t and chord c (m) meets a wall
 * or body at about 90 deg, zero lift: Hoerner, Fluid-Dynamic Drag (1965) ch. 8, dCD on t^2 = 0.75 t/c -
 * 0.0003/(t/c)^2, favourable below about 7.4 % thick (floored at zero). The twin: reference_checks.junction_drag.
 */
function junctionDrag(q is number, t is number, c is number, finish is string) returns number
{
    if (t <= 0 || c <= 0)
        return 0;
    const tc = t / c;
    return max(0, 0.75 * tc - 0.0003 / tc ^ 2) * q * t * t * jointFactor(finish);
}

/** Pressure drag (N) of a face of area A (m^2) square to the flow, front or back, by finish. */
function faceDrag(q is number, A is number, side is string, finish is string) returns number
{
    return faceCd(side, finish) * q * max(A, 0);
}

/**
 * The joints to count, from the parts' own published geometry: two wing-root junctions when the wing has a
 * joint or a fuselage is present, two stab-root junctions with a fuselage, one at the mast's foot on a
 * fuselage or pod; faces: the tube or square socket's nacelle nose where it stands out of the wing's root
 * section and its rear step down to the tube, the flat hub's front where it stands out of the section (a
 * built nose fairing counts as lofted) and its back where no fuselage fills it.
 */
function jointsOf(finishE, wing is map, stab, mastM, fusOn is boolean, socket, hub, flat) returns map
{
    if (finishE == JointFinish.OFF)
        return { "on" : false, "junctions" : [], "faces" : [], "finish" : "OFF", "note" : "" };
    const finish = finishE == JointFinish.LOFT ? "LOFT" : (finishE == JointFinish.BARE ? "BARE" : "FILLET");
    const sockOn = socket != undefined && socket.on == 1;
    const hubOn = hub != undefined && hub.on == 1;
    const flatOn = flat != undefined && flat.on == 1;
    const c0 = wing.c0;
    const tw = wing.rootT * c0;
    var junctions = [];
    var faces = [];
    if (sockOn || hubOn || flatOn || fusOn)
        junctions = append(junctions, (sockOn && socket.fairing == 1) || (hubOn && hub.fairing != undefined && hub.fairing == 1) ? [2, tw, c0, "wing (root fairing)", "LOFT"] : [2, tw, c0, "wing", finish]);
    if (stab != undefined && (fusOn || sockOn || hubOn || flatOn))
        junctions = append(junctions, [2, stab.rootT * stab.c0, stab.c0, "stab", finish]);
    if (mastM != undefined && (fusOn || mastM.podOn == 1))
        junctions = append(junctions, [1, mastM.thick, mastM.chord, "mast", finish]);
    if (sockOn)
    {
        const W = socket.nacelleW != undefined ? socket.nacelleW : socket.nacelleDia;
        const H = socket.nacelleH != undefined ? socket.nacelleH : socket.nacelleDia;
        const sq = socket.joint == "SQUARE";
        const fullA = sq ? W * H : PI / 4 * W * H;
        const rearRatio = socket.rearDia != undefined && socket.nacelleDia != undefined && socket.nacelleDia > 0 ? min(socket.rearDia / socket.nacelleDia, 1) : 1;
        const boreA = sq ? socket.boreW * socket.boreH : PI / 4 * socket.tubeDia ^ 2;
        // the nacelle grows out of the wing from the root's thickest point over Blend length, eased at both
        // ends: its nose is a loft whatever the finish (Hoerner's lofted figure); its mouth is the hard face
        faces = append(faces, [max(fullA - tw * W, 0), "front", "LOFT", "nacelle nose (blended)"]);
        faces = append(faces, [max(fullA * rearRatio ^ 2 - boreA, 0), "back", finish, "socket mouth"]);
    }
    if (hubOn)
    {
        const hW = hub.width;
        const hH = hub.topZ - hub.botZ;
        faces = append(faces, [max(hW * (hH - tw), 0), "front", hub.noseOn == 1 ? "LOFT" : finish, hub.noseOn == 1 ? "hub nose (faired)" : "hub front"]);
        // the nose fairing's flat back face (wing 1.070) is filled by the fuselage; a bar narrower than the hub leaves
        // the strips beside it facing aft
        if (!fusOn && hub.noseOn == 1 && hub.tongueW != undefined && hub.noseTopZ != undefined)
            faces = append(faces, [max((hW - hub.tongueW) * (hub.noseTopZ - hub.topZ), 0), "back", finish, "nose fairing back beside the bar"]);
        if (!fusOn)
            faces = append(faces, [hW * hH, "back", finish, "hub back"]);
    }
    return { "on" : true, "junctions" : junctions, "faces" : faces, "finish" : finish };
}

/**
 * Sets the ride-depth-dependent part data on a copy of ctx: wetted mast span (base to surface,
 * surface at Z = depth in the wing-pivot frame), whether the mast pierces the surface, and the
 * motor pod's wetted fraction and waterline width (from the surface height above its axis).
 */
function rideDepth(ctx is map, depth is number) returns map
{
    var c = ctx;
    c.depth = depth;
    if (c.mastOn)
    {
        c.mastSub = min(max(depth - c.mastBase, 0), c.mastH);
        c.mastPierces = depth - c.mastBase < c.mastH;
        if (c.podOn)
        {
            const hPod = depth - c.podZ;
            const rPod = c.podD / 2;
            c.podFrac = hPod >= rPod ? 1 : (hPod <= -rPod ? 0 : 1 - (acos(hPod / rPod) / radian) / PI);   // acos returns an angle (radian units), not a number
            c.podSprayT = abs(hPod) < rPod ? 2 * sqrt(rPod ^ 2 - hPod ^ 2) : 0;                        // waterline width while it breaks the surface
        }
    }
    return c;
}

// ---------------- propulsion: Wageningen B-series open water ----------------
// Oosterveld & van Oossanen (1975). KT and KQ as sums of C * J^s * (P/D)^t * EAR^u * Z^v,
// each row [C, s, t, u, v]. Identical to the B-series blade feature's tables, so the two agree.
// Fitted for P/D 0.5-1.4, EAR 0.3-1.05, Z 2-7. Open water: no pod/mast wake, no free surface.
const PROP_KT_TERMS = [
    [0.00880496, 0, 0, 0, 0], [-0.204554, 1, 0, 0, 0], [0.166351, 0, 1, 0, 0], [0.158114, 0, 2, 0, 0],
    [-0.147581, 2, 0, 1, 0], [-0.481497, 1, 1, 1, 0], [0.415437, 0, 2, 1, 0], [0.0144043, 0, 0, 0, 1],
    [-0.0530054, 2, 0, 0, 1], [0.0143481, 0, 1, 0, 1], [0.0606826, 1, 1, 0, 1], [-0.0125894, 0, 0, 1, 1],
    [0.0109689, 1, 0, 1, 1], [-0.133698, 0, 3, 0, 0], [0.00638407, 0, 6, 0, 0], [-0.00132718, 2, 6, 0, 0],
    [0.168496, 3, 0, 1, 0], [-0.0507214, 0, 0, 2, 0], [0.0854559, 2, 0, 2, 0], [-0.0504475, 3, 0, 2, 0],
    [0.010465, 1, 6, 2, 0], [-0.00648272, 2, 6, 2, 0], [-0.00841728, 0, 3, 0, 1], [0.0168424, 1, 3, 0, 1],
    [-0.00102296, 3, 3, 0, 1], [-0.0317791, 0, 3, 1, 1], [0.018604, 1, 0, 2, 1], [-0.00410798, 0, 2, 2, 1],
    [-0.000606848, 0, 0, 0, 2], [-0.0049819, 1, 0, 0, 2], [0.0025983, 2, 0, 0, 2], [-0.000560528, 3, 0, 0, 2],
    [-0.00163652, 1, 2, 0, 2], [-0.000328787, 1, 6, 0, 2], [0.000116502, 2, 6, 0, 2], [0.000690904, 0, 0, 1, 2],
    [0.00421749, 0, 3, 1, 2], [0.0000565229, 3, 6, 1, 2], [-0.00146564, 0, 3, 2, 2]
];

const PROP_KQ_TERMS = [
    [0.00379368, 0, 0, 0, 0], [0.00886523, 2, 0, 0, 0], [-0.032241, 1, 1, 0, 0], [0.00344778, 0, 2, 0, 0],
    [-0.0408811, 0, 1, 1, 0], [-0.108009, 1, 1, 1, 0], [-0.0885381, 2, 1, 1, 0], [0.188561, 0, 2, 1, 0],
    [-0.00370871, 1, 0, 0, 1], [0.00513696, 0, 1, 0, 1], [0.0209449, 1, 1, 0, 1], [0.00474319, 2, 1, 0, 1],
    [-0.00723408, 2, 0, 1, 1], [0.00438388, 1, 1, 1, 1], [-0.0269403, 0, 2, 1, 1], [0.0558082, 3, 0, 1, 0],
    [0.0161886, 0, 3, 1, 0], [0.00318086, 1, 3, 1, 0], [0.015896, 0, 0, 2, 0], [0.0471729, 1, 0, 2, 0],
    [0.0196283, 3, 0, 2, 0], [-0.0502782, 0, 1, 2, 0], [-0.030055, 3, 1, 2, 0], [0.0417122, 2, 2, 2, 0],
    [-0.0397722, 0, 3, 2, 0], [-0.00350024, 0, 6, 2, 0], [-0.0106854, 3, 0, 0, 1], [0.00110903, 3, 3, 0, 1],
    [-0.000313912, 0, 6, 0, 1], [0.0035985, 3, 0, 1, 1], [-0.00142121, 0, 6, 1, 1], [-0.00383637, 1, 0, 2, 1],
    [0.0126803, 0, 2, 2, 1], [-0.00318278, 2, 3, 2, 1], [0.00334268, 0, 6, 2, 1], [-0.00183491, 1, 1, 0, 2],
    [0.000112451, 3, 2, 0, 2], [-0.0000297228, 3, 6, 0, 2], [0.000269551, 1, 0, 1, 2], [0.00083265, 2, 0, 1, 2],
    [0.00155334, 0, 2, 1, 2], [0.000302683, 0, 6, 1, 2], [-0.0001843, 0, 0, 2, 2], [-0.000425399, 0, 3, 2, 2],
    [0.0000869243, 3, 3, 2, 2], [-0.0004659, 0, 6, 2, 2], [0.0000554194, 1, 6, 2, 2]
];

/** KT or KQ at advance ratio J for the prop in pr (pd, ear, z). */
function propCoef(terms is array, J is number, pr is map) returns number
{
    var total = 0;
    for (var t in terms)
        total += t[0] * J ^ t[1] * pr.pd ^ t[2] * pr.ear ^ t[3] * pr.z ^ t[4];
    return total;
}

/**
 * Plain-SI propulsion model from the Propulsion group: prop D m, P/D, EAR, blades, hub factors, kV,
 * pack volts (cells x Cell V), torque constant, gear, current limit A, winding ohm, gearbox/ESC
 * efficiency and usable pack Wh.
 * jZero = the advance ratio where KT reaches zero (the prop's no-thrust, windmill boundary).
 */
function propModel(definition is map, rho is number) returns map
{
    var pr = { "D" : definition.propDia / meter, "pd" : definition.propPD, "ear" : definition.propEAR,
               "z" : definition.propBlades, "kv" : definition.motorKv, "vPack" : definition.cells * definition.cellVolts,
               "gear" : definition.gearRatio, "iLim" : definition.currentLimit, "R" : definition.windingR / 1000,
               "etaG" : definition.gearEff / 100, "etaE" : definition.escEff / 100, "rho" : rho };
    pr.kt = definition.torqueConst / pr.kv;                 // N m per motor amp (blade feature's constant, 9.55 default)
    // The polynomials were fitted on a 0.167 D hub; a bigger hub blanks the inner blade:
    // thrust falls with the blanked area (h^3), torque with the blanked moment (h^4).
    const hubRatio = max(0.167, definition.propHub / meter / pr.D);
    pr.hubT = 1 - (hubRatio ^ 3 - 0.167 ^ 3);
    pr.hubQ = 1 - (hubRatio ^ 4 - 0.167 ^ 4);
    pr.packWh = definition.packAh * pr.vPack * definition.usable / 100;
    pr.nNoLoad = pr.kv * pr.vPack / pr.gear / 60;           // prop rev/s at no load
    var lo = 0;
    var hi = 2;
    for (var i = 0; i < 50; i += 1)
    {
        const mid = (lo + hi) / 2;
        if (propCoef(PROP_KT_TERMS, mid, pr) > 0)
            lo = mid;
        else
            hi = mid;
    }
    pr.jZero = lo;
    return pr;
}

/** Shaft torque (N m at the prop) the motor can deliver at full throttle at prop speed n rev/s. */
function propAvailTorque(pr is map, n is number) returns number
{
    const rpmMotor = n * 60 * pr.gear;
    var amps = pr.iLim;
    if (pr.R > 0)
        amps = min(pr.iLim, max(0, (pr.vPack - rpmMotor / pr.kv) / pr.R));   // back-EMF headroom / winding R
    else if (rpmMotor >= pr.kv * pr.vPack)
        amps = 0;
    return pr.kt * amps * pr.gear * pr.etaG;
}

/** Full-throttle operating point at speed V m/s: prop torque demand meets what the motor can give. */
function propFullPower(pr is map, V is number) returns map
{
    const D = pr.D;
    var lo = 1e-3;
    var hi = pr.nNoLoad;
    for (var i = 0; i < 40; i += 1)
    {
        const mid = (lo + hi) / 2;
        if (propCoef(PROP_KQ_TERMS, V / (mid * D), pr) * pr.hubQ * pr.rho * mid ^ 2 * D ^ 5 < propAvailTorque(pr, mid))
            lo = mid;
        else
            hi = mid;
    }
    const n = (lo + hi) / 2;
    const J = V / (n * D);
    return { "n" : n, "J" : J, "T" : propCoef(PROP_KT_TERMS, J, pr) * pr.hubT * pr.rho * n ^ 2 * D ^ 4 };
}

/** Prop thrust N at speed V m/s and prop speed n rev/s. */
function propThrust(pr is map, V is number, n is number) returns number
{
    return propCoef(PROP_KT_TERMS, V / (n * pr.D), pr) * pr.hubT * pr.rho * n ^ 2 * pr.D ^ 4;
}

/** Full-power thrust minus drag at v km/h (positive = still accelerating). */
function propGap(pr is map, pctx is map, v is number) returns number
{
    return propFullPower(pr, v / 3.6).T - trimPoint(pctx, v / 3.6).T;
}

/**
 * Steady operating point: the prop speed that makes thrust T N at speed V m/s (thrust = drag), then
 *   shaft torque Q = KQ rho n^2 D^5, prop efficiency eta0 = J KT / (2 pi KQ),
 *   motor amps Im = Q / (gear x gearbox eff x Torque const/kV), motor volts Vm = motor rpm / kV + Im R,
 *   throttle = Vm / pack V, battery amps = Vm Im / (pack V x ESC eff), Wh/km = battery W / km/h.
 * ok = false when it needs more than the current limit or more than full throttle.
 */
function propOperate(pr is map, V is number, T is number) returns map
{
    const D = pr.D;
    var lo = V / (pr.jZero * D) + 1e-6;
    var hi = max(2 * lo, 5);
    for (var i = 0; i < 30; i += 1)
    {
        if (propThrust(pr, V, hi) >= T)
            break;
        hi = 2 * hi;
    }
    for (var i = 0; i < 40; i += 1)
    {
        const mid = (lo + hi) / 2;
        if (propThrust(pr, V, mid) < T)
            lo = mid;
        else
            hi = mid;
    }
    const n = (lo + hi) / 2;
    const J = V / (n * D);
    const kq = propCoef(PROP_KQ_TERMS, J, pr) * pr.hubQ;
    const Q = kq * pr.rho * n ^ 2 * D ^ 5;
    const eta0 = kq > 0 ? J * propCoef(PROP_KT_TERMS, J, pr) * pr.hubT / (2 * PI * kq) : 0;
    const iMotor = Q / (pr.gear * pr.etaG * pr.kt);
    const vMotor = n * 60 * pr.gear / pr.kv + iMotor * pr.R;
    const throttle = vMotor / pr.vPack;
    const iBatt = vMotor * iMotor / (pr.vPack * pr.etaE);
    const pBatt = pr.vPack * iBatt;
    const whKm = pBatt / (V * 3.6);
    return { "rpm" : n * 60, "J" : J, "eta0" : eta0, "Pshaft" : 2 * PI * n * Q, "iMotor" : iMotor,
             "throttle" : throttle, "iBatt" : iBatt, "pBatt" : pBatt, "whKm" : whKm,
             "range" : pr.packWh / whKm, "tip" : PI * D * n, "ok" : iMotor <= pr.iLim && throttle <= 1 };
}

/**
 * Top speed: where full-power thrust falls to the drag at the powered ride depth. Scans from
 * take-off in 2 km/h steps to a bracket, then bisects. Returns km/h; 0 if full power cannot
 * even hold take-off speed; -1 if still accelerating at 100 km/h.
 */
function propTopSpeed(pr is map, pctx is map, vStart is number) returns number
{
    if (propGap(pr, pctx, vStart) < 0)
        return 0;
    var vLo = vStart;
    var vHi = -1;
    var v = vStart + 2;
    while (v <= 100 + 1e-9)
    {
        if (propGap(pr, pctx, v) < 0)
        {
            vHi = v;
            break;
        }
        vLo = v;
        v += 2;
    }
    if (vHi < 0)
        return -1;
    for (var i = 0; i < 15; i += 1)
    {
        const mid = (vLo + vHi) / 2;
        if (propGap(pr, pctx, mid) < 0)
            vHi = mid;
        else
            vLo = mid;
    }
    return (vLo + vHi) / 2;
}

/** Hoerner body-of-revolution form factor from diameter / length. */
function bodyFormFactor(dl is number) returns number
{
    return 1 + 1.5 * dl ^ 1.5 + 7 * dl ^ 3;
}

/** The mast's chord and thickness (m) at s, its fraction of the height from the base: Foil mast's mastLaw from the published map. */
function mastStrip(ctx is map, s is number) returns array
{
    const ss = min(max(s, 0), 1);
    const u = ctx.mastS0 >= 1 ? 0 : min(max((ss - ctx.mastS0) / (1 - ctx.mastS0), 0), 1);
    return [ctx.mastC0 + (ctx.mastC1 - ctx.mastC0) * ss, ctx.mastT0 + (ctx.mastT1 - ctx.mastT0) * u * u * (3 - 2 * u)];
}

function formFactor(t is number) returns number
{
    return 1 + 2 * t + 60 * t ^ 4;
}

/** Flat-plate skin friction: Schlichting turbulent, with a laminar run corrected by the Blasius value. */
function skinFriction(Re is number, lam is number) returns number
{
    const turbRe = 0.455 / (log(Re) / log(10)) ^ 2.58;
    if (lam <= 0)
        return turbRe;
    const Rt = lam * Re;
    const turbRt = 0.455 / (log(Rt) / log(10)) ^ 2.58;
    return turbRe - lam * (turbRt - 1.328 / sqrt(Rt));
}

/** True if any of the given Reynolds numbers falls outside a surface's own polarRe1-polarRe2 span. */
function polarOutOfRange(m is map, res is array) returns boolean
{
    const lo = min(m.polarRe1, m.polarRe2);
    const hi = max(m.polarRe1, m.polarRe2);
    for (var Re in res)
        if (Re < lo || Re > hi)
            return true;
    return false;
}

/** Log-Re interpolation of a polar quantity between two given (Re, value) points, clamped flat outside the range. */
function polarInterp(re1 is number, y1 is number, re2 is number, y2 is number, Re is number) returns number
{
    if (re1 == re2)
        return y1;
    const lo = min(re1, re2);
    const hi = max(re1, re2);
    const ylo = re1 <= re2 ? y1 : y2;
    const yhi = re1 <= re2 ? y2 : y1;
    var t = (log(Re) - log(lo)) / (log(hi) - log(lo));
    t = max(0, min(1, t));
    return ylo + t * (yhi - ylo);
}

/**
 * Steady level flight at speed V (m/s): solve body angle for lift = weight,
 * then drag, power and the CG position that trims the pitching moment.
 */
/**
 * Trim at speed V. Under power the thrust vector is fixed to the body: it makes the angle
 * (body angle - Pod tilt) with the flow, so it carries a vertical component Tz that unloads the
 * foil and, acting at the pod's X behind the CG, pitches the nose down. Tz depends on the trim
 * and the trim on Tz, so three passes (Tz is at most a few % of the weight).
 */
function trimPoint(ctx is map, V is number) returns map
{
    var Tz = 0;
    var r = trimPass(ctx, V, 0);
    if (ctx.powered)
    {
        for (var pass = 0; pass < 3; pass += 1)
        {
            const theta = r.alpha - ctx.podTilt;
            Tz = r.D / cos(theta * radian) * sin(theta * radian);
            r = trimPass(ctx, V, Tz);
        }
        const theta = r.alpha - ctx.podTilt;
        r.thrustAngle = theta * 180 / PI;                     // deg, positive = pointing up out of the flow
        r.T = r.D / cos(theta * radian);
        r.Tz = Tz;
    }
    else
    {
        r.thrustAngle = 0;
        r.T = r.D;
        r.Tz = 0;
    }
    return r;
}

function trimPass(ctx is map, V is number, Tz is number) returns map
{
    const q = 0.5 * ctx.rho * V * V;
    const wing = ctx.wing;
    const Lw = ctx.Lw;
    const Sw = wing.area;
    const Ss = ctx.hasStab ? ctx.stab.area : 0;

    // the foil carries the weight less the thrust's vertical component
    const alpha = ((ctx.W - Tz) / q - Sw * Lw.CL0 - Ss * ctx.C1) / (Sw * Lw.CLa + Ss * ctx.C2);
    const CLw = Lw.CL0 + Lw.CLa * alpha;
    const eps = ctx.ke * CLw;

    const Rew = V * wing.mac / ctx.nu;
    const CDiw = lltInducedDrag(Lw, alpha);
    const CDprofw = wing.polarOn == 1
        ? polarInterp(wing.polarRe1, wing.polarCdmin1 + wing.polarK1 * (CLw - wing.polarClcd1) ^ 2,
                      wing.polarRe2, wing.polarCdmin2 + wing.polarK2 * (CLw - wing.polarClcd2) ^ 2, Rew)
        : skinFriction(Rew, ctx.lam) * ctx.cd0Shape_w * (1 + 0.38 * CLw * CLw);
    const CDw = CDprofw + CDiw;
    var D = q * (Sw * CDw + ctx.cdA);
    var Di = q * Sw * CDiw;
    var Mo = -q * Sw * CLw * ctx.xw + q * Sw * wing.mac * wing.cm0 + ctx.Mext;

    var CLs = 0;
    var Ds = 0;
    if (ctx.hasStab)
    {
        const stab = ctx.stab;
        const alphaS = alpha - eps; // stab sees the body angle minus wing downwash
        CLs = ctx.Ls.CL0 + ctx.Ls.CLa * alphaS;
        const Res = V * stab.mac / ctx.nu;
        const CDis = lltInducedDrag(ctx.Ls, alphaS);
        const CDprofs = stab.polarOn == 1
            ? polarInterp(stab.polarRe1, stab.polarCdmin1 + stab.polarK1 * (CLs - stab.polarClcd1) ^ 2,
                          stab.polarRe2, stab.polarCdmin2 + stab.polarK2 * (CLs - stab.polarClcd2) ^ 2, Res)
            : skinFriction(Res, ctx.lam) * ctx.cd0Shape_s * (1 + 0.38 * CLs * CLs);
        const CDs = CDprofs + CDis;
        Ds = q * Ss * CDs;
        D += Ds;
        Di += q * Ss * CDis;
        Mo += -q * Ss * CLs * ctx.xs + q * Ss * stab.mac * stab.cm0;
    }
    const parts = partsDrag(ctx, V);
    D += parts.mast + parts.body + parts.joints;

    // powered: thrust = D along the prop axis (Z = thrustZ, forward) against every drag force at its
    // own height. The two sum to zero, so this is a pure couple - the same about any point, so the
    // CG height does not enter. Nose-up positive: sum(D_i z_i) - D z_thrust. Wing drag and Other
    // cm^2 act at Z = 0 (the wing root pivot); the rest at the heights published by their features.
    var Mthrust = 0;
    if (ctx.powered)
    {
        var dz = Ds * ctx.stabZ + parts.fus * ctx.fusZ + parts.joints * ctx.fusZ;
        if (ctx.mastOn)
        {
            dz += (parts.mast - parts.spray) * (ctx.mastBase + ctx.mastSub / 2) + parts.spray * ctx.depth;
            if (ctx.podOn)
                dz += parts.pod * ctx.podZ + parts.podSpray * ctx.depth;
        }
        Mthrust = dz - D * ctx.thrustZ;
        Mo += Mthrust;
        // the vertical component acts at the pod: upward behind the CG is nose-down
        Mo += -Tz * ctx.podX;
    }
    return { "Mthrust" : Mthrust, "alpha" : alpha, "CLw" : CLw, "CLs" : CLs, "Re" : Rew, "D" : D, "Di" : Di,
            "Dmast" : parts.mast, "Dbody" : parts.body, "Dspray" : parts.spray, "DpodSpray" : parts.podSpray, "Djoints" : parts.joints,
            "LD" : ctx.W / D, "P" : D * V, "xcg" : -Mo / ctx.W };
}

/** Quarter-chord pitching moment of a NACA 4-digit mean line (thin-aerofoil theory). About -0.053 for a 2412. */
function momentCoefficient(m is number, p is number) returns number
{
    if (m == 0)
        return 0;
    const N = 400;
    var sum = 0;
    for (var i = 1; i <= N; i += 1)
    {
        const th = PI * (i - 0.5) / N;
        const x = 0.5 * (1 - cos(th * radian));
        const dyc = x < p ? 2 * m / p ^ 2 * (p - x) : 2 * m / (1 - p) ^ 2 * (p - x);
        sum += dyc * (cos(2 * th * radian) - cos(th * radian));
    }
    return 0.5 * sum * PI / N;
}

// ---------------------------------------------------------------------------
// Library
// ---------------------------------------------------------------------------

/**
 * Built-in polar for a profile at its thickness (build 241): the NACA 4-digit fit as it stands, and for a
 * tabulated profile its XFoil polar at the table's own thickness moved to the section actually built
 * (tableSection scales the thickness with the camber line fixed; Clark Y whole). Until wing 1.069 a
 * table polar ignored the thickness, so a thinner MRC-16 tip read the native section's drag and
 * CL max. The changes are quadratics through the native point in dt = t - t0, fitted to NeuralFoil
 * (xlarge, Ncrit 9) on each table scaled the way tableSection scales it, at the two Reynolds numbers
 * of its built-in polar, from 0.65 to 1.3 of t0 (scripts/fit_thickness_polars.py); dt is held to
 * that range. Lift slope, CL max and CL at Cd min take the change added, Cd min and the bucket's
 * curvature as a ratio. alpha0 and cm0 stay thin-aerofoil (sectionAlpha0Cm0).
 */
function builtinPolar(profile is FoilProfile, camberFrac is number, camberPosFrac is number, thickFrac is number)
{
    var b = builtinPolarNative(profile, camberFrac, camberPosFrac, thickFrac);
    const tp = tableThicknessPolar(profile);
    if (b == undefined || tp == undefined)
        return b;
    const t0 = tp.t0;
    const dt = clamp01(thickFrac - t0, -0.35 * t0, 0.3 * t0);
    const shift = function(c) { return c[0] * dt + c[1] * dt * dt; };
    b.cla = clamp01(b.cla + shift(tp.cla), 4, 7.5);
    b.clmax1 = clamp01(b.clmax1 + shift(tp.clmax1), 0.4, 1.8);
    b.clmax2 = clamp01(b.clmax2 + shift(tp.clmax2), 0.4, 1.8);
    b.clcd1 = b.clcd1 + shift(tp.clcd1);
    b.clcd2 = b.clcd2 + shift(tp.clcd2);
    b.cdmin1 = max(b.cdmin1 * (1 + shift(tp.cdmin1)), 0.003);
    b.cdmin2 = max(b.cdmin2 * (1 + shift(tp.cdmin2)), 0.003);
    b.k1 = max(b.k1 * (1 + shift(tp.k1)), 0.001);
    b.k2 = max(b.k2 * (1 + shift(tp.k2)), 0.001);
    return b;
}

/**
 * Thickness change of a tabulated profile's polar (see builtinPolar): t0 the table's own thickness
 * (tableMaxThickness), and per number [a, b] of a dt + b dt^2. Undefined for NACA 4-digit, whose fit
 * already takes the thickness.
 */
function tableThicknessPolar(profile is FoilProfile)
{
    if (profile == FoilProfile.E817)
        return { "t0" : 0.1098, "cla" : [-1.62, 153], "clmax1" : [7.19, -9], "clmax2" : [9.03, -64], "clcd1" : [6.40, 173], "clcd2" : [-0.32, 14],
                 "cdmin1" : [4.87, -4], "cdmin2" : [3.02, 17], "k1" : [-27.75, 80], "k2" : [-20.45, 318] };
    if (profile == FoilProfile.E818)
        return { "t0" : 0.0937, "cla" : [-9.26, 182], "clmax1" : [5.84, 16], "clmax2" : [7.74, 52], "clcd1" : [-1.24, 5], "clcd2" : [0.08, 10],
                 "cdmin1" : [6.55, -12], "cdmin2" : [0.15, 46], "k1" : [-16.29, 257], "k2" : [-15.35, 73] };
    if (profile == FoilProfile.NACA63412)
        return { "t0" : 0.1199, "cla" : [1.66, 57], "clmax1" : [4.40, -64], "clmax2" : [2.06, -44], "clcd1" : [-1.11, -18], "clcd2" : [-0.98, 9],
                 "cdmin1" : [6.80, 21], "cdmin2" : [4.67, 4], "k1" : [-18.86, 145], "k2" : [-17.90, 245] };
    if (profile == FoilProfile.CLARKY)
        return { "t0" : 0.1171, "cla" : [-4.85, 3], "clmax1" : [6.39, 10], "clmax2" : [5.71, -45], "clcd1" : [3.33, -39], "clcd2" : [2.45, -25],
                 "cdmin1" : [5.09, 0], "cdmin2" : [4.95, -17], "k1" : [-4.68, 96], "k2" : [-11.09, 280] };
    if (profile == FoilProfile.MRC16)
        return { "t0" : 0.1390, "cla" : [2.37, -84], "clmax1" : [1.39, 16], "clmax2" : [0.63, -10], "clcd1" : [-1.82, -18], "clcd2" : [-1.26, -4],
                 "cdmin1" : [3.42, 18], "cdmin2" : [3.23, -8], "k1" : [-7.49, 60], "k2" : [-9.47, 196] };
    if (profile == FoilProfile.MH18)
        return { "t0" : 0.1114, "cla" : [8.45, -42], "clmax1" : [3.10, -86], "clmax2" : [3.93, -79], "clcd1" : [-0.08, -26], "clcd2" : [-0.11, -14],
                 "cdmin1" : [3.86, 1], "cdmin2" : [3.06, 0], "k1" : [-18.02, 302], "k2" : [-19.81, 355] };
    if (profile == FoilProfile.H105)
        return { "t0" : 0.1255, "cla" : [0.15, -20], "clmax1" : [3.91, -87], "clmax2" : [3.59, -85], "clcd1" : [-1.06, -5], "clcd2" : [-1.07, 2],
                 "cdmin1" : [2.72, 29], "cdmin2" : [3.32, 0], "k1" : [-12.61, 121], "k2" : [-15.17, 243] };
    return undefined;
}

/**
 * Fitted XFoil polars embedded for the tabulated profiles at the table's own thickness (Ncrit 9
 * except E818 Re 0.5M, Ncrit 5; source airfoiltools.com / UIUC, fitted with scripts/polar_summary.py);
 * builtinPolar moves them to the section's thickness. Returns undefined for profiles without
 * built-in data.
 */
function builtinPolarNative(profile is FoilProfile, camberFrac is number, camberPosFrac is number, thickFrac is number)
{
    if (profile == FoilProfile.NACA4)
    {
        // Parametric, so there is no single fixed polar. alpha0/cm0 come from the SAME exact
        // thin-aerofoil integral used everywhere else in this file (zeroLiftAngle/momentCoefficient)
        // - not a fit, exact for any camber and camber position. Everything else (lift slope, CLmax,
        // drag bucket) is a linear fit in (thickness, camber) against 4 real XFoil polars fetched
        // and fit with polar_summary.py: NACA 0008, 0018 (thickness range, symmetric) and NACA 2412,
        // 4412 (camber range, fixed 12% thick) - see the developer skill's pitfalls.md for why CLcd
        // is anchored through zero at zero camber (aerodynamic symmetry) rather than fit from the
        // thickness pair, which gave a physically impossible negative value at one data point.
        // Coarse by construction: only 4 anchor points for a 2D surface. Clamped to the same limits
        // as the Polar summary fields, since linear extrapolation misbehaves at the extremes (e.g.
        // lift slope exceeds 7.5/rad above ~20% thickness).
        const dt = thickFrac - 0.12;
        const m = camberFrac;
        return { "alpha0Deg" : zeroLiftAngle(camberFrac, camberPosFrac) / degree, "cm0" : momentCoefficient(camberFrac, camberPosFrac),
                 "cla" : clamp01(6.898 + 10.24 * dt - 13.25 * m, 4, 7.5),
                 "re1M" : 0.1, "clmax1" : clamp01(0.916 + 3.79 * dt + 7.05 * m, 0.6, 1.8),
                 "cdmin1" : clamp01(0.0133 + 0.082 * dt + 0.16 * m, 0.004, 0.03),
                 "clcd1" : clamp01(14.55 * m, -0.3, 1.0), "k1" : clamp01(0.0245 - 0.185 * dt + 0.075 * m, 0.005, 0.05),
                 "re2M" : 1.0, "clmax2" : clamp01(1.205 + 1.04 * dt + 4.45 * m, 0.6, 1.8),
                 "cdmin2" : clamp01(0.00336 + 0.059 * dt + 0.03 * m, 0.004, 0.03),
                 "clcd2" : clamp01(13.25 * m, -0.3, 1.0), "k2" : clamp01(0.00474 + 0.026 * dt + 0.005 * m, 0.005, 0.05) };
    }
    if (profile == FoilProfile.E817)
        return { "alpha0Deg" : -2.96, "cla" : 6.471, "cm0" : -0.1069,
                 "re1M" : 0.2, "clmax1" : 1.062, "cdmin1" : 0.0177, "clcd1" : 0.615, "k1" : 0.0021,
                 "re2M" : 1.0, "clmax2" : 1.147, "cdmin2" : 0.0051, "clcd2" : 0.294, "k2" : 0.0164 };
    if (profile == FoilProfile.E818)
        return { "alpha0Deg" : -2.41, "cla" : 6.258, "cm0" : -0.0914,
                 "re1M" : 0.1, "clmax1" : 0.889, "cdmin1" : 0.0106, "clcd1" : 0.698, "k1" : 0.012,
                 "re2M" : 0.5, "clmax2" : 1.025, "cdmin2" : 0.0062, "clcd2" : 0.312, "k2" : 0.0327 };
    if (profile == FoilProfile.NACA63412)
        return { "alpha0Deg" : -2.98, "cla" : 6.194, "cm0" : -0.0752,
                 "re1M" : 0.2, "clmax1" : 0.99, "cdmin1" : 0.0104, "clcd1" : 0.429, "k1" : 0.0154,
                 "re2M" : 0.5, "clmax2" : 1.311, "cdmin2" : 0.0064, "clcd2" : 0.34, "k2" : 0.0154 };
    if (profile == FoilProfile.MRC16)    // airfoiltools XFoil xf-mrc-16-il-200000 / -1000000, Ncrit 9, fit with polar_summary.py (build 227)
        return { "alpha0Deg" : -3.28, "cla" : 6.467, "cm0" : -0.0727,
                 "re1M" : 0.2, "clmax1" : 1.324, "cdmin1" : 0.0101, "clcd1" : 0.517, "k1" : 0.019,
                 "re2M" : 1.0, "clmax2" : 1.494, "cdmin2" : 0.0057, "clcd2" : 0.442, "k2" : 0.009 };
    if (profile == FoilProfile.MH18)     // airfoiltools XFoil xf-mh18-il-200000 / -1000000, Ncrit 9, fit with polar_summary.py (build 227)
        return { "alpha0Deg" : -2.11, "cla" : 6.829, "cm0" : -0.0382,
                 "re1M" : 0.2, "clmax1" : 1.081, "cdmin1" : 0.011, "clcd1" : 0.435, "k1" : 0.018,
                 "re2M" : 1.0, "clmax2" : 1.161, "cdmin2" : 0.0048, "clcd2" : 0.38, "k2" : 0.0129 };
    if (profile == FoilProfile.H105)     // no published XFoil polar: NeuralFoil xlarge (XFoil-trained) at Ncrit 9, Re 0.5 / 1.0 M, same fit (build 227)
        return { "alpha0Deg" : -2.75, "cla" : 5.86, "cm0" : -0.0758,
                 "re1M" : 0.5, "clmax1" : 1.168, "cdmin1" : 0.0059, "clcd1" : 0.27, "k1" : 0.0211,
                 "re2M" : 1.0, "clmax2" : 1.275, "cdmin2" : 0.0044, "clcd2" : 0.25, "k2" : 0.0175 };
    if (profile == FoilProfile.CLARKY)   // airfoiltools XFoil xf-clarky-il-200000 / -1000000, Ncrit 9, fit with polar_summary.py
    {
        // fitted at the table's 11.7 %; the section is scaled whole with its thickness (build 168),
        // so the camber-driven zero-lift angle and moment scale with it; CL at Cd min moves with the
        // thickness fit in builtinPolar, which saw the whole-scaled section (wing 1.069)
        const k = thickFrac / 0.1171;
        return { "alpha0Deg" : -3.56 * k, "cla" : 6.348, "cm0" : -0.0848 * k,
                 "re1M" : 0.2, "clmax1" : 1.397, "cdmin1" : 0.0099, "clcd1" : 0.572, "k1" : 0.0207,
                 "re2M" : 1.0, "clmax2" : 1.524, "cdmin2" : 0.0061, "clcd2" : 0.487, "k2" : 0.0099 };
    }
    return undefined;
}

/** Clamp x to [lo, hi]. */
function clamp01(x is number, lo is number, hi is number) returns number
{
    return min(max(x, lo), hi);
}

/**
 * Section polar data as one map (alpha0Deg, cla, cm0, re1M, clmax1, cdmin1, clcd1, k1, re2M, clmax2,
 * cdmin2, clcd2, k2), from the dialog (Polar summary) or the built-in table (Built-in), or
 * undefined for Analytic. Each dialog parameter is declared exactly once in the precondition -
 * Onshape rejects a parameter declared in more than one branch, so per-profile values live here
 * in code, not as per-branch parameter defaults.
 */
function resolvePolar(definition is map)
{
    if (definition.polarSource == PolarSource.BUILTIN)
    {
        const b = builtinPolar(definition.profile, definition.camber / 100, definition.camberPos / 100, definition.rootThickness / 100);
        if (b == undefined)
            throw regenError("Built-in polar data exists only for NACA 4-digit, E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18 and H105 - choose one of those Profiles, or set Section data to Polar summary or Analytic", ["polarSource"]);
        return b;
    }
    if (definition.polarSource == PolarSource.POLAR)
        return { "alpha0Deg" : definition.polarAlpha0 / degree, "cla" : definition.polarCla, "cm0" : definition.polarCm0,
                 "re1M" : definition.polarRe1, "clmax1" : definition.polarClmax1, "cdmin1" : definition.polarCdmin1,
                 "clcd1" : definition.polarClcd1, "k1" : definition.polarK1,
                 "re2M" : definition.polarRe2, "clmax2" : definition.polarClmax2, "cdmin2" : definition.polarCdmin2,
                 "clcd2" : definition.polarClcd2, "k2" : definition.polarK2 };
    return undefined;
}

/**
 * Shared foil geometry: solves the planform, lofts the half foil through streamwise
 * sections, mirrors and joins. The root pivot is placed at `base`.
 * When the definition has stabLink == LINKED, area, aspect ratio, thickness and
 * incidence are first overridden from the wing variables before solving.
 * Returns the planform metrics as a map.
 */
/** Span and root chord for a chord-shape ratio: area/AR mode solves them (developed area iterates on the droop), span/chord mode reads them. */
/**
 * Span and root chord for a planform law. plCap is the law with capEta unset; planCapLen is the
 * plan-rounding cap length (0 for none): capEta depends on the span, which in area mode depends
 * on the area only (projected) or is iterated (developed), so the law is completed here and
 * returned as pl.
 */
function solvePlanform(definition is map, plCap is map, planCapLen is ValueWithUnits) returns map
{
    var pl = plCap;
    var span;
    var c0;
    if (definition.planformMode == PlanformMode.AREA_AR)
    {
        const target = definition.targetArea * centimeter * centimeter;
        var sProj = target;
        span = sqrt(definition.aspectRatio * sProj);
        pl.capEta = planCapLen > 0 * meter ? max(1 - planCapLen / (span / 2), 0.5) : 1;
        if (definition.areaDefinition == AreaDefinition.DEVELOPED)
        {
            // developed/projected ratio depends on span (drop is absolute), so iterate
            for (var k = 0; k < 12; k += 1)
            {
                const b = sqrt(definition.aspectRatio * sProj);
                pl.capEta = planCapLen > 0 * meter ? max(1 - planCapLen / (b / 2), 0.5) : 1;
                const r = shapeIntegral(pl, 2, definition.tipDrop / (b / 2), tan(definition.rootDihedral)) / shapeIntegral(pl, 0, 0, 0);
                sProj = target / r;
            }
            span = sqrt(definition.aspectRatio * sProj);
            pl.capEta = planCapLen > 0 * meter ? max(1 - planCapLen / (span / 2), 0.5) : 1;
        }
        c0 = sProj / (span * shapeIntegral(pl, 0, 0, 0));
    }
    else
    {
        span = definition.span;
        c0 = definition.rootChord;
        pl.capEta = planCapLen > 0 * meter ? max(1 - planCapLen / (span / 2), 0.5) : 1;
    }
    return { "G" : shapeIntegral(pl, 0, 0, 0), "G2" : shapeIntegral(pl, 1, 0, 0), "span" : span, "c0" : c0, "pl" : pl };
}

/** Names every solid the feature has left in the Part Studio (the sketch and tool bodies are gone by then). */
function nameSolids(context is Context, id is Id, name is string)
{
    setProperty(context, { "entities" : qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID),
                "propertyType" : PropertyType.NAME, "value" : name });
}

function buildFoil(context is Context, id is Id, rawDefinition is map, base is Vector) returns map
{
    var definition = rawDefinition;
    if (definition.stabLink != undefined && definition.stabLink == StabLink.LINKED)
    {
        var wingArea;
        var wingAR;
        var wingRootT;
        var wingTipT;
        var wingInc;
        try silent
        {
            wingArea = getVariable(context, "foilWingArea");
            wingAR = getVariable(context, "foilWingAR");
            wingRootT = getVariable(context, "foilWingRootThickness");
            wingTipT = getVariable(context, "foilWingTipThickness");
            wingInc = getVariable(context, "foilWingIncidence");
        }
        if (wingArea != undefined && wingAR != undefined && wingRootT != undefined
            && wingTipT != undefined && wingInc != undefined)
        {
            definition.targetArea = wingArea / (centimeter * centimeter) * definition.linkAreaRatio;
            definition.aspectRatio = wingAR + definition.linkAROffset;
            definition.rootThickness = wingRootT + definition.linkThicknessOffset;
            definition.tipThickness = wingTipT + definition.linkThicknessOffset;
            definition.incidence = wingInc - definition.linkDecalage;
            definition.planformMode = PlanformMode.AREA_AR;
            definition.areaDefinition = AreaDefinition.PROJECTED;
        }
    }
    // a stab's tabulated profile may be mounted inverted (its own field); the wing never is
    definition.invertSection = definition.invertSection == true && definition.profile != FoilProfile.NACA4;
    // ================= planform solve =================
    const n = definition.chordShape == ChordShape.SUPERELLIPSE ? definition.superN : 2;
    const ratioIn = definition.chordShape == ChordShape.SUPERELLIPSE ? definition.endRatio : definition.tipRatio;
    const shape = definition.chordShape;
    const isDouble = shape == ChordShape.DOUBLE;
    const brk = isDouble ? definition.breakPct / 100 : 0.3;
    const mid = isDouble ? definition.midRatio : 0.6;
    // blend half-width, kept inside (0, brk) and (brk, 1) so the curve never reaches root or tip
    const blend = isDouble ? min(min(definition.blendPct / 100, 0.95 * brk), 0.95 * (1 - brk)) : 0;
    if (isDouble && ratioIn > mid)
        throw regenError("Tip ratio (" ~ fmt(ratioIn, 2) ~ ") exceeds Mid ratio (" ~ fmt(mid, 2) ~ "): the outer taper would widen towards the tip", ["tipRatio", "midRatio"]);
    const capOn = definition.tipCap != TipCap.FLAT;
    const planRound = definition.tipCap == TipCap.ROUND_PLAN;
    const capLen = capOn ? definition.capLength : 0 * meter;
    // root tail (stab only): a fraction of c0, so it has to be re-derived from the mm value as c0
    // moves through the solve; the solve loop below does that
    const tailOn = definition.rootTailOn == true && definition.rootTailLen != undefined;
    const tailEta = tailOn ? definition.rootTailSpan / 100 : 0.3;
    const dropFrom = definition.dropFrom == undefined ? 0 : definition.dropFrom / 100;
    const dropTo = definition.dropTo == undefined ? 1 : max(definition.dropTo / 100, dropFrom + 0.05);
    const dl = { "dropExp" : definition.dropExp, "dropFrom" : dropFrom, "dropTo" : dropTo, "dropSmooth" : definition.dropLaw == DropLaw.SCURVE ? 1 : 0 };
    const bumpOn = definition.bumpOn == true && definition.bumpAmp != undefined;
    const bumpKeys = { "bumpOn" : bumpOn ? 1 : 0, "bumpAmp" : bumpOn ? definition.bumpAmp / meter : 0, "bumpPitch" : bumpOn ? definition.bumpPitch / meter : 0.07,
                       "bumpFrom" : bumpOn ? definition.bumpFrom / 100 : 0, "bumpTo" : bumpOn ? definition.bumpTo / 100 : 0 };

    // Min tip: widen the tip chord (raise the ratio) until the section at the cap start reaches
    // Min tip mm. The root chord moves a little with the ratio in area mode, so iterate.
    const minTipOn = definition.minTipOn == true && definition.minTip != undefined;
    var ratio = ratioIn;
    var tipRaised = false;
    var G;
    var G2;
    var span;
    var c0;
    var pl;
    var tail = 0;
    for (var pass = 0; pass < 8; pass += 1)
    {
        const ps = solvePlanform(definition, { "shape" : shape, "ratio" : ratio, "n" : n, "brk" : brk, "mid" : mid, "blend" : blend, "capEnd" : definition.capEnd / 100, "dropFrom" : dropFrom, "dropTo" : dropTo, "dropSmooth" : dl.dropSmooth, "dropExp" : definition.dropExp,
                                              "tail" : tail, "tailEta" : tailEta },
                                 planRound ? capLen : 0 * meter);
        G = ps.G;
        G2 = ps.G2;
        span = ps.span;
        c0 = ps.c0;
        pl = mergeMaps(ps.pl, bumpKeys);
        var settled = true;
        if (tailOn)
        {
            // the tail is Tail length in mm: as a fraction of c0 it changes as c0 changes, so pass again
            const tailNew = definition.rootTailLen / c0;
            settled = abs(tailNew - tail) < 1e-4;
            tail = tailNew;
        }
        if (!minTipOn && settled)
            break;
        if (!minTipOn)
            continue;
        const tipChord = c0 * chordFactor(pl, pl.capEta);   // the last full section before the cap
        const need = definition.minTip / (definition.tipThickness / 100);
        if (tipChord >= need - 1e-6 * meter)
        {
            // thick enough: only ever RAISE the ratio, never shrink it back down to the minimum
            // (build 145-146 did, while the root tail was still settling: 0.21 became 0.128)
            if (settled)
                break;
            continue;
        }
        ratio = min(isDouble ? mid : 0.95, ratio * need / tipChord); // double taper: never wider than the break
        tipRaised = true;
    }

    const h = span / 2;
    const dropK = definition.tipDrop / h;
    const areaProj = span * c0 * G;
    const areaDev = span * c0 * shapeIntegral(pl, 2, dropK, tan(definition.rootDihedral));
    const mac = span * c0 * c0 * G2 / areaProj;
    const aspect = span ^ 2 / areaProj;
    const tipChord = c0 * chordFactor(pl, pl.capEta);

    // ================= validation =================
    if (definition.teThickness > 0.03 * c0)
        throw regenError("Trailing edge thickness exceeds 3% of the root chord (" ~ toString(round(c0 / millimeter)) ~ " mm)",
            ["teThickness"]);
    if (capOn && capLen > 0.3 * h)
        throw regenError("Tip cap is longer than 30% of the half span", ["capLength"]);

    // ================= winglet =================
    // the outer (1 - wEta) of the developed half span bends through wAng on radius wR; the chord
    // law is unchanged along it, so the planform solve above already includes the winglet's area
    const wingletOn = definition.winglet != undefined && definition.winglet != Winglet.OFF;
    var wEta = 1;
    var wSign = 0;
    var wAng = 0 * degree;
    var wR = 0 * meter;
    var wRClamped = false;
    var wS0 = h;
    var wZ0 = 0 * meter;
    var wPhi0 = 0 * degree;
    if (wingletOn)
    {
        wSign = definition.winglet == Winglet.UP ? 1 : -1;
        wAng = definition.wingletAngle;
        const target = definition.wingletArea * centimeter * centimeter;
        var lo = 0.3;
        var hi = 1;
        for (var it = 0; it < 40; it += 1)
        {
            const em = 0.5 * (lo + hi);
            if (shapeIntegralFrom(pl, em) * c0 * h > target)
                lo = em;
            else
                hi = em;
        }
        wEta = 0.5 * (lo + hi);
        if (wEta < 0.3 + 1e-4)
            throw regenError("Winglet area " ~ fmt(definition.wingletArea, 1) ~ " cm² would start the bend inside 30 % of the half span - reduce it (the outer 70 % holds " ~
                fmt(shapeIntegralFrom(pl, 0.3) * c0 * h / (centimeter * centimeter), 1) ~ " cm²)", ["wingletArea"]);
        wS0 = wEta * h;
        const ps0 = dropSlope(dl, wEta);
        const f0 = dropShape(dl, wEta);
        wZ0 = -definition.tipDrop * f0 + h * tan(definition.rootDihedral) * (wEta - f0);
        wPhi0 = atan((-definition.tipDrop * ps0 + h * tan(definition.rootDihedral) * (1 - ps0)) / h);
        wR = definition.wingletRadius;
        const wLen = h - wS0;
        if (wR * (wAng / radian) > wLen)
        {
            wR = wLen / (wAng / radian);
            wRClamped = true;
        }
    }

    // ================= stations =================
    const secDef = sectionDefFromDefinition(definition);
    const capStart = h - capLen;
    // with Min tip on, the cap's end is at least 0.5 mm thick (build 239): the default wing's 1 mm cap
    // start at Cap end 25 % ran out to 0.25 mm, which a NACA 4-digit section molded but MRC-16 did not
    // (the LOWER cavity cut, non-manifold); 0.4 mm molded. Thickness only - the plan rounding keeps Cap end %
    var capEndT = definition.capEnd / 100;
    var capEndRaised = false;
    if (capOn && definition.minTipOn == true)
    {
        // the end's thickness is Cap end % of Tip thick % of the end chord (the chord at the plan rounding's
        // start, or at the tip without it): the reference the mold's tip advice uses, not the cap-start station's
        const tCS = definition.tipThickness / 100 * c0 * chordFactor(pl, pl.capEta == undefined ? 1 : pl.capEta);
        if (tCS > 0 * meter && tCS * capEndT < 0.5 * millimeter)
        {
            capEndT = min(0.5 * millimeter / tCS, 1);
            capEndRaised = true;
        }
    }
    // the loft's stations (foilStationEtas), from the keys the model publishes; build 235 adds the drop
    // law's, so a drooped surface follows its law between stations
    const stMap = mergeMaps(pl, { "span" : span / meter, "stations" : definition.stations, "tail" : tail, "tailEta" : tailEta,
                                  "tipDrop" : definition.tipDrop / meter, "rootDihedral" : definition.rootDihedral / radian,
                                  "tipOn" : secDef.tipOn ? 1 : 0, "blendFrom" : secDef.blendFrom,
                                  "wingletOn" : wingletOn ? 1 : 0, "wingletEta" : wEta, "wingletR" : wR / meter, "wingletAngle" : wAng / radian,
                                  "capOn" : capOn ? 1 : 0, "capLength" : capLen / meter });
    var stations = [];
    for (var e in foilStationEtas(stMap))
        stations = append(stations, e * h);

    // ================= sections =================
    const pivotFrac = pivotFraction(definition.pivot);
    var profiles = [];
    var sketchBodies = [];
    var rootPts = [];
    for (var i = 0; i < size(stations); i += 1)
    {
        const y = stations[i];
        const eta = min(max(y / h, 0), 1);

        const chord = c0 * chordFactor(pl, eta);
        const tailAdd = c0 * tailFactor(pl, eta);           // root tail: all of it behind the trailing edge

        var thick = (definition.rootThickness + (definition.tipThickness - definition.rootThickness) * eta ^ definition.thicknessExp) / 100;
        thick = thick * (chord - tailAdd) / chord;           // keep the thickness in mm; the tail only stretches the section aft
        if (capOn && y > capStart)
        {
            const d = min((y - capStart) / capLen, 1);
            const endFrac = capEndT;
            // Rounded + plan: the chord already shrinks along the same curve, so divide it back out;
            // the end face is then Cap end % of the cap-start thickness, not Cap end % squared
            // (build 150: 20 % of 20 % left a 0.06 mm end that the mold could not cut)
            thick = thick * (endFrac + (1 - endFrac) * sqrt(max(1 - d * d, 0))) / (planRound ? capPlanFactor(pl, eta) : 1);
        }

        const twist = definition.incidence - definition.washout * eta ^ definition.washoutExp;
        // alignment line follows the sweep curve; pivot shifted so the root pivot stays at the origin
        // alignment line follows the sweep curve on the chord before tip rounding; the rounding's
        // shrink is centred on the mid-chord so the leading and trailing corners both round, and
        // the root tail is all aft (build 146 / 145)
        const capF = capPlanFactor(pl, eta);
        const chordBase = (chord - tailAdd) / capF;
        const alignShift = (pivotFrac - definition.planformAlign / 100) * (chordBase - c0) + pivotFrac * tailAdd + (0.5 - pivotFrac) * (chordBase - (chord - tailAdd));
        const xOff = definition.sweepTip * eta ^ definition.sweepExp + alignShift;
        const fDrop = dropShape(dl, eta);
        var zOff = -definition.tipDrop * fDrop + h * tan(definition.rootDihedral) * (eta - fDrop);
        var yPos = y;
        var phi = 0 * degree;                      // section plane rotation about X (0 = vertical plane)
        if (wingletOn && y > wS0)
        {
            const wp = wingletPath(y, wS0, wZ0, wPhi0, wSign, wAng, wR);
            yPos = wp.y;
            zOff = wp.z;
            phi = wp.phi;
        }

        // leading-edge bumps: the LE moves forward by the bump, the TE stays, thickness in mm stays
        const bump = bumpOffset(pl, eta, h);
        const chordB = chord + bump;
        thick = thick * chord / chordB;
        const xOffB = xOff - (1 - pivotFrac) * bump;
        const teLocal = min(definition.teThickness, 0.03 * chordB);
        const section = buildSectionAt(secDef, thick, teLocal / chordB, definition.pointsPerSurface, sectionWeightAt(secDef, eta));
        const pts = placeSection(section, chordB, pivotFrac, cos(twist), sin(twist));
        // as built: with the sketch plane's own offset. A root tail places the root pivotFrac x tail
        // aft (the tail is all behind the TE), and points without that shift put a 20 mm tail's stab
        // pad 5 mm ahead of the part (build 234); the wing's root offset is always 0
        if (i == 0)
            for (var q in pts)
                rootPts = append(rootPts, q + vector(xOffB, zOff));

        const sketchId = id + ("section" ~ i);
        var sketch = newSketchOnPlane(context, sketchId, {
                    "sketchPlane" : plane(base + vector(xOffB, yPos, zOff), vector(0, -cos(phi), -sin(phi)), X_DIRECTION)
                });
        skFitSpline(sketch, "surface", { "points" : pts });
        skLineSegment(sketch, "trailingEdge", { "start" : pts[0], "end" : pts[size(pts) - 1] });
        skSolve(sketch);

        profiles = append(profiles, qSketchRegion(sketchId));
        sketchBodies = append(sketchBodies, qCreatedBy(sketchId, EntityType.BODY));
    }

    // winglet height above the bend start and the projected span, for the notice and the analysis
    var wHeight = 0 * meter;
    var spanProj = span;
    var wAreaProj = 0 * meter * meter;             // projected area of one winglet
    if (wingletOn)
    {
        const tipP = wingletPath(h, wS0, wZ0, wPhi0, wSign, wAng, wR);
        wHeight = abs(tipP.z - wZ0);
        spanProj = 2 * tipP.y;
        const NW = 40;
        for (var q = 0; q < NW; q += 1)
        {
            const sm = wS0 + (h - wS0) * (q + 0.5) / NW;
            const wp = wingletPath(sm, wS0, wZ0, wPhi0, wSign, wAng, wR);
            wAreaProj += c0 * chordFactor(pl, sm / h) * cos(wp.phi) * (h - wS0) / NW;
        }
    }

    // ================= solid =================
    opLoft(context, id + "loft", { "profileSubqueries" : profiles });
    opDeleteBodies(context, id + "deleteSections", { "entities" : qUnion(sketchBodies) });

    if (definition.mirror)
    {
        opPattern(context, id + "mirror", {
                    "entities" : qCreatedBy(id + "loft", EntityType.BODY),
                    "transforms" : [mirrorAcross(plane(WORLD_ORIGIN, Y_DIRECTION))],
                    "instanceNames" : ["left"]
                });
        opBoolean(context, id + "join", {
                    "tools" : qUnion([qCreatedBy(id + "loft", EntityType.BODY), qCreatedBy(id + "mirror", EntityType.BODY)]),
                    "operationType" : BooleanOperationType.UNION
                });
    }

    // ================= analysis model (SI numbers) =================
    const solidQ = qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID);
    var wetted = evArea(context, { "entities" : qOwnedByBody(solidQ, EntityType.FACE) });
    if (!definition.mirror)
        wetted = wetted * 2;
    const thinAero = sectionAlpha0Cm0(definition, definition.rootThickness / 100);
    const alpha0Thin = thinAero[0];
    const cm0Thin = thinAero[1];
    var pd = resolvePolar(definition); // undefined for Analytic
    const polarOn = pd != undefined;
    if (polarOn && definition.invertSection == true)
    {
        // section upside down: zero-lift angle, moment and the drag-bucket centre change sign
        pd.alpha0Deg = -pd.alpha0Deg;
        pd.cm0 = -pd.cm0;
        pd.clcd1 = -pd.clcd1;
        pd.clcd2 = -pd.clcd2;
    }
    const alpha0 = polarOn ? pd.alpha0Deg * degree : alpha0Thin;
    const cm0Root = polarOn ? pd.cm0 : cm0Thin;
    const claSection = polarOn ? pd.cla : 2 * PI * 0.95;
    // tip section (build 166): its own zero-lift angle and moment, its own built-in polar when the
    // root has one, and the share of the area it covers (for blending the drag bucket and cm0)
    var alpha0Tip = alpha0;
    var cm0Tip = cm0Root;
    var pdTip = pd;
    var tipAreaFrac = 0;
    if (secDef.tipOn)
    {
        const tipAero = sectionAlpha0Cm0(tipSectionDef(secDef), definition.tipThickness / 100);
        alpha0Tip = tipAero[0];
        cm0Tip = tipAero[1];
        if (definition.polarSource == PolarSource.BUILTIN)
        {
            pdTip = builtinPolar(secDef.tipProfile, secDef.tipCamber / 100, secDef.tipCamberPos / 100, definition.tipThickness / 100);
            if (pdTip == undefined)
                throw regenError("Built-in polar data exists only for NACA 4-digit, E817, E818, NACA 63-412, Clark Y, MRC-16, MH 18 and H105 - choose one of those as Tip profile, or set Section data to Polar summary or Analytic", ["tipProfile"]);
            if (definition.invertSection == true)
            {
                pdTip.alpha0Deg = -pdTip.alpha0Deg;
                pdTip.cm0 = -pdTip.cm0;
                pdTip.clcd1 = -pdTip.clcd1;
                pdTip.clcd2 = -pdTip.clcd2;
            }
        }
        if (polarOn)
        {
            alpha0Tip = pdTip.alpha0Deg * degree;
            cm0Tip = pdTip.cm0;
        }
        var num = 0;
        var den = 0;
        for (var i = 0; i <= 200; i += 1)
        {
            const e = i / 200;
            const wS = (i == 0 || i == 200) ? 1 : ((i % 2 == 1) ? 4 : 2);
            const g = chordFactor(pl, e);
            num += wS * g * sectionWeightAt(secDef, e);
            den += wS * g;
        }
        tipAreaFrac = den > 0 ? num / den : 0;
    }
    const cm0 = cm0Root * (1 - tipAreaFrac) + cm0Tip * tipAreaFrac;
    const fT = tipAreaFrac;
    const model = {
            "span" : span / meter, "stations" : definition.stations, "c0" : c0 / meter, "shape" : shape, "ratio" : ratio, "n" : n, "brk" : brk, "mid" : mid, "blend" : blend, "capEta" : pl.capEta, "planRound" : planRound ? 1 : 0, "tail" : tail, "tailEta" : tailEta, "tipRaised" : tipRaised ? 1 : 0,
            "area" : areaProj / (meter * meter), "mac" : mac / meter,
            "incidence" : definition.incidence / radian, "washout" : definition.washout / radian, "washoutExp" : definition.washoutExp,
            "alpha0" : alpha0 / radian, "cm0" : cm0, "claSection" : claSection,
            "tipOn" : secDef.tipOn ? 1 : 0, "tipProfileName" : enumStr_profile(secDef.tipProfile), "tipCamber" : secDef.tipCamber, "tipCamberPos" : secDef.tipCamberPos, "blendFrom" : secDef.blendFrom,
            "alpha0Tip" : alpha0Tip / radian, "cm0Tip" : cm0Tip, "tipAreaFrac" : fT,
            "polarClmax1Tip" : polarOn ? pdTip.clmax1 : 0, "polarClmax2Tip" : polarOn ? pdTip.clmax2 : 0,
            "rootT" : definition.rootThickness / 100, "tipT" : definition.tipThickness / 100, "thicknessExp" : definition.thicknessExp,
            "sweepTip" : definition.sweepTip / meter, "sweepExp" : definition.sweepExp, "align" : definition.planformAlign / 100,
            "pivotFrac" : pivotFrac, "baseX" : base[0] / meter, "baseZ" : base[2] / meter,
            "profileName" : enumStr_profile(definition.profile), "camber" : definition.camber, "camberPos" : definition.camberPos, "mirror" : definition.mirror ? 1 : 0,
            "inverted" : definition.invertSection == true ? 1 : 0, "teThick" : definition.teThickness / meter,
            "wetted" : wetted / (meter * meter),
            "capOn" : capOn ? 1 : 0, "capLength" : capLen / meter, "capEnd" : definition.capEnd / 100, "capEndT" : capEndT,
            "tipDrop" : definition.tipDrop / meter, "dropExp" : definition.dropExp, "dropFrom" : dropFrom, "dropTo" : dropTo, "dropSmooth" : dl.dropSmooth, "rootDihedral" : definition.rootDihedral / radian,
            "wingletOn" : wingletOn ? 1 : 0, "wingletSign" : wSign, "wingletEta" : wEta, "wingletAngle" : wAng / radian, "wingletR" : wR / meter,
            "bumpOn" : bumpOn ? 1 : 0, "bumpAmp" : bumpKeys.bumpAmp, "bumpPitch" : bumpKeys.bumpPitch, "bumpFrom" : bumpKeys.bumpFrom, "bumpTo" : bumpKeys.bumpTo,
            "wingletHeight" : wHeight / meter, "spanProj" : spanProj / meter,
            "polarOn" : polarOn ? 1 : 0,
            "polarRe1" : (polarOn ? pd.re1M : 0) * 1e6, "polarClmax1" : polarOn ? pd.clmax1 : 0,
            "polarCdmin1" : polarOn ? pd.cdmin1 * (1 - fT) + pdTip.cdmin1 * fT : 0, "polarClcd1" : polarOn ? pd.clcd1 * (1 - fT) + pdTip.clcd1 * fT : 0, "polarK1" : polarOn ? pd.k1 * (1 - fT) + pdTip.k1 * fT : 0,
            "polarRe2" : (polarOn ? pd.re2M : 0) * 1e6, "polarClmax2" : polarOn ? pd.clmax2 : 0,
            "polarCdmin2" : polarOn ? pd.cdmin2 * (1 - fT) + pdTip.cdmin2 * fT : 0, "polarClcd2" : polarOn ? pd.clcd2 * (1 - fT) + pdTip.clcd2 * fT : 0, "polarK2" : polarOn ? pd.k2 * (1 - fT) + pdTip.k2 * fT : 0
        };

    return {
            "span" : span, "rootChord" : c0 * (1 + tail), "tipChord" : tipChord, "ratioUsed" : ratio, "tipRaised" : tipRaised, "capEndRaised" : capEndRaised, "capEndT" : capEndT,
            "areaProj" : areaProj, "areaDev" : areaDev, "mac" : mac, "aspect" : aspect,
            "wingletOn" : wingletOn, "wingletHeight" : wHeight, "spanProj" : spanProj, "wingletAreaProj" : wAreaProj, "wingletRClamped" : wRClamped, "wingletR" : wR,
            "rootThickness" : definition.rootThickness, "tipThickness" : definition.tipThickness,
            "incidence" : definition.incidence, "alpha0" : alpha0, "model" : model,
            "rootPts" : rootPts   // root section outline (X, Z) relative to the root pivot, as built
        };
}

/** One-line planform summary for the feature notice. */
function planformSummary(definition is map, m is map) returns string
{
    const cm2 = centimeter * centimeter;
    var msg = "Area " ~ toString(round(m.areaProj / cm2)) ~ " cm² projected";
    if (abs(definition.tipDrop) > 0 * meter || abs(definition.rootDihedral) > 0 * degree)
        msg = msg ~ " (" ~ toString(round(m.areaDev / cm2)) ~ " developed)";
    msg = msg ~ " · span " ~ toString(round(m.span / millimeter)) ~ " mm" ~
        " · AR " ~ toString(round(m.aspect * 100) / 100) ~
        " · root " ~ toString(round(m.rootChord / millimeter)) ~ " mm" ~
        (definition.chordShape == ChordShape.SUPERELLIPSE ? " · end " : " · tip ") ~ toString(round(m.tipChord / millimeter)) ~ " mm" ~
        " · MAC " ~ toString(round(m.mac / millimeter)) ~ " mm";
    if (m.tipRaised)
        msg = msg ~ " · " ~ (definition.chordShape == ChordShape.SUPERELLIPSE ? "End ratio" : "Tip ratio") ~ " raised to " ~ fmt(m.ratioUsed, 3) ~
            " for a " ~ fmt(definition.minTip / millimeter, 1) ~ " mm tip" ~ (m.ratioUsed >= 0.95 ? " (at the 0.95 limit - still thinner than Min tip mm)" : "");
    if (m.capEndRaised == true)
        msg = msg ~ " · Cap end raised to " ~ fmt(m.capEndT * 100, 0) ~ " % for a 0.5 mm cap end";
    if (m.wingletOn)
        msg = msg ~ " | winglets " ~ (definition.winglet == Winglet.UP ? "up" : "down") ~ " " ~ fmt(definition.wingletArea, 1) ~ " cm² each (" ~
            fmt(m.wingletAreaProj / cm2, 1) ~ " projected), " ~ toString(round(m.wingletHeight / millimeter)) ~ " mm high at " ~ fmt(definition.wingletAngle / degree, 0) ~
            "°, projected span " ~ toString(round(m.spanProj / millimeter)) ~ " mm" ~
            (m.wingletRClamped ? " - bend radius reduced to " ~ fmt(m.wingletR / millimeter, 0) ~ " mm so the arc fits the winglet" : "");
    if (definition.tipProfile != undefined && definition.tipProfile != TipProfile.SAME)
        msg = msg ~ " · tip section " ~ enumStr_tipProfile(definition.tipProfile) ~ (definition.tipProfile == TipProfile.NACA4 ? " " ~ fmt(definition.tipCamber, 1) ~ "% camber" : "") ~
            " from " ~ fmt(definition.blendFrom, 0) ~ "% span";
    if (!definition.mirror)
        msg = msg ~ " (full-span values, half built)";
    return msg;
}

/**
 * Zero-lift angle of a NACA 4-digit mean line from thin-aerofoil theory:
 * alpha0 = -(1/pi) * integral over theta of dyc/dx (cos(theta) - 1).
 * Negative for positive camber (e.g. about -2.1 deg for a 2412).
 */
function zeroLiftAngle(m is number, p is number) returns ValueWithUnits
{
    if (m == 0)
        return 0 * degree;
    const N = 400;
    var sum = 0;
    for (var i = 1; i <= N; i += 1)
    {
        const th = PI * (i - 0.5) / N;
        const c = cos(th * radian);
        const x = 0.5 * (1 - c);
        const dyc = x < p ? 2 * m / p ^ 2 * (p - x) : 2 * m / (1 - p) ^ 2 * (p - x);
        sum += dyc * (c - 1);
    }
    return -(sum * PI / N) / PI * radian;
}


function pivotFraction(pivot is FoilPivot) returns number
{
    if (pivot == FoilPivot.LEADING_EDGE)
        return 0;
    if (pivot == FoilPivot.TRAILING_EDGE)
        return 1;
    return 0.25;
}

/**
 * Normalised chord g(eta), eta = 2y/b in [0, 1], g(0) = 1, from a planform law map pl (the same
 * keys live in the published model maps, so a model map can be passed directly):
 *   shape (ChordShape), ratio (end/tip ratio), n (superellipse exponent),
 *   brk, mid, blend (double taper: break eta, chord ratio at the break, blend half-width in eta),
 *   capEta, capEnd (plan-view tip rounding: chord shrinks along a quarter-ellipse from eta = capEta
 *   to capEnd x the cap-start chord at eta = 1; capEta = 1 means none),
 *   tail, tailEta (root tail: the chord grows by tail x c0 at the centreline, fading to nothing at
 *   eta = tailEta with a smoothstep, flat at both ends; tail = 0 means none). g(0) = 1 + tail, so
 *   c0 stays the base root chord and the tail is all trailing-edge extension (see tailFactor).
 * Superellipse is truncated at eta = 1 where g = ratio. Double taper: 1 -> mid over [0, brk], then
 * mid -> ratio over [brk, 1]; within blend of the break the two lines are joined by a quadratic
 * Bezier with its control point at the corner, so it is tangent to both. Missing keys (an older
 * model map) default to no blend and no plan rounding.
 */
function chordFactor(pl is map, eta is number) returns number
{
    const ratio = pl.ratio;
    var g;
    if (pl.shape == ChordShape.LINEAR)
        g = 1 - (1 - ratio) * eta;
    else if (pl.shape == ChordShape.DOUBLE)
    {
        const brk = pl.brk;
        const mid = pl.mid;
        const d = pl.blend == undefined ? 0 : pl.blend;
        if (d > 0 && abs(eta - brk) < d)
        {
            const t = (eta - (brk - d)) / (2 * d);
            const p0 = 1 - (1 - mid) * (brk - d) / brk;
            const p2 = mid - (mid - ratio) * d / (1 - brk);
            g = (1 - t) * (1 - t) * p0 + 2 * t * (1 - t) * mid + t * t * p2;
        }
        else
            g = eta < brk ? 1 - (1 - mid) * eta / brk : mid - (mid - ratio) * (eta - brk) / (1 - brk);
    }
    else
    {
        const v = 1 - (seScale(ratio, pl.n) * eta) ^ pl.n;
        g = v <= 0 ? 0 : v ^ (1 / pl.n);
    }
    return g * capPlanFactor(pl, eta) + tailFactor(pl, eta);
}

/**
 * Plan-view tip rounding multiplier: 1 up to eta = capEta, then a quarter-ellipse down to capEnd
 * at eta = 1. Kept separate so the section placement can centre the shrink on the mid-chord
 * (both corners round) instead of on the alignment line (build 146).
 */
function capPlanFactor(pl is map, eta is number) returns number
{
    const capEta = pl.capEta == undefined ? 1 : pl.capEta;
    if (capEta >= 1 || eta <= capEta)
        return 1;
    const u = min((eta - capEta) / (1 - capEta), 1);
    return pl.capEnd + (1 - pl.capEnd) * sqrt(max(1 - u * u, 0));
}

/**
 * Leading-edge bump (tubercle) offset at eta: how far the leading edge is forward of the smooth
 * outline, up to +/- Bump height / 2, sinusoidal along the span with Bump pitch between Bumps from
 * and Bumps to, fading in and out over half a pitch at each end. The trailing edge is unchanged, so
 * the local chord grows by this. Zero when off. pl / model map keys: bumpOn (true or 1), bumpAmp and
 * bumpPitch in metres (numbers), bumpFrom and bumpTo as fractions of the half span h.
 */
function bumpOffset(pl is map, eta is number, h is ValueWithUnits) returns ValueWithUnits
{
    if (pl.bumpOn != true && pl.bumpOn != 1)
        return 0 * meter;
    const y = eta * h;
    const y0 = pl.bumpFrom * h;
    const y1 = pl.bumpTo * h;
    const lam = pl.bumpPitch * meter;
    if (y < y0 || y > y1 || lam <= 0 * meter)
        return 0 * meter;
    const ramp = lam / 2;
    var w = 1;
    if (y - y0 < ramp)
        w = 0.5 * (1 - cos((PI * (y - y0) / ramp) * radian));
    if (y1 - y < ramp)
        w = min(w, 0.5 * (1 - cos((PI * (y1 - y) / ramp) * radian)));
    return 0.5 * pl.bumpAmp * meter * cos((2 * PI * (y - y0) / lam) * radian) * w;
}

/** The root tail's share of g(eta): tail x (2u^3 - 3u^2 + 1), u = eta / tailEta, zero beyond it. */
function tailFactor(pl is map, eta is number) returns number
{
    if (pl.tail == undefined || pl.tail <= 0 || eta >= pl.tailEta)
        return 0;
    const u = eta / pl.tailEta;
    return pl.tail * (2 * u * u * u - 3 * u * u + 1);
}

/**
 * Spanwise shear force (N) at eta from a Foil performance loads map: the slope of the published
 * moment (21 stations) at its 20 interval midpoints, interpolated between them, the half lift at the
 * root and nothing at the tip. For the mold's core shear check (build 226).
 */
function moldShearAt(loads is map, h is number, eta is number) returns number
{
    const dy = h / 20;
    var e0 = 0;
    var v0 = loads.halfLift != undefined ? loads.halfLift : (loads.M[0] - loads.M[1]) / dy;
    for (var j = 0; j <= 20; j += 1)
    {
        const e1 = j < 20 ? (j + 0.5) / 20 : 1;
        const v1 = j < 20 ? (loads.M[j] - loads.M[j + 1]) / dy : 0;
        if (eta <= e1)
            return v0 + (v1 - v0) * (eta - e0) / max(e1 - e0, 1e-9);
        e0 = e1;
        v0 = v1;
    }
    return 0;
}

/** Scale so the truncated superellipse (1 - (s*eta)^n)^(1/n) equals ratio at eta = 1. */
function seScale(ratio is number, n is number) returns number
{
    return (1 - ratio ^ n) ^ (1 / n);
}

/**
 * Drop shape f(eta) for the tip drop, from a map d carrying dropExp, dropFrom (b), dropTo (t) and
 * dropSmooth (1 = S-curve) - the planform law map, a published model map or the buildFoil literal.
 * f = 0 out to b, 1 from t, and between them u = (eta - b)/(t - b) as u^e (power law) or the
 * smoothstep 3u^2 - 2u^3 (S-curve, flat at both ends). b = 0, t = 1, power e is the original
 * eta^e law. The gull term uses eta - f(eta), so the root dihedral line runs straight to the
 * break, then fades. Missing keys (an older model map) mean the original law.
 */
function dropShape(d is map, eta is number) returns number
{
    const b = d.dropFrom == undefined ? 0 : d.dropFrom;
    const t = d.dropTo == undefined ? 1 : d.dropTo;
    if (eta <= b)
        return 0;
    if (eta >= t)
        return 1;
    const u = (eta - b) / (t - b);
    if (d.dropSmooth == 1)
        return u * u * (3 - 2 * u);
    return u ^ (d.dropExp == undefined ? 2 : d.dropExp);
}

/** d/deta of dropShape. */
function dropSlope(d is map, eta is number) returns number
{
    const b = d.dropFrom == undefined ? 0 : d.dropFrom;
    const t = d.dropTo == undefined ? 1 : d.dropTo;
    if (eta <= b || eta >= t)
        return 0;
    const u = (eta - b) / (t - b);
    if (d.dropSmooth == 1)
        return 6 * u * (1 - u) / (t - b);
    const e = d.dropExp == undefined ? 2 : d.dropExp;
    if (e == 1)
        return 1 / (t - b);
    return e * u ^ (e - 1) / (t - b);
}

/** The span line's height at eta from the drop law and the gull dihedral (m, a number), as buildFoil places each station's section. */
function moldDropZ(m is map, eta is number) returns number
{
    const f = dropShape(m, eta);
    return -m.tipDrop * f + m.span / 2 * tan(m.rootDihedral * radian) * (eta - f);
}

/**
 * The mold's parting stations refined for the span line's drop (build 235). The parting is ruled
 * between its stations while the drop law curves, so a segment whose chord strays more than 0.15 mm
 * from the law (seven samples) is halved, pass after pass (six at most), but never into pieces under 3
 * mm; segments beyond a winglet's bend start are left alone (its own stations follow the bend). A
 * surface without drop or dihedral comes back unchanged. etas: the parting stations; returned sorted.
 */
function moldDropStations(m is map, etas is array) returns array
{
    var es = sort(etas, function(a, b) { return a - b; });
    if ((m.tipDrop == undefined || abs(m.tipDrop) < 1e-6) && (m.rootDihedral == undefined || abs(m.rootDihedral) < 1e-6))
        return es;
    const h = m.span / 2;
    const etaMax = m.wingletOn == 1 ? m.wingletEta : 1;
    for (var pass = 0; pass < 6; pass += 1)
    {
        var out = [es[0]];
        var added = false;
        for (var i = 0; i + 1 < size(es); i += 1)
        {
            const a = es[i];
            const b = es[i + 1];
            if ((b - a) * h > 0.006 && b <= etaMax + 1e-9)
            {
                const za = moldDropZ(m, a);
                const zb = moldDropZ(m, b);
                var dev = 0;
                for (var k = 1; k < 8; k += 1)
                    dev = max(dev, abs(moldDropZ(m, a + (b - a) * k / 8) - (za + (zb - za) * k / 8)));
                if (dev > 0.00015)
                {
                    out = append(out, 0.5 * (a + b));
                    added = true;
                }
            }
            out = append(out, b);
        }
        es = out;
        if (!added)
            break;
    }
    return es;
}

/**
 * The foil's loft stations as etas in [0, 1], from a map with the keys the model maps carry (span in
 * metres, stations, shape, ratio, n, brk, blend, tail, tailEta, bumpOn/Pitch/From/To, tipOn,
 * blendFrom, wingletOn/Eta/R/Angle, capOn, capLength, and from build 235 tipDrop, rootDihedral and the
 * drop law's dropFrom / dropTo / dropSmooth / dropExp). buildFoil lofts through exactly these. The
 * mold's parting has its own list (build 171 reverted 169's merge of the two); it is refined for the
 * drop law separately (moldDropStations, build 235). Sorted, deduped at 0.3 mm, first 0 and last 1.
 */
function foilStationEtas(m is map) returns array
{
    const h = m.span / 2;
    const nMain = m.stations;
    var es = [];
    if (m.shape == ChordShape.SUPERELLIPSE)
    {
        // superellipse parametric angle: eta = sin(phi)^(2/n) / sc; equal phi steps put stations
        // evenly around the curved outline
        const sc = seScale(m.ratio, m.n);
        const phiEnd = asin(min(sc ^ (m.n / 2), 1));
        for (var i = 0; i < nMain; i += 1)
        {
            const phi = phiEnd * i / (nMain - 1);
            es = append(es, min(sin(phi) ^ (2 / m.n) / sc, 1));
        }
    }
    else
    {
        for (var i = 0; i < nMain; i += 1)
            es = append(es, sin((PI / 2 * i / (nMain - 1)) * radian));
        if (m.shape == ChordShape.DOUBLE)
        {
            // through the break: sharp -> at it and just either side; blended -> five across the blend
            const d = m.blend > 0 ? m.blend : 0.03;
            for (var e in [m.brk - d, m.brk - d / 2, m.brk, m.brk + d / 2, m.brk + d])
                es = append(es, min(max(e, 0), 1));
        }
    }
    if (m.tail != undefined && m.tail > 0)
        for (var e in [m.tailEta / 3, 2 * m.tailEta / 3, m.tailEta])
            es = append(es, min(e, 1));
    if (m.bumpOn == 1)
    {
        // six stations per pitch through the bumps
        var yb = m.bumpFrom * h;
        const yEnd = min(m.bumpTo * h, h);
        while (yb <= yEnd)
        {
            es = append(es, yb / h);
            yb += m.bumpPitch / 6;
        }
    }
    if (m.tipOn == 1)
        for (var k = 0; k <= 6; k += 1)
            es = append(es, m.blendFrom + (1 - m.blendFrom) * k / 6);   // six across the section blend
    if (m.wingletOn == 1)
    {
        // the bend start and four around the arc
        const arcLen = m.wingletR * m.wingletAngle;
        for (var k = 0; k <= 4; k += 1)
            es = append(es, min((m.wingletEta * h + arcLen * k / 4) / h, 1));
    }
    if (m.capOn == 1 && m.capLength > 0)
    {
        const capStart = h - m.capLength;
        for (var j = 0; j <= 4; j += 1)
            es = append(es, (capStart + m.capLength * sin((PI / 2 * j / 4) * radian)) / h);
    }
    // the span line's drop and gull (build 235): stations through the drop region, so the loft follows
    // dropShape instead of bridging it in one span. A superellipse n 3 with 9 stations put the first
    // station after the root near eta 0.34, and the loft drooped almost linearly from the root, up to
    // 1.6 mm below a 50 mm S-curve's law by y 60, while the mold's parting follows the law: the lower
    // half lapped over the thin trailing edge (user's studio). Thirteen evenly through [Drop from, Drop
    // to], and two near each end of the drop, where its curvature jumps; each only where no station
    // above sits within 1.5 mm, so no sliver-thin loft span is made
    const hasDrop = (m.tipDrop != undefined && abs(m.tipDrop) > 1e-6) || (m.rootDihedral != undefined && abs(m.rootDihedral) > 1e-6);
    if (hasDrop)
    {
        const db = m.dropFrom == undefined ? 0 : m.dropFrom;
        const dt = m.dropTo == undefined ? 1 : m.dropTo;
        var dropEs = [db + 0.02, db + 0.05, dt - 0.05, dt - 0.02];
        if (dt < 1)
            dropEs = concatenateArrays([dropEs, [dt + 0.02, dt + 0.05]]);
        for (var k = 0; k <= 12; k += 1)
            dropEs = append(dropEs, db + (dt - db) * k / 12);
        for (var e in dropEs)
        {
            const ec = min(max(e, 0), 1);
            var near = false;
            for (var x in es)
            {
                if (abs(x - ec) < 0.0015 / h)
                {
                    near = true;
                    break;
                }
            }
            if (!near)
                es = append(es, ec);
        }
    }
    es = sort(es, function(a, b) { return a - b; });
    var out = [];
    for (var e in es)
    {
        const ec = min(max(e, 0), 1);
        if (size(out) == 0 || ec - out[size(out) - 1] > 0.0003 / h)
            out = append(out, ec);
    }
    out[0] = 0;
    out[size(out) - 1] = 1;
    return out;
}

/** Integral of g from eta0 to 1 (Simpson, 200 intervals): the normalised area outboard of eta0. */
function shapeIntegralFrom(pl is map, eta0 is number) returns number
{
    const N = 200;
    var sum = 0;
    for (var i = 0; i <= N; i += 1)
    {
        const w = (i == 0 || i == N) ? 1 : ((i % 2 == 1) ? 4 : 2);
        sum += w * chordFactor(pl, eta0 + (1 - eta0) * i / N);
    }
    return sum * (1 - eta0) / (3 * N);
}

/**
 * Winglet path: position (y, z) and direction angle phi of the span line at developed distance s
 * from the root, for s beyond the bend start s0. The inboard drop law ends at (s0, z0) with slope
 * angle phi0; the bend turns by sign x ang over an arc of length r x ang, then runs straight.
 */
function wingletPath(s is ValueWithUnits, s0 is ValueWithUnits, z0 is ValueWithUnits, phi0 is ValueWithUnits, sign is number, ang is ValueWithUnits, r is ValueWithUnits) returns map
{
    const ds = s - s0;
    const arcLen = r * (ang / radian);
    var yy = s0;
    var zz = z0;
    const N = 24;
    for (var q = 0; q < N; q += 1)
    {
        const sm = ds * (q + 0.5) / N;
        const ph = phi0 + sign * ang * min(sm / arcLen, 1);
        yy += ds / N * cos(ph);
        zz += ds / N * sin(ph);
    }
    return { "y" : yy, "z" : zz, "phi" : phi0 + sign * ang * min(ds / arcLen, 1) };
}

/**
 * Winglet frame at developed station eta from a published model map (foilWingModel / foilStabModel):
 * origin y and z of the span line (SI numbers x meter), the section-plane tilt phi, and whether the
 * station is in the winglet. eta may exceed 1: the path continues straight beyond the tip, which the
 * mold uses for its beyond-tip parting station. Inboard of the bend (or with no winglet) it returns
 * the drop law's y = eta h and z, phi = 0, so callers can use it for every station.
 */
function wingletFrame(m is map, eta is number) returns map
{
    const h = m.span / 2 * meter;
    const on = m.wingletOn == 1 && eta > m.wingletEta;
    if (!on)
    {
        const f = dropShape(m, eta);
        return { "on" : false, "y" : h * eta, "z" : -m.tipDrop * meter * f + h * tan(m.rootDihedral * radian) * (eta - f), "phi" : 0 * degree };
    }
    const wEta = m.wingletEta;
    const ps0 = dropSlope(m, wEta);
    const f0 = dropShape(m, wEta);
    const z0 = -m.tipDrop * meter * f0 + h * tan(m.rootDihedral * radian) * (wEta - f0);
    const phi0 = atan((-m.tipDrop * meter * ps0 + h * tan(m.rootDihedral * radian) * (1 - ps0)) / h);
    const wp = wingletPath(eta * h, wEta * h, z0, phi0, m.wingletSign, m.wingletAngle * radian, m.wingletR * meter);
    return { "on" : true, "y" : wp.y, "z" : wp.z, "phi" : wp.phi };
}

/**
 * Roll feel of one surface (build 230): Cl_beta per radian from a horseshoe vortex lattice on the
 * surface's own span line (wingletFrame: drop, gull, winglet) and quarter-chord line (sweep, align),
 * 12 panels a side, cosine spaced, at 4 deg and sideslip +-2 deg; + = rolls into the sideslip, as
 * anhedral does. deg is the straight anhedral from the root that gives the same Cl_beta on the same
 * planform (flat and 6 deg references, linear to 0.1 deg over 0-8 deg). The surface alone: the mast's
 * side force dominates the whole foil's roll, so this compares shapes rather than predicting the feel.
 * Python twin: reference_checks.roll_response.
 */
function rollResponse(m is map) returns map
{
    const n = 12;
    const h = m.span / 2;
    const t6 = tan(6 * degree);
    var own = [];
    var flat = [];
    var ref = [];
    for (var i = 0; i <= n; i += 1)
    {
        const e = 0.5 * (1 - cos((PI * i / n) * radian));
        const f = wingletFrame(m, e);
        own = append(own, [e, f.y / meter, f.z / meter]);
        flat = append(flat, [e, e * h, 0]);
        ref = append(ref, [e, e * h, -e * h * t6]);
    }
    const clb = vlmRollDerivative(m, own);
    const c0 = vlmRollDerivative(m, flat);
    const c6 = vlmRollDerivative(m, ref);
    return { "clb" : clb, "deg" : abs(c6 - c0) > 1e-9 ? 6 * (clb - c0) / (c6 - c0) : 0 };
}

/** Cl_beta of the span line pts = [[eta, y, z], ...] root to tip (m), mirrored to the full span. */
function vlmRollDerivative(m is map, pts is array) returns number
{
    var full = [];
    for (var i = size(pts) - 1; i >= 0; i -= 1)
        full = append(full, [pts[i][0], -pts[i][1], pts[i][2]]);
    for (var i = 1; i < size(pts); i += 1)
        full = append(full, pts[i]);
    var P = [];
    for (var q in full)
    {
        const c = chordAt(m, q[0]);
        P = append(P, vector(m.sweepTip * q[0] ^ m.sweepExp + (m.pivotFrac - m.align) * (c - m.c0) + (0.25 - m.pivotFrac) * c, q[1], q[2]));
    }
    const n = size(P) - 1;
    var ctrl = [];
    var nrm = [];
    var mid = [];
    var bound = [];
    for (var i = 0; i < n; i += 1)
    {
        const c = chordAt(m, 0.5 * (full[i][0] + full[i + 1][0]));
        const t = P[i + 1] - P[i];
        const mp = (P[i] + P[i + 1]) / 2;
        mid = append(mid, mp);
        ctrl = append(ctrl, mp + vector(c / 2, 0, 0));   // 3/4 chord
        nrm = append(nrm, normalize(cross(vector(1, 0, 0), t)));
        bound = append(bound, t);
    }
    var A = [];
    for (var i = 0; i < n; i += 1)
    {
        var row = [];
        for (var j = 0; j < n; j += 1)
            row = append(row, dot(vlmSeg(ctrl[i], P[j], P[j + 1]) + vlmLeg(ctrl[i], P[j]) - vlmLeg(ctrl[i], P[j + 1]), nrm[i]));
        A = append(A, row);
    }
    const al = 4 * degree;
    const bt = 2 * degree;
    var cl = [0, 0];
    for (var k = 0; k < 2; k += 1)
    {
        const b = k == 0 ? bt : -bt;
        const V = vector(cos(al) * cos(b), sin(b), sin(al));
        var rhs = [];
        for (var i = 0; i < n; i += 1)
            rhs = append(rhs, -dot(V, nrm[i]));
        const G = solveLinear(A, rhs);
        var mx = 0;
        for (var i = 0; i < n; i += 1)
        {
            const F = cross(V, bound[i]);
            mx += G[i] * (mid[i][1] * F[2] - mid[i][2] * F[1]);
        }
        cl[k] = 2 * mx / (m.area * 2 * P[n][1]);
    }
    return (cl[0] - cl[1]) / (2 * (bt / radian));
}

/** Biot-Savart velocity at p of a unit vortex segment a -> b. */
function vlmSeg(p is Vector, a is Vector, b is Vector) returns Vector
{
    const r1 = p - a;
    const r2 = p - b;
    const cr = cross(r1, r2);
    const c2 = dot(cr, cr);
    if (c2 < 1e-14)
        return vector(0, 0, 0);
    return cr * (dot(b - a, r1 / norm(r1) - r2 / norm(r2)) / (4 * PI * c2));
}

/** Velocity at p of a unit semi-infinite vortex coming in from +x (downstream) to a. */
function vlmLeg(p is Vector, a is Vector) returns Vector
{
    const r = p - a;
    const d2 = r[1] * r[1] + r[2] * r[2];
    if (d2 < 1e-14)
        return vector(0, 0, 0);
    const k = (1 + r[0] / norm(r)) / (4 * PI * d2);
    return vector(0, k * r[2], -k * r[1]);
}

/** Notice text for rollResponse. */
function rollNote(r is map) returns string
{
    const kind = abs(r.deg) < 0.05 ? "a flat surface" : fmt(abs(r.deg), 1) ~ "° of " ~ (r.deg > 0 ? "anhedral" : "dihedral");
    return " | rolls like " ~ kind ~ " (Cl_beta " ~ (r.clb >= 0 ? "+" : "") ~ fmt(r.clb, 3) ~ "/rad, this surface alone)";
}

/**
 * Simpson integration over η in [0, 1].
 * kind 0: integral of g   kind 1: integral of g^2   kind 2: integral of g * sqrt(1 + (dz/dy)^2)  (developed area)
 * z(eta) = -drop * eta^e + h * td * (eta - eta^e);  k = drop / h,  td = tan(root dihedral).
 */
function shapeIntegral(pl is map, kind is number, k is number, td is number) returns number
{
    const N = 400;
    var sum = 0;
    for (var i = 0; i <= N; i += 1)
    {
        const eta = i / N;
        const w = (i == 0 || i == N) ? 1 : ((i % 2 == 1) ? 4 : 2);
        const g = chordFactor(pl, eta);
        var v = g;
        if (kind == 1)
            v = g * g;
        else if (kind == 2)
        {
            const ps = dropSlope(pl, eta);
            const s = -k * ps + td * (1 - ps); // dz/dy of the drop + gull law
            v = g * sqrt(1 + s * s);
        }
        sum += w * v;
    }
    return sum / (3 * N);
}

